import sys
import os
import struct
import random
import socket


def encode_qname(name):
    if name.endswith('.'):
        name = name[:-1]
    if not name:
        return b'\x00'
    labels = name.split('.')
    result = b''
    for label in labels:
        encoded = label.encode('ascii')
        result += bytes([len(encoded)]) + encoded
    result += b'\x00'
    return result


def build_query(name, qtype, qid):
    header = struct.pack('!HHHHHH', qid, 0x0100, 1, 0, 0, 0)
    qname = encode_qname(name)
    question = qname + struct.pack('!HH', qtype, 1)
    return header + question


def parse_name_at(data, offset):
    labels = []
    jumped = False
    next_offset = offset
    while True:
        length = data[offset]
        if length == 0:
            offset += 1
            if not jumped:
                next_offset = offset
            break
        if (length & 0xC0) == 0xC0:
            pointer = struct.unpack('!H', data[offset:offset + 2])[0] & 0x3FFF
            if not jumped:
                next_offset = offset + 2
            offset = pointer
            jumped = True
        else:
            labels.append(data[offset + 1:offset + 1 + length].decode('ascii'))
            offset += 1 + length
            if not jumped:
                next_offset = offset
    name = '.'.join(labels) if labels else '.'
    return name.lower(), next_offset


def format_ipv4(data):
    return '.'.join(str(b) for b in data)


def format_ipv6(data):
    groups = []
    for i in range(8):
        groups.append(struct.unpack('!H', data[i * 2:i * 2 + 2])[0])
    hex_groups = [format(g, 'x') for g in groups]

    best_start = -1
    best_len = 0
    cur_start = -1
    cur_len = 0
    for i, g in enumerate(groups):
        if g == 0:
            if cur_len == 0:
                cur_start = i
            cur_len += 1
        else:
            if cur_len >= 2 and cur_len > best_len:
                best_start = cur_start
                best_len = cur_len
            cur_len = 0
    if cur_len >= 2 and cur_len > best_len:
        best_start = cur_start
        best_len = cur_len

    if best_len >= 2:
        before = ':'.join(hex_groups[:best_start])
        after = ':'.join(hex_groups[best_start + best_len:])
        if before and after:
            return before + '::' + after
        elif before:
            return before + '::'
        elif after:
            return '::' + after
        else:
            return '::'
    else:
        return ':'.join(hex_groups)


def format_txt(rdata):
    strings = []
    offset = 0
    while offset < len(rdata):
        length = rdata[offset]
        offset += 1
        s = rdata[offset:offset + length]
        offset += length
        escaped = ''
        for byte in s:
            if byte == 0x22:
                escaped += '\\"'
            elif byte == 0x5C:
                escaped += '\\\\'
            elif 0x20 <= byte <= 0x7E:
                escaped += chr(byte)
            else:
                escaped += '\\{:03d}'.format(byte)
        strings.append('"' + escaped + '"')
    return ' '.join(strings)


def rcode_name(rcode):
    names = {0: 'NOERROR', 1: 'FORMERR', 2: 'SERVFAIL', 3: 'NXDOMAIN', 4: 'NOTIMP', 5: 'REFUSED'}
    return names.get(rcode, 'RCODE{}'.format(rcode))


def parse_response(data):
    qid, flags, qdcount, ancount, nscount, arcount = struct.unpack('!HHHHHH', data[:12])
    rcode = flags & 0x000F

    offset = 12
    for _ in range(qdcount):
        _, offset = parse_name_at(data, offset)
        offset += 4

    records = []
    for _ in range(ancount):
        owner, offset = parse_name_at(data, offset)
        rtype, rclass, ttl, rdlength = struct.unpack('!HHIH', data[offset:offset + 4])
        offset += 4
        rdata_start = offset
        rdata = data[offset:offset + rdlength]
        offset += rdlength
        records.append((owner, ttl, rtype, rdata, rdata_start, data))

    return rcode, records


def format_record(owner, ttl, rtype, rdata, rdata_start, full_data):
    type_name_map = {1: 'A', 5: 'CNAME', 15: 'MX', 16: 'TXT', 28: 'AAAA'}
    type_name = type_name_map.get(rtype, 'TYPE{}'.format(rtype))

    if rtype == 1:
        data_str = format_ipv4(rdata)
    elif rtype == 28:
        data_str = format_ipv6(rdata)
    elif rtype == 5:
        target, _ = parse_name_at(full_data, rdata_start)
        data_str = target
    elif rtype == 15:
        preference = struct.unpack('!H', rdata[:2])[0]
        exchange, _ = parse_name_at(full_data, rdata_start + 2)
        data_str = '{} {}'.format(preference, exchange)
    elif rtype == 16:
        data_str = format_txt(rdata)
    else:
        if len(rdata) == 0:
            data_str = '\\# 0'
        else:
            data_str = '\\# {} {}'.format(len(rdata), rdata.hex())

    return '  {} {} {} {}'.format(owner, ttl, type_name, data_str)


def main():
    directory = sys.argv[1]
    port = int(sys.argv[2])

    queries_file = os.path.join(directory, 'queries.txt')
    with open(queries_file, 'r') as f:
        lines = f.readlines()

    for line in lines:
        line = line.strip()
        if not line:
            continue

        parts = line.split(' ')
        name = parts[0]
        qtype_str = parts[1]

        type_map = {'A': 1, 'AAAA': 28, 'MX': 15, 'TXT': 16, 'CNAME': 5}
        qtype = type_map[qtype_str]

        qid = random.randint(0, 65535)
        query = build_query(name, qtype, qid)

        # Send via UDP
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.sendto(query, ('127.0.0.1', port))

        response = None
        while True:
            data, addr = sock.recvfrom(65535)
            if len(data) >= 2:
                resp_id = struct.unpack('!H', data[:2])[0]
                if resp_id == qid:
                    response = data
                    break
        sock.close()

        # Check TC flag
        flags = struct.unpack('!H', response[2:4])[0]
        tc = (flags >> 9) & 1

        if tc:
            # Retry over TCP
            tcp_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            tcp_sock.connect(('127.0.0.1', port))
            tcp_sock.sendall(struct.pack('!H', len(query)) + query)

            buf = b''
            while len(buf) < 2:
                chunk = tcp_sock.recv(4096)
                if not chunk:
                    break
                buf += chunk

            if len(buf) >= 2:
                resp_len = struct.unpack('!H', buf[:2])[0]
                while len(buf) < 2 + resp_len:
                    chunk = tcp_sock.recv(4096)
                    if not chunk:
                        break
                    buf += chunk
                response = buf[2:2 + resp_len]

            tcp_sock.close()

        rcode, records = parse_response(response)

        display_name = name.lower().rstrip('.')
        if not display_name:
            display_name = '.'

        print('{} {} {}'.format(display_name, qtype_str, rcode_name(rcode)))

        for owner, ttl, rtype, rdata, rdata_start, full_data in records:
            print(format_record(owner, ttl, rtype, rdata, rdata_start, full_data))


if __name__ == '__main__':
    main()

