import * as fs from 'fs';
import * as dgram from 'dgram';
import * as net from 'net';

const TYPE_MAP: Record<string, number> = { A: 1, AAAA: 28, MX: 15, TXT: 16, CNAME: 5 };
const TYPE_NAMES: Record<number, string> = { 1: 'A', 5: 'CNAME', 15: 'MX', 16: 'TXT', 28: 'AAAA' };
const RCODE_NAMES: Record<number, string> = { 0: 'NOERROR', 1: 'FORMERR', 2: 'SERVFAIL', 3: 'NXDOMAIN', 4: 'NOTIMP', 5: 'REFUSED' };

function splitName(name: string): string[] {
  if (name.endsWith('.')) name = name.slice(0, -1);
  if (name === '') return [];
  return name.split('.');
}

function encodeName(labels: string[]): Buffer {
  const parts: Buffer[] = [];
  for (const label of labels) {
    const buf = Buffer.from(label, 'ascii');
    parts.push(Buffer.from([buf.length]));
    parts.push(buf);
  }
  parts.push(Buffer.from([0]));
  return Buffer.concat(parts);
}

function buildQuery(id: number, name: string, type: number): Buffer {
  const labels = splitName(name);
  const qname = encodeName(labels);
  const header = Buffer.alloc(12);
  header.writeUInt16BE(id, 0);
  header.writeUInt16BE(0x0100, 2);
  header.writeUInt16BE(1, 4);
  header.writeUInt16BE(0, 6);
  header.writeUInt16BE(0, 8);
  header.writeUInt16BE(0, 10);
  const qtype = Buffer.alloc(4);
  qtype.writeUInt16BE(type, 0);
  qtype.writeUInt16BE(1, 2);
  return Buffer.concat([header, qname, qtype]);
}

function parseName(msg: Buffer, offset: number): [string, number] {
  const labels: string[] = [];
  let pos = offset;
  let jumped = false;
  let nextPos = offset;
  let safety = 0;

  while (safety++ < 256) {
    if (pos >= msg.length) break;
    const len = msg[pos];
    if ((len & 0xC0) === 0xC0) {
      if (!jumped) {
        nextPos = pos + 2;
        jumped = true;
      }
      pos = ((len & 0x3F) << 8) | msg[pos + 1];
    } else if (len === 0) {
      if (!jumped) nextPos = pos + 1;
      break;
    } else {
      labels.push(msg.slice(pos + 1, pos + 1 + len).toString('ascii'));
      pos += 1 + len;
    }
  }

  return [labels.join('.'), nextPos];
}

function formatIPv6(bytes: Buffer): string {
  const groups: number[] = [];
  for (let i = 0; i < 8; i++) groups.push(bytes.readUInt16BE(i * 2));

  let bestStart = -1, bestLen = 0, curStart = -1, curLen = 0;
  for (let i = 0; i < 8; i++) {
    if (groups[i] === 0) {
      if (curStart === -1) { curStart = i; curLen = 1; } else { curLen++; }
    } else {
      if (curLen > bestLen) { bestStart = curStart; bestLen = curLen; }
      curStart = -1; curLen = 0;
    }
  }
  if (curLen > bestLen) { bestStart = curStart; bestLen = curLen; }

  if (bestLen < 2) return groups.map(g => g.toString(16)).join(':');

  const before = groups.slice(0, bestStart).map(g => g.toString(16));
  const after = groups.slice(bestStart + bestLen).map(g => g.toString(16));

  if (before.length === 0 && after.length === 0) return '::';
  if (before.length === 0) return '::' + after.join(':');
  if (after.length === 0) return before.join(':') + '::';
  return before.join(':') + '::' + after.join(':');
}

function escapeTXT(data: Buffer): string {
  let pos = 0;
  const strings: string[] = [];
  while (pos < data.length) {
    const len = data[pos]; pos++;
    const strBytes = data.slice(pos, pos + len); pos += len;
    let s = '"';
    for (const b of strBytes) {
      if (b === 0x22) s += '\\"';
      else if (b === 0x5C) s += '\\\\';
      else if (b >= 0x20 && b <= 0x7E) s += String.fromCharCode(b);
      else s += '\\' + b.toString().padStart(3, '0');
    }
    s += '"';
    strings.push(s);
  }
  return strings.join(' ');
}

function fmtName(name: string): string {
  const lower = name.toLowerCase();
  return lower === '' ? '.' : lower;
}

function formatData(type: number, data: Buffer, msg: Buffer, rdataOffset: number): string {
  switch (type) {
    case 1:
      return `${data[0]}.${data[1]}.${data[2]}.${data[3]}`;
    case 28:
      return formatIPv6(data);
    case 5: {
      const [name] = parseName(msg, rdataOffset);
      return fmtName(name);
    }
    case 15: {
      const pref = data.readUInt16BE(0);
      const [exchange] = parseName(msg, rdataOffset + 2);
      return `${pref} ${fmtName(exchange)}`;
    }
    case 16:
      return escapeTXT(data);
    default: {
      if (data.length === 0) return '\\# 0';
      return `\\# ${data.length} ${data.toString('hex')}`;
    }
  }
}

interface ParsedResponse {
  rcode: number;
  answers: { owner: string; type: number; ttl: number; data: string }[];
}

function parseResponse(msg: Buffer): ParsedResponse {
  const flags = msg.readUInt16BE(2);
  const rcode = flags & 0xF;
  const qdcount = msg.readUInt16BE(4);
  const ancount = msg.readUInt16BE(6);

  let pos = 12;
  for (let i = 0; i < qdcount; i++) {
    const [, nextPos] = parseName(msg, pos);
    pos = nextPos + 4;
  }

  const answers: ParsedResponse['answers'] = [];
  for (let i = 0; i < ancount; i++) {
    const [owner, nextPos] = parseName(msg, pos);
    pos = nextPos;
    const type = msg.readUInt16BE(pos); pos += 2;
    pos += 2; // CLASS
    const ttl = msg.readUInt32BE(pos); pos += 4;
    const rdlength = msg.readUInt16BE(pos); pos += 2;
    const rdataOffset = pos;
    const rdata = msg.slice(pos, pos + rdlength);
    pos += rdlength;

    const typeName = TYPE_NAMES[type] || `TYPE${type}`;
    const dataStr = formatData(type, rdata, msg, rdataOffset);
    answers.push({ owner: fmtName(owner), type, ttl, data: dataStr });
  }

  return { rcode, answers };
}

function sendUDP(port: number, query: Buffer, id: number): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const socket = dgram.createSocket('udp4');
    socket.on('message', (msg) => {
      if (msg.length >= 12) {
        const respId = msg.readUInt16BE(0);
        const flags = msg.readUInt16BE(2);
        const qr = (flags >> 15) & 1;
        if (qr === 1 && respId === id) {
          socket.close();
          resolve(msg);
        }
      }
    });
    socket.on('error', reject);
    socket.send(query, 0, query.length, port, '127.0.0.1');
  });
}

function sendTCP(port: number, query: Buffer): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const socket = net.createConnection({ port, host: '127.0.0.1' });
    let chunks: Buffer[] = [];
    let totalLen = 0;
    let msgLen = -1;

    socket.on('connect', () => {
      const prefix = Buffer.alloc(2);
      prefix.writeUInt16BE(query.length, 0);
      socket.write(Buffer.concat([prefix, query]));
    });

    socket.on('data', (chunk) => {
      chunks.push(chunk);
      totalLen += chunk.length;
      if (msgLen === -1 && totalLen >= 2) {
        const combined = Buffer.concat(chunks);
        msgLen = combined.readUInt16BE(0);
      }
      if (msgLen !== -1 && totalLen >= msgLen + 2) {
        const combined = Buffer.concat(chunks);
        socket.destroy();
        resolve(combined.slice(2, 2 + msgLen));
      }
    });

    socket.on('error', reject);
  });
}

async function main() {
  const args = process.argv.slice(2);
  const dir = args[0];
  const port = parseInt(args[1], 10);

  const content = fs.readFileSync(`${dir}/queries.txt`, 'utf-8');
  const lines = content.split('\n');

  const output: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed === '') continue;

    const parts = trimmed.split(' ');
    if (parts.length < 2) continue;
    const name = parts[0];
    const typeName = parts[1];
    const qtype = TYPE_MAP[typeName] || 0;

    const id = Math.floor(Math.random() * 65536);
    const query = buildQuery(id, name, qtype);

    let udpResp = await sendUDP(port, query, id);
    const udpFlags = udpResp.readUInt16BE(2);
    const tc = (udpFlags >> 9) & 1;

    let finalResp: Buffer;
    if (tc === 1) {
      finalResp = await sendTCP(port, query);
    } else {
      finalResp = udpResp;
    }

    const parsed = parseResponse(finalResp);
    const rcodeName = RCODE_NAMES[parsed.rcode] || `RCODE${parsed.rcode}`;

    const queryName = fmtName(name);
    output.push(`${queryName} ${typeName} ${rcodeName}`);

    for (const ans of parsed.answers) {
      const typeNameOut = TYPE_NAMES[ans.type] || `TYPE${ans.type}`;
      output.push(`  ${ans.owner} ${ans.ttl} ${typeNameOut} ${ans.data}`);
    }
  }

  process.stdout.write(output.join('\n') + '\n');
  process.exit(0);
}

main().catch((e) => { console.error(e); process.exit(1); });

