import Foundation

// MARK: - JSON Value

enum JSONValue {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([(String, JSONValue)])
}

// MARK: - JSON Parser

struct JSONParser {
    let chars: [Character]
    var pos: Int

    init(_ input: String) {
        chars = Array(input)
        pos = 0
    }

    mutating func parse() -> JSONValue {
        skipWS()
        let v = parseValue()
        return v
    }

    mutating func skipWS() {
        while pos < chars.count {
            let c = chars[pos]
            if c == " " || c == "\t" || c == "\n" || c == "\r" { pos += 1 }
            else { break }
        }
    }

    mutating func parseValue() -> JSONValue {
        skipWS()
        guard pos < chars.count else { return .null }
        let c = chars[pos]
        switch c {
        case "{": return parseObject()
        case "[": return parseArray()
        case "\"": return .string(parseString())
        case "t": pos += 4; return .bool(true)
        case "f": pos += 5; return .bool(false)
        case "n": pos += 4; return .null
        default: return parseNumber()
        }
    }

    mutating func parseObject() -> JSONValue {
        pos += 1
        skipWS()
        var members: [(String, JSONValue)] = []
        if pos < chars.count && chars[pos] != "}" {
            while true {
                skipWS()
                let key = parseString()
                skipWS()
                pos += 1 // colon
                let val = parseValue()
                members.append((key, val))
                skipWS()
                if pos < chars.count && chars[pos] == "," {
                    pos += 1
                } else {
                    break
                }
            }
        }
        if pos < chars.count && chars[pos] == "}" { pos += 1 }
        return .object(members)
    }

    mutating func parseArray() -> JSONValue {
        pos += 1
        skipWS()
        var elements: [JSONValue] = []
        if pos < chars.count && chars[pos] != "]" {
            while true {
                let val = parseValue()
                elements.append(val)
                skipWS()
                if pos < chars.count && chars[pos] == "," {
                    pos += 1
                } else {
                    break
                }
            }
        }
        if pos < chars.count && chars[pos] == "]" { pos += 1 }
        return .array(elements)
    }

    mutating func parseString() -> String {
        pos += 1 // opening quote
        var result = ""
        while pos < chars.count && chars[pos] != "\"" {
            if chars[pos] == "\\" {
                pos += 1
                guard pos < chars.count else { break }
                let c = chars[pos]
                switch c {
                case "\"": result.append("\"")
                case "\\": result.append("\\")
                case "/": result.append("/")
                case "b": result.append("\u{08}")
                case "f": result.append("\u{0C}")
                case "n": result.append("\n")
                case "r": result.append("\r")
                case "t": result.append("\t")
                case "u":
                    pos += 1
                    let cp = parseHex4()
                    if cp >= 0xD800 && cp <= 0xDBFF && pos + 1 < chars.count && chars[pos] == "\\" && chars[pos+1] == "u" {
                        pos += 2
                        let low = parseHex4()
                        let full = 0x10000 + (cp - 0xD800) * 0x400 + (low - 0xDC00)
                        if let scalar = UnicodeScalar(full) {
                            result.append(Character(scalar))
                        }
                    } else {
                        if let scalar = UnicodeScalar(cp) {
                            result.append(Character(scalar))
                        }
                    }
                default:
                    result.append(c)
                }
            } else {
                result.append(chars[pos])
            }
            pos += 1
        }
        if pos < chars.count && chars[pos] == "\"" { pos += 1 }
        return result
    }

    mutating func parseHex4() -> Int {
        var value = 0
        for _ in 0..<4 {
            guard pos < chars.count else { break }
            value *= 16
            let c = chars[pos]
            if c >= "0" && c <= "9" { value += Int(c.asciiValue! - 48) }
            else if c >= "a" && c <= "f" { value += Int(c.asciiValue! - 97 + 10) }
            else if c >= "A" && c <= "F" { value += Int(c.asciiValue! - 65 + 10) }
            pos += 1
        }
        return value
    }

    mutating func parseNumber() -> JSONValue {
        let start = pos
        if pos < chars.count && chars[pos] == "-" { pos += 1 }
        while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 }
        if pos < chars.count && chars[pos] == "." {
            pos += 1
            while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 }
        }
        if pos < chars.count && (chars[pos] == "e" || chars[pos] == "E") {
            pos += 1
            if pos < chars.count && (chars[pos] == "+" || chars[pos] == "-") { pos += 1 }
            while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 }
        }
        let str = String(chars[start..<pos])
        return .number(Double(str) ?? 0)
    }
}

// MARK: - JSON Pointer

func escapeToken(_ token: String) -> String {
    var result = ""
    for c in token {
        if c == "~" { result += "~0" }
        else if c == "/" { result += "~1" }
        else { result.append(c) }
    }
    return result
}

func unescapeToken(_ token: String) -> String {
    var result = ""
    var i = token.startIndex
    while i < token.endIndex {
        if token[i] == "~" {
            let next = token.index(after: i)
            if next < token.endIndex {
                if token[next] == "0" {
                    result.append("~")
                    i = token.index(after: next)
                    continue
                } else if token[next] == "1" {
                    result.append("/")
                    i = token.index(after: next)
                    continue
                }
            }
        }
        result.append(token[i])
        i = token.index(after: i)
    }
    return result
}

func pointerStr(_ tokens: [String]) -> String {
    if tokens.isEmpty { return "#" }
    var s = "#"
    for t in tokens {
        s += "/" + escapeToken(t)
    }
    return s
}

// MARK: - Deep Equality

func deepEqual(_ a: JSONValue, _ b: JSONValue) -> Bool {
    switch (a, b) {
    case (.null, .null): return true
    case (.bool(let x), .bool(let y)): return x == y
    case (.number(let x), .number(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.array(let x), .array(let y)):
        if x.count != y.count { return false }
        for i in 0..<x.count {
            if !deepEqual(x[i], y[i]) { return false }
        }
        return true
    case (.object(let x), .object(let y)):
        if x.count != y.count { return false }
        for (kx, vx) in x {
            var found = false
            for (ky, vy) in y {
                if kx == ky {
                    if !deepEqual(vx, vy) { return false }
                    found = true
                    break
                }
            }
            if !found { return false }
        }
        return true
    default: return false
    }
}

// MARK: - Helpers

func getMember(_ obj: [(String, JSONValue)], _ key: String) -> JSONValue? {
    for (k, v) in obj {
        if k == key { return v }
    }
    return nil
}

func isInteger(_ n: Double) -> Bool {
    return n == n.rounded()
}

// MARK: - Type Check

func checkType(instance: JSONValue, typeVal: JSONValue) -> Bool {
    var typeNames: [String] = []
    if case .string(let t) = typeVal {
        typeNames = [t]
    } else if case .array(let arr) = typeVal {
        for item in arr {
            if case .string(let t) = item { typeNames.append(t) }
        }
    } else {
        return true
    }
    for name in typeNames {
        switch name {
        case "null": if case .null = instance { return true }
        case "boolean": if case .bool = instance { return true }
        case "number": if case .number = instance { return true }
        case "integer": if case .number(let n) = instance { if isInteger(n) { return true } }
        case "string": if case .string = instance { return true }
        case "array": if case .array = instance { return true }
        case "object": if case .object = instance { return true }
        default: break
        }
    }
    return false
}

// MARK: - Ref Resolution

func resolveRef(ref: String, rootSchema: JSONValue) -> JSONValue? {
    if ref == "#" { return rootSchema }
    guard ref.hasPrefix("#/$defs/") else { return nil }
    let remaining = String(ref.dropFirst("#/$defs/".count))
    let token = unescapeToken(remaining)
    guard case .object(let rootMembers) = rootSchema else { return nil }
    guard let defs = getMember(rootMembers, "$defs") else { return nil }
    guard case .object(let defsMembers) = defs else { return nil }
    return getMember(defsMembers, token)
}

func refSchemaLoc(ref: String) -> [String] {
    if ref == "#" { return [] }
    guard ref.hasPrefix("#/$defs/") else { return [] }
    let remaining = String(ref.dropFirst("#/$defs/".count))
    let token = unescapeToken(remaining)
    return ["$defs", token]
}

// MARK: - Error Pair

struct ErrorPair: Hashable {
    let instLoc: String
    let schemaLoc: String
}

// MARK: - Validation

func validate(instance: JSONValue, schema: JSONValue, instanceLoc: [String], schemaLoc: [String], rootSchema: JSONValue) -> Set<ErrorPair> {
    var errors = Set<ErrorPair>()

    // Boolean schema
    if case .bool(let b) = schema {
        if !b {
            errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc)))
        }
        return errors
    }

    guard case .object(let members) = schema else { return errors }

    func kw(_ name: String) -> JSONValue? {
        return getMember(members, name)
    }

    // --- Any type keywords ---

    // type
    if let typeVal = kw("type") {
        if !checkType(instance: instance, typeVal: typeVal) {
            errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["type"])))
        }
    }

    // enum
    if let enumVal = kw("enum"), case .array(let items) = enumVal {
        var found = false
        for item in items {
            if deepEqual(instance, item) { found = true; break }
        }
        if !found {
            errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["enum"])))
        }
    }

    // const
    if let constVal = kw("const") {
        if !deepEqual(instance, constVal) {
            errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["const"])))
        }
    }

    // --- Number keywords ---
    if case .number(let num) = instance {
        if let v = kw("minimum"), case .number(let val) = v {
            if num < val {
                errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["minimum"])))
            }
        }
        if let v = kw("maximum"), case .number(let val) = v {
            if num > val {
                errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["maximum"])))
            }
        }
        if let v = kw("exclusiveMinimum"), case .number(let val) = v {
            if num <= val {
                errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["exclusiveMinimum"])))
            }
        }
        if let v = kw("exclusiveMaximum"), case .number(let val) = v {
            if num >= val {
                errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["exclusiveMaximum"])))
            }
        }
    }

    // --- String keywords ---
    if case .string(let str) = instance {
        let len = str.unicodeScalars.count
        if let v = kw("minLength"), case .number(let val) = v {
            if Double(len) < val {
                errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["minLength"])))
            }
        }
        if let v = kw("maxLength"), case .number(let val) = v {
            if Double(len) > val {
                errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["maxLength"])))
            }
        }
    }

    // --- Array keywords ---
    if case .array(let arr) = instance {
        if let v = kw("minItems"), case .number(let val) = v {
            if Double(arr.count) < val {
                errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["minItems"])))
            }
        }
        if let v = kw("maxItems"), case .number(let val) = v {
            if Double(arr.count) > val {
                errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["maxItems"])))
            }
        }
        if let v = kw("uniqueItems"), case .bool(let u) = v, u {
            var hasDup = false
            outer: for i in 0..<arr.count {
                for j in (i+1)..<arr.count {
                    if deepEqual(arr[i], arr[j]) { hasDup = true; break outer }
                }
            }
            if hasDup {
                errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["uniqueItems"])))
            }
        }

        // prefixItems
        var prefixLen = 0
        if let pv = kw("prefixItems"), case .array(let schemas) = pv {
            prefixLen = schemas.count
            for i in 0..<min(arr.count, schemas.count) {
                let sub = validate(instance: arr[i], schema: schemas[i],
                    instanceLoc: instanceLoc + [String(i)],
                    schemaLoc: schemaLoc + ["prefixItems", String(i)],
                    rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }

        // items
        if let itemsSchema = kw("items") {
            let startIdx = prefixLen
            for i in startIdx..<arr.count {
                let sub = validate(instance: arr[i], schema: itemsSchema,
                    instanceLoc: instanceLoc + [String(i)],
                    schemaLoc: schemaLoc + ["items"],
                    rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }
    }

    // --- Object keywords ---
    if case .object(let objMembers) = instance {
        if let v = kw("minProperties"), case .number(let val) = v {
            if Double(objMembers.count) < val {
                errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["minProperties"])))
            }
        }
        if let v = kw("maxProperties"), case .number(let val) = v {
            if Double(objMembers.count) > val {
                errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["maxProperties"])))
            }
        }

        // required
        if let rv = kw("required"), case .array(let reqItems) = rv {
            for (j, reqItem) in reqItems.enumerated() {
                if case .string(let name) = reqItem {
                    if getMember(objMembers, name) == nil {
                        errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["required", String(j)])))
                    }
                }
            }
        }

        // properties
        var propKeys = Set<String>()
        if let pv = kw("properties"), case .object(let props) = pv {
            for (k, v) in props {
                propKeys.insert(k)
                if let instVal = getMember(objMembers, k) {
                    let sub = validate(instance: instVal, schema: v,
                        instanceLoc: instanceLoc + [k],
                        schemaLoc: schemaLoc + ["properties", k],
                        rootSchema: rootSchema)
                    errors.formUnion(sub)
                }
            }
        }

        // additionalProperties
        if let addProps = kw("additionalProperties") {
            for (k, v) in objMembers {
                if !propKeys.contains(k) {
                    let sub = validate(instance: v, schema: addProps,
                        instanceLoc: instanceLoc + [k],
                        schemaLoc: schemaLoc + ["additionalProperties"],
                        rootSchema: rootSchema)
                    errors.formUnion(sub)
                }
            }
        }
    }

    // --- Applicators ---

    // $ref
    if let rv = kw("$ref"), case .string(let ref) = rv {
        if let resolved = resolveRef(ref: ref, rootSchema: rootSchema) {
            let sub = validate(instance: instance, schema: resolved,
                instanceLoc: instanceLoc,
                schemaLoc: refSchemaLoc(ref: ref),
                rootSchema: rootSchema)
            errors.formUnion(sub)
        }
    }

    // allOf
    if let av = kw("allOf"), case .array(let schemas) = av {
        for (i, subSchema) in schemas.enumerated() {
            let sub = validate(instance: instance, schema: subSchema,
                instanceLoc: instanceLoc,
                schemaLoc: schemaLoc + ["allOf", String(i)],
                rootSchema: rootSchema)
            errors.formUnion(sub)
        }
    }

    // anyOf
    if let av = kw("anyOf"), case .array(let schemas) = av {
        var anyValid = false
        for (i, subSchema) in schemas.enumerated() {
            let sub = validate(instance: instance, schema: subSchema,
                instanceLoc: instanceLoc,
                schemaLoc: schemaLoc + ["anyOf", String(i)],
                rootSchema: rootSchema)
            if sub.isEmpty { anyValid = true; break }
        }
        if !anyValid {
            errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["anyOf"])))
        }
    }

    // oneOf
    if let ov = kw("oneOf"), case .array(let schemas) = ov {
        var validCount = 0
        for (i, subSchema) in schemas.enumerated() {
            let sub = validate(instance: instance, schema: subSchema,
                instanceLoc: instanceLoc,
                schemaLoc: schemaLoc + ["oneOf", String(i)],
                rootSchema: rootSchema)
            if sub.isEmpty { validCount += 1 }
        }
        if validCount != 1 {
            errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["oneOf"])))
        }
    }

    // not
    if let nv = kw("not") {
        let sub = validate(instance: instance, schema: nv,
            instanceLoc: instanceLoc,
            schemaLoc: schemaLoc + ["not"],
            rootSchema: rootSchema)
        if sub.isEmpty {
            errors.insert(ErrorPair(instLoc: pointerStr(instanceLoc), schemaLoc: pointerStr(schemaLoc + ["not"])))
        }
    }

    // if/then/else
    if let ifVal = kw("if") {
        let ifErrs = validate(instance: instance, schema: ifVal,
            instanceLoc: instanceLoc,
            schemaLoc: schemaLoc + ["if"],
            rootSchema: rootSchema)
        if ifErrs.isEmpty {
            if let thenVal = kw("then") {
                let sub = validate(instance: instance, schema: thenVal,
                    instanceLoc: instanceLoc,
                    schemaLoc: schemaLoc + ["then"],
                    rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        } else {
            if let elseVal = kw("else") {
                let sub = validate(instance: instance, schema: elseVal,
                    instanceLoc: instanceLoc,
                    schemaLoc: schemaLoc + ["else"],
                    rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }
    }

    return errors
}

