            let i2 = Array(e2.instLoc.utf8)
            if i1 != i2 { return i1.lexicographicallyPrecedes(i2) }
            let s1 = Array(e1.schemaLoc.utf8)
            let s2 = Array(e2.schemaLoc.utf8)
            return s1.lexicographicallyPrecedes(s2)
