import * as fs from 'fs';
import * as path from 'path';

function encodeToken(token: string): string {
    return token.replace(/~/g, '~0').replace(/\//g, '~1');
}

function makePointer(tokens: string[]): string {
    return '#' + tokens.map(t => '/' + encodeToken(t)).join('');
}

function decodePointerToken(token: string): string {
    let result = '';
    for (let i = 0; i < token.length; i++) {
        if (token[i] === '~' && i + 1 < token.length) {
            if (token[i + 1] === '0') { result += '~'; i++; }
            else if (token[i + 1] === '1') { result += '/'; i++; }
            else { result += '~'; }
        } else {
            result += token[i];
        }
    }
    return result;
}

function strLen(s: string): number {
    let count = 0;
    for (const _ of s) count++;
    return count;
}

function deepEqual(a: any, b: any): boolean {
    if (a === null && b === null) return true;
    if (a === null || b === null) return false;
    if (typeof a === 'boolean' && typeof b === 'boolean') return a === b;
    if (typeof a === 'number' && typeof b === 'number') return a === b;
    if (typeof a === 'string' && typeof b === 'string') return a === b;
    if (Array.isArray(a) && Array.isArray(b)) {
        if (a.length !== b.length) return false;
        return a.every((v, i) => deepEqual(v, b[i]));
    }
    if (typeof a === 'object' && typeof b === 'object' && !Array.isArray(a) && !Array.isArray(b)) {
        const keysA = Object.keys(a);
        const keysB = Object.keys(b);
        if (keysA.length !== keysB.length) return false;
        const setB = new Set(keysB);
        if (keysA.some(k => !setB.has(k))) return false;
        return keysA.every(k => deepEqual(a[k], b[k]));
    }
    return false;
}

function matchesType(instance: any, typeName: string): boolean {
    switch (typeName) {
        case 'null': return instance === null;
        case 'boolean': return typeof instance === 'boolean';
        case 'number': return typeof instance === 'number';
        case 'integer': return typeof instance === 'number' && Number.isInteger(instance);
        case 'string': return typeof instance === 'string';
        case 'array': return Array.isArray(instance);
        case 'object': return instance !== null && typeof instance === 'object' && !Array.isArray(instance);
        default: return false;
    }
}

function resolveRef(ref: string, rootSchema: any): any {
    if (ref === '#') return rootSchema;
    if (ref.startsWith('#/$defs/')) {
        const encodedName = ref.slice('#/$defs/'.length);
        const name = decodePointerToken(encodedName);
        if (rootSchema && typeof rootSchema === 'object' && '$defs' in rootSchema) {
            return rootSchema['$defs'][name];
        }
    }
    return true;
}

function getRefSchemaTokens(ref: string): string[] {
    if (ref === '#') return [];
    const encodedName = ref.slice('#/$defs/'.length);
    const name = decodePointerToken(encodedName);
    return ['$defs', name];
}

function validate(
    instance: any,
    schema: any,
    instanceTokens: string[],
    schemaTokens: string[],
    rootSchema: any
): Set<string> {
    const errors = new Set<string>();

    if (schema === true) return errors;
    if (schema === false) {
        errors.add(`${makePointer(instanceTokens)}\u0000${makePointer(schemaTokens)}`);
        return errors;
    }

    if (typeof schema !== 'object' || schema === null) return errors;

    // $ref
    if ('$ref' in schema) {
        const refStr = schema['$ref'];
        const refSchema = resolveRef(refStr, rootSchema);
        const refTokens = getRefSchemaTokens(refStr);
        const subErrors = validate(instance, refSchema, instanceTokens, refTokens, rootSchema);
        for (const e of subErrors) errors.add(e);
    }

    // type
    if ('type' in schema) {
        const typeVal = schema['type'];
        const typeNames: string[] = Array.isArray(typeVal) ? typeVal : [typeVal];
        if (!typeNames.some(t => matchesType(instance, t))) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'type'])}`);
        }
    }

    // enum
    if ('enum' in schema) {
        if (!schema['enum'].some((e: any) => deepEqual(instance, e))) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'enum'])}`);
        }
    }

    // const
    if ('const' in schema) {
        if (!deepEqual(instance, schema['const'])) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'const'])}`);
        }
    }

    // Number keywords
    if (typeof instance === 'number') {
        if ('minimum' in schema && instance < schema['minimum']) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'minimum'])}`);
        }
        if ('maximum' in schema && instance > schema['maximum']) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'maximum'])}`);
        }
        if ('exclusiveMinimum' in schema && instance <= schema['exclusiveMinimum']) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'exclusiveMinimum'])}`);
        }
        if ('exclusiveMaximum' in schema && instance >= schema['exclusiveMaximum']) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'exclusiveMaximum'])}`);
        }
    }

    // String keywords
    if (typeof instance === 'string') {
        if ('minLength' in schema && strLen(instance) < schema['minLength']) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'minLength'])}`);
        }
        if ('maxLength' in schema && strLen(instance) > schema['maxLength']) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'maxLength'])}`);
        }
    }

    // Array keywords
    if (Array.isArray(instance)) {
        if ('minItems' in schema && instance.length < schema['minItems']) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'minItems'])}`);
        }
        if ('maxItems' in schema && instance.length > schema['maxItems']) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'maxItems'])}`);
        }
        if (schema['uniqueItems'] === true) {
            let hasDup = false;
            outer: for (let i = 0; i < instance.length; i++) {
                for (let j = i + 1; j < instance.length; j++) {
                    if (deepEqual(instance[i], instance[j])) {
                        hasDup = true;
                        break outer;
                    }
                }
            }
            if (hasDup) {
                errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'uniqueItems'])}`);
            }
        }
        // prefixItems
        if ('prefixItems' in schema) {
            const pi = schema['prefixItems'];
            for (let i = 0; i < Math.min(instance.length, pi.length); i++) {
                const subErrors = validate(
                    instance[i], pi[i],
                    [...instanceTokens, String(i)],
                    [...schemaTokens, 'prefixItems', String(i)],
                    rootSchema
                );
                for (const e of subErrors) errors.add(e);
            }
        }
        // items
        if ('items' in schema) {
            const startIdx = 'prefixItems' in schema ? schema['prefixItems'].length : 0;
            for (let i = startIdx; i < instance.length; i++) {
                const subErrors = validate(
                    instance[i], schema['items'],
                    [...instanceTokens, String(i)],
                    [...schemaTokens, 'items'],
                    rootSchema
                );
                for (const e of subErrors) errors.add(e);
            }
        }
    }

    // Object keywords
    if (instance !== null && typeof instance === 'object' && !Array.isArray(instance)) {
        const instanceKeys = Object.keys(instance);

        // properties
        if ('properties' in schema) {
            const props = schema['properties'];
            for (const key of instanceKeys) {
                if (key in props) {
                    const subErrors = validate(
                        instance[key], props[key],
                        [...instanceTokens, key],
                        [...schemaTokens, 'properties', key],
                        rootSchema
                    );
                    for (const e of subErrors) errors.add(e);
                }
            }
        }

        // required
        if ('required' in schema) {
            const req = schema['required'];
            for (let j = 0; j < req.length; j++) {
                if (!(req[j] in instance)) {
                    errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'required', String(j)])}`);
                }
            }
        }

        // additionalProperties
        if ('additionalProperties' in schema) {
            const propKeys = 'properties' in schema
                ? new Set(Object.keys(schema['properties']))
                : new Set<string>();
            for (const key of instanceKeys) {
                if (!propKeys.has(key)) {
                    const subErrors = validate(
                        instance[key], schema['additionalProperties'],
                        [...instanceTokens, key],
                        [...schemaTokens, 'additionalProperties'],
                        rootSchema
                    );
                    for (const e of subErrors) errors.add(e);
                }
            }
        }

        // minProperties / maxProperties
        if ('minProperties' in schema && instanceKeys.length < schema['minProperties']) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'minProperties'])}`);
        }
        if ('maxProperties' in schema && instanceKeys.length > schema['maxProperties']) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'maxProperties'])}`);
        }
    }

    // allOf
    if ('allOf' in schema) {
        const arr = schema['allOf'];
        for (let i = 0; i < arr.length; i++) {
            const subErrors = validate(
                instance, arr[i],
                instanceTokens,
                [...schemaTokens, 'allOf', String(i)],
                rootSchema
            );
            for (const e of subErrors) errors.add(e);
        }
    }

    // anyOf
    if ('anyOf' in schema) {
        const arr = schema['anyOf'];
        let anyPass = false;
        for (let i = 0; i < arr.length; i++) {
            const subErrors = validate(
                instance, arr[i],
                instanceTokens,
                [...schemaTokens, 'anyOf', String(i)],
                rootSchema
            );
            if (subErrors.size === 0) { anyPass = true; break; }
        }
        if (!anyPass) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'anyOf'])}`);
        }
    }

    // oneOf
    if ('oneOf' in schema) {
        const arr = schema['oneOf'];
        let passCount = 0;
        for (let i = 0; i < arr.length; i++) {
            const subErrors = validate(
                instance, arr[i],
                instanceTokens,
                [...schemaTokens, 'oneOf', String(i)],
                rootSchema
            );
            if (subErrors.size === 0) passCount++;
            if (passCount > 1) break;
        }
        if (passCount !== 1) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'oneOf'])}`);
        }
    }

    // not
    if ('not' in schema) {
        const subErrors = validate(
            instance, schema['not'],
            instanceTokens,
            [...schemaTokens, 'not'],
            rootSchema
        );
        if (subErrors.size === 0) {
            errors.add(`${makePointer(instanceTokens)}\u0000${makePointer([...schemaTokens, 'not'])}`);
        }
    }

    // if / then / else
    if ('if' in schema) {
        const ifErrors = validate(
            instance, schema['if'],
            instanceTokens,
            [...schemaTokens, 'if'],
            rootSchema
        );
        if (ifErrors.size === 0) {
            if ('then' in schema) {
                const subErrors = validate(
                    instance, schema['then'],
                    instanceTokens,
                    [...schemaTokens, 'then'],
                    rootSchema
                );
                for (const e of subErrors) errors.add(e);
            }
        } else {
            if ('else' in schema) {
                const subErrors = validate(
                    instance, schema['else'],
                    instanceTokens,
                    [...schemaTokens, 'else'],
                    rootSchema
                );
                for (const e of subErrors) errors.add(e);
            }
        }
    }

    return errors;
}

function compareCodePoints(a: string, b: string): number {
    let i = 0, j = 0;
    while (i < a.length && j < b.length) {
        const cpA = a.codePointAt(i)!;
        const cpB = b.codePointAt(j)!;
        if (cpA !== cpB) return cpA - cpB;
        i += cpA > 0xFFFF ? 2 : 1;
        j += cpB > 0xFFFF ? 2 : 1;
    }
    if (i < a.length) return 1;
    if (j < b.length) return -1;
    return 0;
}

// Main
const dir = process.argv[2];
const schemaRaw = fs.readFileSync(path.join(dir, 'schema.json'), 'utf-8');
const instancesRaw = fs.readFileSync(path.join(dir, 'instances.json'), 'utf-8');

const rootSchema = JSON.parse(schemaRaw);
const instances = JSON.parse(instancesRaw);

let validCount = 0;
let invalidCount = 0;

for (let n = 0; n < instances.length; n++) {
    const errorSet = validate(instances[n], rootSchema, [], [], rootSchema);

    if (errorSet.size === 0) {
        console.log(`${n}: valid`);
        validCount++;
    } else {
        console.log(`${n}: invalid (${errorSet.size})`);
        const errorList: [string, string][] = [];
        for (const e of errorSet) {
            const sep = e.indexOf('\u0000');
            errorList.push([e.slice(0, sep), e.slice(sep + 1)]);
        }
        errorList.sort((a, b) => {
            const cmp = compareCodePoints(a[0], b[0]);
            if (cmp !== 0) return cmp;
            return compareCodePoints(a[1], b[1]);
        });
        for (const [instLoc, schemaLoc] of errorList) {
            console.log(`  ${instLoc} ${schemaLoc}`);
        }
        invalidCount++;
    }
}

console.log(`valid=${validCount} invalid=${invalidCount}`);

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
#include <CommonCrypto/CommonHMAC.h>
#include <CommonCrypto/CommonDigest.h>

/* ─── JSON ─── */
typedef enum { JSON_NULL, JSON_BOOL, JSON_NUM, JSON_STR, JSON_ARR, JSON_OBJ } JsonType;

typedef struct JsonVal {
    JsonType type;
    union {
        int b;
        double num;
        char *str;
        struct { struct JsonVal **items; int count; } arr;
        struct { char **keys; struct JsonVal **vals; int count; } obj;
    };
} JsonVal;

typedef struct { const char *src; int pos, len; } JP;

static void skip_ws(JP *p) {
    while (p->pos < p->len) {
        char c = p->src[p->pos];
        if (c==' '||c=='\t'||c=='\n'||c=='\r') p->pos++; else break;
    }
}

static char *json_parse_str(JP *p) {
    if (p->pos >= p->len || p->src[p->pos] != '"') return NULL;
    p->pos++;
    int cap = 128, len = 0;
    char *buf = malloc(cap);
    while (p->pos < p->len && p->src[p->pos] != '"') {
        if (len + 4 >= cap) { cap *= 2; buf = realloc(buf, cap); }
        if (p->src[p->pos] == '\\') {
            p->pos++;
            if (p->pos >= p->len) break;
            char c = p->src[p->pos];
            switch (c) {
                case '"': buf[len++]='"'; break;
                case '\\': buf[len++]='\\'; break;
                case '/': buf[len++]='/'; break;
                case 'b': buf[len++]='\b'; break;
                case 'f': buf[len++]='\f'; break;
                case 'n': buf[len++]='\n'; break;
                case 'r': buf[len++]='\r'; break;
                case 't': buf[len++]='\t'; break;
                case 'u': {
                    p->pos++;
                    unsigned int cp = 0;
                    for (int i=0;i<4&&p->pos<p->len;i++){
                        char h=p->src[p->pos]; cp<<=4;
                        if(h>='0'&&h<='9')cp|=h-'0';
                        else if(h>='a'&&h<='f')cp|=h-'a'+10;
                        else if(h>='A'&&h<='F')cp|=h-'A'+10;
                        p->pos++;
                    }
                    if(cp>=0xD800&&cp<=0xDBFF&&p->pos+5<p->len&&p->src[p->pos]=='\\'&&p->src[p->pos+1]=='u'){
                        p->pos+=2;
                        unsigned int lo=0;
                        for(int i=0;i<4&&p->pos<p->len;i++){
                            char h=p->src[p->pos];lo<<=4;
                            if(h>='0'&&h<='9')lo|=h-'0';
                            else if(h>='a'&&h<='f')lo|=h-'a'+10;
                            else if(h>='A'&&h<='F')lo|=h-'A'+10;
                            p->pos++;
                        }
                        if(lo>=0xDC00&&lo<=0xDFFF) cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    }
                    if(cp<0x80){buf[len++]=(char)cp;}
                    else if(cp<0x800){buf[len++]=0xC0|(cp>>6);buf[len++]=0x80|(cp&0x3F);}
                    else if(cp<0x10000){buf[len++]=0xE0|(cp>>12);buf[len++]=0x80|((cp>>6)&0x3F);buf[len++]=0x80|(cp&0x3F);}
                    else{buf[len++]=0xF0|(cp>>18);buf[len++]=0x80|((cp>>12)&0x3F);buf[len++]=0x80|((cp>>6)&0x3F);buf[len++]=0x80|(cp&0x3F);}
                    continue;
                }
                default: buf[len++]=c; break;
            }
            p->pos++;
        } else {
            buf[len++]=p->src[p->pos++];
        }
    }
    if(p->pos<p->len&&p->src[p->pos]=='"') p->pos++;
    buf[len]='\0';
    return buf;
}

static int match_lit(JP *p, const char *lit) {
    int n = strlen(lit);
    if (p->pos + n > p->len) return 0;
    if (memcmp(p->src + p->pos, lit, n) != 0) return 0;
    p->pos += n;
    return 1;
}

static JsonVal *parse_val(JP *p) {
    skip_ws(p);
    if (p->pos >= p->len) return NULL;
    char c = p->src[p->pos];
    JsonVal *v = calloc(1, sizeof(JsonVal));
    if (c=='"') {
        v->type=JSON_STR;
        v->str=json_parse_str(p);
        if(!v->str){free(v);return NULL;}
    } else if (c=='{') {
        v->type=JSON_OBJ; p->pos++;
        skip_ws(p);
        int cap=8;
        v->obj.keys=malloc(cap*sizeof(char*));
        v->obj.vals=malloc(cap*sizeof(JsonVal*));
        v->obj.count=0;
        if(p->pos<p->len&&p->src[p->pos]=='}'){p->pos++;return v;}
        for(;;){
            skip_ws(p);
            if(p->pos>=p->len||p->src[p->pos]!='"'){free(v);return NULL;}
            char *k=json_parse_str(p);
            skip_ws(p);
            if(p->pos>=p->len||p->src[p->pos]!=':'){free(v);return NULL;}
            p->pos++;
            JsonVal *val=parse_val(p);
            if(!val){free(v);return NULL;}
            if(v->obj.count>=cap){cap*=2;v->obj.keys=realloc(v->obj.keys,cap*sizeof(char*));v->obj.vals=realloc(v->obj.vals,cap*sizeof(JsonVal*));}
            v->obj.keys[v->obj.count]=k;
            v->obj.vals[v->obj.count]=val;
            v->obj.count++;
            skip_ws(p);
            if(p->pos<p->len&&p->src[p->pos]==','){p->pos++;continue;}
            if(p->pos<p->len&&p->src[p->pos]=='}'){p->pos++;break;}
            free(v);return NULL;
        }
    } else if (c=='[') {
        v->type=JSON_ARR; p->pos++;
        skip_ws(p);
        int cap=8;
        v->arr.items=malloc(cap*sizeof(JsonVal*));
        v->arr.count=0;
        if(p->pos<p->len&&p->src[p->pos]==']'){p->pos++;return v;}
        for(;;){
            JsonVal *item=parse_val(p);
            if(!item){free(v);return NULL;}
            if(v->arr.count>=cap){cap*=2;v->arr.items=realloc(v->arr.items,cap*sizeof(JsonVal*));}
            v->arr.items[v->arr.count++]=item;
            skip_ws(p);
            if(p->pos<p->len&&p->src[p->pos]==','){p->pos++;continue;}
            if(p->pos<p->len&&p->src[p->pos]==']'){p->pos++;break;}
            free(v);return NULL;
        }
    } else if (match_lit(p,"true")) {
        v->type=JSON_BOOL; v->b=1;
    } else if (match_lit(p,"false")) {
        v->type=JSON_BOOL; v->b=0;
    } else if (match_lit(p,"null")) {
        v->type=JSON_NULL;
    } else if (c=='-'||(c>='0'&&c<='9')) {
        v->type=JSON_NUM;
        int start=p->pos;
        if(c=='-')p->pos++;
        while(p->pos<p->len&&isdigit(p->src[p->pos]))p->pos++;
        if(p->pos<p->len&&p->src[p->pos]=='.'){p->pos++;while(p->pos<p->len&&isdigit(p->src[p->pos]))p->pos++;}
        if(p->pos<p->len&&(p->src[p->pos]=='e'||p->src[p->pos]=='E')){
            p->pos++;
            if(p->pos<p->len&&(p->src[p->pos]=='+'||p->src[p->pos]=='-'))p->pos++;
            while(p->pos<p->len&&isdigit(p->src[p->pos]))p->pos++;
        }
        char tmp[64]; int n=p->pos-start;
        if(n>=64)n=63;
        memcpy(tmp,p->src+start,n); tmp[n]='\0';
        v->num=strtod(tmp,NULL);
    } else {
        free(v); return NULL;
    }
    return v;
}

static JsonVal *json_parse(const char *src, int len) {
    JP p={src,0,len};
    JsonVal *v=parse_val(&p);
    if(!v) return NULL;
    skip_ws(&p);
    if(p.pos!=p.len){free(v);return NULL;}
    return v;
}

static JsonVal *jget(JsonVal *o, const char *k) {
    if(!o||o->type!=JSON_OBJ) return NULL;
    for(int i=0;i<o->obj.count;i++)
        if(strcmp(o->obj.keys[i],k)==0) return o->obj.vals[i];
    return NULL;
}

/* ─── Base64url ─── */
static int b64u_valid(const char *s, int len) {
    if(len%4==1) return 0;
    for(int i=0;i<len;i++){
        char c=s[i];
        if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='-'||c=='_'))
            return 0;
    }
    return 1;
}

static int b64u_val(char c) {
    if(c>='A'&&c<='Z')return c-'A';
    if(c>='a'&&c<='z')return c-'a'+26;
    if(c>='0'&&c<='9')return c-'0'+52;
    if(c=='-')return 62;
    if(c=='_')return 63;
    return -1;
}

static unsigned char *b64u_dec(const char *s, int len, int *out_len) {
    int full=len/4, rem=len%4;
    int total=full*3+(rem==2?1:rem==3?2:0);
    unsigned char *out=malloc(total>0?total:1);
    int oi=0;
    for(int i=0;i<full*4;i+=4){
        int a=b64u_val(s[i]),b=b64u_val(s[i+1]),c=b64u_val(s[i+2]),d=b64u_val(s[i+3]);
        out[oi++]=(a<<2)|(b>>4);
        out[oi++]=((b&0xF)<<4)|(c>>2);
        out[oi++]=((c&0x3)<<6)|d;
    }
    if(rem==2){
        int a=b64u_val(s[full*4]),b=b64u_val(s[full*4+1]);
        out[oi++]=(a<<2)|(b>>4);
    } else if(rem==3){
        int a=b64u_val(s[full*4]),b=b64u_val(s[full*4+1]),c=b64u_val(s[full*4+2]);
        out[oi++]=(a<<2)|(b>>4);
        out[oi++]=((b&0xF)<<4)|(c>>2);
    }
    *out_len=oi;
    return out;
}

/* ─── Key set ─── */
typedef struct {
    char *kid;
    char *alg;
    unsigned char *secret;
    int secret_len;
} KeyEntry;

/* ─── Scope helpers ─── */
static int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char**)a, *(const char**)b);
}

/* ─── Read file ─── */
static char *read_file(const char *path, int *out_len) {
    FILE *f=fopen(path,"rb");
    if(!f){*out_len=0;return NULL;}
    fseek(f,0,SEEK_END);
    long sz=ftell(f);
    fseek(f,0,SEEK_SET);
    char *buf=malloc(sz+1);
    fread(buf,1,sz,f);
    buf[sz]='\0';
    fclose(f);
    *out_len=(int)sz;
    return buf;
}

/* ─── Main ─── */
int main(int argc, char **argv) {
    if(argc<2){return 1;}
    char dir[4096];
    snprintf(dir,sizeof(dir),"%s",argv[1]);

    /* Read config */
    char cpath[4096];
    snprintf(cpath,sizeof(cpath),"%s/config.json",dir);
    int clen=0;
    char *cbuf=read_file(cpath,&clen);
    if(!cbuf) return 1;
    JsonVal *cfg=json_parse(cbuf,clen);
    if(!cfg||cfg->type!=JSON_OBJ) return 1;

    double now=0, leeway=0;
    JsonVal *v;
    v=jget(cfg,"now"); if(v&&v->type==JSON_NUM) now=v->num;
    v=jget(cfg,"leeway"); if(v&&v->type==JSON_NUM) leeway=v->num;

    char *issuer=NULL, *audience=NULL;
    v=jget(cfg,"issuer"); if(v&&v->type==JSON_STR) issuer=strdup(v->str);
    v=jget(cfg,"audience"); if(v&&v->type==JSON_STR) audience=strdup(v->str);

    /* Parse keys */
    KeyEntry keys[256]; int nkeys=0;
    v=jget(cfg,"keys");
    if(v&&v->type==JSON_ARR){
        for(int i=0;i<v->arr.count&&nkeys<256;i++){
            JsonVal *ko=v->arr.items[i];
            if(!ko||ko->type!=JSON_OBJ) continue;
            JsonVal *kid=jget(ko,"kid");
            JsonVal *kty=jget(ko,"kty");
            JsonVal *alg=jget(ko,"alg");
            JsonVal *k=jget(ko,"k");
            if(!kid||kid->type!=JSON_STR) continue;
            if(!k||k->type!=JSON_STR) continue;
            keys[nkeys].kid=strdup(kid->str);
            keys[nkeys].alg=(alg&&alg->type==JSON_STR)?strdup(alg->str):NULL;
            (void)kty;
            int slen=0;
            keys[nkeys].secret=b64u_dec(k->str,(int)strlen(k->str),&slen);
            keys[nkeys].secret_len=slen;
            nkeys++;
        }
    }

    /* Read tokens */
    char tpath[4096];
    snprintf(tpath,sizeof(tpath),"%s/tokens.txt",dir);
    int tlen=0;
    char *tbuf=read_file(tpath,&tlen);
    if(!tbuf) return 1;

    int valid_count=0, invalid_count=0;
    int line_num=0;

    /* Process lines */
    int i=0;
    while(i<tlen){
        /* Find end of line */
        int ls=i;
        while(i<tlen&&tbuf[i]!='\n') i++;
        int le=i; /* exclusive */
        if(i<tlen) i++; /* skip \n */

        /* Trim leading/trailing spaces and tabs */
        while(ls<le&&(tbuf[ls]==' '||tbuf[ls]=='\t')) ls++;
        while(le>ls&&(tbuf[le-1]==' '||tbuf[le-1]=='\t')) le--;
        if(ls>=le) continue; /* empty after trim */

        line_num++;

        /* Extract token string */
        int tok_len=le-ls;
        char *tok=malloc(tok_len+1);
        memcpy(tok,tbuf+ls,tok_len);
        tok[tok_len]='\0';

        /* Rule 1: MALFORMED - exactly 3 segments */
        int d1=-1,d2=-1;
        for(int j=0;j<tok_len;j++){
            if(tok[j]=='.'){
                if(d1<0) d1=j;
                else if(d2<0) d2=j;
                else { /* more than 2 dots */ }
            }
        }
        int malformed=0;
        if(d1<0||d2<0||d2==d1+1||d1==0||d2==tok_len-1){
            /* Check: need exactly 3 segments, each non-empty */
            /* Count dots */
            int ndots=0;
            for(int j=0;j<tok_len;j++) if(tok[j]=='.') ndots++;
            if(ndots!=2) malformed=1;
            else {
                /* segments: [0,d1), (d1,d2), (d2,len) */
                if(d1==0||d2==d1+1||d2==tok_len-1) malformed=1;
            }
        }
        /* More careful: find first and last dot, check no dots between */
        if(!malformed){
            int ndots=0;
            int dots[16];
            for(int j=0;j<tok_len&&ndots<16;j++) if(tok[j]=='.') dots[ndots++]=j;
            if(ndots!=2) malformed=1;
            else {
                int s1_end=dots[0], s2_start=dots[0]+1, s2_end=dots[1], s3_start=dots[1]+1;
                if(s1_end==0||s2_end-s2_start==0||tok_len-s3_start==0) malformed=1;
            }
        }

        if(!malformed){
            int ndots=0;
            int dots[16];
            for(int j=0;j<tok_len&&ndots<16;j++) if(tok[j]=='.') dots[ndots++]=j;
            if(ndots!=2) malformed=1;
        }

        /* Get segment pointers and lengths */
        char *seg1=NULL,*seg2=NULL,*seg3=NULL;
        int seg1_len=0,seg2_len=0,seg3_len=0;

        if(!malformed){
            int ndots=0;
            int dots[4];
            for(int j=0;j<tok_len&&ndots<4;j++) if(tok[j]=='.') dots[ndots++]=j;
            /* We need exactly 2 dots */
            if(ndots!=2){malformed=1;}
            else{
                seg1=tok; seg1_len=dots[0];
                seg2=tok+dots[0]+1; seg2_len=dots[1]-dots[0]-1;
                seg3=tok+dots[1]+1; seg3_len=tok_len-dots[1]-1;
                if(seg1_len==0||seg2_len==0||seg3_len==0) malformed=1;
            }
        }

        if(!malformed){
            if(!b64u_valid(seg1,seg1_len)||!b64u_valid(seg2,seg2_len)||!b64u_valid(seg3,seg3_len))
                malformed=1;
        }

        JsonVal *hdr=NULL,*pld=NULL;
        if(!malformed){
            int hlen=0,plen=0;
            unsigned char *hdec=b64u_dec(seg1,seg1_len,&hlen);
            unsigned char *pdec=b64u_dec(seg2,seg2_len,&plen);
            hdr=json_parse((char*)hdec,hlen);
            pld=json_parse((char*)pdec,plen);
            free(hdec);free(pdec);
            if(!hdr||hdr->type!=JSON_OBJ||!pld||pld->type!=JSON_OBJ) malformed=1;
        }

        if(malformed){
            printf("%d: MALFORMED\n",line_num);
            invalid_count++;
            free(tok);
            continue;
        }

        /* Rule 2: UNSUPPORTED_ALG */
        JsonVal *alg_v=jget(hdr,"alg");
        if(!alg_v||alg_v->type!=JSON_STR){
            printf("%d: UNSUPPORTED_ALG\n",line_num);
            invalid_count++; free(tok);
            if(hdr)free(hdr);if(pld)free(pld);
            continue;
        }
        char *alg_str=alg_v->str;
        if(strcmp(alg_str,"HS256")!=0&&strcmp(alg_str,"HS384")!=0&&strcmp(alg_str,"HS512")!=0){
            printf("%d: UNSUPPORTED_ALG\n",line_num);
            invalid_count++; free(tok);
            if(hdr)free(hdr);if(pld)free(pld);
            continue;
        }

        /* Rule 3: UNKNOWN_KEY */
        JsonVal *kid_v=jget(hdr,"kid");
        if(!kid_v||kid_v->type!=JSON_STR){
            printf("%d: UNKNOWN_KEY\n",line_num);
            invalid_count++; free(tok);
            if(hdr)free(hdr);if(pld)free(pld);
            continue;
        }
        KeyEntry *found=NULL;
        for(int k=0;k<nkeys;k++){
            if(strcmp(keys[k].kid,kid_v->str)==0){found=&keys[k];break;}
        }
        if(!found){
            printf("%d: UNKNOWN_KEY\n",line_num);
            invalid_count++; free(tok);
            if(hdr)free(hdr);if(pld)free(pld);
            continue;
        }

        /* Rule 4: ALG_MISMATCH */
        if(!found->alg||strcmp(found->alg,alg_str)!=0){
            printf("%d: ALG_MISMATCH\n",line_num);
            invalid_count++; free(tok);
            if(hdr)free(hdr);if(pld)free(pld);
            continue;
        }

        /* Rule 5: BAD_SIGNATURE */
        /* signing input = seg1.seg2 (ASCII) */
        int si_len=seg1_len+1+seg2_len;
        char *si=malloc(si_len);
        memcpy(si,seg1,seg1_len);
        si[seg1_len]='.';
        memcpy(si+seg1_len+1,seg2,seg2_len);

        unsigned char mac[64];
        int mac_len;
        CCHmacAlgorithm cc_alg;
        if(strcmp(alg_str,"HS256")==0){cc_alg=kCCHmacAlgSHA256;mac_len=CC_SHA256_DIGEST_LENGTH;}
        else if(strcmp(alg_str,"HS384")==0){cc_alg=kCCHmacAlgSHA384;mac_len=CC_SHA384_DIGEST_LENGTH;}
        else{cc_alg=kCCHmacAlgSHA512;mac_len=CC_SHA512_DIGEST_LENGTH;}
        CCHmac(cc_alg,found->secret,found->secret_len,si,si_len,mac);
        free(si);

        int sig_len=0;
        unsigned char *sig=b64u_dec(seg3,seg3_len,&sig_len);
        if(sig_len!=mac_len||memcmp(sig,mac,mac_len)!=0){
            printf("%d: BAD_SIGNATURE\n",line_num);
            invalid_count++; free(tok);free(sig);
            if(hdr)free(hdr);if(pld)free(pld);
            continue;
        }
        free(sig);

        /* Rule 6: EXPIRED */
        JsonVal *exp_v=jget(pld,"exp");
        if(exp_v&&exp_v->type==JSON_NUM){
            if(now>=exp_v->num+leeway){
                printf("%d: EXPIRED\n",line_num);
                invalid_count++; free(tok);
                if(hdr)free(hdr);if(pld)free(pld);
                continue;
            }
        }

        /* Rule 7: NOT_YET_VALID */
        JsonVal *nbf_v=jget(pld,"nbf");
        if(nbf_v&&nbf_v->type==JSON_NUM){
            if(now+leeway<nbf_v->num){
                printf("%d: NOT_YET_VALID\n",line_num);
                invalid_count++; free(tok);
                if(hdr)free(hdr);if(pld)free(pld);
                continue;
            }
        }

        /* Rule 8: BAD_ISSUER */
        JsonVal *iss_v=jget(pld,"iss");
        if(!iss_v||iss_v->type!=JSON_STR||strcmp(iss_v->str,issuer)!=0){
            printf("%d: BAD_ISSUER\n",line_num);
            invalid_count++; free(tok);
            if(hdr)free(hdr);if(pld)free(pld);
            continue;
        }

        /* Rule 9: BAD_AUDIENCE */
        JsonVal *aud_v=jget(pld,"aud");
        int aud_ok=0;
        if(aud_v){
            if(aud_v->type==JSON_STR){
                if(strcmp(aud_v->str,audience)==0) aud_ok=1;
            } else if(aud_v->type==JSON_ARR){
                for(int j=0;j<aud_v->arr.count;j++){
                    JsonVal *e=aud_v->arr.items[j];
                    if(e&&e->type==JSON_STR&&strcmp(e->str,audience)==0){aud_ok=1;break;}
                }
            }
        }
        if(!aud_ok){
            printf("%d: BAD_AUDIENCE\n",line_num);
            invalid_count++; free(tok);
            if(hdr)free(hdr);if(pld)free(pld);
            continue;
        }

        /* VALID */
        valid_count++;
        JsonVal *sub_v=jget(pld,"sub");
        const char *sub_str=(sub_v&&sub_v->type==JSON_STR)?sub_v->str:"";

        /* scopes */
        JsonVal *scope_v=jget(pld,"scope");
        const char *scope_str=NULL;
        if(scope_v&&scope_v->type==JSON_STR) scope_str=scope_v->str;

        /* Split scope on spaces, dedup, sort */
        char *scopes_out=NULL;
        if(scope_str&&*scope_str){
            /* count pieces */
            int np=0;
            int slen=(int)strlen(scope_str);
            for(int j=0;j<slen;){
                while(j<slen&&scope_str[j]==' ')j++;
                if(j>=slen)break;
                np++;
                while(j<slen&&scope_str[j]!=' ')j++;
            }
            if(np>0){
                char **pieces=malloc(np*sizeof(char*));
                int pi=0;
                for(int j=0;j<slen;){
                    while(j<slen&&scope_str[j]==' ')j++;
                    if(j>=slen)break;
                    int ps=j;
                    while(j<slen&&scope_str[j]!=' ')j++;
                    int plen=j-ps;
                    pieces[pi]=malloc(plen+1);
                    memcpy(pieces[pi],scope_str+ps,plen);
                    pieces[pi][plen]='\0';
                    pi++;
                }
                /* sort */
                qsort(pieces,pi,sizeof(char*),cmp_str);
                /* dedup */
                int dp=0;
                for(int j=1;j<pi;j++){
                    if(strcmp(pieces[j],pieces[dp])!=0) dp++;
                    if(dp!=j) pieces[dp]=pieces[j];
                }
                dp++; /* dp = count after dedup */
                /* join */
                int total_len=0;
                for(int j=0;j<dp;j++) total_len+=(int)strlen(pieces[j]);
                total_len+=dp-1; /* commas */
                scopes_out=malloc(total_len+1);
                int pos=0;
                for(int j=0;j<dp;j++){
                    if(j>0) scopes_out[pos++]=',';
                    int l=(int)strlen(pieces[j]);
                    memcpy(scopes_out+pos,pieces[j],l);
                    pos+=l;
                }
                scopes_out[pos]='\0';
                for(int j=0;j<pi;j++) free(pieces[j]);
                free(pieces);
            }
        }

        printf("%d: VALID sub=%s scope=%s\n",line_num,sub_str,scopes_out?scopes_out:"");
        free(scopes_out);
        free(tok);
        if(hdr)free(hdr);
        if(pld)free(pld);
    }

    printf("\nvalid=%d invalid=%d\n",valid_count,invalid_count);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

/* --- JSON Value --- */
typedef enum { JSON_NULL, JSON_BOOL, JSON_NUM, JSON_STR, JSON_ARR, JSON_OBJ } JsonType;
typedef struct JsonValue JsonValue;
typedef struct { char *key; JsonValue *val; } JsonMember;
struct JsonValue {
    JsonType type;
    union {
        bool boolean;
        double number;
        char *string;
        struct { JsonValue **items; size_t count; size_t cap; } array;
        struct { JsonMember *members; size_t count; size_t cap; } object;
    };
};

static void *xmalloc(size_t n){ void*p=malloc(n); if(!p){fprintf(stderr,"OOM\n");exit(1);} return p; }
static void *xrealloc(void*p,size_t n){ void*q=realloc(p,n); if(!q){fprintf(stderr,"OOM\n");exit(1);} return q; }
static char *xstrdup(const char*s){ size_t l=strlen(s)+1; char*p=xmalloc(l); memcpy(p,s,l); return p; }

/* --- Parser --- */
static const char *g_input;
static size_t g_pos, g_len;

static void skip_ws(void){
    while(g_pos<g_len){char c=g_input[g_pos];if(c==' '||c=='\t'||c=='\n'||c=='\r')g_pos++;else break;}
}
static void expect(char c){
    skip_ws();
    if(g_pos>=g_len||g_input[g_pos]!=c){fprintf(stderr,"Expected '%c' at %zu\n",c,g_pos);exit(1);}
    g_pos++;
}
static JsonValue *parse_value(void);

static void encode_utf8(uint32_t cp, char *out, int *len){
    if(cp<0x80){out[0]=(char)cp;*len=1;}
    else if(cp<0x800){out[0]=(char)(0xC0|(cp>>6));out[1]=(char)(0x80|(cp&0x3F));*len=2;}
    else if(cp<0x10000){out[0]=(char)(0xE0|(cp>>12));out[1]=(char)(0x80|((cp>>6)&0x3F));out[2]=(char)(0x80|(cp&0x3F));*len=3;}
    else{out[0]=(char)(0xF0|(cp>>18));out[1]=(char)(0x80|((cp>>12)&0x3F));out[2]=(char)(0x80|((cp>>6)&0x3F));out[3]=(char)(0x80|(cp&0x3F));*len=4;}
}
static uint32_t parse_hex4(void){
    uint32_t v=0;
    for(int i=0;i<4;i++){char c=g_input[g_pos++];
        if(c>='0'&&c<='9')v=v*16+(c-'0');
        else if(c>='a'&&c<='f')v=v*16+(c-'a'+10);
        else if(c>='A'&&c<='F')v=v*16+(c-'A'+10);
        else{fprintf(stderr,"Bad hex\n");exit(1);}}
    return v;
}
static char *parse_string_raw(void){
    size_t cap=64,len=0;
    char *buf=xmalloc(cap);
    while(g_pos<g_len&&g_input[g_pos]!='"'){
        char c=g_input[g_pos];
        if(c=='\\'){
            g_pos++;
            char e=g_input[g_pos++];
            char tmp[4];int tlen=0;
            switch(e){
                case '"':tmp[0]='"';tlen=1;break;
                case '\\':tmp[0]='\\';tlen=1;break;
                case '/':tmp[0]='/';tlen=1;break;
                case 'b':tmp[0]='\b';tlen=1;break;
                case 'f':tmp[0]='\f';tlen=1;break;
                case 'n':tmp[0]='\n';tlen=1;break;
                case 'r':tmp[0]='\r';tlen=1;break;
                case 't':tmp[0]='\t';tlen=1;break;
                case 'u':{
                    uint32_t cp=parse_hex4();
                    if(cp>=0xD800&&cp<=0xDBFF&&g_pos+1<g_len&&g_input[g_pos]=='\\'&&g_input[g_pos+1]=='u'){
                        g_pos+=2;uint32_t lo=parse_hex4();
                        cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    }
                    encode_utf8(cp,tmp,&tlen);break;
                }
                default:fprintf(stderr,"Bad escape %c\n",e);exit(1);
            }
            if(len+tlen+1>cap){cap=(len+tlen+1)*2;buf=xrealloc(buf,cap);}
            memcpy(buf+len,tmp,tlen);len+=tlen;
        } else {
            if(len+2>cap){cap*=2;buf=xrealloc(buf,cap);}
            buf[len++]=c;g_pos++;
        }
    }
    if(g_pos<g_len&&g_input[g_pos]=='"')g_pos++;
    buf[len]='\0';return buf;
}

static JsonValue *parse_value(void){
    skip_ws();
    char c=g_input[g_pos];
    if(c=='{'){
        g_pos++;skip_ws();
        JsonValue*v=xmalloc(sizeof(JsonValue));v->type=JSON_OBJ;
        v->object.count=0;v->object.cap=8;v->object.members=xmalloc(v->object.cap*sizeof(JsonMember));
        if(g_input[g_pos]=='}'){g_pos++;return v;}
        while(1){
            skip_ws();expect('"');
            char *key=parse_string_raw();
            skip_ws();expect(':');
            JsonValue*val=parse_value();
            if(v->object.count>=v->object.cap){v->object.cap*=2;v->object.members=xrealloc(v->object.members,v->object.cap*sizeof(JsonMember));}
            v->object.members[v->object.count].key=key;
            v->object.members[v->object.count].val=val;
            v->object.count++;
            skip_ws();
            if(g_input[g_pos]==','){g_pos++;continue;}
            if(g_input[g_pos]=='}'){g_pos++;break;}
            fprintf(stderr,"Expected , or }\n");exit(1);
        }
        return v;
    }
    if(c=='['){
        g_pos++;skip_ws();
        JsonValue*v=xmalloc(sizeof(JsonValue));v->type=JSON_ARR;
        v->array.count=0;v->array.cap=8;v->array.items=xmalloc(v->array.cap*sizeof(JsonValue*));
        if(g_input[g_pos]==']'){g_pos++;return v;}
        while(1){
            JsonValue*item=parse_value();
            if(v->array.count>=v->array.cap){v->array.cap*=2;v->array.items=xrealloc(v->array.items,v->array.cap*sizeof(JsonValue*));}
            v->array.items[v->array.count++]=item;
            skip_ws();
            if(g_input[g_pos]==','){g_pos++;continue;}
            if(g_input[g_pos]==']'){g_pos++;break;}
            fprintf(stderr,"Expected , or ]\n");exit(1);
        }
        return v;
    }
    if(c=='"'){g_pos++;char*s=parse_string_raw();JsonValue*v=xmalloc(sizeof(JsonValue));v->type=JSON_STR;v->string=s;return v;}
    if(c=='t'){g_pos+=4;JsonValue*v=xmalloc(sizeof(JsonValue));v->type=JSON_BOOL;v->boolean=true;return v;}
    if(c=='f'){g_pos+=5;JsonValue*v=xmalloc(sizeof(JsonValue));v->type=JSON_BOOL;v->boolean=false;return v;}
    if(c=='n'){g_pos+=4;JsonValue*v=xmalloc(sizeof(JsonValue));v->type=JSON_NULL;return v;}
    /* number */
    const char*start=g_input+g_pos;char*end;
    double d=strtod(start,&end);g_pos+=(size_t)(end-start);
    JsonValue*v=xmalloc(sizeof(JsonValue));v->type=JSON_NUM;v->number=d;return v;
}

/* --- Object helpers --- */
static JsonValue *obj_get(JsonValue *obj, const char *key){
    if(!obj||obj->type!=JSON_OBJ)return NULL;
    for(size_t i=0;i<obj->object.count;i++)
        if(strcmp(obj->object.members[i].key,key)==0)return obj->object.members[i].val;
    return NULL;
}
static bool obj_has(JsonValue *obj, const char *key){ return obj_get(obj,key)!=NULL; }

/* --- Deep equality --- */
static bool json_equal(JsonValue*a,JsonValue*b){
    if(a->type!=b->type)return false;
    switch(a->type){
        case JSON_NULL:return true;
        case JSON_BOOL:return a->boolean==b->boolean;
        case JSON_NUM:return a->number==b->number;
        case JSON_STR:return strcmp(a->string,b->string)==0;
        case JSON_ARR:
            if(a->array.count!=b->array.count)return false;
            for(size_t i=0;i<a->array.count;i++)if(!json_equal(a->array.items[i],b->array.items[i]))return false;
            return true;
        case JSON_OBJ:
            if(a->object.count!=b->object.count)return false;
            for(size_t i=0;i<a->object.count;i++){
                JsonValue*bv=obj_get(b,a->object.members[i].key);
                if(!bv||!json_equal(a->object.members[i].val,bv))return false;
            }
            return true;
    }
    return false;
}

/* --- Code point length --- */
static size_t str_cp_len(const char*s){
    size_t l=0;while(*s){if((*s&0xC0)!=0x80)l++;s++;}return l;
}

/* --- JSON Pointer --- */
static char *escape_token(const char*s){
    size_t len=strlen(s),elen=0;
    for(size_t i=0;i<len;i++){if(s[i]=='~'||s[i]=='/')elen+=2;else elen++;}
    char*out=xmalloc(elen+1);size_t j=0;
    for(size_t i=0;i<len;i++){
        if(s[i]=='~'){out[j++]='~';out[j++]='0';}
        else if(s[i]=='/'){out[j++]='~';out[j++]='1';}
        else out[j++]=s[i];
    }
    out[j]='\0';return out;
}
static char *path_append(const char*path,const char*token){
    char*esc=escape_token(token);
    size_t pl=strlen(path),tl=strlen(esc);
    char*out=xmalloc(pl+1+tl+1);
    memcpy(out,path,pl);out[pl]='/';memcpy(out+pl+1,esc,tl+1);
    free(esc);return out;
}
static char *path_append_idx(const char*path,size_t idx){
    char nb[32];snprintf(nb,sizeof(nb),"%zu",idx);
    return path_append(path,nb);
}
static char *unescape_token(const char*s){
    size_t len=strlen(s);char*out=xmalloc(len+1);size_t j=0;
    for(size_t i=0;i<len;i++){
        if(s[i]=='~'&&i+1<len&&s[i+1]=='0'){out[j++]='~';i++;}
        else if(s[i]=='~'&&i+1<len&&s[i+1]=='1'){out[j++]='/';i++;}
        else out[j++]=s[i];
    }
    out[j]='\0';return out;
}

/* --- Error list --- */
typedef struct{char*inst_loc;char*schema_loc;}Error;
typedef struct{Error*errs;size_t count;size_t cap;}ErrorList;
static void el_init(ErrorList*e){e->errs=NULL;e->count=0;e->cap=0;}
static void el_add(ErrorList*e,const char*il,const char*sl){
    if(e->count>=e->cap){e->cap=e->cap?e->cap*2:16;e->errs=xrealloc(e->errs,e->cap*sizeof(Error));}
    e->errs[e->count].inst_loc=xstrdup(il);
    e->errs[e->count].schema_loc=xstrdup(sl);
    e->count++;
}
static void el_free(ErrorList*e){
    for(size_t i=0;i<e->count;i++){free(e->errs[i].inst_loc);free(e->errs[i].schema_loc);}
    free(e->errs);e->errs=NULL;e->count=0;e->cap=0;
}
static int err_cmp(const void*a,const void*b){
    const Error*ea=(const Error*)a,*eb=(const Error*)b;
    int c=strcmp(ea->inst_loc,eb->inst_loc);
    if(c)return c;return strcmp(ea->schema_loc,eb->schema_loc);
}
static void el_sort_dedup(ErrorList*e){
    if(e->count<=1)return;
    qsort(e->errs,e->count,sizeof(Error),err_cmp);
    size_t w=1;
    for(size_t i=1;i<e->count;i++){
        if(strcmp(e->errs[i].inst_loc,e->errs[i-1].inst_loc)!=0||
           strcmp(e->errs[i].schema_loc,e->errs[i-1].schema_loc)!=0)
            e->errs[w++]=e->errs[i];
    }
    e->count=w;
}

/* --- Validation --- */
static void validate(JsonValue*inst,JsonValue*schema,const char*il,const char*sl,JsonValue*root,ErrorList*errs);

static bool schema_accepts(JsonValue*inst,JsonValue*schema,const char*il,const char*sl,JsonValue*root){
    ErrorList tmp;el_init(&tmp);
    validate(inst,schema,il,sl,root,&tmp);
    bool ok=(tmp.count==0);
    el_free(&tmp);
    return ok;
}

static void resolve_ref(const char*ref,JsonValue*root,JsonValue**out_schema,char**out_loc){
    if(strcmp(ref,"#")==0){*out_schema=root;*out_loc=xstrdup("#");return;}
    const char*prefix="#/$defs/";size_t plen=strlen(prefix);
    if(strncmp(ref,prefix,plen)!=0){fprintf(stderr,"Unsupported $ref: %s\n",ref);exit(1);}
    char*name=unescape_token(ref+plen);
    JsonValue*defs=obj_get(root,"$defs");
    if(!defs||defs->type!=JSON_OBJ){fprintf(stderr,"No $defs\n");exit(1);}
    JsonValue*target=obj_get(defs,name);
    if(!target){fprintf(stderr,"No $defs/%s\n",name);exit(1);}
    *out_schema=target;
    *out_loc=xstrdup(ref);
    free(name);
}

static bool type_matches(JsonValue*inst,const char*tn){
    if(strcmp(tn,"null")==0)return inst->type==JSON_NULL;
    if(strcmp(tn,"boolean")==0)return inst->type==JSON_BOOL;
    if(strcmp(tn,"number")==0)return inst->type==JSON_NUM;
    if(strcmp(tn,"string")==0)return inst->type==JSON_STR;
    if(strcmp(tn,"array")==0)return inst->type==JSON_ARR;
    if(strcmp(tn,"object")==0)return inst->type==JSON_OBJ;
    if(strcmp(tn,"integer")==0)return inst->type==JSON_NUM&&inst->number==floor(inst->number);
    return false;
}

static void validate(JsonValue*inst,JsonValue*schema,const char*il,const char*sl,JsonValue*root,ErrorList*errs){
    if(schema->type==JSON_BOOL){
        if(!schema->boolean)el_add(errs,il,sl);
        return;
    }
    if(schema->type!=JSON_OBJ)return;

    /* $ref */
    JsonValue*ref_val=obj_get(schema,"$ref");
    if(ref_val&&ref_val->type==JSON_STR){
        JsonValue*rs;char*rl;
        resolve_ref(ref_val->string,root,&rs,&rl);
        validate(inst,rs,il,rl,root,errs);
        free(rl);
    }

    /* type */
    JsonValue*tv=obj_get(schema,"type");
    if(tv){
        bool ok=false;
        if(tv->type==JSON_STR){ok=type_matches(inst,tv->string);}
        else if(tv->type==JSON_ARR){
            for(size_t i=0;i<tv->array.count;i++)
                if(tv->array.items[i]->type==JSON_STR&&type_matches(inst,tv->array.items[i]->string)){ok=true;break;}
        }
        if(!ok){char*p=path_append(sl,"type");el_add(errs,il,p);free(p);}
    }

    /* enum */
    JsonValue*ev=obj_get(schema,"enum");
    if(ev&&ev->type==JSON_ARR){
        bool found=false;
        for(size_t i=0;i<ev->array.count;i++)if(json_equal(inst,ev->array.items[i])){found=true;break;}
        if(!found){char*p=path_append(sl,"enum");el_add(errs,il,p);free(p);}
    }

    /* const */
    JsonValue*cv=obj_get(schema,"const");
    if(cv){
        if(!json_equal(inst,cv)){char*p=path_append(sl,"const");el_add(errs,il,p);free(p);}
    }

    /* Numeric keywords */
    if(inst->type==JSON_NUM){
        double d=inst->number;JsonValue*v;
        v=obj_get(schema,"minimum");if(v&&v->type==JSON_NUM&&d<v->number){char*p=path_append(sl,"minimum");el_add(errs,il,p);free(p);}
        v=obj_get(schema,"maximum");if(v&&v->type==JSON_NUM&&d>v->number){char*p=path_append(sl,"maximum");el_add(errs,il,p);free(p);}
        v=obj_get(schema,"exclusiveMinimum");if(v&&v->type==JSON_NUM&&d<=v->number){char*p=path_append(sl,"exclusiveMinimum");el_add(errs,il,p);free(p);}
        v=obj_get(schema,"exclusiveMaximum");if(v&&v->type==JSON_NUM&&d>=v->number){char*p=path_append(sl,"exclusiveMaximum");el_add(errs,il,p);free(p);}
    }

    /* String keywords */
    if(inst->type==JSON_STR){
        size_t slen=str_cp_len(inst->string);JsonValue*v;
        v=obj_get(schema,"minLength");if(v&&v->type==JSON_NUM&&slen<(size_t)v->number){char*p=path_append(sl,"minLength");el_add(errs,il,p);free(p);}
        v=obj_get(schema,"maxLength");if(v&&v->type==JSON_NUM&&slen>(size_t)v->number){char*p=path_append(sl,"maxLength");el_add(errs,il,p);free(p);}
    }

    /* Array keywords */
    if(inst->type==JSON_ARR){
        size_t ic=inst->array.count;JsonValue*v;
        v=obj_get(schema,"minItems");if(v&&v->type==JSON_NUM&&ic<(size_t)v->number){char*p=path_append(sl,"minItems");el_add(errs,il,p);free(p);}
        v=obj_get(schema,"maxItems");if(v&&v->type==JSON_NUM&&ic>(size_t)v->number){char*p=path_append(sl,"maxItems");el_add(errs,il,p);free(p);}

        v=obj_get(schema,"uniqueItems");
        if(v&&v->type==JSON_BOOL&&v->boolean){
            bool uniq=true;
            for(size_t i=0;i<ic&&uniq;i++)
                for(size_t j=i+1;j<ic;j++)
                    if(json_equal(inst->array.items[i],inst->array.items[j])){uniq=false;break;}
            if(!uniq){char*p=path_append(sl,"uniqueItems");el_add(errs,il,p);free(p);}
        }

        /* prefixItems */
        JsonValue*pv=obj_get(schema,"prefixItems");
        size_t plen=0;
        if(pv&&pv->type==JSON_ARR){
            plen=pv->array.count;
            char*base=path_append(sl,"prefixItems");
            for(size_t i=0;i<plen&&i<ic;i++){
                char*ci=path_append_idx(il,i);
                char*cs=path_append_idx(base,i);
                validate(inst->array.items[i],pv->array.items[i],ci,cs,root,errs);
                free(ci);free(cs);
            }
            free(base);
        }

        /* items */
        JsonValue*iv=obj_get(schema,"items");
        if(iv){
            char*iloc=path_append(sl,"items");
            for(size_t i=plen;i<ic;i++){
                char*ci=path_append_idx(il,i);
                validate(inst->array.items[i],iv,ci,iloc,root,errs);
                free(ci);
            }
            free(iloc);
        }
    }

    /* Object keywords */
    if(inst->type==JSON_OBJ){
        size_t pc=inst->object.count;JsonValue*v;
        v=obj_get(schema,"minProperties");if(v&&v->type==JSON_NUM&&pc<(size_t)v->number){char*p=path_append(sl,"minProperties");el_add(errs,il,p);free(p);}
        v=obj_get(schema,"maxProperties");if(v&&v->type==JSON_NUM&&pc>(size_t)v->number){char*p=path_append(sl,"maxProperties");el_add(errs,il,p);free(p);}

        /* required */
        v=obj_get(schema,"required");
        if(v&&v->type==JSON_ARR){
            char*base=path_append(sl,"required");
            for(size_t i=0;i<v->array.count;i++){
                if(v->array.items[i]->type==JSON_STR&&!obj_has(inst,v->array.items[i]->string)){
                    char*p=path_append_idx(base,i);el_add(errs,il,p);free(p);
                }
            }
            free(base);
        }

        /* properties */
        JsonValue*props=obj_get(schema,"properties");
        if(props&&props->type==JSON_OBJ){
            char*base=path_append(sl,"properties");
            for(size_t i=0;i<inst->object.count;i++){
                JsonValue*ps=obj_get(props,inst->object.members[i].key);
                if(ps){
                    char*ci=path_append(il,inst->object.members[i].key);
                    char*cs=path_append(base,inst->object.members[i].key);
                    validate(inst->object.members[i].val,ps,ci,cs,root,errs);
                    free(ci);free(cs);
                }
            }
            free(base);
        }

        /* additionalProperties */
        JsonValue*apv=obj_get(schema,"additionalProperties");
        if(apv){
            char*aloc=path_append(sl,"additionalProperties");
            for(size_t i=0;i<inst->object.count;i++){
                const char*key=inst->object.members[i].key;
                bool in_props=false;
                if(props&&props->type==JSON_OBJ)in_props=obj_has(props,key);
                if(!in_props){
                    char*ci=path_append(il,key);
                    validate(inst->object.members[i].val,apv,ci,aloc,root,errs);
                    free(ci);
                }
            }
            free(aloc);
        }
    }

    /* allOf */
    JsonValue*av=obj_get(schema,"allOf");
    if(av&&av->type==JSON_ARR){
        char*base=path_append(sl,"allOf");
        for(size_t i=0;i<av->array.count;i++){
            char*cl=path_append_idx(base,i);
            validate(inst,av->array.items[i],il,cl,root,errs);
            free(cl);
        }
        free(base);
    }

    /* anyOf */
    JsonValue*aov=obj_get(schema,"anyOf");
    if(aov&&aov->type==JSON_ARR){
        bool any_ok=false;
        char*base=path_append(sl,"anyOf");
        for(size_t i=0;i<aov->array.count;i++){
            char*cl=path_append_idx(base,i);
            if(schema_accepts(inst,aov->array.items[i],il,cl,root)){any_ok=true;free(cl);break;}
            free(cl);
        }
        free(base);
        if(!any_ok){char*p=path_append(sl,"anyOf");el_add(errs,il,p);free(p);}
    }

    /* oneOf */
    JsonValue*ov=obj_get(schema,"oneOf");
    if(ov&&ov->type==JSON_ARR){
        int cnt=0;
        char*base=path_append(sl,"oneOf");
        for(size_t i=0;i<ov->array.count;i++){
            char*cl=path_append_idx(base,i);
            if(schema_accepts(inst,ov->array.items[i],il,cl,root))cnt++;
            free(cl);
            if(cnt>1)break;
        }
        free(base);
        if(cnt!=1){char*p=path_append(sl,"oneOf");el_add(errs,il,p);free(p);}
    }

    /* not */
    JsonValue*nv=obj_get(schema,"not");
    if(nv){
        char*nl=path_append(sl,"not");
        if(schema_accepts(inst,nv,il,nl,root)){el_add(errs,il,nl);}
        free(nl);
    }

    /* if/then/else */
    JsonValue*ifv=obj_get(schema,"if");
    if(ifv){
        char*ifloc=path_append(sl,"if");
        bool ifok=schema_accepts(inst,ifv,il,ifloc,root);
        free(ifloc);
        if(ifok){
            JsonValue*th=obj_get(schema,"then");
            if(th){char*tl=path_append(sl,"then");validate(inst,th,il,tl,root,errs);free(tl);}
        }else{
            JsonValue*el2=obj_get(schema,"else");
            if(el2){char*eloc=path_append(sl,"else");validate(inst,el2,il,eloc,root,errs);free(eloc);}
        }
    }
}

/* --- Main --- */
static char *read_file(const char*path,size_t*out_len){
    FILE*f=fopen(path,"rb");
    if(!f){fprintf(stderr,"Cannot open %s\n",path);exit(1);}
    fseek(f,0,SEEK_END);size_t sz=(size_t)ftell(f);fseek(f,0,SEEK_SET);
    char*buf=xmalloc(sz+1);
    fread(buf,1,sz,f);buf[sz]='\0';fclose(f);
    *out_len=sz;return buf;
}

int main(int argc,char**argv){
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
    char spath[4096],ipath[4096];
    snprintf(spath,sizeof(spath),"%s/schema.json",argv[1]);
    snprintf(ipath,sizeof(ipath),"%s/instances.json",argv[1]);

    size_t slen,ilen;
    char*sbuf=read_file(spath,&slen);
    char*ibuf=read_file(ipath,&ilen);

    g_input=sbuf;g_pos=0;g_len=slen;
    JsonValue*schema=parse_value();

    g_input=ibuf;g_pos=0;g_len=ilen;
    JsonValue*instances=parse_value();

    size_t ninst=instances->array.count;
    size_t vcount=0,icount=0;

    for(size_t n=0;n<ninst;n++){
        ErrorList errs;el_init(&errs);
        validate(instances->array.items[n],schema,"#","#",schema,&errs);
        el_sort_dedup(&errs);
        if(errs.count==0){
            printf("%zu: valid\n",n);
            vcount++;
        }else{
            printf("%zu: invalid (%zu)\n",n,errs.count);
            for(size_t i=0;i<errs.count;i++)
                printf("  %s %s\n",errs.errs[i].inst_loc,errs.errs[i].schema_loc);
            icount++;
        }
        el_free(&errs);
    }
    printf("valid=%zu invalid=%zu\n",vcount,icount);
    return 0;
}

import sys
import json


def is_valid_id(val):
    if isinstance(val, bool):
        return False
    if isinstance(val, str):
        return True
    if isinstance(val, int):
        return True
    return False


def extract_id(msg):
    if 'id' in msg and is_valid_id(msg['id']):
        return msg['id']
    return None


def get_tools():
    return [
        {
            "name": "kv_set",
            "title": "Set a value",
            "description": "Store a string value under a key, replacing any previous value.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "key": {"type": "string", "minLength": 1},
                    "value": {"type": "string"}
                },
                "required": ["key", "value"],
                "additionalProperties": False
            }
        },
        {
            "name": "kv_get",
            "title": "Get a value",
            "description": "Return the value stored under a key.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "key": {"type": "string", "minLength": 1}
                },
                "required": ["key"],
                "additionalProperties": False
            }
        },
        {
            "name": "kv_list",
            "title": "List keys",
            "description": "List the stored keys that start with a prefix, sorted by Unicode code point.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "prefix": {"type": "string"}
                },
                "additionalProperties": False
            },
            "outputSchema": {
                "type": "object",
                "properties": {
                    "keys": {"type": "array", "items": {"type": "string"}},
                    "count": {"type": "integer"}
                },
                "required": ["keys", "count"]
            }
        },
        {
            "name": "sum",
            "title": "Sum integers",
            "description": "Add up a non-empty list of integers.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "numbers": {
                        "type": "array",
                        "items": {"type": "integer"},
                        "minItems": 1
                    }
                },
                "required": ["numbers"],
                "additionalProperties": False
            },
            "outputSchema": {
                "type": "object",
                "properties": {
                    "sum": {"type": "integer"},
                    "count": {"type": "integer"}
                },
                "required": ["sum", "count"]
            },
            "annotations": {
                "readOnlyHint": True,
                "idempotentHint": True
            }
        },
        {
            "name": "text_stats",
            "title": "Text statistics",
            "description": "Count the words, Unicode code points and UTF-8 bytes of a text.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "text": {"type": "string"}
                },
                "required": ["text"],
                "additionalProperties": False
            },
            "outputSchema": {
                "type": "object",
                "properties": {
                    "words": {"type": "integer"},
                    "codepoints": {"type": "integer"},
                    "utf8_bytes": {"type": "integer"}
                },
                "required": ["words", "codepoints", "utf8_bytes"]
            },
            "annotations": {
                "readOnlyHint": True
            }
        }
    ]


TOOL_NAMES = {"kv_set", "kv_get", "kv_list", "sum", "text_stats"}


def validate_arguments(tool_schema, arguments):
    properties = tool_schema.get("properties", {})
    required = tool_schema.get("required", [])

    # Step 2: unknown arguments
    unknown = [k for k in arguments if k not in properties]
    if unknown:
        unknown.sort()
        return "unknown argument: " + unknown[0]

    # Step 3: per-property checks in schema order
    for prop_name in properties:
        if prop_name not in arguments:
            if prop_name in required:
                return "missing required argument: " + prop_name
            continue

        value = arguments[prop_name]
        prop_schema = properties[prop_name]
        prop_type = prop_schema.get("type")

        if prop_type == "string":
            if not isinstance(value, str):
                return "argument " + prop_name + " must be a string"
            min_length = prop_schema.get("minLength")
            if min_length is not None and len(value) < min_length:
                return "argument " + prop_name + " must not be empty"

        elif prop_type == "array":
            if not isinstance(value, list):
                return "argument " + prop_name + " must be an array of integers"
            items_schema = prop_schema.get("items", {})
            if items_schema.get("type") == "integer":
                for elem in value:
                    if isinstance(elem, bool) or not isinstance(elem, int):
                        return "argument " + prop_name + " must be an array of integers"
            min_items = prop_schema.get("minItems")
            if min_items is not None and len(value) < min_items:
                return "argument " + prop_name + " must not be empty"

    return None


def handle_tools_call(msg, req_id, store):
    params = msg.get('params')
    if params is None:
        params = {}

    name = params.get('name')
    if not isinstance(name, str):
        return {"jsonrpc": "2.0", "id": req_id, "error": {"code": -32602, "message": "Invalid params"}}

    if name not in TOOL_NAMES:
        return {"jsonrpc": "2.0", "id": req_id, "error": {"code": -32602, "message": "Unknown tool: " + name}}

    # Get tool definition
    tools = get_tools()
    tool_def = None
    for t in tools:
        if t["name"] == name:
            tool_def = t
            break

    # Validate arguments
    if 'arguments' in params:
        arguments = params['arguments']
        if not isinstance(arguments, dict):
            return {"jsonrpc": "2.0", "id": req_id, "result": {"content": [{"type": "text", "text": "arguments must be an object"}], "isError": True}}
    else:
        arguments = {}

    error = validate_arguments(tool_def["inputSchema"], arguments)
    if error is not None:
        return {"jsonrpc": "2.0", "id": req_id, "result": {"content": [{"type": "text", "text": error}], "isError": True}}

    # Execute tool
    if name == "kv_set":
        key = arguments["key"]
        value = arguments["value"]
        if key in store:
            text = "updated " + key
        else:
            text = "created " + key
        store[key] = value
        return {"jsonrpc": "2.0", "id": req_id, "result": {"content": [{"type": "text", "text": text}], "isError": False}}

    elif name == "kv_get":
        key = arguments["key"]
        if key not in store:
            return {"jsonrpc": "2.0", "id": req_id, "result": {"content": [{"type": "text", "text": "key not found: " + key}], "isError": True}}
        return {"jsonrpc": "2.0", "id": req_id, "result": {"content": [{"type": "text", "text": store[key]}], "isError": False}}

    elif name == "kv_list":
        prefix = arguments.get("prefix", "")
        keys = sorted([k for k in store if k.startswith(prefix)])
        structured = {"keys": keys, "count": len(keys)}
        text = json.dumps(structured)
        return {"jsonrpc": "2.0", "id": req_id, "result": {"content": [{"type": "text", "text": text}], "structuredContent": structured, "isError": False}}

    elif name == "sum":
        numbers = arguments["numbers"]
        total = sum(numbers)
        structured = {"sum": total, "count": len(numbers)}
        text = json.dumps(structured)
        return {"jsonrpc": "2.0", "id": req_id, "result": {"content": [{"type": "text", "text": text}], "structuredContent": structured, "isError": False}}

    elif name == "text_stats":
        text_input = arguments["text"]
        words = 0
        in_word = False
        for ch in text_input:
            if ch in (' ', '\t', '\n', '\r'):
                in_word = False
            else:
                if not in_word:
                    words += 1
                    in_word = True
        codepoints = len(text_input)
        utf8_bytes = len(text_input.encode('utf-8'))
        structured = {"words": words, "codepoints": codepoints, "utf8_bytes": utf8_bytes}
        text = json.dumps(structured)
        return {"jsonrpc": "2.0", "id": req_id, "result": {"content": [{"type": "text", "text": text}], "structuredContent": structured, "isError": False}}


def main():
    initialized = False
    store = {}

    for line in sys.stdin:
        stripped = line.rstrip('\r\n')
        if stripped.strip() == '':
            continue

        try:
            msg = json.loads(stripped)
        except (json.JSONDecodeError, ValueError):
            print(json.dumps({"jsonrpc": "2.0", "id": None, "error": {"code": -32700, "message": "Parse error"}}), flush=True)
            continue

        # Rule 2: not an object
        if not isinstance(msg, dict):
            print(json.dumps({"jsonrpc": "2.0", "id": None, "error": {"code": -32600, "message": "Invalid Request"}}), flush=True)
            continue

        # Rule 3: client response (no method but has result or error)
        if 'method' not in msg and ('result' in msg or 'error' in msg):
            continue

        # Rule 4: invalid request checks
        if msg.get('jsonrpc') != '2.0':
            id_val = extract_id(msg)
            print(json.dumps({"jsonrpc": "2.0", "id": id_val, "error": {"code": -32600, "message": "Invalid Request"}}), flush=True)
            continue

        if 'method' not in msg or not isinstance(msg['method'], str):
            id_val = extract_id(msg)
            print(json.dumps({"jsonrpc": "2.0", "id": id_val, "error": {"code": -32600, "message": "Invalid Request"}}), flush=True)
            continue

        if 'id' in msg and not is_valid_id(msg['id']):
            print(json.dumps({"jsonrpc": "2.0", "id": None, "error": {"code": -32600, "message": "Invalid Request"}}), flush=True)
            continue

        # Rule 5: notification (no id)
        if 'id' not in msg:
            continue

        # Rule 6: valid request
        req_id = msg['id']
        method = msg['method']

        # 6a: method not found
        if method not in ('initialize', 'ping', 'tools/list', 'tools/call'):
            print(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32601, "message": "Method not found"}}), flush=True)
            continue

        # 6b: params present but not object
        if 'params' in msg and not isinstance(msg['params'], dict):
            print(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32602, "message": "Invalid params"}}), flush=True)
            continue

        # 6c: not initialized
        if not initialized and method not in ('initialize', 'ping'):
            print(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32002, "message": "Server not initialized"}}), flush=True)
            continue

        # 6d: dispatch
        if method == 'initialize':
            if initialized:
                print(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32600, "message": "Already initialized"}}), flush=True)
                continue

            params = msg.get('params')
            if params is None or not isinstance(params, dict):
                print(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32602, "message": "Invalid params"}}), flush=True)
                continue

            pv = params.get('protocolVersion')
            if not isinstance(pv, str):
                print(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32602, "message": "Invalid params"}}), flush=True)
                continue

            known_versions = {"2025-06-18", "2025-03-26", "2024-11-05"}
            version = pv if pv in known_versions else "2025-06-18"
            initialized = True
            result = {
                "protocolVersion": version,
                "capabilities": {"tools": {"listChanged": False}},
                "serverInfo": {"name": "cb2-kv", "title": "CB2 key-value server", "version": "1.4.2"}
            }
            print(json.dumps({"jsonrpc": "2.0", "id": req_id, "result": result}), flush=True)

        elif method == 'ping':
            print(json.dumps({"jsonrpc": "2.0", "id": req_id, "result": {}}), flush=True)

        elif method == 'tools/list':
            print(json.dumps({"jsonrpc": "2.0", "id": req_id, "result": {"tools": get_tools()}}), flush=True)

        elif method == 'tools/call':
            response = handle_tools_call(msg, req_id, store)
            print(json.dumps(response), flush=True)

    sys.exit(0)


