use std::collections::{HashMap, HashSet};
use std::env;
use std::fs;

#[derive(Debug, Clone)]
enum Value {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Value>),
    Obj(HashMap<String, Value>),
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a [u8]) -> Self {
        Parser { input, pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn parse_value(&mut self) -> Value {
        self.skip_ws();
        match self.input[self.pos] {
            b'n' => { self.pos += 4; Value::Null }
            b't' => { self.pos += 4; Value::Bool(true) }
            b'f' => { self.pos += 5; Value::Bool(false) }
            b'"' => Value::Str(self.parse_string()),
            b'[' => {
                self.pos += 1;
                let mut arr = Vec::new();
                self.skip_ws();
                if self.pos < self.input.len() && self.input[self.pos] != b']' {
                    loop {
                        arr.push(self.parse_value());
                        self.skip_ws();
                        if self.pos < self.input.len() && self.input[self.pos] == b',' {
                            self.pos += 1;
                        } else {
                            break;
                        }
                    }
                }
                self.pos += 1;
                Value::Arr(arr)
            }
            b'{' => {
                self.pos += 1;
                let mut obj = HashMap::new();
                self.skip_ws();
                if self.pos < self.input.len() && self.input[self.pos] != b'}' {
                    loop {
                        self.skip_ws();
                        let key = self.parse_string();
                        self.skip_ws();
                        self.pos += 1;
                        let val = self.parse_value();
                        obj.insert(key, val);
                        self.skip_ws();
                        if self.pos < self.input.len() && self.input[self.pos] == b',' {
                            self.pos += 1;
                        } else {
                            break;
                        }
                    }
                }
                self.pos += 1;
                Value::Obj(obj)
            }
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> String {
        self.pos += 1;
        let mut result = String::new();
        while self.input[self.pos] != b'"' {
            if self.input[self.pos] == b'\\' {
                self.pos += 1;
                match self.input[self.pos] {
                    b'"' => { result.push('"'); self.pos += 1; }
                    b'\\' => { result.push('\\'); self.pos += 1; }
                    b'/' => { result.push('/'); self.pos += 1; }
                    b'b' => { result.push('\u{0008}'); self.pos += 1; }
                    b'f' => { result.push('\u{000C}'); self.pos += 1; }
                    b'n' => { result.push('\n'); self.pos += 1; }
                    b'r' => { result.push('\r'); self.pos += 1; }
                    b't' => { result.push('\t'); self.pos += 1; }
                    b'u' => {
                        self.pos += 1;
                        let cp = self.parse_hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            self.pos += 1; // '\'
                            self.pos += 1; // 'u'
                            let cp2 = self.parse_hex4();
                            let full = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                            result.push(char::from_u32(full).unwrap());
                        } else {
                            result.push(char::from_u32(cp).unwrap());
                        }
                    }
                    _ => unreachable!(),
                }
            } else {
                let start = self.pos;
                self.pos += 1;
                while self.pos < self.input.len() && (self.input[self.pos] & 0xC0) == 0x80 {
                    self.pos += 1;
                }
                result.push_str(std::str::from_utf8(&self.input[start..self.pos]).unwrap());
            }
        }
        self.pos += 1;
        result
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut val = 0u32;
        for _ in 0..4 {
            val <<= 4;
            let c = self.input[self.pos];
            val += match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => unreachable!(),
            };
            self.pos += 1;
        }
        val
    }

    fn parse_number(&mut self) -> Value {
        let start = self.pos;
        if self.pos < self.input.len() && self.input[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        Value::Num(s.parse::<f64>().unwrap())
    }
}

fn deep_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Num(x), Value::Num(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Arr(x), Value::Arr(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(a, b)| deep_equal(a, b))
        }
        (Value::Obj(x), Value::Obj(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).map_or(false, |w| deep_equal(v, w)))
        }
        _ => false,
    }
}

fn escape_pointer(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

fn unescape_token(s: &str) -> String {
    s.replace("~1", "/").replace("~0", "~")
}

fn resolve_ref<'a>(ref_str: &str, root: &'a Value) -> &'a Value {
    if ref_str == "#" {
        return root;
    }
    let path = &ref_str[2..]; // skip "#/"
    let mut current = root;
    for token in path.split('/') {
        let unescaped = unescape_token(token);
        current = match current {
            Value::Obj(map) => map.get(&unescaped).unwrap(),
            _ => unreachable!(),
        };
    }
    current
}

fn check_type(instance: &Value, type_val: &Value) -> bool {
    let types: Vec<&str> = match type_val {
        Value::Str(s) => vec![s.as_str()],
        Value::Arr(arr) => arr.iter().filter_map(|v| if let Value::Str(s) = v { Some(s.as_str()) } else { None }).collect(),
        _ => return true,
    };
    for t in types {
        match t {
            "null" => if matches!(instance, Value::Null) { return true; },
            "boolean" => if matches!(instance, Value::Bool(_)) { return true; },
            "number" => if matches!(instance, Value::Num(_)) { return true; },
            "integer" => if let Value::Num(n) = instance { if n.fract() == 0.0 { return true; } },
            "string" => if matches!(instance, Value::Str(_)) { return true; },
            "array" => if matches!(instance, Value::Arr(_)) { return true; },
            "object" => if matches!(instance, Value::Obj(_)) { return true; },
            _ => {}
        }
    }
    false
}

fn validate(schema: &Value, instance: &Value, inst_loc: &str, sch_loc: &str, root: &Value) -> Vec<(String, String)> {
    let mut errors: Vec<(String, String)> = Vec::new();

    match schema {
        Value::Bool(b) => {
            if !b {
                errors.push((inst_loc.to_string(), sch_loc.to_string()));
            }
            return errors;
        }
        Value::Obj(sch) => {
            // type
            if let Some(tv) = sch.get("type") {
                if !check_type(instance, tv) {
                    errors.push((inst_loc.to_string(), format!("{}/type", sch_loc)));
                }
            }

            // enum
            if let Some(Value::Arr(vals)) = sch.get("enum") {
                if !vals.iter().any(|v| deep_equal(instance, v)) {
                    errors.push((inst_loc.to_string(), format!("{}/enum", sch_loc)));
                }
            }

            // const
            if let Some(cv) = sch.get("const") {
                if !deep_equal(instance, cv) {
                    errors.push((inst_loc.to_string(), format!("{}/const", sch_loc)));
                }
            }

            // Number keywords
            if let Value::Num(n) = instance {
                if let Some(Value::Num(v)) = sch.get("minimum") {
                    if *n < *v { errors.push((inst_loc.to_string(), format!("{}/minimum", sch_loc))); }
                }
                if let Some(Value::Num(v)) = sch.get("maximum") {
                    if *n > *v { errors.push((inst_loc.to_string(), format!("{}/maximum", sch_loc))); }
                }
                if let Some(Value::Num(v)) = sch.get("exclusiveMinimum") {
                    if *n <= *v { errors.push((inst_loc.to_string(), format!("{}/exclusiveMinimum", sch_loc))); }
                }
                if let Some(Value::Num(v)) = sch.get("exclusiveMaximum") {
                    if *n >= *v { errors.push((inst_loc.to_string(), format!("{}/exclusiveMaximum", sch_loc))); }
                }
            }

            // String keywords
            if let Value::Str(s) = instance {
                let len = s.chars().count() as f64;
                if let Some(Value::Num(v)) = sch.get("minLength") {
                    if len < *v { errors.push((inst_loc.to_string(), format!("{}/minLength", sch_loc))); }
                }
                if let Some(Value::Num(v)) = sch.get("maxLength") {
                    if len > *v { errors.push((inst_loc.to_string(), format!("{}/maxLength", sch_loc))); }
                }
            }

            // Array keywords
            if let Value::Arr(arr) = instance {
                let count = arr.len();

                if let Some(Value::Num(v)) = sch.get("minItems") {
                    if (count as f64) < *v { errors.push((inst_loc.to_string(), format!("{}/minItems", sch_loc))); }
                }
                if let Some(Value::Num(v)) = sch.get("maxItems") {
                    if (count as f64) > *v { errors.push((inst_loc.to_string(), format!("{}/maxItems", sch_loc))); }
                }

                if let Some(Value::Bool(true)) = sch.get("uniqueItems") {
                    let mut has_dup = false;
                    'outer: for i in 0..count {
                        for j in (i + 1)..count {
                            if deep_equal(&arr[i], &arr[j]) {
                                has_dup = true;
                                break 'outer;
                            }
                        }
                    }
                    if has_dup {
                        errors.push((inst_loc.to_string(), format!("{}/uniqueItems", sch_loc)));
                    }
                }

                // prefixItems
                let prefix_len = if let Some(Value::Arr(prefixes)) = sch.get("prefixItems") {
                    let plen = prefixes.len().min(count);
                    for i in 0..plen {
                        errors.extend(validate(&prefixes[i], &arr[i],
                            &format!("{}/{}", inst_loc, i),
                            &format!("{}/prefixItems/{}", sch_loc, i), root));
                    }
                    prefixes.len()
                } else { 0 };

                // items
                if let Some(items_schema) = sch.get("items") {
                    for i in prefix_len..count {
                        errors.extend(validate(items_schema, &arr[i],
                            &format!("{}/{}", inst_loc, i),
                            &format!("{}/items", sch_loc), root));
                    }
                }
            }

            // Object keywords
            if let Value::Obj(obj) = instance {
                let count = obj.len();

                if let Some(Value::Num(v)) = sch.get("minProperties") {
                    if (count as f64) < *v { errors.push((inst_loc.to_string(), format!("{}/minProperties", sch_loc))); }
                }
                if let Some(Value::Num(v)) = sch.get("maxProperties") {
                    if (count as f64) > *v { errors.push((inst_loc.to_string(), format!("{}/maxProperties", sch_loc))); }
                }

                // required
                if let Some(Value::Arr(req)) = sch.get("required") {
                    for (j, name) in req.iter().enumerate() {
                        if let Value::Str(n) = name {
                            if !obj.contains_key(n) {
                                errors.push((inst_loc.to_string(), format!("{}/required/{}", sch_loc, j)));
                            }
                        }
                    }
                }

                // properties
                let prop_keys: HashSet<String> = if let Some(Value::Obj(props)) = sch.get("properties") {
                    for (name, sub) in props {
                        if let Some(val) = obj.get(name) {
                            errors.extend(validate(sub, val,
                                &format!("{}/{}", inst_loc, escape_pointer(name)),
                                &format!("{}/properties/{}", sch_loc, escape_pointer(name)), root));
                        }
                    }
                    props.keys().cloned().collect()
                } else {
                    HashSet::new()
                };

                // additionalProperties
                if let Some(addl) = sch.get("additionalProperties") {
                    for (name, val) in obj {
                        if !prop_keys.contains(name) {
                            errors.extend(validate(addl, val,
                                &format!("{}/{}", inst_loc, escape_pointer(name)),
                                &format!("{}/additionalProperties", sch_loc), root));
                        }
                    }
                }
            }

            // $ref
            if let Some(Value::Str(ref_str)) = sch.get("$ref") {
                let resolved = resolve_ref(ref_str, root);
                errors.extend(validate(resolved, instance, inst_loc, ref_str, root));
            }

            // allOf
            if let Some(Value::Arr(subs)) = sch.get("allOf") {
                for (i, sub) in subs.iter().enumerate() {
                    errors.extend(validate(sub, instance, inst_loc,
                        &format!("{}/allOf/{}", sch_loc, i), root));
                }
            }

            // anyOf
            if let Some(Value::Arr(subs)) = sch.get("anyOf") {
                let any_valid = subs.iter().enumerate().any(|(i, sub)| {
                    validate(sub, instance, inst_loc,
                        &format!("{}/anyOf/{}", sch_loc, i), root).is_empty()
                });
                if !any_valid {
                    errors.push((inst_loc.to_string(), format!("{}/anyOf", sch_loc)));
                }
            }

            // oneOf
            if let Some(Value::Arr(subs)) = sch.get("oneOf") {
                let accept_count = subs.iter().enumerate().filter(|(i, sub)| {
                    validate(sub, instance, inst_loc,
                        &format!("{}/oneOf/{}", sch_loc, i), root).is_empty()
                }).count();
                if accept_count != 1 {
                    errors.push((inst_loc.to_string(), format!("{}/oneOf", sch_loc)));
                }
            }

            // not
            if let Some(not_schema) = sch.get("not") {
                if validate(not_schema, instance, inst_loc,
                    &format!("{}/not", sch_loc), root).is_empty() {
                    errors.push((inst_loc.to_string(), format!("{}/not", sch_loc)));
                }
            }

            // if/then/else
            if let Some(if_schema) = sch.get("if") {
                let if_valid = validate(if_schema, instance, inst_loc,
                    &format!("{}/if", sch_loc), root).is_empty();
                if if_valid {
                    if let Some(then_schema) = sch.get("then") {
                        errors.extend(validate(then_schema, instance, inst_loc,
                            &format!("{}/then", sch_loc), root));
                    }
                } else {
                    if let Some(else_schema) = sch.get("else") {
                        errors.extend(validate(else_schema, instance, inst_loc,
                            &format!("{}/else", sch_loc), root));
                    }
                }
            }
        }
        _ => {}
    }

    errors
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let schema_str = fs::read_to_string(format!("{}/schema.json", dir)).unwrap();
    let instances_str = fs::read_to_string(format!("{}/instances.json", dir)).unwrap();

    let schema = Parser::new(schema_str.as_bytes()).parse_value();
    let instances = Parser::new(instances_str.as_bytes()).parse_value();

    let inst_arr = match &instances {
        Value::Arr(a) => a,
        _ => panic!("instances must be array"),
    };

    let mut valid_count = 0usize;
    let mut invalid_count = 0usize;

    for (n, instance) in inst_arr.iter().enumerate() {
        let mut errors = validate(&schema, instance, "#", "#", &schema);
        errors.sort();
        errors.dedup();

        if errors.is_empty() {
            println!("{}: valid", n);
            valid_count += 1;
        } else {
            println!("{}: invalid ({})", n, errors.len());
            for (inst_loc, sch_loc) in &errors {
                println!("  {} {}", inst_loc, sch_loc);
            }
            invalid_count += 1;
        }
    }

    println!("valid={} invalid={}", valid_count, invalid_count);
}

