function compareByCodePoint(a: string, b: string): number {
  const aChars = Array.from(a);
  const bChars = Array.from(b);
  const len = Math.min(aChars.length, bChars.length);
  for (let i = 0; i < len; i++) {
    const ca = aChars[i].codePointAt(0)!;
    const cb = bChars[i].codePointAt(0)!;
    if (ca !== cb) return ca - cb;
  }
  return aChars.length - bChars.length;
}

function isValidId(id: any): boolean {
  if (typeof id === 'string') return true;
  if (typeof id === 'number' && Number.isInteger(id)) return true;
  return false;
}

function processLine(line: string): string | null {
  if (line.trim() === '') return null;

  let msg: any;
  try {
    msg = JSON.parse(line);
  } catch {
    return JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } });
  }

  if (typeof msg !== 'object' || msg === null || Array.isArray(msg)) {
    return JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32600, message: "Invalid Request" } });
  }

  // Response from client: no method but has result or error → ignore
  if (!('method' in msg) && ('result' in msg || 'error' in msg)) {
    return null;
  }

  // Check invalid request conditions
  const jsonrpcOk = 'jsonrpc' in msg && msg.jsonrpc === "2.0";
  const methodOk = 'method' in msg && typeof msg.method === 'string';

  let idValid = true;
  let idValue: any = null;
  if ('id' in msg) {
    if (isValidId(msg.id)) {
      idValue = msg.id;
    } else {
      idValid = false;
    }
  }

  if (!jsonrpcOk || !methodOk || !idValid) {
    return JSON.stringify({ jsonrpc: "2.0", id: idValid ? idValue : null, error: { code: -32600, message: "Invalid Request" } });
  }

  // Notification: valid object without id → ignore
  if (!('id' in msg)) {
    return null;
  }

  // It's a request
  const id = idValue;
  const method = msg.method as string;

  // 6a: method not found
  const validMethods = ['initialize', 'ping', 'tools/list', 'tools/call'];
  if (!validMethods.includes(method)) {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32601, message: "Method not found" } });
  }

  // 6b: params present but not an object
  if ('params' in msg) {
    const p = msg.params;
    if (typeof p !== 'object' || p === null || Array.isArray(p)) {
      return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } });
    }
  }

  const params = 'params' in msg ? msg.params : undefined;

  // 6c: not initialized and method is not initialize or ping
  if (!initialized && method !== 'initialize' && method !== 'ping') {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32002, message: "Server not initialized" } });
  }

  // 6d: dispatch
  switch (method) {
    case 'initialize': return handleInitialize(id, params);
    case 'ping': return handlePing(id);
    case 'tools/list': return handleToolsList(id);
    case 'tools/call': return handleToolsCall(id, params);
  }

  return null;
}

function handleInitialize(id: any, params: any): string {
  if (initialized) {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32600, message: "Already initialized" } });
  }

  if (params === undefined || typeof params !== 'object' || params === null || Array.isArray(params)) {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } });
  }

  if (!('protocolVersion' in params) || typeof params.protocolVersion !== 'string') {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } });
  }

  const supportedVersions = ["2025-06-18", "2025-03-26", "2024-11-05"];
  const version = supportedVersions.includes(params.protocolVersion) ? params.protocolVersion : "2025-06-18";

  initialized = true;

  return JSON.stringify({
    jsonrpc: "2.0",
    id,
    result: {
      protocolVersion: version,
      capabilities: { tools: { listChanged: false } },
      serverInfo: { name: "cb2-kv", title: "CB2 key-value server", version: "1.4.2" }
    }
  });
}

function handlePing(id: any): string {
  return JSON.stringify({ jsonrpc: "2.0", id, result: {} });
}

function handleToolsList(id: any): string {
  return JSON.stringify({ jsonrpc: "2.0", id, result: { tools: toolDefs } });
}

function handleToolsCall(id: any, params: any): string {
  if (params === undefined || params === null || typeof params !== 'object' || Array.isArray(params)) {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } });
  }

  if (!('name' in params) || typeof params.name !== 'string') {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } });
  }

  const toolName = params.name;
  const toolDef = toolDefs.find(t => t.name === toolName);

  if (!toolDef) {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: `Unknown tool: ${toolName}` } });
  }

  let args: Record<string, any> = {};
  if ('arguments' in params) {
    const a = params.arguments;
    if (a === null || typeof a !== 'object' || Array.isArray(a)) {
      return JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: "arguments must be an object" }], isError: true } });
    }
    args = a;
  }

  const failure = validateArgs(args, toolDef.inputSchema);
  if (failure) {
    return JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: failure }], isError: true } });
  }

  return executeTool(id, toolDef.name, args);
}

function validateArgs(args: Record<string, any>, schema: any): string | null {
  const properties: Record<string, any> = schema.properties || {};
  const required: string[] = schema.required || [];
  const propNames = Object.keys(properties);

  // Check unknown arguments
  const unknownKeys = Object.keys(args).filter(k => !propNames.includes(k));
  if (unknownKeys.length > 0) {
    unknownKeys.sort(compareByCodePoint);
    return `unknown argument: ${unknownKeys[0]}`;
  }

  // Check each property in schema order
  for (const propName of propNames) {
    const propSchema = properties[propName];
    const isRequired = required.includes(propName);
    const isPresent = propName in args;

    if (!isPresent) {
      if (isRequired) {
        return `missing required argument: ${propName}`;
      }
      continue;
    }

    const value = args[propName];

    if (propSchema.type === 'string') {
      if (typeof value !== 'string') {
        return `argument ${propName} must be a string`;
      }
      if (propSchema.minLength === 1 && value.length === 0) {
        return `argument ${propName} must not be empty`;
      }
    } else if (propSchema.type === 'array') {
      if (!Array.isArray(value)) {
        return `argument ${propName} must be an array of integers`;
      }
      const itemSchema = propSchema.items;
      if (itemSchema && itemSchema.type === 'integer') {
        for (const elem of value) {
          if (typeof elem !== 'number' || !Number.isInteger(elem)) {
            return `argument ${propName} must be an array of integers`;
          }
        }
      }
      if (propSchema.minItems === 1 && value.length === 0) {
        return `argument ${propName} must not be empty`;
      }
    }
  }

  return null;
}

function executeTool(id: any, toolName: string, args: Record<string, any>): string {
  switch (toolName) {
    case 'kv_set': {
      const key = args.key as string;
      const value = args.value as string;
      const existed = store.has(key);
      store.set(key, value);
      const text = existed ? `updated ${key}` : `created ${key}`;
      return JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text }], isError: false } });
    }
    case 'kv_get': {
      const key = args.key as string;
      if (!store.has(key)) {
        return JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: `key not found: ${key}` }], isError: true } });
      }
      const value = store.get(key)!;
      return JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: value }], isError: false } });
    }
    case 'kv_list': {
      const prefix = (args.prefix as string) || "";
      let keys = Array.from(store.keys());
      if (prefix) {
        keys = keys.filter(k => k.startsWith(prefix));
      }
      keys.sort(compareByCodePoint);
      const structuredContent = { keys, count: keys.length };
      return JSON.stringify({
        jsonrpc: "2.0", id,
        result: {
          content: [{ type: "text", text: JSON.stringify(structuredContent) }],
          structuredContent,
          isError: false
        }
      });
    }
    case 'sum': {
      const numbers = args.numbers as number[];
      const total = numbers.reduce((acc, n) => acc + n, 0);
      const structuredContent = { sum: total, count: numbers.length };
      return JSON.stringify({
        jsonrpc: "2.0", id,
        result: {
          content: [{ type: "text", text: JSON.stringify(structuredContent) }],
          structuredContent,
          isError: false
        }
      });
    }
    case 'text_stats': {
      const text = args.text as string;
      let words = 0;
      let inWord = false;
      for (const ch of text) {
        if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
          inWord = false;
        } else {
          if (!inWord) words++;
          inWord = true;
        }
      }
      const codepoints = Array.from(text).length;
      const utf8Bytes = Buffer.byteLength(text, 'utf8');
      const structuredContent = { words, codepoints, utf8_bytes: utf8Bytes };
      return JSON.stringify({
        jsonrpc: "2.0", id,
        result: {
          content: [{ type: "text", text: JSON.stringify(structuredContent) }],
          structuredContent,
          isError: false
        }
      });
    }
  }
  return null;
}

const outputs: string[] = [];

rl.on('line', (line: string) => {
  const result = processLine(line);
  if (result !== null) {
    outputs.push(result);
  }
});

rl.on('close', () => {
  for (const line of outputs) {
    process.stdout.write(line + '\n');
  }
  process.exit(0);
});

import Foundation

// BigInt: arbitrary precision integer, decimal digits LSB first
struct BigInt {
    var neg: Bool
    var d: [Int] // digits 0-9, LSB first, empty = zero

    init() { neg = false; d = [] }
    init(_ n: Int) {
        if n == 0 { neg = false; d = [] }
        else { neg = n < 0; var v = abs(n); d = []; while v > 0 { d.append(v % 10); v /= 10 } }
    }
    init(fromString s: String) {
        var digits: [Int] = []
        for c in s.reversed() { if c.isNumber { digits.append(Int(c.asciiValue! - 48)) } }
        while digits.count > 1 && digits.last == 0 { digits.removeLast() }
        if digits.count == 1 && digits[0] == 0 { digits = [] }
        neg = false; d = digits
    }
    var isZero: Bool { d.isEmpty }
    var mag: BigInt { var r = self; r.neg = false; return r }
    func cmpMag(_ o: BigInt) -> Int {
        if d.count != o.d.count { return d.count < o.d.count ? -1 : 1 }
        for i in stride(from: d.count-1, through: 0, by: -1) {
            if d[i] != o.d[i] { return d[i] < o.d[i] ? -1 : 1 }
        }
        return 0
    }
}

func negB(_ b: BigInt) -> BigInt { var r = b; r.neg = !r.neg; if r.isZero { r.neg = false }; return r }

func addM(_ a: BigInt, _ b: BigInt) -> BigInt {
    let n = max(a.d.count, b.d.count)
    var r = [Int](repeating: 0, count: n+1); var c = 0
    for i in 0..<n { let s = (i < a.d.count ? a.d[i] : 0) + (i < b.d.count ? b.d[i] : 0) + c; r[i] = s % 10; c = s / 10 }
    r[n] = c
    while r.count > 1 && r.last == 0 { r.removeLast() }
    if r.count == 1 && r[0] == 0 { r = [] }
    var res = BigInt(); res.d = r; return res
}

func subM(_ a: BigInt, _ b: BigInt) -> BigInt {
    var r = [Int](repeating: 0, count: a.d.count); var br = 0
    for i in 0..<a.d.count { let s = a.d[i] - (i < b.d.count ? b.d[i] : 0) - br; if s < 0 { r[i] = s+10; br = 1 } else { r[i] = s; br = 0 } }
    while r.count > 1 && r.last == 0 { r.removeLast() }
    if r.count == 1 && r[0] == 0 { r = [] }
    var res = BigInt(); res.d = r; return res
}

func +(a: BigInt, b: BigInt) -> BigInt {
    if a.isZero { return b }; if b.isZero { return a }
    if a.neg == b.neg { var r = BigInt(); r.neg = a.neg; r.d = addM(a,b).d; return r }
    let c = a.cmpMag(b)
    if c == 0 { return BigInt() }
    if c > 0 { var r = BigInt(); r.neg = a.neg; r.d = subM(a,b).d; return r }
    var r = BigInt(); r.neg = b.neg; r.d = subM(b,a).d; return r
}
func -(a: BigInt, b: BigInt) -> BigInt { return a + negB(b) }

func *(a: BigInt, b: BigInt) -> BigInt {
    if a.isZero || b.isZero { return BigInt() }
    var r = [Int](repeating: 0, count: a.d.count + b.d.count)
    for i in 0..<a.d.count {
        var c = 0
        for j in 0..<b.d.count { let p = a.d[i] * b.d[j] + r[i+j] + c; r[i+j] = p % 10; c = p / 10 }
        var k = i + b.d.count
        while c > 0 { let s = r[k]+c; r[k] = s%10; c = s/10; k += 1 }
    }
    while r.count > 1 && r.last == 0 { r.removeLast() }
    if r.count == 1 && r[0] == 0 { r = [] }
    var res = BigInt(); res.neg = a.neg != b.neg; res.d = r
    if res.isZero { res.neg = false }
    return res
}

func cmpB(_ a: BigInt, _ b: BigInt) -> Int {
    if a.isZero && b.isZero { return 0 }
    if a.neg != b.neg { return a.neg ? -1 : 1 }
    let c = a.cmpMag(b); return a.neg ? -c : c
}
func <(a: BigInt, b: BigInt) -> Bool { cmpB(a,b) < 0 }
func <=(a: BigInt, b: BigInt) -> Bool { cmpB(a,b) <= 0 }
func >(a: BigInt, b: BigInt) -> Bool { cmpB(a,b) > 0 }
func >=(a: BigInt, b: BigInt) -> Bool { cmpB(a,b) >= 0 }
func ==(a: BigInt, b: BigInt) -> Bool { cmpB(a,b) == 0 }

func cmpD(_ a: [Int], _ b: [Int]) -> Int {
    if a.count != b.count { return a.count < b.count ? -1 : 1 }
    for i in 0..<a.count { if a[i] != b[i] { return a[i] < b[i] ? -1 : 1 } }
    return 0
}
func subD(_ a: [Int], _ b: [Int]) -> [Int] {
    var r = [Int](repeating: 0, count: a.count); var br = 0
    for i in stride(from: a.count-1, through: 0, by: -1) {
        let j = i - (a.count - b.count); let bv = j >= 0 ? b[j] : 0
        let s = a[i] - bv - br
        if s < 0 { r[i] = s+10; br = 1 } else { r[i] = s; br = 0 }
    }
    while r.count > 1 && r[0] == 0 { r.removeFirst() }
    if r.count == 1 && r[0] == 0 { r = [] }
    return r
}

func divModM(_ a: BigInt, _ b: BigInt) -> (BigInt, BigInt) {
    let c = a.cmpMag(b)
    if c < 0 { return (BigInt(), a) }
    if c == 0 { return (BigInt(1), BigInt()) }
    let ad = Array(a.d.reversed()); let bd = Array(b.d.reversed())
    var qd: [Int] = []; var cur: [Int] = []
    for i in 0..<ad.count {
        cur.append(ad[i])
        while cur.count > 1 && cur[0] == 0 { cur.removeFirst() }
        if cur.count == 1 && cur[0] == 0 { qd.append(0); continue }
        var cnt = 0
        while cmpD(cur, bd) >= 0 { cur = subD(cur, bd); cnt += 1 }
        qd.append(cnt)
    }
    while qd.count > 1 && qd[0] == 0 { qd.removeFirst() }
    if qd.count == 1 && qd[0] == 0 { qd = [] }
    while cur.count > 1 && cur[0] == 0 { cur.removeFirst() }
    if cur.count == 1 && cur[0] == 0 { cur = [] }
    var q = BigInt(); q.d = qd.reversed()
    var r = BigInt(); r.d = cur.reversed()
    return (q, r)
}

func pow10(_ n: Int) -> BigInt {
    var r = BigInt(); r.d = [1]
    for _ in 0..<n { r.d.append(0) }
    return r
}

// Decimal: value = v * 10^(-e)
struct Dec { var v: BigInt; var e: Int }

func decAlign(_ a: Dec, _ b: Dec) -> (BigInt, BigInt) {
    let me = max(a.e, b.e)
    var av = a.v; var bv = b.v
    if a.e < me { av = av * pow10(me - a.e) }
    if b.e < me { bv = bv * pow10(me - b.e) }
    return (av, bv)
}
func decAdd(_ a: Dec, _ b: Dec) -> Dec { let (av,bv) = decAlign(a,b); return Dec(v: av+bv, e: max(a.e,b.e)) }
func decSub(_ a: Dec, _ b: Dec) -> Dec { let (av,bv) = decAlign(a,b); return Dec(v: av-bv, e: max(a.e,b.e)) }
func decMul(_ a: Dec, _ b: Dec) -> Dec { return Dec(v: a.v*b.v, e: a.e+b.e) }

func roundD(_ a: Dec, to mu: Int) -> Dec {
    if a.e <= mu {
        var v = a.v; if a.e < mu { v = v * pow10(mu - a.e) }
        return Dec(v: v, e: mu)
    }
    let diff = a.e - mu
    let div = pow10(diff)
    let mag = a.v.mag
    let (q, r) = divModM(mag, div)
    let twoR = r + r
    let c = twoR.cmpMag(div)
    var m = q
    if c > 0 { m = addM(m, BigInt(1)) }
    else if c == 0 { let ld = q.isZero ? 0 : q.d[0]; if ld % 2 != 0 { m = addM(m, BigInt(1)) } }
    var res = m; res.neg = a.v.neg; if res.isZero { res.neg = false }
    return Dec(v: res, e: mu)
}

func parseDec(_ s: String) -> Dec {
    var n = false; var str = s
    if str.hasPrefix("-") { n = true; str = String(str.dropFirst()) }
    let parts = str.components(separatedBy: ".")
    let ip = parts[0]; let fp = parts.count > 1 ? parts[1] : ""
    let e = fp.count; let digits = ip + fp
    var bi = BigInt(fromString: digits); bi.neg = n; if bi.isZero { bi.neg = false }
    return Dec(v: bi, e: e)
}

func fmtMoney(_ v: BigInt, _ mu: Int) -> String {
    if v.isZero { return mu == 0 ? "0" : "0." + String(repeating: "0", count: mu) }
    let n = v.neg; let msb = Array(v.d.reversed()); let tot = msb.count
    var ip: String; var fp: String
    if tot > mu {
        let ic = tot - mu; ip = ""
        for i in 0..<ic { if i > 0 && (ic-i)%3 == 0 { ip += "," }; ip += String(msb[i]) }
        fp = ""; for i in ic..<tot { fp += String(msb[i]) }
    } else {
        ip = "0"; fp = String(repeating: "0", count: mu-tot)
        for i in 0..<tot { fp += String(msb[i]) }
    }
    let s = n ? "-" : ""
    return mu > 0 ? s+ip+"."+fp : s+ip
}

// Main
struct Acct { var cur: String; var bal: Dec; var lim: BigInt }

var curMap: [String:Int] = [:]
var accts: [String:Acct] = [:]
var rejects: [(Int,String)] = []

let dir = CommandLine.arguments[1]
let content = try! String(contentsOfFile: dir+"/ledger.txt", encoding: .utf8)
let lines = content.components(separatedBy: "\n")

outer: for (idx, line) in lines.enumerated() {
    let ln = idx+1
    let tr = line.trimmingCharacters(in: .whitespaces)
    if tr.isEmpty || tr.hasPrefix("#") { continue }
    var fs: [String] = []; var cur = ""
    for ch in tr { if ch == " "||ch == "\t" { if !cur.isEmpty { fs.append(cur); cur="" } } else { cur.append(ch) } }
    if !cur.isEmpty { fs.append(cur) }
    if fs.isEmpty { continue }
    let cmd = fs[0]

    switch cmd {
    case "currency":
        curMap[fs[1]] = Int(fs[2])!

    case "open":
        let name = fs[1]; let code = fs[2]
        if accts[name] != nil { rejects.append((ln,"account exists \(name)")); continue }
        let mu = curMap[code]!
        let ls = fs.count > 3 ? fs[3] : "0"
        var lim = roundD(parseDec(ls), to: mu).v
        if lim.neg { lim = negB(lim) }
        accts[name] = Acct(cur: code, bal: Dec(v:BigInt(),e:mu), lim: lim)

    case "deposit":
        let name = fs[1]
        if accts[name] == nil { rejects.append((ln,"unknown account \(name)")); continue }
        let mu = curMap[accts[name]!.cur]!
        let amt = roundD(parseDec(fs[2]), to: mu)
        if amt.v <= BigInt() { rejects.append((ln,"non-positive amount")); continue }
        accts[name]!.bal = decAdd(accts[name]!.bal, amt)

    case "withdraw":
        let name = fs[1]
        if accts[name] == nil { rejects.append((ln,"unknown account \(name)")); continue }
        let acc = accts[name]!
        let mu = curMap[acc.cur]!
        let amt = roundD(parseDec(fs[2]), to: mu)
        if amt.v <= BigInt() { rejects.append((ln,"non-positive amount")); continue }
        let nb = decSub(acc.bal, amt)
        if nb.v < negB(acc.lim) { rejects.append((ln,"insufficient funds \(name)")); continue }
        accts[name]!.bal = nb

    case "transfer":
        let f = fs[1]; let t = fs[2]
        if accts[f] == nil { rejects.append((ln,"unknown account \(f)")); continue }
        if accts[t] == nil { rejects.append((ln,"unknown account \(t)")); continue }
        let fa = accts[f]!; let ta = accts[t]!
        if fa.cur != ta.cur { rejects.append((ln,"currency mismatch")); continue }
        let mu = curMap[fa.cur]!
        let amt = roundD(parseDec(fs[3]), to: mu)
        if amt.v <= BigInt() { rejects.append((ln,"non-positive amount")); continue }
        let nb = decSub(fa.bal, amt)
        if nb.v < negB(fa.lim) { rejects.append((ln,"insufficient funds \(f)")); continue }
        accts[f]!.bal = nb; accts[t]!.bal = decAdd(ta.bal, amt)

    case "convert":
        let f = fs[1]; let t = fs[2]
        if accts[f] == nil { rejects.append((ln,"unknown account \(f)")); continue }
        if accts[t] == nil { rejects.append((ln,"unknown account \(t)")); continue }
        let fa = accts[f]!; let ta = accts[t]!
        let fmu = curMap[fa.cur]!; let tmu = curMap[ta.cur]!
        let amt = roundD(parseDec(fs[3]), to: fmu)
        if amt.v <= BigInt() { rejects.append((ln,"non-positive amount")); continue }
        let nb = decSub(fa.bal, amt)
        if nb.v < negB(fa.lim) { rejects.append((ln,"insufficient funds \(f)")); continue }
        let rate = parseDec(fs[4])
        let conv = roundD(decMul(amt, rate), to: tmu)
        accts[f]!.bal = nb; accts[t]!.bal = decAdd(ta.bal, conv)

    case "interest":
        let name = fs[1]
        if accts[name] == nil { rejects.append((ln,"unknown account \(name)")); continue }
        let acc = accts[name]!
        let mu = curMap[acc.cur]!
        let rate = parseDec(fs[2])
        let intAmt = roundD(decMul(acc.bal, rate), to: mu)
        accts[name]!.bal = decAdd(acc.bal, intAmt)

    case "split":
        let f = fs[1]
        if accts[f] == nil { rejects.append((ln,"unknown account \(f)")); continue }
        var tNames: [String] = []; var tWeights: [BigInt] = []
        for i in 3..<fs.count {
            let parts = fs[i].components(separatedBy: ":")
            tNames.append(parts[0])
            tWeights.append(BigInt(fromString: parts[1]))
        }
        // Check unknown accounts in order
        for tn in tNames {
            if accts[tn] == nil { rejects.append((ln,"unknown account \(tn)")); continue outer }
        }
        let fa = accts[f]!
        // Currency mismatch
        for tn in tNames {
            if accts[tn]!.cur != fa.cur { rejects.append((ln,"currency mismatch")); continue outer }
        }
        let mu = curMap[fa.cur]!
        let amt = roundD(parseDec(fs[2]), to: mu)
        if amt.v <= BigInt() { rejects.append((ln,"non-positive amount")); continue }
        let nb = decSub(fa.bal, amt)
        if nb.v < negB(fa.lim) { rejects.append((ln,"insufficient funds \(f)")); continue }

        let A = amt.v
        var W = BigInt()
        for w in tWeights { W = W + w }

        var bases: [BigInt] = []
        var rems: [BigInt] = []
        for w in tWeights {
            let prod = A * w
            let (q, r) = divModM(prod, W)
            bases.append(q); rems.append(r)
        }

        var sumBase = BigInt()
        for b in bases { sumBase = sumBase + b }
        let L = A - sumBase

        var lVal = 0
        if !L.isZero { var mult = 1; for dd in L.d { lVal += dd * mult; mult *= 10 } }

        var indices = Array(0..<tNames.count)
        indices.sort { i, j in
            let c = rems[i].cmpMag(rems[j])
            if c != 0 { return c > 0 }
            return i < j
        }

        accts[f]!.bal = nb
        for k in 0..<tNames.count {
            let ti = indices[k]
            var extra = BigInt()
            if k < lVal { extra = BigInt(1) }
            accts[tNames[ti]]!.bal = decAdd(accts[tNames[ti]]!.bal, Dec(v: bases[ti] + extra, e: mu))
        }

    default:
        break
    }
}

// Output
var out = ""
for (ln, reason) in rejects {
    out += "line \(ln): REJECT \(reason)\n"
}
out += "\n"

let sortedNames = accts.keys.sorted()
for name in sortedNames {
    let acc = accts[name]!
    let mu = curMap[acc.cur]!
    out += "\(name) \(acc.cur) \(fmtMoney(acc.bal.v, mu))\n"
}
out += "\n"

var curTotals: [String: (BigInt, Int)] = [:]
for name in sortedNames {
    let acc = accts[name]!
    let cur = acc.cur
    if curTotals[cur] == nil { curTotals[cur] = (BigInt(), 0) }
    curTotals[cur]!.0 = curTotals[cur]!.0 + acc.bal.v
    curTotals[cur]!.1 += 1
}
let sortedCurs = curTotals.keys.sorted()
for cur in sortedCurs {
    let (total, count) = curTotals[cur]!
    let mu = curMap[cur]!
    out += "total \(cur) \(fmtMoney(total, mu)) (\(count) accounts)\n"
}

print(out, terminator: "")

import Foundation

// Big integer: magnitude as [Int] decimal digits LSB first, plus sign.
// Zero = empty digits, neg=false.

struct BI {
    var neg: Bool
    var d: [Int] // LSB first, normalized (no trailing zeros)
    init() { neg = false; d = [] }
}

func mkBI(_ neg: Bool, _ d: [Int]) -> BI {
    var dd = d
    while !dd.isEmpty && dd.last! == 0 { dd.removeLast() }
    var r = BI()
    r.d = dd
    r.neg = dd.isEmpty ? false : neg
    return r
}

func biFromInt(_ n: Int) -> BI {
    if n == 0 { return BI() }
    var b = BI()
    b.neg = n < 0
    var v = n < 0 ? -n : n
    while v > 0 { b.d.append(v % 10); v /= 10 }
    return b
}

func biFromStr(_ s: String, _ neg: Bool) -> BI {
    var d: [Int] = []
    for ch in s.reversed() { d.append(Int(ch.asciiValue! - 48)) }
    return mkBI(neg, d)
}

func cmpMag(_ a: BI, _ b: BI) -> Int {
    if a.d.count != b.d.count { return a.d.count < b.d.count ? -1 : 1 }
    for i in stride(from: a.d.count - 1, through: 0, by: -1) {
        if a.d[i] != b.d[i] { return a.d[i] < b.d[i] ? -1 : 1 }
    }
    return 0
}

func addM(_ a: BI, _ b: BI) -> BI {
    let n = max(a.d.count, b.d.count)
    var d = [Int](repeating: 0, count: n + 1)
    var c = 0
    for i in 0..<n {
        let av = i < a.d.count ? a.d[i] : 0
        let bv = i < b.d.count ? b.d[i] : 0
        let s = av + bv + c
        d[i] = s % 10; c = s / 10
    }
    d[n] = c
    return mkBI(false, d)
}

func subM(_ a: BI, _ b: BI) -> BI {
    // requires |a| >= |b|
    var d = [Int](repeating: 0, count: a.d.count)
    var br = 0
    for i in 0..<a.d.count {
        let bv = i < b.d.count ? b.d[i] : 0
        let s = a.d[i] - bv - br
        if s < 0 { d[i] = s + 10; br = 1 } else { d[i] = s; br = 0 }
    }
    return mkBI(false, d)
}

func mulM(_ a: BI, _ b: BI) -> BI {
    if a.d.isEmpty || b.d.isEmpty { return BI() }
    var d = [Int](repeating: 0, count: a.d.count + b.d.count)
    for i in 0..<a.d.count {
        var c = 0
        for j in 0..<b.d.count {
            let p = a.d[i] * b.d[j] + d[i+j] + c
            d[i+j] = p % 10; c = p / 10
        }
        var k = i + b.d.count
        while c > 0 { let s = d[k] + c; d[k] = s % 10; c = s / 10; k += 1 }
    }
    return mkBI(false, d)
}

func negBI(_ a: BI) -> BI {
    var r = a; r.neg.toggle(); if r.d.isEmpty { r.neg = false }; return r
}

func biAdd(_ a: BI, _ b: BI) -> BI {
    if a.d.isEmpty { return b }
    if b.d.isEmpty { return a }
    if a.neg == b.neg {
        var r = addM(a, b); r.neg = a.neg; return r
    }
    let c = cmpMag(a, b)
    if c == 0 { return BI() }
    if c > 0 { var r = subM(a, b); r.neg = a.neg; return r }
    var r = subM(b, a); r.neg = b.neg; return r
}

func biSub(_ a: BI, _ b: BI) -> BI { return biAdd(a, negBI(b)) }

func biMul(_ a: BI, _ b: BI) -> BI {
    var r = mulM(a, b)
    if !r.d.isEmpty { r.neg = a.neg != b.neg }
    return r
}

func biCmp(_ a: BI, _ b: BI) -> Int {
    if a.d.isEmpty && b.d.isEmpty { return 0 }
    if a.neg != b.neg { return a.neg ? -1 : 1 }
    let c = cmpMag(a, b)
    return a.neg ? -c : c
}

func pow10(_ n: Int) -> BI {
    var b = BI(); b.d = [1]
    for _ in 0..<n { b.d.append(0) }
    return b
}

// MSB-first digit array helpers for long division
func cmpDigits(_ a: [Int], _ b: [Int]) -> Int {
    if a.count != b.count { return a.count < b.count ? -1 : 1 }
    for i in 0..<a.count { if a[i] != b[i] { return a[i] < b[i] ? -1 : 1 } }
    return 0
}

func subDigits(_ a: [Int], _ b: [Int]) -> [Int] {
    // a >= b, both MSB-first, a.count >= b.count
    var r = [Int](repeating: 0, count: a.count)
    var br = 0
    for i in stride(from: a.count - 1, through: 0, by: -1) {
        let j = i - (a.count - b.count)
        let bv = j >= 0 ? b[j] : 0
        let s = a[i] - bv - br
        if s < 0 { r[i] = s + 10; br = 1 } else { r[i] = s; br = 0 }
    }
    while r.count > 1 && r[0] == 0 { r.removeFirst() }
    if r.count == 1 && r[0] == 0 { r = [] }
    return r
}

func divModMag(_ a: BI, _ b: BI) -> (BI, BI) {
    let c = cmpMag(a, b)
    if c < 0 { return (BI(), a) }
    if c == 0 { return (biFromInt(1), BI()) }
    let ad = Array(a.d.reversed()) // MSB first
    let bd = Array(b.d.reversed()) // MSB first
    var qd: [Int] = []
    var cur: [Int] = []
    for i in 0..<ad.count {
        cur.append(ad[i])
        while cur.count > 1 && cur[0] == 0 { cur.removeFirst() }
        if cur.isEmpty || (cur.count == 1 && cur[0] == 0) { qd.append(0); continue }
        var cnt = 0
        while cmpDigits(cur, bd) >= 0 { cur = subDigits(cur, bd); cnt += 1 }
        qd.append(cnt)
    }
    while qd.count > 1 && qd[0] == 0 { qd.removeFirst() }
    if qd.count == 1 && qd[0] == 0 { qd = [] }
    while cur.count > 1 && cur[0] == 0 { cur.removeFirst() }
    if cur.count == 1 && cur[0] == 0 { cur = [] }
    var q = BI(); q.d = qd.reversed()
    var r = BI(); r.d = cur.reversed()
    return (q, r)
}

// Decimal: value = v * 10^(-e)
struct Dec { var v: BI; var e: Int }

func decAlign(_ a: Dec, _ b: Dec) -> (BI, BI) {
    let me = max(a.e, b.e)
    var av = a.v; var bv = b.v
    if a.e < me { av = biMul(av, pow10(me - a.e)) }
    if b.e < me { bv = biMul(bv, pow10(me - b.e)) }
    return (av, bv)
}

func decAdd(_ a: Dec, _ b: Dec) -> Dec {
    let (av, bv) = decAlign(a, b)
    return Dec(v: biAdd(av, bv), e: max(a.e, b.e))
}

func decSub(_ a: Dec, _ b: Dec) -> Dec {
    let (av, bv) = decAlign(a, b)
    return Dec(v: biSub(av, bv), e: max(a.e, b.e))
}

func decMul(_ a: Dec, _ b: Dec) -> Dec {
    return Dec(v: biMul(a.v, b.v), e: a.e + b.e)
}

func roundD(_ a: Dec, to mu: Int) -> Dec {
    if a.e <= mu {
        var v = a.v
        if a.e < mu { v = biMul(v, pow10(mu - a.e)) }
        return Dec(v: v, e: mu)
    }
    let diff = a.e - mu
    let div = pow10(diff)
    let mag = BI(); var mag2 = a.v; mag2.neg = false
    let (q, r) = divModMag(mag2, div)
    let twoR = biAdd(r, r)
    let c = cmpMag(twoR, div)
    var m = q
    if c > 0 { m = addM(m, biFromInt(1)) }
    else if c == 0 {
        let ld = q.d.isEmpty ? 0 : q.d[0]
        if ld % 2 != 0 { m = addM(m, biFromInt(1)) }
    }
    var res = m; res.neg = a.v.neg
    if res.d.isEmpty { res.neg = false }
    return Dec(v: res, e: mu)
}

func parseDec(_ s: String) -> Dec {
    var n = false; var str = s
    if str.hasPrefix("-") { n = true; str = String(str.dropFirst()) }
    let dotIdx = str.firstIndex(of: ".")
    let ip: String; let fp: String
    if let di = dotIdx {
        ip = String(str[str.startIndex..<di])
        fp = String(str[str.index(after: di)...])
    } else {
        ip = str; fp = ""
    }
    let e = fp.count
    let digits = ip + fp
    var bi = biFromStr(digits, n)
    return Dec(v: bi, e: e)
}

func fmtMoney(_ v: BI, _ mu: Int) -> String {
    if v.d.isEmpty {
        return mu == 0 ? "0" : "0." + String(repeating: "0", count: mu)
    }
    let n = v.neg
    let msb = Array(v.d.reversed())
    let tot = msb.count
    var ip: String; var fp: String
    if tot > mu {
        let ic = tot - mu
        ip = ""
        for i in 0..<ic {
            if i > 0 && (ic - i) % 3 == 0 { ip += "," }
            ip += String(msb[i])
        }
        fp = ""
        for i in ic..<tot { fp += String(msb[i]) }
    } else {
        ip = "0"
        fp = String(repeating: "0", count: mu - tot)
        for i in 0..<tot { fp += String(msb[i]) }
    }
    let s = n ? "-" : ""
    return mu > 0 ? s + ip + "." + fp : s + ip
}

// Main
struct Acct { var cur: String; var bal: Dec; var lim: BI }

var curMap: [String: Int] = [:]
var accts: [String: Acct] = [:]
var rejects: [(Int, String)] = []

let dir = CommandLine.arguments[1]
let content = try! String(contentsOfFile: dir + "/ledger.txt", encoding: .utf8)
var lines = content.components(separatedBy: "\n")
// Remove trailing empty line if file ends with newline
if !lines.isEmpty && lines.last!.isEmpty { lines.removeLast() }

outer: for (idx, line) in lines.enumerated() {
    let ln = idx + 1
    var tr = line
    if tr.hasSuffix("\r") { tr = String(tr.dropLast()) }
    tr = tr.trimmingCharacters(in: .whitespaces)
    if tr.isEmpty || tr.hasPrefix("#") { continue }
    var fs: [String] = []
    var cur = ""
    for ch in tr {
        if ch == " " || ch == "\t" {
            if !cur.isEmpty { fs.append(cur); cur = "" }
        } else { cur.append(ch) }
    }
    if !cur.isEmpty { fs.append(cur) }
    if fs.isEmpty { continue }
    let cmd = fs[0]

    switch cmd {
    case "currency":
        curMap[fs[1]] = Int(fs[2])!

    case "open":
        let name = fs[1]; let code = fs[2]
        if accts[name] != nil { rejects.append((ln, "account exists \(name)")); continue }
        let mu = curMap[code]!
        let ls = fs.count > 3 ? fs[3] : "0"
        var lim = roundD(parseDec(ls), to: mu).v
        if lim.neg { lim = negBI(lim) }
        accts[name] = Acct(cur: code, bal: Dec(v: BI(), e: mu), lim: lim)

    case "deposit":
        let name = fs[1]
        if accts[name] == nil { rejects.append((ln, "unknown account \(name)")); continue }
        let mu = curMap[accts[name]!.cur]!
        let amt = roundD(parseDec(fs[2]), to: mu)
        if amt.v.d.isEmpty || amt.v.neg { rejects.append((ln, "non-positive amount")); continue }
        accts[name]!.bal = decAdd(accts[name]!.bal, amt)

    case "withdraw":
        let name = fs[1]
        if accts[name] == nil { rejects.append((ln, "unknown account \(name)")); continue }
        let acc = accts[name]!
        let mu = curMap[acc.cur]!
        let amt = roundD(parseDec(fs[2]), to: mu)
        if amt.v.d.isEmpty || amt.v.neg { rejects.append((ln, "non-positive amount")); continue }
        let nb = decSub(acc.bal, amt)
        let negLim = negBI(acc.lim)
        if biCmp(nb.v, negLim) < 0 { rejects.append((ln, "insufficient funds \(name)")); continue }
        accts[name]!.bal = nb

    case "transfer":
        let f = fs[1]; let t = fs[2]
        if accts[f] == nil { rejects.append((ln, "unknown account \(f)")); continue }
        if accts[t] == nil { rejects.append((ln, "unknown account \(t)")); continue }
        let fa = accts[f]!; let ta = accts[t]!
        if fa.cur != ta.cur { rejects.append((ln, "currency mismatch")); continue }
        let mu = curMap[fa.cur]!
        let amt = roundD(parseDec(fs[3]), to: mu)
        if amt.v.d.isEmpty || amt.v.neg { rejects.append((ln, "non-positive amount")); continue }
        let nb = decSub(fa.bal, amt)
        let negLim = negBI(fa.lim)
        if biCmp(nb.v, negLim) < 0 { rejects.append((ln, "insufficient funds \(f)")); continue }
        accts[f]!.bal = nb
        accts[t]!.bal = decAdd(ta.bal, amt)

    case "convert":
        let f = fs[1]; let t = fs[2]
        if accts[f] == nil { rejects.append((ln, "unknown account \(f)")); continue }
        if accts[t] == nil { rejects.append((ln, "unknown account \(t)")); continue }
        let fa = accts[f]!; let ta = accts[t]!
        let fmu = curMap[fa.cur]!; let tmu = curMap[ta.cur]!
        let amt = roundD(parseDec(fs[3]), to: fmu)
        if amt.v.d.isEmpty || amt.v.neg { rejects.append((ln, "non-positive amount")); continue }
        let nb = decSub(fa.bal, amt)
        let negLim = negBI(fa.lim)
        if biCmp(nb.v, negLim) < 0 { rejects.append((ln, "insufficient funds \(f)")); continue }
        let rate = parseDec(fs[4])
        let conv = roundD(decMul(amt, rate), to: tmu)
        accts[f]!.bal = nb
        accts[t]!.bal = decAdd(ta.bal, conv)

    case "interest":
        let name = fs[1]
        if accts[name] == nil { rejects.append((ln, "unknown account \(name)")); continue }
        let acc = accts[name]!
        let mu = curMap[acc.cur]!
        let rate = parseDec(fs[2])
        let intAmt = roundD(decMul(acc.bal, rate), to: mu)
        accts[name]!.bal = decAdd(acc.bal, intAmt)

    case "split":
        let f = fs[1]
        if accts[f] == nil { rejects.append((ln, "unknown account \(f)")); continue }
        var tNames: [String] = []
        var tWeights: [BI] = []
        for i in 3..<fs.count {
            let colonPos = fs[i].firstIndex(of: ":")!
            let tn = String(fs[i][fs[i].startIndex..<colonPos])
            let ws = String(fs[i][fs[i].index(after: colonPos)...])
            tNames.append(tn)
            tWeights.append(biFromStr(ws, false))
        }
        for tn in tNames {
            if accts[tn] == nil { rejects.append((ln, "unknown account \(tn)")); continue outer }
        }
        let fa = accts[f]!
        for tn in tNames {
            if accts[tn]!.cur != fa.cur { rejects.append((ln, "currency mismatch")); continue outer }
        }
        let mu = curMap[fa.cur]!
        let amt = roundD(parseDec(fs[2]), to: mu)
        if amt.v.d.isEmpty || amt.v.neg { rejects.append((ln, "non-positive amount")); continue }
        let nb = decSub(fa.bal, amt)
        let negLim = negBI(fa.lim)
        if biCmp(nb.v, negLim) < 0 { rejects.append((ln, "insufficient funds \(f)")); continue }

        let A = amt.v
        var W = BI()
        for w in tWeights { W = biAdd(W, w) }

        var bases: [BI] = []
        var rems: [BI] = []
        for w in tWeights {
            let prod = biMul(A, w)
            let (q, r) = divModMag(prod, W)
            bases.append(q); rems.append(r)
        }

        var sumBase = BI()
        for b in bases { sumBase = biAdd(sumBase, b) }
        let L = biSub(A, sumBase)

        var lVal = 0
        if !L.d.isEmpty {
            var mult = 1
            for dd in L.d { lVal += dd * mult; mult *= 10 }
        }

        var indices = Array(0..<tNames.count)
        indices.sort { i, j in
            let c = cmpMag(rems[i], rems[j])
            if c != 0 { return c > 0 }
            return i < j
        }

        accts[f]!.bal = nb
        for k in 0..<tNames.count {
            let ti = indices[k]
            var extra = BI()
            if k < lVal { extra = biFromInt(1) }
            accts[tNames[ti]]!.bal = decAdd(accts[tNames[ti]]!.bal, Dec(v: biAdd(bases[ti], extra), e: mu))
        }

    default:
        break
    }
}

// Output
var out = ""
for (ln, reason) in rejects {
    out += "line \(ln): REJECT \(reason)\n"
}
out += "\n"

let sortedNames = accts.keys.sorted()
for name in sortedNames {
    let acc = accts[name]!
    let mu = curMap[acc.cur]!
    out += "\(name) \(acc.cur) \(fmtMoney(acc.bal.v, mu))\n"
}
out += "\n"

var curTotals: [String: (BI, Int)] = [:]
for name in sortedNames {
    let acc = accts[name]!
    let cur = acc.cur
    if curTotals[cur] == nil { curTotals[cur] = (BI(), 0) }
    curTotals[cur]!.0 = biAdd(curTotals[cur]!.0, acc.bal.v)
    curTotals[cur]!.1 += 1
}
let sortedCurs = curTotals.keys.sorted()
for cur in sortedCurs {
    let (total, count) = curTotals[cur]!
    let mu = curMap[cur]!
    out += "total \(cur) \(fmtMoney(total, mu)) (\(count) accounts)\n"
}

print(out, terminator: "")

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {

    static class ParseException extends Exception {}

    static class JsonNum {
        boolean isInt;
        long longVal;
        double dblVal;
        JsonNum(boolean isInt, long longVal, double dblVal) {
            this.isInt = isInt; this.longVal = longVal; this.dblVal = dblVal;
        }
    }

    static class Parser {
        String s; int pos;
        Parser(String s) { this.s = s; this.pos = 0; }

        Object parse() throws ParseException {
            skipWs();
            Object v = parseValue();
            skipWs();
            if (pos != s.length()) throw new ParseException();
            return v;
        }

        void skipWs() {
            while (pos < s.length()) {
                char c = s.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\r' || c == '\n') pos++;
                else break;
            }
        }

        Object parseValue() throws ParseException {
            if (pos >= s.length()) throw new ParseException();
            char c = s.charAt(pos);
            if (c == '{') return parseObj();
            if (c == '[') return parseArr();
            if (c == '"') return parseStr();
            if (c == 't') { expect("true"); return Boolean.TRUE; }
            if (c == 'f') { expect("false"); return Boolean.FALSE; }
            if (c == 'n') { expect("null"); return null; }
            if (c == '-' || (c >= '0' && c <= '9')) return parseNum();
            throw new ParseException();
        }

        void expect(String lit) throws ParseException {
            if (!s.startsWith(lit, pos)) throw new ParseException();
            pos += lit.length();
        }

        @SuppressWarnings("unchecked")
        Map<String, Object> parseObj() throws ParseException {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++;
            skipWs();
            if (pos < s.length() && s.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                skipWs();
                if (pos >= s.length() || s.charAt(pos) != '"') throw new ParseException();
                String key = parseStr();
                skipWs();
                if (pos >= s.length() || s.charAt(pos) != ':') throw new ParseException();
                pos++;
                skipWs();
                Object val = parseValue();
                map.put(key, val);
                skipWs();
                if (pos >= s.length()) throw new ParseException();
                char c = s.charAt(pos);
                if (c == '}') { pos++; return map; }
                if (c == ',') { pos++; continue; }
                throw new ParseException();
            }
        }

        List<Object> parseArr() throws ParseException {
            List<Object> list = new ArrayList<>();
            pos++;
            skipWs();
            if (pos < s.length() && s.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                skipWs();
                Object val = parseValue();
                list.add(val);
                skipWs();
                if (pos >= s.length()) throw new ParseException();
                char c = s.charAt(pos);
                if (c == ']') { pos++; return list; }
                if (c == ',') { pos++; continue; }
                throw new ParseException();
            }
        }

        String parseStr() throws ParseException {
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < s.length()) {
                char c = s.charAt(pos);
                if (c == '"') { pos++; return sb.toString(); }
                if (c == '\\') {
                    pos++;
                    if (pos >= s.length()) throw new ParseException();
                    char e = s.charAt(pos); pos++;
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if (pos + 4 > s.length()) throw new ParseException();
                            String hex = s.substring(pos, pos + 4);
                            try { sb.append((char) Integer.parseInt(hex, 16)); }
                            catch (NumberFormatException ex) { throw new ParseException(); }
                            pos += 4;
                            break;
                        default: throw new ParseException();
                    }
                } else if (c < 0x20) {
                    throw new ParseException();
                } else {
                    sb.append(c); pos++;
                }
            }
            throw new ParseException();
        }

        JsonNum parseNum() throws ParseException {
            int start = pos;
            if (pos < s.length() && s.charAt(pos) == '-') pos++;
            if (pos >= s.length()) throw new ParseException();
            char c = s.charAt(pos);
            if (c == '0') { pos++; }
            else if (c >= '1' && c <= '9') { while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++; }
            else throw new ParseException();
            boolean hasFrac = false, hasExp = false;
            if (pos < s.length() && s.charAt(pos) == '.') {
                hasFrac = true; pos++;
                if (pos >= s.length() || s.charAt(pos) < '0' || s.charAt(pos) > '9') throw new ParseException();
                while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++;
            }
            if (pos < s.length() && (s.charAt(pos) == 'e' || s.charAt(pos) == 'E')) {
                hasExp = true; pos++;
                if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-')) pos++;
                if (pos >= s.length() || s.charAt(pos) < '0' || s.charAt(pos) > '9') throw new ParseException();
                while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++;
            }
            String numStr = s.substring(start, pos);
            boolean isInt = !hasFrac && !hasExp;
            long lv = 0; double dv = 0;
            if (isInt) { lv = Long.parseLong(numStr); dv = (double) lv; }
            else { dv = Double.parseDouble(numStr); lv = (long) dv; }
            return new JsonNum(isInt, lv, dv);
        }
    }

    @SuppressWarnings("unchecked")
    static String toJson(Object val) {
        if (val == null) return "null";
        if (val instanceof Boolean) return val.toString();
        if (val instanceof JsonNum) {
            JsonNum n = (JsonNum) val;
            if (n.isInt) return Long.toString(n.longVal);
            double d = n.dblVal;
            if (d == Math.floor(d) && !Double.isInfinite(d) && Math.abs(d) < 9e15)
                return Long.toString((long) d);
            return Double.toString(d);
        }
        if (val instanceof String) return escStr((String) val);
        if (val instanceof Map) {
            Map<String, Object> m = (Map<String, Object>) val;
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, Object> e : m.entrySet()) {
                if (!first) sb.append(",");
                sb.append(escStr(e.getKey())).append(":").append(toJson(e.getValue()));
                first = false;
            }
            return sb.append("}").toString();
        }
        if (val instanceof List) {
            List<Object> l = (List<Object>) val;
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            for (Object item : l) { if (!first) sb.append(","); sb.append(toJson(item)); first = false; }
            return sb.append("]").toString();
        }
        return "null";
    }

    static String escStr(String s) {
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        return sb.append("\"").toString();
    }

    // Tool definitions
    static class PropDef {
        String name, type; int minLength, minItems;
        PropDef(String n, String t, int ml, int mi) { name=n; type=t; minLength=ml; minItems=mi; }
    }
    static class ToolDef {
        String name, title, desc; List<PropDef> props; Set<String> required; boolean hasOutputSchema;
        ToolDef(String n, String t, String d, List<PropDef> p, Set<String> r, boolean os) {
            name=n; title=t; desc=d; props=p; required=r; hasOutputSchema=os;
        }
    }

