    @SuppressWarnings("unchecked")
    static String handleToolsCall(Object id, Map<String,Object> params) {
        if (params == null || !params.containsKey("name") || !(params.get("name") instanceof String))
            return makeError(id,-32602,"Invalid params");
        String toolName = (String) params.get("name");
        ToolDef tool = null;
        for (ToolDef t : tools) if (t.name.equals(toolName)) { tool = t; break; }
        if (tool == null) return makeError(id,-32602,"Unknown tool: "+toolName);

        Map<String,Object> arguments;
        if (!params.containsKey("arguments")) {
            arguments = new LinkedHashMap<>();
        } else {
            Object ao = params.get("arguments");
            if (ao == null || !(ao instanceof Map)) return toolFail(id,"arguments must be an object");
            arguments = (Map<String,Object>) ao;
        }

        Set<String> known = new HashSet<>();
        for (PropDef p : tool.props) known.add(p.name);
        String unknownArg = null;
        for (String k : arguments.keySet()) {
            if (!known.contains(k)) {
                if (unknownArg == null || cmpCP(k, unknownArg) < 0) unknownArg = k;
            }
        }
        if (unknownArg != null) return toolFail(id,"unknown argument: "+unknownArg);

        for (PropDef p : tool.props) {
            boolean present = arguments.containsKey(p.name);
            Object val = present ? arguments.get(p.name) : null;
            if (!present) {
                if (tool.required.contains(p.name)) return toolFail(id,"missing required argument: "+p.name);
                continue;
            }
            if (p.type.equals("string")) {
                if (!(val instanceof String)) return toolFail(id,"argument "+p.name+" must be a string");
                if (p.minLength > 0 && ((String)val).codePointCount(0,((String)val).length()) < p.minLength)
                    return toolFail(id,"argument "+p.name+" must not be empty");
            } else if (p.type.equals("array")) {
                if (!(val instanceof List)) return toolFail(id,"argument "+p.name+" must be an array of integers");
                List<Object> arr = (List<Object>) val;
                if (p.minItems > 0 && arr.size() < p.minItems)
                    return toolFail(id,"argument "+p.name+" must not be empty");
                for (Object el : arr) {
                    if (!(el instanceof JsonNum) || !((JsonNum)el).isInt)
                        return toolFail(id,"argument "+p.name+" must be an array of integers");
                }
            }
        }

        return execTool(id, tool, arguments);
    }

    @SuppressWarnings("unchecked")
    static String execTool(Object id, ToolDef tool, Map<String,Object> args) {
        switch (tool.name) {
            case "kv_set": {
                String k = (String) args.get("key"), v = (String) args.get("value");
                boolean ex = kvStore.containsKey(k); kvStore.put(k,v);
                return toolOk(id,(ex?"updated ":"created ")+k);
            }
            case "kv_get": {
                String k = (String) args.get("key");
                if (!kvStore.containsKey(k)) return toolFail(id,"key not found: "+k);
                return toolOk(id,kvStore.get(k));
            }
            case "kv_list": {
                String prefix = args.containsKey("prefix") ? (String)args.get("prefix") : "";
                List<String> keys = new ArrayList<>();
                for (String k : kvStore.keySet()) if (k.startsWith(prefix)) keys.add(k);
                keys.sort(Main::cmpCP);
                Map<String,Object> sc = new LinkedHashMap<>();
                sc.put("keys", new ArrayList<Object>(keys));
                sc.put("count", new JsonNum(true, keys.size(), keys.size()));
                return toolOkStruct(id, sc);
            }
            case "sum": {
                List<Object> nums = (List<Object>) args.get("numbers");
                long s = 0; for (Object n : nums) s += ((JsonNum)n).longVal;
                Map<String,Object> sc = new LinkedHashMap<>();
                sc.put("sum", new JsonNum(true,s,s));
                sc.put("count", new JsonNum(true,nums.size(),nums.size()));
                return toolOkStruct(id, sc);
            }
            case "text_stats": {
                String text = (String) args.get("text");
                int w = countWords(text);
                int cp = text.codePointCount(0, text.length());
                int ub = text.getBytes(StandardCharsets.UTF_8).length;
                Map<String,Object> sc = new LinkedHashMap<>();
                sc.put("words", new JsonNum(true,w,w));
                sc.put("codepoints", new JsonNum(true,cp,cp));
                sc.put("utf8_bytes", new JsonNum(true,ub,ub));
                return toolOkStruct(id, sc);
            }
        }
        return toolFail(id,"internal error");
    }

    static int countWords(String text) {
        int w = 0; boolean inW = false;
        int i = 0;
        while (i < text.length()) {
            int cp = text.codePointAt(i);
            if (cp==0x20||cp==0x09||cp==0x0A||cp==0x0D) inW=false;
            else { if(!inW) w++; inW=true; }
            i += Character.charCount(cp);
        }
        return w;
    }

    static String toolOk(Object id, String text) {
        Map<String,Object> r = new LinkedHashMap<>();
        List<Object> c = new ArrayList<>();
        Map<String,Object> b = new LinkedHashMap<>(); b.put("type","text"); b.put("text",text); c.add(b);
        r.put("content",c); r.put("isError",false);
        return makeResponse(id,r);
    }

    static String toolOkStruct(Object id, Map<String,Object> sc) {
        String jsonText = toJson(sc);
        Map<String,Object> r = new LinkedHashMap<>();
        List<Object> c = new ArrayList<>();
        Map<String,Object> b = new LinkedHashMap<>(); b.put("type","text"); b.put("text",jsonText); c.add(b);
        r.put("content",c); r.put("structuredContent",sc); r.put("isError",false);
        return makeResponse(id,r);
    }

    static String toolFail(Object id, String msg) {
        Map<String,Object> r = new LinkedHashMap<>();
        List<Object> c = new ArrayList<>();
        Map<String,Object> b = new LinkedHashMap<>(); b.put("type","text"); b.put("text",msg); c.add(b);
        r.put("content",c); r.put("isError",true);
        return makeResponse(id,r);
    }

    static int cmpCP(String a, String b) {
        int i=0, j=0;
        while (i<a.length() && j<b.length()) {
            int ca=a.codePointAt(i), cb=b.codePointAt(j);
            if (ca!=cb) return Integer.compare(ca,cb);
            i+=Character.charCount(ca); j+=Character.charCount(cb);
        }
        return Integer.compare(a.length()-i, b.length()-j);
    }
}

use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::cmp::Ordering;

const B: u64 = 1_000_000_000;

#[derive(Clone, Debug)]
struct Big {
    d: Vec<u32>,
}

impl Big {
    fn zero() -> Self { Big { d: vec![] } }
    fn is_zero(&self) -> bool { self.d.is_empty() }
    fn norm(&mut self) { while self.d.last() == Some(&0) { self.d.pop(); } }

    fn from_u64(v: u64) -> Self {
        if v == 0 { return Self::zero(); }
        let mut d = vec![]; let mut v = v;
        while v > 0 { d.push((v % B) as u32); v /= B; }
        Big { d }
    }

    fn from_digits(s: &str) -> Self {
        if s.is_empty() { return Self::zero(); }
        let mut d = vec![]; let n = s.len(); let mut i = n;
        while i > 0 {
            let start = if i >= 9 { i - 9 } else { 0 };
            d.push(s[start..i].parse::<u32>().unwrap_or(0));
            i = start;
        }
        let mut r = Big { d }; r.norm(); r
    }

    fn cmp(&self, o: &Self) -> Ordering {
        if self.d.len() != o.d.len() { return self.d.len().cmp(&o.d.len()); }
        for i in (0..self.d.len()).rev() {
            match self.d[i].cmp(&o.d[i]) { Ordering::Equal => {}, ord => return ord }
        }
        Ordering::Equal
    }

    fn add(&self, o: &Self) -> Self {
        let mut d = vec![]; let mut c: u64 = 0;
        let n = self.d.len().max(o.d.len());
        for i in 0..n {
            let a = if i < self.d.len() { self.d[i] as u64 } else { 0 };
            let b = if i < o.d.len() { o.d[i] as u64 } else { 0 };
            let s = a + b + c; d.push((s % B) as u32); c = s / B;
        }
        if c > 0 { d.push(c as u32); }
        let mut r = Big { d }; r.norm(); r
    }

    fn sub(&self, o: &Self) -> Self {
        let mut d = vec![]; let mut borrow: i64 = 0;
        for i in 0..self.d.len() {
            let a = self.d[i] as i64;
            let b = if i < o.d.len() { o.d[i] as i64 } else { 0 };
            let mut diff = a - b - borrow;
            if diff < 0 { diff += B as i64; borrow = 1; } else { borrow = 0; }
            d.push(diff as u32);
        }
        let mut r = Big { d }; r.norm(); r
    }

    fn mul(&self, o: &Self) -> Self {
        if self.is_zero() || o.is_zero() { return Self::zero(); }
        let mut acc = vec![0u64; self.d.len() + o.d.len()];
        for i in 0..self.d.len() {
            let mut carry: u64 = 0;
            for j in 0..o.d.len() {
                let p = (self.d[i] as u64) * (o.d[j] as u64) + acc[i+j] + carry;
                acc[i+j] = p % B; carry = p / B;
            }
            if carry > 0 { acc[i + o.d.len()] += carry; }
        }
        let d: Vec<u32> = acc.iter().map(|&x| x as u32).collect();
        let mut r = Big { d }; r.norm(); r
    }

    fn mul_pow10(&self, n: usize) -> Big {
        if self.is_zero() || n == 0 { return self.clone(); }
        let full = n / 9; let rem = n % 9;
        let mut d = vec![0u32; full];
        d.extend_from_slice(&self.d);
        if rem > 0 {
            let factor = 10u64.pow(rem as u32);
            let mut carry: u64 = 0;
            for i in full..d.len() {
                let p = (d[i] as u64) * factor + carry;
                d[i] = (p % B) as u32; carry = p / B;
            }
            if carry > 0 { d.push(carry as u32); }
        }
        let mut r = Big { d }; r.norm(); r
    }

    fn div_pow10(&self, n: usize) -> (Big, Big) {
        if n == 0 || self.is_zero() { return (self.clone(), Big::zero()); }
        let full = n / 9; let rem = n % 9;
        if full >= self.d.len() { return (Big::zero(), self.clone()); }
        let mut q_digits = self.d[full..].to_vec();
        let mut r_digits = self.d[..full].to_vec();
        if rem > 0 {
            let divisor = 10u64.pow(rem as u32);
            let mut carry: u64 = 0;
            for i in (0..q_digits.len()).rev() {
                let current = carry * B + q_digits[i] as u64;
                q_digits[i] = (current / divisor) as u32;
                carry = current % divisor;
            }
            if carry > 0 { r_digits.push(carry as u32); }
        }
        let mut q = Big { d: q_digits }; q.norm();
        let mut r = Big { d: r_digits }; r.norm();
        (q, r)
    }

    fn is_odd(&self) -> bool {
        if self.d.is_empty() { return false; }
        self.d[0] % 2 == 1
    }

    fn to_u64(&self) -> u64 {
        if self.d.is_empty() { return 0; }
        let mut result: u64 = 0;
        for i in (0..self.d.len()).rev() {
            result = result * B + self.d[i] as u64;
        }
        result
    }

    fn divmod(&self, o: &Self) -> (Self, Self) {
        if o.is_zero() { panic!("div by zero"); }
        if self.is_zero() { return (Self::zero(), Self::zero()); }
        if self.cmp(o) == Ordering::Less { return (Self::zero(), self.clone()); }
        let sd: Vec<u32> = self.to_base10();
        let od: Vec<u32> = o.to_base10();
        let mut q_digits: Vec<u32> = Vec::with_capacity(sd.len());
        let mut rem: Vec<u32> = vec![];
        for &digit in &sd {
            rem.push(digit);
            while rem.len() > 1 && rem[0] == 0 { rem.remove(0); }
            if rem.len() == 1 && rem[0] == 0 { rem.clear(); }
            let mut q: u32 = 0;
            if !rem.is_empty() {
                let r_len = rem.len(); let d_len = od.len();
                if r_len > d_len {
                    q = 9;
                } else if r_len == d_len {
                    if d_len >= 2 {
                        let r_est = (rem[0] as u64) * 10 + rem[1] as u64;
                        let d_est = od[0] as u64;
                        q = std::cmp::min(9, (r_est / d_est) as u32);
                    } else {
                        q = std::cmp::min(9, rem[0] / od[0]);
                    }
                }
                while q > 0 {
                    let prod = mul_small_base10(&od, q);
                    if cmp_base10(&rem, &prod) != Ordering::Less { break; }
                    q -= 1;
                }
                if q > 0 {
                    let prod = mul_small_base10(&od, q);
                    rem = sub_base10(&rem, &prod);
                    while rem.len() > 1 && rem[0] == 0 { rem.remove(0); }
                    if rem.len() == 1 && rem[0] == 0 { rem.clear(); }
                }
            }
            q_digits.push(q);
        }
        while q_digits.len() > 1 && q_digits[0] == 0 { q_digits.remove(0); }
        if q_digits.len() == 1 && q_digits[0] == 0 { q_digits.clear(); }
        let q_str: String = q_digits.iter().map(|&d| (d as u8 + b'0') as char).collect();
        let r_str: String = if rem.is_empty() { "0".into() } else { rem.iter().map(|&d| (d as u8 + b'0') as char).collect() };
        (Self::from_digits(&q_str), Self::from_digits(&r_str))
    }

    fn to_base10(&self) -> Vec<u32> {
        if self.d.is_empty() { return vec![0]; }
        let mut result = vec![];
        let top = self.d.last().unwrap().to_string();
        for ch in top.bytes() { result.push((ch - b'0') as u32); }
        for i in (0..self.d.len()-1).rev() {
            let s = format!("{:09}", self.d[i]);
            for ch in s.bytes() { result.push((ch - b'0') as u32); }
        }
        result
    }

    fn to_dec_str(&self) -> String {
        if self.d.is_empty() { return "0".into(); }
        let mut s = self.d.last().unwrap().to_string();
        for i in (0..self.d.len()-1).rev() {
            s.push_str(&format!("{:09}", self.d[i]));
        }
        s
    }
}

fn mul_small_base10(digits: &[u32], m: u32) -> Vec<u32> {
    if m == 0 { return vec![]; }
    let mut carry: u32 = 0;
    let mut result = Vec::with_capacity(digits.len() + 1);
    for i in (0..digits.len()).rev() {
        let p = digits[i] * m + carry;
        result.push(p % 10); carry = p / 10;
    }
    while carry > 0 { result.push(carry % 10); carry /= 10; }
    result.reverse(); result
}

fn cmp_base10(a: &[u32], b: &[u32]) -> Ordering {
    if a.len() != b.len() { return a.len().cmp(&b.len()); }
    for i in 0..a.len() {
        match a[i].cmp(&b[i]) { Ordering::Equal => {}, ord => return ord }
    }
    Ordering::Equal
}

fn sub_base10(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut result = vec![0u32; a.len()];
    let mut borrow: i32 = 0;
    for i in (0..a.len()).rev() {
        let j = i as isize - (a.len() as isize - b.len() as isize);
        let bj = if j >= 0 { b[j as usize] as i32 } else { 0 };
        let mut diff = a[i] as i32 - bj - borrow;
        if diff < 0 { diff += 10; borrow = 1; } else { borrow = 0; }
        result[i] = diff as u32;
    }
    result
}

#[derive(Clone, Debug)]
struct Dec {
    neg: bool,
    mant: Big,
    scale: usize,
}

impl Dec {
    fn zero() -> Self { Dec { neg: false, mant: Big::zero(), scale: 0 } }
    fn is_zero(&self) -> bool { self.mant.is_zero() }

    fn parse(s: &str) -> Self {
        let (neg, rest) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
        let (int_part, frac_part) = if let Some(pos) = rest.find('.') {
            (&rest[..pos], &rest[pos+1..])
        } else { (rest, "") };
        let all_digits = format!("{}{}", int_part, frac_part);
        let scale = frac_part.len();
        let mant = Big::from_digits(&all_digits);
        let mut r = Dec { neg, mant, scale };
        if r.mant.is_zero() { r.neg = false; }
        r
    }

    fn cmp(&self, o: &Self) -> Ordering {
        if self.is_zero() && o.is_zero() { return Ordering::Equal; }
        if self.neg != o.neg { return o.neg.cmp(&self.neg); }
        let (a, b) = self.align(o);
        let c = a.mant.cmp(&b.mant);
        if self.neg { c.reverse() } else { c }
    }

    fn align(&self, o: &Self) -> (Dec, Dec) {
        let ms = self.scale.max(o.scale);
        (Dec { neg: self.neg, mant: self.mant.mul_pow10(ms - self.scale), scale: ms },
         Dec { neg: o.neg, mant: o.mant.mul_pow10(ms - o.scale), scale: ms })
    }

    fn add(&self, o: &Self) -> Self {
        let (a, b) = self.align(o);
        let scale = a.scale;
        if self.neg == o.neg {
            let mant = a.mant.add(&b.mant);
            let mut r = Dec { neg: self.neg, mant, scale };
            if r.mant.is_zero() { r.neg = false; }
            r
        } else {
            match a.mant.cmp(&b.mant) {
                Ordering::Greater => {
                    let mant = a.mant.sub(&b.mant);
                    let mut r = Dec { neg: self.neg, mant, scale };
                    if r.mant.is_zero() { r.neg = false; }
                    r
                }
                Ordering::Less => {
                    let mant = b.mant.sub(&a.mant);
                    let mut r = Dec { neg: o.neg, mant, scale };
                    if r.mant.is_zero() { r.neg = false; }
                    r
                }
                Ordering::Equal => Dec::zero(),
            }
        }
    }

    fn sub(&self, o: &Self) -> Self {
        self.add(&Dec { neg: !o.neg, mant: o.mant.clone(), scale: o.scale })
    }

    fn mul(&self, o: &Self) -> Self {
        let mant = self.mant.mul(&o.mant);
        let scale = self.scale + o.scale;
        let neg = self.neg != o.neg;
        let mut r = Dec { neg, mant, scale };
        if r.mant.is_zero() { r.neg = false; }
        r
    }

    fn round(&self, target: usize) -> Self {
        if self.scale <= target {
            let extra = target - self.scale;
            let mant = self.mant.mul_pow10(extra);
            let mut r = Dec { neg: self.neg, mant, scale: target };
            if r.mant.is_zero() { r.neg = false; }
            r
        } else {
            let extra = self.scale - target;
            let (q, r) = self.mant.div_pow10(extra);
            let half = Big::from_u64(5).mul_pow10(extra - 1);
            let rounded = match r.cmp(&half) {
                Ordering::Greater => q.add(&Big::from_u64(1)),
                Ordering::Less => q,
                Ordering::Equal => {
                    if q.is_odd() { q.add(&Big::from_u64(1)) } else { q }
                }
            };
            let mut result = Dec { neg: self.neg, mant: rounded, scale: target };
            if result.mant.is_zero() { result.neg = false; }
            result
        }
    }
}

fn add_commas(s: &str) -> String {
    let mut result = String::new();
    let n = s.len();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (n - i) % 3 == 0 { result.push(','); }
        result.push(c);
    }
    result
}

fn format_money(d: &Dec, minor: usize) -> String {
    let d = d.round(minor);
    if d.is_zero() {
        if minor == 0 { return "0".into(); }
        return format!("0.{}", "0".repeat(minor));
    }
    let mut s = String::new();
    if d.neg { s.push('-'); }
    let mant_str = d.mant.to_dec_str();
    if minor == 0 {
        s.push_str(&add_commas(&mant_str));
    } else {
        let padded = if mant_str.len() <= minor {
            format!("{}{}", "0".repeat(minor + 1 - mant_str.len()), mant_str)
        } else { mant_str };
        let int_part = &padded[..padded.len() - minor];
        let frac_part = &padded[padded.len() - minor..];
        s.push_str(&add_commas(int_part));
        s.push('.');
        s.push_str(frac_part);
    }
    s
}

struct Account {
    code: String,
    balance: Dec,
    limit: Dec,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/ledger.txt", dir)).unwrap();

    let mut currencies: BTreeMap<String, usize> = BTreeMap::new();
    let mut accounts: BTreeMap<String, Account> = BTreeMap::new();
    let mut rejects: Vec<String> = vec![];

    for (line_num, line) in content.lines().enumerate() {
        let n = line_num + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') { continue; }
        let fields: Vec<&str> = trimmed.split_whitespace().collect();
        let cmd = fields[0];

        match cmd {
            "currency" => {
                currencies.insert(fields[1].to_string(), fields[2].parse::<usize>().unwrap());
            }
            "open" => {
                let name = fields[1].to_string();
                let code = fields[2].to_string();
                let limit_str = if fields.len() > 3 { fields[3] } else { "0" };
                if accounts.contains_key(&name) {
                    rejects.push(format!("line {}: REJECT account exists {}", n, name));
                    continue;
                }
                let minor = *currencies.get(&code).unwrap();
                let limit = Dec::parse(limit_str).round(minor);
                accounts.insert(name, Account { code, balance: Dec::zero(), limit });
            }
            "deposit" => {
                let name = fields[1].to_string();
                if !accounts.contains_key(&name) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].code).unwrap();
                let amount = Dec::parse(fields[2]).round(minor);
                if amount.is_zero() || amount.neg {
                    rejects.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }
                accounts.get_mut(&name).unwrap().balance = accounts[&name].balance.add(&amount);
            }
            "withdraw" => {
                let name = fields[1].to_string();
                if !accounts.contains_key(&name) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].code).unwrap();
                let amount = Dec::parse(fields[2]).round(minor);
                if amount.is_zero() || amount.neg {
                    rejects.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }
                let acct = &accounts[&name];
                let new_bal = acct.balance.sub(&amount);
                let min_allowed = Dec { neg: true, mant: acct.limit.mant.clone(), scale: acct.limit.scale };
                if new_bal.cmp(&min_allowed) == Ordering::Less {
                    rejects.push(format!("line {}: REJECT insufficient funds {}", n, name));
                    continue;
                }
                accounts.get_mut(&name).unwrap().balance = new_bal;
            }
            "transfer" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                if !accounts.contains_key(&from) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, from));
                    continue;
                }
                if !accounts.contains_key(&to) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, to));
                    continue;
                }
                let from_code = accounts[&from].code.clone();
                let to_code = accounts[&to].code.clone();
                if from_code != to_code {
                    rejects.push(format!("line {}: REJECT currency mismatch", n));
                    continue;
                }
                let minor = *currencies.get(&from_code).unwrap();
                let amount = Dec::parse(fields[3]).round(minor);
                if amount.is_zero() || amount.neg {
                    rejects.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }
                let acct = &accounts[&from];
                let new_bal = acct.balance.sub(&amount);
                let min_allowed = Dec { neg: true, mant: acct.limit.mant.clone(), scale: acct.limit.scale };
                if new_bal.cmp(&min_allowed) == Ordering::Less {
                    rejects.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }
                accounts.get_mut(&from).unwrap().balance = new_bal;
                accounts.get_mut(&to).unwrap().balance = accounts[&to].balance.add(&amount);
            }
            "convert" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                if !accounts.contains_key(&from) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, from));
                    continue;
                }
                if !accounts.contains_key(&to) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, to));
                    continue;
                }
                let from_code = accounts[&from].code.clone();
                let to_code = accounts[&to].code.clone();
                let from_minor = *currencies.get(&from_code).unwrap();
                let to_minor = *currencies.get(&to_code).unwrap();
                let amount = Dec::parse(fields[3]).round(from_minor);
                if amount.is_zero() || amount.neg {
                    rejects.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }
                let acct = &accounts[&from];
                let new_bal = acct.balance.sub(&amount);
                let min_allowed = Dec { neg: true, mant: acct.limit.mant.clone(), scale: acct.limit.scale };
                if new_bal.cmp(&min_allowed) == Ordering::Less {
                    rejects.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }
                let rate = Dec::parse(fields[4]);
                let received = amount.mul(&rate).round(to_minor);
                accounts.get_mut(&from).unwrap().balance = new_bal;
                accounts.get_mut(&to).unwrap().balance = accounts[&to].balance.add(&received);
            }
            "interest" => {
                let name = fields[1].to_string();
                if !accounts.contains_key(&name) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].code).unwrap();
                let rate = Dec::parse(fields[2]);
                let balance = accounts[&name].balance.clone();
                let interest = balance.mul(&rate).round(minor);
                accounts.get_mut(&name).unwrap().balance = balance.add(&interest);
            }
            "split" => {
                let from = fields[1].to_string();
                let mut targets: Vec<(String, Big)> = vec![];
                for i in 3..fields.len() {
                    let cp = fields[i].find(':').unwrap();
                    let tname = fields[i][..cp].to_string();
                    let w = Big::from_digits(&fields[i][cp+1..]);
                    targets.push((tname, w));
                }
                let mut skip = false;
                if !accounts.contains_key(&from) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, from));
                    skip = true;
                }
                if !skip {
                    for (tname, _) in &targets {
                        if !accounts.contains_key(tname) {
                            rejects.push(format!("line {}: REJECT unknown account {}", n, tname));
                            skip = true; break;
                        }
                    }
                }
                if skip { continue; }

                let from_code = accounts[&from].code.clone();
                let from_minor = *currencies.get(&from_code).unwrap();

                let mut mismatch = false;
                for (tname, _) in &targets {
                    if accounts[tname].code != from_code { mismatch = true; break; }
                }
                if mismatch {
                    rejects.push(format!("line {}: REJECT currency mismatch", n));
                    continue;
                }

                let amount = Dec::parse(fields[2]).round(from_minor);
                if amount.is_zero() || amount.neg {
                    rejects.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                let acct = &accounts[&from];
                let new_bal = acct.balance.sub(&amount);
                let min_allowed = Dec { neg: true, mant: acct.limit.mant.clone(), scale: acct.limit.scale };
                if new_bal.cmp(&min_allowed) == Ordering::Less {
                    rejects.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }

                let a_minor = amount.mant.clone();
                let w_sum: Big = targets.iter().map(|(_, w)| w.clone()).fold(Big::zero(), |acc, w| acc.add(w));

                let mut base_amounts: Vec<Big> = vec![];
                let mut remainders: Vec<Big> = vec![];
                for (_, w) in &targets {
                    let prod = a_minor.mul(w);
                    let (q, r) = prod.divmod(&w_sum);
                    base_amounts.push(q);
                    remainders.push(r);
                }

                let total_given: Big = base_amounts.iter().fold(Big::zero(), |acc, x| acc.add(x));
                let leftover = a_minor.sub(&total_given);
                let leftover_count = leftover.to_u64();

                let mut indices: Vec<usize> = (0..targets.len()).collect();
                indices.sort_by(|&i, &j| {
                    let c = remainders[j].cmp(&remainders[i]);
                    if c != Ordering::Equal { return c; }
                    i.cmp(&j)
                });

                for k in 0..leftover_count as usize {
                    let idx = indices[k];
                    base_amounts[idx] = base_amounts[idx].add(&Big::from_u64(1));
                }

                accounts.get_mut(&from).unwrap().balance = new_bal;
                for (k, (tname, _)) in targets.iter().enumerate() {
                    let received = Dec { neg: false, mant: base_amounts[k].clone(), scale: from_minor };
                    accounts.get_mut(tname).unwrap().balance = accounts[tname].balance.add(&received);
                }
            }
            _ => {}
        }
    }

    for r in &rejects { println!("{}", r); }
    println!();
    for (name, acct) in &accounts {
        let minor = *currencies.get(&acct.code).unwrap();
        println!("{} {} {}", name, acct.code, format_money(&acct.balance, minor));
    }
    println!();
    let mut totals: BTreeMap<String, (Dec, usize)> = BTreeMap::new();
    for (_, acct) in &accounts {
        let e = totals.entry(acct.code.clone()).or_insert((Dec::zero(), 0));
        e.0 = e.0.add(&acct.balance);
        e.1 += 1;
    }
    for (code, (bal, count)) in &totals {
        let minor = *currencies.get(code).unwrap();
        println!("total {} {} ({} accounts)", code, format_money(bal, minor), count);
    }
}

use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::cmp::Ordering;

const B: u64 = 1_000_000_000;

#[derive(Clone, Debug)]
struct Big {
    d: Vec<u32>,
}

impl Big {
    fn zero() -> Self { Big { d: vec![] } }
    fn is_zero(&self) -> bool { self.d.is_empty() }
    fn norm(&mut self) { while self.d.last() == Some(&0) { self.d.pop(); } }

    fn from_u64(v: u64) -> Self {
        if v == 0 { return Self::zero(); }
        let mut d = vec![]; let mut v = v;
        while v > 0 { d.push((v % B) as u32); v /= B; }
        Big { d }
    }

    fn from_digits(s: &str) -> Self {
        if s.is_empty() { return Self::zero(); }
        let mut d = vec![]; let n = s.len(); let mut i = n;
        while i > 0 {
            let start = if i >= 9 { i - 9 } else { 0 };
            d.push(s[start..i].parse::<u32>().unwrap_or(0));
            i = start;
        }
        let mut r = Big { d }; r.norm(); r
    }

    fn cmp(&self, o: &Self) -> Ordering {
        if self.d.len() != o.d.len() { return self.d.len().cmp(&o.d.len()); }
        for i in (0..self.d.len()).rev() {
            match self.d[i].cmp(&o.d[i]) { Ordering::Equal => {}, ord => return ord }
        }
        Ordering::Equal
    }

    fn add(&self, o: &Self) -> Self {
        let mut d = vec![]; let mut c: u64 = 0;
        let n = self.d.len().max(o.d.len());
        for i in 0..n {
            let a = if i < self.d.len() { self.d[i] as u64 } else { 0 };
            let b = if i < o.d.len() { o.d[i] as u64 } else { 0 };
            let s = a + b + c; d.push((s % B) as u32); c = s / B;
        }
        if c > 0 { d.push(c as u32); }
        let mut r = Big { d }; r.norm(); r
    }

    fn sub(&self, o: &Self) -> Self {
        let mut d = vec![]; let mut borrow: i64 = 0;
        for i in 0..self.d.len() {
            let a = self.d[i] as i64;
            let b = if i < o.d.len() { o.d[i] as i64 } else { 0 };
            let mut diff = a - b - borrow;
            if diff < 0 { diff += B as i64; borrow = 1; } else { borrow = 0; }
            d.push(diff as u32);
        }
        let mut r = Big { d }; r.norm(); r
    }

    fn mul(&self, o: &Self) -> Self {
        if self.is_zero() || o.is_zero() { return Self::zero(); }
        let mut acc = vec![0u64; self.d.len() + o.d.len()];
        for i in 0..self.d.len() {
            let mut carry: u64 = 0;
            for j in 0..o.d.len() {
                let p = (self.d[i] as u64) * (o.d[j] as u64) + acc[i+j] + carry;
                acc[i+j] = p % B; carry = p / B;
            }
            if carry > 0 { acc[i + o.d.len()] += carry; }
        }
        let d: Vec<u32> = acc.iter().map(|&x| x as u32).collect();
        let mut r = Big { d }; r.norm(); r
    }

    fn mul_pow10(&self, n: usize) -> Big {
        if self.is_zero() || n == 0 { return self.clone(); }
        let full = n / 9; let rem = n % 9;
        let mut d = vec![0u32; full];
        d.extend_from_slice(&self.d);
        if rem > 0 {
            let factor = 10u64.pow(rem as u32);
            let mut carry: u64 = 0;
            for i in full..d.len() {
                let p = (d[i] as u64) * factor + carry;
                d[i] = (p % B) as u32; carry = p / B;
            }
            if carry > 0 { d.push(carry as u32); }
        }
        let mut r = Big { d }; r.norm(); r
    }

    fn div_pow10(&self, n: usize) -> (Big, Big) {
        if n == 0 || self.is_zero() { return (self.clone(), Big::zero()); }
        let full = n / 9; let rem = n % 9;
        if full >= self.d.len() { return (Big::zero(), self.clone()); }
        let mut q_digits = self.d[full..].to_vec();
        let mut r_digits = self.d[..full].to_vec();
        if rem > 0 {
            let divisor = 10u64.pow(rem as u32);
            let mut carry: u64 = 0;
            for i in (0..q_digits.len()).rev() {
                let current = carry * B + q_digits[i] as u64;
                q_digits[i] = (current / divisor) as u32;
                carry = current % divisor;
            }
            if carry > 0 { r_digits.push(carry as u32); }
        }
        let mut q = Big { d: q_digits }; q.norm();
        let mut r = Big { d: r_digits }; r.norm();
        (q, r)
    }

    fn is_odd(&self) -> bool {
        if self.d.is_empty() { return false; }
        self.d[0] % 2 == 1
    }

    fn to_u64(&self) -> u64 {
        if self.d.is_empty() { return 0; }
        let mut result: u64 = 0;
        for i in (0..self.d.len()).rev() {
            result = result * B + self.d[i] as u64;
        }
        result
    }

    fn divmod(&self, o: &Self) -> (Self, Self) {
        if o.is_zero() { panic!("div by zero"); }
        if self.is_zero() { return (Self::zero(), Self::zero()); }
        if self.cmp(o) == Ordering::Less { return (Self::zero(), self.clone()); }
        let sd: Vec<u32> = self.to_base10();
        let od: Vec<u32> = o.to_base10();
        let mut q_digits: Vec<u32> = Vec::with_capacity(sd.len());
        let mut rem: Vec<u32> = vec![];
        for &digit in &sd {
            rem.push(digit);
            while rem.len() > 1 && rem[0] == 0 { rem.remove(0); }
            if rem.len() == 1 && rem[0] == 0 { rem.clear(); }
            let mut q: u32 = 0;
            if !rem.is_empty() {
                let r_len = rem.len(); let d_len = od.len();
                if r_len > d_len {
                    q = 9;
                } else if r_len == d_len {
                    if d_len >= 2 {
                        let r_est = (rem[0] as u64) * 10 + rem[1] as u64;
                        let d_est = od[0] as u64;
                        q = std::cmp::min(9, (r_est / d_est) as u32);
                    } else {
                        q = std::cmp::min(9, rem[0] / od[0]);
                    }
                }
                while q > 0 {
                    let prod = mul_small_base10(&od, q);
                    if cmp_base10(&rem, &prod) != Ordering::Less { break; }
                    q -= 1;
                }
                if q > 0 {
                    let prod = mul_small_base10(&od, q);
                    rem = sub_base10(&rem, &prod);
                    while rem.len() > 1 && rem[0] == 0 { rem.remove(0); }
                    if rem.len() == 1 && rem[0] == 0 { rem.clear(); }
                }
            }
            q_digits.push(q);
        }
        while q_digits.len() > 1 && q_digits[0] == 0 { q_digits.remove(0); }
        if q_digits.len() == 1 && q_digits[0] == 0 { q_digits.clear(); }
        let q_str: String = q_digits.iter().map(|&d| (d as u8 + b'0') as char).collect();
        let r_str: String = if rem.is_empty() { "0".into() } else { rem.iter().map(|&d| (d as u8 + b'0') as char).collect() };
        (Self::from_digits(&q_str), Self::from_digits(&r_str))
    }

    fn to_base10(&self) -> Vec<u32> {
        if self.d.is_empty() { return vec![0]; }
        let mut result = vec![];
        let top = self.d.last().unwrap().to_string();
        for ch in top.bytes() { result.push((ch - b'0') as u32); }
        for i in (0..self.d.len()-1).rev() {
            let s = format!("{:09}", self.d[i]);
            for ch in s.bytes() { result.push((ch - b'0') as u32); }
        }
        result
    }

    fn to_dec_str(&self) -> String {
        if self.d.is_empty() { return "0".into(); }
        let mut s = self.d.last().unwrap().to_string();
        for i in (0..self.d.len()-1).rev() {
            s.push_str(&format!("{:09}", self.d[i]));
        }
        s
    }
}

fn mul_small_base10(digits: &[u32], m: u32) -> Vec<u32> {
    if m == 0 { return vec![]; }
    let mut carry: u32 = 0;
    let mut result = Vec::with_capacity(digits.len() + 1);
    for i in (0..digits.len()).rev() {
        let p = digits[i] * m + carry;
        result.push(p % 10); carry = p / 10;
    }
    while carry > 0 { result.push(carry % 10); carry /= 10; }
    result.reverse(); result
}

fn cmp_base10(a: &[u32], b: &[u32]) -> Ordering {
    if a.len() != b.len() { return a.len().cmp(&b.len()); }
    for i in 0..a.len() {
        match a[i].cmp(&b[i]) { Ordering::Equal => {}, ord => return ord }
    }
    Ordering::Equal
}

fn sub_base10(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut result = vec![0u32; a.len()];
    let mut borrow: i32 = 0;
    for i in (0..a.len()).rev() {
        let j = i as isize - (a.len() as isize - b.len() as isize);
        let bj = if j >= 0 { b[j as usize] as i32 } else { 0 };
        let mut diff = a[i] as i32 - bj - borrow;
        if diff < 0 { diff += 10; borrow = 1; } else { borrow = 0; }
        result[i] = diff as u32;
    }
    result
}

#[derive(Clone, Debug)]
struct Dec {
    neg: bool,
    mant: Big,
    scale: usize,
}

impl Dec {
    fn zero() -> Self { Dec { neg: false, mant: Big::zero(), scale: 0 } }
    fn is_zero(&self) -> bool { self.mant.is_zero() }

    fn parse(s: &str) -> Self {
        let (neg, rest) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
        let (int_part, frac_part) = if let Some(pos) = rest.find('.') {
            (&rest[..pos], &rest[pos+1..])
        } else { (rest, "") };
        let all_digits = format!("{}{}", int_part, frac_part);
        let scale = frac_part.len();
        let mant = Big::from_digits(&all_digits);
        let mut r = Dec { neg, mant, scale };
        if r.mant.is_zero() { r.neg = false; }
        r
    }

    fn cmp(&self, o: &Self) -> Ordering {
        if self.is_zero() && o.is_zero() { return Ordering::Equal; }
        if self.neg != o.neg { return o.neg.cmp(&self.neg); }
        let (a, b) = self.align(o);
        let c = a.mant.cmp(&b.mant);
        if self.neg { c.reverse() } else { c }
    }

    fn align(&self, o: &Self) -> (Dec, Dec) {
        let ms = self.scale.max(o.scale);
        (Dec { neg: self.neg, mant: self.mant.mul_pow10(ms - self.scale), scale: ms },
         Dec { neg: o.neg, mant: o.mant.mul_pow10(ms - o.scale), scale: ms })
    }

    fn add(&self, o: &Self) -> Self {
        let (a, b) = self.align(o);
        let scale = a.scale;
        if self.neg == o.neg {
            let mant = a.mant.add(&b.mant);
            let mut r = Dec { neg: self.neg, mant, scale };
            if r.mant.is_zero() { r.neg = false; }
            r
        } else {
            match a.mant.cmp(&b.mant) {
                Ordering::Greater => {
                    let mant = a.mant.sub(&b.mant);
                    let mut r = Dec { neg: self.neg, mant, scale };
                    if r.mant.is_zero() { r.neg = false; }
                    r
                }
                Ordering::Less => {
                    let mant = b.mant.sub(&a.mant);
                    let mut r = Dec { neg: o.neg, mant, scale };
                    if r.mant.is_zero() { r.neg = false; }
                    r
                }
                Ordering::Equal => Dec::zero(),
            }
        }
    }

    fn sub(&self, o: &Self) -> Self {
        self.add(&Dec { neg: !o.neg, mant: o.mant.clone(), scale: o.scale })
    }

    fn mul(&self, o: &Self) -> Self {
        let mant = self.mant.mul(&o.mant);
        let scale = self.scale + o.scale;
        let neg = self.neg != o.neg;
        let mut r = Dec { neg, mant, scale };
        if r.mant.is_zero() { r.neg = false; }
        r
    }

    fn round(&self, target: usize) -> Self {
        if self.scale <= target {
            let extra = target - self.scale;
            let mant = self.mant.mul_pow10(extra);
            let mut r = Dec { neg: self.neg, mant, scale: target };
            if r.mant.is_zero() { r.neg = false; }
            r
        } else {
            let extra = self.scale - target;
            let (q, r) = self.mant.div_pow10(extra);
            let half = Big::from_u64(5).mul_pow10(extra - 1);
            let rounded = match r.cmp(&half) {
                Ordering::Greater => q.add(&Big::from_u64(1)),
                Ordering::Less => q,
                Ordering::Equal => {
                    if q.is_odd() { q.add(&Big::from_u64(1)) } else { q }
                }
            };
            let mut result = Dec { neg: self.neg, mant: rounded, scale: target };
            if result.mant.is_zero() { result.neg = false; }
            result
        }
    }
}

fn add_commas(s: &str) -> String {
    let mut result = String::new();
    let n = s.len();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (n - i) % 3 == 0 { result.push(','); }
        result.push(c);
    }
    result
}

fn format_money(d: &Dec, minor: usize) -> String {
    let d = d.round(minor);
    if d.is_zero() {
        if minor == 0 { return "0".into(); }
        return format!("0.{}", "0".repeat(minor));
    }
    let mut s = String::new();
    if d.neg { s.push('-'); }
    let mant_str = d.mant.to_dec_str();
    if minor == 0 {
        s.push_str(&add_commas(&mant_str));
    } else {
        let padded = if mant_str.len() <= minor {
            format!("{}{}", "0".repeat(minor + 1 - mant_str.len()), mant_str)
        } else { mant_str };
        let int_part = &padded[..padded.len() - minor];
        let frac_part = &padded[padded.len() - minor..];
        s.push_str(&add_commas(int_part));
        s.push('.');
        s.push_str(frac_part);
    }
    s
}

struct Account {
    code: String,
    balance: Dec,
    limit: Dec,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/ledger.txt", dir)).unwrap();

    let mut currencies: BTreeMap<String, usize> = BTreeMap::new();
    let mut accounts: BTreeMap<String, Account> = BTreeMap::new();
    let mut rejects: Vec<String> = vec![];

    for (line_num, line) in content.lines().enumerate() {
        let n = line_num + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') { continue; }
        let fields: Vec<&str> = trimmed.split_whitespace().collect();
        let cmd = fields[0];

        match cmd {
            "currency" => {
                currencies.insert(fields[1].to_string(), fields[2].parse::<usize>().unwrap());
            }
            "open" => {
                let name = fields[1].to_string();
                let code = fields[2].to_string();
                let limit_str = if fields.len() > 3 { fields[3] } else { "0" };
                if accounts.contains_key(&name) {
                    rejects.push(format!("line {}: REJECT account exists {}", n, name));
                    continue;
                }
                let minor = *currencies.get(&code).unwrap();
                let limit = Dec::parse(limit_str).round(minor);
                accounts.insert(name, Account { code, balance: Dec::zero(), limit });
            }
            "deposit" => {
                let name = fields[1].to_string();
                if !accounts.contains_key(&name) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].code).unwrap();
                let amount = Dec::parse(fields[2]).round(minor);
                if amount.is_zero() || amount.neg {
                    rejects.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }
                accounts.get_mut(&name).unwrap().balance = accounts[&name].balance.add(&amount);
            }
            "withdraw" => {
                let name = fields[1].to_string();
                if !accounts.contains_key(&name) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].code).unwrap();
                let amount = Dec::parse(fields[2]).round(minor);
                if amount.is_zero() || amount.neg {
                    rejects.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }
                let acct = &accounts[&name];
                let new_bal = acct.balance.sub(&amount);
                let min_allowed = Dec { neg: true, mant: acct.limit.mant.clone(), scale: acct.limit.scale };
                if new_bal.cmp(&min_allowed) == Ordering::Less {
                    rejects.push(format!("line {}: REJECT insufficient funds {}", n, name));
                    continue;
                }
                accounts.get_mut(&name).unwrap().balance = new_bal;
            }
            "transfer" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                if !accounts.contains_key(&from) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, from));
                    continue;
                }
                if !accounts.contains_key(&to) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, to));
                    continue;
                }
                let from_code = accounts[&from].code.clone();
                let to_code = accounts[&to].code.clone();
                if from_code != to_code {
                    rejects.push(format!("line {}: REJECT currency mismatch", n));
                    continue;
                }
                let minor = *currencies.get(&from_code).unwrap();
                let amount = Dec::parse(fields[3]).round(minor);
                if amount.is_zero() || amount.neg {
                    rejects.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }
                let acct = &accounts[&from];
                let new_bal = acct.balance.sub(&amount);
                let min_allowed = Dec { neg: true, mant: acct.limit.mant.clone(), scale: acct.limit.scale };
                if new_bal.cmp(&min_allowed) == Ordering::Less {
                    rejects.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }
                accounts.get_mut(&from).unwrap().balance = new_bal;
                accounts.get_mut(&to).unwrap().balance = accounts[&to].balance.add(&amount);
            }
            "convert" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                if !accounts.contains_key(&from) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, from));
                    continue;
                }
                if !accounts.contains_key(&to) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, to));
                    continue;
                }
                let from_code = accounts[&from].code.clone();
                let to_code = accounts[&to].code.clone();
                let from_minor = *currencies.get(&from_code).unwrap();
                let to_minor = *currencies.get(&to_code).unwrap();
                let amount = Dec::parse(fields[3]).round(from_minor);
                if amount.is_zero() || amount.neg {
                    rejects.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }
                let acct = &accounts[&from];
                let new_bal = acct.balance.sub(&amount);
                let min_allowed = Dec { neg: true, mant: acct.limit.mant.clone(), scale: acct.limit.scale };
                if new_bal.cmp(&min_allowed) == Ordering::Less {
                    rejects.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }
                let rate = Dec::parse(fields[4]);
                let received = amount.mul(&rate).round(to_minor);
                accounts.get_mut(&from).unwrap().balance = new_bal;
                accounts.get_mut(&to).unwrap().balance = accounts[&to].balance.add(&received);
            }
            "interest" => {
                let name = fields[1].to_string();
                if !accounts.contains_key(&name) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].code).unwrap();
                let rate = Dec::parse(fields[2]);
                let balance = accounts[&name].balance.clone();
                let interest = balance.mul(&rate).round(minor);
                accounts.get_mut(&name).unwrap().balance = balance.add(&interest);
            }
            "split" => {
                let from = fields[1].to_string();
                let mut targets: Vec<(String, Big)> = vec![];
                for i in 3..fields.len() {
                    let cp = fields[i].find(':').unwrap();
                    let tname = fields[i][..cp].to_string();
                    let w = Big::from_digits(&fields[i][cp+1..]);
                    targets.push((tname, w));
                }
                let mut skip = false;
                if !accounts.contains_key(&from) {
                    rejects.push(format!("line {}: REJECT unknown account {}", n, from));
                    skip = true;
                }
                if !skip {
                    for (tname, _) in &targets {
                        if !accounts.contains_key(tname) {
                            rejects.push(format!("line {}: REJECT unknown account {}", n, tname));
                            skip = true; break;
                        }
                    }
                }
                if skip { continue; }

                let from_code = accounts[&from].code.clone();
                let from_minor = *currencies.get(&from_code).unwrap();

                let mut mismatch = false;
                for (tname, _) in &targets {
                    if accounts[tname].code != from_code { mismatch = true; break; }
                }
                if mismatch {
                    rejects.push(format!("line {}: REJECT currency mismatch", n));
                    continue;
                }

                let amount = Dec::parse(fields[2]).round(from_minor);
                if amount.is_zero() || amount.neg {
                    rejects.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                let acct = &accounts[&from];
                let new_bal = acct.balance.sub(&amount);
                let min_allowed = Dec { neg: true, mant: acct.limit.mant.clone(), scale: acct.limit.scale };
                if new_bal.cmp(&min_allowed) == Ordering::Less {
                    rejects.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }

                let a_minor = amount.mant.clone();
                let w_sum: Big = targets.iter().map(|(_, w)| w.clone()).fold(Big::zero(), |acc, w| acc.add(&w));

                let mut base_amounts: Vec<Big> = vec![];
                let mut remainders: Vec<Big> = vec![];
                for (_, w) in &targets {
                    let prod = a_minor.mul(w);
                    let (q, r) = prod.divmod(&w_sum);
                    base_amounts.push(q);
                    remainders.push(r);
                }

                let total_given: Big = base_amounts.iter().fold(Big::zero(), |acc, x| acc.add(x));
                let leftover = a_minor.sub(&total_given);
                let leftover_count = leftover.to_u64();

                let mut indices: Vec<usize> = (0..targets.len()).collect();
                indices.sort_by(|&i, &j| {
                    let c = remainders[j].cmp(&remainders[i]);
                    if c != Ordering::Equal { return c; }
                    i.cmp(&j)
                });

                for k in 0..leftover_count as usize {
                    let idx = indices[k];
                    base_amounts[idx] = base_amounts[idx].add(&Big::from_u64(1));
                }

                accounts.get_mut(&from).unwrap().balance = new_bal;
                for (k, (tname, _)) in targets.iter().enumerate() {
                    let received = Dec { neg: false, mant: base_amounts[k].clone(), scale: from_minor };
                    accounts.get_mut(tname).unwrap().balance = accounts[tname].balance.add(&received);
                }
            }
            _ => {}
        }
    }

    for r in &rejects { println!("{}", r); }
    println!();
    for (name, acct) in &accounts {
        let minor = *currencies.get(&acct.code).unwrap();
        println!("{} {} {}", name, acct.code, format_money(&acct.balance, minor));
    }
    println!();
    let mut totals: BTreeMap<String, (Dec, usize)> = BTreeMap::new();
    for (_, acct) in &accounts {
        let e = totals.entry(acct.code.clone()).or_insert((Dec::zero(), 0));
        e.0 = e.0.add(&acct.balance);
        e.1 += 1;
    }
    for (code, (bal, count)) in &totals {
        let minor = *currencies.get(code).unwrap();
        println!("total {} {} ({} accounts)", code, format_money(bal, minor), count);
    }
}

use std::collections::HashSet;
use std::env;
use std::fs;

// ============ SHA-256 ============
const K256: [u32; 64] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
