// ============ HMAC ============
fn hmac(key: &[u8], message: &[u8], block_size: usize, hash_fn: fn(&[u8]) -> Vec<u8>) -> Vec<u8> {
    let mut k = key.to_vec();
    if k.len() > block_size {
        k = hash_fn(&k);
    }
    k.resize(block_size, 0);
    let ipad: Vec<u8> = k.iter().map(|b| b ^ 0x36).collect();
    let opad: Vec<u8> = k.iter().map(|b| b ^ 0x5c).collect();
    let mut inner = ipad;
    inner.extend_from_slice(message);
    let inner_hash = hash_fn(&inner);
    let mut outer = opad;
    outer.extend_from_slice(&inner_hash);
    hash_fn(&outer)
}

fn hmac_sha256(key: &[u8], message: &[u8]) -> Vec<u8> {
    hmac(key, message, 64, |d| sha256(d).to_vec())
}
fn hmac_sha384(key: &[u8], message: &[u8]) -> Vec<u8> {
    hmac(key, message, 128, |d| sha384(d).to_vec())
}
fn hmac_sha512(key: &[u8], message: &[u8]) -> Vec<u8> {
    hmac(key, message, 128, |d| sha512(d).to_vec())
}

// ============ Base64url ============
fn base64url_valid(s: &str) -> bool {
    if s.is_empty() { return false; }
    if s.len() % 4 == 1 { return false; }
    for c in s.chars() {
        if !c.is_ascii_alphanumeric() && c != '-' && c != '_' {
            return false;
        }
    }
    true
}

fn base64url_decode(s: &str) -> Vec<u8> {
    let mut result = Vec::new();
    let mut bit_buf: u32 = 0;
    let mut bit_count: u32 = 0;
    for c in s.chars() {
        let v: u32 = match c {
            'A'..='Z' => (c as u32) - ('A' as u32),
            'a'..='z' => (c as u32) - ('a' as u32) + 26,
            '0'..='9' => (c as u32) - ('0' as u32) + 52,
            '-' => 62,
            '_' => 63,
            _ => unreachable!(),
        };
        bit_buf = (bit_buf << 6) | v;
        bit_count += 6;
        if bit_count >= 8 {
            bit_count -= 8;
            result.push((bit_buf >> bit_count) as u8);
        }
    }
    result
}

// ============ JSON ============
#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(fields) = self {
            for (k, v) in fields {
                if k == key { return Some(v); }
            }
        }
        None
    }
}

struct JParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JParser<'a> {
    fn new(s: &'a str) -> Self {
        JParser { input: s.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }

    fn parse_value(&mut self) -> Result<Json, &'static str> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string().map(Json::Str),
            Some(b't') => self.expect_lit(b"true").map(|_| Json::Bool(true)),
            Some(b'f') => self.expect_lit(b"false").map(|_| Json::Bool(false)),
            Some(b'n') => self.expect_lit(b"null").map(|_| Json::Null),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err("invalid value"),
        }
    }

    fn expect_lit(&mut self, lit: &[u8]) -> Result<(), &'static str> {
        if self.pos + lit.len() <= self.input.len() && &self.input[self.pos..self.pos+lit.len()] == lit {
            self.pos += lit.len();
            Ok(())
        } else {
            Err("invalid literal")
        }
    }

    fn parse_object(&mut self) -> Result<Json, &'static str> {
        self.pos += 1; // {
        let mut fields = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(Json::Obj(fields)); }
        loop {
            self.skip_ws();
            if self.peek() != Some(b'"') { return Err("expected key"); }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.peek() != Some(b':') { return Err("expected colon"); }
            self.pos += 1;
            let val = self.parse_value()?;
            fields.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; break; }
                _ => return Err("expected , or }"),
            }
        }
        Ok(Json::Obj(fields))
    }

    fn parse_array(&mut self) -> Result<Json, &'static str> {
        self.pos += 1; // [
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(Json::Arr(items)); }
        loop {
            let val = self.parse_value()?;
            items.push(val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; break; }
                _ => return Err("expected , or ]"),
            }
        }
        Ok(Json::Arr(items))
    }

    fn parse_string(&mut self) -> Result<String, &'static str> {
        self.pos += 1; // opening "
        let mut s = String::new();
        loop {
            if self.pos >= self.input.len() { return Err("unterminated string"); }
            let c = self.input[self.pos];
            match c {
                b'"' => { self.pos += 1; return Ok(s); }
                b'\\' => {
                    self.pos += 1;
                    if self.pos >= self.input.len() { return Err("unterminated escape"); }
                    let e = self.input[self.pos];
                    self.pos += 1;
                    match e {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'b' => s.push('\u{0008}'),
                        b'f' => s.push('\u{000C}'),
                        b'n' => s.push('\n'),
                        b'r' => s.push('\r'),
                        b't' => s.push('\t'),
                        b'u' => {
                            let cp = self.parse_hex4()?;
                            if cp >= 0xD800 && cp <= 0xDBFF {
                                // high surrogate, expect low surrogate
                                if self.pos + 1 < self.input.len() && self.input[self.pos] == b'\\' && self.input[self.pos+1] == b'u' {
                                    self.pos += 2;
                                    let lo = self.parse_hex4()?;
                                    if lo >= 0xDC00 && lo <= 0xDFFF {
                                        let full = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                        s.push(char::from_u32(full).unwrap_or('\u{FFFD}'));
                                    } else {
                                        s.push('\u{FFFD}');
                                        if let Some(ch) = char::from_u32(lo) { s.push(ch); }
                                    }
                                } else {
                                    s.push('\u{FFFD}');
                                }
                            } else {
                                s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                            }
                        }
                        _ => return Err("invalid escape"),
                    }
                }
                _ => {
                    // raw byte, collect UTF-8 sequence
                    let start = self.pos;
                    self.pos += 1;
                    // handle multi-byte UTF-8
                    if c >= 0x80 {
                        let extra = if c < 0xC0 { 0 } else if c < 0xE0 { 1 } else if c < 0xF0 { 2 } else { 3 };
                        for _ in 0..extra {
                            if self.pos < self.input.len() { self.pos += 1; }
                        }
                    }
                    s.push_str(std::str::from_utf8(&self.input[start..self.pos]).unwrap_or("\u{FFFD}"));
                }
            }
        }
    }

    fn parse_hex4(&mut self) -> Result<u32, &'static str> {
        if self.pos + 4 > self.input.len() { return Err("hex too short"); }
        let mut val: u32 = 0;
        for i in 0..4 {
            let c = self.input[self.pos + i];
            let d = match c {
                b'0'..='9' => (c - b'0') as u32,
                b'a'..='f' => (c - b'a') as u32 + 10,
                b'A'..='F' => (c - b'A') as u32 + 10,
                _ => return Err("invalid hex"),
            };
            val = val * 16 + d;
        }
        self.pos += 4;
        Ok(val)
    }

    fn parse_number(&mut self) -> Result<Json, &'static str> {
        let start = self.pos;
        if self.peek() == Some(b'-') { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).map_err(|_| "invalid number")?;
        s.parse::<f64>().map(Json::Num).map_err(|_| "invalid number")
    }
}

fn parse_json(s: &str) -> Result<Json, &'static str> {
    let mut p = JParser::new(s);
    let v = p.parse_value()?;
    p.skip_ws();
    if p.pos != p.input.len() { return Err("trailing content"); }
    Ok(v)
}

// ============ Main ============
fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let config_str = fs::read_to_string(format!("{}/config.json", dir)).unwrap();
    let config = parse_json(&config_str).unwrap();

    let now = match config.get("now") { Some(Json::Num(n)) => *n, _ => 0.0 };
    let leeway = match config.get("leeway") { Some(Json::Num(n)) => *n, _ => 0.0 };
    let issuer = match config.get("issuer") { Some(Json::Str(s)) => s.clone(), _ => String::new() };
    let audience = match config.get("audience") { Some(Json::Str(s)) => s.clone(), _ => String::new() };

    // Parse keys
    let mut keys: Vec<(String, String, String, Vec<u8>)> = Vec::new(); // kid, kty, alg, secret_bytes
    if let Some(Json::Arr(key_arr)) = config.get("keys") {
        for k in key_arr {
            let kid = match k.get("kid") { Some(Json::Str(s)) => s.clone(), _ => continue };
            let kty = match k.get("kty") { Some(Json::Str(s)) => s.clone(), _ => continue };
            let alg = match k.get("alg") { Some(Json::Str(s)) => s.clone(), _ => continue };
            let k_val = match k.get("k") { Some(Json::Str(s)) => s.clone(), _ => continue };
            let secret = base64url_decode(&k_val);
            keys.push((kid, kty, alg, secret));
        }
    }

    // Read tokens
    let tokens_str = fs::read_to_string(format!("{}/tokens.txt", dir)).unwrap();
    let lines: Vec<&str> = tokens_str.split('\n').collect();

    let mut valid_count = 0;
    let mut invalid_count = 0;
    let mut output = String::new();
    let mut token_num = 0;

    for line in lines {
        let trimmed = line.trim_matches(|c| c == ' ' || c == '\t' || c == '\r');
        if trimmed.is_empty() { continue; }
        token_num += 1;
        let token = trimmed;

        let result = validate_token(token, now, leeway, &issuer, &audience, &keys);
        if result == "VALID" {
            valid_count += 1;
        } else {
            invalid_count += 1;
        }
        output.push_str(&format!("{}: {}\n", token_num, result));
    }

    output.push('\n');
    output.push_str(&format!("valid={} invalid={}", valid_count, invalid_count));
    print!("{}", output);
}

fn validate_token(
    token: &str,
    now: f64,
    leeway: f64,
    issuer: &str,
    audience: &str,
    keys: &[(String, String, String, Vec<u8>)],
) -> String {
    // Rule 1: MALFORMED
    let parts: Vec<&str> = token.split('.').collect();
    if parts.len() != 3 { return "MALFORMED".to_string(); }

    for &p in &parts {
        if !base64url_valid(p) { return "MALFORMED".to_string(); }
    }

    let header_bytes = base64url_decode(parts[0]);
    let payload_bytes = base64url_decode(parts[1]);

    let header_str = match std::str::from_utf8(&header_bytes) {
        Ok(s) => s,
        Err(_) => return "MALFORMED".to_string(),
    };
    let payload_str = match std::str::from_utf8(&payload_bytes) {
        Ok(s) => s,
        Err(_) => return "MALFORMED".to_string(),
    };

    let header = match parse_json(header_str) {
        Ok(Json::Obj(_)) => Json::Obj(match parse_json(header_str) { Ok(Json::Obj(f)) => f, _ => unreachable!() }),
        _ => return "MALFORMED".to_string(),
    };
    let payload = match parse_json(payload_str) {
        Ok(Json::Obj(_)) => Json::Obj(match parse_json(payload_str) { Ok(Json::Obj(f)) => f, _ => unreachable!() }),
        _ => return "MALFORMED".to_string(),
    };

    // Rule 2: UNSUPPORTED_ALG
    let alg = match header.get("alg") {
        Some(Json::Str(s)) => s.clone(),
        _ => return "UNSUPPORTED_ALG".to_string(),
    };
    if alg != "HS256" && alg != "HS384" && alg != "HS512" {
        return "UNSUPPORTED_ALG".to_string();
    }

    // Rule 3: UNKNOWN_KEY
    let kid = match header.get("kid") {
        Some(Json::Str(s)) => s.clone(),
        _ => return "UNKNOWN_KEY".to_string(),
    };
    let key_idx = keys.iter().position(|(k, _, _, _)| k == &kid);
    let key_idx = match key_idx {
        Some(i) => i,
        None => return "UNKNOWN_KEY".to_string(),
    };

    // Rule 4: ALG_MISMATCH
    if keys[key_idx].2 != alg {
        return "ALG_MISMATCH".to_string();
    }

    // Rule 5: BAD_SIGNATURE
    let signing_input = format!("{}.{}", parts[0], parts[1]).into_bytes();
    let secret = &keys[key_idx].3;
    let expected_sig = match alg.as_str() {
        "HS256" => hmac_sha256(secret, &signing_input),
        "HS384" => hmac_sha384(secret, &signing_input),
        "HS512" => hmac_sha512(secret, &signing_input),
        _ => unreachable!(),
    };
    let actual_sig = base64url_decode(parts[2]);
    if actual_sig != expected_sig {
        return "BAD_SIGNATURE".to_string();
    }

    // Rule 6: EXPIRED
    if let Some(Json::Num(exp)) = payload.get("exp") {
        if now >= *exp + leeway { return "EXPIRED".to_string(); }
    }

    // Rule 7: NOT_YET_VALID
    if let Some(Json::Num(nbf)) = payload.get("nbf") {
        if now + leeway < *nbf { return "NOT_YET_VALID".to_string(); }
    }

    // Rule 8: BAD_ISSUER
    match payload.get("iss") {
        Some(Json::Str(s)) if s == issuer => {}
        _ => return "BAD_ISSUER".to_string(),
    }

    // Rule 9: BAD_AUDIENCE
    match payload.get("aud") {
        Some(Json::Str(s)) if s == audience => {}
        Some(Json::Arr(items)) => {
            let found = items.iter().any(|item| matches!(item, Json::Str(s) if s == audience));
            if !found { return "BAD_AUDIENCE".to_string(); }
        }
        _ => return "BAD_AUDIENCE".to_string(),
    }

    // VALID
    let sub = match payload.get("sub") {
        Some(Json::Str(s)) => s.clone(),
        _ => String::new(),
    };
    let scope_str = match payload.get("scope") {
        Some(Json::Str(s)) => s.clone(),
        _ => String::new(),
    };
    let mut scope_set: HashSet<String> = HashSet::new();
    for piece in scope_str.split(' ') {
        if !piece.is_empty() {
            scope_set.insert(piece.to_string());
        }
    }
    let mut scopes: Vec<String> = scope_set.into_iter().collect();
    scopes.sort();
    let scopes_joined = scopes.join(",");

    format!("VALID sub={} scope={}", sub, scopes_joined)
}

