    sb_init(sb);
    sb_puts(sb,"{\"jsonrpc\":\"2.0\",\"id\":");
    ser_id(sb,id);
    sb_puts(sb,",\"result\":{\"tools\":[");

    /* kv_set */
    sb_puts(sb,"{\"name\":\"kv_set\",\"title\":\"Set a value\",\"description\":\"Store a string value under a key, replacing any previous value.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1},\"value\":{\"type\":\"string\"}},\"required\":[\"key\",\"value\"],\"additionalProperties\":false}}");
    sb_putc(sb,',');
    /* kv_get */
    sb_puts(sb,"{\"name\":\"kv_get\",\"title\":\"Get a value\",\"description\":\"Return the value stored under a key.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1}},\"required\":[\"key\"],\"additionalProperties\":false}}");
    sb_putc(sb,',');
    /* kv_list */
    sb_puts(sb,"{\"name\":\"kv_list\",\"title\":\"List keys\",\"description\":\"List the stored keys that start with a prefix, sorted by Unicode code point.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"prefix\":{\"type\":\"string\"}},\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"keys\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"count\":{\"type\":\"integer\"}},\"required\":[\"keys\",\"count\"]}}");
    sb_putc(sb,',');
    /* sum */
    sb_puts(sb,"{\"name\":\"sum\",\"title\":\"Sum integers\",\"description\":\"Add up a non-empty list of integers.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"numbers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"minItems\":1}},\"required\":[\"numbers\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"sum\":{\"type\":\"integer\"},\"count\":{\"type\":\"integer\"}},\"required\":[\"sum\",\"count\"]},\"annotations\":{\"readOnlyHint\":true,\"idempotentHint\":true}}");
    sb_putc(sb,',');
    /* text_stats */
    sb_puts(sb,"{\"name\":\"text_stats\",\"title\":\"Text statistics\",\"description\":\"Count the words, Unicode code points and UTF-8 bytes of a text.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"text\":{\"type\":\"string\"}},\"required\":[\"text\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"words\":{\"type\":\"integer\"},\"codepoints\":{\"type\":\"integer\"},\"utf8_bytes\":{\"type\":\"integer\"}},\"required\":[\"words\",\"codepoints\",\"utf8_bytes\"]},\"annotations\":{\"readOnlyHint\":true}}");

    sb_puts(sb,"]}}");
}

/* ============ Main ============ */
int main(void){
    int initialized=0;
    char *line=NULL;
    size_t linecap=0;
    ssize_t llen;

    while((llen=getline(&line,&linecap,stdin))!=-1){
        /* strip trailing \n and \r */
        while(llen>0&&(line[llen-1]=='\n'||line[llen-1]=='\r'))llen--;
        line[llen]=0;

        /* check if line is empty or whitespace only */
        int blank=1;
        for(ssize_t i=0;i<llen;i++){
            char c=line[i];
            if(c!=' '&&c!='\t'&&c!='\r'){blank=0;break;}
        }
        if(blank)continue;

        /* parse JSON */
        JV *msg=parse_json(line);
        if(!msg){
            SB sb;emit_error(&sb,NULL,-32700,"Parse error");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        /* rule 2: not an object */
        if(msg->type!=J_OBJ){
            SB sb;emit_error(&sb,NULL,-32600,"Invalid Request");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        /* rule 3: response from client */
        JV *jr=obj_get(msg,"jsonrpc");
        JV *jmethod=obj_get(msg,"method");
        JV *jresult=obj_get(msg,"result");
        JV *jerror=obj_get(msg,"error");

        if(!jmethod&&(jresult||jerror)){
            /* client response, ignore */
            continue;
        }

        /* rule 4: check validity */
        /* extract id for error reporting */
        JV *id=obj_get(msg,"id");
        JV *valid_id=NULL;
        if(id){
            if(id->type==J_STR)valid_id=id;
            else if(id->type==J_NUM&&id->is_int)valid_id=id;
        }

        /* invalid if jsonrpc != "2.0" */
        int invalid=0;
        if(!jr||jr->type!=J_STR||strcmp(jr->str,"2.0")!=0)invalid=1;
        /* invalid if method missing or not string */
        if(!jmethod||jmethod->type!=J_STR)invalid=1;
        /* invalid if id present but not valid */
        if(id&&!valid_id)invalid=1;

        if(invalid){
            SB sb;emit_error(&sb,valid_id,-32600,"Invalid Request");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        /* rule 5: notification (no id) */
        if(!id){
            continue;
        }

        /* rule 6: valid request */
        const char *method=jmethod->str;

        /* 6a: method not found */
        if(strcmp(method,"initialize")!=0&&strcmp(method,"ping")!=0&&
           strcmp(method,"tools/list")!=0&&strcmp(method,"tools/call")!=0){
            SB sb;emit_error(&sb,valid_id,-32601,"Method not found");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        /* 6b: params present but not object */
        JV *params=obj_get(msg,"params");
        if(params&&params->type!=J_OBJ){
            SB sb;emit_error(&sb,valid_id,-32602,"Invalid params");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        /* 6c: not initialized */
        if(!initialized&&strcmp(method,"initialize")!=0&&strcmp(method,"ping")!=0){
            SB sb;emit_error(&sb,valid_id,-32002,"Server not initialized");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        /* 6d: dispatch */
        if(strcmp(method,"initialize")==0){
            if(initialized){
                SB sb;emit_error(&sb,valid_id,-32600,"Already initialized");
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }
            if(!params){
                SB sb;emit_error(&sb,valid_id,-32602,"Invalid params");
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }
            JV *pv=obj_get(params,"protocolVersion");
            if(!pv||pv->type!=J_STR){
                SB sb;emit_error(&sb,valid_id,-32602,"Invalid params");
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }
            initialized=1;
            const char *ver=pv->str;
            const char *resp_ver;
            if(strcmp(ver,"2025-06-18")==0||strcmp(ver,"2025-03-26")==0||strcmp(ver,"2024-11-05")==0)
                resp_ver=ver;
            else resp_ver="2025-06-18";

            SB sb;sb_init(&sb);
            sb_puts(&sb,"{\"jsonrpc\":\"2.0\",\"id\":");
            ser_id(&sb,valid_id);
            sb_puts(&sb,",\"result\":{\"protocolVersion\":");
            sb_json_str(&sb,resp_ver);
            sb_puts(&sb,",\"capabilities\":{\"tools\":{\"listChanged\":false}},\"serverInfo\":{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
        }
        else if(strcmp(method,"ping")==0){
            SB sb;sb_init(&sb);
            sb_puts(&sb,"{\"jsonrpc\":\"2.0\",\"id\":");
            ser_id(&sb,valid_id);
            sb_puts(&sb,",\"result\":{}}");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
        }
        else if(strcmp(method,"tools/list")==0){
            SB sb;output_tools_list(&sb,valid_id);
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
        }
        else if(strcmp(method,"tools/call")==0){
            /* params.name */
            if(!params||!obj_get(params,"name")||obj_get(params,"name")->type!=J_STR){
                SB sb;emit_error(&sb,valid_id,-32602,"Invalid params");
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }
            const char *tname=obj_get(params,"name")->str;

            /* find tool */
            ToolDef *td=NULL;
            for(int i=0;i<ntools;i++){
                if(strcmp(tools[i].name,tname)==0){td=&tools[i];break;}
            }
            if(!td){
                char msg[256];sprintf(msg,"Unknown tool: %s",tname);
                SB sb;emit_error(&sb,valid_id,-32602,msg);
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }

            /* arguments */
            JV *args=obj_get(params,"arguments");
            if(args&&args->type!=J_OBJ){
                /* includes null */
                tool_fail(&SB{NULL,0,0},valid_id,"arguments must be an object");
                /* need to redo this properly */
                SB sb;sb_init(&sb);
                sb_puts(&sb,"{\"jsonrpc\":\"2.0\",\"id\":");
                ser_id(&sb,valid_id);
                sb_puts(&sb,",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"arguments must be an object\"}],\"isError\":true}}");
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }

            char fail_buf[4096];
            if(!validate_args(args,td,fail_buf)){
                tool_fail(&SB{NULL,0,0},valid_id,fail_buf);
                /* redo properly */
                SB sb;sb_init(&sb);
                sb_puts(&sb,"{\"jsonrpc\":\"2.0\",\"id\":");
                ser_id(&sb,valid_id);
                sb_puts(&sb,",\"result\":{\"content\":[{\"type\":\"text\",\"text\":");
                sb_json_str(&sb,fail_buf);
                sb_puts(&sb,"}],\"isError\":true}}");
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }

            /* execute */
            SB sb;
            exec_tool(&sb,valid_id,td,args?args:jv_new(J_OBJ));
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
        }
    }

    free(line);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* ============ Dynamic String Builder ============ */
typedef struct { char *buf; size_t len, cap; } SB;
static void sb_init(SB *sb){sb->cap=512;sb->buf=malloc(sb->cap);sb->len=0;sb->buf[0]=0;}
static void sb_ensure(SB *sb,size_t x){if(sb->len+x+1>sb->cap){while(sb->len+x+1>sb->cap)sb->cap*=2;sb->buf=realloc(sb->buf,sb->cap);}}
static void sb_putc(SB *sb,char c){sb_ensure(sb,1);sb->buf[sb->len++]=c;sb->buf[sb->len]=0;}
static void sb_puts(SB *sb,const char *s){size_t n=strlen(s);sb_ensure(sb,n);memcpy(sb->buf+sb->len,s,n);sb->len+=n;sb->buf[sb->len]=0;}
static void sb_json_str(SB *sb,const char *s){
    sb_putc(sb,'"');
    for(;*s;s++){unsigned char c=(unsigned char)*s;
        switch(c){case '"':sb_puts(sb,"\\\"");break;case'\\':sb_puts(sb,"\\\\");break;
        case'\b':sb_puts(sb,"\\b");break;case'\f':sb_puts(sb,"\\f");break;
        case'\n':sb_puts(sb,"\\n");break;case'\r':sb_puts(sb,"\\r");break;case'\t':sb_puts(sb,"\\t");break;
        default:if(c<0x20){sb_ensure(sb,6);sb->len+=sprintf(sb->buf+sb->len,"\\u%04x",c);sb->buf[sb->len]=0;}
                else sb_putc(sb,(char)c);}}
    sb_putc(sb,'"');
}

/* ============ JSON Value ============ */
typedef enum{J_NULL,J_TRUE,J_FALSE,J_NUM,J_STR,J_ARR,J_OBJ}JType;
typedef struct JV{
    JType type;
    double num;
    int is_int;
    char *num_text;
    char *str;
    struct JV **items; int count;
    char **keys; struct JV **vals;
}JV;

static JV *jv_new(JType t){JV *v=calloc(1,sizeof(JV));v->type=t;return v;}
static int obj_get_idx(JV *o,const char *k){for(int i=0;i<o->count;i++)if(strcmp(o->keys[i],k)==0)return i;return -1;}
static JV *obj_get(JV *o,const char *k){int i=obj_get_idx(o,k);return i<0?NULL:o->vals[i];}

/* ============ JSON Parser ============ */
static const char *g_p;
static int g_err;

static void skip_ws(void){while(*g_p==' '||*g_p=='\t'||*g_p=='\n'||*g_p=='\r')g_p++;}

static JV *parse_value(void);

static JV *parse_string_raw(void){
    g_p++;
    size_t cap=64,len=0;char *buf=malloc(cap);
    while(*g_p&&*g_p!='"'){
        if(len+4>=cap){cap*=2;buf=realloc(buf,cap);}
        if(*g_p=='\\'){
            g_p++;
            switch(*g_p){
                case'"':buf[len++]='"';g_p++;break;
                case'\\':buf[len++]='\\';g_p++;break;
                case'/':buf[len++]='/';g_p++;break;
                case'b':buf[len++]='\b';g_p++;break;
                case'f':buf[len++]='\f';g_p++;break;
                case'n':buf[len++]='\n';g_p++;break;
                case'r':buf[len++]='\r';g_p++;break;
                case't':buf[len++]='\t';g_p++;break;
                case'u':{
                    g_p++;
                    unsigned cp=0;
                    for(int i=0;i<4;i++){
                        char c=*g_p;g_p++;
                        if(c>='0'&&c<='9')cp=cp*16+(c-'0');
                        else if(c>='a'&&c<='f')cp=cp*16+(c-'a'+10);
                        else if(c>='A'&&c<='F')cp=cp*16+(c-'A'+10);
                        else{g_err=1;free(buf);return NULL;}
                    }
                    if(cp>=0xD800&&cp<=0xDBFF){
                        if(*g_p=='\\'&&g_p[1]=='u'){
                            g_p+=2;
                            unsigned lo=0;
                            for(int i=0;i<4;i++){
                                char c=*g_p;g_p++;
                                if(c>='0'&&c<='9')lo=lo*16+(c-'0');
                                else if(c>='a'&&c<='f')lo=lo*16+(c-'a'+10);
                                else if(c>='A'&&c<='F')lo=lo*16+(c-'A'+10);
                                else{g_err=1;free(buf);return NULL;}
                            }
                            if(lo>=0xDC00&&lo<=0xDFFF){
                                cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                            } else {
                                cp=0xFFFD;
                            }
                        } else {
                            cp=0xFFFD;
                        }
                    } else if(cp>=0xDC00&&cp<=0xDFFF){
                        cp=0xFFFD;
                    }
                    if(len+4>=cap){cap*=2;buf=realloc(buf,cap);}
                    if(cp<0x80)buf[len++]=(char)cp;
                    else if(cp<0x800){buf[len++]=(char)(0xC0|(cp>>6));buf[len++]=(char)(0x80|(cp&0x3F));}
                    else if(cp<0x10000){buf[len++]=(char)(0xE0|(cp>>12));buf[len++]=(char)(0x80|((cp>>6)&0x3F));buf[len++]=(char)(0x80|(cp&0x3F));}
                    else{buf[len++]=(char)(0xF0|(cp>>18));buf[len++]=(char)(0x80|((cp>>12)&0x3F));buf[len++]=(char)(0x80|((cp>>6)&0x3F));buf[len++]=(char)(0x80|(cp&0x3F));}
                }break;
                default:g_err=1;free(buf);return NULL;
            }
        } else {
            buf[len++]=*g_p++;
        }
    }
    if(*g_p!='"'){g_err=1;free(buf);return NULL;}
    g_p++;
    buf[len]=0;
    JV *v=jv_new(J_STR);v->str=buf;return v;
}

static JV *parse_number(void){
    const char *start=g_p;
    int is_int=1;
    if(*g_p=='-')g_p++;
    if(*g_p=='0'){g_p++;}
    else if(*g_p>='1'&&*g_p<='9'){while(*g_p>='0'&&*g_p<='9')g_p++;}
    else{g_err=1;return NULL;}
    if(*g_p=='.'){is_int=0;g_p++;if(*g_p<'0'||*g_p>'9'){g_err=1;return NULL;}while(*g_p>='0'&&*g_p<='9')g_p++;}
    if(*g_p=='e'||*g_p=='E'){is_int=0;g_p++;if(*g_p=='+'||*g_p=='-')g_p++;if(*g_p<'0'||*g_p>'9'){g_err=1;return NULL;}while(*g_p>='0'&&*g_p<='9')g_p++;}
    size_t n=(size_t)(g_p-start);
    char *txt=malloc(n+1);memcpy(txt,start,n);txt[n]=0;
    JV *v=jv_new(J_NUM);v->num=strtod(start,NULL);v->is_int=is_int;v->num_text=txt;return v;
}

static JV *parse_value(void){
    skip_ws();
    if(g_err)return NULL;
    char c=*g_p;
    if(c=='"')return parse_string_raw();
    if(c=='{'){
        g_p++;skip_ws();
        int cap=8,count=0;
        char **keys=malloc(cap*sizeof(char*));
        JV **vals=malloc(cap*sizeof(JV*));
        if(*g_p=='}'){g_p++;JV *v=jv_new(J_OBJ);v->keys=keys;v->vals=vals;v->count=0;return v;}
        while(1){
            skip_ws();
            if(*g_p!='"'){g_err=1;return NULL;}
            JV *kv=parse_string_raw();if(!kv)return NULL;
            skip_ws();
            if(*g_p!=':'){g_err=1;return NULL;}
            g_p++;
            JV *val=parse_value();if(!val)return NULL;
            if(count>=cap){cap*=2;keys=realloc(keys,cap*sizeof(char*));vals=realloc(vals,cap*sizeof(JV*));}
            keys[count]=kv->str;free(kv);
            vals[count]=val;count++;
            skip_ws();
            if(*g_p==','){g_p++;continue;}
            if(*g_p=='}'){g_p++;break;}
            g_err=1;return NULL;
        }
        JV *v=jv_new(J_OBJ);v->keys=keys;v->vals=vals;v->count=count;return v;
    }
    if(c=='['){
        g_p++;skip_ws();
        int cap=8,count=0;
        JV **items=malloc(cap*sizeof(JV*));
        if(*g_p==']'){g_p++;JV *v=jv_new(J_ARR);v->items=items;v->count=0;return v;}
        while(1){
            JV *item=parse_value();if(!item)return NULL;
            if(count>=cap){cap*=2;items=realloc(items,cap*sizeof(JV*));}
            items[count++]=item;
            skip_ws();
            if(*g_p==','){g_p++;continue;}
            if(*g_p==']'){g_p++;break;}
            g_err=1;return NULL;
        }
        JV *v=jv_new(J_ARR);v->items=items;v->count=count;return v;
    }
    if(c=='t'){if(strncmp(g_p,"true",4)==0){g_p+=4;return jv_new(J_TRUE);}g_err=1;return NULL;}
    if(c=='f'){if(strncmp(g_p,"false",5)==0){g_p+=5;return jv_new(J_FALSE);}g_err=1;return NULL;}
    if(c=='n'){if(strncmp(g_p,"null",4)==0){g_p+=4;return jv_new(J_NULL);}g_err=1;return NULL;}
    if(c=='-'||(c>='0'&&c<='9'))return parse_number();
    g_err=1;return NULL;
}

static JV *parse_json(const char *s){
    g_p=s;g_err=0;
    JV *v=parse_value();
    if(g_err)return NULL;
    skip_ws();
    if(*g_p!=0)return NULL;
    return v;
}

/* ============ Serialize JSON value to SB ============ */
static void ser_json(SB *sb,JV *v){
    if(!v){sb_puts(sb,"null");return;}
    switch(v->type){
        case J_NULL:sb_puts(sb,"null");break;
        case J_TRUE:sb_puts(sb,"true");break;
        case J_FALSE:sb_puts(sb,"false");break;
        case J_NUM:sb_puts(sb,v->num_text);break;
        case J_STR:sb_json_str(sb,v->str);break;
        case J_ARR:
            sb_putc(sb,'[');
            for(int i=0;i<v->count;i++){if(i)sb_putc(sb,',');ser_json(sb,v->items[i]);}
            sb_putc(sb,']');break;
        case J_OBJ:
            sb_putc(sb,'{');
            for(int i=0;i<v->count;i++){if(i)sb_putc(sb,',');sb_json_str(sb,v->keys[i]);sb_putc(sb,':');ser_json(sb,v->vals[i]);}
            sb_putc(sb,'}');break;
    }
}

static void ser_id(SB *sb,JV *id){
    if(!id){sb_puts(sb,"null");return;}
    if(id->type==J_STR)sb_json_str(sb,id->str);
    else if(id->type==J_NUM)sb_puts(sb,id->num_text);
    else sb_puts(sb,"null");
}

/* ============ KV Store ============ */
typedef struct KV{char *key;char *val;struct KV *next;}KV;
static KV *kv_head=NULL;

static void kv_set(const char *k,const char *v){
    for(KV *p=kv_head;p;p=p->next){
        if(strcmp(p->key,k)==0){free(p->val);p->val=strdup(v);return;}
    }
    KV *n=malloc(sizeof(KV));n->key=strdup(k);n->val=strdup(v);n->next=kv_head;kv_head=n;
}
static int kv_exists(const char *k){for(KV *p=kv_head;p;p=p->next)if(strcmp(p->key,k)==0)return 1;return 0;}
static const char *kv_get(const char *k){for(KV *p=kv_head;p;p=p->next)if(strcmp(p->key,k)==0)return p->val;return NULL;}

/* ============ UTF-8 helpers ============ */
static int count_codepoints(const char *s){
    int c=0;
    while(*s){unsigned char b=(unsigned char)*s;
        if(b<0x80)s+=1;else if(b<0xE0)s+=2;else if(b<0xF0)s+=3;else s+=4;c++;}
    return c;
}
static int count_words(const char *s){
    int w=0,in=0;
    while(*s){unsigned char b=(unsigned char)*s;
        if(b==0x20||b==0x09||b==0x0A||b==0x0D){in=0;}
        else{if(!in)w++;in=1;}s++;}
    return w;
}

