/* ============ Output helpers ============ */
static void emit_error(SB *sb,JV *id,int code,const char *msg){
    sb_init(sb);
    sb_puts(sb,"{\"jsonrpc\":\"2.0\",\"id\":");
    ser_id(sb,id);
    sb_puts(sb,",\"error\":{\"code\":");
    char tmp[32];sprintf(tmp,"%d",code);sb_puts(sb,tmp);
    sb_puts(sb,",\"message\":");
    sb_json_str(sb,msg);
    sb_puts(sb,"}}");
}

static void tool_success(SB *sb,JV *id,const char *text){
    sb_init(sb);
