/* ============ Validate arguments ============ */
static int validate_args(JV *args,ToolDef *td,char *fail_buf){
    if(args){
        const char *smallest=NULL;
        for(int i=0;i<args->count;i++){
            int found=0;
            for(int j=0;j<td->prop_count;j++){
                if(strcmp(args->keys[i],td->prop_names[j])==0){found=1;break;}
            }
            if(!found){
                if(!smallest||strcmp(args->keys[i],smallest)<0)smallest=args->keys[i];
            }
        }
        if(smallest){sprintf(fail_buf,"unknown argument: %s",smallest);return 0;}
    }
    for(int j=0;j<td->prop_count;j++){
        const char *pname=td->prop_names[j];
        JV *pv=args?obj_get(args,pname):NULL;
        if(!pv){
            if(td->prop_required[j]){sprintf(fail_buf,"missing required argument: %s",pname);return 0;}
            continue;
        }
        if(td->prop_types[j]==0){
            if(pv->type!=J_STR){sprintf(fail_buf,"argument %s must be a string",pname);return 0;}
            if(td->prop_min[j]&&pv->str[0]==0){sprintf(fail_buf,"argument %s must not be empty",pname);return 0;}
        } else if(td->prop_types[j]==1){
            if(pv->type!=J_ARR){sprintf(fail_buf,"argument %s must be an array of integers",pname);return 0;}
            if(td->prop_min[j]&&pv->count==0){sprintf(fail_buf,"argument %s must not be empty",pname);return 0;}
            for(int k=0;k<pv->count;k++){
                if(pv->items[k]->type!=J_NUM||!pv->items[k]->is_int){
                    sprintf(fail_buf,"argument %s must be an array of integers",pname);return 0;
                }
            }
        }
    }
    return 1;
}

/* ============ Comparison for qsort ============ */
static int cmp_str(const void *a,const void *b){
    return strcmp(*(const char**)a,*(const char**)b);
}

/* ============ Execute tool ============ */
static void exec_tool(SB *sb,JV *id,ToolDef *td,JV *args){
    if(strcmp(td->name,"kv_set")==0){
        JV *jkey=obj_get(args,"key");
        JV *jval=obj_get(args,"value");
        const char *key=jkey->str;
        const char *val=jval->str;
        int existed=kv_exists(key);
        kv_set(key,val);
        char buf[4096];
        sprintf(buf,"%s %s",existed?"updated":"created",key);
        tool_success(sb,id,buf);
    } else if(strcmp(td->name,"kv_get")==0){
        JV *jkey=obj_get(args,"key");
        const char *key=jkey->str;
        const char *val=kv_get(key);
        if(!val){
            char buf[4096];sprintf(buf,"key not found: %s",key);
            tool_fail(sb,id,buf);
        } else {
            tool_success(sb,id,val);
        }
    } else if(strcmp(td->name,"kv_list")==0){
        JV *jpfx=obj_get(args,"prefix");
        const char *prefix=jpfx?jpfx->str:"";
        int cap=16,count=0;
        char **keys=malloc(cap*sizeof(char*));
        size_t plen=strlen(prefix);
        for(KV *p=kv_head;p;p=p->next){
            if(strncmp(p->key,prefix,plen)==0){
                if(count>=cap){cap*=2;keys=realloc(keys,cap*sizeof(char*));}
                keys[count++]=p->key;
            }
        }
        qsort(keys,(size_t)count,sizeof(char*),cmp_str);
        SB sc;sb_init(&sc);
        sb_puts(&sc,"{\"keys\":[");
        for(int i=0;i<count;i++){if(i)sb_putc(&sc,',');sb_json_str(&sc,keys[i]);}
        sb_puts(&sc,"],\"count\":");
        char tmp[32];sprintf(tmp,"%d",count);sb_puts(&sc,tmp);
        sb_putc(&sc,'}');
        tool_success_struct(sb,id,sc.buf);
        free(sc.buf);free(keys);
    } else if(strcmp(td->name,"sum")==0){
        JV *jnums=obj_get(args,"numbers");
        int64_t s=0;int cnt=jnums->count;
        for(int i=0;i<cnt;i++)s+=(int64_t)jnums->items[i]->num;
        SB sc;sb_init(&sc);
        sb_puts(&sc,"{\"sum\":");
        char tmp[64];sprintf(tmp,"%lld",(long long)s);sb_puts(&sc,tmp);
        sb_puts(&sc,",\"count\":");
        sprintf(tmp,"%d",cnt);sb_puts(&sc,tmp);
        sb_putc(&sc,'}');
        tool_success_struct(sb,id,sc.buf);
        free(sc.buf);
    } else if(strcmp(td->name,"text_stats")==0){
        JV *jtext=obj_get(args,"text");
        const char *text=jtext->str;
        int w=count_words(text);
        int cp=count_codepoints(text);
        int by=(int)strlen(text);
        SB sc;sb_init(&sc);
        sb_puts(&sc,"{\"words\":");
        char tmp[32];sprintf(tmp,"%d",w);sb_puts(&sc,tmp);
        sb_puts(&sc,",\"codepoints\":");
        sprintf(tmp,"%d",cp);sb_puts(&sc,tmp);
        sb_puts(&sc,",\"utf8_bytes\":");
        sprintf(tmp,"%d",by);sb_puts(&sc,tmp);
        sb_putc(&sc,'}');
        tool_success_struct(sb,id,sc.buf);
        free(sc.buf);
    }
}

/* ============ Output tools/list ============ */
static void output_tools_list(SB *sb,JV *id){
    sb_init(sb);
    sb_puts(sb,"{\"jsonrpc\":\"2.0\",\"id\":");
    ser_id(sb,id);
    sb_puts(sb,",\"result\":{\"tools\":[");
    sb_puts(sb,"{\"name\":\"kv_set\",\"title\":\"Set a value\",\"description\":\"Store a string value under a key, replacing any previous value.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1},\"value\":{\"type\":\"string\"}},\"required\":[\"key\",\"value\"],\"additionalProperties\":false}}");
    sb_putc(sb,',');
    sb_puts(sb,"{\"name\":\"kv_get\",\"title\":\"Get a value\",\"description\":\"Return the value stored under a key.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1}},\"required\":[\"key\"],\"additionalProperties\":false}}");
    sb_putc(sb,',');
    sb_puts(sb,"{\"name\":\"kv_list\",\"title\":\"List keys\",\"description\":\"List the stored keys that start with a prefix, sorted by Unicode code point.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"prefix\":{\"type\":\"string\"}},\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"keys\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"count\":{\"type\":\"integer\"}},\"required\":[\"keys\",\"count\"]}}");
    sb_putc(sb,',');
    sb_puts(sb,"{\"name\":\"sum\",\"title\":\"Sum integers\",\"description\":\"Add up a non-empty list of integers.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"numbers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"minItems\":1}},\"required\":[\"numbers\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"sum\":{\"type\":\"integer\"},\"count\":{\"type\":\"integer\"}},\"required\":[\"sum\",\"count\"]},\"annotations\":{\"readOnlyHint\":true,\"idempotentHint\":true}}");
    sb_putc(sb,',');
    sb_puts(sb,"{\"name\":\"text_stats\",\"title\":\"Text statistics\",\"description\":\"Count the words, Unicode code points and UTF-8 bytes of a text.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"text\":{\"type\":\"string\"}},\"required\":[\"text\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"words\":{\"type\":\"integer\"},\"codepoints\":{\"type\":\"integer\"},\"utf8_bytes\":{\"type\":\"integer\"}},\"required\":[\"words\",\"codepoints\",\"utf8_bytes\"]},\"annotations\":{\"readOnlyHint\":true}}");
    sb_puts(sb,"]}}");
}

/* ============ Main ============ */
int main(void){
    int initialized=0;
    char *line=NULL;
    size_t linecap=0;
    ssize_t llen;

    while((llen=getline(&line,&linecap,stdin))!=-1){
        while(llen>0&&(line[llen-1]=='\n'||line[llen-1]=='\r'))llen--;
        line[llen]=0;

        int blank=1;
        for(ssize_t i=0;i<llen;i++){
            char c=line[i];
            if(c!=' '&&c!='\t'&&c!='\r'){blank=0;break;}
        }
        if(blank)continue;

        JV *msg=parse_json(line);
        if(!msg){
            SB sb;emit_error(&sb,NULL,-32700,"Parse error");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        if(msg->type!=J_OBJ){
            SB sb;emit_error(&sb,NULL,-32600,"Invalid Request");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        JV *jr=obj_get(msg,"jsonrpc");
        JV *jmethod=obj_get(msg,"method");
        JV *jresult=obj_get(msg,"result");
        JV *jerror=obj_get(msg,"error");

        if(!jmethod&&(jresult||jerror)){
            continue;
        }

        JV *id=obj_get(msg,"id");
        JV *valid_id=NULL;
        if(id){
            if(id->type==J_STR)valid_id=id;
            else if(id->type==J_NUM&&id->is_int)valid_id=id;
        }

        int invalid=0;
        if(!jr||jr->type!=J_STR||strcmp(jr->str,"2.0")!=0)invalid=1;
        if(!jmethod||jmethod->type!=J_STR)invalid=1;
        if(id&&!valid_id)invalid=1;

        if(invalid){
            SB sb;emit_error(&sb,valid_id,-32600,"Invalid Request");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        if(!id){
            continue;
        }

        const char *method=jmethod->str;

        if(strcmp(method,"initialize")!=0&&strcmp(method,"ping")!=0&&
           strcmp(method,"tools/list")!=0&&strcmp(method,"tools/call")!=0){
            SB sb;emit_error(&sb,valid_id,-32601,"Method not found");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        JV *params=obj_get(msg,"params");
        if(params&&params->type!=J_OBJ){
            SB sb;emit_error(&sb,valid_id,-32602,"Invalid params");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        if(!initialized&&strcmp(method,"initialize")!=0&&strcmp(method,"ping")!=0){
            SB sb;emit_error(&sb,valid_id,-32002,"Server not initialized");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
            continue;
        }

        if(strcmp(method,"initialize")==0){
            if(initialized){
                SB sb;emit_error(&sb,valid_id,-32600,"Already initialized");
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }
            if(!params){
                SB sb;emit_error(&sb,valid_id,-32602,"Invalid params");
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }
            JV *pv=obj_get(params,"protocolVersion");
            if(!pv||pv->type!=J_STR){
                SB sb;emit_error(&sb,valid_id,-32602,"Invalid params");
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }
            initialized=1;
            const char *ver=pv->str;
            const char *resp_ver;
            if(strcmp(ver,"2025-06-18")==0||strcmp(ver,"2025-03-26")==0||strcmp(ver,"2024-11-05")==0)
                resp_ver=ver;
            else resp_ver="2025-06-18";

            SB sb;sb_init(&sb);
            sb_puts(&sb,"{\"jsonrpc\":\"2.0\",\"id\":");
            ser_id(&sb,valid_id);
            sb_puts(&sb,",\"result\":{\"protocolVersion\":");
            sb_json_str(&sb,resp_ver);
            sb_puts(&sb,",\"capabilities\":{\"tools\":{\"listChanged\":false}},\"serverInfo\":{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
        }
        else if(strcmp(method,"ping")==0){
            SB sb;sb_init(&sb);
            sb_puts(&sb,"{\"jsonrpc\":\"2.0\",\"id\":");
            ser_id(&sb,valid_id);
            sb_puts(&sb,",\"result\":{}}");
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
        }
        else if(strcmp(method,"tools/list")==0){
            SB sb;output_tools_list(&sb,valid_id);
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
        }
        else if(strcmp(method,"tools/call")==0){
            JV *jname=params?obj_get(params,"name"):NULL;
            if(!jname||jname->type!=J_STR){
                SB sb;emit_error(&sb,valid_id,-32602,"Invalid params");
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }
            const char *tname=jname->str;

            ToolDef *td=NULL;
            for(int i=0;i<ntools;i++){
                if(strcmp(tools[i].name,tname)==0){td=&tools[i];break;}
            }
            if(!td){
                char buf[256];sprintf(buf,"Unknown tool: %s",tname);
                SB sb;emit_error(&sb,valid_id,-32602,buf);
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }

            JV *args=obj_get(params,"arguments");
            if(args&&args->type!=J_OBJ){
                SB sb;tool_fail(&sb,valid_id,"arguments must be an object");
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }

            char fail_buf[4096];
            if(!validate_args(args,td,fail_buf)){
                SB sb;tool_fail(&sb,valid_id,fail_buf);
                printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
                continue;
            }

            SB sb;
            JV *real_args=args?args:jv_new(J_OBJ);
            exec_tool(&sb,valid_id,td,real_args);
            printf("%s\n",sb.buf);fflush(stdout);free(sb.buf);
        }
    }

    free(line);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define BASE 1000000000ULL
#define MAX_LIMBS 50
#define MAX_DIGITS 500
#define MAX_ACC 10000
#define MAX_CURR 1000
#define MAX_REJ 10000
#define MAX_FIELDS 500

/* ---- BigInt (non-negative, base 10^9, least-significant limb first) ---- */
typedef struct { int n; uint32_t d[MAX_LIMBS]; } BI;

static void bi_norm(BI *a){ while(a->n>0&&a->d[a->n-1]==0) a->n--; }
static int  bi_zero(const BI *a){ return a->n==0; }
static int  bi_cmp(const BI *a,const BI *b){
    if(a->n!=b->n) return a->n<b->n?-1:1;
    for(int i=a->n-1;i>=0;i--) if(a->d[i]!=b->d[i]) return a->d[i]<b->d[i]?-1:1;
    return 0;
}
static void bi_add(BI *r,const BI *a,const BI *b){
    int n=(a->n>b->n?a->n:b->n)+1; uint64_t c=0;
    for(int i=0;i<n;i++){
        uint64_t s=(i<a->n?(uint64_t)a->d[i]:0)+(i<b->n?(uint64_t)b->d[i]:0)+c;
        r->d[i]=(uint32_t)(s%BASE); c=s/BASE;
    }
    r->n=n; bi_norm(r);
}
static void bi_sub(BI *r,const BI *a,const BI *b){ /* a>=b */
    r->n=a->n; uint64_t br=0;
    for(int i=0;i<r->n;i++){
        uint64_t da=a->d[i], db=i<b->n?b->d[i]:0;
        if(da-db<br){ r->d[i]=(uint32_t)(da-db+BASE-br); br=1; }
        else { r->d[i]=(uint32_t)(da-db-br); br=0; }
    }
    bi_norm(r);
}
static void bi_mul(BI *r,const BI *a,const BI *b){
    if(bi_zero(a)||bi_zero(b)){r->n=0;return;}
    int n=a->n+b->n; memset(r->d,0,n*sizeof(uint32_t));
    for(int i=0;i<a->n;i++){
        uint64_t c=0;
        for(int j=0;j<b->n;j++){
            uint64_t p=(uint64_t)a->d[i]*b->d[j]+r->d[i+j]+c;
            r->d[i+j]=(uint32_t)(p%BASE); c=p/BASE;
        }
        int k=i+b->n;
        while(c>0){uint64_t s=(uint64_t)r->d[k]+c;r->d[k]=(uint32_t)(s%BASE);c=s/BASE;k++;}
    }
    r->n=n; bi_norm(r);
}
static void bi_mul10(BI *r,const BI *a,int k){
    if(bi_zero(a)||k==0){*r=*a;return;}
    int ls=k/9,ds=k%9;
    static const uint32_t p10[]={1,10,100,1000,10000,100000,1000000,10000000,100000000};
    r->n=a->n+ls;
    for(int i=0;i<ls;i++) r->d[i]=0;
    for(int i=0;i<a->n;i++) r->d[i+ls]=a->d[i];
    if(ds>0){
        uint32_t m=p10[ds]; uint64_t c=0;
        for(int i=ls;i<r->n;i++){
            uint64_t p=(uint64_t)r->d[i]*m+c;
            r->d[i]=(uint32_t)(p%BASE); c=p/BASE;
        }
        if(c){r->d[r->n]=(uint32_t)c;r->n++;}
    }
    bi_norm(r);
}
static void bi_divmod(BI *q,BI *rem,const BI *a,const BI *b){
    if(bi_cmp(a,b)<0){q->n=0;*rem=*a;return;}
    int qlen=a->n-b->n+1;
    q->n=qlen; memset(q->d,0,qlen*sizeof(uint32_t));
    *rem=*a;
    for(int i=qlen-1;i>=0;i--){
        uint32_t bt=b->d[b->n-1];
        uint64_t rt;
        if(rem->n>i+b->n) rt=(uint64_t)rem->d[i+b->n]*BASE+rem->d[i+b->n-1];
        else if(rem->n>i+b->n-1) rt=rem->d[i+b->n-1];
        else{q->d[i]=0;continue;}
        uint64_t est=rt/bt; if(est>=BASE)est=BASE-1;
        while(est>0){
            uint32_t tmp[MAX_LIMBS]; uint64_t c=0; int tl=b->n;
            for(int j=0;j<b->n;j++){uint64_t p=(uint64_t)est*b->d[j]+c;tmp[j]=(uint32_t)(p%BASE);c=p/BASE;}
            if(c){tmp[tl]=(uint32_t)c;tl++;}
            int fits=1;
            if(tl>rem->n-i) fits=0;
            else for(int j=tl-1;j>=0;j--){
                uint32_t rl=i+j<rem->n?rem->d[i+j]:0;
                if(tmp[j]>rl){fits=0;break;} if(tmp[j]<rl)break;
            }
            if(fits)break; est--;
        }
        q->d[i]=(uint32_t)est;
        if(est>0){
            uint64_t c=0; int64_t br=0;
            for(int j=0;j<b->n;j++){
                uint64_t p=(uint64_t)est*b->d[j]+c; c=p/BASE;
                uint32_t s=(uint32_t)(p%BASE);
                int64_t df=(int64_t)rem->d[i+j]-s-br;
                if(df<0){df+=BASE;br=1;}else br=0;
                rem->d[i+j]=(uint32_t)df;
            }
            int k=i+b->n;
            while(c>0||br>0){
                int64_t df=(int64_t)rem->d[k]-(int64_t)c-br;
                if(df<0){df+=BASE;br=1;}else br=0;
                c=0; rem->d[k]=(uint32_t)df; k++;
            }
        }
        bi_norm(rem);
    }
    bi_norm(q);
}
static int bi_digits(const BI *a,int dg[]){
    if(bi_zero(a)){dg[0]=0;return 1;}
    int nd=0; BI t=*a;
    while(t.n>0){
        uint32_t lo=t.d[0];
        for(int i=0;i<9;i++){dg[nd++]=lo%10;lo/=10;}
        t.n--; memmove(t.d,t.d+1,t.n*sizeof(uint32_t));
    }
    while(nd>1&&dg[nd-1]==0) nd--;
    for(int i=0;i<nd/2;i++){int t2=dg[i];dg[i]=dg[nd-1-i];dg[nd-1-i]=t2;}
    return nd;
}

/* ---- Decimal ---- */
typedef struct { int sign; BI val; int dp; } Dec;

static void dz(Dec *d){d->sign=1;d->val.n=0;d->dp=0;}
static int  disz(const Dec *d){return bi_zero(&d->val);}
static int  disp(const Dec *d){return !bi_zero(&d->val)&&d->sign==1;}
static int  disn(const Dec *d){return !bi_zero(&d->val)&&d->sign==-1;}
static void dneg(Dec *r,const Dec *a){*r=*a;if(!bi_zero(&r->val))r->sign=-r->sign;}

static void dround(Dec *r,const Dec *a,int n){
    if(a->dp<=n){
        r->sign=a->sign; r->dp=n;
        if(a->dp<n) bi_mul10(&r->val,&a->val,n-a->dp); else r->val=a->val;
        if(bi_zero(&r->val))r->sign=1; return;
    }
    int k=a->dp-n;
    int dg[MAX_DIGITS]; int nd=bi_digits(&a->val,dg);
    int qnd=nd-k; if(qnd<0)qnd=0;
    int ru=0;
    if(k>0){
        int fd;
        if(nd<=k) fd=dg[0]; else fd=dg[nd-k];
        if(fd>5) ru=1;
        else if(fd==5){
            int nz=0; int st=(nd<=k)?1:nd-k+1;
            for(int i=st;i<nd;i++) if(dg[i]!=0){nz=1;break;}
            if(nz) ru=1;
            else if(nd>k){ if(dg[nd-k-1]%2!=0) ru=1; }
        }
    }
    BI q; q.n=0; memset(q.d,0,sizeof(q.d));
    for(int i=0;i<qnd;i++){
        uint64_t c=dg[i];
        for(int j=0;j<q.n;j++){uint64_t p=(uint64_t)q.d[j]*10+c;q.d[j]=(uint32_t)(p%BASE);c=p/BASE;}
        if(c){q.d[q.n]=(uint32_t)c;q.n++;}
    }
    if(ru){uint64_t c=1;int j=0;while(c>0){if(j>=q.n){q.d[j]=0;q.n=j+1;}uint64_t s=(uint64_t)q.d[j]+c;q.d[j]=(uint32_t)(s%BASE);c=s/BASE;j++;}}
    bi_norm(&q);
    r->val=q; r->dp=n; r->sign=a->sign;
    if(bi_zero(&r->val))r->sign=1;
}
static void dadd(Dec *r,const Dec *a,const Dec *b){
    int mdp=a->dp>b->dp?a->dp:b->dp;
    BI av,bv; bi_mul10(&av,&a->val,mdp-a->dp); bi_mul10(&bv,&b->val,mdp-b->dp);
    if(a->sign==b->sign){bi_add(&r->val,&av,&bv);r->sign=a->sign;}
    else{int c=bi_cmp(&av,&bv);if(c>=0){bi_sub(&r->val,&av,&bv);r->sign=a->sign;}else{bi_sub(&r->val,&bv,&av);r->sign=b->sign;}}
    r->dp=mdp; if(bi_zero(&r->val))r->sign=1;
}
static void dsub(Dec *r,const Dec *a,const Dec *b){Dec nb;dneg(&nb,b);dadd(r,a,&nb);}
static void dmul(Dec *r,const Dec *a,const Dec *b){
    bi_mul(&r->val,&a->val,&b->val); r->dp=a->dp+b->dp;
    r->sign=(a->sign==b->sign)?1:-1; if(bi_zero(&r->val))r->sign=1;
}

/* ---- Parse decimal string ---- */
static void pdec(Dec *d,const char *s){
    d->sign=1; d->dp=0; d->val.n=0; memset(d->val.d,0,sizeof(d->val.d));
    const char *p=s;
    if(*p=='-'){d->sign=-1;p++;}else if(*p=='+'){p++;}
    int ip=1;
    while(*p){
        if(*p=='.'){ip=0;p++;}
        else if(*p>='0'&&*p<='9'){
            uint64_t c=*p-'0';
            for(int j=0;j<d->val.n;j++){uint64_t pr=(uint64_t)d->val.d[j]*10+c;d->val.d[j]=(uint32_t)(pr%BASE);c=pr/BASE;}
            if(c){d->val.d[d->val.n]=(uint32_t)c;d->val.n++;}
            if(!ip)d->dp++;
            p++;
        } else break;
    }
    bi_norm(&d->val); if(bi_zero(&d->val))d->sign=1;
}

/* ---- Storage ---- */
typedef struct{char code[16];int minor;}Cur;
typedef struct{char name[256];int ci;Dec bal;Dec lim;}Acc;

static Cur cur[MAX_CURR]; static int ncur=0;
static Acc acc[MAX_ACC]; static int nacc=0;
static char rej[MAX_REJ][512]; static int nrej=0;

static int fcur(const char*c){for(int i=0;i<ncur;i++)if(!strcmp(cur[i].code,c))return i;return -1;}
static int facc(const char*n){for(int i=0;i<nacc;i++)if(!strcmp(acc[i].name,n))return i;return -1;}

/* ---- Format money ---- */
static void fmt(char *buf,const Dec *d,int minor){
    int dg[MAX_DIGITS]; int nd=bi_digits(&d->val,dg);
    while(nd<minor){memmove(dg+1,dg,nd*sizeof(int));dg[0]=0;nd++;}
    int pos=0;
    if(d->sign==-1&&!bi_zero(&d->val)) buf[pos++]='-';
    int il=nd-minor;
    if(il<=0){buf[pos++]='0';}
    else{for(int i=0;i<il;i++){if(i>0&&(il-i)%3==0)buf[pos++]=',';buf[pos++]='0'+dg[i];}}
    if(minor>0){buf[pos++]='.';for(int i=0;i<minor;i++){int idx=nd-minor+i;buf[pos++]='0'+(idx>=0&&idx<nd?dg[idx]:0);}}
    buf[pos]='\0';
}

/* ---- Tokenize ---- */
static int tok(char *ln,char *f[],int mx){
    int nf=0; char *p=ln;
    while(*p&&nf<mx){
        while(*p==' '||*p=='\t')p++;
        if(*p=='\0'||*p=='\n'||*p=='\r')break;
        f[nf++]=p;
        while(*p&&*p!=' '&&*p!='\t'&&*p!='\n'&&*p!='\r')p++;
        if(*p){*p=0;p++;}
    }
    return nf;
}

/* ---- Main ---- */
int main(int argc,char *argv[]){
    char path[512];
    snprintf(path,sizeof(path),"%s/ledger.txt",argv[1]);
    FILE *f=fopen(path,"r");
    if(!f)return 1;
    char ln[65536]; int lno=0;

    while(fgets(ln,sizeof(ln),f)){
        lno++;
        char *p=ln; while(*p==' '||*p=='\t')p++;
        if(*p=='\0'||*p=='\n'||*p=='\r'||*p=='#')continue;

        char *fd[MAX_FIELDS]; int nf=tok(ln,fd,MAX_FIELDS);
        if(nf==0)continue;
        const char *cmd=fd[0];

        if(!strcmp(cmd,"currency")){
            int ci=fcur(fd[1]);
            if(ci>=0)cur[ci].minor=atoi(fd[2]);
            else{ci=ncur++;strcpy(cur[ci].code,fd[1]);cur[ci].minor=atoi(fd[2]);}
        }
        else if(!strcmp(cmd,"open")){
            const char *an=fd[1];
            if(facc(an)>=0){snprintf(rej[nrej++],512,"line %d: REJECT account exists %s",lno,an);continue;}
            int ci=fcur(fd[2]); int mi=cur[ci].minor;
            Dec lim; dz(&lim);
            if(nf>=4){pdec(&lim,fd[3]);dround(&lim,&lim,mi);}
            int ai=nacc++; strcpy(acc[ai].name,an); acc[ai].ci=ci; dz(&acc[ai].bal); acc[ai].lim=lim;
        }
        else if(!strcmp(cmd,"deposit")){
            const char *an=fd[1]; int ai=facc(an);
            if(ai<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,an);continue;}
            Dec amt; pdec(&amt,fd[2]); int mi=cur[acc[ai].ci].minor; dround(&amt,&amt,mi);
            if(!disp(&amt)){snprintf(rej[nrej++],512,"line %d: REJECT non-positive amount",lno);continue;}
            dadd(&acc[ai].bal,&acc[ai].bal,&amt);
        }
        else if(!strcmp(cmd,"withdraw")){
            const char *an=fd[1]; int ai=facc(an);
            if(ai<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,an);continue;}
            Dec amt; pdec(&amt,fd[2]); int mi=cur[acc[ai].ci].minor; dround(&amt,&amt,mi);
            if(!disp(&amt)){snprintf(rej[nrej++],512,"line %d: REJECT non-positive amount",lno);continue;}
            Dec nb,chk; dsub(&nb,&acc[ai].bal,&amt); dadd(&chk,&nb,&acc[ai].lim);
            if(disn(&chk)){snprintf(rej[nrej++],512,"line %d: REJECT insufficient funds %s",lno,an);continue;}
            acc[ai].bal=nb;
        }
        else if(!strcmp(cmd,"transfer")){
            const char *fn=fd[1],*tn=fd[2];
            int fi=facc(fn),ti=facc(tn);
            if(fi<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,fn);continue;}
            if(ti<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,tn);continue;}
            if(acc[fi].ci!=acc[ti].ci){snprintf(rej[nrej++],512,"line %d: REJECT currency mismatch",lno);continue;}
            Dec amt; pdec(&amt,fd[3]); int mi=cur[acc[fi].ci].minor; dround(&amt,&amt,mi);
            if(!disp(&amt)){snprintf(rej[nrej++],512,"line %d: REJECT non-positive amount",lno);continue;}
            Dec nb,chk; dsub(&nb,&acc[fi].bal,&amt); dadd(&chk,&nb,&acc[fi].lim);
            if(disn(&chk)){snprintf(rej[nrej++],512,"line %d: REJECT insufficient funds %s",lno,fn);continue;}
            acc[fi].bal=nb; dadd(&acc[ti].bal,&acc[ti].bal,&amt);
        }
        else if(!strcmp(cmd,"convert")){
            const char *fn=fd[1],*tn=fd[2];
            int fi=facc(fn),ti=facc(tn);
            if(fi<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,fn);continue;}
            if(ti<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,tn);continue;}
            Dec amt; pdec(&amt,fd[3]); int fmi=cur[acc[fi].ci].minor; dround(&amt,&amt,fmi);
            if(!disp(&amt)){snprintf(rej[nrej++],512,"line %d: REJECT non-positive amount",lno);continue;}
            Dec nb,chk; dsub(&nb,&acc[fi].bal,&amt); dadd(&chk,&nb,&acc[fi].lim);
            if(disn(&chk)){snprintf(rej[nrej++],512,"line %d: REJECT insufficient funds %s",lno,fn);continue;}
            Dec rate,recv; pdec(&rate,fd[4]); dmul(&recv,&amt,&rate);
            int tmi=cur[acc[ti].ci].minor; dround(&recv,&recv,tmi);
            acc[fi].bal=nb; dadd(&acc[ti].bal,&acc[ti].bal,&recv);
        }
        else if(!strcmp(cmd,"interest")){
            const char *an=fd[1]; int ai=facc(an);
            if(ai<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,an);continue;}
            Dec rate,gain; pdec(&rate,fd[2]); dmul(&gain,&acc[ai].bal,&rate);
            int mi=cur[acc[ai].ci].minor; dround(&gain,&gain,mi);
            dadd(&acc[ai].bal,&acc[ai].bal,&gain);
        }
        else if(!strcmp(cmd,"split")){
            const char *fn=fd[1]; int fi=facc(fn);
            if(fi<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,fn);continue;}
            int mi=cur[acc[fi].ci].minor;
            int nt=nf-3;
            int ti_arr[MAX_FIELDS]; BI wbi[MAX_FIELDS];
            int bad=0;
            for(int i=0;i<nt;i++){
                char *cp=strchr(fd[3+i],':');
                char tnb[256]; int tl=cp-fd[3+i]; memcpy(tnb,fd[3+i],tl); tnb[tl]=0;
                int ti=facc(tnb);
                if(ti<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,tnb);bad=1;break;}
                ti_arr[i]=ti;
                Dec wd; pdec(&wd,cp+1); wbi[i]=wd.val;
            }
            if(bad)continue;
            for(int i=0;i<nt;i++){
                if(acc[ti_arr[i]].ci!=acc[fi].ci){snprintf(rej[nrej++],512,"line %d: REJECT currency mismatch",lno);bad=1;break;}
            }
            if(bad)continue;
            Dec amt; pdec(&amt,fd[2]); dround(&amt,&amt,mi);
            if(!disp(&amt)){snprintf(rej[nrej++],512,"line %d: REJECT non-positive amount",lno);continue;}
            Dec nb,chk; dsub(&nb,&acc[fi].bal,&amt); dadd(&chk,&nb,&acc[fi].lim);
            if(disn(&chk)){snprintf(rej[nrej++],512,"line %d: REJECT insufficient funds %s",lno,fn);continue;}
            BI W; W.n=0;
            for(int i=0;i<nt;i++) bi_add(&W,&W,&wbi[i]);
            BI Ai=amt.val;
            BI shares[MAX_FIELDS],rems[MAX_FIELDS],tsh; tsh.n=0;
            for(int i=0;i<nt;i++){
                BI pr; bi_mul(&pr,&Ai,&wbi[i]);
                bi_divmod(&shares[i],&rems[i],&pr,&W);
                bi_add(&tsh,&tsh,&shares[i]);
            }
            BI lo; bi_sub(&lo,&Ai,&tsh);
            int nleft=bi_zero(&lo)?0:(int)lo.d[0];
            int order[MAX_FIELDS]; for(int i=0;i<nt;i++)order[i]=i;
            for(int i=0;i<nt-1;i++)for(int j=0;j<nt-1-i;j++){
                if(bi_cmp(&rems[order[j]],&rems[order[j+1]])<0){int t=order[j];order[j]=order[j+1];order[j+1]=t;}
            }
            BI one; one.n=1; one.d[0]=1;
            for(int i=0;i<nleft;i++) bi_add(&shares[order[i]],&shares[order[i]],&one);
            acc[fi].bal=nb;
            for(int i=0;i<nt;i++){
                if(!bi_zero(&shares[i])){
                    Dec sd; sd.sign=1; sd.val=shares[i]; sd.dp=mi;
                    dadd(&acc[ti_arr[i]].bal,&acc[ti_arr[i]].bal,&sd);
                }
            }
        }
    }
    fclose(f);

    /* Output rejections */
    for(int i=0;i<nrej;i++) printf("%s\n",rej[i]);
    printf("\n");

    /* Sort accounts by name */
    for(int i=1;i<nacc;i++){
        Acc tmp=acc[i]; int j=i-1;
        while(j>=0&&strcmp(acc[j].name,tmp.name)>0){acc[j+1]=acc[j];j--;}
        acc[j+1]=tmp;
    }
    for(int i=0;i<nacc;i++){
        char buf[256]; fmt(buf,&acc[i].bal,cur[acc[i].ci].minor);
        printf("%s %s %s\n",acc[i].name,cur[acc[i].ci].code,buf);
    }
    printf("\n");

    /* Currency totals */
    /* Collect currencies with at least one account */
    int in_use[MAX_CURR]={0}; Dec tot[MAX_CURR];
    int cnt[MAX_CURR]={0};
    for(int i=0;i<nacc;i++){
        int ci=acc[i].ci;
        if(!in_use[ci]){in_use[ci]=1;dz(&tot[ci]);}
        dadd(&tot[ci],&tot[ci],&acc[i].bal);
        cnt[ci]++;
    }
    /* Collect and sort by code */
    int cidx[MAX_CURR],nc=0;
    for(int i=0;i<ncur;i++) if(in_use[i]) cidx[nc++]=i;
    for(int i=1;i<nc;i++){int tmp=cidx[i];int j=i-1;while(j>=0&&strcmp(cur[cidx[j]].code,cur[tmp].code)>0){cidx[j+1]=cidx[j];j--;}cidx[j+1]=tmp;}
    for(int i=0;i<nc;i++){
        int ci=cidx[i]; char buf[256]; fmt(buf,&tot[ci],cur[ci].minor);
        printf("total %s %s (%d accounts)\n",cur[ci].code,buf,cnt[ci]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define BASE 1000000000ULL
#define MAX_LIMBS 50
#define MAX_DIGITS 500
#define MAX_ACC 10000
#define MAX_CURR 1000
#define MAX_REJ 10000
#define MAX_FIELDS 500

/* ---- BigInt (non-negative, base 10^9, least-significant limb first) ---- */
typedef struct { int n; uint32_t d[MAX_LIMBS]; } BI;

static void bi_norm(BI *a){ while(a->n>0&&a->d[a->n-1]==0) a->n--; }
static int  bi_zero(const BI *a){ return a->n==0; }
static int  bi_cmp(const BI *a,const BI *b){
    if(a->n!=b->n) return a->n<b->n?-1:1;
    for(int i=a->n-1;i>=0;i--) if(a->d[i]!=b->d[i]) return a->d[i]<b->d[i]?-1:1;
    return 0;
}
static void bi_add(BI *r,const BI *a,const BI *b){
    int n=(a->n>b->n?a->n:b->n)+1; uint64_t c=0;
    for(int i=0;i<n;i++){
        uint64_t s=(i<a->n?(uint64_t)a->d[i]:0)+(i<b->n?(uint64_t)b->d[i]:0)+c;
        r->d[i]=(uint32_t)(s%BASE); c=s/BASE;
    }
    r->n=n; bi_norm(r);
}
static void bi_sub(BI *r,const BI *a,const BI *b){ /* a>=b */
    r->n=a->n; uint64_t br=0;
    for(int i=0;i<r->n;i++){
        uint64_t da=a->d[i], db=i<b->n?b->d[i]:0;
        if(da-db<br){ r->d[i]=(uint32_t)(da-db+BASE-br); br=1; }
        else { r->d[i]=(uint32_t)(da-db-br); br=0; }
    }
    bi_norm(r);
}
static void bi_mul(BI *r,const BI *a,const BI *b){
    if(bi_zero(a)||bi_zero(b)){r->n=0;return;}
    int n=a->n+b->n; memset(r->d,0,n*sizeof(uint32_t));
    for(int i=0;i<a->n;i++){
        uint64_t c=0;
        for(int j=0;j<b->n;j++){
            uint64_t p=(uint64_t)a->d[i]*b->d[j]+r->d[i+j]+c;
            r->d[i+j]=(uint32_t)(p%BASE); c=p/BASE;
        }
        int k=i+b->n;
        while(c>0){uint64_t s=(uint64_t)r->d[k]+c;r->d[k]=(uint32_t)(s%BASE);c=s/BASE;k++;}
    }
    r->n=n; bi_norm(r);
}
static void bi_mul10(BI *r,const BI *a,int k){
    if(bi_zero(a)||k==0){*r=*a;return;}
    int ls=k/9,ds=k%9;
    static const uint32_t p10[]={1,10,100,1000,10000,100000,1000000,10000000,100000000};
    r->n=a->n+ls;
    for(int i=0;i<ls;i++) r->d[i]=0;
    for(int i=0;i<a->n;i++) r->d[i+ls]=a->d[i];
    if(ds>0){
        uint32_t m=p10[ds]; uint64_t c=0;
        for(int i=ls;i<r->n;i++){
            uint64_t p=(uint64_t)r->d[i]*m+c;
            r->d[i]=(uint32_t)(p%BASE); c=p/BASE;
        }
        if(c){r->d[r->n]=(uint32_t)c;r->n++;}
    }
    bi_norm(r);
}

static void bi_divmod(BI *q,BI *rem,const BI *a,const BI *b){
    if(bi_cmp(a,b)<0){q->n=0;*rem=*a;return;}
    if(bi_zero(b)){q->n=0;rem->n=0;return;}

    /* Normalize: multiply both by k so b's top limb >= BASE/2 */
    uint32_t d_top = b->d[b->n-1];
    uint32_t k = (uint32_t)((BASE + 2ULL*d_top - 1) / (2ULL*d_top));

    BI an, bn;
    if(k==1){ an=*a; bn=*b; }
    else {
        BI kb; kb.n=1; kb.d[0]=k;
        bi_mul(&an,a,&kb);
        bi_mul(&bn,b,&kb);
    }

    int qlen = an.n - bn.n + 1;
    q->n=qlen; memset(q->d,0,qlen*sizeof(uint32_t));
    BI r; r=an;

    for(int i=qlen-1;i>=0;i--){
        uint32_t bt=bn.d[bn.n-1]; /* >= BASE/2 */
        uint64_t rt;
        if(i+bn.n < r.n) rt=(uint64_t)r.d[i+bn.n]*BASE+r.d[i+bn.n-1];
        else if(i+bn.n-1 < r.n) rt=r.d[i+bn.n-1];
        else { q->d[i]=0; continue; }

        uint64_t est=rt/bt; if(est>=BASE)est=BASE-1;

        while(est>0){
            uint32_t tmp[MAX_LIMBS+1]; uint64_t c=0; int tl=bn.n;
            for(int j=0;j<bn.n;j++){uint64_t p=(uint64_t)est*bn.d[j]+c;tmp[j]=(uint32_t)(p%BASE);c=p/BASE;}
            if(c) tmp[tl++]=(uint32_t)c;

            int fits=1;
            if(tl > r.n - i){ fits=0; }
            else if(tl == r.n - i){
                for(int j=tl-1;j>=0;j--){
                    if(tmp[j]>r.d[i+j]){fits=0;break;}
                    if(tmp[j]<r.d[i+j])break;
                }
            }
            /* tl < r.n-i: automatically fits */
            if(fits)break;
            est--;
        }
        q->d[i]=(uint32_t)est;

        if(est>0){
            uint64_t c=0; int64_t br=0;
            for(int j=0;j<bn.n;j++){
                uint64_t p=(uint64_t)est*bn.d[j]+c; c=p/BASE;
                uint32_t s=(uint32_t)(p%BASE);
                uint32_t rv=(i+j<r.n)?r.d[i+j]:0;
                int64_t df=(int64_t)rv-(int64_t)s-br;
                if(df<0){df+=(int64_t)BASE;br=1;}else br=0;
                r.d[i+j]=(uint32_t)df;
            }
            int kk=i+bn.n;
            while(c>0||br>0){
                uint32_t rv=(kk<r.n)?r.d[kk]:0;
                int64_t df=(int64_t)rv-(int64_t)c-br;
                if(df<0){df+=(int64_t)BASE;br=1;}else br=0;
                c=0; r.d[kk]=(uint32_t)df; kk++;
            }
            if(kk>r.n) r.n=kk;
        }
        bi_norm(&r);
    }
    bi_norm(q);

    /* true remainder = a - q*b */
    BI qb;
    bi_mul(&qb,q,b);
    bi_sub(rem,a,&qb);
}

static int bi_digits(const BI *a,int dg[]){
    if(bi_zero(a)){dg[0]=0;return 1;}
    int nd=0; BI t=*a;
    while(t.n>0){
        uint32_t lo=t.d[0];
        for(int i=0;i<9;i++){dg[nd++]=lo%10;lo/=10;}
        t.n--; memmove(t.d,t.d+1,t.n*sizeof(uint32_t));
    }
    while(nd>1&&dg[nd-1]==0) nd--;
    for(int i=0;i<nd/2;i++){int t2=dg[i];dg[i]=dg[nd-1-i];dg[nd-1-i]=t2;}
    return nd;
}

/* ---- Decimal ---- */
typedef struct { int sign; BI val; int dp; } Dec;

static void dz(Dec *d){d->sign=1;d->val.n=0;d->dp=0;}
static int  disz(const Dec *d){return bi_zero(&d->val);}
static int  disp(const Dec *d){return !bi_zero(&d->val)&&d->sign==1;}
static int  disn(const Dec *d){return !bi_zero(&d->val)&&d->sign==-1;}
static void dneg(Dec *r,const Dec *a){*r=*a;if(!bi_zero(&r->val))r->sign=-r->sign;}

static void dround(Dec *r,const Dec *a,int n){
    if(a->dp<=n){
        r->sign=a->sign; r->dp=n;
        if(a->dp<n) bi_mul10(&r->val,&a->val,n-a->dp); else r->val=a->val;
        if(bi_zero(&r->val))r->sign=1; return;
    }
    int k=a->dp-n;
    int dg[MAX_DIGITS]; int nd=bi_digits(&a->val,dg);
    int qnd=nd-k; if(qnd<0)qnd=0;
    int ru=0;
    if(k>0){
        int fd;
        if(nd<=k) fd=dg[0]; else fd=dg[nd-k];
        if(fd>5) ru=1;
        else if(fd==5){
            int nz=0; int st=(nd<=k)?1:nd-k+1;
            for(int i=st;i<nd;i++) if(dg[i]!=0){nz=1;break;}
            if(nz) ru=1;
            else if(nd>k){ if(dg[nd-k-1]%2!=0) ru=1; }
        }
    }
    BI q; q.n=0; memset(q.d,0,sizeof(q.d));
    for(int i=0;i<qnd;i++){
        uint64_t c=dg[i];
        for(int j=0;j<q.n;j++){uint64_t p=(uint64_t)q.d[j]*10+c;q.d[j]=(uint32_t)(p%BASE);c=p/BASE;}
        if(c){q.d[q.n]=(uint32_t)c;q.n++;}
    }
    if(ru){uint64_t c=1;int j=0;while(c>0){if(j>=q.n){q.d[j]=0;q.n=j+1;}uint64_t s=(uint64_t)q.d[j]+c;q.d[j]=(uint32_t)(s%BASE);c=s/BASE;j++;}}
    bi_norm(&q);
    r->val=q; r->dp=n; r->sign=a->sign;
    if(bi_zero(&r->val))r->sign=1;
}
static void dadd(Dec *r,const Dec *a,const Dec *b){
    int mdp=a->dp>b->dp?a->dp:b->dp;
    BI av,bv; bi_mul10(&av,&a->val,mdp-a->dp); bi_mul10(&bv,&b->val,mdp-b->dp);
    if(a->sign==b->sign){bi_add(&r->val,&av,&bv);r->sign=a->sign;}
    else{int c=bi_cmp(&av,&bv);if(c>=0){bi_sub(&r->val,&av,&bv);r->sign=a->sign;}else{bi_sub(&r->val,&bv,&av);r->sign=b->sign;}}
    r->dp=mdp; if(bi_zero(&r->val))r->sign=1;
}
static void dsub(Dec *r,const Dec *a,const Dec *b){Dec nb;dneg(&nb,b);dadd(r,a,&nb);}
static void dmul(Dec *r,const Dec *a,const Dec *b){
    bi_mul(&r->val,&a->val,&b->val); r->dp=a->dp+b->dp;
    r->sign=(a->sign==b->sign)?1:-1; if(bi_zero(&r->val))r->sign=1;
}

/* ---- Parse decimal string ---- */
static void pdec(Dec *d,const char *s){
    d->sign=1; d->dp=0; d->val.n=0; memset(d->val.d,0,sizeof(d->val.d));
    const char *p=s;
    if(*p=='-'){d->sign=-1;p++;}else if(*p=='+'){p++;}
    int ip=1;
    while(*p){
        if(*p=='.'){ip=0;p++;}
        else if(*p>='0'&&*p<='9'){
            uint64_t c=*p-'0';
            for(int j=0;j<d->val.n;j++){uint64_t pr=(uint64_t)d->val.d[j]*10+c;d->val.d[j]=(uint32_t)(pr%BASE);c=pr/BASE;}
            if(c){d->val.d[d->val.n]=(uint32_t)c;d->val.n++;}
            if(!ip)d->dp++;
            p++;
        } else break;
    }
    bi_norm(&d->val); if(bi_zero(&d->val))d->sign=1;
}

/* ---- Parse positive integer (for weights) ---- */
static void pint(BI *r,const char *s){
    r->n=0; memset(r->d,0,sizeof(r->d));
    for(;*s>='0'&&*s<='9';s++){
        uint64_t c=*s-'0';
        for(int j=0;j<r->n;j++){uint64_t p=(uint64_t)r->d[j]*10+c;r->d[j]=(uint32_t)(p%BASE);c=p/BASE;}
        if(c){r->d[r->n]=(uint32_t)c;r->n++;}
    }
    bi_norm(r);
}

/* ---- Storage ---- */
typedef struct{char code[16];int minor;}Cur;
typedef struct{char name[256];int ci;Dec bal;Dec lim;}Acc;

static Cur cur[MAX_CURR]; static int ncur=0;
static Acc acc[MAX_ACC]; static int nacc=0;
static char rej[MAX_REJ][512]; static int nrej=0;

static int fcur(const char*c){for(int i=0;i<ncur;i++)if(!strcmp(cur[i].code,c))return i;return -1;}
static int facc(const char*n){for(int i=0;i<nacc;i++)if(!strcmp(acc[i].name,n))return i;return -1;}

/* ---- Format money ---- */
static void fmt(char *buf,const Dec *d,int minor){
    int dg[MAX_DIGITS]; int nd=bi_digits(&d->val,dg);
    while(nd<minor){memmove(dg+1,dg,nd*sizeof(int));dg[0]=0;nd++;}
    int pos=0;
    if(d->sign==-1&&!bi_zero(&d->val)) buf[pos++]='-';
    int il=nd-minor;
    if(il<=0){buf[pos++]='0';}
    else{for(int i=0;i<il;i++){if(i>0&&(il-i)%3==0)buf[pos++]=',';buf[pos++]='0'+dg[i];}}
    if(minor>0){buf[pos++]='.';for(int i=0;i<minor;i++){int idx=nd-minor+i;buf[pos++]='0'+(idx>=0&&idx<nd?dg[idx]:0);}}
    buf[pos]='\0';
}

/* ---- Tokenize ---- */
static int tok(char *ln,char *f[],int mx){
    int nf=0; char *p=ln;
    while(*p&&nf<mx){
        while(*p==' '||*p=='\t')p++;
        if(*p=='\0'||*p=='\n'||*p=='\r')break;
        f[nf++]=p;
        while(*p&&*p!=' '&&*p!='\t'&&*p!='\n'&&*p!='\r')p++;
        if(*p){*p=0;p++;}
    }
    return nf;
}

/* ---- Main ---- */
int main(int argc,char *argv[]){
    char path[512];
    snprintf(path,sizeof(path),"%s/ledger.txt",argv[1]);
    FILE *f=fopen(path,"r");
    if(!f)return 1;
    char ln[65536]; int lno=0;

    while(fgets(ln,sizeof(ln),f)){
        lno++;
        char *p=ln; while(*p==' '||*p=='\t')p++;
        if(*p=='\0'||*p=='\n'||*p=='\r'||*p=='#')continue;

        char *fd[MAX_FIELDS]; int nf=tok(ln,fd,MAX_FIELDS);
        if(nf==0)continue;
        const char *cmd=fd[0];

        if(!strcmp(cmd,"currency")){
            int ci=fcur(fd[1]);
            if(ci>=0)cur[ci].minor=atoi(fd[2]);
            else{ci=ncur++;strcpy(cur[ci].code,fd[1]);cur[ci].minor=atoi(fd[2]);}
        }
        else if(!strcmp(cmd,"open")){
            const char *an=fd[1];
            if(facc(an)>=0){snprintf(rej[nrej++],512,"line %d: REJECT account exists %s",lno,an);continue;}
            int ci=fcur(fd[2]); int mi=cur[ci].minor;
            Dec lim; dz(&lim);
            if(nf>=4){pdec(&lim,fd[3]);dround(&lim,&lim,mi);}
            int ai=nacc++; strcpy(acc[ai].name,an); acc[ai].ci=ci; dz(&acc[ai].bal); acc[ai].lim=lim;
        }
        else if(!strcmp(cmd,"deposit")){
            const char *an=fd[1]; int ai=facc(an);
            if(ai<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,an);continue;}
            Dec amt; pdec(&amt,fd[2]); int mi=cur[acc[ai].ci].minor; dround(&amt,&amt,mi);
            if(!disp(&amt)){snprintf(rej[nrej++],512,"line %d: REJECT non-positive amount",lno);continue;}
            dadd(&acc[ai].bal,&acc[ai].bal,&amt);
        }
        else if(!strcmp(cmd,"withdraw")){
            const char *an=fd[1]; int ai=facc(an);
            if(ai<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,an);continue;}
            Dec amt; pdec(&amt,fd[2]); int mi=cur[acc[ai].ci].minor; dround(&amt,&amt,mi);
            if(!disp(&amt)){snprintf(rej[nrej++],512,"line %d: REJECT non-positive amount",lno);continue;}
            Dec nb,chk; dsub(&nb,&acc[ai].bal,&amt); dadd(&chk,&nb,&acc[ai].lim);
            if(disn(&chk)){snprintf(rej[nrej++],512,"line %d: REJECT insufficient funds %s",lno,an);continue;}
            acc[ai].bal=nb;
        }
        else if(!strcmp(cmd,"transfer")){
            const char *fn=fd[1],*tn=fd[2];
            int fi=facc(fn),ti=facc(tn);
            if(fi<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,fn);continue;}
            if(ti<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,tn);continue;}
            if(acc[fi].ci!=acc[ti].ci){snprintf(rej[nrej++],512,"line %d: REJECT currency mismatch",lno);continue;}
            Dec amt; pdec(&amt,fd[3]); int mi=cur[acc[fi].ci].minor; dround(&amt,&amt,mi);
            if(!disp(&amt)){snprintf(rej[nrej++],512,"line %d: REJECT non-positive amount",lno);continue;}
            Dec nb,chk; dsub(&nb,&acc[fi].bal,&amt); dadd(&chk,&nb,&acc[fi].lim);
            if(disn(&chk)){snprintf(rej[nrej++],512,"line %d: REJECT insufficient funds %s",lno,fn);continue;}
            acc[fi].bal=nb; dadd(&acc[ti].bal,&acc[ti].bal,&amt);
        }
        else if(!strcmp(cmd,"convert")){
            const char *fn=fd[1],*tn=fd[2];
            int fi=facc(fn),ti=facc(tn);
            if(fi<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,fn);continue;}
            if(ti<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,tn);continue;}
            Dec amt; pdec(&amt,fd[3]); int fmi=cur[acc[fi].ci].minor; dround(&amt,&amt,fmi);
            if(!disp(&amt)){snprintf(rej[nrej++],512,"line %d: REJECT non-positive amount",lno);continue;}
            Dec nb,chk; dsub(&nb,&acc[fi].bal,&amt); dadd(&chk,&nb,&acc[fi].lim);
            if(disn(&chk)){snprintf(rej[nrej++],512,"line %d: REJECT insufficient funds %s",lno,fn);continue;}
            Dec rate,recv; pdec(&rate,fd[4]); dmul(&recv,&amt,&rate);
            int tmi=cur[acc[ti].ci].minor; dround(&recv,&recv,tmi);
            acc[fi].bal=nb; dadd(&acc[ti].bal,&acc[ti].bal,&recv);
        }
        else if(!strcmp(cmd,"interest")){
            const char *an=fd[1]; int ai=facc(an);
            if(ai<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,an);continue;}
            Dec rate,gain; pdec(&rate,fd[2]); dmul(&gain,&acc[ai].bal,&rate);
            int mi=cur[acc[ai].ci].minor; dround(&gain,&gain,mi);
            dadd(&acc[ai].bal,&acc[ai].bal,&gain);
        }
        else if(!strcmp(cmd,"split")){
            const char *fn=fd[1]; int fi=facc(fn);
            if(fi<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,fn);continue;}
            int mi=cur[acc[fi].ci].minor;
            int nt=nf-3;
            int ti_arr[MAX_FIELDS]; BI wbi[MAX_FIELDS];
            int bad=0;
            for(int i=0;i<nt;i++){
                char *cp=strchr(fd[3+i],':');
                if(!cp){bad=1;break;}
                char tnb[256]; int tl=cp-fd[3+i]; memcpy(tnb,fd[3+i],tl); tnb[tl]=0;
                int ti=facc(tnb);
                if(ti<0){snprintf(rej[nrej++],512,"line %d: REJECT unknown account %s",lno,tnb);bad=1;break;}
                ti_arr[i]=ti;
                pint(&wbi[i],cp+1);
            }
            if(bad)continue;
            for(int i=0;i<nt;i++){
                if(acc[ti_arr[i]].ci!=acc[fi].ci){snprintf(rej[nrej++],512,"line %d: REJECT currency mismatch",lno);bad=1;break;}
            }
            if(bad)continue;
            Dec amt; pdec(&amt,fd[2]); dround(&amt,&amt,mi);
            if(!disp(&amt)){snprintf(rej[nrej++],512,"line %d: REJECT non-positive amount",lno);continue;}
            Dec nb,chk; dsub(&nb,&acc[fi].bal,&amt); dadd(&chk,&nb,&acc[fi].lim);
            if(disn(&chk)){snprintf(rej[nrej++],512,"line %d: REJECT insufficient funds %s",lno,fn);continue;}
            BI W; W.n=0; memset(W.d,0,sizeof(W.d));
            for(int i=0;i<nt;i++) bi_add(&W,&W,&wbi[i]);
            BI Ai=amt.val;
            BI shares[MAX_FIELDS],rems[MAX_FIELDS],tsh; tsh.n=0; memset(tsh.d,0,sizeof(tsh.d));
            for(int i=0;i<nt;i++){
                BI pr; bi_mul(&pr,&Ai,&wbi[i]);
                bi_divmod(&shares[i],&rems[i],&pr,&W);
                bi_add(&tsh,&tsh,&shares[i]);
            }
            BI lo; bi_sub(&lo,&Ai,&tsh);
            int nleft=bi_zero(&lo)?0:(int)lo.d[0];
            int order[MAX_FIELDS]; for(int i=0;i<nt;i++)order[i]=i;
            for(int i=0;i<nt-1;i++)for(int j=0;j<nt-1-i;j++){
                if(bi_cmp(&rems[order[j]],&rems[order[j+1]])<0){int t=order[j];order[j]=order[j+1];order[j+1]=t;}
            }
            BI one; one.n=1; one.d[0]=1;
            for(int i=0;i<nleft;i++) bi_add(&shares[order[i]],&shares[order[i]],&one);
            acc[fi].bal=nb;
            for(int i=0;i<nt;i++){
                if(!bi_zero(&shares[i])){
                    Dec sd; sd.sign=1; sd.val=shares[i]; sd.dp=mi;
                    dadd(&acc[ti_arr[i]].bal,&acc[ti_arr[i]].bal,&sd);
                }
            }
        }
    }
    fclose(f);

    /* Output rejections */
    for(int i=0;i<nrej;i++) printf("%s\n",rej[i]);
    printf("\n");

    /* Sort accounts by name */
    for(int i=1;i<nacc;i++){
        Acc tmp=acc[i]; int j=i-1;
        while(j>=0&&strcmp(acc[j].name,tmp.name)>0){acc[j+1]=acc[j];j--;}
        acc[j+1]=tmp;
    }
    for(int i=0;i<nacc;i++){
        char buf[256]; fmt(buf,&acc[i].bal,cur[acc[i].ci].minor);
        printf("%s %s %s\n",acc[i].name,cur[acc[i].ci].code,buf);
    }
    printf("\n");

    /* Currency totals */
    int in_use[MAX_CURR]={0}; Dec tot[MAX_CURR];
    int cnt[MAX_CURR]={0};
    for(int i=0;i<nacc;i++){
        int ci=acc[i].ci;
        if(!in_use[ci]){in_use[ci]=1;dz(&tot[ci]);}
        dadd(&tot[ci],&tot[ci],&acc[i].bal);
        cnt[ci]++;
    }
    int cidx[MAX_CURR],nc=0;
    for(int i=0;i<ncur;i++) if(in_use[i]) cidx[nc++]=i;
    for(int i=1;i<nc;i++){int tmp=cidx[i];int j=i-1;while(j>=0&&strcmp(cur[cidx[j]].code,cur[tmp].code)>0){cidx[j+1]=cidx[j];j--;}cidx[j+1]=tmp;}
    for(int i=0;i<nc;i++){
        int ci=cidx[i]; char buf[256]; fmt(buf,&tot[ci],cur[ci].minor);
        printf("total %s %s (%d accounts)\n",cur[ci].code,buf,cnt[ci]);
    }

    return 0;
}

use std::io::{self, BufRead, Write};

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }

    fn parse_value(&mut self) -> Result<JsonValue, ()> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string().map(JsonValue::Str),
            Some(b't') => self.parse_true(),
            Some(b'f') => self.parse_false(),
            Some(b'n') => self.parse_null(),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err(()),
        }
    }

    fn parse_true(&mut self) -> Result<JsonValue, ()> {
        if self.pos + 4 <= self.input.len() && &self.input[self.pos..self.pos+4] == b"true" {
            self.pos += 4;
            Ok(JsonValue::Bool(true))
        } else { Err(()) }
    }

    fn parse_false(&mut self) -> Result<JsonValue, ()> {
        if self.pos + 5 <= self.input.len() && &self.input[self.pos..self.pos+5] == b"false" {
            self.pos += 5;
            Ok(JsonValue::Bool(false))
        } else { Err(()) }
    }

    fn parse_null(&mut self) -> Result<JsonValue, ()> {
        if self.pos + 4 <= self.input.len() && &self.input[self.pos..self.pos+4] == b"null" {
            self.pos += 4;
            Ok(JsonValue::Null)
        } else { Err(()) }
    }

    fn parse_number(&mut self) -> Result<JsonValue, ()> {
        let start = self.pos;
        let mut is_float = false;
        if self.peek() == Some(b'-') { self.pos += 1; }
        if self.peek() == Some(b'0') {
            self.pos += 1;
        } else if self.peek().map_or(false, |c| c.is_ascii_digit()) {
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        } else { return Err(()); }
        if self.peek() == Some(b'.') {
            is_float = true;
            self.pos += 1;
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) { return Err(()); }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        }
        if self.peek() == Some(b'e') || self.peek() == Some(b'E') {
            is_float = true;
            self.pos += 1;
            if self.peek() == Some(b'+') || self.peek() == Some(b'-') { self.pos += 1; }
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) { return Err(()); }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).map_err(|_| ())?;
        if is_float {
            s.parse::<f64>().map(JsonValue::Float).map_err(|_| ())
        } else {
            s.parse::<i64>().map(JsonValue::Int).map_err(|_| ())
        }
    }

    fn parse_hex4(&mut self) -> Result<u32, ()> {
        if self.pos + 4 > self.input.len() { return Err(()); }
        let mut val: u32 = 0;
        for i in 0..4 {
            let c = self.input[self.pos + i];
            let d = match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => return Err(()),
            };
            val = val * 16 + d;
        }
        self.pos += 4;
        Ok(val)
    }

    fn parse_string(&mut self) -> Result<String, ()> {
        self.pos += 1; // skip opening "
        let mut result: Vec<u8> = Vec::new();
        loop {
            if self.pos >= self.input.len() { return Err(()); }
            let c = self.input[self.pos];
            match c {
                b'"' => { self.pos += 1; return String::from_utf8(result).map_err(|_| ()); }
                b'\\' => {
                    self.pos += 1;
                    if self.pos >= self.input.len() { return Err(()); }
                    match self.input[self.pos] {
                        b'"' => { result.push(b'"'); self.pos += 1; }
                        b'\\' => { result.push(b'\\'); self.pos += 1; }
                        b'/' => { result.push(b'/'); self.pos += 1; }
                        b'b' => { result.push(0x08); self.pos += 1; }
                        b'f' => { result.push(0x0C); self.pos += 1; }
                        b'n' => { result.push(b'\n'); self.pos += 1; }
                        b'r' => { result.push(b'\r'); self.pos += 1; }
                        b't' => { result.push(b'\t'); self.pos += 1; }
                        b'u' => {
                            self.pos += 1;
                            let cp = self.parse_hex4()?;
                            if cp >= 0xD800 && cp <= 0xDBFF {
                                if self.pos + 1 < self.input.len() && self.input[self.pos] == b'\\' && self.input[self.pos+1] == b'u' {
                                    self.pos += 2;
                                    let lo = self.parse_hex4()?;
                                    if lo >= 0xDC00 && lo <= 0xDFFF {
                                        let combined = 0x10000u32 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                        let ch = char::from_u32(combined).ok_or(())?;
                                        let mut buf = [0u8; 4];
                                        let s = ch.encode_utf8(&mut buf);
                                        result.extend_from_slice(s.as_bytes());
                                    } else { return Err(()); }
                                } else { return Err(()); }
                            } else if cp >= 0xDC00 && cp <= 0xDFFF {
                                return Err(());
                            } else {
                                let ch = char::from_u32(cp).ok_or(())?;
                                let mut buf = [0u8; 4];
                                let s = ch.encode_utf8(&mut buf);
                                result.extend_from_slice(s.as_bytes());
                            }
                        }
                        _ => return Err(()),
                    }
                }
                _ => { result.push(c); self.pos += 1; }
            }
        }
    }

    fn parse_object(&mut self) -> Result<JsonValue, ()> {
        self.pos += 1; // skip {
        let mut members = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(JsonValue::Object(members)); }
        loop {
            self.skip_ws();
            if self.peek() != Some(b'"') { return Err(()); }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.peek() != Some(b':') { return Err(()); }
            self.pos += 1;
            let value = self.parse_value()?;
            members.push((key, value));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; return Ok(JsonValue::Object(members)); }
                _ => return Err(()),
            }
        }
    }

    fn parse_array(&mut self) -> Result<JsonValue, ()> {
        self.pos += 1; // skip [
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(JsonValue::Array(items)); }
        loop {
            let value = self.parse_value()?;
            items.push(value);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; return Ok(JsonValue::Array(items)); }
                _ => return Err(()),
            }
        }
    }
}

fn parse_json(s: &str) -> Option<JsonValue> {
    let mut p = Parser::new(s);
    let v = p.parse_value().ok()?;
    p.skip_ws();
    if p.pos != p.input.len() { return None; }
    Some(v)
}

fn escape_str(s: &str) -> String {
    let mut r = String::with_capacity(s.len() + 2);
    r.push('"');
    for ch in s.chars() {
        match ch {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\u{08}' => r.push_str("\\b"),
            '\u{0C}' => r.push_str("\\f"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c if (c as u32) < 0x20 => { r.push_str(&format!("\\u{:04x}", c as u32)); }
            c => r.push(c),
        }
    }
    r.push('"');
    r
}

fn to_json(v: &JsonValue) -> String {
    match v {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(true) => "true".to_string(),
        JsonValue::Bool(false) => "false".to_string(),
        JsonValue::Int(n) => format!("{}", n),
        JsonValue::Float(_) => "0".to_string(), // shouldn't appear in output
        JsonValue::Str(s) => escape_str(s),
        JsonValue::Array(items) => {
            let parts: Vec<String> = items.iter().map(to_json).collect();
            format!("[{}]", parts.join(","))
        }
        JsonValue::Object(members) => {
            let parts: Vec<String> = members.iter().map(|(k, v)| format!("{}:{}", escape_str(k), to_json(v))).collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn obj_get<'a>(v: &'a JsonValue, key: &str) -> Option<&'a JsonValue> {
    if let JsonValue::Object(members) = v {
        members.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    } else { None }
}

fn obj_has(v: &JsonValue, key: &str) -> bool {
    if let JsonValue::Object(members) = v {
        members.iter().any(|(k, _)| k == key)
    } else { false }
}

fn is_valid_id(v: &JsonValue) -> bool {
    matches!(v, JsonValue::Str(_) | JsonValue::Int(_))
}

fn is_json_int(v: &JsonValue) -> bool {
    matches!(v, JsonValue::Int(_))
}

fn make_id(v: &JsonValue) -> String {
    match v {
        JsonValue::Str(s) => escape_str(s),
        JsonValue::Int(n) => format!("{}", n),
        _ => "null".to_string(),
    }
}

fn make_result(id_json: &str, result_json: &str) -> String {
    format!("{{\"jsonrpc\":\"2.0\",\"id\":{},\"result\":{}}}", id_json, result_json)
}

fn make_error(id_json: &str, code: i64, msg: &str) -> String {
    format!("{{\"jsonrpc\":\"2.0\",\"id\":{},\"error\":{{\"code\":{},\"message\":{}}}}}", id_json, code, escape_str(msg))
}

struct Server {
    initialized: bool,
    store: Vec<(String, String)>,
}

impl Server {
    fn new() -> Self { Server { initialized: false, store: Vec::new() } }
}

fn count_words(text: &str) -> usize {
    let mut count = 0;
    let mut in_word = false;
    for ch in text.chars() {
        if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
            in_word = false;
        } else {
            if !in_word { count += 1; in_word = true; }
        }
    }
    count
}

