fn process_line(server: &mut Server, line: &str) -> Option<String> {
    // Rule 1: parse JSON
    let msg = match parse_json(line) {
        Some(v) => v,
        None => return Some(make_error("null", -32700, "Parse error")),
    };

    // Rule 2: must be object
    if !matches!(msg, JsonValue::Object(_)) {
        return Some(make_error("null", -32600, "Invalid Request"));
    }

    // Rule 3: response from client (no method, has result or error)
    if !obj_has(&msg, "method") && (obj_has(&msg, "result") || obj_has(&msg, "error")) {
        return None;
    }

    // Rule 4: invalid request check
    let jsonrpc_ok = obj_get(&msg, "jsonrpc").map_or(false, |v| matches!(v, JsonValue::Str(s) if s == "2.0"));
    let method_ok = obj_get(&msg, "method").map_or(false, |v| matches!(v, JsonValue::Str(_)));
    let id_present = obj_has(&msg, "id");
    let id_ok = if id_present {
        obj_get(&msg, "id").map_or(false, |v| is_valid_id(v))
    } else {
        true
    };

    if !jsonrpc_ok || !method_ok || !id_ok {
        let id_json = if id_present && obj_get(&msg, "id").map_or(false, |v| is_valid_id(v)) {
            make_id(obj_get(&msg, "id").unwrap())
        } else {
            "null".to_string()
        };
        return Some(make_error(&id_json, -32600, "Invalid Request"));
    }

    // Rule 5: notification (valid, no id)
    if !id_present {
        return None;
    }

    let id_json = make_id(obj_get(&msg, "id").unwrap());
    let method = if let JsonValue::Str(m) = obj_get(&msg, "method").unwrap() { m.clone() } else { unreachable!() };

    // Rule 6a: method not found
    let known = ["initialize", "ping", "tools/list", "tools/call"];
    if !known.contains(&method.as_str()) {
        return Some(make_error(&id_json, -32601, "Method not found"));
    }

    // Rule 6b: params present but not object
    let params = obj_get(&msg, "params");
    if let Some(p) = params {
        if !matches!(p, JsonValue::Object(_)) {
            return Some(make_error(&id_json, -32602, "Invalid params"));
        }
    }

    // Rule 6c: not initialized
    if !server.initialized && method != "initialize" && method != "ping" {
        return Some(make_error(&id_json, -32002, "Server not initialized"));
    }

    // Rule 6d: dispatch
    match method.as_str() {
        "initialize" => {
            if server.initialized {
                return Some(make_error(&id_json, -32600, "Already initialized"));
            }
            let pv = if let Some(p) = params {
                match obj_get(p, "protocolVersion") {
                    Some(JsonValue::Str(s)) => s.clone(),
                    _ => return Some(make_error(&id_json, -32602, "Invalid params")),
                }
            } else {
                return Some(make_error(&id_json, -32602, "Invalid params"));
            };
            let version = if pv == "2025-06-18" || pv == "2025-03-26" || pv == "2024-11-05" {
                pv
            } else {
                "2025-06-18".to_string()
            };
            server.initialized = true;
            let result = format!(
                "{{\"protocolVersion\":{},\"capabilities\":{{\"tools\":{{\"listChanged\":false}}}},\"serverInfo\":{{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}}",
                escape_str(&version)
            );
            Some(make_result(&id_json, &result))
        }
        "ping" => {
            Some(make_result(&id_json, "{}"))
        }
        "tools/list" => {
            Some(make_result(&id_json, TOOLS_LIST_JSON))
        }
        "tools/call" => {
            // params.name
            let tool_name = match params {
                Some(p) => match obj_get(p, "name") {
                    Some(JsonValue::Str(s)) => s.clone(),
                    _ => return Some(make_error(&id_json, -32602, "Invalid params")),
                },
                None => return Some(make_error(&id_json, -32602, "Invalid params")),
            };
            let valid_tools = ["kv_set", "kv_get", "kv_list", "sum", "text_stats"];
            if !valid_tools.contains(&tool_name.as_str()) {
                return Some(make_error(&id_json, -32602, &format!("Unknown tool: {}", tool_name)));
            }

            // Get arguments
            let args: &JsonValue = match params {
                Some(p) => match obj_get(p, "arguments") {
                    Some(a) => a,
                    None => &JsonValue::Object(vec![]),
                },
                None => &JsonValue::Object(vec![]),
            };

            // Validate arguments
            if !matches!(args, JsonValue::Object(_)) {
                return Some(make_result(&id_json, &make_tool_failure("arguments must be an object")));
            }

            // Check for unknown arguments
            let props = tool_properties(&tool_name);
            let prop_names: Vec<&str> = props.iter().map(|(n, _, _, _)| *n).collect();
            let mut unknown: Vec<String> = Vec::new();
            if let JsonValue::Object(members) = args {
                for (k, _) in members {
                    if !prop_names.contains(&k.as_str()) {
                        unknown.push(k.clone());
                    }
                }
            }
            if !unknown.is_empty() {
                unknown.sort();
                return Some(make_result(&id_json, &make_tool_failure(&format!("unknown argument: {}", unknown[0]))));
            }

            // Check each property
            for (pname, ptype, required, min_len) in &props {
                let val = obj_get(args, pname);
                match val {
                    None => {
                        if *required {
                            return Some(make_result(&id_json, &make_tool_failure(&format!("missing required argument: {}", pname))));
                        }
                    }
                    Some(v) => {
                        match *ptype {
                            "string" => {
                                if !matches!(v, JsonValue::Str(_)) {
                                    return Some(make_result(&id_json, &make_tool_failure(&format!("argument {} must be a string", pname))));
                                }
                                if let Some(ml) = min_len {
                                    if let JsonValue::Str(s) = v {
                                        if s.len() < ml {
                                            return Some(make_result(&id_json, &make_tool_failure(&format!("argument {} must not be empty", pname))));
                                        }
                                    }
                                }
                            }
                            "array" => {
                                match v {
                                    JsonValue::Array(items) => {
                                        for item in items {
                                            if !is_json_int(item) {
                                                return Some(make_result(&id_json, &make_tool_failure(&format!("argument {} must be an array of integers", pname))));
                                            }
                                        }
                                        if let Some(mi) = min_len {
                                            if items.len() < mi {
                                                return Some(make_result(&id_json, &make_tool_failure(&format!("argument {} must not be empty", pname))));
                                            }
                                        }
                                    }
                                    _ => {
                                        return Some(make_result(&id_json, &make_tool_failure(&format!("argument {} must be an array of integers", pname))));
                                    }
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }

            // Execute tool
            let result_json = execute_tool(server, &tool_name, args);
            Some(make_result(&id_json, &result_json))
        }
        _ => unreachable!(),
    }
}

fn execute_tool(server: &mut Server, name: &str, args: &JsonValue) -> String {
    match name {
        "kv_set" => {
            let key = if let JsonValue::Str(s) = obj_get(args, "key").unwrap() { s.clone() } else { unreachable!() };
            let value = if let JsonValue::Str(s) = obj_get(args, "value").unwrap() { s.clone() } else { unreachable!() };
            let existed = server.store.iter().any(|(k, _)| k == &key);
            if existed {
                for entry in server.store.iter_mut() {
                    if entry.0 == key { entry.1 = value; break; }
                }
                make_tool_success(&format!("updated {}", key))
            } else {
                server.store.push((key.clone(), value));
                make_tool_success(&format!("created {}", key))
            }
        }
        "kv_get" => {
            let key = if let JsonValue::Str(s) = obj_get(args, "key").unwrap() { s.clone() } else { unreachable!() };
            match server.store.iter().find(|(k, _)| k == &key) {
                Some((_, v)) => make_tool_success(v),
                None => make_tool_failure(&format!("key not found: {}", key)),
            }
        }
        "kv_list" => {
            let prefix = match obj_get(args, "prefix") {
                Some(JsonValue::Str(s)) => s.clone(),
                _ => String::new(),
            };
            let mut keys: Vec<String> = server.store.iter()
                .filter(|(k, _)| k.starts_with(&prefix))
                .map(|(k, _)| k.clone())
                .collect();
            keys.sort();
            let count = keys.len() as i64;
            let structured = JsonValue::Object(vec![
                ("keys".to_string(), JsonValue::Array(keys.into_iter().map(JsonValue::Str).collect())),
                ("count".to_string(), JsonValue::Int(count)),
            ]);
            let text = to_json(&structured);
            make_tool_success_structured(&text, &structured)
        }
        "sum" => {
            let items = if let JsonValue::Array(arr) = obj_get(args, "numbers").unwrap() { arr } else { unreachable!() };
            let mut sum: i64 = 0;
            for item in items {
                if let JsonValue::Int(n) = item { sum += n; }
            }
            let count = items.len() as i64;
            let structured = JsonValue::Object(vec![
                ("sum".to_string(), JsonValue::Int(sum)),
                ("count".to_string(), JsonValue::Int(count)),
            ]);
            let text = to_json(&structured);
            make_tool_success_structured(&text, &structured)
        }
        "text_stats" => {
            let text = if let JsonValue::Str(s) = obj_get(args, "text").unwrap() { s.clone() } else { unreachable!() };
            let words = count_words(&text) as i64;
            let codepoints = text.chars().count() as i64;
            let utf8_bytes = text.len() as i64;
            let structured = JsonValue::Object(vec![
                ("words".to_string(), JsonValue::Int(words)),
                ("codepoints".to_string(), JsonValue::Int(codepoints)),
                ("utf8_bytes".to_string(), JsonValue::Int(utf8_bytes)),
            ]);
            let text_json = to_json(&structured);
            make_tool_success_structured(&text_json, &structured)
        }
        _ => unreachable!(),
    }
}

const TOOLS_LIST_JSON: &str = r#"{"tools":[{"name":"kv_set","title":"Set a value","description":"Store a string value under a key, replacing any previous value.","inputSchema":{"type":"object","properties":{"key":{"type":"string","minLength":1},"value":{"type":"string"}},"required":["key","value"],"additionalProperties":false}},{"name":"kv_get","title":"Get a value","description":"Return the value stored under a key.","inputSchema":{"type":"object","properties":{"key":{"type":"string","minLength":1}},"required":["key"],"additionalProperties":false}},{"name":"kv_list","title":"List keys","description":"List the stored keys that start with a prefix, sorted by Unicode code point.","inputSchema":{"type":"object","properties":{"prefix":{"type":"string"}},"additionalProperties":false},"outputSchema":{"type":"object","properties":{"keys":{"type":"array","items":{"type":"string"}},"count":{"type":"integer"}},"required":["keys","count"]}},{"name":"sum","title":"Sum integers","description":"Add up a non-empty list of integers.","inputSchema":{"type":"object","properties":{"numbers":{"type":"array","items":{"type":"integer"},"minItems":1}},"required":["numbers"],"additionalProperties":false},"outputSchema":{"type":"object","properties":{"sum":{"type":"integer"},"count":{"type":"integer"}},"required":["sum","count"]},"annotations":{"readOnlyHint":true,"idempotentHint":true}},{"name":"text_stats","title":"Text statistics","description":"Count the words, Unicode code points and UTF-8 bytes of a text.","inputSchema":{"type":"object","properties":{"text":{"type":"string"}},"required":["text"],"additionalProperties":false},"outputSchema":{"type":"object","properties":{"words":{"type":"integer"},"codepoints":{"type":"integer"},"utf8_bytes":{"type":"integer"}},"required":["words","codepoints","utf8_bytes"]},"annotations":{"readOnlyHint":true}}]}"#;

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let mut server = Server::new();

    for line in stdin.lock().lines() {
        let raw = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        // Strip trailing \r (for CRLF line endings; lines() already strips \n)
        let trimmed = if raw.ends_with('\r') { &raw[..raw.len()-1] } else { &raw[..] };
        // Check if line is empty or only whitespace (space, tab, CR)
        if trimmed.is_empty() || trimmed.chars().all(|c| c == ' ' || c == '\t' || c == '\r') {
            continue;
        }
        if let Some(response) = process_line(&mut server, trimmed) {
            let _ = writeln!(out, "{}", response);
        }
    }
    let _ = out.flush();
}

use std::io::{self, BufRead, Write};

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }

    fn parse_value(&mut self) -> Result<JsonValue, ()> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string().map(JsonValue::Str),
            Some(b't') => self.parse_true(),
            Some(b'f') => self.parse_false(),
            Some(b'n') => self.parse_null(),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err(()),
        }
    }

    fn parse_true(&mut self) -> Result<JsonValue, ()> {
        if self.pos + 4 <= self.input.len() && &self.input[self.pos..self.pos+4] == b"true" {
            self.pos += 4;
            Ok(JsonValue::Bool(true))
        } else { Err(()) }
    }

    fn parse_false(&mut self) -> Result<JsonValue, ()> {
        if self.pos + 5 <= self.input.len() && &self.input[self.pos..self.pos+5] == b"false" {
            self.pos += 5;
            Ok(JsonValue::Bool(false))
        } else { Err(()) }
    }

    fn parse_null(&mut self) -> Result<JsonValue, ()> {
        if self.pos + 4 <= self.input.len() && &self.input[self.pos..self.pos+4] == b"null" {
            self.pos += 4;
            Ok(JsonValue::Null)
        } else { Err(()) }
    }

    fn parse_number(&mut self) -> Result<JsonValue, ()> {
        let start = self.pos;
        let mut is_float = false;
        if self.peek() == Some(b'-') { self.pos += 1; }
        if self.peek() == Some(b'0') {
            self.pos += 1;
        } else if self.peek().map_or(false, |c| c.is_ascii_digit()) {
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        } else { return Err(()); }
        if self.peek() == Some(b'.') {
            is_float = true;
            self.pos += 1;
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) { return Err(()); }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        }
        if self.peek() == Some(b'e') || self.peek() == Some(b'E') {
            is_float = true;
            self.pos += 1;
            if self.peek() == Some(b'+') || self.peek() == Some(b'-') { self.pos += 1; }
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) { return Err(()); }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).map_err(|_| ())?;
        if is_float {
            s.parse::<f64>().map(JsonValue::Float).map_err(|_| ())
        } else {
            s.parse::<i64>().map(JsonValue::Int).map_err(|_| ())
        }
    }

    fn parse_hex4(&mut self) -> Result<u32, ()> {
        if self.pos + 4 > self.input.len() { return Err(()); }
        let mut val: u32 = 0;
        for i in 0..4 {
            let c = self.input[self.pos + i];
            let d = match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => return Err(()),
            };
            val = val * 16 + d;
        }
        self.pos += 4;
        Ok(val)
    }

    fn parse_string(&mut self) -> Result<String, ()> {
        self.pos += 1; // skip opening "
        let mut result: Vec<u8> = Vec::new();
        loop {
            if self.pos >= self.input.len() { return Err(()); }
            let c = self.input[self.pos];
            match c {
                b'"' => { self.pos += 1; return String::from_utf8(result).map_err(|_| ()); }
                b'\\' => {
                    self.pos += 1;
                    if self.pos >= self.input.len() { return Err(()); }
                    match self.input[self.pos] {
                        b'"' => { result.push(b'"'); self.pos += 1; }
                        b'\\' => { result.push(b'\\'); self.pos += 1; }
                        b'/' => { result.push(b'/'); self.pos += 1; }
                        b'b' => { result.push(0x08); self.pos += 1; }
                        b'f' => { result.push(0x0C); self.pos += 1; }
                        b'n' => { result.push(b'\n'); self.pos += 1; }
                        b'r' => { result.push(b'\r'); self.pos += 1; }
                        b't' => { result.push(b'\t'); self.pos += 1; }
                        b'u' => {
                            self.pos += 1;
                            let cp = self.parse_hex4()?;
                            if cp >= 0xD800 && cp <= 0xDBFF {
                                if self.pos + 1 < self.input.len() && self.input[self.pos] == b'\\' && self.input[self.pos+1] == b'u' {
                                    self.pos += 2;
                                    let lo = self.parse_hex4()?;
                                    if lo >= 0xDC00 && lo <= 0xDFFF {
                                        let combined = 0x10000u32 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                        let ch = char::from_u32(combined).ok_or(())?;
                                        let mut buf = [0u8; 4];
                                        let s = ch.encode_utf8(&mut buf);
                                        result.extend_from_slice(s.as_bytes());
                                    } else { return Err(()); }
                                } else { return Err(()); }
                            } else if cp >= 0xDC00 && cp <= 0xDFFF {
                                return Err(());
                            } else {
                                let ch = char::from_u32(cp).ok_or(())?;
                                let mut buf = [0u8; 4];
                                let s = ch.encode_utf8(&mut buf);
                                result.extend_from_slice(s.as_bytes());
                            }
                        }
                        _ => return Err(()),
                    }
                }
                _ => { result.push(c); self.pos += 1; }
            }
        }
    }

    fn parse_object(&mut self) -> Result<JsonValue, ()> {
        self.pos += 1; // skip {
        let mut members = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(JsonValue::Object(members)); }
        loop {
            self.skip_ws();
            if self.peek() != Some(b'"') { return Err(()); }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.peek() != Some(b':') { return Err(()); }
            self.pos += 1;
            let value = self.parse_value()?;
            members.push((key, value));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; return Ok(JsonValue::Object(members)); }
                _ => return Err(()),
            }
        }
    }

    fn parse_array(&mut self) -> Result<JsonValue, ()> {
        self.pos += 1; // skip [
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(JsonValue::Array(items)); }
        loop {
            let value = self.parse_value()?;
            items.push(value);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; return Ok(JsonValue::Array(items)); }
                _ => return Err(()),
            }
        }
    }
}

fn parse_json(s: &str) -> Option<JsonValue> {
    let mut p = Parser::new(s);
    let v = p.parse_value().ok()?;
    p.skip_ws();
    if p.pos != p.input.len() { return None; }
    Some(v)
}

fn escape_str(s: &str) -> String {
    let mut r = String::with_capacity(s.len() + 2);
    r.push('"');
    for ch in s.chars() {
        match ch {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\u{08}' => r.push_str("\\b"),
            '\u{0C}' => r.push_str("\\f"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c if (c as u32) < 0x20 => { r.push_str(&format!("\\u{:04x}", c as u32)); }
            c => r.push(c),
        }
    }
    r.push('"');
    r
}

fn to_json(v: &JsonValue) -> String {
    match v {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(true) => "true".to_string(),
        JsonValue::Bool(false) => "false".to_string(),
        JsonValue::Int(n) => format!("{}", n),
        JsonValue::Float(_) => "0".to_string(),
        JsonValue::Str(s) => escape_str(s),
        JsonValue::Array(items) => {
            let parts: Vec<String> = items.iter().map(to_json).collect();
            format!("[{}]", parts.join(","))
        }
        JsonValue::Object(members) => {
            let parts: Vec<String> = members.iter().map(|(k, v)| format!("{}:{}", escape_str(k), to_json(v))).collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn obj_get<'a>(v: &'a JsonValue, key: &str) -> Option<&'a JsonValue> {
    if let JsonValue::Object(members) = v {
        members.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    } else { None }
}

fn obj_has(v: &JsonValue, key: &str) -> bool {
    if let JsonValue::Object(members) = v {
        members.iter().any(|(k, _)| k == key)
    } else { false }
}

fn is_valid_id(v: &JsonValue) -> bool {
    matches!(v, JsonValue::Str(_) | JsonValue::Int(_))
}

fn is_json_int(v: &JsonValue) -> bool {
    matches!(v, JsonValue::Int(_))
}

fn make_id(v: &JsonValue) -> String {
    match v {
        JsonValue::Str(s) => escape_str(s),
        JsonValue::Int(n) => format!("{}", n),
        _ => "null".to_string(),
    }
}

fn make_result(id_json: &str, result_json: &str) -> String {
    format!("{{\"jsonrpc\":\"2.0\",\"id\":{},\"result\":{}}}", id_json, result_json)
}

fn make_error(id_json: &str, code: i64, msg: &str) -> String {
    format!("{{\"jsonrpc\":\"2.0\",\"id\":{},\"error\":{{\"code\":{},\"message\":{}}}}}", id_json, code, escape_str(msg))
}

struct Server {
    initialized: bool,
    store: Vec<(String, String)>,
}

impl Server {
    fn new() -> Self { Server { initialized: false, store: Vec::new() } }
}

fn count_words(text: &str) -> usize {
    let mut count = 0;
    let mut in_word = false;
    for ch in text.chars() {
        if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
            in_word = false;
        } else {
            if !in_word { count += 1; in_word = true; }
        }
    }
    count
}

fn tool_properties(name: &str) -> Vec<(&'static str, &'static str, bool, Option<usize>)> {
    match name {
        "kv_set" => vec![("key", "string", true, Some(1)), ("value", "string", true, None)],
        "kv_get" => vec![("key", "string", true, Some(1))],
        "kv_list" => vec![("prefix", "string", false, None)],
        "sum" => vec![("numbers", "array", true, Some(1))],
        "text_stats" => vec![("text", "string", true, None)],
        _ => vec![],
    }
}

fn make_tool_success(text: &str) -> String {
    format!("{{\"content\":[{{\"type\":\"text\",\"text\":{}}}],\"isError\":false}}", escape_str(text))
}

fn make_tool_success_structured(text: &str, structured: &JsonValue) -> String {
    format!("{{\"content\":[{{\"type\":\"text\",\"text\":{}}}],\"structuredContent\":{},\"isError\":false}}",
        escape_str(text), to_json(structured))
}

fn make_tool_failure(msg: &str) -> String {
    format!("{{\"content\":[{{\"type\":\"text\",\"text\":{}}}],\"isError\":true}}", escape_str(msg))
}

fn process_line(server: &mut Server, line: &str) -> Option<String> {
    // Rule 1: parse JSON
    let msg = match parse_json(line) {
        Some(v) => v,
        None => return Some(make_error("null", -32700, "Parse error")),
    };

    // Rule 2: must be object
    if !matches!(msg, JsonValue::Object(_)) {
        return Some(make_error("null", -32600, "Invalid Request"));
    }

    // Rule 3: response from client (no method, has result or error)
    if !obj_has(&msg, "method") && (obj_has(&msg, "result") || obj_has(&msg, "error")) {
        return None;
    }

    // Rule 4: invalid request check
    let jsonrpc_ok = obj_get(&msg, "jsonrpc").map_or(false, |v| matches!(v, JsonValue::Str(s) if s == "2.0"));
    let method_ok = obj_get(&msg, "method").map_or(false, |v| matches!(v, JsonValue::Str(_)));
    let id_present = obj_has(&msg, "id");
    let id_ok = if id_present {
        obj_get(&msg, "id").map_or(false, |v| is_valid_id(v))
    } else {
        true
    };

    if !jsonrpc_ok || !method_ok || !id_ok {
        let id_json = if id_present && obj_get(&msg, "id").map_or(false, |v| is_valid_id(v)) {
            make_id(obj_get(&msg, "id").unwrap())
        } else {
            "null".to_string()
        };
        return Some(make_error(&id_json, -32600, "Invalid Request"));
    }

    // Rule 5: notification (valid, no id)
    if !id_present {
        return None;
    }

    let id_json = make_id(obj_get(&msg, "id").unwrap());
    let method = if let JsonValue::Str(m) = obj_get(&msg, "method").unwrap() { m.clone() } else { unreachable!() };

    // Rule 6a: method not found
    let known = ["initialize", "ping", "tools/list", "tools/call"];
    if !known.contains(&method.as_str()) {
        return Some(make_error(&id_json, -32601, "Method not found"));
    }

    // Rule 6b: params present but not object
    let params = obj_get(&msg, "params");
    if let Some(p) = params {
        if !matches!(p, JsonValue::Object(_)) {
            return Some(make_error(&id_json, -32602, "Invalid params"));
        }
    }

    // Rule 6c: not initialized
    if !server.initialized && method != "initialize" && method != "ping" {
        return Some(make_error(&id_json, -32002, "Server not initialized"));
    }

    // Rule 6d: dispatch
    match method.as_str() {
        "initialize" => {
            if server.initialized {
                return Some(make_error(&id_json, -32600, "Already initialized"));
            }
            let pv = if let Some(p) = params {
                match obj_get(p, "protocolVersion") {
                    Some(JsonValue::Str(s)) => s.clone(),
                    _ => return Some(make_error(&id_json, -32602, "Invalid params")),
                }
            } else {
                return Some(make_error(&id_json, -32602, "Invalid params"));
            };
            let version = if pv == "2025-06-18" || pv == "2025-03-26" || pv == "2024-11-05" {
                pv
            } else {
                "2025-06-18".to_string()
            };
            server.initialized = true;
            let result = format!(
                "{{\"protocolVersion\":{},\"capabilities\":{{\"tools\":{{\"listChanged\":false}}}},\"serverInfo\":{{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}}",
                escape_str(&version)
            );
            Some(make_result(&id_json, &result))
        }
        "ping" => {
            Some(make_result(&id_json, "{}"))
        }
        "tools/list" => {
            Some(make_result(&id_json, TOOLS_LIST_JSON))
        }
        "tools/call" => {
            // params.name
            let tool_name = match params {
                Some(p) => match obj_get(p, "name") {
                    Some(JsonValue::Str(s)) => s.clone(),
                    _ => return Some(make_error(&id_json, -32602, "Invalid params")),
                },
                None => return Some(make_error(&id_json, -32602, "Invalid params")),
            };
            let valid_tools = ["kv_set", "kv_get", "kv_list", "sum", "text_stats"];
            if !valid_tools.contains(&tool_name.as_str()) {
                return Some(make_error(&id_json, -32602, &format!("Unknown tool: {}", tool_name)));
            }

            // Get arguments
            let args: &JsonValue = match params {
                Some(p) => match obj_get(p, "arguments") {
                    Some(a) => a,
                    None => &JsonValue::Object(vec![]),
                },
                None => &JsonValue::Object(vec![]),
            };

            // Validate arguments
            if !matches!(args, JsonValue::Object(_)) {
                return Some(make_result(&id_json, &make_tool_failure("arguments must be an object")));
            }

            // Check for unknown arguments
            let props = tool_properties(&tool_name);
            let prop_names: Vec<&str> = props.iter().map(|(n, _, _, _)| *n).collect();
            let mut unknown: Vec<String> = Vec::new();
            if let JsonValue::Object(members) = args {
                for (k, _) in members {
                    if !prop_names.contains(&k.as_str()) {
                        unknown.push(k.clone());
                    }
                }
            }
            if !unknown.is_empty() {
                unknown.sort();
                return Some(make_result(&id_json, &make_tool_failure(&format!("unknown argument: {}", unknown[0]))));
            }

            // Check each property
            for (pname, ptype, required, min_len) in &props {
                let val = obj_get(args, pname);
                match val {
                    None => {
                        if *required {
                            return Some(make_result(&id_json, &make_tool_failure(&format!("missing required argument: {}", pname))));
                        }
                    }
                    Some(v) => {
                        match *ptype {
                            "string" => {
                                if !matches!(v, JsonValue::Str(_)) {
                                    return Some(make_result(&id_json, &make_tool_failure(&format!("argument {} must be a string", pname))));
                                }
                                if let Some(ml) = min_len {
                                    if let JsonValue::Str(s) = v {
                                        if s.len() < *ml {
                                            return Some(make_result(&id_json, &make_tool_failure(&format!("argument {} must not be empty", pname))));
                                        }
                                    }
                                }
                            }
                            "array" => {
                                match v {
                                    JsonValue::Array(items) => {
                                        for item in items {
                                            if !is_json_int(item) {
                                                return Some(make_result(&id_json, &make_tool_failure(&format!("argument {} must be an array of integers", pname))));
                                            }
                                        }
                                        if let Some(mi) = min_len {
                                            if items.len() < *mi {
                                                return Some(make_result(&id_json, &make_tool_failure(&format!("argument {} must not be empty", pname))));
                                            }
                                        }
                                    }
                                    _ => {
                                        return Some(make_result(&id_json, &make_tool_failure(&format!("argument {} must be an array of integers", pname))));
                                    }
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }

            // Execute tool
            let result_json = execute_tool(server, &tool_name, args);
            Some(make_result(&id_json, &result_json))
        }
        _ => unreachable!(),
    }
}

fn execute_tool(server: &mut Server, name: &str, args: &JsonValue) -> String {
    match name {
        "kv_set" => {
            let key = if let JsonValue::Str(s) = obj_get(args, "key").unwrap() { s.clone() } else { unreachable!() };
            let value = if let JsonValue::Str(s) = obj_get(args, "value").unwrap() { s.clone() } else { unreachable!() };
            let existed = server.store.iter().any(|(k, _)| k == &key);
            if existed {
                for entry in server.store.iter_mut() {
                    if entry.0 == key { entry.1 = value; break; }
                }
                make_tool_success(&format!("updated {}", key))
            } else {
                server.store.push((key.clone(), value));
                make_tool_success(&format!("created {}", key))
            }
        }
        "kv_get" => {
            let key = if let JsonValue::Str(s) = obj_get(args, "key").unwrap() { s.clone() } else { unreachable!() };
            match server.store.iter().find(|(k, _)| k == &key) {
                Some((_, v)) => make_tool_success(v),
                None => make_tool_failure(&format!("key not found: {}", key)),
            }
        }
        "kv_list" => {
            let prefix = match obj_get(args, "prefix") {
                Some(JsonValue::Str(s)) => s.clone(),
                _ => String::new(),
            };
            let mut keys: Vec<String> = server.store.iter()
                .filter(|(k, _)| k.starts_with(&prefix))
                .map(|(k, _)| k.clone())
                .collect();
            keys.sort();
            let count = keys.len() as i64;
            let structured = JsonValue::Object(vec![
                ("keys".to_string(), JsonValue::Array(keys.into_iter().map(JsonValue::Str).collect())),
                ("count".to_string(), JsonValue::Int(count)),
            ]);
            let text = to_json(&structured);
            make_tool_success_structured(&text, &structured)
        }
        "sum" => {
            let items = if let JsonValue::Array(arr) = obj_get(args, "numbers").unwrap() { arr } else { unreachable!() };
            let mut sum: i64 = 0;
            for item in items {
                if let JsonValue::Int(n) = item { sum += n; }
            }
            let count = items.len() as i64;
            let structured = JsonValue::Object(vec![
                ("sum".to_string(), JsonValue::Int(sum)),
                ("count".to_string(), JsonValue::Int(count)),
            ]);
            let text = to_json(&structured);
            make_tool_success_structured(&text, &structured)
        }
        "text_stats" => {
            let text = if let JsonValue::Str(s) = obj_get(args, "text").unwrap() { s.clone() } else { unreachable!() };
            let words = count_words(&text) as i64;
            let codepoints = text.chars().count() as i64;
            let utf8_bytes = text.len() as i64;
            let structured = JsonValue::Object(vec![
                ("words".to_string(), JsonValue::Int(words)),
                ("codepoints".to_string(), JsonValue::Int(codepoints)),
                ("utf8_bytes".to_string(), JsonValue::Int(utf8_bytes)),
            ]);
            let text_json = to_json(&structured);
            make_tool_success_structured(&text_json, &structured)
        }
        _ => unreachable!(),
    }
}

const TOOLS_LIST_JSON: &str = r#"{"tools":[{"name":"kv_set","title":"Set a value","description":"Store a string value under a key, replacing any previous value.","inputSchema":{"type":"object","properties":{"key":{"type":"string","minLength":1},"value":{"type":"string"}},"required":["key","value"],"additionalProperties":false}},{"name":"kv_get","title":"Get a value","description":"Return the value stored under a key.","inputSchema":{"type":"object","properties":{"key":{"type":"string","minLength":1}},"required":["key"],"additionalProperties":false}},{"name":"kv_list","title":"List keys","description":"List the stored keys that start with a prefix, sorted by Unicode code point.","inputSchema":{"type":"object","properties":{"prefix":{"type":"string"}},"additionalProperties":false},"outputSchema":{"type":"object","properties":{"keys":{"type":"array","items":{"type":"string"}},"count":{"type":"integer"}},"required":["keys","count"]}},{"name":"sum","title":"Sum integers","description":"Add up a non-empty list of integers.","inputSchema":{"type":"object","properties":{"numbers":{"type":"array","items":{"type":"integer"},"minItems":1}},"required":["numbers"],"additionalProperties":false},"outputSchema":{"type":"object","properties":{"sum":{"type":"integer"},"count":{"type":"integer"}},"required":["sum","count"]},"annotations":{"readOnlyHint":true,"idempotentHint":true}},{"name":"text_stats","title":"Text statistics","description":"Count the words, Unicode code points and UTF-8 bytes of a text.","inputSchema":{"type":"object","properties":{"text":{"type":"string"}},"required":["text"],"additionalProperties":false},"outputSchema":{"type":"object","properties":{"words":{"type":"integer"},"codepoints":{"type":"integer"},"utf8_bytes":{"type":"integer"}},"required":["words","codepoints","utf8_bytes"]},"annotations":{"readOnlyHint":true}}]}"#;

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let mut server = Server::new();

    for line in stdin.lock().lines() {
        let raw = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        // Strip trailing \r (for CRLF line endings; lines() already strips \n)
        let trimmed = if raw.ends_with('\r') { &raw[..raw.len()-1] } else { &raw[..] };
        // Check if line is empty or only whitespace (space, tab, CR)
        if trimmed.is_empty() || trimmed.chars().all(|c| c == ' ' || c == '\t' || c == '\r') {
            continue;
        }
        if let Some(response) = process_line(&mut server, trimmed) {
            let _ = writeln!(out, "{}", response);
        }
    }
    let _ = out.flush();
}

import * as fs from 'fs';
import * as path from 'path';

// ===== TOKEN =====
interface Token { type: string; value: string; line: number; }

// ===== LEXER =====
function tokenize(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  const n = src.length;
  while (i < n) {
    const c = src[i];
    if (c === ' ' || c === '\t' || c === '\r') { i++; continue; }
    if (c === '\n') { line++; i++; continue; }
    if (c === '#') { while (i < n && src[i] !== '\n') i++; continue; }
    if (c >= '0' && c <= '9') {
      const s = i;
      while (i < n && src[i] >= '0' && src[i] <= '9') i++;
      tokens.push({ type: 'INT', value: src.slice(s, i), line });
      continue;
    }
    if (c === '"') {
      i++;
      let s = '';
      while (i < n && src[i] !== '"') {
        if (src[i] === '\\') {
          i++;
          const e = src[i];
          if (e === 'n') s += '\n';
          else if (e === 't') s += '\t';
          else if (e === '"') s += '"';
          else if (e === '\\') s += '\\';
          i++;
        } else { s += src[i]; i++; }
      }
      i++;
      tokens.push({ type: 'STRING', value: s, line });
      continue;
    }
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_') {
      const s = i;
      while (i < n && ((src[i] >= 'a' && src[i] <= 'z') || (src[i] >= 'A' && src[i] <= 'Z') || (src[i] >= '0' && src[i] <= '9') || src[i] === '_')) i++;
      const w = src.slice(s, i);
      const kws = new Set(['let','fn','if','else','while','for','in','return','break','continue','and','or','not','true','false','nil']);
      tokens.push({ type: kws.has(w) ? w : 'IDENT', value: w, line });
      continue;
    }
    if (i + 1 < n) {
      const two = src.slice(i, i + 2);
      if (two === '==' || two === '!=' || two === '<=' || two === '>=') {
        tokens.push({ type: two, value: two, line }); i += 2; continue;
      }
    }
    if ('<>=+-*/%()[]{},;'.includes(c)) {
      tokens.push({ type: c, value: c, line }); i++; continue;
    }
    i++;
  }
  tokens.push({ type: 'EOF', value: '', line });
  return tokens;
}

// ===== AST =====
interface ExprNode { kind: string; line: number; }
interface IntLit extends ExprNode { kind: 'int'; value: bigint; }
interface StrLit extends ExprNode { kind: 'str'; value: string; }
interface BoolLit extends ExprNode { kind: 'bool'; value: boolean; }
interface NilLit extends ExprNode { kind: 'nil'; }
interface IdentNode extends ExprNode { kind: 'ident'; name: string; }
interface BinaryNode extends ExprNode { kind: 'binary'; op: string; left: ExprNode; right: ExprNode; }
interface UnaryNode extends ExprNode { kind: 'unary'; op: string; operand: ExprNode; }
interface CallNode extends ExprNode { kind: 'call'; callee: ExprNode; args: ExprNode[]; }
interface IndexNode extends ExprNode { kind: 'index'; obj: ExprNode; index: ExprNode; }
interface ListLitNode extends ExprNode { kind: 'list'; elements: ExprNode[]; }
interface FnExprNode extends ExprNode { kind: 'fn'; params: string[]; body: StmtNode[]; }
type Expr = IntLit | StrLit | BoolLit | NilLit | IdentNode | BinaryNode | UnaryNode | CallNode | IndexNode | ListLitNode | FnExprNode;

interface StmtNode { kind: string; line: number; }
interface LetStmt extends StmtNode { kind: 'let'; name: string; value: Expr; }
interface FnDeclStmt extends StmtNode { kind: 'fnDecl'; name: string; params: string[]; body: StmtNode[]; }
interface AssignStmt extends StmtNode { kind: 'assign'; name: string; value: Expr; }
interface IndexAssignStmt extends StmtNode { kind: 'indexAssign'; obj: Expr; index: Expr; value: Expr; }
interface IfStmt extends StmtNode { kind: 'if'; cond: Expr; then: StmtNode[]; elseBranch: StmtNode[] | IfStmt | null; }
interface WhileStmt extends StmtNode { kind: 'while'; cond: Expr; body: StmtNode[]; }
interface ForStmt extends StmtNode { kind: 'for'; varName: string; iterable: Expr; body: StmtNode[]; }
interface ReturnStmt extends StmtNode { kind: 'return'; value: Expr | null; }
interface BreakStmt extends StmtNode { kind: 'break'; }
interface ContinueStmt extends StmtNode { kind: 'continue'; }
interface ExprStmt extends StmtNode { kind: 'expr'; expr: Expr; }
type Stmt = LetStmt | FnDeclStmt | AssignStmt | IndexAssignStmt | IfStmt | WhileStmt | ForStmt | ReturnStmt | BreakStmt | ContinueStmt | ExprStmt;

// ===== PARSER =====
const KW_SET = new Set(['let','fn','if','else','while','for','in','return','break','continue','and','or','not','true','false','nil']);

class Parser {
  tokens: Token[];
  pos: number;
  constructor(tokens: Token[]) { this.tokens = tokens; this.pos = 0; }
  peek(): Token { return this.tokens[this.pos]; }
  advance(): Token { return this.tokens[this.pos++]; }
  expect(_type: string): Token { return this.advance(); }

  parseProgram(): Stmt[] {
    const stmts: Stmt[] = [];
    while (this.peek().type !== 'EOF') stmts.push(this.parseStmt());
    return stmts;
  }

  parseParams(): string[] {
    const params: string[] = [];
    if (this.peek().type === ')') return params;
    params.push(this.advance().value);
    while (this.peek().type === ',') { this.advance(); params.push(this.advance().value); }
    return params;
  }

  parseBlock(): Stmt[] {
    this.expect('{');
    const stmts: Stmt[] = [];
    while (this.peek().type !== '}') stmts.push(this.parseStmt());
    this.expect('}');
    return stmts;
  }

  parseStmt(): Stmt {
    const t = this.peek();
    switch (t.type) {
      case 'let': {
        this.advance();
        const name = this.advance().value;
        this.expect('=');
        const value = this.parseExpr(1);
        this.expect(';');
        return { kind: 'let', name, value, line: t.line };
      }
      case 'fn': {
        // Check if next is IDENT (declaration) or '(' (expression stmt)
        if (this.tokens[this.pos + 1].type === 'IDENT') {
          this.advance();
          const name = this.advance().value;
          this.expect('(');
          const params = this.parseParams();
          this.expect(')');
          const body = this.parseBlock();
          return { kind: 'fnDecl', name, params, body, line: t.line };
        }
        // else fall through to expression statement
        break;
      }
      case 'if': return this.parseIf();
      case 'while': {
        this.advance();
        const cond = this.parseExpr(1);
        const body = this.parseBlock();
        return { kind: 'while', cond, body, line: t.line };
      }
      case 'for': {
        this.advance();
        const varName = this.advance().value;
        this.expect('in');
        const iterable = this.parseExpr(1);
        const body = this.parseBlock();
        return { kind: 'for', varName, iterable, body, line: t.line };
      }
      case 'return': {
        this.advance();
        let value: Expr | null = null;
        if (this.peek().type !== ';') value = this.parseExpr(1);
        this.expect(';');
        return { kind: 'return', value, line: t.line };
      }
      case 'break': this.advance(); this.expect(';'); return { kind: 'break', line: t.line };
      case 'continue': this.advance(); this.expect(';'); return { kind: 'continue', line: t.line };
      case 'IDENT': {
        // Check for simple assignment: IDENT = expr ;
        if (this.tokens[this.pos + 1].type === '=') {
          this.advance(); // consume IDENT
          const name = t.value;
          this.advance(); // consume =
          const value = this.parseExpr(1);
          this.expect(';');
          return { kind: 'assign', name, value, line: t.line };
        }
        // Otherwise parse expression, check for index assignment
        const expr = this.parseExpr(1);
        if (this.peek().type === '=') {
          this.advance(); // consume =
          const value = this.parseExpr(1);
          this.expect(';');
          const idx = expr as IndexNode;
          return { kind: 'indexAssign', obj: idx.obj, index: idx.index, value, line: t.line };
        }
        this.expect(';');
        return { kind: 'expr', expr, line: t.line };
      }
    }
    // expression statement
    const expr = this.parseExpr(1);
    if (this.peek().type === '=') {
      this.advance();
      const value = this.parseExpr(1);
      this.expect(';');
      const idx = expr as IndexNode;
      return { kind: 'indexAssign', obj: idx.obj, index: idx.index, value, line: t.line };
    }
    this.expect(';');
    return { kind: 'expr', expr, line: t.line };
  }

  parseIf(): IfStmt {
    const t = this.advance(); // consume 'if'
    const cond = this.parseExpr(1);
    const then = this.parseBlock();
    let elseBranch: StmtNode[] | IfStmt | null = null;
    if (this.peek().type === 'else') {
      this.advance();
      if (this.peek().type === 'if') {
        elseBranch = this.parseIf();
      } else {
        elseBranch = this.parseBlock();
      }
    }
    return { kind: 'if', cond, then, elseBranch, line: t.line };
  }

  // Precedence: or=1, and=2, not=3, cmp=4, addsub=5, muldiv=6, neg=7, postfix=8
  parseExpr(minPrec: number): Expr {
    let left = this.parsePrefixExpr();
    while (true) {
      const t = this.peek();
      const prec = this.binaryPrec(t.type);
      if (prec === null || prec < minPrec) break;
      this.advance();
      const right = this.parseExpr(prec + 1);
      left = { kind: 'binary', op: t.value, left, right, line: t.line } as BinaryNode;
    }
    return left;
  }

  binaryPrec(type: string): number | null {
    if (type === 'or') return 1;
    if (type === 'and') return 2;
    if (type === '==' || type === '!=' || type === '<' || type === '<=' || type === '>' || type === '>=') return 4;
    if (type === '+' || type === '-') return 5;
    if (type === '*' || type === '/' || type === '%') return 6;
    return null;
  }

  parsePrefixExpr(): Expr {
    const t = this.peek();
    if (t.type === 'not') {
      this.advance();
      const operand = this.parseExpr(3);
      return { kind: 'unary', op: 'not', operand, line: t.line } as UnaryNode;
    }
    if (t.type === '-') {
      this.advance();
      const operand = this.parseExpr(7);
      return { kind: 'unary', op: '-', operand, line: t.line } as UnaryNode;
    }
    let expr = this.parsePrimary();
    // postfix loop
    while (true) {
      const pt = this.peek();
      if (pt.type === '(') {
        this.advance();
        const args: ExprNode[] = [];
        if (this.peek().type !== ')') {
          args.push(this.parseExpr(1));
          while (this.peek().type === ',') { this.advance(); args.push(this.parseExpr(1)); }
        }
        this.expect(')');
        expr = { kind: 'call', callee: expr, args, line: pt.line } as CallNode;
      } else if (pt.type === '[') {
        this.advance();
        const index = this.parseExpr(1);
        this.expect(']');
        expr = { kind: 'index', obj: expr, index, line: pt.line } as IndexNode;
      } else break;
    }
    return expr;
  }

  parsePrimary(): Expr {
    const t = this.peek();
    switch (t.type) {
      case 'INT': this.advance(); return { kind: 'int', value: BigInt(t.value), line: t.line } as IntLit;
      case 'STRING': this.advance(); return { kind: 'str', value: t.value, line: t.line } as StrLit;
      case 'true': this.advance(); return { kind: 'bool', value: true, line: t.line } as BoolLit;
      case 'false': this.advance(); return { kind: 'bool', value: false, line: t.line } as BoolLit;
      case 'nil': this.advance(); return { kind: 'nil', line: t.line } as NilLit;
      case 'IDENT': this.advance(); return { kind: 'ident', name: t.value, line: t.line } as IdentNode;
      case '(': {
        this.advance();
        const expr = this.parseExpr(1);
        this.expect(')');
        return expr;
      }
      case '[': {
        this.advance();
        const elements: ExprNode[] = [];
        if (this.peek().type !== ']') {
          elements.push(this.parseExpr(1));
          while (this.peek().type === ',') { this.advance(); elements.push(this.parseExpr(1)); }
        }
        this.expect(']');
        return { kind: 'list', elements, line: t.line } as ListLitNode;
      }
      case 'fn': {
        this.advance();
        this.expect('(');
        const params = this.parseParams();
        this.expect(')');
        const body = this.parseBlock();
        return { kind: 'fn', params, body, line: t.line } as FnExprNode;
      }
    }
    // shouldn't reach with valid input
    this.advance();
    return { kind: 'nil', line: t.line } as NilLit;
  }
}

// ===== VALUES =====
interface TVInt { t: 'int'; v: bigint; }
interface TVBool { t: 'bool'; v: boolean; }
interface TVStr { t: 'str'; v: string; }
interface TVList { t: 'list'; v: TV[]; }
interface TVFn { t: 'fn'; params: string[]; body: Stmt[]; scope: Scope; }
interface TVBuiltin { t: 'builtin'; name: string; fn: (args: TV[]) => TV; arity: number; }
interface TVNil { t: 'nil'; }
type TV = TVInt | TVBool | TVStr | TVList | TVFn | TVBuiltin | TVNil;

const NIL: TV = { t: 'nil' };
const TRUE: TV = { t: 'bool', v: true };
const FALSE: TV = { t: 'bool', v: false };
const INT64_MAX = (1n << 63n) - 1n;
const INT64_MIN = -(1n << 63n);

// ===== SCOPE =====
interface Scope { vars: Map<string, TV>; parent: Scope | null; }
function newScope(parent: Scope | null): Scope { return { vars: new Map(), parent }; }

function lookup(scope: Scope, name: string): TV | undefined {
  let s: Scope | null = scope;
  while (s !== null) {
    const v = s.vars.get(name);
    if (v !== undefined) return v;
    s = s.parent;
  }
  return undefined;
}

function assignVar(scope: Scope, name: string, value: TV): boolean {
  let s: Scope | null = scope;
  while (s !== null) {
    if (s.vars.has(name)) { s.vars.set(name, value); return true; }
    s = s.parent;
  }
  return false;
}

// ===== CONTROL FLOW =====
class BreakSignal {}
class ContinueSignal {}
class ReturnSignal { value: TV; constructor(v: TV) { this.value = v; } }
class TernError { line: number; msg: string; constructor(l: number, m: string) { this.line = l; this.msg = m; } }

// ===== DISPLAY =====
function typeName(v: TV): string {
  switch (v.t) {
    case 'int': return 'int';
    case 'bool': return 'bool';
    case 'str': return 'string';
    case 'list': return 'list';
    case 'fn': case 'builtin': return 'function';
    case 'nil': return 'nil';
  }
}

function quoteStr(s: string): string {
  let r = '"';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === '\\') r += '\\\\';
    else if (c === '"') r += '\\"';
    else if (c === '\n') r += '\\n';
    else if (c === '\t') r += '\\t';
    else r += c;
  }
  r += '"';
  return r;
}

function display(v: TV, nested: boolean, seen: Set<TV[]>): string {
  switch (v.t) {
    case 'int': return v.v.toString();
    case 'bool': return v.v ? 'true' : 'false';
    case 'str': return nested ? quoteStr(v.v) : v.v;
    case 'nil': return 'nil';
    case 'fn': case 'builtin': return '<fn>';
    case 'list': {
      if (seen.has(v.v)) return '[...]';
      seen.add(v.v);
      const parts: string[] = [];
      for (const el of v.v) parts.push(display(el, true, seen));
      seen.delete(v.v);
      return '[' + parts.join(', ') + ']';
    }
  }
}

function displayTop(v: TV): string { return display(v, false, new Set()); }

// ===== EQUALITY =====
function ternEq(a: TV, b: TV): boolean {
  if (a.t !== b.t) return false;
  switch (a.t) {
    case 'int': return a.v === (b as TVInt).v;
    case 'bool': return a.v === (b as TVBool).v;
    case 'str': return a.v === (b as TVStr).v;
    case 'nil': return true;
    case 'fn': return a === b;
    case 'builtin': return a === b;
    case 'list': {
      const la = a.v, lb = (b as TVList).v;
      if (la.length !== lb.length) return false;
      for (let i = 0; i < la.length; i++) {
        if (!ternEq(la[i], lb[i])) return false;
      }
      return true;
    }
  }
}

// ===== TRUTHINESS =====
function truthy(v: TV): boolean {
  switch (v.t) {
    case 'bool': return v.v;
    case 'nil': return false;
    case 'int': return v.v !== 0n;
    case 'str': return v.v.length !== 0;
    case 'list': return v.v.length !== 0;
    default: return true;
  }
}

// ===== BUILTINS =====
function makeBuiltins(): Map<string, TV> {
  const m = new Map<string, TV>();

  m.set('print', { t: 'builtin', name: 'print', arity: -1, fn: (args: TV[]): TV => {
    const parts: string[] = [];
    for (const a of args) parts.push(displayTop(a));
    outBuf.push(parts.join(' ') + '\n');
    return NIL;
  }});

  m.set('str', { t: 'builtin', name: 'str', arity: 1, fn: (args: TV[]): TV => {
    return { t: 'str', v: displayTop(args[0]) };
  }});

  m.set('type', { t: 'builtin', name: 'type', arity: 1, fn: (args: TV[]): TV => {
    return { t: 'str', v: typeName(args[0]) };
  }});

  m.set('len', { t: 'builtin', name: 'len', arity: 1, fn: (args: TV[]): TV => {
    const x = args[0];
    if (x.t === 'str') return { t: 'int', v: BigInt(x.v.length) };
    if (x.t === 'list') return { t: 'int', v: BigInt(x.v.length) };
    throw new TernError(0, 'bad argument to len');
  }});

  m.set('push', { t: 'builtin', name: 'push', arity: 2, fn: (args: TV[]): TV => {
    const x = args[0];
    if (x.t !== 'list') throw new TernError(0, 'bad argument to push');
    x.v.push(args[1]);
    return NIL;
  }});

  m.set('pop', { t: 'builtin', name: 'pop', arity: 1, fn: (args: TV[]): TV => {
    const x = args[0];
    if (x.t !== 'list' || x.v.length === 0) throw new TernError(0, 'bad argument to pop');
    return x.v.pop()!;
  }});

  m.set('range', { t: 'builtin', name: 'range', arity: 2, fn: (args: TV[]): TV => {
    const a = args[0], b = args[1];
    if (a.t !== 'int' || b.t !== 'int') throw new TernError(0, 'bad argument to range');
    const result: TV[] = [];
    for (let i = a.v; i < b.v; i++) result.push({ t: 'int', v: i });
    return { t: 'list', v: result };
  }});

  m.set('slice', { t: 'builtin', name: 'slice', arity: 3, fn: (args: TV[]): TV => {
    const x = args[0], a = args[1], b = args[2];
    if (x.t !== 'str' && x.t !== 'list') throw new TernError(0, 'bad argument to slice');
    if (a.t !== 'int' || b.t !== 'int') throw new TernError(0, 'bad argument to slice');
    const len = x.t === 'str' ? x.v.length : x.v.length;
    if (a.v < 0n || b.v > BigInt(len) || a.v > b.v) throw new TernError(0, 'bad argument to slice');
    if (x.t === 'str') return { t: 'str', v: x.v.slice(Number(a.v), Number(b.v)) };
    return { t: 'list', v: (x as TVList).v.slice(Number(a.v), Number(b.v)) };
  }});

  return m;
}

// ===== INTERPRETER =====
let outBuf: string[] = [];

function checkInt(v: bigint, line: number): TVInt {
  if (v > INT64_MAX || v < INT64_MIN) throw new TernError(line, 'integer overflow');
  return { t: 'int', v };
}

function evalExpr(expr: Expr, scope: Scope): TV {
  switch (expr.kind) {
    case 'int': return { t: 'int', v: expr.value };
    case 'str': return { t: 'str', v: expr.value };
    case 'bool': return expr.value ? TRUE : FALSE;
    case 'nil': return NIL;
    case 'ident': {
      const v = lookup(scope, expr.name);
      if (v === undefined) throw new TernError(expr.line, `undefined variable ${expr.name}`);
      return v;
    }
    case 'binary': {
      const op = expr.op;
      if (op === 'and') {
        const left = evalExpr(expr.left, scope);
        if (!truthy(left)) return left;
        return evalExpr(expr.right, scope);
      }
      if (op === 'or') {
        const left = evalExpr(expr.left, scope);
        if (truthy(left)) return left;
        return evalExpr(expr.right, scope);
      }
      const left = evalExpr(expr.left, scope);
      const right = evalExpr(expr.right, scope);
      return applyBinary(op, left, right, expr.line);
    }
    case 'unary': {
      if (expr.op === 'not') {
        const v = evalExpr(expr.operand, scope);
        return truthy(v) ? FALSE : TRUE;
      }
      // '-'
      const v = evalExpr(expr.operand, scope);
      if (v.t !== 'int') throw new TernError(expr.line, `cannot apply - to ${typeName(v)}`);
      return checkInt(-v.v, expr.line);
    }
    case 'call': {
      const callee = evalExpr(expr.callee, scope);
      const args: TV[] = [];
      for (const a of expr.args) args.push(evalExpr(a, scope));
      return callValue(callee, args, expr.line);
    }
    case 'index': {
      const obj = evalExpr(expr.obj, scope);
      const idx = evalExpr(expr.index, scope);
      return indexRead(obj, idx, expr.line);
    }
    case 'list': {
      const elements: TV[] = [];
      for (const el of expr.elements) elements.push(evalExpr(el, scope));
      return { t: 'list', v: elements };
    }
    case 'fn': {
      return { t: 'fn', params: expr.params, body: expr.body, scope };
    }
  }
  return NIL;
}

function applyBinary(op: string, left: TV, right: TV, line: number): TV {
  switch (op) {
    case '+': {
      if (left.t === 'int' && right.t === 'int') return checkInt(left.v + right.v, line);
      if (left.t === 'str' && right.t === 'str') return { t: 'str', v: left.v + right.v };
      if (left.t === 'list' && right.t === 'list') return { t: 'list', v: [...left.v, ...right.v] };
      throw new TernError(line, `cannot apply + to ${typeName(left)} and ${typeName(right)}`);
    }
    case '-': {
      if (left.t === 'int' && right.t === 'int') return checkInt(left.v - right.v, line);
      throw new TernError(line, `cannot apply - to ${typeName(left)} and ${typeName(right)}`);
    }
    case '*': {
      if (left.t === 'int' && right.t === 'int') return checkInt(left.v * right.v, line);
      throw new TernError(line, `cannot apply * to ${typeName(left)} and ${typeName(right)}`);
    }
    case '/': {
      if (left.t === 'int' && right.t === 'int') {
        if (right.v === 0n) throw new TernError(line, 'division by zero');
        return checkInt(left.v / right.v, line);
      }
      throw new TernError(line, `cannot apply / to ${typeName(left)} and ${typeName(right)}`);
    }
    case '%': {
      if (left.t === 'int' && right.t === 'int') {
        if (right.v === 0n) throw new TernError(line, 'division by zero');
        return checkInt(left.v % right.v, line);
      }
      throw new TernError(line, `cannot apply % to ${typeName(left)} and ${typeName(right)}`);
    }
    case '==': return ternEq(left, right) ? TRUE : FALSE;
    case '!=': return ternEq(left, right) ? FALSE : TRUE;
    case '<': {
      if (left.t === 'int' && right.t === 'int') return left.v < right.v ? TRUE : FALSE;
      if (left.t === 'str' && right.t === 'str') return left.v < right.v ? TRUE : FALSE;
      throw new TernError(line, `cannot apply < to ${typeName(left)} and ${typeName(right)}`);
    }
    case '<=': {
      if (left.t === 'int' && right.t === 'int') return left.v <= right.v ? TRUE : FALSE;
      if (left.t === 'str' && right.t === 'str') return left.v <= right.v ? TRUE : FALSE;
      throw new TernError(line, `cannot apply <= to ${typeName(left)} and ${typeName(right)}`);
    }
    case '>': {
      if (left.t === 'int' && right.t === 'int') return left.v > right.v ? TRUE : FALSE;
      if (left.t === 'str' && right.t === 'str') return left.v > right.v ? TRUE : FALSE;
      throw new TernError(line, `cannot apply > to ${typeName(left)} and ${typeName(right)}`);
    }
    case '>=': {
      if (left.t === 'int' && right.t === 'int') return left.v >= right.v ? TRUE : FALSE;
      if (left.t === 'str' && right.t === 'str') return left.v >= right.v ? TRUE : FALSE;
      throw new TernError(line, `cannot apply >= to ${typeName(left)} and ${typeName(right)}`);
    }
  }
  return NIL;
}

function indexRead(obj: TV, idx: TV, line: number): TV {
  if (obj.t !== 'list' && obj.t !== 'str') {
    throw new TernError(line, `cannot index ${typeName(obj)} with ${typeName(idx)}`);
  }
  if (idx.t !== 'int') {
    throw new TernError(line, `cannot index ${typeName(obj)} with ${typeName(idx)}`);
  }
  const i = idx.v;
  const len = obj.t === 'str' ? BigInt(obj.v.length) : BigInt(obj.v.length);
  if (i < 0n || i >= len) {
    throw new TernError(line, `index ${i} out of range for length ${len}`);
  }
  if (obj.t === 'str') return { t: 'str', v: obj.v[Number(i)] };
  return (obj as TVList).v[Number(i)];
}

function callValue(callee: TV, args: TV[], line: number): TV {
  if (callee.t === 'builtin') {
    if (callee.arity >= 0 && args.length !== callee.arity) {
      throw new TernError(line, `expected ${callee.arity} arguments, got ${args.length}`);
    }
    try {
      return callee.fn(args);
    } catch (e) {
      if (e instanceof TernError) { e.line = line; throw e; }
      throw e;
    }
  }
  if (callee.t === 'fn') {
    if (args.length !== callee.params.length) {
      throw new TernError(line, `expected ${callee.params.length} arguments, got ${args.length}`);
    }
    const callScope = newScope(callee.scope);
    for (let i = 0; i < callee.params.length; i++) {
      callScope.vars.set(callee.params[i], args[i]);
    }
    try {
      execBlock(callee.body, callScope);
    } catch (e) {
      if (e instanceof ReturnSignal) return e.value;
      throw e;
    }
    return NIL;
  }
  throw new TernError(line, `cannot call ${typeName(callee)}`);
}

function execBlock(stmts: Stmt[], scope: Scope): void {
  for (const s of stmts) execStmt(s, scope);
}

function execStmt(stmt: Stmt, scope: Scope): void {
  switch (stmt.kind) {
    case 'let': {
      const v = evalExpr(stmt.value, scope);
      scope.vars.set(stmt.name, v);
      break;
    }
    case 'fnDecl': {
      const fn: TVFn = { t: 'fn', params: stmt.params, body: stmt.body, scope };
      scope.vars.set(stmt.name, fn);
      break;
    }
    case 'assign': {
      const v = evalExpr(stmt.value, scope);
      if (!assignVar(scope, stmt.name, v)) {
        throw new TernError(stmt.line, `undefined variable ${stmt.name}`);
      }
      break;
    }
    case 'indexAssign': {
      const obj = evalExpr(stmt.obj, scope);
      const idx = evalExpr(stmt.index, scope);
      const val = evalExpr(stmt.value, scope);
      if (obj.t !== 'list') {
        throw new TernError(stmt.line, `cannot assign into ${typeName(obj)}`);
      }
      if (idx.t !== 'int') {
        throw new TernError(stmt.line, `cannot index list with ${typeName(idx)}`);
      }
      const i = idx.v;
      const len = BigInt(obj.v.length);
      if (i < 0n || i >= len) {
        throw new TernError(stmt.line, `index ${i} out of range for length ${len}`);
      }
      obj.v[Number(i)] = val;
      break;
    }
    case 'if': {
      if (truthy(evalExpr(stmt.cond, scope))) {
        const s = newScope(scope);
        execBlock(stmt.then, s);
      } else if (stmt.elseBranch !== null) {
        if (Array.isArray(stmt.elseBranch)) {
          const s = newScope(scope);
          execBlock(stmt.elseBranch, s);
        } else {
          execStmt(stmt.elseBranch, scope);
        }
      }
      break;
    }
    case 'while': {
      while (truthy(evalExpr(stmt.cond, scope))) {
        const s = newScope(scope);
        try {
          execBlock(stmt.body, s);
        } catch (e) {
          if (e instanceof BreakSignal) break;
          if (e instanceof ContinueSignal) continue;
          throw e;
        }
      }
      break;
    }
    case 'for': {
      const iterVal = evalExpr(stmt.iterable, scope);
      if (iterVal.t !== 'list') {
        throw new TernError(stmt.line, `cannot iterate ${typeName(iterVal)}`);
      }
      const list = iterVal.v;
      let i = 0;
      while (i < list.length) {
        const s = newScope(scope);
        s.vars.set(stmt.varName, list[i]);
        try {
          execBlock(stmt.body, s);
        } catch (e) {
          if (e instanceof BreakSignal) break;
          if (e instanceof ContinueSignal) { i++; continue; }
          throw e;
        }
        i++;
      }
      break;
    }
    case 'return': {
      const v = stmt.value !== null ? evalExpr(stmt.value, scope) : NIL;
      throw new ReturnSignal(v);
    }
    case 'break': throw new BreakSignal();
    case 'continue': throw new ContinueSignal();
    case 'expr': evalExpr(stmt.expr, scope); break;
  }
}

// ===== MAIN =====
const dir = process.argv[2];
const src = fs.readFileSync(path.join(dir, 'program.tern'), 'utf-8');
const tokens = tokenize(src);
const parser = new Parser(tokens);
const program = parser.parseProgram();

const globalScope = newScope(null);
const builtins = makeBuiltins();
for (const [name, fn] of builtins) globalScope.vars.set(name, fn);

try {
  execBlock(program, globalScope);
} catch (e) {
  if (e instanceof TernError) {
    outBuf.push(`error at line ${e.line}: ${e.msg}\n`);
  } else if (e instanceof ReturnSignal || e instanceof BreakSignal || e instanceof ContinueSignal) {
    // shouldn't happen
  } else {
    throw e;
  }
}

process.stdout.write(outBuf.join(''));

import sys
import os
import zlib


def split_lines(content):
    if content == b'':
        return []
    parts = content.split(b'\n')
    if parts[-1] == b'':
        return [p + b'\n' for p in parts[:-1]]
    else:
        return [p + b'\n' for p in parts[:-1]] + [parts[-1]]


def join_lines(lines):
    return b''.join(lines)


def parse_diff(diff_bytes):
    if diff_bytes.endswith(b'\n'):
        lines = diff_bytes[:-1].split(b'\n')
    else:
        lines = diff_bytes.split(b'\n')

    sections = []
    i = 0
    n = len(lines)

    while i < n:
        line = lines[i]
        if not line.startswith(b'diff --git '):
            i += 1
            continue

        rest = line[len(b'diff --git '):]
        space_idx = rest.index(b' ')
        path = rest[:space_idx][2:]

        section = {'path': path, 'kind': 'modify', 'hunks': []}
        i += 1

        while i < n:
            l = lines[i]
            if l.startswith(b'new file mode'):
                section['kind'] = 'create'
                i += 1
            elif l.startswith(b'deleted file mode'):
                section['kind'] = 'delete'
                i += 1
            elif l.startswith(b'index '):
                i += 1
            elif l.startswith(b'--- '):
                i += 1
                if i < n and lines[i].startswith(b'+++ '):
                    i += 1
                break
            elif l.startswith(b'@@ '):
                break
            else:
                break

        while i < n:
            l = lines[i]
            if l.startswith(b'@@ '):
                header = l[3:]
                at_pos = header.find(b'@@')
                range_part = header[:at_pos]
                range_parts = range_part.split()

                old_spec = range_parts[0][1:]
                new_spec = range_parts[1][1:]

                if b',' in old_spec:
                    a_str, b_str = old_spec.split(b',', 1)
                    a = int(a_str)
                    b_count = int(b_str)
                else:
                    a = int(old_spec)
                    b_count = 1

                if b',' in new_spec:
                    c_str, d_str = new_spec.split(b',', 1)
                    c = int(c_str)
                    d_count = int(d_str)
                else:
                    c = int(new_spec)
                    d_count = 1

                i += 1

                body = []
                while i < n:
                    bl = lines[i]
                    if bl.startswith(b'@@ ') or bl.startswith(b'diff --git '):
                        break
                    if bl.startswith(b' '):
                        body.append((' ', bl[1:]))
                    elif bl.startswith(b'-'):
                        body.append(('-', bl[1:]))
                    elif bl.startswith(b'+'):
                        body.append(('+', bl[1:]))
                    elif bl.startswith(b'\\'):
                        body.append(('\\',))
                    else:
                        break
                    i += 1

                old_lines = []
                new_lines = []
                for j, entry in enumerate(body):
                    if entry[0] == '\\':
                        continue
                    marker = entry[0]
                    content = entry[1]
                    has_nl = True
                    if j + 1 < len(body) and body[j + 1][0] == '\\':
                        has_nl = False
                    line_bytes = content + (b'\n' if has_nl else b'')

                    if marker == ' ':
                        old_lines.append(line_bytes)
                        new_lines.append(line_bytes)
                    elif marker == '-':
                        old_lines.append(line_bytes)
                    elif marker == '+':
                        new_lines.append(line_bytes)

                malformed = (len(old_lines) != b_count or len(new_lines) != d_count)
                section['hunks'].append({
                    'a': a, 'b': b_count, 'c': c, 'd': d_count,
                    'old_lines': old_lines, 'new_lines': new_lines,
                    'malformed': malformed
                })
            else:
                break

        sections.append(section)

    return sections


def main():
    input_dir = sys.argv[1]

    with open(os.path.join(input_dir, 'changes.diff'), 'rb') as f:
        diff_bytes = f.read()

    sections = parse_diff(diff_bytes)
    sections.sort(key=lambda s: s['path'])

    out = []

    for sec in sections:
        path_bytes = sec['path']
