import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.CRC32;

public class Main {

    static class Line {
        byte[] content;
        boolean hasNL;
        Line(byte[] content, boolean hasNL) {
            this.content = content;
            this.hasNL = hasNL;
        }
    }

    static boolean lineEquals(Line a, Line b) {
        return a.hasNL == b.hasNL && Arrays.equals(a.content, b.content);
    }

    static List<Line> splitLines(byte[] data) {
        List<Line> lines = new ArrayList<>();
        int pos = 0;
        while (pos < data.length) {
            int nl = -1;
            for (int i = pos; i < data.length; i++) {
                if (data[i] == '\n') { nl = i; break; }
            }
            if (nl >= 0) {
                lines.add(new Line(Arrays.copyOfRange(data, pos, nl), true));
                pos = nl + 1;
            } else {
                lines.add(new Line(Arrays.copyOfRange(data, pos, data.length), false));
                pos = data.length;
            }
        }
        return lines;
    }

    static byte[] joinLines(List<Line> lines) {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        for (Line l : lines) {
            bos.write(l.content, 0, l.content.length);
            if (l.hasNL) bos.write('\n');
        }
        return bos.toByteArray();
    }

    static class Hunk {
        int a, b, c, d;
        List<Line> oldLines;
        List<Line> newLines;
        boolean malformed;
    }

    static class Section {
        String path;
        String kind;
        List<Hunk> hunks;
    }

    static class HunkResult {
        String status;
        int position;
        int offset;
        HunkResult(String status, int position, int offset) {
            this.status = status;
            this.position = position;
            this.offset = offset;
        }
    }

    static void parseHunkHeader(String h, Hunk hunk) {
        int dashPos = h.indexOf('-', 3);
        int plusPos = h.indexOf('+', dashPos + 1);

        int i = dashPos + 1;
        int start = i;
        while (i < h.length() && Character.isDigit(h.charAt(i))) i++;
        hunk.a = Integer.parseInt(h.substring(start, i));
        if (i < h.length() && h.charAt(i) == ',') {
            i++;
            start = i;
            while (i < h.length() && Character.isDigit(h.charAt(i))) i++;
            hunk.b = Integer.parseInt(h.substring(start, i));
        } else {
            hunk.b = 1;
        }

        i = plusPos + 1;
        start = i;
        while (i < h.length() && Character.isDigit(h.charAt(i))) i++;
        hunk.c = Integer.parseInt(h.substring(start, i));
        if (i < h.length() && h.charAt(i) == ',') {
            i++;
            start = i;
            while (i < h.length() && Character.isDigit(h.charAt(i))) i++;
            hunk.d = Integer.parseInt(h.substring(start, i));
        } else {
            hunk.d = 1;
        }
    }

    static boolean matchAt(List<Line> content, int p, List<Line> oldLines) {
        for (int j = 0; j < oldLines.size(); j++) {
            if (!lineEquals(content.get(p - 1 + j), oldLines.get(j))) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        byte[] diffData = Files.readAllBytes(Paths.get(dir, "changes.diff"));

        // Split diff into lines
        List<byte[]> diffLines = new ArrayList<>();
        {
            int pos = 0;
            while (pos < diffData.length) {
                int nl = -1;
                for (int i = pos; i < diffData.length; i++) {
                    if (diffData[i] == '\n') { nl = i; break; }
                }
                if (nl >= 0) {
                    diffLines.add(Arrays.copyOfRange(diffData, pos, nl));
                    pos = nl + 1;
                } else {
                    diffLines.add(Arrays.copyOfRange(diffData, pos, diffData.length));
                    pos = diffData.length;
                }
            }
        }

        // Parse sections
        List<Section> sections = new ArrayList<>();
        int idx = 0;
        while (idx < diffLines.size()) {
            String s = new String(diffLines.get(idx), StandardCharsets.UTF_8);
            if (!s.startsWith("diff --git a/")) {
                idx++;
                continue;
            }

            String rest = s.substring("diff --git a/".length());
            int sp = rest.indexOf(' ');
            String path = rest.substring(0, sp);

            Section sec = new Section();
            sec.path = path;
            sec.kind = "modify";
            sec.hunks = new ArrayList<>();

            idx++;

            // Parse header lines
            while (idx < diffLines.size()) {
                String h = new String(diffLines.get(idx), StandardCharsets.UTF_8);
                if (h.startsWith("new file mode ")) {
                    sec.kind = "create"; idx++;
                } else if (h.startsWith("deleted file mode ")) {
                    sec.kind = "delete"; idx++;
                } else if (h.startsWith("index ")) {
                    idx++;
                } else if (h.startsWith("--- ")) {
                    idx++;
                } else if (h.startsWith("+++ ")) {
                    idx++;
                    break;
                } else {
                    break;
                }
            }

            // Parse hunks
            while (idx < diffLines.size()) {
                String h = new String(diffLines.get(idx), StandardCharsets.UTF_8);
                if (h.startsWith("diff --git ")) break;
                if (!h.startsWith("@@ ")) { idx++; continue; }

                Hunk hunk = new Hunk();
                parseHunkHeader(h, hunk);
                idx++;

                List<Line> oldLines = new ArrayList<>();
                List<Line> newLines = new ArrayList<>();
                char lastMarker = 0;

                while (idx < diffLines.size()) {
                    byte[] bl = diffLines.get(idx);
                    if (bl.length == 0) {
                        idx++;
                        continue;
                    }
                    char marker = (char)(bl[0] & 0xFF);

                    // Check end of hunk
                    if (marker == '@' && bl.length >= 3 && bl[1] == '@' && bl[2] == ' ') break;
                    if (bl.length >= 11) {
                        String bs = new String(bl, StandardCharsets.UTF_8);
                        if (bs.startsWith("diff --git ")) break;
                    }

                    if (marker == '\\') {
                        if (lastMarker == ' ') {
                            oldLines.get(oldLines.size() - 1).hasNL = false;
                            newLines.get(newLines.size() - 1).hasNL = false;
                        } else if (lastMarker == '-') {
                            oldLines.get(oldLines.size() - 1).hasNL = false;
                        } else if (lastMarker == '+') {
                            newLines.get(newLines.size() - 1).hasNL = false;
                        }
                        idx++;
                        continue;
                    }

                    byte[] content = Arrays.copyOfRange(bl, 1, bl.length);

                    if (marker == ' ') {
                        Line l = new Line(content, true);
                        oldLines.add(l);
                        newLines.add(l);
                        lastMarker = ' ';
                    } else if (marker == '-') {
                        oldLines.add(new Line(content, true));
                        lastMarker = '-';
                    } else if (marker == '+') {
                        newLines.add(new Line(content, true));
                        lastMarker = '+';
                    }

                    idx++;
                }

                hunk.oldLines = oldLines;
                hunk.newLines = newLines;
                hunk.malformed = (oldLines.size() != hunk.b || newLines.size() != hunk.d);
                sec.hunks.add(hunk);
            }

            sections.add(sec);
        }

        // Sort by path bytewise
        sections.sort((a, b) -> {
            byte[] ab = a.path.getBytes(StandardCharsets.UTF_8);
            byte[] bb = b.path.getBytes(StandardCharsets.UTF_8);
            int len = Math.min(ab.length, bb.length);
            for (int i = 0; i < len; i++) {
                int cmp = (ab[i] & 0xFF) - (bb[i] & 0xFF);
                if (cmp != 0) return cmp;
            }
            return ab.length - bb.length;
        });

        StringBuilder out = new StringBuilder();

        for (Section sec : sections) {
            out.append(sec.path).append(": ").append(sec.kind).append("\n");

            Path filePath = Paths.get(dir, "tree", sec.path);
            boolean fileExists = Files.exists(filePath);

            if (sec.kind.equals("create")) {
                if (fileExists) {
                    out.append("  error: already exists\n");
                    continue;
                }
            } else {
                if (!fileExists) {
                    out.append("  error: not found\n");
                    continue;
                }
            }

            List<Line> content;
            if (sec.kind.equals("create")) {
                content = new ArrayList<>();
            } else {
                byte[] fileData = Files.readAllBytes(filePath);
                content = splitLines(fileData);
            }

            int delta = 0;
            List<HunkResult> results = new ArrayList<>();

            for (Hunk hunk : sec.hunks) {
                if (hunk.malformed) {
                    results.add(new HunkResult("malformed", 0, 0));
                    continue;
                }

                int P = hunk.a + delta;

                if (hunk.b == 0) {
                    if (P >= 0 && P <= content.size()) {
                        content.addAll(P, hunk.newLines);
                        results.add(new HunkResult("applied", P, 0));
                        delta += hunk.d - hunk.b;
                    } else {
                        results.add(new HunkResult("rejected", 0, 0));
                    }
                } else {
                    int lineCount = content.size();
                    boolean found = false;
                    int foundP = -1;

                    for (int k = 0; ; k++) {
                        boolean anyValid = false;
                        if (k == 0) {
                            int p = P;
                            if (p >= 1 && p + hunk.b - 1 <= lineCount) {
                                anyValid = true;
                                if (matchAt(content, p, hunk.oldLines)) {
                                    found = true; foundP = p; break;
                                }
                            }
                        } else {
                            int p1 = P - k;
                            if (p1 >= 1 && p1 + hunk.b - 1 <= lineCount) {
                                anyValid = true;
                                if (matchAt(content, p1, hunk.oldLines)) {
                                    found = true; foundP = p1; break;
                                }
                            }
                            int p2 = P + k;
                            if (p2 >= 1 && p2 + hunk.b - 1 <= lineCount) {
                                anyValid = true;
                                if (matchAt(content, p2, hunk.oldLines)) {
                                    found = true; foundP = p2; break;
                                }
                            }
                        }
                        if (!anyValid) break;
                    }

                    if (found) {
                        int startIdx = foundP - 1;
                        for (int j = 0; j < hunk.b; j++) {
                            content.remove(startIdx);
                        }
                        content.addAll(startIdx, hunk.newLines);
                        int offset = foundP - P;
                        results.add(new HunkResult("applied", foundP, offset));
                        delta += hunk.d - hunk.b;
                    } else {
                        results.add(new HunkResult("rejected", 0, 0));
                    }
                }
            }

            for (int i = 0; i < results.size(); i++) {
                HunkResult r = results.get(i);
                out.append("  hunk ").append(i + 1).append(": ");
                if (r.status.equals("applied")) {
                    out.append("applied at ").append(r.position).append(" (offset ");
                    if (r.offset > 0) out.append("+").append(r.offset);
                    else out.append(r.offset);
                    out.append(")\n");
                } else {
                    out.append(r.status).append("\n");
                }
            }

            if (sec.kind.equals("delete")) {
                boolean allApplied = true;
                for (HunkResult r : results) {
                    if (!r.status.equals("applied")) { allApplied = false; break; }
                }
                if (allApplied && content.isEmpty()) {
                    out.append("  result: deleted\n");
                } else {
                    byte[] finalBytes = joinLines(content);
                    CRC32 crc = new CRC32();
                    crc.update(finalBytes);
                    out.append("  result: ").append(content.size()).append(" lines, crc32 ");
                    out.append(String.format("%08x", crc.getValue())).append("\n");
                }
            } else {
                byte[] finalBytes = joinLines(content);
                CRC32 crc = new CRC32();
                crc.update(finalBytes);
                out.append("  result: ").append(content.size()).append(" lines, crc32 ");
                out.append(String.format("%08x", crc.getValue())).append("\n");
            }
        }

        System.out.print(out.toString());
    }
}

