let cp1252: [UInt32] = [
    0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
    0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
    0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
    0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178
]
func win1252(_ b: UInt8) -> UInt32 {
    if b >= 0x80 && b <= 0x9F { return cp1252[Int(b - 0x80)] }
    return UInt32(b)
}

// Charset decode
func decodeCharset(_ bytes: [UInt8], _ charset: String) -> [UInt32] {
    let cs = charset.lowercased()
    switch cs {
    case "us-ascii", "iso-8859-1":
        return bytes.map { UInt32($0) }
    case "windows-1252":
        return bytes.map { win1252($0) }
    case "utf-8":
        return decodeUTF8(bytes)
    default:
        return bytes.map { UInt32($0) }
    }
}

func decodeUTF8(_ bytes: [UInt8]) -> [UInt32] {
    var result: [UInt32] = []
    var i = 0
    while i < bytes.count {
        let b = bytes[i]
        if b < 0x80 {
            result.append(UInt32(b))
            i += 1
        } else if b < 0xC0 {
            result.append(UInt32(b))
            i += 1
        } else if b < 0xE0 {
            if i + 1 < bytes.count && (bytes[i + 1] & 0xC0) == 0x80 {
                result.append((UInt32(b & 0x1F) << 6) | UInt32(bytes[i + 1] & 0x3F))
                i += 2
            } else {
                result.append(UInt32(b))
                i += 1
            }
        } else if b < 0xF0 {
            if i + 2 < bytes.count && (bytes[i + 1] & 0xC0) == 0x80 && (bytes[i + 2] & 0xC0) == 0x80 {
                result.append((UInt32(b & 0x0F) << 12) | (UInt32(bytes[i + 1] & 0x3F) << 6) | UInt32(bytes[i + 2] & 0x3F))
                i += 3
            } else {
                result.append(UInt32(b))
                i += 1
            }
        } else if b < 0xF8 {
            if i + 3 < bytes.count && (bytes[i + 1] & 0xC0) == 0x80 && (bytes[i + 2] & 0xC0) == 0x80 && (bytes[i + 3] & 0xC0) == 0x80 {
                result.append((UInt32(b & 0x07) << 18) | (UInt32(bytes[i + 1] & 0x3F) << 12) | (UInt32(bytes[i + 2] & 0x3F) << 6) | UInt32(bytes[i + 3] & 0x3F))
                i += 4
            } else {
                result.append(UInt32(b))
                i += 1
            }
        } else {
            result.append(UInt32(b))
            i += 1
        }
    }
    return result
}

// RFC 2047 Q decode
func rfc2047QDecode(_ bytes: [UInt8]) -> [UInt8] {
    var result: [UInt8] = []
    var i = 0
    while i < bytes.count {
        if bytes[i] == 0x5F {
            result.append(0x20)
            i += 1
        } else if bytes[i] == 0x3D && i + 2 < bytes.count {
            let h1 = hexVal(bytes[i + 1])
            let h2 = hexVal(bytes[i + 2])
            if h1 >= 0 && h2 >= 0 {
                result.append(UInt8(h1 * 16 + h2))
                i += 3
            } else {
                result.append(0x3D)
                i += 1
            }
        } else {
            result.append(bytes[i])
            i += 1
        }
    }
    return result
}

// RFC 2047 decode
func rfc2047Decode(_ text: String) -> [UInt32] {
    let bytes: [UInt8] = Array(text.utf8)
    struct EW {
        let start: Int
        let end: Int
        let cs: String
        let data: [UInt8]
    }
    var words: [EW] = []
    var i = 0
    while i < bytes.count {
        if i + 1 < bytes.count && bytes[i] == 0x3D && bytes[i + 1] == 0x3F {
            var j = i + 2
            var csBytes: [UInt8] = []
            while j < bytes.count && bytes[j] != 0x3F && bytes[j] != 0x20 && bytes[j] != 0x09 {
                csBytes.append(bytes[j])
                j += 1
            }
            if j < bytes.count && bytes[j] == 0x3F && !csBytes.isEmpty {
                j += 1
                if j < bytes.count && (bytes[j] == 0x42 || bytes[j] == 0x62 || bytes[j] == 0x51 || bytes[j] == 0x71) {
                    let enc = bytes[j]
                    j += 1
                    if j < bytes.count && bytes[j] == 0x3F {
                        j += 1
                        var tb: [UInt8] = []
                        while j < bytes.count && bytes[j] != 0x3F && bytes[j] != 0x20 && bytes[j] != 0x09 {
                            tb.append(bytes[j])
                            j += 1
                        }
                        if j + 1 < bytes.count && bytes[j] == 0x3F && bytes[j + 1] == 0x3D {
                            let cs = String(bytes: csBytes, encoding: .ascii) ?? "us-ascii"
                            var decoded: [UInt8]
                            if enc == 0x42 || enc == 0x62 {
                                decoded = base64Decode(tb)
                            } else {
                                decoded = rfc2047QDecode(tb)
                            }
                            words.append(EW(start: i, end: j + 2, cs: cs, data: decoded))
                            i = j + 2
                            continue
                        }
                    }
                }
            }
        }
        i += 1
    }
    var result: [UInt32] = []
    var pos = 0
    var wi = 0
    while wi < words.count {
        if words[wi].start > pos {
            for k in pos ..< words[wi].start {
                result.append(UInt32(bytes[k]))
            }
        }
        var gb = words[wi].data
        var gcs = words[wi].cs.lowercased()
        if let sp = gcs.firstIndex(of: "*") {
            gcs = String(gcs[gcs.startIndex ..< sp])
        }
        var gEnd = words[wi].end
        var nwi = wi + 1
        while nwi < words.count {
            var adj = true
            for k in gEnd ..< words[nwi].start {
                if bytes[k] != 0x20 && bytes[k] != 0x09 {
                    adj = false
                    break
                }
            }
            var ncs = words[nwi].cs.lowercased()
            if let sp = ncs.firstIndex(of: "*") {
                ncs = String(ncs[ncs.startIndex ..< sp])
            }
            if adj && ncs == gcs {
                gb.append(contentsOf: words[nwi].data)
                gEnd = words[nwi].end
                nwi += 1
            } else {
                break
            }
        }
        result.append(contentsOf: decodeCharset(gb, gcs))
        pos = gEnd
        wi = nwi
    }
    if pos < bytes.count {
        for k in pos ..< bytes.count {
            result.append(UInt32(bytes[k]))
        }
    }
    return result
}

// Percent decode
func percentDecode(_ s: String) -> [UInt8] {
    var bytes: [UInt8] = []
    let chars = Array(s)
    var i = 0
    while i < chars.count {
        if chars[i] == "%" && i + 2 < chars.count {
            let h1 = hexCharVal(chars[i + 1])
            let h2 = hexCharVal(chars[i + 2])
            if h1 >= 0 && h2 >= 0 {
                bytes.append(UInt8(h1 * 16 + h2))
                i += 3
            } else {
                bytes.append(0x25)
                i += 1
            }
        } else {
            bytes.append(UInt8(ascii: chars[i]))
            i += 1
        }
    }
    return bytes
}

// RFC 2231
func splitRFC2231Val(_ v: String) -> (charset: String, lang: String, encoded: String) {
    var parts: [String] = []
    var cur = ""
    var q = 0
    for ch in v {
        if ch == "'" && q < 2 {
            parts.append(cur)
            cur = ""
            q += 1
        } else {
            cur.append(ch)
        }
    }
    parts.append(cur)
    if parts.count >= 3 { return (parts[0], parts[1], parts[2]) }
    if parts.count == 2 { return (parts[0], "", parts[1]) }
    return ("", "", v)
}

func rfc2231Decode(params: [String: String], baseName: String) -> [UInt32]? {
    let lb = baseName.lowercased()
    let sk = lb + "*"
    if let v = params[sk] {
        let (cs, _, enc) = splitRFC2231Val(v)
        let bytes = percentDecode(enc)
        return decodeCharset(bytes, cs.isEmpty ? "us-ascii" : cs)
    }
    var segs: [(index: Int, pct: Bool, value: String)] = []
    var charset: String? = nil
    var idx = 0
    while true {
        let pk = lb + "*\(idx)*"
        let lk = lb + "*\(idx)"
        if let v = params[pk] {
            if idx == 0 {
                let (cs, _, enc) = splitRFC2231Val(v)
                charset = cs.isEmpty ? nil : cs
                segs.append((idx, true, enc))
            } else {
                segs.append((idx, true, v))
            }
        } else if let v = params[lk] {
            segs.append((idx, false, v))
        } else {
            break
        }
        idx += 1
    }
    if segs.isEmpty { return nil }
    segs.sort { $0.index < $1.index }
    var bytes: [UInt8] = []
    for s in segs {
        if s.pct {
            bytes.append(contentsOf: percentDecode(s.value))
        } else {
            bytes.append(contentsOf: Array(s.value.utf8))
        }
    }
    return decodeCharset(bytes, charset ?? "us-ascii")
}

// Content-Type parser
func parseContentType(_ value: String) -> (type: String, subtype: String, params: [String: String]) {
    var params: [String: String] = [:]
    let ch = Array(value)
    var i = 0
    while i < ch.count && (ch[i] == " " || ch[i] == "\t") { i += 1 }
    var typeS = ""
    while i < ch.count && ch[i] != "/" && ch[i] != ";" && ch[i] != " " && ch[i] != "\t" {
        typeS.append(ch[i])
        i += 1
    }
    while i < ch.count && (ch[i] == " " || ch[i] == "\t") { i += 1 }
    if i < ch.count && ch[i] == "/" { i += 1 }
    while i < ch.count && (ch[i] == " " || ch[i] == "\t") { i += 1 }
    var subS = ""
    while i < ch.count && ch[i] != ";" && ch[i] != " " && ch[i] != "\t" {
        subS.append(ch[i])
        i += 1
    }
    while i < ch.count {
        while i < ch.count && (ch[i] == " " || ch[i] == "\t" || ch[i] == ";") { i += 1 }
        if i >= ch.count { break }
        var attr = ""
        while i < ch.count && ch[i] != "=" && ch[i] != ";" && ch[i] != " " && ch[i] != "\t" {
            attr.append(ch[i])
            i += 1
        }
        while i < ch.count && (ch[i] == " " || ch[i] == "\t") { i += 1 }
        if i < ch.count && ch[i] == "=" { i += 1 }
        while i < ch.count && (ch[i] == " " || ch[i] == "\t") { i += 1 }
        var val = ""
        if i < ch.count && ch[i] == "\"" {
            i += 1
            while i < ch.count && ch[i] != "\"" {
                if ch[i] == "\\" && i + 1 < ch.count {
                    i += 1
                    val.append(ch[i])
                } else {
                    val.append(ch[i])
                }
                i += 1
            }
            if i < ch.count { i += 1 }
        } else {
            while i < ch.count && ch[i] != ";" && ch[i] != " " && ch[i] != "\t" {
                val.append(ch[i])
                i += 1
            }
        }
        if !attr.isEmpty { params[attr.lowercased()] = val }
    }
    return (typeS.lowercased(), subS.lowercased(), params)
}

// Content-Disposition parser
func parseContentDisposition(_ value: String) -> (type: String, params: [String: String]) {
    var params: [String: String] = [:]
    let ch = Array(value)
    var i = 0
    while i < ch.count && (ch[i] == " " || ch[i] == "\t") { i += 1 }
    var dt = ""
    while i < ch.count && ch[i] != ";" && ch[i] != " " && ch[i] != "\t" {
        dt.append(ch[i])
        i += 1
    }
    while i < ch.count {
        while i < ch.count && (ch[i] == " " || ch[i] == "\t" || ch[i] == ";") { i += 1 }
        if i >= ch.count { break }
        var attr = ""
        while i < ch.count && ch[i] != "=" && ch[i] != ";" && ch[i] != " " && ch[i] != "\t" {
            attr.append(ch[i])
            i += 1
        }
        while i < ch.count && (ch[i] == " " || ch[i] == "\t") { i += 1 }
        if i < ch.count && ch[i] == "=" { i += 1 }
        while i < ch.count && (ch[i] == " " || ch[i] == "\t") { i += 1 }
        var val = ""
        if i < ch.count && ch[i] == "\"" {
            i += 1
            while i < ch.count && ch[i] != "\"" {
                if ch[i] == "\\" && i + 1 < ch.count {
                    i += 1
                    val.append(ch[i])
                } else {
                    val.append(ch[i])
                }
                i += 1
            }
            if i < ch.count { i += 1 }
        } else {
            while i < ch.count && ch[i] != ";" && ch[i] != " " && ch[i] != "\t" {
                val.append(ch[i])
                i += 1
            }
        }
        if !attr.isEmpty { params[attr.lowercased()] = val }
    }
    return (dt.lowercased(), params)
}

// Line break detection
func detectLineBreak(_ data: [UInt8]) -> [UInt8] {
    for i in 0 ..< data.count {
        if data[i] == 0x0D && i + 1 < data.count && data[i + 1] == 0x0A {
            return [0x0D, 0x0A]
        }
    }
    return [0x0A]
}

// Entity
struct Entity {
    var headers: [String: String]
    var bodyBytes: [UInt8]
    var parts: [Entity]?
}

// Parse entity
func parseEntity(_ data: [UInt8], _ lb: [UInt8]) -> Entity {
    var emptyPos = -1
    var pos = 0
    while pos < data.count {
        var le = pos
        while le < data.count {
            if le + lb.count <= data.count && Array(data[le ..< le + lb.count]) == lb { break }
            le += 1
        }
        if le == pos {
            emptyPos = pos
            break
        }
        if le < data.count { pos = le + lb.count } else { break }
    }
    var headers: [String: String] = [:]
    var bodyBytes: [UInt8]
    if emptyPos >= 0 {
        let hs = Array(data[0 ..< emptyPos])
        if emptyPos + lb.count <= data.count {
            bodyBytes = Array(data[(emptyPos + lb.count)...])
        } else {
            bodyBytes = []
        }
        var hLines: [[UInt8]] = []
        var hp = 0
        while hp < hs.count {
            var le = hp
            while le < hs.count {
                if le + lb.count <= hs.count && Array(hs[le ..< le + lb.count]) == lb { break }
                le += 1
            }
            hLines.append(Array(hs[hp ..< le]))
            if le < hs.count { hp = le + lb.count } else { break }
        }
        var unfolded: [String] = []
        for line in hLines {
            if !line.isEmpty && (line[0] == 0x20 || line[0] == 0x09) {
                if !unfolded.isEmpty {
                    unfolded[unfolded.count - 1] += String(bytes: line, encoding: .ascii) ?? ""
                }
            } else {
                unfolded.append(String(bytes: line, encoding: .ascii) ?? "")
            }
        }
        for line in unfolded {
            if let ci = line.firstIndex(of: ":") {
                let nm = String(line[line.startIndex ..< ci]).lowercased()
                var v = String(line[line.index(after: ci)...])
                v = v.trimmingCharacters(in: CharacterSet(charactersIn: " \t"))
                headers[nm] = v
            }
        }
    } else {
        bodyBytes = []
        if !data.isEmpty {
            let s = String(bytes: data, encoding: .ascii) ?? ""
            if let ci = s.firstIndex(of: ":") {
                let nm = String(s[s.startIndex ..< ci]).lowercased()
                var v = String(s[s.index(after: ci)...])
                v = v.trimmingCharacters(in: CharacterSet(charactersIn: " \t"))
                headers[nm] = v
            }
        }
    }
    let ctV = headers["content-type"] ?? "text/plain"
    let (tp, _, ctP) = parseContentType(ctV)
    var parts: [Entity]? = nil
    if tp == "multipart" {
        if let bnd = ctP["boundary"] {
            parts = extractParts(bodyBytes, lb, bnd)
        }
    }
    return Entity(headers: headers, bodyBytes: bodyBytes, parts: parts)
}

// Extract multipart parts
func extractParts(_ body: [UInt8], _ lb: [UInt8], _ boundary: String) -> [Entity] {
    let dBytes: [UInt8] = Array("--\(boundary)".utf8)
    let cBytes: [UInt8] = Array("--\(boundary)--".utf8)
    struct LI {
        let start: Int
        let end: Int
        let isD: Bool
        let isC: Bool
    }
    var lines: [LI] = []
    var pos = 0
    while pos < body.count {
        var le = pos
        while le < body.count {
            if le + lb.count <= body.count && Array(body[le ..< le + lb.count]) == lb { break }
            le += 1
        }
        let content = Array(body[pos ..< le])
        var isD = false
        var isC = false
        if content.count >= cBytes.count && Array(content[0 ..< cBytes.count]) == cBytes {
            if content[cBytes.count...].allSatisfy({ $0 == 0x20 || $0 == 0x09 }) {
                isC = true
            }
        }
        if !isC && content.count >= dBytes.count && Array(content[0 ..< dBytes.count]) == dBytes {
            if content[dBytes.count...].allSatisfy({ $0 == 0x20 || $0 == 0x09 }) {
                isD = true
            }
        }
        lines.append(LI(start: pos, end: le, isD: isD, isC: isC))
        if le < body.count { pos = le + lb.count } else { break }
    }
    // Collect delimiter/close-delimiter indices
    var delimIndices: [Int] = []
    for (idx, ln) in lines.enumerated() {
        if ln.isD || ln.isC {
            delimIndices.append(idx)
            if ln.isC { break }
        }
    }
    if delimIndices.count < 2 { return [] }
    var parts: [Entity] = []
    for i in 0 ..< (delimIndices.count - 1) {
        let dIdx = delimIndices[i]
        let nextIdx = delimIndices[i + 1]
        let cs = lines[dIdx].end + lb.count
        let ce: Int
        if nextIdx - 1 >= dIdx + 1 {
            ce = lines[nextIdx - 1].end
        } else {
            ce = cs
        }
        if ce > cs {
            parts.append(parseEntity(Array(body[cs ..< ce]), lb))
        } else {
            parts.append(parseEntity([], lb))
        }
    }
    return parts
}

// Quoted string output
func quotedString(_ cps: [UInt32]) -> String {
    var r = "\""
    for cp in cps {
        if cp == 0x5C {
            r += "\\\\"
        } else if cp == 0x22 {
            r += "\\\""
        } else if cp == 0x0A {
            r += "\\n"
        } else if cp == 0x09 {
            r += "\\t"
        } else if cp < 0x20 || (cp >= 0x7F && cp <= 0x9F) {
            r += String(format: "\\u%04x", cp)
        } else {
            if let s = Unicode.Scalar(cp) {
                r.unicodeScalars.append(s)
            }
        }
    }
    r += "\""
    return r
}

// Print entity tree
func printEntity(_ ent: Entity, level: Int, lb: [UInt8]) {
    let ind = String(repeating: "  ", count: level)
    let ctV = ent.headers["content-type"] ?? "text/plain"
    let (tp, sub, ctP) = parseContentType(ctV)
    let cte = (ent.headers["content-transfer-encoding"] ?? "7bit").lowercased()
    if tp == "multipart" {
        print("\(ind)multipart/\(sub) parts=\(ent.parts?.count ?? 0)")
        if let ps = ent.parts {
            for p in ps {
                printEntity(p, level: level + 1, lb: lb)
            }
        }
    } else {
        let cdV = ent.headers["content-disposition"]
        var dispT = "-"
        var cdP: [String: String] = [:]
        if let cd = cdV {
            let (dt, dp) = parseContentDisposition(cd)
            dispT = dt
            cdP = dp
        }
        if tp == "text" && dispT != "attachment" {
            let charset = (ctP["charset"] ?? "us-ascii").lowercased()
            var db: [UInt8]
            switch cte {
            case "base64":
                db = base64Decode(ent.bodyBytes)
            case "quoted-printable":
                db = qpDecode(ent.bodyBytes, lb)
            default:
                db = ent.bodyBytes
            }
            let cps = decodeCharset(db, charset)
            var fixed: [UInt32] = []
            var i = 0
            while i < cps.count {
                if cps[i] == 0x0D {
                    fixed.append(0x0A)
                    if i + 1 < cps.count && cps[i + 1] == 0x0A {
                        i += 2
                    } else {
                        i += 1
                    }
                } else {
                    fixed.append(cps[i])
                    i += 1
                }
            }
            print("\(ind)text/\(sub) charset=\(charset) cte=\(cte) chars=\(fixed.count)")
            print("\(ind)  \(quotedString(fixed))")
        } else {
            var db: [UInt8]
            switch cte {
            case "base64":
                db = base64Decode(ent.bodyBytes)
            case "quoted-printable":
                db = qpDecode(ent.bodyBytes, lb)
            default:
                db = ent.bodyBytes
            }
            let sz = db.count
            let crc = crc32(db)
            var nameCP: [UInt32]? = nil
            if let r = rfc2231Decode(params: cdP, baseName: "filename") { nameCP = r }
            if nameCP == nil, let fn = cdP["filename"] { nameCP = rfc2047Decode(fn) }
            if nameCP == nil, let r = rfc2231Decode(params: ctP, baseName: "name") { nameCP = r }
            if nameCP == nil, let n = ctP["name"] { nameCP = rfc2047Decode(n) }
            let nStr: String
            if let ncp = nameCP {
                nStr = quotedString(ncp)
            } else {
                nStr = "-"
            }
            print("\(ind)\(tp)/\(sub) cte=\(cte) disposition=\(dispT) name=\(nStr) size=\(sz) crc32=\(String(format: "%08x", crc))")
        }
    }
}

// Main
initCRC()
let args = CommandLine.arguments
guard args.count >= 2 else { exit(0) }
let dirPath = args[1]
guard let entries = try? FileManager.default.contentsOfDirectory(atPath: dirPath) else { exit(0) }
let emlFiles = entries.filter { $0.hasSuffix(".eml") }.sorted { a, b in
    Array(a.utf8).lexicographicallyPrecedes(Array(b.utf8))
}
for (idx, fn) in emlFiles.enumerated() {
    if idx > 0 { print("") }
    let fp = dirPath + "/" + fn
    guard let data = FileManager.default.contents(atPath: fp) else { continue }
    let bytes = [UInt8](data)
    let lb = detectLineBreak(bytes)
    let ent = parseEntity(bytes, lb)
    print("== \(fn)")
    if let f = ent.headers["from"] {
        print("From: \(quotedString(rfc2047Decode(f)))")
    } else {
        print("From: -")
    }
    if let s = ent.headers["subject"] {
        print("Subject: \(quotedString(rfc2047Decode(s)))")
    } else {
        print("Subject: -")
    }
    printEntity(ent, level: 0, lb: lb)
}
exit(0)

import Foundation

// ============ TOKENS ============

enum TK: UInt8 {
    case intLit, strLit, ident
    case kwLet, kwFn, kwIf, kwElse, kwWhile, kwFor, kwIn, kwReturn, kwBreak, kwContinue
    case kwAnd, kwOr, kwNot, kwTrue, kwFalse, kwNil
    case plus, minus, star, slash, percent
    case eq, neq, lt, le, gt, ge
    case assign
    case lparen, rparen, lbracket, rbracket, lbrace, rbrace
    case comma, semicolon
    case eof
}

struct Token {
    var kind: TK
    var intVal: Int = 0
    var strVal: String = ""
    var line: Int = 1
}

func tokenize(_ src: [UInt8]) -> [Token] {
    var tokens: [Token] = []
    tokens.reserveCapacity(src.count / 3)
    var pos = 0
    var line = 1
    let n = src.count

    func isDigit(_ c: UInt8) -> Bool { c >= 48 && c <= 57 }
    func isAlpha(_ c: UInt8) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }
    func isAlnum(_ c: UInt8) -> Bool { isAlpha(c) || isDigit(c) }

    while true {
        // skip whitespace and comments
        while pos < n {
            let c = src[pos]
            if c == 10 { line += 1; pos += 1 }
            else if c == 32 || c == 9 || c == 13 { pos += 1 }
            else if c == 35 { while pos < n && src[pos] != 10 { pos += 1 } }
            else { break }
        }
        if pos >= n { tokens.append(Token(kind: .eof, line: line)); break }

        let c = src[pos]
        let ln = line

        if isDigit(c) {
            var val: Int = 0
            while pos < n && isDigit(src[pos]) {
                val = val &* 10 &+ Int(src[pos] - 48)
                pos += 1
            }
            tokens.append(Token(kind: .intLit, intVal: val, line: ln))
        } else if c == 34 {
            pos += 1
            var buf: [UInt8] = []
            while pos < n && src[pos] != 34 {
                if src[pos] == 92 {
                    pos += 1
                    let e = src[pos]
                    switch e {
                    case 110: buf.append(10)
                    case 116: buf.append(9)
                    case 34:  buf.append(34)
                    case 92:  buf.append(92)
                    default:  buf.append(e)
                    }
                    pos += 1
                } else {
                    buf.append(src[pos])
                    pos += 1
                }
            }
            pos += 1
            tokens.append(Token(kind: .strLit, strVal: String(decoding: buf, as: UTF8.self), line: ln))
        } else if isAlpha(c) {
            var buf: [UInt8] = []
            while pos < n && isAlnum(src[pos]) {
                buf.append(src[pos])
                pos += 1
            }
            let str = String(decoding: buf, as: UTF8.self)
            let kind: TK
            switch str {
            case "let": kind = .kwLet
            case "fn": kind = .kwFn
            case "if": kind = .kwIf
            case "else": kind = .kwElse
            case "while": kind = .kwWhile
            case "for": kind = .kwFor
            case "in": kind = .kwIn
            case "return": kind = .kwReturn
            case "break": kind = .kwBreak
            case "continue": kind = .kwContinue
            case "and": kind = .kwAnd
            case "or": kind = .kwOr
            case "not": kind = .kwNot
            case "true": kind = .kwTrue
            case "false": kind = .kwFalse
            case "nil": kind = .kwNil
            default: kind = .ident
            }
            tokens.append(Token(kind: kind, strVal: str, line: ln))
        } else {
            let next: UInt8? = pos + 1 < n ? src[pos + 1] : nil
            if c == 61 && next == 61 { tokens.append(Token(kind: .eq, line: ln)); pos += 2; continue }
            if c == 33 && next == 61 { tokens.append(Token(kind: .neq, line: ln)); pos += 2; continue }
            if c == 60 && next == 61 { tokens.append(Token(kind: .le, line: ln)); pos += 2; continue }
            if c == 62 && next == 61 { tokens.append(Token(kind: .ge, line: ln)); pos += 2; continue }

            switch c {
            case 43: tokens.append(Token(kind: .plus, line: ln))
            case 45: tokens.append(Token(kind: .minus, line: ln))
            case 42: tokens.append(Token(kind: .star, line: ln))
            case 47: tokens.append(Token(kind: .slash, line: ln))
            case 37: tokens.append(Token(kind: .percent, line: ln))
            case 61: tokens.append(Token(kind: .assign, line: ln))
            case 60: tokens.append(Token(kind: .lt, line: ln))
            case 62: tokens.append(Token(kind: .gt, line: ln))
            case 40: tokens.append(Token(kind: .lparen, line: ln))
            case 41: tokens.append(Token(kind: .rparen, line: ln))
            case 91: tokens.append(Token(kind: .lbracket, line: ln))
            case 93: tokens.append(Token(kind: .rbracket, line: ln))
            case 123: tokens.append(Token(kind: .lbrace, line: ln))
            case 125: tokens.append(Token(kind: .rbrace, line: ln))
            case 44: tokens.append(Token(kind: .comma, line: ln))
            case 59: tokens.append(Token(kind: .semicolon, line: ln))
            default: pos += 1; continue
            }
            pos += 1
        }
    }
    return tokens
}

// ============ AST ============

indirect enum Expr {
    case intLit(Int, Int)
    case strLit(String, Int)
    case boolLit(Bool, Int)
    case nilLit(Int)
    case ident(String, Int)
    case binop(op: String, lhs: Expr, rhs: Expr, line: Int)
    case unop(op: String, operand: Expr, line: Int)
    case call(callee: Expr, args: [Expr], line: Int)
    case index(obj: Expr, idx: Expr, line: Int)
    case listLit([Expr], Int)
    case fnExpr(params: [String], body: [ASTStmt], line: Int)
}

enum ElsePart {
    case none
    case elseIf(ASTStmt)
    case elseBlock([ASTStmt])
}

indirect enum ASTStmt {
    case letDecl(name: String, value: Expr, line: Int)
    case fnDecl(name: String, params: [String], body: [ASTStmt], line: Int)
    case ifStmt(cond: Expr, then: [ASTStmt], elsePart: ElsePart, line: Int)
    case whileStmt(cond: Expr, body: [ASTStmt], line: Int)
    case forStmt(varName: String, iterable: Expr, body: [ASTStmt], line: Int)
    case returnStmt(value: Expr?, line: Int)
    case breakStmt(Int)
    case continueStmt(Int)
    case assign(name: String, value: Expr, line: Int)
    case indexAssign(obj: Expr, idx: Expr, value: Expr, line: Int)
    case exprStmt(expr: Expr, line: Int)
}

// ============ VALUES ============

enum Val {
    case int(Int)
    case bool(Bool)
    case string(String)
    case list(ListRef)
    case func(FuncRef)
    case nil_
}

final class ListRef {
    var elements: [Val]
    init(_ e: [Val] = []) { elements = e }
}

final class FuncRef {
    let params: [String]
    let body: [ASTStmt]
    let capturedScope: Scope?
    let builtinName: String
    let builtinArity: Int
    let builtinImpl: (([Val], Int) throws -> Val)?

    init(params: [String], body: [ASTStmt], scope: Scope) {
        self.params = params
        self.body = body
        self.capturedScope = scope
        self.builtinName = ""
        self.builtinArity = 0
        self.builtinImpl = nil
    }
    init(builtin name: String, arity: Int, impl: @escaping ([Val], Int) throws -> Val) {
        self.params = []
        self.body = []
        self.capturedScope = nil
        self.builtinName = name
        self.builtinArity = arity
        self.builtinImpl = impl
    }
}

// ============ SCOPE ============

final class Scope {
    var vars: [String: Val]
    let parent: Scope?
    init(parent: Scope?) { vars = [:]; self.parent = parent }

    func lookup(_ name: String) -> Val? {
        var s: Scope? = self
        while let sc = s {
            if let v = sc.vars[name] { return v }
            s = sc.parent
        }
        return nil
    }
    func assign(_ name: String, _ value: Val) -> Bool {
        var s: Scope? = self
        while let sc = s {
            if sc.vars[name] != nil { sc.vars[name] = value; return true }
            s = sc.parent
        }
        return false
    }
    func declare(_ name: String, _ value: Val) { vars[name] = value }
}

// ============ ERRORS & CONTROL FLOW ============

struct TernError: Error {
    let line: Int
    let message: String
}

enum Ctrl {
    case normal
    case breakLoop
    case continueLoop
    case returnVal(Val)
}

// ============ PARSER ============

final class Parser {
    let tokens: [Token]
    var pos = 0
    init(_ t: [Token]) { tokens = t }

    func peek() -> Token { tokens[pos] }
    func advance() -> Token { let t = tokens[pos]; pos += 1; return t }
    func expect(_ k: TK) { pos += 1 }

    func parseProgram() -> [ASTStmt] {
        var s: [ASTStmt] = []
        while peek().kind != .eof { s.append(parseStmt()) }
        return s
    }

    func parseStmt() -> ASTStmt {
        let t = peek()
        switch t.kind {
        case .kwLet:
            pos += 1
            let name = advance().strVal
            expect(.assign)
            let v = parseExpr()
            expect(.semicolon)
            return .letDecl(name: name, value: v, line: t.line)
        case .kwFn:
            pos += 1
            let name = advance().strVal
            expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnDecl(name: name, params: params, body: body, line: t.line)
        case .kwIf:
            return parseIfStmt()
        case .kwWhile:
            pos += 1
            let cond = parseExpr()
            let body = parseBlock()
            return .whileStmt(cond: cond, body: body, line: t.line)
        case .kwFor:
            pos += 1
            let vn = advance().strVal
            expect(.kwIn)
            let iter = parseExpr()
            let body = parseBlock()
            return .forStmt(varName: vn, iterable: iter, body: body, line: t.line)
        case .kwReturn:
            pos += 1
            if peek().kind == .semicolon { pos += 1; return .returnStmt(value: nil, line: t.line) }
            let v = parseExpr()
            expect(.semicolon)
            return .returnStmt(value: v, line: t.line)
        case .kwBreak:
            pos += 1; expect(.semicolon); return .breakStmt(t.line)
        case .kwContinue:
            pos += 1; expect(.semicolon); return .continueStmt(t.line)
        default:
            // assignment, index-assign, or expr stmt
            if t.kind == .ident && tokens[pos + 1].kind == .assign {
                let name = advance().strVal
                pos += 1 // skip =
                let v = parseExpr()
                expect(.semicolon)
                return .assign(name: name, value: v, line: t.line)
            }
            let expr = parseExpr()
            if peek().kind == .assign {
                pos += 1
                let v = parseExpr()
                expect(.semicolon)
                if case let .index(obj, idx, _) = expr {
                    return .indexAssign(obj: obj, idx: idx, value: v, line: t.line)
                }
                return .exprStmt(expr: expr, line: t.line)
            }
            expect(.semicolon)
            return .exprStmt(expr: expr, line: t.line)
        }
    }

    func parseIfStmt() -> ASTStmt {
        let t = advance()
        let cond = parseExpr()
        let then = parseBlock()
        var ep: ElsePart = .none
        if peek().kind == .kwElse {
            pos += 1
            if peek().kind == .kwIf { ep = .elseIf(parseIfStmt()) }
            else { ep = .elseBlock(parseBlock()) }
        }
        return .ifStmt(cond: cond, then: then, elsePart: ep, line: t.line)
    }

    func parseBlock() -> [ASTStmt] {
        expect(.lbrace)
        var s: [ASTStmt] = []
        while peek().kind != .rbrace { s.append(parseStmt()) }
        expect(.rbrace)
        return s
    }

    func parseParams() -> [String] {
        var p: [String] = []
        if peek().kind != .rparen {
            p.append(advance().strVal)
            while peek().kind == .comma { pos += 1; p.append(advance().strVal) }
        }
        return p
    }

    func parseExpr() -> Expr { parseOr() }

    func parseOr() -> Expr {
        var l = parseAnd()
        while peek().kind == .kwOr {
            let t = advance(); let r = parseAnd()
            l = .binop(op: "or", lhs: l, rhs: r, line: t.line)
        }
        return l
    }

    func parseAnd() -> Expr {
        var l = parseNot()
        while peek().kind == .kwAnd {
            let t = advance(); let r = parseNot()
            l = .binop(op: "and", lhs: l, rhs: r, line: t.line)
        }
        return l
    }

    func parseNot() -> Expr {
        if peek().kind == .kwNot {
            let t = advance(); let o = parseNot()
            return .unop(op: "not", operand: o, line: t.line)
        }
        return parseCmp()
    }

    func parseCmp() -> Expr {
        var l = parseAdd()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .eq: op = "=="
            case .neq: op = "!="
            case .lt: op = "<"
            case .le: op = "<="
            case .gt: op = ">"
            case .ge: op = ">="
            default: return l
            }
            pos += 1; let r = parseAdd()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseAdd() -> Expr {
        var l = parseMul()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .plus: op = "+"
            case .minus: op = "-"
            default: return l
            }
            pos += 1; let r = parseMul()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseMul() -> Expr {
        var l = parseUnary()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .star: op = "*"
            case .slash: op = "/"
            case .percent: op = "%"
            default: return l
            }
            pos += 1; let r = parseUnary()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseUnary() -> Expr {
        if peek().kind == .minus {
            let t = advance(); let o = parseUnary()
            return .unop(op: "neg", operand: o, line: t.line)
        }
        return parsePostfix()
    }

    func parsePostfix() -> Expr {
        var e = parsePrimary()
        while true {
            let t = peek()
            if t.kind == .lparen {
                pos += 1
                var args: [Expr] = []
                if peek().kind != .rparen {
                    args.append(parseExpr())
                    while peek().kind == .comma { pos += 1; args.append(parseExpr()) }
                }
                expect(.rparen)
                e = .call(callee: e, args: args, line: t.line)
            } else if t.kind == .lbracket {
                pos += 1
                let idx = parseExpr()
                expect(.rbracket)
                e = .index(obj: e, idx: idx, line: t.line)
            } else { break }
        }
        return e
    }

    func parsePrimary() -> Expr {
        let t = peek()
        switch t.kind {
        case .intLit: pos += 1; return .intLit(t.intVal, t.line)
        case .strLit: pos += 1; return .strLit(t.strVal, t.line)
        case .kwTrue: pos += 1; return .boolLit(true, t.line)
        case .kwFalse: pos += 1; return .boolLit(false, t.line)
        case .kwNil: pos += 1; return .nilLit(t.line)
        case .ident: pos += 1; return .ident(t.strVal, t.line)
        case .lparen:
            pos += 1; let e = parseExpr(); expect(.rparen); return e
        case .lbracket:
            pos += 1
            var elems: [Expr] = []
            if peek().kind != .rbracket {
                elems.append(parseExpr())
                while peek().kind == .comma { pos += 1; elems.append(parseExpr()) }
            }
            expect(.rbracket)
            return .listLit(elems, t.line)
        case .kwFn:
            pos += 1; expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnExpr(params: params, body: body, line: t.line)
        default:
            pos += 1; return .nilLit(t.line)
        }
    }
}

// ============ TYPE NAME ============

func typeName(_ v: Val) -> String {
    switch v {
    case .int: return "int"
    case .bool: return "bool"
    case .string: return "string"
    case .list: return "list"
    case .func: return "function"
    case .nil_: return "nil"
    }
}

// ============ TRUTHINESS ============

func truthy(_ v: Val) -> Bool {
    switch v {
    case .int(let i): return i != 0
    case .bool(let b): return b
    case .string(let s): return !s.isEmpty
    case .list(let l): return !l.elements.isEmpty
    case .func: return true
    case .nil_: return false
    }
}

// ============ DISPLAY ============

func displayVal(_ v: Val, inList: Bool, seen: inout Set<ObjectIdentifier>) -> String {
    switch v {
    case .int(let i): return String(i)
    case .bool(let b): return b ? "true" : "false"
    case .nil_: return "nil"
    case .func: return "<fn>"
    case .string(let s):
        if inList { return quoteString(s) }
        return s
    case .list(let l):
        let oid = ObjectIdentifier(l)
        if seen.contains(oid) { return "[...]" }
        seen.insert(oid)
        var parts: [String] = []
        parts.reserveCapacity(l.elements.count)
        for e in l.elements {
            parts.append(displayVal(e, inList: true, seen: &seen))
        }
        seen.remove(oid)
        return "[" + parts.joined(separator: ", ") + "]"
    }
}

func quoteString(_ s: String) -> String {
    var r = "\""
    for ch in s.unicodeScalars {
        switch ch {
        case "\\": r += "\\\\"
        case "\"": r += "\\\""
        case "\n": r += "\\n"
        case "\t": r += "\\t"
        default: r.unicodeScalars.append(ch)
        }
    }
    r += "\""
    return r
}

// ============ VALUE EQUALITY ============

func valEqual(_ a: Val, _ b: Val) -> Bool {
    switch (a, b) {
    case (.int(let x), .int(let y)): return x == y
    case (.bool(let x), .bool(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.nil_, .nil_): return true
    case (.func(let x), .func(let y)): return x === y
    case (.list(let x), .list(let y)):
        if x === y { return true }
        if x.elements.count != y.elements.count { return false }
        for i in 0..<x.elements.count {
            if !valEqual(x.elements[i], y.elements[i]) { return false }
        }
        return true
    default: return false
    }
}

// ============ BUILTINS ============

func makeBuiltins() -> Scope {
    let s = Scope(parent: nil)

    s.declare("print", .func(FuncRef(builtin: "print", arity: -1) { args, ln in
        var parts: [String] = []
        parts.reserveCapacity(args.count)
        for a in args {
            var seen = Set<ObjectIdentifier>()
            parts.append(displayVal(a, inList: false, seen: &seen))
        }
        print(parts.joined(separator: " "))
        return .nil_
    }))

    s.declare("str", .func(FuncRef(builtin: "str", arity: 1) { args, ln in
        var seen = Set<ObjectIdentifier>()
        return .string(displayVal(args[0], inList: false, seen: &seen))
    }))

    s.declare("type", .func(FuncRef(builtin: "type", arity: 1) { args, _ in
        .string(typeName(args[0]))
    }))

    s.declare("len", .func(FuncRef(builtin: "len", arity: 1) { args, ln in
        switch args[0] {
        case .string(let s): return .int(s.count)
        case .list(let l): return .int(l.elements.count)
        default: throw TernError(line: ln, message: "bad argument to len")
        }
    }))

    s.declare("push", .func(FuncRef(builtin: "push", arity: 2) { args, ln in
        switch args[0] {
        case .list(let l): l.elements.append(args[1]); return .nil_
        default: throw TernError(line: ln, message: "bad argument to push")
        }
    }))

    s.declare("pop", .func(FuncRef(builtin: "pop", arity: 1) { args, ln in
        switch args[0] {
        case .list(let l):
            if l.elements.isEmpty { throw TernError(line: ln, message: "bad argument to pop") }
            return l.elements.removeLast()
        default: throw TernError(line: ln, message: "bad argument to pop")
        }
    }))

    s.declare("range", .func(FuncRef(builtin: "range", arity: 2) { args, ln in
        guard case .int(let a) = args[0], case .int(let b) = args[1] else {
            throw TernError(line: ln, message: "bad argument to range")
        }
        if b <= a { return .list(ListRef()) }
        var elems: [Val] = []
        elems.reserveCapacity(b - a)
        var i = a
        while i < b { elems.append(.int(i)); i += 1 }
        return .list(ListRef(elems))
    }))

    s.declare("slice", .func(FuncRef(builtin: "slice", arity: 3) { args, ln in
        guard case .int(let a) = args[1], case .int(let b) = args[2] else {
            throw TernError(line: ln, message: "bad argument to slice")
        }
        switch args[0] {
        case .string(let s):
            let chars = Array(s)
            if a < 0 || b > chars.count || a > b { throw TernError(line: ln, message: "bad argument to slice") }
            return .string(String(chars[a..<b]))
        case .list(let l):
            if a < 0 || b > l.elements.count || a > b { throw TernError(line: ln, message: "bad argument to slice") }
            return .list(ListRef(Array(l.elements[a..<b])))
        default:
            throw TernError(line: ln, message: "bad argument to slice")
        }
    }))

    return s
}

// ============ INTERPRETER ============

func evalExpr(_ e: Expr, _ scope: Scope) throws -> Val {
    switch e {
    case .intLit(let v, _): return .int(v)
    case .strLit(let s, _): return .string(s)
    case .boolLit(let b, _): return .bool(b)
    case .nilLit: return .nil_
    case .ident(let name, let ln):
        if let v = scope.lookup(name) { return v }
        throw TernError(line: ln, message: "undefined variable \(name)")

    case .binop(let op, let lhs, let rhs, let ln):
        if op == "and" {
            let lv = try evalExpr(lhs, scope)
            if !truthy(lv) { return lv }
            return try evalExpr(rhs, scope)
        }
        if op == "or" {
            let lv = try evalExpr(lhs, scope)
            if truthy(lv) { return lv }
            return try evalExpr(rhs, scope)
        }
        if op == "==" {
            let lv = try evalExpr(lhs, scope)
            let rv = try evalExpr(rhs, scope)
            return .bool(valEqual(lv, rv))
        }
        if op == "!=" {
            let lv = try evalExpr(lhs, scope)
            let rv = try evalExpr(rhs, scope)
            return .bool(!valEqual(lv, rv))
        }
        // arithmetic and comparison operators
        let lv = try evalExpr(lhs, scope)
        let rv = try evalExpr(rhs, scope)
        return try applyBinop(op, lv, rv, ln)

    case .unop(let op, let operand, let ln):
        if op == "not" {
            let v = try evalExpr(operand, scope)
            return .bool(!truthy(v))
        }
        // neg
        let v = try evalExpr(operand, scope)
        guard case .int(let i) = v else {
            throw TernError(line: ln, message: "cannot apply - to \(typeName(v))")
        }
        if i == Int.min { throw TernError(line: ln, message: "integer overflow") }
        return .int(-i)

    case .call(let callee, let argExprs, let ln):
        let fnVal = try evalExpr(callee, scope)
        var args: [Val] = []
        args.reserveCapacity(argExprs.count)
        for ae in argExprs { args.append(try evalExpr(ae, scope)) }
        guard case .func(let f) = fnVal else {
            throw TernError(line: ln, message: "cannot call \(typeName(fnVal))")
        }
        if f.builtinImpl != nil {
            // builtin
            if f.builtinArity >= 0 && args.count != f.builtinArity {
                throw TernError(line: ln, message: "expected \(f.builtinArity) arguments, got \(args.count)")
            }
            return try f.builtinImpl!(args, ln)
        } else {
            // user function
            if args.count != f.params.count {
                throw TernError(line: ln, message: "expected \(f.params.count) arguments, got \(args.count)")
            }
            let callScope = Scope(parent: f.capturedScope!)
            for i in 0..<f.params.count {
                callScope.declare(f.params[i], args[i])
            }
            let result = try execBlock(f.body, callScope)
            if case .returnVal(let v) = result { return v }
            return .nil_
        }

    case .index(let obj, let idx, let ln):
        let ov = try evalExpr(obj, scope)
        let iv = try evalExpr(idx, scope)
        return try indexRead(ov, iv, ln)

    case .listLit(let elems, _):
        var vals: [Val] = []
        vals.reserveCapacity(elems.count)
        for el in elems { vals.append(try evalExpr(el, scope)) }
        return .list(ListRef(vals))

    case .fnExpr(let params, let body, _):
        return .func(FuncRef(params: params, body: body, scope: scope))
    }
}

func indexRead(_ obj: Val, _ idx: Val, _ ln: Int) throws -> Val {
    switch obj {
    case .list(let l):
        guard case .int(let i) = idx else {
            throw TernError(line: ln, message: "cannot index list with \(typeName(idx))")
        }
        if i < 0 || i >= l.elements.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(l.elements.count)")
        }
        return l.elements[i]
    case .string(let s):
        guard case .int(let i) = idx else {
            throw TernError(line: ln, message: "cannot index string with \(typeName(idx))")
        }
        let chars = Array(s)
        if i < 0 || i >= chars.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(chars.count)")
        }
        return .string(String(chars[i]))
    default:
        throw TernError(line: ln, message: "cannot index \(typeName(obj)) with \(typeName(idx))")
    }
}

func applyBinop(_ op: String, _ lv: Val, _ rv: Val, _ ln: Int) throws -> Val {
    switch op {
    case "+":
        if case .int(let a) = lv, case .int(let b) = rv {
            let (r, ov) = a.addingReportingOverflow(b)
            if ov { throw TernError(line: ln, message: "integer overflow") }
            return .int(r)
        }
        if case .string(let a) = lv, case .string(let b) = rv { return .string(a + b) }
        if case .list(let a) = lv, case .list(let b) = rv {
            var elems = a.elements
            elems.append(contentsOf: b.elements)
            return .list(ListRef(elems))
        }
        throw TernError(line: ln, message: "cannot apply + to \(typeName(lv)) and \(typeName(rv))")
    case "-":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply - to \(typeName(lv)) and \(typeName(rv))")
        }
        let (r, ov) = a.subtractingReportingOverflow(b)
        if ov { throw TernError(line: ln, message: "integer overflow") }
        return .int(r)
    case "*":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply * to \(typeName(lv)) and \(typeName(rv))")
        }
        let (r, ov) = a.multipliedReportingOverflow(by: b)
        if ov { throw TernError(line: ln, message: "integer overflow") }
        return .int(r)
    case "/":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply / to \(typeName(lv)) and \(typeName(rv))")
        }
        if b == 0 { throw TernError(line: ln, message: "division by zero") }
        if a == Int.min && b == -1 { throw TernError(line: ln, message: "integer overflow") }
        return .int(a / b) // Swift truncates toward zero
    case "%":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply % to \(typeName(lv)) and \(typeName(rv))")
        }
        if b == 0 { throw TernError(line: ln, message: "division by zero") }
        if b == -1 { return .int(0) }
        return .int(a % b) // Swift % gives sign of dividend
    case "<":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a < b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a < b) }
        throw TernError(line: ln, message: "cannot apply < to \(typeName(lv)) and \(typeName(rv))")
    case "<=":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a <= b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a <= b) }
        throw TernError(line: ln, message: "cannot apply <= to \(typeName(lv)) and \(typeName(rv))")
    case ">":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a > b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a > b) }
        throw TernError(line: ln, message: "cannot apply > to \(typeName(lv)) and \(typeName(rv))")
    case ">=":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a >= b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a >= b) }
        throw TernError(line: ln, message: "cannot apply >= to \(typeName(lv)) and \(typeName(rv))")
    default:
        throw TernError(line: ln, message: "unknown operator \(op)")
    }
}

func execBlock(_ stmts: [ASTStmt], _ scope: Scope) throws -> Ctrl {
    for s in stmts {
        let c = try execStmt(s, scope)
        switch c {
        case .normal: continue
        default: return c
        }
    }
    return .normal
}

func execStmt(_ s: ASTStmt, _ scope: Scope) throws -> Ctrl {
    switch s {
    case .letDecl(let name, let value, _):
        let v = try evalExpr(value, scope)
        scope.declare(name, v)
        return .normal

    case .fnDecl(let name, let params, let body, _):
        let f = FuncRef(params: params, body: body, scope: scope)
        scope.declare(name, .func(f))
        return .normal

    case .ifStmt(let cond, let then, let elsePart, _):
        let cv = try evalExpr(cond, scope)
        if truthy(cv) {
            let inner = Scope(parent: scope)
            return try execBlock(then, inner)
        } else {
            switch elsePart {
            case .none: return .normal
            case .elseIf(let stmt): return try execStmt(stmt, scope)
            case .elseBlock(let stmts):
                let inner = Scope(parent: scope)
                return try execBlock(stmts, inner)
            }
        }

    case .whileStmt(let cond, let body, _):
        while true {
            let cv = try evalExpr(cond, scope)
            if !truthy(cv) { break }
            let inner = Scope(parent: scope)
            let c = try execBlock(body, inner)
            switch c {
            case .breakLoop: break
            case .continueLoop: continue
            case .returnVal(let v): return .returnVal(v)
            case .normal: continue
            }
        }
        return .normal

    case .forStmt(let varName, let iterable, let body, let ln):
        let iterVal = try evalExpr(iterable, scope)
        guard case .list(let lst) = iterVal else {
            throw TernError(line: ln, message: "cannot iterate \(typeName(iterVal))")
        }
        var i = 0
        while i < lst.elements.count {
            let inner = Scope(parent: scope)
            inner.declare(varName, lst.elements[i])
            let c = try execBlock(body, inner)
            switch c {
            case .breakLoop: break
            case .continueLoop: i += 1; continue
            case .returnVal(let v): return .returnVal(v)
            case .normal: i += 1; continue
            }
            break // breakLoop exits while
        }
        return .normal

    case .returnStmt(let value, _):
        if let v = value { return .returnVal(try evalExpr(v, scope)) }
        return .returnVal(.nil_)

    case .breakStmt: return .breakLoop
    case .continueStmt: return .continueLoop

    case .assign(let name, let value, let ln):
        let v = try evalExpr(value, scope)
        if !scope.assign(name, v) {
            throw TernError(line: ln, message: "undefined variable \(name)")
        }
        return .normal

    case .indexAssign(let obj, let idx, let value, let ln):
        let ov = try evalExpr(obj, scope)
        let iv = try evalExpr(idx, scope)
        let vv = try evalExpr(value, scope)
        guard case .list(let l) = ov else {
            throw TernError(line: ln, message: "cannot assign into \(typeName(ov))")
        }
        guard case .int(let i) = iv else {
            throw TernError(line: ln, message: "cannot index list with \(typeName(iv))")
        }
        if i < 0 || i >= l.elements.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(l.elements.count)")
        }
        l.elements[i] = vv
        return .normal

    case .exprStmt(let expr, _):
        _ = try evalExpr(expr, scope)
        return .normal
    }
}

// ============ MAIN ============

func main() {
    let args = CommandLine.arguments
    guard args.count >= 2 else { exit(0) }
    let dir = args[1]
    let path = dir + "/program.tern"
    guard let data = FileManager.default.contents(atPath: path) else { exit(0) }
    let src = [UInt8](data)

    let tokens = tokenize(src)
    let parser = Parser(tokens)
    let program = parser.parseProgram()

    let builtins = makeBuiltins()
    let globalScope = Scope(parent: builtins)

    do {
        _ = try execBlock(program, globalScope)
    } catch let e as TernError {
        print("error at line \(e.line): \(e.message)")
    } catch {
        // shouldn't happen
    }
    fflush(stdout)
    exit(0)
}

main()

import Foundation

// ============ TOKENS ============

enum TK: UInt8 {
    case intLit, strLit, ident
    case kwLet, kwFn, kwIf, kwElse, kwWhile, kwFor, kwIn, kwReturn, kwBreak, kwContinue
    case kwAnd, kwOr, kwNot, kwTrue, kwFalse, kwNil
    case plus, minus, star, slash, percent
    case eq, neq, lt, le, gt, ge
    case assign
    case lparen, rparen, lbracket, rbracket, lbrace, rbrace
    case comma, semicolon
    case eof
}

struct Token {
    var kind: TK
    var intVal: Int = 0
    var strVal: String = ""
    var line: Int = 1
}

func tokenize(_ src: [UInt8]) -> [Token] {
    var tokens: [Token] = []
    tokens.reserveCapacity(src.count / 3)
    var pos = 0
    var line = 1
    let n = src.count

    func isDigit(_ c: UInt8) -> Bool { c >= 48 && c <= 57 }
    func isAlpha(_ c: UInt8) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }
    func isAlnum(_ c: UInt8) -> Bool { isAlpha(c) || isDigit(c) }

    while true {
        // skip whitespace and comments
        while pos < n {
            let c = src[pos]
            if c == 10 { line += 1; pos += 1 }
            else if c == 32 || c == 9 || c == 13 { pos += 1 }
            else if c == 35 { while pos < n && src[pos] != 10 { pos += 1 } }
            else { break }
        }
        if pos >= n { tokens.append(Token(kind: .eof, line: line)); break }

        let c = src[pos]
        let ln = line

        if isDigit(c) {
            var val: Int = 0
            while pos < n && isDigit(src[pos]) {
                val = val &* 10 &+ Int(src[pos] - 48)
                pos += 1
            }
            tokens.append(Token(kind: .intLit, intVal: val, line: ln))
        } else if c == 34 {
            pos += 1
            var buf: [UInt8] = []
            while pos < n && src[pos] != 34 {
                if src[pos] == 92 {
                    pos += 1
                    let e = src[pos]
                    switch e {
                    case 110: buf.append(10)
                    case 116: buf.append(9)
                    case 34:  buf.append(34)
                    case 92:  buf.append(92)
                    default:  buf.append(e)
                    }
                    pos += 1
                } else {
                    buf.append(src[pos])
                    pos += 1
                }
            }
            pos += 1
            tokens.append(Token(kind: .strLit, strVal: String(decoding: buf, as: UTF8.self), line: ln))
        } else if isAlpha(c) {
            var buf: [UInt8] = []
            while pos < n && isAlnum(src[pos]) {
                buf.append(src[pos])
                pos += 1
            }
            let str = String(decoding: buf, as: UTF8.self)
            let kind: TK
            switch str {
            case "let": kind = .kwLet
            case "fn": kind = .kwFn
            case "if": kind = .kwIf
            case "else": kind = .kwElse
            case "while": kind = .kwWhile
            case "for": kind = .kwFor
            case "in": kind = .kwIn
            case "return": kind = .kwReturn
            case "break": kind = .kwBreak
            case "continue": kind = .kwContinue
            case "and": kind = .kwAnd
            case "or": kind = .kwOr
            case "not": kind = .kwNot
            case "true": kind = .kwTrue
            case "false": kind = .kwFalse
            case "nil": kind = .kwNil
            default: kind = .ident
            }
            tokens.append(Token(kind: kind, strVal: str, line: ln))
        } else {
            let next: UInt8? = pos + 1 < n ? src[pos + 1] : nil
            if c == 61 && next == 61 { tokens.append(Token(kind: .eq, line: ln)); pos += 2; continue }
            if c == 33 && next == 61 { tokens.append(Token(kind: .neq, line: ln)); pos += 2; continue }
            if c == 60 && next == 61 { tokens.append(Token(kind: .le, line: ln)); pos += 2; continue }
            if c == 62 && next == 61 { tokens.append(Token(kind: .ge, line: ln)); pos += 2; continue }

            switch c {
            case 43: tokens.append(Token(kind: .plus, line: ln))
            case 45: tokens.append(Token(kind: .minus, line: ln))
            case 42: tokens.append(Token(kind: .star, line: ln))
            case 47: tokens.append(Token(kind: .slash, line: ln))
            case 37: tokens.append(Token(kind: .percent, line: ln))
            case 61: tokens.append(Token(kind: .assign, line: ln))
            case 60: tokens.append(Token(kind: .lt, line: ln))
            case 62: tokens.append(Token(kind: .gt, line: ln))
            case 40: tokens.append(Token(kind: .lparen, line: ln))
            case 41: tokens.append(Token(kind: .rparen, line: ln))
            case 91: tokens.append(Token(kind: .lbracket, line: ln))
            case 93: tokens.append(Token(kind: .rbracket, line: ln))
            case 123: tokens.append(Token(kind: .lbrace, line: ln))
            case 125: tokens.append(Token(kind: .rbrace, line: ln))
            case 44: tokens.append(Token(kind: .comma, line: ln))
            case 59: tokens.append(Token(kind: .semicolon, line: ln))
            default: pos += 1; continue
            }
            pos += 1
        }
    }
    return tokens
}

// ============ AST ============

indirect enum Expr {
    case intLit(Int, Int)
    case strLit(String, Int)
    case boolLit(Bool, Int)
    case nilLit(Int)
    case ident(String, Int)
    case binop(op: String, lhs: Expr, rhs: Expr, line: Int)
    case unop(op: String, operand: Expr, line: Int)
    case call(callee: Expr, args: [Expr], line: Int)
    case index(obj: Expr, idx: Expr, line: Int)
    case listLit([Expr], Int)
    case fnExpr(params: [String], body: [ASTStmt], line: Int)
}

enum ElsePart {
    case none
    case elseIf(ASTStmt)
    case elseBlock([ASTStmt])
}

indirect enum ASTStmt {
    case letDecl(name: String, value: Expr, line: Int)
    case fnDecl(name: String, params: [String], body: [ASTStmt], line: Int)
    case ifStmt(cond: Expr, then: [ASTStmt], elsePart: ElsePart, line: Int)
    case whileStmt(cond: Expr, body: [ASTStmt], line: Int)
    case forStmt(varName: String, iterable: Expr, body: [ASTStmt], line: Int)
    case returnStmt(value: Expr?, line: Int)
    case breakStmt(Int)
    case continueStmt(Int)
    case assign(name: String, value: Expr, line: Int)
    case indexAssign(obj: Expr, idx: Expr, value: Expr, line: Int)
    case exprStmt(expr: Expr, line: Int)
}

// ============ VALUES ============

enum Val {
    case int(Int)
    case bool(Bool)
    case string(String)
    case list(ListRef)
    case fn(FuncRef)
    case nil_
}

final class ListRef {
    var elements: [Val]
    init(_ e: [Val] = []) { elements = e }
}

final class FuncRef {
    let params: [String]
    let body: [ASTStmt]
    let capturedScope: Scope?
    let builtinName: String
    let builtinArity: Int
    let builtinImpl: (([Val], Int) throws -> Val)?

    init(params: [String], body: [ASTStmt], scope: Scope) {
        self.params = params
        self.body = body
        self.capturedScope = scope
        self.builtinName = ""
        self.builtinArity = 0
        self.builtinImpl = nil
    }
    init(builtin name: String, arity: Int, impl: @escaping ([Val], Int) throws -> Val) {
        self.params = []
        self.body = []
        self.capturedScope = nil
        self.builtinName = name
        self.builtinArity = arity
        self.builtinImpl = impl
    }
}

// ============ SCOPE ============

final class Scope {
    var vars: [String: Val]
    let parent: Scope?
    init(parent: Scope?) { vars = [:]; self.parent = parent }

    func lookup(_ name: String) -> Val? {
        var s: Scope? = self
        while let sc = s {
            if let v = sc.vars[name] { return v }
            s = sc.parent
        }
        return nil
    }
    func assign(_ name: String, _ value: Val) -> Bool {
        var s: Scope? = self
        while let sc = s {
            if sc.vars[name] != nil { sc.vars[name] = value; return true }
            s = sc.parent
        }
        return false
    }
    func declare(_ name: String, _ value: Val) { vars[name] = value }
}

// ============ ERRORS & CONTROL FLOW ============

struct TernError: Error {
    let line: Int
    let message: String
}

enum Ctrl {
    case normal
    case breakLoop
    case continueLoop
    case returnVal(Val)
}

// ============ PARSER ============

final class Parser {
    let tokens: [Token]
    var pos = 0
    init(_ t: [Token]) { tokens = t }

    func peek() -> Token { tokens[pos] }
    func advance() -> Token { let t = tokens[pos]; pos += 1; return t }
    func expect(_ k: TK) { pos += 1 }

    func parseProgram() -> [ASTStmt] {
        var s: [ASTStmt] = []
        while peek().kind != .eof { s.append(parseStmt()) }
        return s
    }

    func parseStmt() -> ASTStmt {
        let t = peek()
        switch t.kind {
        case .kwLet:
            pos += 1
            let name = advance().strVal
            expect(.assign)
            let v = parseExpr()
            expect(.semicolon)
            return .letDecl(name: name, value: v, line: t.line)
        case .kwFn:
            pos += 1
            let name = advance().strVal
            expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnDecl(name: name, params: params, body: body, line: t.line)
        case .kwIf:
            return parseIfStmt()
        case .kwWhile:
            pos += 1
            let cond = parseExpr()
            let body = parseBlock()
            return .whileStmt(cond: cond, body: body, line: t.line)
        case .kwFor:
            pos += 1
            let vn = advance().strVal
            expect(.kwIn)
            let iter = parseExpr()
            let body = parseBlock()
            return .forStmt(varName: vn, iterable: iter, body: body, line: t.line)
        case .kwReturn:
            pos += 1
            if peek().kind == .semicolon { pos += 1; return .returnStmt(value: nil, line: t.line) }
            let v = parseExpr()
            expect(.semicolon)
            return .returnStmt(value: v, line: t.line)
        case .kwBreak:
            pos += 1; expect(.semicolon); return .breakStmt(t.line)
        case .kwContinue:
            pos += 1; expect(.semicolon); return .continueStmt(t.line)
        default:
            // assignment, index-assign, or expr stmt
            if t.kind == .ident && tokens[pos + 1].kind == .assign {
                let name = advance().strVal
                pos += 1 // skip =
                let v = parseExpr()
                expect(.semicolon)
                return .assign(name: name, value: v, line: t.line)
            }
            let expr = parseExpr()
            if peek().kind == .assign {
                pos += 1
                let v = parseExpr()
                expect(.semicolon)
                if case let .index(obj, idx, _) = expr {
                    return .indexAssign(obj: obj, idx: idx, value: v, line: t.line)
                }
                return .exprStmt(expr: expr, line: t.line)
            }
            expect(.semicolon)
            return .exprStmt(expr: expr, line: t.line)
        }
    }

    func parseIfStmt() -> ASTStmt {
        let t = advance()
        let cond = parseExpr()
        let then = parseBlock()
        var ep: ElsePart = .none
        if peek().kind == .kwElse {
            pos += 1
            if peek().kind == .kwIf { ep = .elseIf(parseIfStmt()) }
            else { ep = .elseBlock(parseBlock()) }
        }
        return .ifStmt(cond: cond, then: then, elsePart: ep, line: t.line)
    }

    func parseBlock() -> [ASTStmt] {
        expect(.lbrace)
        var s: [ASTStmt] = []
        while peek().kind != .rbrace { s.append(parseStmt()) }
        expect(.rbrace)
        return s
    }

    func parseParams() -> [String] {
        var p: [String] = []
        if peek().kind != .rparen {
            p.append(advance().strVal)
            while peek().kind == .comma { pos += 1; p.append(advance().strVal) }
        }
        return p
    }

    func parseExpr() -> Expr { parseOr() }

    func parseOr() -> Expr {
        var l = parseAnd()
        while peek().kind == .kwOr {
            let t = advance(); let r = parseAnd()
            l = .binop(op: "or", lhs: l, rhs: r, line: t.line)
        }
        return l
    }

    func parseAnd() -> Expr {
        var l = parseNot()
        while peek().kind == .kwAnd {
            let t = advance(); let r = parseNot()
            l = .binop(op: "and", lhs: l, rhs: r, line: t.line)
        }
        return l
    }

    func parseNot() -> Expr {
        if peek().kind == .kwNot {
            let t = advance(); let o = parseNot()
            return .unop(op: "not", operand: o, line: t.line)
        }
        return parseCmp()
    }

    func parseCmp() -> Expr {
        var l = parseAdd()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .eq: op = "=="
            case .neq: op = "!="
            case .lt: op = "<"
            case .le: op = "<="
            case .gt: op = ">"
            case .ge: op = ">="
            default: return l
            }
            pos += 1; let r = parseAdd()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseAdd() -> Expr {
        var l = parseMul()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .plus: op = "+"
            case .minus: op = "-"
            default: return l
            }
            pos += 1; let r = parseMul()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseMul() -> Expr {
        var l = parseUnary()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .star: op = "*"
            case .slash: op = "/"
            case .percent: op = "%"
            default: return l
            }
            pos += 1; let r = parseUnary()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseUnary() -> Expr {
        if peek().kind == .minus {
            let t = advance(); let o = parseUnary()
            return .unop(op: "neg", operand: o, line: t.line)
        }
        return parsePostfix()
    }

    func parsePostfix() -> Expr {
        var e = parsePrimary()
        while true {
            let t = peek()
            if t.kind == .lparen {
                pos += 1
                var args: [Expr] = []
                if peek().kind != .rparen {
                    args.append(parseExpr())
                    while peek().kind == .comma { pos += 1; args.append(parseExpr()) }
                }
                expect(.rparen)
                e = .call(callee: e, args: args, line: t.line)
            } else if t.kind == .lbracket {
                pos += 1
                let idx = parseExpr()
                expect(.rbracket)
                e = .index(obj: e, idx: idx, line: t.line)
            } else { break }
        }
        return e
    }

    func parsePrimary() -> Expr {
        let t = peek()
        switch t.kind {
        case .intLit: pos += 1; return .intLit(t.intVal, t.line)
        case .strLit: pos += 1; return .strLit(t.strVal, t.line)
        case .kwTrue: pos += 1; return .boolLit(true, t.line)
        case .kwFalse: pos += 1; return .boolLit(false, t.line)
        case .kwNil: pos += 1; return .nilLit(t.line)
        case .ident: pos += 1; return .ident(t.strVal, t.line)
        case .lparen:
            pos += 1; let e = parseExpr(); expect(.rparen); return e
        case .lbracket:
            pos += 1
            var elems: [Expr] = []
            if peek().kind != .rbracket {
                elems.append(parseExpr())
                while peek().kind == .comma { pos += 1; elems.append(parseExpr()) }
            }
            expect(.rbracket)
            return .listLit(elems, t.line)
        case .kwFn:
            pos += 1; expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnExpr(params: params, body: body, line: t.line)
        default:
            pos += 1; return .nilLit(t.line)
        }
    }
}

// ============ TYPE NAME ============

func typeName(_ v: Val) -> String {
    switch v {
    case .int: return "int"
    case .bool: return "bool"
    case .string: return "string"
    case .list: return "list"
    case .fn: return "function"
    case .nil_: return "nil"
    }
}

// ============ TRUTHINESS ============

func truthy(_ v: Val) -> Bool {
    switch v {
    case .int(let i): return i != 0
    case .bool(let b): return b
    case .string(let s): return !s.isEmpty
    case .list(let l): return !l.elements.isEmpty
    case .fn: return true
    case .nil_: return false
    }
}

// ============ DISPLAY ============

func displayVal(_ v: Val, inList: Bool, seen: inout Set<ObjectIdentifier>) -> String {
    switch v {
    case .int(let i): return String(i)
    case .bool(let b): return b ? "true" : "false"
    case .nil_: return "nil"
    case .fn: return "<fn>"
    case .string(let s):
        if inList { return quoteString(s) }
        return s
    case .list(let l):
        let oid = ObjectIdentifier(l)
        if seen.contains(oid) { return "[...]" }
        seen.insert(oid)
        var parts: [String] = []
        parts.reserveCapacity(l.elements.count)
        for e in l.elements {
            parts.append(displayVal(e, inList: true, seen: &seen))
        }
        seen.remove(oid)
        return "[" + parts.joined(separator: ", ") + "]"
    }
}

func quoteString(_ s: String) -> String {
    var r = "\""
    for ch in s.unicodeScalars {
        switch ch {
        case "\\": r += "\\\\"
        case "\"": r += "\\\""
        case "\n": r += "\\n"
        case "\t": r += "\\t"
        default: r.unicodeScalars.append(ch)
        }
    }
    r += "\""
    return r
}

// ============ VALUE EQUALITY ============

func valEqual(_ a: Val, _ b: Val) -> Bool {
    switch (a, b) {
    case (.int(let x), .int(let y)): return x == y
    case (.bool(let x), .bool(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.nil_, .nil_): return true
    case (.fn(let x), .fn(let y)): return x === y
    case (.list(let x), .list(let y)):
        if x === y { return true }
        if x.elements.count != y.elements.count { return false }
        for i in 0..<x.elements.count {
            if !valEqual(x.elements[i], y.elements[i]) { return false }
        }
        return true
    default: return false
    }
}

// ============ BUILTINS ============

func makeBuiltins() -> Scope {
    let s = Scope(parent: nil)

    s.declare("print", .fn(FuncRef(builtin: "print", arity: -1) { args, ln in
        var parts: [String] = []
        parts.reserveCapacity(args.count)
        for a in args {
            var seen = Set<ObjectIdentifier>()
            parts.append(displayVal(a, inList: false, seen: &seen))
        }
        print(parts.joined(separator: " "))
        return .nil_
    }))

    s.declare("str", .fn(FuncRef(builtin: "str", arity: 1) { args, ln in
        var seen = Set<ObjectIdentifier>()
        return .string(displayVal(args[0], inList: false, seen: &seen))
    }))

    s.declare("type", .fn(FuncRef(builtin: "type", arity: 1) { args, _ in
        .string(typeName(args[0]))
    }))

    s.declare("len", .fn(FuncRef(builtin: "len", arity: 1) { args, ln in
        switch args[0] {
        case .string(let s): return .int(s.utf8.count)
        case .list(let l): return .int(l.elements.count)
        default: throw TernError(line: ln, message: "bad argument to len")
        }
    }))

    s.declare("push", .fn(FuncRef(builtin: "push", arity: 2) { args, ln in
        switch args[0] {
        case .list(let l): l.elements.append(args[1]); return .nil_
        default: throw TernError(line: ln, message: "bad argument to push")
        }
    }))

    s.declare("pop", .fn(FuncRef(builtin: "pop", arity: 1) { args, ln in
        switch args[0] {
        case .list(let l):
            if l.elements.isEmpty { throw TernError(line: ln, message: "bad argument to pop") }
            return l.elements.removeLast()
        default: throw TernError(line: ln, message: "bad argument to pop")
        }
    }))

    s.declare("range", .fn(FuncRef(builtin: "range", arity: 2) { args, ln in
        guard case .int(let a) = args[0], case .int(let b) = args[1] else {
            throw TernError(line: ln, message: "bad argument to range")
        }
        if b <= a { return .list(ListRef()) }
        var elems: [Val] = []
        elems.reserveCapacity(b - a)
        var i = a
        while i < b { elems.append(.int(i)); i += 1 }
        return .list(ListRef(elems))
    }))

    s.declare("slice", .fn(FuncRef(builtin: "slice", arity: 3) { args, ln in
        guard case .int(let a) = args[1], case .int(let b) = args[2] else {
            throw TernError(line: ln, message: "bad argument to slice")
        }
        switch args[0] {
        case .string(let s):
            let chars = Array(s.unicodeScalars)
            if a < 0 || b > chars.count || a > b { throw TernError(line: ln, message: "bad argument to slice") }
            return .string(String(String.UnicodeScalarView(chars[a..<b])))
        case .list(let l):
            if a < 0 || b > l.elements.count || a > b { throw TernError(line: ln, message: "bad argument to slice") }
            return .list(ListRef(Array(l.elements[a..<b])))
        default:
            throw TernError(line: ln, message: "bad argument to slice")
        }
    }))

    return s
}

// ============ INTERPRETER ============

func evalExpr(_ e: Expr, _ scope: Scope) throws -> Val {
    switch e {
    case .intLit(let v, _): return .int(v)
    case .strLit(let s, _): return .string(s)
    case .boolLit(let b, _): return .bool(b)
    case .nilLit: return .nil_
    case .ident(let name, let ln):
        if let v = scope.lookup(name) { return v }
        throw TernError(line: ln, message: "undefined variable \(name)")

    case .binop(let op, let lhs, let rhs, let ln):
        if op == "and" {
            let lv = try evalExpr(lhs, scope)
            if !truthy(lv) { return lv }
            return try evalExpr(rhs, scope)
        }
        if op == "or" {
            let lv = try evalExpr(lhs, scope)
            if truthy(lv) { return lv }
            return try evalExpr(rhs, scope)
        }
        if op == "==" {
            let lv = try evalExpr(lhs, scope)
            let rv = try evalExpr(rhs, scope)
            return .bool(valEqual(lv, rv))
        }
        if op == "!=" {
            let lv = try evalExpr(lhs, scope)
            let rv = try evalExpr(rhs, scope)
            return .bool(!valEqual(lv, rv))
        }
        // arithmetic and comparison operators
        let lv = try evalExpr(lhs, scope)
        let rv = try evalExpr(rhs, scope)
        return try applyBinop(op, lv, rv, ln)

    case .unop(let op, let operand, let ln):
        if op == "not" {
            let v = try evalExpr(operand, scope)
            return .bool(!truthy(v))
        }
        // neg
        let v = try evalExpr(operand, scope)
        guard case .int(let i) = v else {
            throw TernError(line: ln, message: "cannot apply - to \(typeName(v))")
        }
        if i == Int.min { throw TernError(line: ln, message: "integer overflow") }
        return .int(-i)

    case .call(let callee, let argExprs, let ln):
        let fnVal = try evalExpr(callee, scope)
        var args: [Val] = []
        args.reserveCapacity(argExprs.count)
        for ae in argExprs { args.append(try evalExpr(ae, scope)) }
        guard case .fn(let f) = fnVal else {
            throw TernError(line: ln, message: "cannot call \(typeName(fnVal))")
        }
        if f.builtinImpl != nil {
            // builtin
            if f.builtinArity >= 0 && args.count != f.builtinArity {
                throw TernError(line: ln, message: "expected \(f.builtinArity) arguments, got \(args.count)")
            }
            return try f.builtinImpl!(args, ln)
        } else {
            // user function
            if args.count != f.params.count {
                throw TernError(line: ln, message: "expected \(f.params.count) arguments, got \(args.count)")
            }
            let callScope = Scope(parent: f.capturedScope!)
            for i in 0..<f.params.count {
                callScope.declare(f.params[i], args[i])
            }
            let result = try execBlock(f.body, callScope)
            if case .returnVal(let v) = result { return v }
            return .nil_
        }

    case .index(let obj, let idx, let ln):
        let ov = try evalExpr(obj, scope)
        let iv = try evalExpr(idx, scope)
        return try indexRead(ov, iv, ln)

    case .listLit(let elems, _):
        var vals: [Val] = []
        vals.reserveCapacity(elems.count)
        for el in elems { vals.append(try evalExpr(el, scope)) }
        return .list(ListRef(vals))

    case .fnExpr(let params, let body, _):
        return .fn(FuncRef(params: params, body: body, scope: scope))
    }
}

func indexRead(_ obj: Val, _ idx: Val, _ ln: Int) throws -> Val {
    switch obj {
    case .list(let l):
        guard case .int(let i) = idx else {
            throw TernError(line: ln, message: "cannot index list with \(typeName(idx))")
        }
        if i < 0 || i >= l.elements.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(l.elements.count)")
        }
        return l.elements[i]
    case .string(let s):
        guard case .int(let i) = idx else {
            throw TernError(line: ln, message: "cannot index string with \(typeName(idx))")
        }
        let chars = Array(s.unicodeScalars)
        if i < 0 || i >= chars.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(chars.count)")
        }
        return .string(String(String.UnicodeScalarView([chars[i]])))
    default:
        throw TernError(line: ln, message: "cannot index \(typeName(obj)) with \(typeName(idx))")
    }
}

func applyBinop(_ op: String, _ lv: Val, _ rv: Val, _ ln: Int) throws -> Val {
    switch op {
    case "+":
        if case .int(let a) = lv, case .int(let b) = rv {
            let (r, ov) = a.addingReportingOverflow(b)
            if ov { throw TernError(line: ln, message: "integer overflow") }
            return .int(r)
        }
        if case .string(let a) = lv, case .string(let b) = rv { return .string(a + b) }
        if case .list(let a) = lv, case .list(let b) = rv {
            var elems = a.elements
            elems.append(contentsOf: b.elements)
            return .list(ListRef(elems))
        }
        throw TernError(line: ln, message: "cannot apply + to \(typeName(lv)) and \(typeName(rv))")
    case "-":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply - to \(typeName(lv)) and \(typeName(rv))")
        }
        let (r, ov) = a.subtractingReportingOverflow(b)
        if ov { throw TernError(line: ln, message: "integer overflow") }
        return .int(r)
    case "*":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply * to \(typeName(lv)) and \(typeName(rv))")
        }
        let (r, ov) = a.multipliedReportingOverflow(by: b)
        if ov { throw TernError(line: ln, message: "integer overflow") }
        return .int(r)
    case "/":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply / to \(typeName(lv)) and \(typeName(rv))")
        }
        if b == 0 { throw TernError(line: ln, message: "division by zero") }
        if a == Int.min && b == -1 { throw TernError(line: ln, message: "integer overflow") }
        return .int(a / b)
    case "%":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply % to \(typeName(lv)) and \(typeName(rv))")
        }
        if b == 0 { throw TernError(line: ln, message: "division by zero") }
        if b == -1 { return .int(0) }
        return .int(a % b)
    case "<":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a < b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a < b) }
        throw TernError(line: ln, message: "cannot apply < to \(typeName(lv)) and \(typeName(rv))")
    case "<=":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a <= b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a <= b) }
        throw TernError(line: ln, message: "cannot apply <= to \(typeName(lv)) and \(typeName(rv))")
    case ">":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a > b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a > b) }
        throw TernError(line: ln, message: "cannot apply > to \(typeName(lv)) and \(typeName(rv))")
    case ">=":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a >= b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a >= b) }
        throw TernError(line: ln, message: "cannot apply >= to \(typeName(lv)) and \(typeName(rv))")
    default:
        throw TernError(line: ln, message: "unknown operator \(op)")
    }
}

func execBlock(_ stmts: [ASTStmt], _ scope: Scope) throws -> Ctrl {
    for s in stmts {
        let c = try execStmt(s, scope)
        switch c {
        case .normal: continue
        default: return c
        }
    }
    return .normal
}

func execStmt(_ s: ASTStmt, _ scope: Scope) throws -> Ctrl {
    switch s {
    case .letDecl(let name, let value, _):
        let v = try evalExpr(value, scope)
        scope.declare(name, v)
        return .normal

    case .fnDecl(let name, let params, let body, _):
        let f = FuncRef(params: params, body: body, scope: scope)
        scope.declare(name, .fn(f))
        return .normal

    case .ifStmt(let cond, let then, let elsePart, _):
        let cv = try evalExpr(cond, scope)
        if truthy(cv) {
            let inner = Scope(parent: scope)
            return try execBlock(then, inner)
        } else {
            switch elsePart {
            case .none: return .normal
            case .elseIf(let stmt): return try execStmt(stmt, scope)
            case .elseBlock(let stmts):
                let inner = Scope(parent: scope)
                return try execBlock(stmts, inner)
            }
        }

    case .whileStmt(let cond, let body, _):
        while true {
            let cv = try evalExpr(cond, scope)
            if !truthy(cv) { break }
            let inner = Scope(parent: scope)
            let c = try execBlock(body, inner)
            switch c {
            case .breakLoop: break
            case .continueLoop: continue
            case .returnVal(let v): return .returnVal(v)
            case .normal: continue
            }
        }
        return .normal

    case .forStmt(let varName, let iterable, let body, let ln):
        let iterVal = try evalExpr(iterable, scope)
        guard case .list(let lst) = iterVal else {
            throw TernError(line: ln, message: "cannot iterate \(typeName(iterVal))")
        }
        var i = 0
        while i < lst.elements.count {
            let inner = Scope(parent: scope)
            inner.declare(varName, lst.elements[i])
            let c = try execBlock(body, inner)
            switch c {
            case .breakLoop: break
            case .continueLoop: i += 1; continue
            case .returnVal(let v): return .returnVal(v)
            case .normal: i += 1; continue
            }
            break // breakLoop exits while
        }
        return .normal

    case .returnStmt(let value, _):
        if let v = value { return .returnVal(try evalExpr(v, scope)) }
        return .returnVal(.nil_)

    case .breakStmt: return .breakLoop
    case .continueStmt: return .continueLoop

    case .assign(let name, let value, let ln):
        let v = try evalExpr(value, scope)
        if !scope.assign(name, v) {
            throw TernError(line: ln, message: "undefined variable \(name)")
        }
        return .normal

    case .indexAssign(let obj, let idx, let value, let ln):
        let ov = try evalExpr(obj, scope)
        let iv = try evalExpr(idx, scope)
        let vv = try evalExpr(value, scope)
        guard case .list(let l) = ov else {
            throw TernError(line: ln, message: "cannot assign into \(typeName(ov))")
        }
        guard case .int(let i) = iv else {
            throw TernError(line: ln, message: "cannot index list with \(typeName(iv))")
        }
        if i < 0 || i >= l.elements.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(l.elements.count)")
        }
        l.elements[i] = vv
        return .normal

    case .exprStmt(let expr, _):
        _ = try evalExpr(expr, scope)
        return .normal
    }
}

// ============ MAIN ============

func main() {
    let args = CommandLine.arguments
    guard args.count >= 2 else { exit(0) }
    let dir = args[1]
    let path = dir + "/program.tern"
    guard let data = FileManager.default.contents(atPath: path) else { exit(0) }
    let src = [UInt8](data)

    let tokens = tokenize(src)
    let parser = Parser(tokens)
    let program = parser.parseProgram()

    let builtins = makeBuiltins()
    let globalScope = Scope(parent: builtins)

    do {
        _ = try execBlock(program, globalScope)
    } catch let e as TernError {
        print("error at line \(e.line): \(e.message)")
    } catch {
        // shouldn't happen
    }
    fflush(stdout)
    exit(0)
}

