func applyHunks(_ content: [[UInt8]], hunks: [Hunk]) -> ([[UInt8]], [String], Bool) {
    var current = content
    var delta = 0
    var reports: [String] = []
    var allApplied = true

    for (idx, hunk) in hunks.enumerated() {
        let hunkNum = idx + 1

        if hunk.malformed {
            reports.append("  hunk \(hunkNum): malformed")
            allApplied = false
            continue
        }

        let P = hunk.a + delta

        if hunk.b == 0 {
            if P < 0 || P > current.count {
                reports.append("  hunk \(hunkNum): rejected")
                allApplied = false
                continue
            }
            var newContent = Array(current[0..<P])
            newContent.append(contentsOf: hunk.newLines)
            if P < current.count {
                newContent.append(contentsOf: current[P...])
            }
            current = newContent
            delta += hunk.d
            reports.append("  hunk \(hunkNum): applied at \(P) (offset 0)")
        } else {
            let b = hunk.b
            let n = current.count

            if n < b {
                reports.append("  hunk \(hunkNum): rejected")
                allApplied = false
                continue
            }

            let minP = 1
            let maxP = n - b + 1

            var found = false
            var foundP = 0

            let maxDist = max(P - minP, maxP - P)

            for k in 0...max(maxDist, 0) {
                if k == 0 {
                    if P >= minP && P <= maxP {
                        var matches = true
                        for j in 0..<b {
                            if current[P - 1 + j] != hunk.oldLines[j] {
                                matches = false
                                break
                            }
                        }
                        if matches {
                            found = true
                            foundP = P
                            break
                        }
                    }
                } else {
                    let p1 = P - k
                    if p1 >= minP && p1 <= maxP {
                        var matches = true
                        for j in 0..<b {
                            if current[p1 - 1 + j] != hunk.oldLines[j] {
                                matches = false
                                break
                            }
                        }
                        if matches {
                            found = true
                            foundP = p1
                            break
                        }
                    }
                    let p2 = P + k
                    if p2 >= minP && p2 <= maxP {
                        var matches = true
                        for j in 0..<b {
                            if current[p2 - 1 + j] != hunk.oldLines[j] {
                                matches = false
                                break
                            }
                        }
                        if matches {
                            found = true
                            foundP = p2
                            break
                        }
                    }
                }
            }

            if found {
                var newContent: [[UInt8]] = []
                if foundP - 1 > 0 {
                    newContent.append(contentsOf: current[0..<foundP - 1])
                }
                newContent.append(contentsOf: hunk.newLines)
                if foundP + b - 1 < current.count {
                    newContent.append(contentsOf: current[foundP + b - 1...])
                }
                current = newContent
                let offset = foundP - P
                delta += hunk.d - hunk.b
                let offsetStr = offset > 0 ? "+\(offset)" : "\(offset)"
                reports.append("  hunk \(hunkNum): applied at \(foundP) (offset \(offsetStr))")
            } else {
                reports.append("  hunk \(hunkNum): rejected")
                allApplied = false
            }
        }
    }

    return (current, reports, allApplied)
}

