import Foundation

func splitIntoLines(_ data: [UInt8]) -> [[UInt8]] {
    if data.isEmpty { return [] }
    var lines: [[UInt8]] = []
    var start = 0
    for i in 0..<data.count {
        if data[i] == 0x0A {
            lines.append(Array(data[start...i]))
            start = i + 1
        }
    }
    if start < data.count {
        lines.append(Array(data[start..<data.count]))
    }
    return lines
}

func joinLines(_ lines: [[UInt8]]) -> [UInt8] {
    var result: [UInt8] = []
    for line in lines {
        result.append(contentsOf: line)
    }
    return result
}

func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc ^= UInt32(byte)
        for _ in 0..<8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
    }
    return crc ^ 0xFFFFFFFF
}

