func startsWithBytes(_ line: [UInt8], _ prefix: [UInt8]) -> Bool {
    if line.count < prefix.count { return false }
    for i in 0..<prefix.count {
        if line[i] != prefix[i] { return false }
    }
    return true
}

func startsWithString(_ line: [UInt8], _ prefix: String) -> Bool {
    return startsWithBytes(line, Array(prefix.utf8))
}

func lineToString(_ line: [UInt8]) -> String {
    if line.last == 0x0A {
        return String(bytes: line[0..<line.count - 1], encoding: .utf8) ?? ""
    }
    return String(bytes: line, encoding: .utf8) ?? ""
}

