function crc32(data: Buffer): number {
    const table: number[] = new Array(256);
    for (let i = 0; i < 256; i++) {
        let c = i;
        for (let j = 0; j < 8; j++) {
            if (c & 1) c = 0xEDB88320 ^ (c >>> 1);
            else c = c >>> 1;
        }
        table[i] = c;
    }
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc = table[(crc ^ data[i]) & 0xFF] ^ (crc >>> 8);
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

function splitLines(content: string): string[] {
    if (content === '') return [];
    const parts = content.split('\n');
    const lines: string[] = [];
    for (let i = 0; i < parts.length; i++) {
        if (i < parts.length - 1) {
            lines.push(parts[i] + '\n');
        } else {
            if (parts[i] !== '') {
                lines.push(parts[i]);
            }
        }
    }
    return lines;
}

interface Hunk {
    a: number;
    b: number;
    c: number;
    d: number;
    oldLines: string[];
    newLines: string[];
    malformed: boolean;
}

interface Section {
    filePath: string;
    kind: 'create' | 'delete' | 'modify';
    hunks: Hunk[];
}

function parseDiff(diffContent: string): Section[] {
    const lines = diffContent.split('\n');
    if (lines.length > 0 && lines[lines.length - 1] === '') {
        lines.pop();
    }

    const sections: Section[] = [];
    let i = 0;

    while (i < lines.length) {
        const line = lines[i];
        const diffMatch = line.match(/^diff --git a\/(.+) b\/(.+)$/);
        if (!diffMatch) {
            i++;
            continue;
        }

        const filePath = diffMatch[1];
        i++;

        let kind: 'create' | 'delete' | 'modify' = 'modify';

        while (i < lines.length) {
            const l = lines[i];
            if (l.startsWith('new file mode')) {
                kind = 'create';
                i++;
            } else if (l.startsWith('deleted file mode')) {
                kind = 'delete';
                i++;
            } else if (l.startsWith('index ')) {
                i++;
            } else if (
                l.startsWith('--- ') ||
                l.startsWith('+++ ') ||
                l.startsWith('@@ ') ||
                l.startsWith('diff --git ')
            ) {
                break;
            } else {
                i++;
            }
        }

        if (i < lines.length && lines[i].startsWith('--- ')) i++;
        if (i < lines.length && lines[i].startsWith('+++ ')) i++;

        const hunks: Hunk[] = [];

        while (i < lines.length) {
            const l = lines[i];
            if (l.startsWith('diff --git ')) break;
            if (!l.startsWith('@@ ')) {
                i++;
                continue;
            }

            const hunkMatch = l.match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
            if (!hunkMatch) {
                i++;
                continue;
            }

            const a = parseInt(hunkMatch[1]);
            const b = hunkMatch[2] !== undefined ? parseInt(hunkMatch[2]) : 1;
            const c = parseInt(hunkMatch[3]);
            const d = hunkMatch[4] !== undefined ? parseInt(hunkMatch[4]) : 1;

            i++;

            const oldLines: string[] = [];
            const newLines: string[] = [];
            let lastMarker = '';

            while (i < lines.length) {
                const bl = lines[i];
                if (bl.startsWith('diff --git ') || bl.startsWith('@@ ')) break;

                if (bl.startsWith('\\')) {
                    if (lastMarker === '-' || lastMarker === ' ') {
                        if (oldLines.length > 0) {
                            oldLines[oldLines.length - 1] = oldLines[oldLines.length - 1].replace(/\n$/, '');
                        }
                    }
                    if (lastMarker === '+' || lastMarker === ' ') {
                        if (newLines.length > 0) {
                            newLines[newLines.length - 1] = newLines[newLines.length - 1].replace(/\n$/, '');
                        }
                    }
                    i++;
                    continue;
                }

                if (bl.length === 0) {
                    i++;
                    continue;
                }

                const marker = bl[0];
                const content = bl.slice(1);

                if (marker === ' ') {
                    oldLines.push(content + '\n');
                    newLines.push(content + '\n');
                    lastMarker = ' ';
                } else if (marker === '-') {
                    oldLines.push(content + '\n');
                    lastMarker = '-';
                } else if (marker === '+') {
                    newLines.push(content + '\n');
                    lastMarker = '+';
                }

                i++;
            }

            const malformed = oldLines.length !== b || newLines.length !== d;
            hunks.push({ a, b, c, d, oldLines, newLines, malformed });
        }

        sections.push({ filePath, kind, hunks });
    }

    return sections;
}

function main(): void {
    const dir = process.argv[2];
    const diffPath = path.join(dir, 'changes.diff');
    const treePath = path.join(dir, 'tree');

    const diffContent = fs.readFileSync(diffPath, 'latin1');
    const sections = parseDiff(diffContent);

    sections.sort((a, b) =>
        Buffer.from(a.filePath, 'latin1').compare(Buffer.from(b.filePath, 'latin1'))
    );

    const output: string[] = [];

    for (const section of sections) {
        const fullPath = path.join(treePath, section.filePath);

        if (section.kind === 'create') {
            if (fs.existsSync(fullPath)) {
                output.push(`${section.filePath}: ${section.kind}`);
                output.push(`  error: already exists`);
                continue;
            }
        } else {
            if (!fs.existsSync(fullPath)) {
                output.push(`${section.filePath}: ${section.kind}`);
                output.push(`  error: not found`);
                continue;
            }
        }

        let lines: string[];
        if (section.kind === 'create') {
            lines = [];
        } else {
            const content = fs.readFileSync(fullPath, 'latin1');
            lines = splitLines(content);
        }

        let delta = 0;
        const results: { status: string; position?: number; offset?: number }[] = [];

        for (const hunk of section.hunks) {
            if (hunk.malformed) {
                results.push({ status: 'malformed' });
                continue;
            }

            const P = hunk.a + delta;

            if (hunk.b === 0) {
                if (P >= 0 && P <= lines.length) {
                    lines.splice(P, 0, ...hunk.newLines);
                    results.push({ status: 'applied', position: P, offset: 0 });
                    delta += hunk.d - hunk.b;
                } else {
                    results.push({ status: 'rejected' });
                }
                continue;
            }

            let found = false;
            for (let offset = 0; ; offset++) {
                const low = P - offset;
                const high = P + offset;

                if (low < 1 && high + hunk.b - 1 > lines.length) break;

                if (low >= 1 && low + hunk.b - 1 <= lines.length) {
                    let match = true;
                    for (let j = 0; j < hunk.b; j++) {
                        if (lines[low - 1 + j] !== hunk.oldLines[j]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        lines.splice(low - 1, hunk.b, ...hunk.newLines);
                        results.push({ status: 'applied', position: low, offset: low - P });
                        delta += hunk.d - hunk.b;
                        found = true;
                        break;
                    }
                }

                if (offset > 0 && high >= 1 && high + hunk.b - 1 <= lines.length) {
                    let match = true;
                    for (let j = 0; j < hunk.b; j++) {
                        if (lines[high - 1 + j] !== hunk.oldLines[j]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        lines.splice(high - 1, hunk.b, ...hunk.newLines);
                        results.push({ status: 'applied', position: high, offset: high - P });
                        delta += hunk.d - hunk.b;
                        found = true;
                        break;
                    }
                }
            }

            if (!found) {
                results.push({ status: 'rejected' });
            }
        }

        output.push(`${section.filePath}: ${section.kind}`);

        for (let idx = 0; idx < results.length; idx++) {
            const r = results[idx];
            const n = idx + 1;
            if (r.status === 'applied') {
                const k = r.offset!;
                const kStr = k > 0 ? `+${k}` : `${k}`;
                output.push(`  hunk ${n}: applied at ${r.position} (offset ${kStr})`);
            } else if (r.status === 'rejected') {
                output.push(`  hunk ${n}: rejected`);
            } else {
                output.push(`  hunk ${n}: malformed`);
            }
        }

        if (section.kind === 'delete') {
            const allApplied = results.every(r => r.status === 'applied');
            if (allApplied && lines.length === 0) {
                output.push(`  result: deleted`);
            } else {
                const content = Buffer.from(lines.join(''), 'latin1');
                const crc = crc32(content);
                output.push(`  result: ${lines.length} lines, crc32 ${crc.toString(16).padStart(8, '0')}`);
            }
        } else {
            const content = Buffer.from(lines.join(''), 'latin1');
            const crc = crc32(content);
            output.push(`  result: ${lines.length} lines, crc32 ${crc.toString(16).padStart(8, '0')}`);
        }
    }

    if (output.length > 0) {
        process.stdout.write(output.join('\n') + '\n');
    }
}

main();

#!/usr/bin/env python3
import sys
import os
import re
import zlib
import base64


def main():
    directory = sys.argv[1]
    files = sorted([f for f in os.listdir(directory) if f.endswith('.eml')])

    first = True
    for fname in files:
        if not first:
            print()
        first = False
        print(f"== {fname}")
        path = os.path.join(directory, fname)
        with open(path, 'rb') as f:
            data = f.read()
        process_message(data)


def detect_line_break(data):
    if b'\r\n' in data:
        return b'\r\n'
    return b'\n'


def split_lines(data, lb):
    """Split data into lines. Returns list of (content_bytes, lb_bytes_or_None)."""
    lines = []
    pos = 0
    while pos < len(data):
        crlf = data.find(b'\r\n', pos)
        lf = data.find(b'\n', pos)
        cr = data.find(b'\r', pos)

        candidates = []
        if crlf != -1:
            candidates.append((crlf, 2))
        if lf != -1 and (crlf == -1 or lf < crlf):
            candidates.append((lf, 1))
        if cr != -1 and (crlf == -1 or cr < crlf):
            candidates.append((cr, 1))

        if not candidates:
            lines.append((data[pos:], None))
            break

        candidates.sort()
        bp, bl = candidates[0]
        lines.append((data[pos:bp], data[bp:bp + bl]))
        pos = bp + bl

    return lines


def parse_headers(header_bytes, lb):
    """Parse header bytes into dict of lowercase name -> value."""
    lines = split_lines(header_bytes, lb)

    unfolded = []
    for content, _ in lines:
        if content and (content[0:1] == b' ' or content[0:1] == b'\t'):
            if unfolded:
                unfolded[-1] += content
            else:
                unfolded.append(content)
        else:
            unfolded.append(content)

    headers = {}
    for line in unfolded:
        colon_pos = line.find(b':')
        if colon_pos == -1:
            continue
        name = line[:colon_pos].decode('ascii').strip().lower()
        value = line[colon_pos + 1:].strip(b' \t').decode('ascii')
        headers[name] = value

    return headers


def parse_params(value, start):
    """Parse parameters from value starting at position start."""
    params = {}
    j = start
    while j < len(value):
        while j < len(value) and value[j] != ';':
            j += 1
        if j >= len(value):
            break
        j += 1
        while j < len(value) and value[j] in ' \t':
            j += 1
        k = j
        while k < len(value) and value[k] not in '= \t;':
            k += 1
        attr = value[j:k].lower()
        while k < len(value) and value[k] in ' \t':
            k += 1
        if k < len(value) and value[k] == '=':
            k += 1
            while k < len(value) and value[k] in ' \t':
                k += 1
            if k < len(value) and value[k] == '"':
                k += 1
                val_chars = []
                while k < len(value) and value[k] != '"':
                    if value[k] == '\\':
                        k += 1
                        if k < len(value):
                            val_chars.append(value[k])
                    else:
                        val_chars.append(value[k])
                    k += 1
                if k < len(value):
                    k += 1
                param_val = ''.join(val_chars)
            else:
                val_start = k
                while k < len(value) and value[k] not in '; \t':
                    k += 1
                param_val = value[val_start:k]
            if attr:
                params[attr] = param_val
            j = k
        else:
            j = k
    return params


def parse_content_type(value):
    """Parse Content-Type. Returns (type, subtype, params)."""
    i = 0
    while i < len(value) and value[i] in ' \t':
        i += 1
    j = i
    while j < len(value) and value[j] not in '/ \t;':
        j += 1
    type_name = value[i:j].lower()
    while j < len(value) and value[j] in ' \t':
        j += 1
    if j < len(value) and value[j] == '/':
        j += 1
        while j < len(value) and value[j] in ' \t':
            j += 1
        k = j
        while k < len(value) and value[k] not in '; \t':
            k += 1
        subtype = value[j:k].lower()
        j = k
    else:
        subtype = ''
    params = parse_params(value, j)
    return type_name, subtype, params


def parse_content_disposition(value):
    """Parse Content-Disposition. Returns (disp_type, params)."""
    i = 0
    while i < len(value) and value[i] in ' \t':
        i += 1
    j = i
    while j < len(value) and value[j] not in '; \t':
        j += 1
    disp_type = value[i:j].lower()
    params = parse_params(value, j)
    return disp_type, params


def decode_base64_bytes(data):
    """Decode base64 from bytes, ignoring non-alphabet chars, stopping at =."""
    alphabet = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    filtered = []
    for b in data:
        if b == 61:  # '='
            break
        if b in alphabet:
            filtered.append(b)
    s = bytes(filtered)
    padding = (4 - len(s) % 4) % 4
    s += b'=' * padding
    return base64.b64decode(s)


def decode_base64_str(s):
    """Decode base64 from string (RFC 2047 B encoding)."""
    alphabet = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    filtered = []
    for c in s:
        if c == '=':
            break
        if c in alphabet:
            filtered.append(c)
    b_str = ''.join(filtered)
    padding = (4 - len(b_str) % 4) % 4
    b_str += '=' * padding
    return base64.b64decode(b_str)


def decode_q_encoding(s):
    """Decode Q encoding (RFC 2047)."""
    result = bytearray()
    i = 0
    while i < len(s):
        if s[i] == '_':
            result.append(0x20)
            i += 1
        elif s[i] == '=' and i + 2 < len(s):
            hex_str = s[i + 1:i + 3]
            if all(c in '0123456789abcdefABCDEF' for c in hex_str):
                result.append(int(hex_str, 16))
                i += 3
            else:
                result.append(ord('='))
                i += 1
        else:
            result.append(ord(s[i]))
            i += 1
    return bytes(result)


def decode_quoted_printable(data, lb):
    """Decode quoted-printable bytes."""
    lines = split_lines(data, lb)

    result = bytearray()
    i = 0
    while i < len(lines):
        content, line_lb = lines[i]
        stripped = content.rstrip(b' \t')

        if stripped.endswith(b'=') and i + 1 < len(lines):
            result.extend(stripped[:-1])
            i += 1
        else:
            result.extend(stripped)
            if line_lb is not None:
                result.extend(line_lb)
            i += 1

    final = bytearray()
    i = 0
    while i < len(result):
        if result[i:i + 1] == b'=' and i + 2 < len(result):
            hex_str = result[i + 1:i + 3]
            if all(c in b'0123456789abcdefABCDEF' for c in hex_str):
                final.append(int(hex_str, 16))
                i += 3
            else:
                final.append(ord('='))
                i += 1
        else:
            final.append(result[i])
            i += 1

    return bytes(final)


def decode_cte(data, encoding, lb):
    """Decode Content-Transfer-Encoding."""
    enc = encoding.lower()
    if enc == 'base64':
        return decode_base64_bytes(data)
    elif enc == 'quoted-printable':
        return decode_quoted_printable(data, lb)
    else:
        return data


def decode_charset(data, charset):
    """Decode bytes using charset."""
    cs = charset.lower()
    if cs == 'us-ascii':
        return data.decode('ascii', errors='replace')
    elif cs == 'utf-8':
        return data.decode('utf-8', errors='replace')
    elif cs == 'iso-8859-1':
        return data.decode('iso-8859-1')
    elif cs == 'windows-1252':
        cp1252_map = {
            0x80: 0x20AC, 0x81: 0x0081, 0x82: 0x201A, 0x83: 0x0192,
            0x84: 0x201E, 0x85: 0x2026, 0x86: 0x2020, 0x87: 0x2021,
            0x88: 0x02C6, 0x89: 0x2030, 0x8A: 0x0160, 0x8B: 0x2039,
            0x8C: 0x0152, 0x8D: 0x008D, 0x8E: 0x017D, 0x8F: 0x008F,
            0x90: 0x0090, 0x91: 0x2018, 0x92: 0x2019, 0x93: 0x201C,
            0x94: 0x201D, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014,
            0x98: 0x02DC, 0x99: 0x2122, 0x9A: 0x0161, 0x9B: 0x203A,
            0x9C: 0x0153, 0x9D: 0x009D, 0x9E: 0x017E, 0x9F: 0x0178,
        }
        result = []
        for b in data:
            if 0x80 <= b <= 0x9F:
                result.append(chr(cp1252_map.get(b, b)))
            else:
                result.append(chr(b))
        return ''.join(result)
    else:
        return data.decode('ascii', errors='replace')


def decode_encoded_words(value):
    """Decode RFC 2047 encoded words in a string."""
    pattern = re.compile(r'=\?([^ \t?]+)\?([BbQq])\?([^ \t?]*)\?=')
    matches = list(pattern.finditer(value))
    if not matches:
        return value

    result = []
    i = 0
    last_end = 0

    while i < len(matches):
        m = matches[i]
        charset = m.group(1).split('*')[0].lower()

        run = [m]
        j = i + 1
        while j < len(matches):
            between = value[matches[j - 1].end():matches[j].start()]
            if all(c in ' \t' for c in between):
                cs2 = matches[j].group(1).split('*')[0].lower()
                if cs2 == charset:
                    run.append(matches[j])
                    j += 1
                else:
                    break
            else:
                break

        result.append(value[last_end:run[0].start()])

        all_bytes = bytearray()
        for rm in run:
            enc = rm.group(2).upper()
            enc_text = rm.group(3)
            if enc == 'B':
                all_bytes.extend(decode_base64_str(enc_text))
            elif enc == 'Q':
                all_bytes.extend(decode_q_encoding(enc_text))

        decoded = decode_charset(bytes(all_bytes), charset)
        result.append(decoded)

        last_end = run[-1].end()
        i = j

    result.append(value[last_end:])
    return ''.join(result)


def percent_decode(s):
    """Percent-decode a string to bytes."""
    result = bytearray()
    i = 0
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s):
            hex_str = s[i + 1:i + 3]
            if all(c in '0123456789abcdefABCDEF' for c in hex_str):
                result.append(int(hex_str, 16))
                i += 3
            else:
                result.append(ord(s[i]))
                i += 1
        else:
            result.append(ord(s[i]))
            i += 1
    return bytes(result)


def parse_rfc2231(params, attr_name):
    """Parse RFC 2231 parameter from params dict. Returns decoded string or None."""
    key_star = attr_name + '*'

    has_single = key_star in params

    segments = {}
    i = 0
    while True:
        key_enc = f"{attr_name}*{i}*"
        key_lit = f"{attr_name}*{i}"
        if key_enc in params:
            segments[i] = (params[key_enc], True)
            i += 1
        elif key_lit in params:
            segments[i] = (params[key_lit], False)
            i += 1
        else:
            break

    if not has_single and not segments:
        return None

    raw = bytearray()
    charset = None

    if segments:
        for idx in sorted(segments.keys()):
            val, is_encoded = segments[idx]
            if is_encoded:
                if idx == 0:
                    q1 = val.find("'")
                    if q1 != -1:
                        charset = val[:q1]
                        rest = val[q1 + 1:]
                        q2 = rest.find("'")
                        if q2 != -1:
                            percent_data = rest[q2 + 1:]
                        else:
                            percent_data = rest
                    else:
                        percent_data = val
                    raw.extend(percent_decode(percent_data))
                else:
                    raw.extend(percent_decode(val))
            else:
                raw.extend(val.encode('latin-1'))
    else:
        val = params[key_star]
        q1 = val.find("'")
        if q1 != -1:
            charset = val[:q1]
            rest = val[q1 + 1:]
            q2 = rest.find("'")
            if q2 != -1:
                percent_data = rest[q2 + 1:]
            else:
                percent_data = rest
        else:
            percent_data = val
        raw.extend(percent_decode(percent_data))

    cs = charset.lower() if charset else 'us-ascii'
    return decode_charset(bytes(raw), cs)


def get_filename(headers):
    """Get decoded file name from headers."""
    if 'content-disposition' in headers:
        _, disp_params = parse_content_disposition(headers['content-disposition'])
        result = parse_rfc2231(disp_params, 'filename')
        if result is not None:
            return result
        if 'filename' in disp_params:
            return decode_encoded_words(disp_params['filename'])

    if 'content-type' in headers:
        _, _, ct_params = parse_content_type(headers['content-type'])
        result = parse_rfc2231(ct_params, 'name')
        if result is not None:
            return result
        if 'name' in ct_params:
            return decode_encoded_words(ct_params['name'])

    return None


def quoted_string(s):
    """Format string as quoted string."""
    result = ['"']
    for ch in s:
        cp = ord(ch)
        if ch == '\\':
            result.append('\\\\')
        elif ch == '"':
            result.append('\\"')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\t':
            result.append('\\t')
        elif cp < 0x20 or (0x7F <= cp <= 0x9F):
            result.append(f'\\u{cp:04x}')
        else:
            result.append(ch)
    result.append('"')
    return ''.join(result)


class Entity:
    def __init__(self):
        self.headers = {}
        self.body = b''
        self.parts = []
        self.ctype = 'text'
        self.subtype = 'plain'
        self.charset = 'us-ascii'
        self.cte = '7bit'
        self.disposition = None
        self.filename = None
        self.is_multipart = False


def parse_entity(data, lb):
    """Parse an entity from raw bytes."""
    entity = Entity()

    sep = lb + lb
    sep_pos = data.find(sep)

    if sep_pos == -1:
        if data.startswith(lb):
            entity.body = data[len(lb):]
        else:
            entity.headers = parse_headers(data, lb)
    else:
        header_bytes = data[:sep_pos]
        body_start = sep_pos + len(lb)
        if header_bytes:
            entity.headers = parse_headers(header_bytes, lb)
        entity.body = data[body_start:]

    # Parse Content-Type
    if 'content-type' in entity.headers:
        ctype, subtype, params = parse_content_type(entity.headers['content-type'])
        entity.ctype = ctype
        entity.subtype = subtype
        if ctype == 'multipart':
            entity.is_multipart = True
            entity.charset = ''
        else:
            if 'charset' in params:
                entity.charset = params['charset'].lower()
            else:
                entity.charset = 'us-ascii'
    else:
        entity.ctype = 'text'
        entity.subtype = 'plain'
        entity.charset = 'us-ascii'

    # Content-Transfer-Encoding
    if 'content-transfer-encoding' in entity.headers:
        entity.cte = entity.headers['content-transfer-encoding'].strip().lower()
    else:
        entity.cte = '7bit'

    # Content-Disposition
    if 'content-disposition' in entity.headers:
        disp_type, _ = parse_content_disposition(entity.headers['content-disposition'])
        entity.disposition = disp_type

    # File name
    entity.filename = get_filename(entity.headers)

    # Parse multipart
    if entity.is_multipart:
        _, _, params = parse_content_type(entity.headers['content-type'])
        boundary = params.get('boundary', '')
        entity.parts = parse_multipart(entity.body, boundary, lb)

    return entity


def parse_multipart(body, boundary, lb):
    """Parse multipart body into parts."""
    parts = []
    delimiter = b'--' + boundary.encode('ascii')

    lines = split_lines(body, lb)

    delim_indices = []
    for i, (content, _) in enumerate(lines):
        if content.startswith(delimiter):
            rest = content[len(delimiter):]
            if all(c in b' \t' for c in rest):
                delim_indices.append(i)

    for k in range(len(delim_indices) - 1):
        start_idx = delim_indices[k]
        end_idx = delim_indices[k + 1]

        content_lines = lines[start_idx + 1:end_idx]

        if content_lines:
            part_body = lb.join(content_bytes for content_bytes, _ in content_lines)
        else:
            part_body = b''

        parts.append(parse_entity(part_body, lb))

    return parts


def print_entity(entity, indent, lb):
    """Print entity tree."""
    prefix = '  ' * indent

    if entity.is_multipart:
        print(f"{prefix}multipart/{entity.subtype} parts={len(entity.parts)}")
        for part in entity.parts:
            print_entity(part, indent + 1, lb)
    elif entity.ctype == 'text' and entity.disposition != 'attachment':
        decoded_body = decode_cte(entity.body, entity.cte, lb)
        text = decode_charset(decoded_body, entity.charset)
        text = text.replace('\r\n', '\n').replace('\r', '\n')
        num_chars = len(text)
        print(f"{prefix}text/{entity.subtype} charset={entity.charset} cte={entity.cte} chars={num_chars}")
        print(f"{prefix}  {quoted_string(text)}")
    else:
        decoded_body = decode_cte(entity.body, entity.cte, lb)
        size = len(decoded_body)
        crc = zlib.crc32(decoded_body) & 0xFFFFFFFF
        disp = entity.disposition if entity.disposition else '-'
        name = quoted_string(entity.filename) if entity.filename else '-'
        print(f"{prefix}{entity.ctype}/{entity.subtype} cte={entity.cte} disposition={disp} name={name} size={size} crc32={crc:08x}")


def process_message(data):
    """Process a complete message."""
    lb = detect_line_break(data)
    entity = parse_entity(data, lb)

    from_val = entity.headers.get('from', None)
    subject_val = entity.headers.get('subject', None)

    if from_val:
        print(f"From: {quoted_string(decode_encoded_words(from_val))}")
    else:
        print("From: -")

    if subject_val:
        print(f"Subject: {quoted_string(decode_encoded_words(subject_val))}")
    else:
        print("Subject: -")

    print_entity(entity, 0, lb)


main()

import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.CRC32;

public class Main {
    static String lb;

    static class Entity {
        Map<String, String> headers = new LinkedHashMap<>();
        byte[] body = new byte[0];
        List<Entity> parts;
    }

    static class ParsedCT {
        String type = "", subtype = "";
        Map<String, String> params = new LinkedHashMap<>();
    }

    static class ParsedCD {
        String dispType = "";
        Map<String, String> params = new LinkedHashMap<>();
    }

    public static void main(String[] args) throws Exception {
        File dir = new File(args[0]);
        File[] files = dir.listFiles((d, n) -> n.endsWith(".eml"));
        if (files == null) files = new File[0];
        Arrays.sort(files, (a, b) -> {
            byte[] an = a.getName().getBytes(StandardCharsets.UTF_8);
            byte[] bn = b.getName().getBytes(StandardCharsets.UTF_8);
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++) {
                int c = (an[i] & 0xFF) - (bn[i] & 0xFF);
                if (c != 0) return c;
            }
            return Integer.compare(an.length, bn.length);
        });
        boolean first = true;
        for (File f : files) {
            if (!first) System.out.println();
            first = false;
            processFile(f);
        }
    }

    static void processFile(File f) throws Exception {
        byte[] data = Files.readAllBytes(f.toPath());
        lb = detectLineBreak(data);
        Entity msg = parseEntity(data);
        System.out.println("== " + f.getName());
        String from = msg.headers.get("from");
        String subj = msg.headers.get("subject");
        System.out.println("From: " + (from != null ? quote(decodeRfc2047(from)) : "-"));
        System.out.println("Subject: " + (subj != null ? quote(decodeRfc2047(subj)) : "-"));
        printEntity(msg, 0);
    }

    static String detectLineBreak(byte[] data) {
        for (int i = 0; i < data.length; i++) {
            if (data[i] == '\n') {
                if (i > 0 && data[i - 1] == '\r') return "\r\n";
                return "\n";
            }
        }
        return "\n";
    }

    static boolean isLB(byte[] data, int pos) {
        for (int i = 0; i < lb.length(); i++) {
            if (pos + i >= data.length || data[pos + i] != (byte) lb.charAt(i)) return false;
        }
        return true;
    }

    static int findSep(byte[] data) {
        int lbLen = lb.length();
        if (data.length >= lbLen && isLB(data, 0)) return 0;
        for (int i = 0; i + 2 * lbLen <= data.length; i++) {
            if (isLB(data, i) && isLB(data, i + lbLen)) return i + lbLen;
        }
        return -1;
    }

    static Entity parseEntity(byte[] data) {
        Entity e = new Entity();
        int sep = findSep(data);
        byte[] hdr;
        if (sep >= 0) {
            hdr = Arrays.copyOfRange(data, 0, sep);
            e.body = Arrays.copyOfRange(data, sep + lb.length(), data.length);
        } else {
            hdr = new byte[0];
            e.body = data;
        }
        e.headers = parseHeaders(hdr);
        String ct = e.headers.get("content-type");
        if (ct != null) {
            ParsedCT p = parseCT(ct);
            if (p.type.equals("multipart")) {
                String bnd = p.params.get("boundary");
                if (bnd != null) {
                    e.parts = parseMultipart(e.body, bnd);
                }
            }
        }
        return e;
    }

    static Map<String, String> parseHeaders(byte[] hdr) {
        Map<String, String> map = new LinkedHashMap<>();
        String text = new String(hdr, StandardCharsets.US_ASCII);
        text = text.replace(lb + " ", " ").replace(lb + "\t", "\t");
        String[] lines = text.split(java.util.regex.Pattern.quote(lb), -1);
        for (String line : lines) {
            if (line.isEmpty()) continue;
            int colon = line.indexOf(':');
            if (colon < 0) continue;
            String name = line.substring(0, colon).trim().toLowerCase();
            String val = line.substring(colon + 1);
            int s = 0, en = val.length();
            while (s < en && (val.charAt(s) == ' ' || val.charAt(s) == '\t')) s++;
            while (en > s && (val.charAt(en - 1) == ' ' || val.charAt(en - 1) == '\t')) en--;
            map.put(name, val.substring(s, en));
        }
        return map;
    }

    static ParsedCT parseCT(String v) {
        ParsedCT p = new ParsedCT();
        int pos = 0;
        pos = skipWS(v, pos);
        int ts = pos;
        while (pos < v.length() && v.charAt(pos) != '/' && v.charAt(pos) != ' ' && v.charAt(pos) != '\t' && v.charAt(pos) != ';') pos++;
        p.type = v.substring(ts, pos).toLowerCase();
        pos = skipWS(v, pos);
        if (pos < v.length() && v.charAt(pos) == '/') pos++;
        pos = skipWS(v, pos);
        int ss = pos;
        while (pos < v.length() && v.charAt(pos) != ' ' && v.charAt(pos) != '\t' && v.charAt(pos) != ';') pos++;
        p.subtype = v.substring(ss, pos).toLowerCase();
        parseParams(v, pos, p.params);
        return p;
    }

    static ParsedCD parseCD(String v) {
        ParsedCD p = new ParsedCD();
        int pos = 0;
        pos = skipWS(v, pos);
        int ts = pos;
        while (pos < v.length() && v.charAt(pos) != ' ' && v.charAt(pos) != '\t' && v.charAt(pos) != ';') pos++;
        p.dispType = v.substring(ts, pos).toLowerCase();
        parseParams(v, pos, p.params);
        return p;
    }

    static int skipWS(String s, int pos) {
        while (pos < s.length() && (s.charAt(pos) == ' ' || s.charAt(pos) == '\t')) pos++;
        return pos;
    }

    static void parseParams(String v, int pos, Map<String, String> params) {
        while (pos < v.length()) {
            pos = skipWS(v, pos);
            if (pos >= v.length() || v.charAt(pos) != ';') break;
            pos++;
            pos = skipWS(v, pos);
            int as = pos;
            while (pos < v.length() && v.charAt(pos) != '=' && v.charAt(pos) != ' ' && v.charAt(pos) != '\t' && v.charAt(pos) != ';') pos++;
            String attr = v.substring(as, pos).toLowerCase();
            pos = skipWS(v, pos);
            if (pos < v.length() && v.charAt(pos) == '=') pos++;
            pos = skipWS(v, pos);
            String val;
            if (pos < v.length() && v.charAt(pos) == '"') {
                pos++;
                StringBuilder sb = new StringBuilder();
                while (pos < v.length() && v.charAt(pos) != '"') {
                    if (v.charAt(pos) == '\\' && pos + 1 < v.length()) {
                        sb.append(v.charAt(pos + 1));
                        pos += 2;
                    } else {
                        sb.append(v.charAt(pos));
                        pos++;
                    }
                }
                if (pos < v.length()) pos++;
                val = sb.toString();
            } else {
                int vs = pos;
                while (pos < v.length() && v.charAt(pos) != ';' && v.charAt(pos) != ' ' && v.charAt(pos) != '\t') pos++;
                val = v.substring(vs, pos);
            }
            if (!attr.isEmpty()) params.put(attr, val);
        }
    }

    static List<Entity> parseMultipart(byte[] body, String boundary) {
        List<Entity> parts = new ArrayList<>();
        int lbLen = lb.length();
        String delim = "--" + boundary;
        String closeD = "--" + boundary + "--";
        List<int[]> dLines = new ArrayList<>();
        int closeStart = -1;
        int pos = 0;
        while (pos <= body.length) {
            int le = pos;
            while (le < body.length && !isLB(body, le)) le++;
            int lineLen = le - pos;
            if (isDelim(body, pos, lineLen, closeD)) {
                closeStart = pos;
                break;
            }
            if (isDelim(body, pos, lineLen, delim)) {
                int e = le + lbLen;
                if (e > body.length) e = body.length;
                dLines.add(new int[]{pos, e});
            }
            if (le >= body.length) break;
            pos = le + lbLen;
        }
        for (int i = 0; i < dLines.size(); i++) {
            int ps = dLines.get(i)[1];
            int pe;
            if (i + 1 < dLines.size()) pe = dLines.get(i + 1)[0];
            else if (closeStart >= 0) pe = closeStart;
            else break;
            if (pe >= ps + lbLen && isLB(body, pe - lbLen)) pe -= lbLen;
            if (pe < ps) pe = ps;
            parts.add(parseEntity(Arrays.copyOfRange(body, ps, pe)));
        }
        return parts;
    }

    static boolean isDelim(byte[] data, int pos, int lineLen, String d) {
        if (lineLen < d.length()) return false;
        for (int i = 0; i < d.length(); i++)
            if (data[pos + i] != (byte) d.charAt(i)) return false;
        for (int i = d.length(); i < lineLen; i++) {
            byte b = data[pos + i];
            if (b != ' ' && b != '\t') return false;
        }
        return true;
    }

    static void printEntity(Entity e, int indent) {
        String pre = " ".repeat(indent);
        String ct = e.headers.get("content-type");
        String cte = e.headers.get("content-transfer-encoding");
        if (cte == null) cte = "7bit";
        cte = cte.toLowerCase();

        if (e.parts != null) {
            ParsedCT p = parseCT(ct != null ? ct : "multipart/mixed");
            System.out.println(pre + "multipart/" + p.subtype + " parts=" + e.parts.size());
            for (Entity part : e.parts) printEntity(part, indent + 2);
        } else {
            ParsedCT p = parseCT(ct != null ? ct : "text/plain");
            String type = p.type, sub = p.subtype;
            String dispType = "-";
            String cd = e.headers.get("content-disposition");
            if (cd != null) {
                ParsedCD cdp = parseCD(cd);
                if (cdp.dispType != null && !cdp.dispType.isEmpty()) dispType = cdp.dispType;
            }

            if (type.equals("text") && !dispType.equals("attachment")) {
                String charset = p.params.getOrDefault("charset", "us-ascii").toLowerCase();
                byte[] decoded = transferDecode(e.body, cte);
                String text = decodeCharset(decoded, charset);
                text = text.replace("\r\n", "\n").replace("\r", "\n");
                int chars = text.codePointCount(0, text.length());
                System.out.println(pre + "text/" + sub + " charset=" + charset + " cte=" + cte + " chars=" + chars);
                System.out.println(" ".repeat(indent + 2) + quote(text));
            } else {
                byte[] decoded = transferDecode(e.body, cte);
                int size = decoded.length;
                CRC32 crc = new CRC32();
                crc.update(decoded);
                String crcStr = String.format("%08x", crc.getValue());
                String name = extractFileName(e);
                String nameStr = name != null ? quote(name) : "-";
                System.out.println(pre + type + "/" + sub + " cte=" + cte + " disposition=" + dispType + " name=" + nameStr + " size=" + size + " crc32=" + crcStr);
            }
        }
    }

    static byte[] transferDecode(byte[] data, String enc) {
        switch (enc) {
            case "base64": return decodeB64(data);
            case "quoted-printable": return decodeQP(data);
            default: return data;
        }
    }

    static byte[] decodeB64(byte[] data) {
        byte[] tmp = new byte[data.length];
        int n = 0;
        for (byte b : data) {
            char c = (char) (b & 0xFF);
            if (c == '=') break;
            if (b64val(c) >= 0) tmp[n++] = b;
        }
        int full = n / 4, rem = n % 4;
        int outLen = full * 3 + (rem >= 2 ? rem - 1 : 0);
        byte[] out = new byte[outLen];
        int oi = 0;
        for (int i = 0; i < full; i++) {
            int v = (b64val((char)(tmp[i*4]&0xFF)) << 18) | (b64val((char)(tmp[i*4+1]&0xFF)) << 12)
                  | (b64val((char)(tmp[i*4+2]&0xFF)) << 6) | b64val((char)(tmp[i*4+3]&0xFF));
            out[oi++] = (byte)(v >> 16);
            out[oi++] = (byte)(v >> 8);
            out[oi++] = (byte) v;
        }
        if (rem >= 2) {
            int v = (b64val((char)(tmp[full*4]&0xFF)) << 18) | (b64val((char)(tmp[full*4+1]&0xFF)) << 12);
            out[oi++] = (byte)(v >> 16);
            if (rem == 3) {
                v |= b64val((char)(tmp[full*4+2]&0xFF)) << 6;
                out[oi++] = (byte)(v >> 8);
            }
        }
        return out;
    }

    static int b64val(char c) {
        if (c >= 'A' && c <= 'Z') return c - 'A';
        if (c >= 'a' && c <= 'z') return c - 'a' + 26;
        if (c >= '0' && c <= '9') return c - '0' + 52;
        if (c == '+') return 62;
        if (c == '/') return 63;
        return -1;
    }

    static byte[] decodeQP(byte[] data) {
        int lbLen = lb.length();
        List<byte[]> lines = new ArrayList<>();
        List<Boolean> softBreaks = new ArrayList<>();
        int pos = 0;
        while (pos <= data.length) {
            int le = pos;
            while (le < data.length && !isLB(data, le)) le++;
            int lineLen = le - pos;
            int trimmedLen = lineLen;
            while (trimmedLen > 0 && (data[pos + trimmedLen - 1] == ' ' || data[pos + trimmedLen - 1] == '\t')) trimmedLen--;
            byte[] lineBytes = Arrays.copyOfRange(data, pos, pos + trimmedLen);
            boolean soft = trimmedLen > 0 && lineBytes[trimmedLen - 1] == '=';
            if (soft) lineBytes = Arrays.copyOfRange(data, pos, pos + trimmedLen - 1);
            lines.add(lineBytes);
            softBreaks.add(soft);
            if (le >= data.length) break;
            pos = le + lbLen;
        }
        ByteArrayOutputStream joined = new ByteArrayOutputStream();
        for (int i = 0; i < lines.size(); i++) {
            joined.write(lines.get(i), 0, lines.get(i).length);
            if (i < lines.size() - 1 && !softBreaks.get(i)) {
                joined.write(lb.getBytes(StandardCharsets.ISO_8859_1), 0, lbLen);
            }
        }
        byte[] jb = joined.toByteArray();
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        int i = 0;
        while (i < jb.length) {
            if (jb[i] == '=' && i + 2 < jb.length && isHexB(jb[i+1]) && isHexB(jb[i+2])) {
                out.write(Integer.parseInt(new String(jb, i+1, 2), 16));
                i += 3;
            } else {
                out.write(jb[i]);
                i++;
            }
        }
        return out.toByteArray();
    }

    static boolean isHexB(byte b) {
        char c = (char)(b & 0xFF);
        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
    }

    static String decodeCharset(byte[] data, String cs) {
        String lower = cs.toLowerCase();
        switch (lower) {
            case "utf-8": return new String(data, StandardCharsets.UTF_8);
            case "iso-8859-1": return new String(data, StandardCharsets.ISO_8859_1);
            case "windows-1252": return decodeCP1252(data);
            default: return new String(data, StandardCharsets.ISO_8859_1);
        }
    }

    static final int[] CP1252_MAP = {
        0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
        0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
        0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
        0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178
    };

    static String decodeCP1252(byte[] data) {
        StringBuilder sb = new StringBuilder();
        for (byte b : data) {
            int v = b & 0xFF;
            if (v >= 0x80 && v <= 0x9F) sb.append((char) CP1252_MAP[v - 0x80]);
            else sb.append((char) v);
        }
        return sb.toString();
    }

    static String decodeRfc2047(String value) {
        List<int[]> spans = new ArrayList<>();
        List<String> csets = new ArrayList<>();
        List<byte[]> bList = new ArrayList<>();
        int i = 0;
        while (i < value.length()) {
            int ws = findEWStart(value, i);
            if (ws < 0) break;
            int p = ws + 2;
            int q1 = value.indexOf('?', p);
            if (q1 < 0) { i = ws + 1; continue; }
            String charset = value.substring(p, q1);
            if (charset.isEmpty()) { i = ws + 1; continue; }
            p = q1 + 1;
            if (p >= value.length()) { i = ws + 1; continue; }
            char enc = value.charAt(p);
            if (enc != 'B' && enc != 'b' && enc != 'Q' && enc != 'q') { i = ws + 1; continue; }
            p++;
            int q2 = value.indexOf('?', p);
            if (q2 < 0) { i = ws + 1; continue; }
            if (q2 + 1 >= value.length() || value.charAt(q2 + 1) != '=') { i = ws + 1; continue; }
            String encText = value.substring(p, q2);
            int we = q2 + 2;
            byte[] decoded = decodeEW(enc, encText);
            spans.add(new int[]{ws, we});
            csets.add(normCharset(charset));
            bList.add(decoded);
            i = we;
        }
        if (spans.isEmpty()) return value;
        List<List<Integer>> groups = new ArrayList<>();
        int gi = 0;
        while (gi < spans.size()) {
            List<Integer> g = new ArrayList<>();
            g.add(gi);
            int gj = gi + 1;
            while (gj < spans.size()) {
                String between = value.substring(spans.get(gj-1)[1], spans.get(gj)[0]);
                if (between.matches("[ \t]*") && csets.get(gj-1).equals(csets.get(gj))) {
                    g.add(gj); gj++;
                } else break;
            }
            groups.add(g);
            gi = gj;
        }
        StringBuilder result = new StringBuilder();
        int prev = 0;
        for (List<Integer> g : groups) {
            int gs = spans.get(g.get(0))[0];
            int ge = spans.get(g.get(g.size()-1))[1];
            result.append(value, prev, gs);
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            for (int idx : g) baos.write(bList.get(idx), 0, bList.get(idx).length);
            result.append(decodeCharset(baos.toByteArray(), csets.get(g.get(0))));
            prev = ge;
        }
        result.append(value, prev, value.length());
        return result.toString();
    }

    static int findEWStart(String v, int from) {
        for (int i = from; i + 1 < v.length(); i++) {
            if (v.charAt(i) == '=' && v.charAt(i+1) == '?') {
                if (isValidEW(v, i)) return i;
            }
        }
        return -1;
    }

    static boolean isValidEW(String v, int start) {
        int p = start + 2;
        int q1 = v.indexOf('?', p);
        if (q1 < 0) return false;
        if (q1 == p) return false;
        p = q1 + 1;
        if (p >= v.length()) return false;
        char enc = v.charAt(p);
        if (enc != 'B' && enc != 'b' && enc != 'Q' && enc != 'q') return false;
        p++;
        int q2 = v.indexOf('?', p);
        if (q2 < 0) return false;
        if (q2 + 1 >= v.length() || v.charAt(q2 + 1) != '=') return false;
        return true;
    }

    static String normCharset(String cs) {
        int star = cs.indexOf('*');
        if (star >= 0) cs = cs.substring(0, star);
        return cs.toLowerCase();
    }

    static byte[] decodeEW(char enc, String text) {
        if (enc == 'B' || enc == 'b') {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < text.length(); i++) {
                char c = text.charAt(i);
                if (c == '=') break;
                if (b64val(c) >= 0) sb.append(c);
            }
            String s = sb.toString();
            int full = s.length() / 4, rem = s.length() % 4;
            int outLen = full * 3 + (rem >= 2 ? rem - 1 : 0);
            byte[] out = new byte[outLen];
            int oi = 0;
            for (int i = 0; i < full; i++) {
                int v = (b64val(s.charAt(i*4)) << 18) | (b64val(s.charAt(i*4+1)) << 12)
                      | (b64val(s.charAt(i*4+2)) << 6) | b64val(s.charAt(i*4+3));
                out[oi++] = (byte)(v >> 16);
                out[oi++] = (byte)(v >> 8);
                out[oi++] = (byte) v;
            }
            if (rem >= 2) {
                int v = (b64val(s.charAt(full*4)) << 18) | (b64val(s.charAt(full*4+1)) << 12);
                out[oi++] = (byte)(v >> 16);
                if (rem == 3) {
                    v |= b64val(s.charAt(full*4+2)) << 6;
                    out[oi++] = (byte)(v >> 8);
                }
            }
            return out;
        } else {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            for (int i = 0; i < text.length(); i++) {
                char c = text.charAt(i);
                if (c == '_') {
                    baos.write(0x20);
                } else if (c == '=' && i + 2 < text.length() && isHexChar(text.charAt(i+1)) && isHexChar(text.charAt(i+2))) {
                    baos.write(Integer.parseInt(text.substring(i+1, i+3), 16));
                    i += 2;
                } else {
                    baos.write(c & 0xFF);
                }
            }
            return baos.toByteArray();
        }
    }

    static boolean isHexChar(char c) {
        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
    }

    static String extractFileName(Entity e) {
        ParsedCT cti = null;
        ParsedCD cdi = null;
        String ct = e.headers.get("content-type");
        String cd = e.headers.get("content-disposition");
        if (ct != null) cti = parseCT(ct);
        if (cd != null) cdi = parseCD(cd);
        if (cdi != null && hasRfc2231(cdi.params, "filename")) return doRfc2231(cdi.params, "filename");
        if (cdi != null && cdi.params.containsKey("filename")) return decodeRfc2047(cdi.params.get("filename"));
        if (cti != null && hasRfc2231(cti.params, "name")) return doRfc2231(cti.params, "name");
        if (cti != null && cti.params.containsKey("name")) return decodeRfc2047(cti.params.get("name"));
        return null;
    }

    static boolean hasRfc2231(Map<String, String> params, String attr) {
        String a = attr.toLowerCase();
        if (params.containsKey(a + "*")) return true;
        for (String key : params.keySet()) {
            if (key.startsWith(a + "*") && key.length() > a.length() + 1) {
                String rest = key.substring(a.length() + 1);
                boolean pe = rest.endsWith("*");
                String numStr = pe ? rest.substring(0, rest.length() - 1) : rest;
                if (!numStr.isEmpty() && numStr.chars().allMatch(Character::isDigit)) return true;
            }
        }
        return false;
    }

    static String doRfc2231(Map<String, String> params, String attr) {
        String a = attr.toLowerCase();
        String singleKey = a + "*";
        if (params.containsKey(singleKey)) {
            return decodeRfc2231Single(params.get(singleKey));
        }
        List<Integer> indices = new ArrayList<>();
        Set<Integer> peSet = new HashSet<>();
        for (String key : params.keySet()) {
            if (key.startsWith(a + "*") && key.length() > a.length() + 1) {
                String rest = key.substring(a.length() + 1);
                boolean pe = rest.endsWith("*");
                String numStr = pe ? rest.substring(0, rest.length() - 1) : rest;
                if (!numStr.isEmpty() && numStr.chars().allMatch(Character::isDigit)) {
                    int num = Integer.parseInt(numStr);
                    indices.add(num);
                    if (pe) peSet.add(num);
                }
            }
        }
        if (indices.isEmpty()) return null;
        Collections.sort(indices);
        String charset = "us-ascii";
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        for (int idx : indices) {
            boolean pe = peSet.contains(idx);
            String key = a + "*" + idx + (pe ? "*" : "");
            String val = params.get(key);
            if (val == null) continue;
            if (pe) {
                if (idx == 0) {
                    int q1 = val.indexOf('\'');
                    int q2 = val.indexOf('\'', q1 + 1);
                    if (q1 >= 0 && q2 >= 0) {
                        charset = val.substring(0, q1);
                        val = val.substring(q2 + 1);
                    }
                }
                byte[] pb = percentDecode(val);
                baos.write(pb, 0, pb.length);
            } else {
                byte[] lb2 = val.getBytes(StandardCharsets.ISO_8859_1);
                baos.write(lb2, 0, lb2.length);
            }
        }
        return decodeCharset(baos.toByteArray(), charset);
    }

    static String decodeRfc2231Single(String val) {
        int q1 = val.indexOf('\'');
        int q2 = val.indexOf('\'', q1 + 1);
        String charset = "us-ascii";
        if (q1 >= 0 && q2 >= 0) {
            charset = val.substring(0, q1);
            val = val.substring(q2 + 1);
        }
        return decodeCharset(percentDecode(val), charset);
    }

    static byte[] percentDecode(String s) {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        int i = 0;
        while (i < s.length()) {
            if (s.charAt(i) == '%' && i + 2 < s.length() && isHexChar(s.charAt(i+1)) && isHexChar(s.charAt(i+2))) {
                baos.write(Integer.parseInt(s.substring(i+1, i+3), 16));
                i += 3;
            } else {
                baos.write(s.charAt(i) & 0xFF);
                i++;
            }
        }
        return baos.toByteArray();
    }

    static String quote(String text) {
        StringBuilder sb = new StringBuilder("\"");
        int i = 0;
        while (i < text.length()) {
            int cp = text.codePointAt(i);
            if (cp == '\\') sb.append("\\\\");
            else if (cp == '"') sb.append("\\\"");
            else if (cp == '\n') sb.append("\\n");
            else if (cp == '\t') sb.append("\\t");
            else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) sb.append(String.format("\\u%04x", cp));
            else sb.appendCodePoint(cp);
            i += Character.charCount(cp);
        }
        sb.append("\"");
        return sb.toString();
    }
}

import * as fs from 'fs';
import * as path from 'path';

// CRC-32 table
const CRC_TABLE: number[] = [];
for (let n = 0; n < 256; n++) {
  let c = n;
  for (let k = 0; k < 8; k++) {
    c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  }
  CRC_TABLE[n] = c;
}

function crc32(buf: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) {
    crc = CRC_TABLE[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

// Windows-1252 mapping for bytes 0x80-0x9F
const CP1252: number[] = [
  0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
  0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
  0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
  0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178,
];

let currentLineEnd: string = '\n';
let currentLineEndBuf: Buffer = Buffer.from('\n');

interface Entity {
  headers: Map<string, string>;
  bodyRaw: Buffer;
  ct: { type: string; subtype: string; params: Map<string, string> };
  cd: { type: string; params: Map<string, string> } | null;
  cte: string;
  parts: Entity[] | null;
}

function main() {
  const dir = process.argv[2];
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.eml')).sort();

  let first = true;
  for (const file of files) {
    if (!first) console.log('');
    first = false;
    const buf = fs.readFileSync(path.join(dir, file));
    currentLineEnd = buf.includes(0x0D) ? '\r\n' : '\n';
    currentLineEndBuf = Buffer.from(currentLineEnd);

    const entity = parseEntity(buf);

    console.log(`== ${file}`);

    const fromVal = entity.headers.get('from');
    const subjVal = entity.headers.get('subject');

    console.log(`From: ${fromVal !== undefined ? quotedString(decodeEncodedWords(fromVal)) : '-'}`);
    console.log(`Subject: ${subjVal !== undefined ? quotedString(decodeEncodedWords(subjVal)) : '-'}`);

    printEntity(entity, 0);
  }
}

function parseEntity(buf: Buffer): Entity {
  const bodyStart = findBodyStart(buf);
  const headerSectionLen = Math.max(0, bodyStart - currentLineEndBuf.length);
  const headerSection = buf.slice(0, headerSectionLen);
  const bodyRaw = buf.slice(bodyStart);

  const headers = parseHeaders(headerSection);

  const ctValue = headers.get('content-type');
  let ct: { type: string; subtype: string; params: Map<string, string> };
  if (ctValue !== undefined) {
    ct = parseContentType(ctValue);
  } else {
    ct = { type: 'text', subtype: 'plain', params: new Map() };
  }

  const cdValue = headers.get('content-disposition');
  let cd: { type: string; params: Map<string, string> } | null = null;
  if (cdValue !== undefined) {
    cd = parseContentDisposition(cdValue);
  }

  const cteValue = headers.get('content-transfer-encoding');
  let cte = '7bit';
  if (cteValue !== undefined) {
    cte = cteValue.trim().toLowerCase();
  }

  let parts: Entity[] | null = null;
  if (ct.type === 'multipart') {
    const boundary = ct.params.get('boundary');
    if (boundary !== undefined) {
      parts = parseMultipart(bodyRaw, boundary);
    }
  }

  return { headers, bodyRaw, ct, cd, cte, parts };
}

function findBodyStart(buf: Buffer): number {
  const le = currentLineEndBuf;
  if (buf.length >= le.length && buf.slice(0, le.length).equals(le)) {
    return le.length;
  }
  const sep = Buffer.concat([le, le]);
  const idx = buf.indexOf(sep);
  if (idx >= 0) return idx + sep.length;
  return buf.length;
}

function parseHeaders(headerSection: Buffer): Map<string, string> {
  const lines = splitBufferByLine(headerSection, currentLineEndBuf);
  const logicalLines: string[] = [];
  for (const line of lines) {
    const str = line.toString('ascii');
    if (str.length === 0) continue;
    const c0 = str.charCodeAt(0);
    if (c0 === 0x20 || c0 === 0x09) {
      if (logicalLines.length > 0) {
        logicalLines[logicalLines.length - 1] += str;
      }
    } else {
      logicalLines.push(str);
    }
  }

  const headers = new Map<string, string>();
  for (const line of logicalLines) {
    const ci = line.indexOf(':');
    if (ci < 0) continue;
    const name = line.slice(0, ci).toLowerCase();
    let value = line.slice(ci + 1);
    value = value.replace(/^[ \t]+/, '').replace(/[ \t]+$/, '');
    headers.set(name, value);
  }
  return headers;
}

function splitBufferByLine(buf: Buffer, le: Buffer): Buffer[] {
  const lines: Buffer[] = [];
  let start = 0;
  while (start < buf.length) {
    const idx = buf.indexOf(le, start);
    if (idx === -1) {
      lines.push(buf.slice(start));
      break;
    }
    lines.push(buf.slice(start, idx));
    start = idx + le.length;
  }
  return lines;
}

function parseContentType(value: string): { type: string; subtype: string; params: Map<string, string> } {
  const semiIdx = value.indexOf(';');
  let typeStr: string;
  let paramStr: string;
  if (semiIdx >= 0) {
    typeStr = value.slice(0, semiIdx);
    paramStr = value.slice(semiIdx);
  } else {
    typeStr = value;
    paramStr = '';
  }

  const slashIdx = typeStr.indexOf('/');
  let type: string, subtype: string;
  if (slashIdx >= 0) {
    type = typeStr.slice(0, slashIdx).replace(/[ \t]+$/, '').toLowerCase();
    subtype = typeStr.slice(slashIdx + 1).replace(/^[ \t]+/, '').toLowerCase();
  } else {
    type = typeStr.replace(/[ \t]+$/, '').toLowerCase();
    subtype = '';
  }

  return { type, subtype, params: parseParams(paramStr) };
}

function parseContentDisposition(value: string): { type: string; params: Map<string, string> } {
  const semiIdx = value.indexOf(';');
  let dispType: string;
  let paramStr: string;
  if (semiIdx >= 0) {
    dispType = value.slice(0, semiIdx).replace(/[ \t]+$/, '').toLowerCase();
    paramStr = value.slice(semiIdx);
  } else {
    dispType = value.replace(/[ \t]+$/, '').toLowerCase();
    paramStr = '';
  }
  return { type: dispType, params: parseParams(paramStr) };
}

function parseParams(input: string): Map<string, string> {
  const params = new Map<string, string>();
  let pos = 0;
  while (pos < input.length) {
    while (pos < input.length && (input[pos] === ' ' || input[pos] === '\t')) pos++;
    if (pos >= input.length) break;
    if (input[pos] !== ';') break;
    pos++;
    while (pos < input.length && (input[pos] === ' ' || input[pos] === '\t')) pos++;
    if (pos >= input.length) break;

    const attrStart = pos;
    while (pos < input.length && input[pos] !== '=' && input[pos] !== ' ' && input[pos] !== '\t' && input[pos] !== ';') pos++;
    const attr = input.slice(attrStart, pos).toLowerCase();

    while (pos < input.length && (input[pos] === ' ' || input[pos] === '\t')) pos++;
    if (pos >= input.length || input[pos] !== '=') break;
    pos++;
    while (pos < input.length && (input[pos] === ' ' || input[pos] === '\t')) pos++;

    let value: string;
    if (pos < input.length && input[pos] === '"') {
      pos++;
      let v = '';
      while (pos < input.length && input[pos] !== '"') {
        if (input[pos] === '\\' && pos + 1 < input.length) {
          v += input[pos + 1];
          pos += 2;
        } else {
          v += input[pos];
          pos++;
        }
      }
      if (pos < input.length) pos++;
      value = v;
    } else {
      const vStart = pos;
      while (pos < input.length && input[pos] !== ';' && input[pos] !== ' ' && input[pos] !== '\t') pos++;
      value = input.slice(vStart, pos);
    }

    if (attr.length > 0) {
      params.set(attr, value);
    }
  }
  return params;
}

function parseMultipart(body: Buffer, boundary: string): Entity[] {
  const lines = splitBufferByLine(body, currentLineEndBuf);
  const delimStr = '--' + boundary;
  const closeStr = '--' + boundary + '--';
  const boundaryIndices: number[] = [];

  for (let i = 0; i < lines.length; i++) {
    const lineStr = lines[i].toString('ascii');
    if (lineStr.length >= closeStr.length && lineStr.startsWith(closeStr)) {
      const rest = lineStr.slice(closeStr.length);
      if (isOnlySpacesTabs(rest)) {
        boundaryIndices.push(i);
        break;
      }
    }
    if (lineStr.length >= delimStr.length && lineStr.startsWith(delimStr)) {
      const rest = lineStr.slice(delimStr.length);
      if (isOnlySpacesTabs(rest)) {
        boundaryIndices.push(i);
      }
    }
  }

  const parts: Entity[] = [];
  for (let i = 0; i < boundaryIndices.length - 1; i++) {
    const startLine = boundaryIndices[i] + 1;
    const endLine = boundaryIndices[i + 1];
    const partLines = lines.slice(startLine, endLine);
    let partBuf: Buffer;
    if (partLines.length === 0) {
      partBuf = Buffer.alloc(0);
    } else {
      const bufs: Buffer[] = [];
      for (let j = 0; j < partLines.length; j++) {
        if (j > 0) bufs.push(currentLineEndBuf);
        bufs.push(partLines[j]);
      }
      partBuf = Buffer.concat(bufs);
    }
    parts.push(parseEntity(partBuf));
  }
  return parts;
}

function isOnlySpacesTabs(s: string): boolean {
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c !== 0x20 && c !== 0x09) return false;
  }
  return true;
}

// --- Transfer decoding ---

function decodeBody(entity: Entity): Buffer {
  if (entity.cte === 'base64') return decodeBase64Body(entity.bodyRaw);
  if (entity.cte === 'quoted-printable') return decodeQpBody(entity.bodyRaw);
  return entity.bodyRaw;
}

function decodeBase64Body(buf: Buffer): Buffer {
  const chars: number[] = [];
  for (let i = 0; i < buf.length; i++) {
    const b = buf[i];
    if (b === 0x3D) break;
    if ((b >= 0x41 && b <= 0x5A) || (b >= 0x61 && b <= 0x7A) ||
        (b >= 0x30 && b <= 0x39) || b === 0x2B || b === 0x2F) {
      chars.push(b);
    }
  }
  return Buffer.from(Buffer.from(chars).toString('ascii'), 'base64');
}

function decodeQpBody(buf: Buffer): Buffer {
  const lines = splitBufferByLine(buf, currentLineEndBuf);
  const stripped: Buffer[] = lines.map(line => {
    let end = line.length;
    while (end > 0 && (line[end - 1] === 0x20 || line[end - 1] === 0x09)) end--;
    return line.slice(0, end);
  });

  const joined: number[] = [];
  for (let i = 0; i < stripped.length; i++) {
    const line = stripped[i];
    if (line.length > 0 && line[line.length - 1] === 0x3D) {
      for (let j = 0; j < line.length - 1; j++) joined.push(line[j]);
    } else {
      for (let j = 0; j < line.length; j++) joined.push(line[j]);
      if (i < stripped.length - 1) {
        for (let j = 0; j < currentLineEndBuf.length; j++) joined.push(currentLineEndBuf[j]);
      }
    }
  }

  const result: number[] = [];
  let i = 0;
  while (i < joined.length) {
    if (joined[i] === 0x3D && i + 2 < joined.length && isHexByte(joined[i + 1]) && isHexByte(joined[i + 2])) {
      result.push(parseInt(String.fromCharCode(joined[i + 1], joined[i + 2]), 16));
      i += 3;
    } else {
      result.push(joined[i]);
      i++;
    }
  }
  return Buffer.from(result);
}

function isHexByte(b: number): boolean {
  return (b >= 0x30 && b <= 0x39) || (b >= 0x41 && b <= 0x46) || (b >= 0x61 && b <= 0x66);
}

// --- Charset decoding ---

function decodeBytesToText(buf: Buffer, charset: string): string {
  switch (charset) {
    case 'us-ascii':
    case 'ascii':
    case 'iso-8859-1':
    case 'latin-1':
    case 'latin1':
      return buf.toString('latin1');
    case 'utf-8':
    case 'utf8':
      return buf.toString('utf-8');
    case 'windows-1252':
    case 'cp1252': {
      let s = '';
      for (let i = 0; i < buf.length; i++) {
        const b = buf[i];
        if (b >= 0x80 && b <= 0x9F) {
          s += String.fromCodePoint(CP1252[b - 0x80]);
        } else {
          s += String.fromCharCode(b);
        }
      }
      return s;
    }
    default:
      return buf.toString('latin1');
  }
}

// --- RFC 2047 encoded words ---

function decodeEncodedWords(text: string): string {
  const pattern = /=\?([^? \t]+)\?([BbQq])\?([^? \t]*)\?=/g;
  interface Word {
    start: number; end: number; charset: string; encoding: string; encodedText: string;
  }
  const words: Word[] = [];
  let m: RegExpExecArray | null;
  while ((m = pattern.exec(text)) !== null) {
    words.push({
      start: m.index, end: m.index + m[0].length,
      charset: m[1], encoding: m[2], encodedText: m[3],
    });
  }
  if (words.length === 0) return text;

  interface Group { words: Word[]; start: number; end: number; }
  const groups: Group[] = [];
  let cur: Group = { words: [words[0]], start: words[0].start, end: words[0].end };

  for (let i = 1; i < words.length; i++) {
    const prev = words[i - 1];
    const curr = words[i];
    const between = text.slice(prev.end, curr.start);
    const adjacent = /^[ \t]*$/.test(between);
    const prevCs = prev.charset.split('*')[0].toLowerCase();
    const currCs = curr.charset.split('*')[0].toLowerCase();
    if (adjacent && prevCs === currCs) {
      cur.words.push(curr);
      cur.end = curr.end;
    } else {
      groups.push(cur);
      cur = { words: [curr], start: curr.start, end: curr.end };
    }
  }
  groups.push(cur);

  let result = '';
  let pos = 0;
  for (const group of groups) {
    result += text.slice(pos, group.start);
    const charset = group.words[0].charset.split('*')[0].toLowerCase();
    let allBytes: number[] = [];
    for (const w of group.words) {
      if (w.encoding === 'B' || w.encoding === 'b') {
        const decoded = Buffer.from(w.encodedText, 'base64');
        for (let j = 0; j < decoded.length; j++) allBytes.push(decoded[j]);
      } else {
        allBytes = allBytes.concat(qDecodeWord(w.encodedText));
      }
    }
    result += decodeBytesToText(Buffer.from(allBytes), charset);
    pos = group.end;
  }
  result += text.slice(pos);
  return result;
}

function qDecodeWord(s: string): number[] {
  const bytes: number[] = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '_') {
      bytes.push(0x20);
      i++;
    } else if (s[i] === '=' && i + 2 < s.length && isHexChar(s[i + 1]) && isHexChar(s[i + 2])) {
      bytes.push(parseInt(s.slice(i + 1, i + 3), 16));
      i += 3;
    } else {
      bytes.push(s.charCodeAt(i));
      i++;
    }
  }
  return bytes;
}

function isHexChar(c: string): boolean {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

// --- RFC 2231 file names ---

function resolveFileName(entity: Entity): string | null {
  if (entity.cd) {
    let name = resolveRFC2231(entity.cd.params, 'filename');
    if (name !== null) return name;
    const plain = entity.cd.params.get('filename');
    if (plain !== undefined) return decodeEncodedWords(plain);
  }
  let name = resolveRFC2231(entity.ct.params, 'name');
  if (name !== null) return name;
  const plain = entity.ct.params.get('name');
  if (plain !== undefined) return decodeEncodedWords(plain);
  return null;
}

function resolveRFC2231(params: Map<string, string>, attr: string): string | null {
  const singleKey = attr + '*';
  if (params.has(singleKey)) {
    return decodeRFC2231Single(params.get(singleKey)!);
  }
  const segments: { num: number; pe: boolean; value: string }[] = [];
  const prefix = attr + '*';
  for (const [key, value] of params) {
    if (key.startsWith(prefix)) {
      const suffix = key.slice(prefix.length);
      const m = suffix.match(/^(\d+)(\*?)$/);
      if (m) {
        segments.push({ num: parseInt(m[1], 10), pe: m[2] === '*', value });
      }
    }
  }
  if (segments.length === 0) return null;
  segments.sort((a, b) => a.num - b.num);
  return decodeRFC2231Continuation(segments);
}

function decodeRFC2231Single(value: string): string {
  const q1 = value.indexOf("'");
  const q2 = q1 >= 0 ? value.indexOf("'", q1 + 1) : -1;
  if (q1 < 0 || q2 < 0) return value;
  const charset = value.slice(0, q1).toLowerCase();
  const encoded = value.slice(q2 + 1);
  const bytes = percentDecodeBytes(encoded);
  return decodeBytesToText(Buffer.from(bytes), charset);
}

function decodeRFC2231Continuation(segments: { num: number; pe: boolean; value: string }[]): string {
  let charset = 'us-ascii';
  let allBytes: number[] = [];
  let foundCharset = false;
  for (const seg of segments) {
    let bytes: number[];
    if (seg.pe) {
      bytes = percentDecodeBytes(seg.value);
      if (!foundCharset) {
        const q1 = bytes.indexOf(0x27);
        const q2 = q1 >= 0 ? bytes.indexOf(0x27, q1 + 1) : -1;
        if (q1 >= 0 && q2 >= 0) {
          charset = Buffer.from(bytes.slice(0, q1)).toString('ascii').toLowerCase();
          bytes = bytes.slice(q2 + 1);
          foundCharset = true;
        }
      }
    } else {
      bytes = [];
      for (let i = 0; i < seg.value.length; i++) bytes.push(seg.value.charCodeAt(i));
    }
    allBytes = allBytes.concat(bytes);
  }
  return decodeBytesToText(Buffer.from(allBytes), charset);
}

function percentDecodeBytes(s: string): number[] {
  const bytes: number[] = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '%' && i + 2 < s.length && isHexChar(s[i + 1]) && isHexChar(s[i + 2])) {
      bytes.push(parseInt(s.slice(i + 1, i + 3), 16));
      i += 3;
    } else {
      bytes.push(s.charCodeAt(i));
      i++;
    }
  }
  return bytes;
}

// --- Output ---

function printEntity(entity: Entity, indent: number) {
  const pad = ' '.repeat(indent);

  if (entity.parts !== null) {
    console.log(`${pad}multipart/${entity.ct.subtype} parts=${entity.parts.length}`);
    for (const part of entity.parts) {
      printEntity(part, indent + 2);
    }
  } else {
    const decodedBytes = decodeBody(entity);
    const charset = getCharset(entity);
    const disposition = entity.cd ? entity.cd.type : '-';
    const isText = entity.ct.type === 'text' && disposition !== 'attachment';

    if (isText) {
      let text = decodeBytesToText(decodedBytes, charset);
      text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
      const numChars = Array.from(text).length;
      console.log(`${pad}${entity.ct.type}/${entity.ct.subtype} charset=${charset} cte=${entity.cte} chars=${numChars}`);
      console.log(`${pad}  ${quotedString(text)}`);
    } else {
      const size = decodedBytes.length;
      const crc = crc32(decodedBytes).toString(16).padStart(8, '0');
      const name = resolveFileName(entity);
      const nameStr = name !== null ? quotedString(name) : '-';
      console.log(`${pad}${entity.ct.type}/${entity.ct.subtype} cte=${entity.cte} disposition=${disposition} name=${nameStr} size=${size} crc32=${crc}`);
    }
  }
}

function getCharset(entity: Entity): string {
  if (entity.ct.type === 'text') {
    const cs = entity.ct.params.get('charset');
    return cs !== undefined ? cs.toLowerCase() : 'us-ascii';
  }
  return 'us-ascii';
}

function quotedString(text: string): string {
  let result = '"';
  for (const ch of text) {
    const cp = ch.codePointAt(0)!;
    if (ch === '\\') result += '\\\\';
    else if (ch === '"') result += '\\"';
    else if (ch === '\n') result += '\\n';
    else if (ch === '\t') result += '\\t';
    else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) {
      result += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      result += ch;
    }
  }
  result += '"';
  return result;
}

