#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <ctype.h>
#include <dirent.h>
#include <sys/stat.h>
#include <stdint.h>

/* Dynamic byte buffer */
typedef struct { unsigned char *d; size_t len, cap; } Buf;
static void binit(Buf *b){b->d=NULL;b->len=0;b->cap=0;}
static void bensure(Buf *b,size_t x){if(b->len+x>b->cap){b->cap=(b->len+x)*2+64;b->d=realloc(b->d,b->cap);}}
static void bpush(Buf *b,unsigned char c){bensure(b,1);b->d[b->len++]=c;}
static void bpushn(Buf *b,const unsigned char*p,size_t n){bensure(b,n);memcpy(b->d+b->len,p,n);b->len+=n;}

/* CRC-32 (zlib/PNG) */
static uint32_t crctab[256];
static void init_crc(void){for(int i=0;i<256;i++){uint32_t c=i;for(int j=0;j<8;j++)c=(c&1)?(0xEDB88320^(c>>1)):(c>>1);crctab[i]=c;}}
static uint32_t crc32(const unsigned char*d,size_t n){uint32_t c=0xFFFFFFFF;for(size_t i=0;i<n;i++)c=crctab[(c^d[i])&0xFF]^(c>>8);return c^0xFFFFFFFF;}

/* Base64 decode */
static void b64dec(const unsigned char*in,size_t n,Buf*out){
    int rev[256];memset(rev,-1,sizeof(rev));
    const char*a="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    for(int i=0;i<64;i++)rev[(unsigned char)a[i]]=i;
    uint32_t bits=0;int nb=0;
    for(size_t i=0;i<n;i++){unsigned char c=in[i];if(c=='=')break;if(rev[c]<0)continue;bits=(bits<<6)|rev[c];nb+=6;if(nb>=8){nb-=8;bpush(out,(unsigned char)((bits>>nb)&0xFF));}}
}

/* Quoted-printable transfer decode */
static void qpdec(const unsigned char*in,size_t n,Buf*out,int crlf){
    Buf tmp;binit(&tmp);
    size_t lb=crlf?2:1;
    size_t i=0;
    while(i<n){
        if(crlf&&i+1<n&&in[i]=='\r'&&in[i+1]=='\n'){
            size_t j=tmp.len;
            while(j>0&&(tmp.d[j-1]==' '||tmp.d[j-1]=='\t'))j--;
            if(j>0&&tmp.d[j-1]=='='){tmp.len=j-1;i+=2;}
            else{bpush(&tmp,'\r');bpush(&tmp,'\n');i+=2;}
        }else if(in[i]=='\n'){
            size_t j=tmp.len;
            while(j>0&&(tmp.d[j-1]==' '||tmp.d[j-1]=='\t'))j--;
            if(j>0&&tmp.d[j-1]=='='){tmp.len=j-1;i+=1;}
            else{bpush(&tmp,'\n');i+=1;}
        }else{bpush(&tmp,in[i]);i++;}
    }
    /* Pass 2: decode =XY */
    i=0;
    while(i<tmp.len){
        if(tmp.d[i]=='='&&i+2<tmp.len){
            int h1=-1,h2=-1;
            char c1=(char)tmp.d[i+1],c2=(char)tmp.d[i+2];
            if(c1>='0'&&c1<='9')h1=c1-'0';else if(c1>='A'&&c1<='F')h1=c1-'A'+10;else if(c1>='a'&&c1<='f')h1=c1-'a'+10;
            if(c2>='0'&&c2<='9')h2=c2-'0';else if(c2>='A'&&c2<='F')h2=c2-'A'+10;else if(c2>='a'&&c2<='f')h2=c2-'a'+10;
            if(h1>=0&&h2>=0){bpush(out,(unsigned char)(h1*16+h2));i+=3;}
            else{bpush(out,'=');i++;}
        }else{bpush(out,tmp.d[i]);i++;}
    }
    free(tmp.d);
}

/* Transfer decode */
static void tdec(const unsigned char*body,size_t blen,const char*cte,Buf*out,int crlf){
    if(strcasecmp(cte,"base64")==0)b64dec(body,blen,out);
    else if(strcasecmp(cte,"quoted-printable")==0)qpdec(body,blen,out,crlf);
    else bpushn(out,body,blen); /* 7bit, 8bit, binary */
}

/* Charset decode: bytes → code points */
static void csdec(const unsigned char*d,size_t n,const char*cs,uint32_t**out,size_t*outn){
    uint32_t*cp=malloc((n+1)*sizeof(uint32_t));size_t k=0;
    if(strcasecmp(cs,"utf-8")==0){
        size_t i=0;
        while(i<n){
            unsigned char c=d[i];
            if(c<0x80){cp[k++]=c;i++;}
            else if((c&0xE0)==0xC0&&i+1<n){cp[k++]=((uint32_t)(c&0x1F)<<6)|(d[i+1]&0x3F);i+=2;}
            else if((c&0xF0)==0xE0&&i+2<n){cp[k++]=((uint32_t)(c&0x0F)<<12)|((uint32_t)(d[i+1]&0x3F)<<6)|(d[i+2]&0x3F);i+=3;}
            else if((c&0xF8)==0xF0&&i+3<n){cp[k++]=((uint32_t)(c&0x07)<<18)|((uint32_t)(d[i+1]&0x3F)<<12)|((uint32_t)(d[i+2]&0x3F)<<6)|(d[i+3]&0x3F);i+=4;}
            else{cp[k++]=c;i++;}
        }
    }else if(strcasecmp(cs,"windows-1252")==0){
        static const uint32_t m1252[]={
            0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
            0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
            0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
            0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178};
        for(size_t i=0;i<n;i++){unsigned char c=d[i];if(c>=0x80&&c<=0x9F)cp[k++]=m1252[c-0x80];else cp[k++]=c;}
    }else{
        /* us-ascii, iso-8859-1, unknown */
        for(size_t i=0;i<n;i++)cp[k++]=d[i];
    }
    *out=cp;*outn=k;
}

/* RFC 2047 encoded-word decode */
static void rfc2047(const char*val,uint32_t**out,size_t*outn){
    size_t len=strlen(val);
    typedef struct{size_t s,e,es,ee;char cs[256];char enc;}EW;
    EW*words=malloc(sizeof(EW)*(len/4+1));int nw=0;
    size_t pos=0;
    while(pos<len){
        if(val[pos]=='='&&pos+1<len&&val[pos+1]=='?'){
            size_t p=pos+2;
            size_t cs_s=p;
            while(p<len&&val[p]!='?'&&val[p]!=' '&&val[p]!='\t')p++;
            if(p>=len||val[p]!='?'||p==cs_s){pos++;continue;}
            size_t cs_e=p;p++;
            if(p>=len){pos++;continue;}
            char enc=val[p];
            if(enc!='B'&&enc!='b'&&enc!='Q'&&enc!='q'){pos++;continue;}
            p++;
            if(p>=len||val[p]!='?'){pos++;continue;}
            p++;
            size_t et_s=p;
            while(p<len&&val[p]!='?'&&val[p]!=' '&&val[p]!='\t')p++;
            if(p+1>=len||val[p]!='?'||val[p+1]!='='){pos++;continue;}
            size_t et_e=p;p+=2;
            words[nw].s=pos;words[nw].e=p;words[nw].es=et_s;words[nw].ee=et_e;
            size_t cl=cs_e-cs_s;if(cl>=256)cl=255;
            memcpy(words[nw].cs,val+cs_s,cl);words[nw].cs[cl]='\0';
            words[nw].enc=enc;
            nw++;pos=p;
        }else pos++;
    }
    /* Build output */
    uint32_t*res=malloc((len+1)*sizeof(uint32_t));size_t rn=0;
    size_t prev_e=0;int wi=0;
    while(wi<nw){
        /* text before this word */
        for(size_t i=prev_e;i<words[wi].s;i++)res[rn++]=(unsigned char)val[i];
        /* collect run */
        int run_s=wi,run_e=wi;
        size_t cur_e=words[wi].e;
        while(run_e+1<nw){
            int adj=1;
            for(size_t i=cur_e;i<words[run_e+1].s;i++){if(val[i]!=' '&&val[i]!='\t'){adj=0;break;}}
            if(!adj)break;
            /* compare charset (case-insensitive, strip *lang) */
            char*c1=words[run_s].cs,*c2=words[run_e+1].cs;
            char*s1=strchr(c1,'*'),*s2=strchr(c2,'*');
            size_t l1=s1?(size_t)(s1-c1):strlen(c1);
            size_t l2=s2?(size_t)(s2-c2):strlen(c2);
            if(l1!=l2)break;
            if(strncasecmp(c1,c2,l1)!=0)break;
            run_e++;cur_e=words[run_e].e;
        }
        /* decode run */
        Buf rb;binit(&rb);
        for(int w=run_s;w<=run_e;w++){
            const char*et=val+words[w].es;size_t el=words[w].ee-words[w].es;
            if(words[w].enc=='B'||words[w].enc=='b'){
                b64dec((const unsigned char*)et,el,&rb);
            }else{
                /* Q encoding */
                for(size_t j=0;j<el;j++){
                    if(et[j]=='_')bpush(&rb,0x20);
                    else if(et[j]=='='&&j+2<el){
                        int h1=-1,h2=-1;char a=et[j+1],b=et[j+2];
                        if(a>='0'&&a<='9')h1=a-'0';else if(a>='A'&&a<='F')h1=a-'A'+10;else if(a>='a'&&a<='f')h1=a-'a'+10;
                        if(b>='0'&&b<='9')h2=b-'0';else if(b>='A'&&b<='F')h2=b-'A'+10;else if(b>='a'&&b<='f')h2=b-'a'+10;
                        if(h1>=0&&h2>=0){bpush(&rb,(unsigned char)(h1*16+h2));j+=2;}
                        else bpush(&rb,'=');
                    }else bpush(&rb,(unsigned char)et[j]);
                }
            }
        }
        /* extract charset (strip *lang) */
        char cs2use[256];
        char*st=strchr(words[run_s].cs,'*');
        if(st){size_t l=(size_t)(st-words[run_s].cs);memcpy(cs2use,words[run_s].cs,l);cs2use[l]='\0';}
        else strcpy(cs2use,words[run_s].cs);
        uint32_t*rcp;size_t rcn;
        csdec(rb.d,rb.len,cs2use,&rcp,&rcn);
        for(size_t j=0;j<rcn;j++)res[rn++]=rcp[j];
        free(rcp);free(rb.d);
        prev_e=cur_e;
        wi=run_e+1;
    }
    /* text after last word */
    for(size_t i=prev_e;i<len;i++)res[rn++]=(unsigned char)val[i];
    free(words);
    *out=res;*outn=rn;
}

/* Parameter structure */
typedef struct{char name[256];char value[4096];int is_q; /* is_q: value was quoted */} Param;

/* Parse parameter list from value string (after type/subtype or disposition type) */
static void parse_params(const char*s,Param*params,int*pn){
    *pn=0;
    while(*s){
        while(*s==' '||*s=='\t')s++;
        if(*s!=';')break;
        s++;
        while(*s==' '||*s=='\t')s++;
        /* read name (up to =, space, tab, ;) */
        int ni=0;
        while(*s&&*s!='='&&*s!=' '&&*s!='\t'&&*s!=';'&&ni<255)params[*pn].name[ni++]=*s++;
        params[*pn].name[ni]='\0';
        /* lowercase name */
        for(int i=0;i<ni;i++)params[*pn].name[i]=tolower((unsigned char)params[*pn].name[i]);
        while(*s==' '||*s=='\t')s++;
        if(*s!='=')break;
        s++;
        while(*s==' '||*s=='\t')s++;
        /* read value */
        int vi=0;params[*pn].is_q=0;
        if(*s=='"'){
            s++;params[*pn].is_q=1;
            while(*s&&*s!='"'&&vi<4095){
                if(*s=='\\'&&s[1]){s++;params[*pn].value[vi++]=*s++;}
                else params[*pn].value[vi++]=*s++;
            }
            if(*s=='"')s++;
        }else{
            while(*s&&*s!=';'&&*s!=' '&&*s!='\t'&&vi<4095)params[*pn].value[vi++]=*s++;
        }
        params[*pn].value[vi]='\0';
        (*pn)++;
    }
}

/* Find a param by name (case-insensitive) */
static Param*find_param(Param*ps,int n,const char*name){
    for(int i=0;i<n;i++)if(strcasecmp(ps[i].name,name)==0)return&ps[i];
    return NULL;
}

/* Percent decode */
static void pctdec(const char*s,Buf*out){
    while(*s){
        if(*s=='%'&&s[1]&&s[2]){
            int h1=-1,h2=-1;char a=s[1],b=s[2];
            if(a>='0'&&a<='9')h1=a-'0';else if(a>='A'&&a<='F')h1=a-'A'+10;else if(a>='a'&&a<='f')h1=a-'a'+10;
            if(b>='0'&&b<='9')h2=b-'0';else if(b>='A'&&b<='F')h2=b-'A'+10;else if(b>='a'&&b<='f')h2=b-'a'+10;
            if(h1>=0&&h2>=0){bpush(out,(unsigned char)(h1*16+h2));s+=3;}
            else{bpush(out,(unsigned char)*s);s++;}
        }else{bpush(out,(unsigned char)*s);s++;}
    }
}

/* RFC 2231 decode for an attribute 'attr' from params */
static int rfc2231(Param*ps,int np,const char*attr,char*out,int outsz){
    /* Check single-segment: attr* */
    char sname[256];
    snprintf(sname,sizeof(sname),"%s*",attr);
    Param*p=find_param(ps,np,sname);
    if(p){
        /* p->value is charset'lang'percent-encoded */
        char cs[256]={0};
        const char*v=p->value;
        const char*q1=strchr(v,'\'');
        if(!q1){/* malformed, treat as literal */strcpy(out,v);return 1;}
        size_t cl=(size_t)(q1-v);if(cl>=256)cl=255;
        memcpy(cs,v,cl);cs[cl]='\0';
        const char*q2=strchr(q1+1,'\'');
        if(!q2){strcpy(out,v);return 1;}
        const char*enc=q2+1;
        Buf rb;binit(&rb);
        pctdec(enc,&rb);
        uint32_t*cp;size_t cn;
        csdec(rb.d,rb.len,cs,&cp,&cn);
        /* encode as UTF-8 */
        int oi=0;
        for(size_t i=0;i<cn&&oi<outsz-4;i++){
            uint32_t c=cp[i];
            if(c<0x80)out[oi++]=(char)c;
            else if(c<0x800){out[oi++]=(char)(0xC0|(c>>6));out[oi++]=(char)(0x80|(c&0x3F));}
            else if(c<0x10000){out[oi++]=(char)(0xE0|(c>>12));out[oi++]=(char)(0x80|((c>>6)&0x3F));out[oi++]=(char)(0x80|(c&0x3F));}
            else{out[oi++]=(char)(0xF0|(c>>18));out[oi++]=(char)(0x80|((c>>12)&0x3F));out[oi++]=(char)(0x80|((c>>6)&0x3F));out[oi++]=(char)(0x80|(c&0x3F));}
        }
        out[oi]='\0';
        free(cp);free(rb.d);
        return 1;
    }
    /* Check continuation segments: attr*0, attr*1, ... */
    int segs[100];int seg_pct[100];int nsegs=0;
    char seg_vals[100][4096];
    for(int i=0;i<np;i++){
        /* check if ps[i].name starts with attr* followed by digits, optionally followed by * */
        size_t alen=strlen(attr);
        if(strncasecmp(ps[i].name,attr,alen)!=0)continue;
        if(ps[i].name[alen]!='*')continue;
        const char*d=ps[i].name+alen+1;
        if(*d<'0'||*d>'9')continue;
        int num=atoi(d);
        const char*after=d;while(*after>='0'&&*after<='9')after++;
        int pct=(*after=='*')?1:0;
        if(nsegs<100){segs[nsegs]=num;seg_pct[nsegs]=pct;strncpy(seg_vals[nsegs],ps[i].value,4095);seg_vals[nsegs][4095]='\0';nsegs++;}
    }
    if(nsegs==0)return 0;
    /* sort by segment number */
    for(int i=0;i<nsegs-1;i++)for(int j=i+1;j<nsegs;j++){
        if(segs[j]<segs[i]){int t=segs[i];segs[i]=segs[j];segs[j]=t;
        t=seg_pct[i];seg_pct[i]=seg_pct[j];seg_pct[j]=t;
        char tmp[4096];strcpy(tmp,seg_vals[i]);strcpy(seg_vals[i],seg_vals[j]);strcpy(seg_vals[j],tmp);}
    }
    /* check if any is percent-encoded */
    int any_pct=0;for(int i=0;i<nsegs;i++)if(seg_pct[i]){any_pct=1;break;}
    char cs[256]="us-ascii";
    Buf rb;binit(&rb);
    size_t start_off=0;
    if(any_pct){
        /* segment 0 must be percent-encoded */
        if(!seg_pct[0]){strcpy(out,seg_vals[0]);return 1;}
        /* extract charset from segment 0 */
        const char*v=seg_vals[0];
        const char*q1=strchr(v,'\'');
        const char*q2=q1?strchr(q1+1,'\''):NULL;
        if(q1&&q2){
            size_t cl=(size_t)(q1-v);if(cl>=256)cl=255;
            memcpy(cs,v,cl);cs[cl]='\0';
            start_off=(size_t)(q2-v)+1;
        }
    }
    for(int i=0;i<nsegs;i++){
        const char*v=seg_vals[i];
        size_t off=(i==0)?start_off:0;
        if(seg_pct[i])pctdec(v+off,&rb);
        else bpushn(&rb,(const unsigned char*)(v+off),strlen(v+off));
    }
    uint32_t*cp;size_t cn;
    csdec(rb.d,rb.len,cs,&cp,&cn);
    int oi=0;
    for(size_t i=0;i<cn&&oi<outsz-4;i++){
        uint32_t c=cp[i];
        if(c<0x80)out[oi++]=(char)c;
        else if(c<0x800){out[oi++]=(char)(0xC0|(c>>6));out[oi++]=(char)(0x80|(c&0x3F));}
        else if(c<0x10000){out[oi++]=(char)(0xE0|(c>>12));out[oi++]=(char)(0x80|((c>>6)&0x3F));out[oi++]=(char)(0x80|(c&0x3F));}
        else{out[oi++]=(char)(0xF0|(c>>18));out[oi++]=(char)(0x80|((c>>12)&0x3F));out[oi++]=(char)(0x80|((c>>6)&0x3F));out[oi++]=(char)(0x80|(c&0x3F));}
    }
    out[oi]='\0';
    free(cp);free(rb.d);
    return 1;
}

/* Entity */
typedef struct Ent{
    char type[256],subtype[256];
    char cte[256];
    char charset[256];
    char disp[256];int has_disp;
    char boundary[256];
    char filename[8192];int has_fn;
