    }
}

/* RFC 2047 encoded-word decode */
static void rfc2047(const char*val,Buf*out_utf8){
    size_t len=strlen(val);
    typedef struct{size_t s,e,es,ee;char cs[256];char enc;}EW;
    EW*words=(EW*)malloc(sizeof(EW)*(len/4+2));int nw=0;
    size_t pos=0;
    while(pos<len){
        if(val[pos]=='='&&pos+1<len&&val[pos+1]=='?'){
            size_t p=pos+2;
            size_t cs_s=p;
            while(p<len&&val[p]!='?'&&val[p]!=' '&&val[p]!='\t')p++;
            if(p>=len||val[p]!='?'||p==cs_s){pos++;continue;}
            size_t cs_e=p;p++;
            if(p>=len){pos++;continue;}
            char enc=val[p];
            if(enc!='B'&&enc!='b'&&enc!='Q'&&enc!='q'){pos++;continue;}
            p++;
            if(p>=len||val[p]!='?'){pos++;continue;}
            p++;
            size_t et_s=p;
            while(p<len&&val[p]!='?'&&val[p]!=' '&&val[p]!='\t')p++;
            if(p+1>=len||val[p]!='?'||val[p+1]!='='){pos++;continue;}
            size_t et_e=p;p+=2;
            words[nw].s=pos;words[nw].e=p;words[nw].es=et_s;words[nw].ee=et_e;
            size_t cl=cs_e-cs_s;if(cl>=256)cl=255;
            memcpy(words[nw].cs,val+cs_s,cl);words[nw].cs[cl]='\0';
            words[nw].enc=enc;
            nw++;pos=p;
        }else pos++;
    }
    /* Build output */
    Buf res;binit(&res);
    size_t prev_e=0;int wi=0;
    while(wi<nw){
        /* text before this word */
        for(size_t i=prev_e;i<words[wi].s;i++)bpush(&res,(unsigned char)val[i]);
        /* collect run of adjacent words with same charset */
        int run_s=wi,run_e=wi;
        size_t cur_e=words[wi].e;
        while(run_e+1<nw){
            int adj=1;
            for(size_t i=cur_e;i<words[run_e+1].s;i++){if(val[i]!=' '&&val[i]!='\t'){adj=0;break;}}
            if(!adj)break;
            /* compare charset (case-insensitive, strip *lang) */
            char*c1=words[run_s].cs,*c2=words[run_e+1].cs;
            char*s1=strchr(c1,'*'),*s2=strchr(c2,'*');
            size_t l1=s1?(size_t)(s1-c1):strlen(c1);
            size_t l2=s2?(size_t)(s2-c2):strlen(c2);
            if(l1!=l2)break;
            if(strncasecmp(c1,c2,l1)!=0)break;
            run_e++;cur_e=words[run_e].e;
        }
        /* decode run: concatenate all encoded-text bytes, then decode with charset */
        Buf rb;binit(&rb);
        for(int w=run_s;w<=run_e;w++){
            const char*et=val+words[w].es;size_t el=words[w].ee-words[w].es;
            if(words[w].enc=='B'||words[w].enc=='b'){
                b64dec((const unsigned char*)et,el,&rb);
            }else{
                /* Q encoding */
                for(size_t j=0;j<el;j++){
                    if(et[j]=='_')bpush(&rb,0x20);
                    else if(et[j]=='='&&j+2<el){
                        int h1=-1,h2=-1;char a=et[j+1],b=et[j+2];
                        if(a>='0'&&a<='9')h1=a-'0';else if(a>='A'&&a<='F')h1=a-'A'+10;else if(a>='a'&&a<='f')h1=a-'a'+10;
                        if(b>='0'&&b<='9')h2=b-'0';else if(b>='A'&&b<='F')h2=b-'A'+10;else if(b>='a'&&b<='f')h2=b-'a'+10;
                        if(h1>=0&&h2>=0){bpush(&rb,(unsigned char)(h1*16+h2));j+=2;}
                        else bpush(&rb,'=');
