        char csuse[256];
        char*st=strchr(words[run_s].cs,'*');
        if(st){size_t l=(size_t)(st-words[run_s].cs);memcpy(csuse,words[run_s].cs,l);csuse[l]='\0';}
        else strcpy(csuse,words[run_s].cs);
