        params[*pn].name[ni]='\0';
        for(int i=0;i<ni;i++)params[*pn].name[i]=(char)tolower((unsigned char)params[*pn].name[i]);
        while(*s==' '||*s=='\t')s++;
        if(*s!='=')break;
        s++;
