static size_t find_body_start(const unsigned char*data,size_t len,int crlf){
    size_t lb=crlf?2:1;
    if(len>=lb){
        if(crlf&&data[0]=='\r'&&data[1]=='\n')return lb;
        if(!crlf&&data[0]=='\n')return lb;
    }
    for(size_t i=0;i+2*lb<=len;i++){
