                for(size_t k=0;k<llen;k++){if(data[i+k]==':'){colon=(const char*)(data+i+k);break;}}
                if(colon){
                    size_t nl=(size_t)(colon-(const char*)(data+i));if(nl>255)nl=255;
                    memcpy(cur_name,data+i,nl);cur_name[nl]='\0';
                    const char*vp=colon+1;size_t vlen=llen-(size_t)(vp-(const char*)(data+i));
                    while(vlen>0&&(*vp==' '||*vp=='\t')){vp++;vlen--;}
                    while(vlen>0&&(vp[vlen-1]==' '||vp[vlen-1]=='\t'))vlen--;
                    if(vlen>8191)vlen=8191;
                    memcpy(cur_val,vp,vlen);cur_val[vlen]='\0';
                }
            }
            i=eol+1;
        }
        if(have_hdr&&nh<256){
            strcpy(hdrs[nh].name,cur_name);strcpy(hdrs[nh].value,cur_val);nh++;
        }
    }

    /* Extract key headers */
    const char*ct_val=NULL,*cd_val=NULL,*cte_val=NULL;
    e->has_from=0;e->has_subj=0;
    for(int i=0;i<nh;i++){
        if(strcasecmp(hdrs[i].name,"Content-Type")==0)ct_val=hdrs[i].value;
        else if(strcasecmp(hdrs[i].name,"Content-Disposition")==0)cd_val=hdrs[i].value;
        else if(strcasecmp(hdrs[i].name,"Content-Transfer-Encoding")==0)cte_val=hdrs[i].value;
        else if(strcasecmp(hdrs[i].name,"From")==0){strcpy(e->from_raw,hdrs[i].value);e->has_from=1;}
        else if(strcasecmp(hdrs[i].name,"Subject")==0){strcpy(e->subj_raw,hdrs[i].value);e->has_subj=1;}
    }

    /* Parse Content-Type */
    Param ct_params[64];int n_ct=0;
    if(ct_val){
        const char*s=ct_val;
        while(*s==' '||*s=='\t')s++;
        int ti=0;while(*s&&*s!='/'&&*s!=';'&&*s!=' '&&*s!='\t'&&ti<255)e->type[ti++]=(char)tolower((unsigned char)*s++);
        e->type[ti]='\0';
        while(*s==' '||*s=='\t')s++;
        if(*s=='/'){s++;while(*s==' '||*s=='\t')s++;}
        int si=0;while(*s&&*s!=';'&&*s!=' '&&*s!='\t'&&si<255)e->subtype[si++]=(char)tolower((unsigned char)*s++);
        e->subtype[si]='\0';
        while(*s==' '||*s=='\t')s++;
        parse_params(s,ct_params,&n_ct);
    }else{
        strcpy(e->type,"text");strcpy(e->subtype,"plain");
    }

    /* Parse Content-Disposition */
    Param cd_params[64];int n_cd=0;
    if(cd_val){
        const char*s=cd_val;
        while(*s==' '||*s=='\t')s++;
        int di=0;while(*s&&*s!=';'&&*s!=' '&&*s!='\t'&&di<255)e->disp[di++]=(char)tolower((unsigned char)*s++);
        e->disp[di]='\0';
        e->has_disp=1;
        while(*s==' '||*s=='\t')s++;
        parse_params(s,cd_params,&n_cd);
    }

    /* CTE */
    if(cte_val){
        int ci=0;const char*s=cte_val;
        while(*s==' '||*s=='\t')s++;
        while(*s&&ci<255)e->cte[ci++]=(char)tolower((unsigned char)*s++);
        e->cte[ci]='\0';
    }else strcpy(e->cte,"7bit");

    /* Charset */
    strcpy(e->charset,"us-ascii");
    if(strcasecmp(e->type,"text")==0){
        Param*cp=find_param(ct_params,n_ct,"charset");
        if(cp){int i=0;const char*v=cp->value;while(*v&&i<255)e->charset[i++]=(char)tolower((unsigned char)*v++);e->charset[i]='\0';}
    }

    /* Boundary */
    if(strcasecmp(e->type,"multipart")==0){
        Param*bp=find_param(ct_params,n_ct,"boundary");
        if(bp)strncpy(e->boundary,bp->value,sizeof(e->boundary)-1);
    }

    /* Filename (RFC 2231 priority) */
    e->has_fn=0;
    if(rfc2231(cd_params,n_cd,"filename",&e->filename_utf8))e->has_fn=1;
    if(!e->has_fn){
        Param*fp=find_param(cd_params,n_cd,"filename");
        if(fp){Buf tmp;binit(&tmp);rfc2047(fp->value,&tmp);bpushn(&e->filename_utf8,tmp.d,tmp.len);free(tmp.d);e->has_fn=1;}
    }
    if(!e->has_fn){
        if(rfc2231(ct_params,n_ct,"name",&e->filename_utf8))e->has_fn=1;
    }
    if(!e->has_fn){
        Param*np=find_param(ct_params,n_ct,"name");
        if(np){Buf tmp;binit(&tmp);rfc2047(np->value,&tmp);bpushn(&e->filename_utf8,tmp.d,tmp.len);free(tmp.d);e->has_fn=1;}
    }

    /* Body */
    e->body=(unsigned char*)data+bs;
    e->body_len=len-bs;

    /* Multipart */
    if(strcasecmp(e->type,"multipart")==0&&e->boundary[0]){
        size_t blen=strlen(e->boundary);
        typedef struct{size_t ls,le;int close;}BM;
        BM*bms=(BM*)malloc(sizeof(BM)*1024);int nbm=0;
        size_t p=0;
        while(p<e->body_len&&nbm<1024){
            size_t le=p;
            while(le<e->body_len&&e->body[le]!='\n')le++;
            size_t ce=le;
            if(crlf&&ce>p&&e->body[ce-1]=='\r')ce--;
            size_t lcl=ce-p;
            int is_close=0,found=0;
            /* check --B-- */
            if(lcl>=2+blen+2&&e->body[p]=='-'&&e->body[p+1]=='-'&&memcmp(e->body+p+2,e->boundary,blen)==0&&e->body[p+2+blen]=='-'&&e->body[p+2+blen+1]=='-'){
                int ok=1;for(size_t k=p+2+blen+2;k<ce;k++)if(e->body[k]!=' '&&e->body[k]!='\t'){ok=0;break;}
                if(ok){is_close=1;found=1;}
            }
            if(!found&&lcl>=2+blen&&e->body[p]=='-'&&e->body[p+1]=='-'&&memcmp(e->body+p+2,e->boundary,blen)==0){
                int ok=1;for(size_t k=p+2+blen;k<ce;k++)if(e->body[k]!=' '&&e->body[k]!='\t'){ok=0;break;}
                if(ok){is_close=0;found=1;}
            }
            if(found){
                bms[nbm].ls=p;bms[nbm].le=(le<e->body_len)?le+1:e->body_len;bms[nbm].close=is_close;nbm++;
            }
            p=(le<e->body_len)?le+1:e->body_len;
        }
        int nparts=nbm>0?nbm-1:0;
        e->kids=(Ent**)malloc(sizeof(Ent*)*(nparts>0?nparts:1));e->nkids=0;
        for(int i=0;i<nparts;i++){
            size_t ps=bms[i].le;
            size_t pe=bms[i+1].ls;
            /* remove trailing line break before delimiter */
            if(pe>ps){
                if(crlf&&pe>=ps+2&&e->body[pe-2]=='\r'&&e->body[pe-1]=='\n')pe-=2;
                else if(e->body[pe-1]=='\n')pe-=1;
            }
            e->kids[e->nkids++]=parse_entity(e->body+ps,pe-ps,crlf);
        }
        free(bms);
    }

    return e;
}

/* Replace CRLF and lone CR with LF */
static void normalize_lf(Buf*b){
    size_t j=0;
    for(size_t i=0;i<b->len;i++){
        if(b->d[i]=='\r'){
            if(i+1<b->len&&b->d[i+1]=='\n')i++; /* skip the \n after \r */
            b->d[j++]='\n';
        }else{
            b->d[j++]=b->d[i];
        }
    }
    b->len=j;
}

/* Count code points in UTF-8 */
static size_t count_codepoints(const unsigned char*d,size_t n){
    size_t cnt=0;
    for(size_t i=0;i<n;i++){
        unsigned char c=d[i];
        if(c<0x80)i+=0;
        else if((c&0xE0)==0xC0)i+=1;
        else if((c&0xF0)==0xE0)i+=2;
        else if((c&0xF8)==0xF0)i+=3;
        cnt++;
    }
    return cnt;
}

/* Print quoted string */
static void print_quoted(const unsigned char*d,size_t n){
    putchar('"');
    /* decode UTF-8 to code points and print */
    size_t i=0;
    while(i<n){
        unsigned char c=d[i];
        uint32_t cp;
        if(c<0x80){cp=c;i++;}
        else if((c&0xE0)==0xC0&&i+1<n){cp=((uint32_t)(c&0x1F)<<6)|(d[i+1]&0x3F);i+=2;}
        else if((c&0xF0)==0xE0&&i+2<n){cp=((uint32_t)(c&0x0F)<<12)|((uint32_t)(d[i+1]&0x3F)<<6)|(d[i+2]&0x3F);i+=3;}
        else if((c&0xF8)==0xF0&&i+3<n){cp=((uint32_t)(c&0x07)<<18)|((uint32_t)(d[i+1]&0x3F)<<12)|((uint32_t)(d[i+2]&0x3F)<<6)|(d[i+3]&0x3F);i+=4;}
        else{cp=c;i++;}
        if(cp=='\\')printf("\\\\");
        else if(cp=='"')printf("\\\"");
        else if(cp=='\n')printf("\\n");
        else if(cp=='\t')printf("\\t");
        else if(cp<0x20||(cp>=0x7F&&cp<=0x9F))printf("\\u%04x",(unsigned)cp);
        else{
            /* output as UTF-8 */
            if(cp<0x80)putchar((int)cp);
            else if(cp<0x800){putchar(0xC0|(int)(cp>>6));putchar(0x80|(int)(cp&0x3F));}
            else if(cp<0x10000){putchar(0xE0|(int)(cp>>12));putchar(0x80|(int)((cp>>6)&0x3F));putchar(0x80|(int)(cp&0x3F));}
            else{putchar(0xF0|(int)(cp>>18));putchar(0x80|(int)((cp>>12)&0x3F));putchar(0x80|(int)((cp>>6)&0x3F));putchar(0x80|(int)(cp&0x3F));}
        }
    }
    putchar('"');
}

/* Print tree */
static void print_tree(Ent*e,int indent){
    for(int i=0;i<indent;i++)printf("  ");
    if(strcasecmp(e->type,"multipart")==0){
        printf("multipart/%s parts=%d\n",e->subtype,e->nkids);
