/* Global crlf for current file */
static int g_crlf=0;

/* Proper print tree */
static void print_tree2(Ent*e,int indent){
    for(int i=0;i<indent;i++)printf("  ");
    if(strcasecmp(e->type,"multipart")==0){
        printf("multipart/%s parts=%d\n",e->subtype,e->nkids);
        for(int i=0;i<e->nkids;i++)print_tree2(e->kids[i],indent+1);
    }else if(strcasecmp(e->type,"text")==0&&!(e->has_disp&&strcasecmp(e->disp,"attachment")==0)){
        printf("text/%s charset=%s cte=%s ",e->subtype,e->charset,e->cte);
        Buf decoded;binit(&decoded);
        tdec(e->body,e->body_len,e->cte,&decoded,g_crlf);
        normalize_lf(&decoded);
        /* decode charset */
        uint32_t*cp;size_t cn;
        csdec(decoded.d,decoded.len,e->charset,&cp,&cn);
        Buf utf8;binit(&utf8);
        cp_to_utf8(cp,cn,&utf8);
        printf("chars=%zu\n",(size_t)cn);
        for(int i=0;i<indent+1;i++)printf("  ");
        print_quoted(utf8.d,utf8.len);
        printf("\n");
