        free(decoded.d);
    }
}

int main(int argc,char**argv){
    init_crc();
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
    const char*dir=argv[1];
    DIR*d=opendir(dir);
    if(!d){perror("opendir");return 1;}
    struct dirent*de;
    char**names=NULL;int nn=0,ncap=0;
    while((de=readdir(d))){
        size_t l=strlen(de->d_name);
        if(l>4&&strcmp(de->d_name+l-4,".eml")==0){
            if(nn>=ncap){ncap=ncap?ncap*2:16;names=realloc(names,ncap*sizeof(char*));}
            names[nn++]=strdup(de->d_name);
        }
    }
    closedir(d);
    /* sort byte-wise ascending */
    for(int i=0;i<nn-1;i++)for(int j=i+1;j<nn;j++){
        if(strcmp(names[j],names[i])<0){char*t=names[i];names[i]=names[j];names[j]=t;}
    }
    int first=1;
    for(int fi=0;fi<nn;fi++){
        char path[4096];
        snprintf(path,sizeof(path),"%s/%s",dir,names[fi]);
        FILE*f=fopen(path,"rb");
        if(!f)continue;
        fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
        unsigned char*raw=(unsigned char*)malloc((size_t)fsz+1);
        fread(raw,1,(size_t)fsz,f);fclose(f);
        /* detect line ending: look for first \r or \n */
        g_crlf=0;
        for(long i=0;i<fsz;i++){if(raw[i]=='\r'){g_crlf=1;break;}if(raw[i]=='\n')break;}
        /* parse */
        Ent*msg=parse_entity(raw,(size_t)fsz,g_crlf);
        if(!first)printf("\n");
        first=0;
        printf("== %s\n",names[fi]);
        /* From */
        if(msg->has_from){
            Buf tmp;binit(&tmp);rfc2047(msg->from_raw,&tmp);
            printf("From: ");print_quoted(tmp.d,tmp.len);printf("\n");free(tmp.d);
        }else printf("From: -\n");
        /* Subject */
        if(msg->has_subj){
            Buf tmp;binit(&tmp);rfc2047(msg->subj_raw,&tmp);
            printf("Subject: ");print_quoted(tmp.d,tmp.len);printf("\n");free(tmp.d);
        }else printf("Subject: -\n");
        print_tree2(msg,0);
        free(raw);
    }
    return 0;
}

import sys
import os

sys.setrecursionlimit(10000)

INT_MIN = -(2**63)
INT_MAX = 2**63 - 1

# ─── Lexer ────────────────────────────────────────────────────────────────────

KEYWORDS = frozenset({'let','fn','if','else','while','for','in','return',
                      'break','continue','and','or','not','true','false','nil'})

class Token:
    __slots__ = ('kind','val','line')
    def __init__(self, kind, val, line):
        self.kind = kind
        self.val = val
        self.line = line

def lex(src):
    tokens = []
    i = 0
    n = len(src)
    line = 1
    while i < n:
        c = src[i]
        if c in ' \t\r\n':
            if c == '\n':
                line += 1
            i += 1
            continue
        if c == '#':
            while i < n and src[i] != '\n':
                i += 1
            continue
        if '0' <= c <= '9':
            j = i + 1
            while j < n and '0' <= src[j] <= '9':
                j += 1
            tokens.append(Token('INT', int(src[i:j]), line))
            i = j
            continue
        if c == '"':
            i += 1
            parts = []
            while i < n and src[i] != '"':
                if src[i] == '\\':
                    i += 1
                    c2 = src[i]
                    if c2 == 'n': parts.append('\n')
                    elif c2 == 't': parts.append('\t')
                    elif c2 == '"': parts.append('"')
                    elif c2 == '\\': parts.append('\\')
                    else: parts.append(c2)
                    i += 1
                else:
                    parts.append(src[i])
                    i += 1
            i += 1
            tokens.append(Token('STRING', ''.join(parts), line))
            continue
        if c.isalpha() or c == '_':
            j = i + 1
            while j < n and (src[j].isalnum() or src[j] == '_'):
                j += 1
            word = src[i:j]
            if word in KEYWORDS:
                tokens.append(Token(word, word, line))
            else:
                tokens.append(Token('IDENT', word, line))
            i = j
            continue
        if i + 1 < n:
            two = src[i:i+2]
            if two in ('==','!=','<=','>='):
                tokens.append(Token(two, two, line))
                i += 2
                continue
        if c in '+-*/%()[{}],;':
            tokens.append(Token(c, c, line))
            i += 1
            continue
        i += 1
    tokens.append(Token('EOF', None, line))
    return tokens

# ─── Parser ───────────────────────────────────────────────────────────────────

class Parser:
    __slots__ = ('tokens','pos')
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse_program(self):
        stmts = []
        while self.peek().kind != 'EOF':
            stmts.append(self.parse_stmt())
        return stmts

    def parse_stmt(self):
        tok = self.peek()
        k = tok.kind
        if k == 'let':
            self.advance()
            name = self.advance().val
            self.expect('=')
            val = self.parse_expr()
            self.expect(';')
            return ('let', tok.line, name, val)
        if k == 'fn':
            self.advance()
            name = self.advance().val
            self.expect('(')
            params = self.parse_params()
            self.expect(')')
            body = self.parse_block()
            return ('fn_decl', tok.line, name, params, body)
        if k == 'if':
            return self.parse_if()
        if k == 'while':
            self.advance()
            cond = self.parse_expr()
            body = self.parse_block()
            return ('while', tok.line, cond, body)
        if k == 'for':
            self.advance()
            var = self.advance().val
            self.expect('in')
            iterable = self.parse_expr()
            body = self.parse_block()
            return ('for', tok.line, var, iterable, body)
        if k == 'return':
            self.advance()
            if self.peek().kind == ';':
                self.advance()
                return ('return', tok.line, None)
            val = self.parse_expr()
            self.expect(';')
            return ('return', tok.line, val)
        if k == 'break':
            self.advance()
            self.expect(';')
            return ('break', tok.line)
        if k == 'continue':
            self.advance()
            self.expect(';')
            return ('continue', tok.line)
        if k == 'IDENT':
            if self.tokens[self.pos + 1].kind == '=':
                self.advance()
                self.advance()
                val = self.parse_expr()
                self.expect(';')
                return ('assign', tok.line, tok.val, val)
            expr = self.parse_expr()
            if self.peek().kind == '=':
                self.advance()
                val = self.parse_expr()
                self.expect(';')
                return ('index_assign', expr[1], expr[2], expr[3], val)
            self.expect(';')
            return ('expr_stmt', tok.line, expr)
        expr = self.parse_expr()
        self.expect(';')
        return ('expr_stmt', tok.line, expr)

    def parse_if(self):
        tok = self.advance()
        cond = self.parse_expr()
        then_body = self.parse_block()
        else_body = None
        if self.peek().kind == 'else':
            self.advance()
            if self.peek().kind == 'if':
                else_body = self.parse_if()
            else:
                else_body = ('block', self.peek().line, self.parse_block())
        return ('if', tok.line, cond, then_body, else_body)

    def parse_block(self):
        self.expect('{')
        stmts = []
        while self.peek().kind != '}':
            stmts.append(self.parse_stmt())
        self.expect('}')
        return stmts

    def parse_params(self):
        params = []
        if self.peek().kind == ')':
            return params
        params.append(self.advance().val)
        while self.peek().kind == ',':
            self.advance()
            params.append(self.advance().val)
        return params

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.peek().kind == 'or':
            tok = self.advance()
            right = self.parse_and()
            left = ('or', tok.line, left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.peek().kind == 'and':
            tok = self.advance()
            right = self.parse_not()
            left = ('and', tok.line, left, right)
        return left

    def parse_not(self):
        if self.peek().kind == 'not':
            tok = self.advance()
            operand = self.parse_not()
            return ('not', tok.line, operand)
        return self.parse_cmp()

    def parse_cmp(self):
        left = self.parse_add()
        while self.peek().kind in ('==','!=','<','<=','>','>='):
            tok = self.advance()
            right = self.parse_add()
            left = ('cmp', tok.line, tok.val, left, right)
        return left

    def parse_add(self):
        left = self.parse_mul()
        while self.peek().kind in ('+','-'):
            tok = self.advance()
            right = self.parse_mul()
            left = ('binop', tok.line, tok.val, left, right)
        return left

    def parse_mul(self):
        left = self.parse_unary()
        while self.peek().kind in ('*','/','%'):
            tok = self.advance()
            right = self.parse_unary()
            left = ('binop', tok.line, tok.val, left, right)
        return left

    def parse_unary(self):
        if self.peek().kind == '-':
            tok = self.advance()
            operand = self.parse_unary()
            return ('neg', tok.line, operand)
        return self.parse_postfix()

    def parse_postfix(self):
        expr = self.parse_primary()
        while True:
            k = self.peek().kind
            if k == '(':
                tok = self.advance()
                args = []
                if self.peek().kind != ')':
                    args.append(self.parse_expr())
                    while self.peek().kind == ',':
                        self.advance()
                        args.append(self.parse_expr())
                self.expect(')')
                expr = ('call', tok.line, expr, args)
            elif k == '[':
                tok = self.advance()
                idx = self.parse_expr()
                self.expect(']')
                expr = ('index', tok.line, expr, idx)
            else:
                break
        return expr

    def parse_primary(self):
        tok = self.peek()
        k = tok.kind
        if k == 'INT':
            self.advance()
            return ('int', tok.line, tok.val)
        if k == 'STRING':
            self.advance()
            return ('str', tok.line, tok.val)
        if k == 'true':
            self.advance()
            return ('bool', tok.line, True)
        if k == 'false':
            self.advance()
            return ('bool', tok.line, False)
        if k == 'nil':
            self.advance()
            return ('nil', tok.line)
        if k == 'IDENT':
            self.advance()
            return ('ident', tok.line, tok.val)
        if k == '(':
            self.advance()
            expr = self.parse_expr()
            self.expect(')')
            return expr
        if k == '[':
            self.advance()
            elements = []
            if self.peek().kind != ']':
                elements.append(self.parse_expr())
                while self.peek().kind == ',':
                    self.advance()
                    elements.append(self.parse_expr())
            self.expect(']')
            return ('list_lit', tok.line, elements)
        if k == 'fn':
            self.advance()
            self.expect('(')
            params = self.parse_params()
            self.expect(')')
            body = self.parse_block()
            return ('fn_lit', tok.line, params, body)
        self.advance()
        return ('nil', tok.line)

# ─── Runtime Values ───────────────────────────────────────────────────────────

class TernFunction:
    __slots__ = ('params','body','scope')
    def __init__(self, params, body, scope):
        self.params = params
        self.body = body
        self.scope = scope

class BuiltinFunction:
    __slots__ = ('name','arity','func')
    def __init__(self, name, arity, func):
        self.name = name
        self.arity = arity
        self.func = func

class BreakSignal(Exception):
    pass

class ContinueSignal(Exception):
    pass

class ReturnSignal(Exception):
    __slots__ = ('value',)
    def __init__(self, value):
        self.value = value

class TernError(Exception):
    __slots__ = ('line','msg')
    def __init__(self, line, msg):
        self.line = line
        self.msg = msg

class Scope:
    __slots__ = ('vars','parent')
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent

# ─── Helpers ──────────────────────────────────────────────────────────────────

def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)

def type_name(v):
    if v is None: return 'nil'
    if isinstance(v, bool): return 'bool'
    if isinstance(v, int): return 'int'
    if isinstance(v, str): return 'string'
    if isinstance(v, list): return 'list'
    return 'function'

def truthy(v):
    if v is None: return False
    if v is True: return True
    if v is False: return False
    if isinstance(v, int): return v != 0
    if isinstance(v, str): return len(v) != 0
    if isinstance(v, list): return len(v) != 0
    return True

def int_div(a, b):
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return q

def tern_eq(a, b):
    ta = type_name(a)
    tb = type_name(b)
    if ta != tb:
        return False
    if ta == 'nil':
        return True
    if ta == 'bool':
        return a == b
    if ta == 'int':
        return a == b
    if ta == 'string':
        return a == b
    if ta == 'list':
        if len(a) != len(b):
            return False
        for x, y in zip(a, b):
            if not tern_eq(x, y):
                return False
        return True
    return a is b

def quote_string(s):
    r = []
    for c in s:
        if c == '\\': r.append('\\\\')
        elif c == '"': r.append('\\"')
        elif c == '\n': r.append('\\n')
        elif c == '\t': r.append('\\t')
        else: r.append(c)
    return '"' + ''.join(r) + '"'

def display(v, in_list, seen):
    if v is None: return 'nil'
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, int): return str(v)
    if isinstance(v, str):
        if in_list: return quote_string(v)
        return v
    if isinstance(v, list):
        vid = id(v)
        if vid in seen: return '[...]'
        seen.add(vid)
        parts = [display(e, True, seen) for e in v]
        seen.discard(vid)
        return '[' + ', '.join(parts) + ']'
    return '<fn>'

def display_top(v):
    return display(v, False, set())

# ─── Interpreter ──────────────────────────────────────────────────────────────

def eval_expr(node, scope):
    tag = node[0]
    line = node[1]

    if tag == 'int':
        return node[2]
    if tag == 'str':
        return node[2]
    if tag == 'bool':
        return node[2]
    if tag == 'nil':
        return None
    if tag == 'ident':
        name = node[2]
        s = scope
        while s is not None:
            if name in s.vars:
                return s.vars[name]
            s = s.parent
        raise TernError(line, f'undefined variable {name}')
    if tag == 'binop':
        op = node[2]
        left = eval_expr(node[3], scope)
        right = eval_expr(node[4], scope)
        return apply_binop(op, left, right, line)
    if tag == 'and':
        left = eval_expr(node[2], scope)
        if not truthy(left):
            return left
        return eval_expr(node[3], scope)
    if tag == 'or':
        left = eval_expr(node[2], scope)
        if truthy(left):
            return left
        return eval_expr(node[3], scope)
    if tag == 'not':
        val = eval_expr(node[2], scope)
        return not truthy(val)
    if tag == 'neg':
        val = eval_expr(node[2], scope)
        if not is_int(val):
            raise TernError(line, f'cannot apply - to {type_name(val)}')
        result = -val
        if result < INT_MIN or result > INT_MAX:
            raise TernError(line, 'integer overflow')
        return result
    if tag == 'cmp':
        op = node[2]
        left = eval_expr(node[3], scope)
        right = eval_expr(node[4], scope)
        if op == '==':
            return tern_eq(left, right)
        if op == '!=':
            return not tern_eq(left, right)
        if is_int(left) and is_int(right):
            pass
        elif isinstance(left, str) and isinstance(right, str):
            pass
        else:
            raise TernError(line, f'cannot apply {op} to {type_name(left)} and {type_name(right)}')
        if op == '<': return left < right
        if op == '<=': return left <= right
        if op == '>': return left > right
        return left >= right
    if tag == 'call':
        callee = eval_expr(node[2], scope)
        args = [eval_expr(a, scope) for a in node[3]]
        return do_call(callee, args, line)
    if tag == 'index':
        obj = eval_expr(node[2], scope)
        idx = eval_expr(node[3], scope)
        if isinstance(obj, list):
            if not is_int(idx):
                raise TernError(line, f'cannot index list with {type_name(idx)}')
            if idx < 0 or idx >= len(obj):
                raise TernError(line, f'index {idx} out of range for length {len(obj)}')
            return obj[idx]
        if isinstance(obj, str):
            if not is_int(idx):
                raise TernError(line, f'cannot index string with {type_name(idx)}')
            if idx < 0 or idx >= len(obj):
                raise TernError(line, f'index {idx} out of range for length {len(obj)}')
            return obj[idx]
        raise TernError(line, f'cannot index {type_name(obj)} with {type_name(idx)}')
    if tag == 'list_lit':
        return [eval_expr(e, scope) for e in node[2]]
    if tag == 'fn_lit':
        return TernFunction(node[2], node[3], scope)
    raise TernError(line, 'internal error')

def apply_binop(op, left, right, line):
    if op == '+':
        if is_int(left) and is_int(right):
            r = left + right
            if r < INT_MIN or r > INT_MAX:
                raise TernError(line, 'integer overflow')
            return r
        if isinstance(left, str) and isinstance(right, str):
            return left + right
        if isinstance(left, list) and isinstance(right, list):
            return left + right
        raise TernError(line, f'cannot apply + to {type_name(left)} and {type_name(right)}')
    if op == '-':
        if is_int(left) and is_int(right):
            r = left - right
            if r < INT_MIN or r > INT_MAX:
                raise TernError(line, 'integer overflow')
            return r
        raise TernError(line, f'cannot apply - to {type_name(left)} and {type_name(right)}')
    if op == '*':
        if is_int(left) and is_int(right):
            r = left * right
            if r < INT_MIN or r > INT_MAX:
                raise TernError(line, 'integer overflow')
            return r
        raise TernError(line, f'cannot apply * to {type_name(left)} and {type_name(right)}')
    if op == '/':
        if is_int(left) and is_int(right):
            if right == 0:
                raise TernError(line, 'division by zero')
            r = int_div(left, right)
            if r < INT_MIN or r > INT_MAX:
                raise TernError(line, 'integer overflow')
            return r
        raise TernError(line, f'cannot apply / to {type_name(left)} and {type_name(right)}')
    if op == '%':
        if is_int(left) and is_int(right):
            if right == 0:
                raise TernError(line, 'division by zero')
            q = int_div(left, right)
            r = left - q * right
            if r < INT_MIN or r > INT_MAX:
                raise TernError(line, 'integer overflow')
            return r
        raise TernError(line, f'cannot apply % to {type_name(left)} and {type_name(right)}')

def do_call(callee, args, line):
    if isinstance(callee, TernFunction):
        if len(args) != len(callee.params):
            raise TernError(line, f'expected {len(callee.params)} arguments, got {len(args)}')
        new_scope = Scope(callee.scope)
        for p, v in zip(callee.params, args):
            new_scope.vars[p] = v
        try:
            exec_block(callee.body, new_scope)
        except ReturnSignal as r:
            return r.value
        return None
    if isinstance(callee, BuiltinFunction):
        if callee.arity is not None and len(args) != callee.arity:
            raise TernError(line, f'expected {callee.arity} arguments, got {len(args)}')
        return callee.func(args, line)
    raise TernError(line, f'cannot call {type_name(callee)}')

def exec_block(stmts, scope):
    for stmt in stmts:
        exec_stmt(stmt, scope)

def exec_stmt(node, scope):
    tag = node[0]
    line = node[1]

    if tag == 'let':
        name = node[2]
        val = eval_expr(node[3], scope)
        scope.vars[name] = val
    elif tag == 'fn_decl':
        name = node[2]
        scope.vars[name] = TernFunction(node[3], node[4], scope)
    elif tag == 'assign':
        name = node[2]
        val = eval_expr(node[3], scope)
        s = scope
        while s is not None:
            if name in s.vars:
                s.vars[name] = val
                return
            s = s.parent
        raise TernError(line, f'undefined variable {name}')
    elif tag == 'index_assign':
        obj = eval_expr(node[2], scope)
        idx = eval_expr(node[3], scope)
        val = eval_expr(node[4], scope)
        if isinstance(obj, list):
            if not is_int(idx):
                raise TernError(line, f'cannot index list with {type_name(idx)}')
            if idx < 0 or idx >= len(obj):
                raise TernError(line, f'index {idx} out of range for length {len(obj)}')
            obj[idx] = val
        else:
            raise TernError(line, f'cannot assign into {type_name(obj)}')
    elif tag == 'if':
        cond = eval_expr(node[2], scope)
        if truthy(cond):
            exec_block(node[3], Scope(scope))
        elif node[4] is not None:
            eb = node[4]
            if eb[0] == 'if':
                exec_stmt(eb, scope)
            else:
                exec_block(eb[2], Scope(scope))
    elif tag == 'while':
        cond = node[2]
        body = node[3]
        while truthy(eval_expr(cond, scope)):
            try:
                exec_block(body, Scope(scope))
            except BreakSignal:
                break
            except ContinueSignal:
                continue
    elif tag == 'for':
        var = node[2]
        iterable = eval_expr(node[3], scope)
        if not isinstance(iterable, list):
            raise TernError(line, f'cannot iterate {type_name(iterable)}')
        i = 0
        while i < len(iterable):
            new_scope = Scope(scope)
            new_scope.vars[var] = iterable[i]
            try:
                exec_block(node[4], new_scope)
            except BreakSignal:
                break
            except ContinueSignal:
                pass
            i += 1
    elif tag == 'return':
        val = eval_expr(node[2], scope) if node[2] is not None else None
        raise ReturnSignal(val)
    elif tag == 'break':
        raise BreakSignal()
    elif tag == 'continue':
        raise ContinueSignal()
    elif tag == 'expr_stmt':
        eval_expr(node[2], scope)

# ─── Builtins ─────────────────────────────────────────────────────────────────

def make_builtins():
    scope = Scope()

    def bi_print(args, line):
        sys.stdout.write(' '.join(display_top(a) for a in args) + '\n')
        return None
    scope.vars['print'] = BuiltinFunction('print', None, bi_print)

    def bi_str(args, line):
        return display_top(args[0])
    scope.vars['str'] = BuiltinFunction('str', 1, bi_str)

    def bi_type(args, line):
        return type_name(args[0])
    scope.vars['type'] = BuiltinFunction('type', 1, bi_type)

    def bi_len(args, line):
        v = args[0]
        if isinstance(v, str): return len(v)
        if isinstance(v, list): return len(v)
        raise TernError(line, 'bad argument to len')
    scope.vars['len'] = BuiltinFunction('len', 1, bi_len)

    def bi_push(args, line):
        lst, v = args
        if not isinstance(lst, list):
            raise TernError(line, 'bad argument to push')
        lst.append(v)
        return None
    scope.vars['push'] = BuiltinFunction('push', 2, bi_push)

    def bi_pop(args, line):
        lst = args[0]
        if not isinstance(lst, list) or len(lst) == 0:
            raise TernError(line, 'bad argument to pop')
        return lst.pop()
    scope.vars['pop'] = BuiltinFunction('pop', 1, bi_pop)

    def bi_range(args, line):
        a, b = args
        if not is_int(a) or not is_int(b):
            raise TernError(line, 'bad argument to range')
        return list(range(a, b))
    scope.vars['range'] = BuiltinFunction('range', 2, bi_range)

    def bi_slice(args, line):
        x, a, b = args
        if not is_int(a) or not is_int(b):
            raise TernError(line, 'bad argument to slice')
        if isinstance(x, str):
            if 0 <= a <= b <= len(x):
                return x[a:b]
        elif isinstance(x, list):
            if 0 <= a <= b <= len(x):
                return x[a:b]
        raise TernError(line, 'bad argument to slice')
    scope.vars['slice'] = BuiltinFunction('slice', 3, bi_slice)

    return scope

# ─── Main ─────────────────────────────────────────────────────────────────────

def main():
    dirname = sys.argv[1]
    filepath = os.path.join(dirname, 'program.tern')
    with open(filepath, 'r') as f:
        source = f.read()

    tokens = lex(source)
    parser = Parser(tokens)
    ast = parser.parse_program()

    builtins = make_builtins()
    global_scope = Scope(builtins)

    try:
        exec_block(ast, global_scope)
    except TernError as e:
        sys.stdout.write(f'error at line {e.line}: {e.msg}\n')

    sys.exit(0)

main()

use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

fn make_crc_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    for i in 0..256 {
        let mut crc = i as u32;
        for _ in 0..8 {
            if crc & 1 == 1 { crc = (crc >> 1) ^ 0xEDB88320; } else { crc >>= 1; }
        }
        table[i] = crc;
    }
    table
}

fn crc32(data: &[u8], table: &[u32; 256]) -> u32 {
    let mut crc = 0xFFFFFFFFu32;
    for &b in data { crc = table[((crc ^ b as u32) & 0xFF) as usize] ^ (crc >> 8); }
    crc ^ 0xFFFFFFFF
}

fn hex_val(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

fn base64_decode(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut buf: u32 = 0;
    let mut bits: u32 = 0;
    for &b in data {
        let val = match b {
            b'A'..=b'Z' => (b - b'A') as u32,
            b'a'..=b'z' => (b - b'a' + 26) as u32,
            b'0'..=b'9' => (b - b'0' + 52) as u32,
            b'+' => 62u32,
            b'/' => 63u32,
            b'=' => break,
            _ => continue,
        };
        buf = (buf << 6) | val;
        bits += 6;
        if bits >= 8 { bits -= 8; result.push((buf >> bits) as u8); }
    }
    result
}

fn q_decode_2047(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut i = 0;
    while i < data.len() {
        if data[i] == b'_' {
            result.push(0x20); i += 1;
        } else if data[i] == b'=' && i + 2 < data.len() {
            let hi = hex_val(data[i+1]);
            let lo = hex_val(data[i+2]);
            if hi.is_some() && lo.is_some() {
                result.push((hi.unwrap() << 4 | lo.unwrap()) as u8); i += 3;
            } else { result.push(b'='); i += 1; }
        } else { result.push(data[i]); i += 1; }
    }
    result
}

fn find_line_break_pos(data: &[u8], start: usize, crlf: bool) -> usize {
    let mut i = start;
    while i < data.len() {
        if crlf {
            if i + 1 < data.len() && data[i] == b'\r' && data[i+1] == b'\n' { return i; }
        } else {
            if data[i] == b'\n' { return i; }
        }
        i += 1;
    }
    data.len()
}

fn qp_decode(data: &[u8], crlf: bool) -> Vec<u8> {
    let sep_len = if crlf { 2 } else { 1 };
    let mut result = Vec::new();
    let mut pos = 0;
    while pos < data.len() {
        let line_end = find_line_break_pos(data, pos, crlf);
        let mut line = &data[pos..line_end];
        let mut end = line.len();
        while end > 0 && (line[end-1] == b' ' || line[end-1] == b'\t') { end -= 1; }
        line = &line[..end];
        let soft = line.len() > 0 && line[line.len()-1] == b'=';
        if soft { line = &line[..line.len()-1]; }
        let mut i = 0;
        while i < line.len() {
            if line[i] == b'=' && i + 2 < line.len() {
                let hi = hex_val(line[i+1]);
                let lo = hex_val(line[i+2]);
                if hi.is_some() && lo.is_some() {
                    result.push((hi.unwrap() << 4 | lo.unwrap()) as u8); i += 3;
                } else { result.push(b'='); i += 1; }
            } else { result.push(line[i]); i += 1; }
        }
        if line_end < data.len() {
            if !soft { result.extend_from_slice(if crlf { b"\r\n" } else { b"\n" }); }
            pos = line_end + sep_len;
        } else {
            if soft { result.push(b'='); }
            pos = data.len();
        }
    }
    result
}

fn decode_charset(data: &[u8], charset: &str) -> String {
    match charset {
        "us-ascii" | "iso-8859-1" => data.iter().map(|&b| b as char).collect(),
        "utf-8" => String::from_utf8_lossy(data).into_owned(),
        "windows-1252" => {
            let table: [char; 32] = [
                '\u{20AC}','\u{0081}','\u{201A}','\u{0192}','\u{201E}','\u{2026}','\u{2020}','\u{2021}',
                '\u{02C6}','\u{2030}','\u{0160}','\u{2039}','\u{0152}','\u{008D}','\u{017D}','\u{008F}',
                '\u{0090}','\u{2018}','\u{2019}','\u{201C}','\u{201D}','\u{2022}','\u{2013}','\u{2014}',
                '\u{02DC}','\u{2122}','\u{0161}','\u{203A}','\u{0153}','\u{009D}','\u{017E}','\u{0178}',
            ];
            data.iter().map(|&b| {
                if b >= 0x80 && b <= 0x9F { table[(b - 0x80) as usize] } else { b as char }
            }).collect()
        }
        _ => String::from_utf8_lossy(data).into_owned(),
    }
}

fn normalize_line_breaks(s: &str) -> String {
    s.replace("\r\n", "\n").replace('\r', "\n")
}

fn quote_string(s: &str) -> String {
    let mut result = String::from("\"");
    for ch in s.chars() {
        match ch {
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            '\n' => result.push_str("\\n"),
            '\t' => result.push_str("\\t"),
            c => {
                let cp = c as u32;
                if cp < 0x20 || (cp >= 0x7F && cp <= 0x9F) {
                    result.push_str(&format!("\\u{:04x}", cp));
                } else { result.push(c); }
            }
        }
    }
    result.push('"');
    result
}

fn normalize_ew_charset(cs: &str) -> String {
    let lower = cs.to_lowercase();
    if let Some(pos) = lower.find('*') { lower[..pos].to_string() } else { lower }
}

fn decode_rfc2047(s: &str) -> String {
    let bytes = s.as_bytes();
    struct EW { start: usize, end: usize, charset: String, decoded: Vec<u8> }
    let mut matches: Vec<EW> = Vec::new();
    let mut pos = 0;
    while pos < bytes.len() {
        if bytes[pos] == b'=' && pos + 1 < bytes.len() && bytes[pos+1] == b'?' {
            let start = pos;
            let mut p = pos + 2;
            let cs_start = p;
            while p < bytes.len() && bytes[p] != b'?' && bytes[p] != b' ' && bytes[p] != b'\t' { p += 1; }
            if p >= bytes.len() || bytes[p] != b'?' || p == cs_start { pos = start + 1; continue; }
            let charset = &s[cs_start..p]; p += 1;
            if p >= bytes.len() { pos = start + 1; continue; }
            let enc = bytes[p];
            if enc != b'B' && enc != b'b' && enc != b'Q' && enc != b'q' { pos = start + 1; continue; }
            p += 1;
            if p >= bytes.len() || bytes[p] != b'?' { pos = start + 1; continue; }
            p += 1;
            let et_start = p;
            while p < bytes.len() && bytes[p] != b'?' && bytes[p] != b' ' && bytes[p] != b'\t' { p += 1; }
            if p >= bytes.len() || bytes[p] != b'?' { pos = start + 1; continue; }
            p += 1;
            if p >= bytes.len() || bytes[p] != b'=' { pos = start + 1; continue; }
            p += 1;
            let encoded_text = &bytes[et_start..p-2];
            let decoded = match enc {
                b'B' | b'b' => base64_decode(encoded_text),
                _ => q_decode_2047(encoded_text),
            };
            matches.push(EW { start, end: p, charset: charset.to_string(), decoded });
            pos = p;
        } else { pos += 1; }
    }
    if matches.is_empty() { return s.to_string(); }
    let mut result = String::new();
    let mut last_end = 0;
    let mut i = 0;
    while i < matches.len() {
        let group_cs = normalize_ew_charset(&matches[i].charset);
        let mut group_bytes = matches[i].decoded.clone();
        let mut group_end = matches[i].end;
        let mut j = i + 1;
        while j < matches.len() {
            let gap = &bytes[matches[j-1].end..matches[j].start];
            if gap.iter().all(|&b| b == b' ' || b == b'\t')
                && normalize_ew_charset(&matches[j].charset) == group_cs {
                group_bytes.extend_from_slice(&matches[j].decoded);
                group_end = matches[j].end;
                j += 1;
            } else { break; }
        }
        result.push_str(&s[last_end..matches[i].start]);
        result.push_str(&decode_charset(&group_bytes, &group_cs));
        last_end = group_end;
        i = j;
    }
    result.push_str(&s[last_end..]);
    result
}

struct RawParam { name: String, value: String }

fn parse_params(s: &str, start: usize) -> Vec<RawParam> {
    let bytes = s.as_bytes();
    let mut pos = start;
    let mut params = Vec::new();
    loop {
        while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t') { pos += 1; }
        if pos >= bytes.len() || bytes[pos] != b';' { break; }
        pos += 1;
        while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t') { pos += 1; }
        let name_start = pos;
        while pos < bytes.len() && bytes[pos] != b'=' && bytes[pos] != b' ' && bytes[pos] != b'\t' && bytes[pos] != b';' { pos += 1; }
        let name = s[name_start..pos].to_lowercase();
        while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t') { pos += 1; }
        if pos >= bytes.len() || bytes[pos] != b'=' { break; }
        pos += 1;
        while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t') { pos += 1; }
        let value = if pos < bytes.len() && bytes[pos] == b'"' {
            pos += 1;
            let mut val: Vec<u8> = Vec::new();
            while pos < bytes.len() && bytes[pos] != b'"' {
                if bytes[pos] == b'\\' && pos + 1 < bytes.len() { val.push(bytes[pos+1]); pos += 2; }
                else { val.push(bytes[pos]); pos += 1; }
            }
            if pos < bytes.len() { pos += 1; }
            String::from_utf8_lossy(&val).into_owned()
        } else {
            let vs = pos;
            while pos < bytes.len() && bytes[pos] != b';' && bytes[pos] != b' ' && bytes[pos] != b'\t' { pos += 1; }
            s[vs..pos].to_string()
        };
        params.push(RawParam { name, value });
    }
    params
}

fn parse_ct(s: &str) -> (String, String, Vec<RawParam>) {
    let bytes = s.as_bytes();
    let mut pos = 0;
    while pos < bytes.len() && bytes[pos] != b'/' && bytes[pos] != b' ' && bytes[pos] != b'\t' { pos += 1; }
    let ctype = s[..pos].trim().to_lowercase();
    while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t') { pos += 1; }
    if pos < bytes.len() && bytes[pos] == b'/' { pos += 1; }
    while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t') { pos += 1; }
    let ss = pos;
    while pos < bytes.len() && bytes[pos] != b';' && bytes[pos] != b' ' && bytes[pos] != b'\t' { pos += 1; }
    let subtype = s[ss..pos].trim().to_lowercase();
    (ctype, subtype, parse_params(s, pos))
}

fn parse_disp(s: &str) -> (Option<String>, Vec<RawParam>) {
    let bytes = s.as_bytes();
    let mut pos = 0;
    while pos < bytes.len() && bytes[pos] != b';' && bytes[pos] != b' ' && bytes[pos] != b'\t' { pos += 1; }
    let dtype = if pos > 0 { Some(s[..pos].trim().to_lowercase()) } else { None };
    (dtype, parse_params(s, pos))
}

fn percent_decode(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut i = 0;
    while i < data.len() {
        if data[i] == b'%' && i + 2 < data.len() {
            let hi = hex_val(data[i+1]);
            let lo = hex_val(data[i+2]);
            if hi.is_some() && lo.is_some() { result.push((hi.unwrap() << 4 | lo.unwrap()) as u8); i += 3; }
            else { result.push(b'%'); i += 1; }
        } else { result.push(data[i]); i += 1; }
    }
    result
}

fn extract_param_rfc2231(params: &[RawParam], attr: &str) -> Option<String> {
    let single_key = format!("{}*", attr);
    if let Some(p) = params.iter().find(|p| p.name == single_key) {
        return Some(decode_rfc2231_single(&p.value));
    }
    let prefix = format!("{}*", attr);
    let mut segments: Vec<(usize, String, bool)> = Vec::new();
    for p in params {
        if p.name.starts_with(&prefix) && p.name.len() > prefix.len() {
            let rest = &p.name[prefix.len()..];
            let (idx_str, encoded) = if rest.ends_with('*') {
                (&rest[..rest.len()-1], true)
            } else { (rest, false) };
            if let Ok(idx) = idx_str.parse::<usize>() {
                segments.push((idx, p.value.clone(), encoded));
            }
        }
    }
    if !segments.is_empty() {
        segments.sort_by_key(|(idx, _, _)| *idx);
        return Some(decode_rfc2231_continuation(&segments));
    }
    None
}

fn decode_rfc2231_single(value: &str) -> String {
    let bytes = value.as_bytes();
    let mut pos = 0;
    while pos < bytes.len() && bytes[pos] != b'\'' { pos += 1; }
    let charset = if pos > 0 { value[..pos].to_lowercase() } else { "us-ascii".to_string() };
    if pos < bytes.len() { pos += 1; }
    while pos < bytes.len() && bytes[pos] != b'\'' { pos += 1; }
    if pos < bytes.len() { pos += 1; }
    decode_charset(&percent_decode(value[pos..].as_bytes()), &charset)
}

fn decode_rfc2231_continuation(segments: &[(usize, String, bool)]) -> String {
    let mut charset = "us-ascii".to_string();
    let mut all_bytes: Vec<u8> = Vec::new();
    for (idx, value, encoded) in segments {
        if *encoded {
            let mut val = value.as_str();
            if *idx == 0 {
                let vb = val.as_bytes();
                let mut p = 0;
                while p < vb.len() && vb[p] != b'\'' { p += 1; }
                if p > 0 { charset = val[..p].to_lowercase(); }
                if p < vb.len() { p += 1; }
                while p < vb.len() && vb[p] != b'\'' { p += 1; }
                if p < vb.len() { p += 1; }
                val = &val[p..];
            }
            all_bytes.extend_from_slice(&percent_decode(val.as_bytes()));
        } else {
            all_bytes.extend_from_slice(value.as_bytes());
        }
    }
    decode_charset(&all_bytes, &charset)
}

fn extract_filename(cd_params: &[RawParam], ct_params: &[RawParam]) -> Option<String> {
    if let Some(v) = extract_param_rfc2231(cd_params, "filename") { return Some(v); }
    if let Some(p) = cd_params.iter().find(|p| p.name == "filename") { return Some(decode_rfc2047(&p.value)); }
    if let Some(v) = extract_param_rfc2231(ct_params, "name") { return Some(v); }
    if let Some(p) = ct_params.iter().find(|p| p.name == "name") { return Some(decode_rfc2047(&p.value)); }
    None
}

struct Entity {
    headers: BTreeMap<String, String>,
    body: Vec<u8>,
    ctype: String, csubtype: String, ct_params: Vec<RawParam>,
    disp_type: Option<String>, disp_params: Vec<RawParam>,
    cte: String,
}

fn find_body_start(data: &[u8], crlf: bool) -> usize {
    let sep_len = if crlf { 2 } else { 1 };
    let mut pos = 0;
    while pos + sep_len <= data.len() {
        let is_break = if crlf {
            data[pos] == b'\r' && data[pos+1] == b'\n'
        } else {
            data[pos] == b'\n'
        };
        if is_break {
            if pos == 0 { return pos + sep_len; }
            if pos >= sep_len {
                let prev = if crlf {
                    data[pos-2] == b'\r' && data[pos-1] == b'\n'
                } else {
                    data[pos-1] == b'\n'
                };
                if prev { return pos + sep_len; }
            }
        }
        pos += 1;
    }
    data.len()
}

fn parse_headers(data: &[u8], crlf: bool) -> BTreeMap<String, String> {
    let sep_len = if crlf { 2 } else { 1 };
    let mut unfolded: Vec<u8> = Vec::new();
    let mut pos = 0;
    while pos < data.len() {
        let is_break = if pos + sep_len <= data.len() {
            if crlf { data[pos] == b'\r' && data[pos+1] == b'\n' }
            else { data[pos] == b'\n' }
        } else { false };
        if is_break {
            let after = pos + sep_len;
            if after < data.len() && (data[after] == b' ' || data[after] == b'\t') {
                pos = after;
            } else {
                unfolded.push(b'\n');
                pos = after;
            }
        } else { unfolded.push(data[pos]); pos += 1; }
    }
    let mut headers = BTreeMap::new();
    for line in unfolded.split(|&b| b == b'\n') {
        if line.is_empty() { continue; }
        if let Some(cp) = line.iter().position(|&b| b == b':') {
            let name = std::str::from_utf8(&line[..cp]).unwrap_or("").trim().to_lowercase();
            let value = std::str::from_utf8(&line[cp+1..]).unwrap_or("").trim().to_string();
            headers.insert(name, value);
        }
    }
    headers
}

fn parse_entity(data: &[u8], crlf: bool) -> Entity {
    let sep_len = if crlf { 2 } else { 1 };
    let bs = find_body_start(data, crlf);
    let hd_end = if bs > sep_len { bs - sep_len } else { 0 };
    let header_data = &data[..hd_end];
    let body = data[bs..].to_vec();
    let headers = parse_headers(header_data, crlf);
    let (ctype, csubtype, ct_params) = if let Some(ct) = headers.get("content-type") {
        parse_ct(ct)
    } else { ("text".to_string(), "plain".to_string(), vec![]) };
    let (disp_type, disp_params) = if let Some(cd) = headers.get("content-disposition") {
        parse_disp(cd)
    } else { (None, vec![]) };
    let cte = headers.get("content-transfer-encoding")
        .map(|s| s.trim().to_lowercase())
        .unwrap_or_else(|| "7bit".to_string());
    Entity { headers, body, ctype, csubtype, ct_params, disp_type, disp_params, cte }
}

fn find_delimiters(body: &[u8], boundary: &[u8], crlf: bool) -> Vec<(usize, bool)> {
    let sep_len = if crlf { 2 } else { 1 };
    let prefix = format!("--{}", std::str::from_utf8(boundary).unwrap_or(""));
    let pb = prefix.as_bytes();
    let mut delims = Vec::new();
    let mut pos = 0;
    while pos < body.len() {
        if pos + pb.len() <= body.len() && &body[pos..pos+pb.len()] == pb {
            let ap = pos + pb.len();
            let mut is_close = false;
            let mut lce = ap;
            if ap + 1 < body.len() && body[ap] == b'-' && body[ap+1] == b'-' {
                is_close = true; lce = ap + 2;
            }
            let mut i = lce;
            while i < body.len() && (body[i] == b' ' || body[i] == b'\t') { i += 1; }
            let line_ok = if i >= body.len() { true }
                else if crlf { i + 1 < body.len() && body[i] == b'\r' && body[i+1] == b'\n' }
                else { body[i] == b'\n' };
            if line_ok {
                delims.push((pos, is_close));
                pos = if i < body.len() { i + sep_len } else { body.len() };
                continue;
            }
        }
        pos = find_line_break_pos(body, pos, crlf);
        if pos < body.len() { pos += sep_len; } else { break; }
    }
    delims
}

fn extract_parts(body: &[u8], boundary: &[u8], crlf: bool) -> Vec<Vec<u8>> {
    let sep_len = if crlf { 2 } else { 1 };
    let delims = find_delimiters(body, boundary, crlf);
    if delims.is_empty() { return vec![]; }
    let mut end_idx = delims.len();
    for (i, d) in delims.iter().enumerate() {
        if d.1 { end_idx = i + 1; break; }
    }
    let mut parts = Vec::new();
    for i in 0..end_idx.saturating_sub(1) {
        let d1_line_end = find_line_break_pos(body, delims[i].0, crlf);
        let content_start = if d1_line_end < body.len() { d1_line_end + sep_len } else { body.len() };
        let content_end = delims[i+1].0;
        let actual_end = if content_end > content_start {
            if crlf && content_end >= 2 && body[content_end-2] == b'\r' && body[content_end-1] == b'\n' {
                content_end - 2
            } else if !crlf && content_end >= 1 && body[content_end-1] == b'\n' {
                content_end - 1
            } else { content_end }
        } else { content_start };
        if content_start <= actual_end {
            parts.push(body[content_start..actual_end].to_vec());
        } else {
            parts.push(vec![]);
        }
    }
    parts
}

fn decode_te(data: &[u8], cte: &str, crlf: bool) -> Vec<u8> {
    match cte {
        "base64" => base64_decode(data),
        "quoted-printable" => qp_decode(data, crlf),
        _ => data.to_vec(),
    }
}

fn process_entity(entity: &Entity, indent: usize, crlf: bool, crc_table: &[u32; 256]) -> Vec<String> {
    let pad = " ".repeat(indent * 2);
    let mut lines = Vec::new();
    if entity.ctype == "multipart" {
        let boundary = entity.ct_params.iter()
            .find(|p| p.name == "boundary")
            .map(|p| p.value.clone())
            .unwrap_or_default();
        let parts_data = extract_parts(&entity.body, boundary.as_bytes(), crlf);
        lines.push(format!("{}multipart/{} parts={}", pad, entity.csubtype, parts_data.len()));
        for pd in &parts_data {
            let part = parse_entity(pd, crlf);
            lines.extend(process_entity(&part, indent + 1, crlf, crc_table));
        }
    } else if entity.ctype == "text" && entity.disp_type.as_deref() != Some("attachment") {
        let charset = entity.ct_params.iter()
            .find(|p| p.name == "charset")
            .map(|p| p.value.to_lowercase())
            .unwrap_or_else(|| "us-ascii".to_string());
        let decoded_bytes = decode_te(&entity.body, &entity.cte, crlf);
        let decoded_str = decode_charset(&decoded_bytes, &charset);
        let normalized = normalize_line_breaks(&decoded_str);
        let char_count = normalized.chars().count();
        lines.push(format!("{}text/{} charset={} cte={} chars={}", pad, entity.csubtype, charset, entity.cte, char_count));
        lines.push(format!("{}  {}", pad, quote_string(&normalized)));
    } else {
        let decoded_bytes = decode_te(&entity.body, &entity.cte, crlf);
        let size = decoded_bytes.len();
        let crc = crc32(&decoded_bytes, crc_table);
        let disp = entity.disp_type.as_deref().unwrap_or("-");
        let name = extract_filename(&entity.disp_params, &entity.ct_params);
        let name_str = match name {
            Some(n) => quote_string(&n),
            None => "-".to_string(),
        };
        lines.push(format!("{}{}/{} cte={} disposition={} name={} size={} crc32={:08x}",
            pad, entity.ctype, entity.csubtype, entity.cte, disp, name_str, size, crc));
    }
    lines
}

fn process_message(data: &[u8], crc_table: &[u32; 256]) {
    let crlf = data.contains(&b'\r');
    let entity = parse_entity(data, crlf);
    let from = entity.headers.get("from")
        .map(|v| quote_string(&decode_rfc2047(v)))
        .unwrap_or_else(|| "-".to_string());
    println!("From: {}", from);
    let subject = entity.headers.get("subject")
        .map(|v| quote_string(&decode_rfc2047(v)))
        .unwrap_or_else(|| "-".to_string());
    println!("Subject: {}", subject);
    let lines = process_entity(&entity, 0, crlf, crc_table);
    for line in lines { println!("{}", line); }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let mut files: Vec<String> = Vec::new();
    for entry in fs::read_dir(dir).unwrap() {
        let entry = entry.unwrap();
        let name = entry.file_name().to_str().unwrap().to_string();
        if name.ends_with(".eml") { files.push(name); }
    }
    files.sort();
    let crc_table = make_crc_table();
    for (i, name) in files.iter().enumerate() {
        if i > 0 { println!(); }
        println!("== {}", name);
        let path = Path::new(dir).join(name);
        let data = fs::read(&path).unwrap();
        process_message(&data, &crc_table);
    }
}

