                        if (trns != null) {
                            int tr = ((trns[0] & 0xFF) << 8) | (trns[1] & 0xFF);
                            int tg = ((trns[2] & 0xFF) << 8) | (trns[3] & 0xFF);
                            int tb = ((trns[4] & 0xFF) << 8) | (trns[5] & 0xFF);
                            A = (samples[0] == tr && samples[1] == tg && samples[2] == tb) ? 0 : 255;
                        } else A = 255;
                    } else if (ct == 3) {
                        int idx = samples[0];
                        R = plte[idx * 3] & 0xFF;
                        G = plte[idx * 3 + 1] & 0xFF;
                        B = plte[idx * 3 + 2] & 0xFF;
                        if (trns != null && idx < trns.length) A = trns[idx] & 0xFF;
                        else A = 255;
                    } else if (ct == 4) {
                        R = G = B = convertGray(samples[0], depth);
                        A = convertGray(samples[1], depth);
                    } else {
                        R = convertSample(samples[0], depth);
                        G = convertSample(samples[1], depth);
                        B = convertSample(samples[2], depth);
                        A = convertSample(samples[3], depth);
                    }

                    rgbaBuf[rp++] = (byte) R;
                    rgbaBuf[rp++] = (byte) G;
                    rgbaBuf[rp++] = (byte) B;
                    rgbaBuf[rp++] = (byte) A;
                    sums[0] += R; sums[1] += G; sums[2] += B; sums[3] += A;
                }
            }

            CRC32 rcrc = new CRC32();
            rcrc.update(rgbaBuf);
            System.out.println("rgba sum=" + sums[0] + "," + sums[1] + "," + sums[2] + "," + sums[3] +
                              " crc32=" + String.format("%08x", rcrc.getValue()));
        }
    }
}

use std::collections::HashMap;
use std::rc::Rc;
use std::cell::RefCell;
use std::env;
use std::fs;
use std::process;

// ===== Token =====
#[derive(Debug, Clone, PartialEq)]
enum TK {
    Int, Str, Ident,
    Let, Fn, If, Else, While, For, In, Return, Break, Continue,
    And, Or, Not, True, False, Nil,
    Eq, Ne, Le, Ge, Lt, Gt, Assign,
    Plus, Minus, Star, Slash, Percent,
    LP, RP, LB, RB, LC, RC, Comma, Semi,
    EOF,
}

#[derive(Debug, Clone)]
struct Tok { kind: TK, text: String, line: usize }

fn lex(src: &str) -> Vec<Tok> {
    let b = src.as_bytes();
    let mut tokens = Vec::new();
    let mut i = 0usize;
    let mut line = 1usize;
    while i < b.len() {
        let c = b[i];
        if c == b' ' || c == b'\t' || c == b'\r' { i += 1; continue; }
        if c == b'\n' { line += 1; i += 1; continue; }
        if c == b'#' { while i < b.len() && b[i] != b'\n' { i += 1; } continue; }
        if c.is_ascii_digit() {
            let s = i;
            while i < b.len() && b[i].is_ascii_digit() { i += 1; }
            tokens.push(Tok { kind: TK::Int, text: src[s..i].to_string(), line });
            continue;
        }
        if c == b'"' {
            i += 1;
            let mut s = String::new();
            while i < b.len() && b[i] != b'"' {
                if b[i] == b'\\' {
                    i += 1;
                    match b[i] {
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        _ => { s.push('\\'); s.push(b[i] as char); }
                    }
                } else {
                    s.push(b[i] as char);
                }
                i += 1;
            }
            i += 1; // closing "
            tokens.push(Tok { kind: TK::Str, text: s, line });
            continue;
        }
        if c.is_ascii_alphabetic() || c == b'_' {
            let s = i;
            while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_') { i += 1; }
            let text = &src[s..i];
            let kind = match text {
                "let" => TK::Let, "fn" => TK::Fn, "if" => TK::If, "else" => TK::Else,
                "while" => TK::While, "for" => TK::For, "in" => TK::In,
                "return" => TK::Return, "break" => TK::Break, "continue" => TK::Continue,
                "and" => TK::And, "or" => TK::Or, "not" => TK::Not,
                "true" => TK::True, "false" => TK::False, "nil" => TK::Nil,
                _ => TK::Ident,
            };
            tokens.push(Tok { kind, text: text.to_string(), line });
            continue;
        }
        // operators (longest match first)
        let (kind, len) = if i + 1 < b.len() {
            let two = (b[i], b[i+1]);
            match two {
                (b'=', b'=') => (TK::Eq, 2),
                (b'!', b'=') => (TK::Ne, 2),
                (b'<', b'=') => (TK::Le, 2),
                (b'>', b'=') => (TK::Ge, 2),
                _ => (TK::EOF, 1), // placeholder
            }
        } else { (TK::EOF, 1) };
        if kind != TK::EOF {
            tokens.push(Tok { kind, text: src[i..i+len].to_string(), line });
            i += len;
            continue;
        }
        let kind = match c {
            b'<' => TK::Lt, b'>' => TK::Gt, b'=' => TK::Assign,
            b'+' => TK::Plus, b'-' => TK::Minus, b'*' => TK::Star,
            b'/' => TK::Slash, b'%' => TK::Percent,
            b'(' => TK::LP, b')' => TK::RP, b'[' => TK::LB, b']' => TK::RB,
            b'{' => TK::LC, b'}' => TK::RC, b',' => TK::Comma, b';' => TK::Semi,
            _ => { i += 1; continue; }
        };
        tokens.push(Tok { kind, text: (c as char).to_string(), line });
        i += 1;
    }
    tokens.push(Tok { kind: TK::EOF, text: String::new(), line });
    tokens
}

// ===== AST =====
#[derive(Debug, Clone, Copy, PartialEq)]
enum BOP { Add, Sub, Mul, Div, Mod, Eq, Ne, Lt, Le, Gt, Ge, And, Or }

#[derive(Debug, Clone)]
enum Expr {
    IntLit(i64),
    StrLit(String),
    BoolLit(bool),
    NilLit,
    Ident(String, usize),
    BinOp(BOP, Box<Expr>, Box<Expr>, usize),
    Not(Box<Expr>, usize),
    Neg(Box<Expr>, usize),
    Call(Box<Expr>, Vec<Expr>, usize),
    Index(Box<Expr>, Box<Expr>, usize),
    ListLit(Vec<Expr>),
    FnLit(Vec<String>, Vec<Stmt>),
}

#[derive(Debug, Clone)]
enum ElseB { Block(Vec<Stmt>), If(Stmt) }

#[derive(Debug, Clone)]
enum Stmt {
    Let(String, Expr, usize),
    FnDecl(String, Vec<String>, Vec<Stmt>, usize),
    If(Expr, Vec<Stmt>, Option<ElseB>, usize),
    While(Expr, Vec<Stmt>, usize),
    For(String, Expr, Vec<Stmt>, usize),
    Ret(Option<Expr>, usize),
    Brk(usize),
    Cont(usize),
    Assign(String, Expr, usize),
    IndexAssign(Box<Expr>, Box<Expr>, Expr, usize),
    ExprStmt(Expr),
}

// ===== Values =====
#[derive(Clone)]
enum Val {
    Int(i64),
    Bool(bool),
    Str(Rc<String>),
    List(Rc<RefCell<Vec<Val>>>),
    Func(Rc<FuncVal>),
    Nil,
}

struct FuncVal {
    params: Vec<String>,
    body: Vec<Stmt>,
    scope: Rc<RefCell<Scope>>,
    builtin: Option<BuiltinInfo>,
}

struct BuiltinInfo { name: &'static str, arity: Option<usize> }

struct Scope {
    vars: HashMap<String, Val>,
    parent: Option<Rc<RefCell<Scope>>>,
}

struct ErrInfo { line: usize, msg: String }
enum CF { Normal, Break, Continue, Ret(Val) }

// ===== Parser =====
struct Parser { toks: Vec<Tok>, pos: usize }

impl Parser {
    fn new(toks: Vec<Tok>) -> Self { Parser { toks, pos: 0 } }
    fn peek(&self) -> &Tok { &self.toks[self.pos] }
    fn peek2(&self) -> &Tok { &self.toks[if self.pos+1 < self.toks.len() { self.pos+1 } else { self.toks.len()-1 }] }
    fn advance(&mut self) -> Tok { let t = self.toks[self.pos].clone(); self.pos += 1; t }
    fn at(&self, k: TK) -> bool { self.peek().kind == k }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut v = Vec::new();
        while !self.at(TK::EOF) { v.push(self.parse_stmt()); }
        v
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.advance(); // {
        let mut v = Vec::new();
        while !self.at(TK::RC) && !self.at(TK::EOF) { v.push(self.parse_stmt()); }
        self.advance(); // }
        v
    }

    fn parse_params(&mut self) -> Vec<String> {
        let mut v = Vec::new();
        if !self.at(TK::RP) {
            v.push(self.advance().text);
            while self.at(TK::Comma) { self.advance(); v.push(self.advance().text); }
        }
        v
    }

    fn parse_stmt(&mut self) -> Stmt {
        match self.peek().kind {
            TK::Let => {
                self.advance();
                let name = self.advance().text;
                self.advance(); // =
                let expr = self.parse_expr();
                self.advance(); // ;
                Stmt::Let(name, expr, 0)
            }
            TK::Fn => {
                self.advance();
                let name = self.advance().text;
                self.advance(); // (
                let params = self.parse_params();
                self.advance(); // )
                let body = self.parse_block();
                Stmt::FnDecl(name, params, body, 0)
            }
            TK::If => {
                let line = self.peek().line;
                self.advance();
                let cond = self.parse_expr();
                let then_b = self.parse_block();
                let else_b = if self.at(TK::Else) {
                    self.advance();
                    if self.at(TK::If) { Some(ElseB::If(self.parse_stmt())) }
                    else { Some(ElseB::Block(self.parse_block())) }
                } else { None };
                Stmt::If(cond, then_b, else_b, line)
            }
            TK::While => {
                let line = self.peek().line;
                self.advance();
                let cond = self.parse_expr();
                let body = self.parse_block();
                Stmt::While(cond, body, line)
            }
            TK::For => {
                let line = self.peek().line;
                self.advance();
                let var = self.advance().text;
                self.advance(); // in
                let iter = self.parse_expr();
                let body = self.parse_block();
                Stmt::For(var, iter, body, line)
            }
            TK::Return => {
                let line = self.peek().line;
                self.advance();
                let expr = if self.at(TK::Semi) { None } else { Some(self.parse_expr()) };
                self.advance(); // ;
                Stmt::Ret(expr, line)
            }
            TK::Break => { let l = self.peek().line; self.advance(); self.advance(); Stmt::Brk(l) }
            TK::Continue => { let l = self.peek().line; self.advance(); self.advance(); Stmt::Cont(l) }
            TK::Ident if self.peek2().kind == TK::Assign => {
                let line = self.peek().line;
                let name = self.advance().text;
                self.advance(); // =
                let expr = self.parse_expr();
                self.advance(); // ;
                Stmt::Assign(name, expr, line)
            }
            _ => {
                let expr = self.parse_expr();
                if self.at(TK::Assign) {
                    let line = self.peek().line;
                    self.advance(); // =
                    let val = self.parse_expr();
                    self.advance(); // ;
                    // expr should be Index(obj, idx, line)
                    match expr {
                        Expr::Index(obj, idx, _) => Stmt::IndexAssign(obj, idx, val, line),
                        _ => Stmt::ExprStmt(val), // shouldn't happen
                    }
                } else {
                    self.advance(); // ;
                    Stmt::ExprStmt(expr)
                }
            }
        }
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }

    fn parse_or(&mut self) -> Expr {
        let mut left = self.parse_and();
        while self.at(TK::Or) {
            let line = self.peek().line;
            self.advance();
            let right = self.parse_and();
            left = Expr::BinOp(BOP::Or, Box::new(left), Box::new(right), line);
        }
        left
    }

    fn parse_and(&mut self) -> Expr {
        let mut left = self.parse_not();
        while self.at(TK::And) {
            let line = self.peek().line;
            self.advance();
            let right = self.parse_not();
            left = Expr::BinOp(BOP::And, Box::new(left), Box::new(right), line);
        }
        left
    }

    fn parse_not(&mut self) -> Expr {
        if self.at(TK::Not) {
            let line = self.peek().line;
            self.advance();
            let inner = self.parse_not();
            Expr::Not(Box::new(inner), line)
        } else {
            self.parse_cmp()
        }
    }

    fn parse_cmp(&mut self) -> Expr {
        let mut left = self.parse_add();
        loop {
            let (op, line) = match self.peek().kind {
                TK::Eq => (BOP::Eq, self.peek().line),
                TK::Ne => (BOP::Ne, self.peek().line),
                TK::Lt => (BOP::Lt, self.peek().line),
                TK::Le => (BOP::Le, self.peek().line),
                TK::Gt => (BOP::Gt, self.peek().line),
                TK::Ge => (BOP::Ge, self.peek().line),
                _ => break,
            };
            self.advance();
            let right = self.parse_add();
            left = Expr::BinOp(op, Box::new(left), Box::new(right), line);
        }
        left
    }

    fn parse_add(&mut self) -> Expr {
        let mut left = self.parse_mul();
        loop {
            let (op, line) = match self.peek().kind {
                TK::Plus => (BOP::Add, self.peek().line),
                TK::Minus => (BOP::Sub, self.peek().line),
                _ => break,
            };
            self.advance();
            let right = self.parse_mul();
            left = Expr::BinOp(op, Box::new(left), Box::new(right), line);
        }
        left
    }

    fn parse_mul(&mut self) -> Expr {
        let mut left = self.parse_neg();
        loop {
            let (op, line) = match self.peek().kind {
                TK::Star => (BOP::Mul, self.peek().line),
                TK::Slash => (BOP::Div, self.peek().line),
                TK::Percent => (BOP::Mod, self.peek().line),
                _ => break,
            };
            self.advance();
            let right = self.parse_neg();
            left = Expr::BinOp(op, Box::new(left), Box::new(right), line);
        }
        left
    }

    fn parse_neg(&mut self) -> Expr {
        if self.at(TK::Minus) {
            let line = self.peek().line;
            self.advance();
            let inner = self.parse_neg();
            Expr::Neg(Box::new(inner), line)
        } else {
            self.parse_postfix()
        }
    }

    fn parse_postfix(&mut self) -> Expr {
        let mut expr = self.parse_primary();
        loop {
            if self.at(TK::LP) {
                let line = self.peek().line;
                self.advance(); // (
                let mut args = Vec::new();
                if !self.at(TK::RP) {
                    args.push(self.parse_expr());
                    while self.at(TK::Comma) { self.advance(); args.push(self.parse_expr()); }
                }
                self.advance(); // )
                expr = Expr::Call(Box::new(expr), args, line);
            } else if self.at(TK::LB) {
                let line = self.peek().line;
                self.advance(); // [
                let idx = self.parse_expr();
                self.advance(); // ]
                expr = Expr::Index(Box::new(expr), Box::new(idx), line);
            } else {
                break;
            }
        }
        expr
    }

    fn parse_primary(&mut self) -> Expr {
        match self.peek().kind {
            TK::Int => { let t = self.advance(); Expr::IntLit(t.text.parse::<i64>().unwrap()) }
            TK::Str => { let t = self.advance(); Expr::StrLit(t.text) }
            TK::True => { self.advance(); Expr::BoolLit(true) }
            TK::False => { self.advance(); Expr::BoolLit(false) }
            TK::Nil => { self.advance(); Expr::NilLit }
            TK::Ident => { let t = self.advance(); Expr::Ident(t.text, t.line) }
            TK::LP => {
                self.advance(); // (
                let e = self.parse_expr();
                self.advance(); // )
                e
            }
            TK::LB => {
                self.advance(); // [
                let mut items = Vec::new();
                if !self.at(TK::RB) {
                    items.push(self.parse_expr());
                    while self.at(TK::Comma) { self.advance(); items.push(self.parse_expr()); }
                }
                self.advance(); // ]
                Expr::ListLit(items)
            }
            TK::Fn => {
                self.advance(); // fn
                self.advance(); // (
                let params = self.parse_params();
                self.advance(); // )
                let body = self.parse_block();
                Expr::FnLit(params, body)
            }
            _ => { self.advance(); Expr::NilLit }
        }
    }
}

// ===== Interpreter =====
struct Interp { out: String }

fn type_name(v: &Val) -> &'static str {
    match v {
        Val::Int(_) => "int", Val::Bool(_) => "bool", Val::Str(_) => "string",
        Val::List(_) => "list", Val::Func(_) => "function", Val::Nil => "nil",
    }
}

fn truthy(v: &Val) -> bool {
    match v {
        Val::Bool(b) => *b,
        Val::Nil => false,
        Val::Int(i) => *i != 0,
        Val::Str(s) => !s.is_empty(),
        Val::List(l) => !l.borrow().is_empty(),
        Val::Func(_) => true,
    }
}

fn escape_str(s: &str) -> String {
    let mut r = String::new();
    for c in s.chars() {
        match c {
            '\\' => r.push_str("\\\\"),
            '"' => r.push_str("\\\""),
            '\n' => r.push_str("\\n"),
            '\t' => r.push_str("\\t"),
            _ => r.push(c),
        }
    }
    r
}

impl Interp {
    fn new() -> Self { Interp { out: String::new() } }

    fn display(&self, v: &Val, in_list: bool, anc: &mut Vec<usize>) -> String {
        match v {
            Val::Int(n) => n.to_string(),
            Val::Bool(b) => if *b { "true" } else { "false" }.to_string(),
            Val::Nil => "nil".to_string(),
            Val::Func(_) => "<fn>".to_string(),
            Val::Str(s) => {
                if in_list { format!("\"{}\"", escape_str(s)) } else { s.as_str().to_string() }
            }
            Val::List(items) => {
                let ptr = Rc::as_ptr(items) as usize;
                if anc.contains(&ptr) { return "[...]".to_string(); }
                anc.push(ptr);
                let parts: Vec<String> = items.borrow().iter().map(|v| self.display(v, true, anc)).collect();
                anc.pop();
                format!("[{}]", parts.join(", "))
            }
        }
    }

    fn display_val(&self, v: &Val) -> String {
        self.display(v, false, &mut Vec::new())
    }

    fn lookup(&self, name: &str, scope: &Rc<RefCell<Scope>>) -> Option<Val> {
        let s = scope.borrow();
        if let Some(v) = s.vars.get(name) { return Some(v.clone()); }
        if let Some(ref p) = s.parent { let p = p.clone(); drop(s); return self.lookup(name, &p); }
        None
    }

    fn assign_var(&self, name: &str, val: Val, scope: &Rc<RefCell<Scope>>) -> Result<(), ()> {
        let s = scope.borrow();
        if s.vars.contains_key(name) {
            drop(s);
            scope.borrow_mut().vars.insert(name.to_string(), val);
            return Ok(());
        }
        if let Some(ref p) = s.parent {
            let p = p.clone();
            drop(s);
            return self.assign_var(name, val, &p);
        }
        drop(s);
        Err(())
    }

    fn eval(&mut self, e: &Expr, scope: &Rc<RefCell<Scope>>) -> Result<Val, ErrInfo> {
        match e {
            Expr::IntLit(n) => Ok(Val::Int(*n)),
            Expr::StrLit(s) => Ok(Val::Str(Rc::new(s.clone()))),
            Expr::BoolLit(b) => Ok(Val::Bool(*b)),
            Expr::NilLit => Ok(Val::Nil),
            Expr::Ident(name, line) => {
                self.lookup(name, scope).ok_or_else(|| ErrInfo { line: *line, msg: format!("undefined variable {}", name) })
            }
            Expr::BinOp(op, left, right, line) => {
                match op {
                    BOP::And => {
                        let l = self.eval(left, scope)?;
                        if !truthy(&l) { Ok(l) } else { self.eval(right, scope) }
                    }
                    BOP::Or => {
                        let l = self.eval(left, scope)?;
                        if truthy(&l) { Ok(l) } else { self.eval(right, scope) }
                    }
                    _ => {
                        let l = self.eval(left, scope)?;
                        let r = self.eval(right, scope)?;
                        self.apply_binop(*op, &l, &r, *line)
                    }
                }
            }
            Expr::Not(inner, line) => {
                let v = self.eval(inner, scope)?;
                Ok(Val::Bool(!truthy(&v)))
            }
            Expr::Neg(inner, line) => {
                let v = self.eval(inner, scope)?;
                match v {
                    Val::Int(n) => {
                        if n == i64::MIN { return Err(ErrInfo { line: *line, msg: "integer overflow".into() }); }
                        Ok(Val::Int(-n))
                    }
                    ref other => Err(ErrInfo { line: *line, msg: format!("cannot apply - to {}", type_name(other)) }),
                }
            }
            Expr::Call(callee, args, line) => {
                let cv = self.eval(callee, scope)?;
                let mut arg_vals = Vec::with_capacity(args.len());
                for a in args { arg_vals.push(self.eval(a, scope)?); }
                self.call_func(cv, arg_vals, *line)
            }
            Expr::Index(obj, idx, line) => {
                let ov = self.eval(obj, scope)?;
                let iv = self.eval(idx, scope)?;
                self.index_read(&ov, &iv, *line)
            }
            Expr::ListLit(items) => {
                let mut vals = Vec::with_capacity(items.len());
                for it in items { vals.push(self.eval(it, scope)?); }
                Ok(Val::List(Rc::new(RefCell::new(vals))))
            }
            Expr::FnLit(params, body) => {
                Ok(Val::Func(Rc::new(FuncVal {
                    params: params.clone(), body: body.clone(), scope: scope.clone(), builtin: None,
                })))
            }
        }
    }

    fn apply_binop(&mut self, op: BOP, l: &Val, r: &Val, line: usize) -> Result<Val, ErrInfo> {
        match op {
            BOP::Add => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => a.checked_add(*b).map(Val::Int).ok_or(ErrInfo{line,msg:"integer overflow".into()}),
                    (Val::Str(a), Val::Str(b)) => Ok(Val::Str(Rc::new(format!("{}{}", a, b)))),
                    (Val::List(a), Val::List(b)) => {
                        let mut new_items: Vec<Val> = Vec::with_capacity(a.borrow().len() + b.borrow().len());
                        new_items.extend(a.borrow().iter().cloned());
                        new_items.extend(b.borrow().iter().cloned());
                        Ok(Val::List(Rc::new(RefCell::new(new_items))))
                    }
                    _ => Err(ErrInfo { line, msg: format!("cannot apply + to {} and {}", type_name(l), type_name(r)) }),
                }
            }
            BOP::Sub => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => a.checked_sub(*b).map(Val::Int).ok_or(ErrInfo{line,msg:"integer overflow".into()}),
                    _ => Err(ErrInfo { line, msg: format!("cannot apply - to {} and {}", type_name(l), type_name(r)) }),
                }
            }
            BOP::Mul => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => a.checked_mul(*b).map(Val::Int).ok_or(ErrInfo{line,msg:"integer overflow".into()}),
                    _ => Err(ErrInfo { line, msg: format!("cannot apply * to {} and {}", type_name(l), type_name(r)) }),
                }
            }
            BOP::Div => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => {
                        if *b == 0 { return Err(ErrInfo { line, msg: "division by zero".into() }); }
                        if *a == i64::MIN && *b == -1 { return Err(ErrInfo { line, msg: "integer overflow".into() }); }
                        Ok(Val::Int(a / b))
                    }
                    _ => Err(ErrInfo { line, msg: format!("cannot apply / to {} and {}", type_name(l), type_name(r)) }),
                }
            }
            BOP::Mod => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => {
                        if *b == 0 { return Err(ErrInfo { line, msg: "division by zero".into() }); }
                        if *b == -1 { return Ok(Val::Int(0)); }
                        Ok(Val::Int(a % b))
                    }
                    _ => Err(ErrInfo { line, msg: format!("cannot apply % to {} and {}", type_name(l), type_name(r)) }),
                }
            }
            BOP::Eq => Ok(Val::Bool(self.val_eq(l, r))),
            BOP::Ne => Ok(Val::Bool(!self.val_eq(l, r))),
            BOP::Lt | BOP::Le | BOP::Gt | BOP::Ge => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => {
                        let ord = a.cmp(b);
                        Ok(Val::Bool(match op {
                            BOP::Lt => ord == std::cmp::Ordering::Less,
                            BOP::Le => ord != std::cmp::Ordering::Greater,
                            BOP::Gt => ord == std::cmp::Ordering::Greater,
                            _ => ord != std::cmp::Ordering::Less,
                        }))
                    }
                    (Val::Str(a), Val::Str(b)) => {
                        let ord = a.as_bytes().cmp(b.as_bytes());
                        Ok(Val::Bool(match op {
                            BOP::Lt => ord == std::cmp::Ordering::Less,
                            BOP::Le => ord != std::cmp::Ordering::Greater,
                            BOP::Gt => ord == std::cmp::Ordering::Greater,
                            _ => ord != std::cmp::Ordering::Less,
                        }))
                    }
                    _ => {
                        let op_str = match op { BOP::Lt => "<", BOP::Le => "<=", BOP::Gt => ">", _ => ">=" };
                        Err(ErrInfo { line, msg: format!("cannot apply {} to {} and {}", op_str, type_name(l), type_name(r)) })
                    }
                }
            }
            BOP::And | BOP::Or => unreachable!(),
        }
    }

    fn val_eq(&self, a: &Val, b: &Val) -> bool {
        match (a, b) {
            (Val::Int(x), Val::Int(y)) => x == y,
            (Val::Bool(x), Val::Bool(y)) => x == y,
            (Val::Str(x), Val::Str(y)) => x == y,
            (Val::Nil, Val::Nil) => true,
            (Val::List(x), Val::List(y)) => {
                if Rc::ptr_eq(x, y) { return true; }
                let xa = x.borrow();
                let yb = y.borrow();
                if xa.len() != yb.len() { return false; }
                for (i, j) in xa.iter().zip(yb.iter()) {
                    if !self.val_eq(i, j) { return false; }
                }
                true
            }
            (Val::Func(x), Val::Func(y)) => Rc::ptr_eq(x, y),
            _ => false,
        }
    }

    fn index_read(&self, obj: &Val, idx: &Val, line: usize) -> Result<Val, ErrInfo> {
        match obj {
            Val::List(items) => {
                match idx {
                    Val::Int(i) => {
                        let len = items.borrow().len() as i64;
                        if *i < 0 || *i >= len {
                            return Err(ErrInfo { line, msg: format!("index {} out of range for length {}", i, len) });
                        }
                        Ok(items.borrow()[*i as usize].clone())
                    }
                    other => Err(ErrInfo { line, msg: format!("cannot index list with {}", type_name(other)) }),
                }
            }
            Val::Str(s) => {
                match idx {
                    Val::Int(i) => {
                        let len = s.len() as i64;
                        if *i < 0 || *i >= len {
                            return Err(ErrInfo { line, msg: format!("index {} out of range for length {}", i, len) });
                        }
                        Ok(Val::Str(Rc::new(vec![s.as_bytes()[*i as usize]].into_iter().map(|b| b as char).collect::<String>())))
                    }
                    other => Err(ErrInfo { line, msg: format!("cannot index string with {}", type_name(other)) }),
                }
            }
            other => Err(ErrInfo { line, msg: format!("cannot index {} with {}", type_name(other), type_name(idx)) }),
        }
    }

    fn index_write(&self, obj: &Val, idx: &Val, val: Val, line: usize) -> Result<(), ErrInfo> {
        match obj {
            Val::List(items) => {
                match idx {
                    Val::Int(i) => {
                        let len = items.borrow().len() as i64;
                        if *i < 0 || *i >= len {
                            return Err(ErrInfo { line, msg: format!("index {} out of range for length {}", i, len) });
                        }
                        items.borrow_mut()[*i as usize] = val;
                        Ok(())
                    }
                    other => Err(ErrInfo { line, msg: format!("cannot index list with {}", type_name(other)) }),
                }
            }
            other => Err(ErrInfo { line, msg: format!("cannot assign into {}", type_name(other)) }),
        }
    }

    fn call_func(&mut self, func: Val, args: Vec<Val>, line: usize) -> Result<Val, ErrInfo> {
        match func {
            Val::Func(fv) => {
                if let Some(ref bi) = fv.builtin {
                    if let Some(expected) = bi.arity {
                        if args.len() != expected {
                            return Err(ErrInfo { line, msg: format!("expected {} arguments, got {}", expected, args.len()) });
                        }
                    }
                    self.call_builtin(bi.name, args, line)
                } else {
                    if args.len() != fv.params.len() {
                        return Err(ErrInfo { line, msg: format!("expected {} arguments, got {}", fv.params.len(), args.len()) });
                    }
                    let mut vars = HashMap::new();
                    for (p, a) in fv.params.iter().zip(args.into_iter()) {
                        vars.insert(p.clone(), a);
                    }
                    let call_scope = Rc::new(RefCell::new(Scope { vars, parent: Some(fv.scope.clone()) }));
                    match self.exec_block(&fv.body, &call_scope) {
                        Ok(CF::Ret(v)) => Ok(v),
                        Ok(_) => Ok(Val::Nil),
                        Err(e) => Err(e),
                    }
                }
            }
            ref other => Err(ErrInfo { line, msg: format!("cannot call {}", type_name(other)) }),
        }
    }

    fn call_builtin(&mut self, name: &str, args: Vec<Val>, line: usize) -> Result<Val, ErrInfo> {
        match name {
            "print" => {
                let parts: Vec<String> = args.iter().map(|v| self.display_val(v)).collect();
                self.out.push_str(&parts.join(" "));
                self.out.push('\n');
                Ok(Val::Nil)
            }
            "str" => Ok(Val::Str(Rc::new(self.display_val(&args[0])))),
            "type" => Ok(Val::Str(Rc::new(type_name(&args[0]).to_string()))),
            "len" => {
                match &args[0] {
                    Val::Str(s) => Ok(Val::Int(s.len() as i64)),
                    Val::List(l) => Ok(Val::Int(l.borrow().len() as i64)),
                    _ => Err(ErrInfo { line, msg: format!("bad argument to {}", name) }),
                }
            }
            "push" => {
                match &args[0] {
                    Val::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Val::Nil) }
                    _ => Err(ErrInfo { line, msg: format!("bad argument to {}", name) }),
                }
            }
            "pop" => {
                match &args[0] {
                    Val::List(l) => {
                        let mut items = l.borrow_mut();
                        if items.is_empty() { return Err(ErrInfo { line, msg: format!("bad argument to {}", name) }); }
                        Ok(items.pop().unwrap())
                    }
                    _ => Err(ErrInfo { line, msg: format!("bad argument to {}", name) }),
                }
            }
            "range" => {
                match (&args[0], &args[1]) {
                    (Val::Int(a), Val::Int(b)) => {
                        let mut v = Vec::new();
                        let mut i = *a;
                        while i < *b { v.push(Val::Int(i)); i += 1; }
                        Ok(Val::List(Rc::new(RefCell::new(v))))
                    }
                    _ => Err(ErrInfo { line, msg: format!("bad argument to {}", name) }),
                }
            }
            "slice" => {
                match (&args[0], &args[1], &args[2]) {
                    (Val::Str(s), Val::Int(a), Val::Int(b)) => {
                        let a = *a as usize; let b = *b as usize;
                        if a > b || b > s.len() { return Err(ErrInfo { line, msg: format!("bad argument to {}", name) }); }
                        Ok(Val::Str(Rc::new(s[a..b].to_string())))
                    }
                    (Val::List(l), Val::Int(a), Val::Int(b)) => {
                        let a = *a as usize; let b = *b as usize;
                        let items = l.borrow();
                        if a > b || b > items.len() { return Err(ErrInfo { line, msg: format!("bad argument to {}", name) }); }
                        Ok(Val::List(Rc::new(RefCell::new(items[a..b].to_vec()))))
                    }
                    _ => Err(ErrInfo { line, msg: format!("bad argument to {}", name) }),
                }
            }
            _ => unreachable!(),
        }
    }

    fn exec_block(&mut self, stmts: &[Stmt], scope: &Rc<RefCell<Scope>>) -> Result<CF, ErrInfo> {
        for stmt in stmts {
            match self.exec_stmt(stmt, scope)? {
                CF::Normal => {},
                other => return Ok(other),
            }
        }
        Ok(CF::Normal)
    }

    fn exec_stmt(&mut self, stmt: &Stmt, scope: &Rc<RefCell<Scope>>) -> Result<CF, ErrInfo> {
        match stmt {
            Stmt::Let(name, expr, _line) => {
                let v = self.eval(expr, scope)?;
                scope.borrow_mut().vars.insert(name.clone(), v);
                Ok(CF::Normal)
            }
            Stmt::FnDecl(name, params, body, _line) => {
                let fv = Rc::new(FuncVal {
                    params: params.clone(), body: body.clone(), scope: scope.clone(), builtin: None,
                });
                scope.borrow_mut().vars.insert(name.clone(), Val::Func(fv));
                Ok(CF::Normal)
            }
            Stmt::If(cond, then_body, else_body, _line) => {
                let cv = self.eval(cond, scope)?;
                if truthy(&cv) {
                    let ns = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(scope.clone()) }));
                    self.exec_block(then_body, &ns)
                } else {
                    match else_body {
                        Some(ElseB::Block(body)) => {
                            let ns = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(scope.clone()) }));
                            self.exec_block(body, &ns)
                        }
                        Some(ElseB::If(s)) => self.exec_stmt(s, scope),
                        None => Ok(CF::Normal),
                    }
                }
            }
            Stmt::While(cond, body, _line) => {
                loop {
                    let cv = self.eval(cond, scope)?;
                    if !truthy(&cv) { break; }
                    let ns = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(scope.clone()) }));
                    match self.exec_block(body, &ns)? {
                        CF::Normal => {},
                        CF::Break => break,
                        CF::Continue => {},
                        CF::Ret(v) => return Ok(CF::Ret(v)),
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::For(var, iter, body, line) => {
                let list_val = self.eval(iter, scope)?;
                match &list_val {
                    Val::List(items) => {
                        let mut i: usize = 0;
                        loop {
                            let len = items.borrow().len();
                            if i >= len { break; }
                            let elem = items.borrow()[i].clone();
                            let mut vars = HashMap::new();
                            vars.insert(var.clone(), elem);
                            let ns = Rc::new(RefCell::new(Scope { vars, parent: Some(scope.clone()) }));
                            match self.exec_block(body, &ns)? {
                                CF::Normal => {},
                                CF::Break => break,
                                CF::Continue => {},
                                CF::Ret(v) => return Ok(CF::Ret(v)),
                            }
                            i += 1;
                        }
                        Ok(CF::Normal)
                    }
                    other => Err(ErrInfo { line: *line, msg: format!("cannot iterate {}", type_name(other)) }),
                }
            }
            Stmt::Ret(expr, _line) => {
                let v = match expr {
                    Some(e) => self.eval(e, scope)?,
                    None => Val::Nil,
                };
                Ok(CF::Ret(v))
            }
            Stmt::Brk(_) => Ok(CF::Break),
            Stmt::Cont(_) => Ok(CF::Continue),
            Stmt::Assign(name, expr, line) => {
                let v = self.eval(expr, scope)?;
                self.assign_var(name, v, scope).map_err(|_| ErrInfo { line: *line, msg: format!("undefined variable {}", name) })?;
                Ok(CF::Normal)
            }
            Stmt::IndexAssign(obj, idx, val, line) => {
                let ov = self.eval(obj, scope)?;
                let iv = self.eval(idx, scope)?;
                let vv = self.eval(val, scope)?;
                self.index_write(&ov, &iv, vv, *line)?;
                Ok(CF::Normal)
            }
            Stmt::ExprStmt(expr) => {
                self.eval(expr, scope)?;
                Ok(CF::Normal)
            }
        }
    }
}

fn make_builtins() -> Scope {
    let mut vars = HashMap::new();
    let builtins: Vec<(&str, Option<usize>)> = vec![
        ("print", None), ("str", Some(1)), ("type", Some(1)),
        ("len", Some(1)), ("push", Some(2)), ("pop", Some(1)),
        ("range", Some(2)), ("slice", Some(3)),
    ];
    for (name, arity) in builtins {
        vars.insert(name.to_string(), Val::Func(Rc::new(FuncVal {
            params: vec![],
            body: vec![],
            scope: Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: None })),
            builtin: Some(BuiltinInfo { name, arity }),
        })));
    }
    Scope { vars, parent: None }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { process::exit(1); }
    let dir = &args[1];
    let path = format!("{}/program.tern", dir);
    let src = fs::read_to_string(&path).expect("cannot read program");

    let tokens = lex(&src);
    let mut parser = Parser::new(tokens);
    let program = parser.parse_program();

    let builtin_scope = Rc::new(RefCell::new(make_builtins()));
    let global_scope = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(builtin_scope) }));

    let mut interp = Interp::new();
    match interp.exec_block(&program, &global_scope) {
        Ok(_) => {},
        Err(e) => {
            interp.out.push_str(&format!("error at line {}: {}\n", e.line, e.msg));
        }
    }
    print!("{}", interp.out);
    process::exit(0);
}

use std::collections::HashMap;
use std::rc::Rc;
use std::cell::RefCell;
use std::env;
use std::fs;
use std::process;

// ===== Token =====
#[derive(Debug, Clone, PartialEq)]
enum TK {
    Int, Str, Ident,
    Let, Fn, If, Else, While, For, In, Return, Break, Continue,
    And, Or, Not, True, False, Nil,
    Eq, Ne, Le, Ge, Lt, Gt, Assign,
    Plus, Minus, Star, Slash, Percent,
    LP, RP, LB, RB, LC, RC, Comma, Semi,
    EOF,
}

#[derive(Debug, Clone)]
struct Tok { kind: TK, text: String, line: usize }

fn lex(src: &str) -> Vec<Tok> {
    let b = src.as_bytes();
    let mut tokens = Vec::new();
    let mut i = 0usize;
    let mut line = 1usize;
    while i < b.len() {
        let c = b[i];
        if c == b' ' || c == b'\t' || c == b'\r' { i += 1; continue; }
        if c == b'\n' { line += 1; i += 1; continue; }
        if c == b'#' { while i < b.len() && b[i] != b'\n' { i += 1; } continue; }
        if c.is_ascii_digit() {
            let s = i;
            while i < b.len() && b[i].is_ascii_digit() { i += 1; }
            tokens.push(Tok { kind: TK::Int, text: src[s..i].to_string(), line });
            continue;
        }
        if c == b'"' {
            i += 1;
            let mut s = String::new();
            while i < b.len() && b[i] != b'"' {
                if b[i] == b'\\' {
                    i += 1;
                    match b[i] {
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        _ => { s.push('\\'); s.push(b[i] as char); }
                    }
                } else {
                    s.push(b[i] as char);
                }
                i += 1;
            }
            i += 1; // closing "
            tokens.push(Tok { kind: TK::Str, text: s, line });
            continue;
        }
        if c.is_ascii_alphabetic() || c == b'_' {
            let s = i;
            while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_') { i += 1; }
            let text = &src[s..i];
            let kind = match text {
                "let" => TK::Let, "fn" => TK::Fn, "if" => TK::If, "else" => TK::Else,
                "while" => TK::While, "for" => TK::For, "in" => TK::In,
                "return" => TK::Return, "break" => TK::Break, "continue" => TK::Continue,
                "and" => TK::And, "or" => TK::Or, "not" => TK::Not,
                "true" => TK::True, "false" => TK::False, "nil" => TK::Nil,
                _ => TK::Ident,
            };
            tokens.push(Tok { kind, text: text.to_string(), line });
            continue;
        }
        // operators (longest match first)
        let (kind, len) = if i + 1 < b.len() {
            let two = (b[i], b[i+1]);
            match two {
                (b'=', b'=') => (TK::Eq, 2),
                (b'!', b'=') => (TK::Ne, 2),
                (b'<', b'=') => (TK::Le, 2),
                (b'>', b'=') => (TK::Ge, 2),
                _ => (TK::EOF, 1),
            }
        } else { (TK::EOF, 1) };
        if kind != TK::EOF {
            tokens.push(Tok { kind, text: src[i..i+len].to_string(), line });
            i += len;
            continue;
        }
        let kind = match c {
            b'<' => TK::Lt, b'>' => TK::Gt, b'=' => TK::Assign,
            b'+' => TK::Plus, b'-' => TK::Minus, b'*' => TK::Star,
            b'/' => TK::Slash, b'%' => TK::Percent,
            b'(' => TK::LP, b')' => TK::RP, b'[' => TK::LB, b']' => TK::RB,
            b'{' => TK::LC, b'}' => TK::RC, b',' => TK::Comma, b';' => TK::Semi,
            _ => { i += 1; continue; }
        };
        tokens.push(Tok { kind, text: (c as char).to_string(), line });
        i += 1;
    }
    tokens.push(Tok { kind: TK::EOF, text: String::new(), line });
    tokens
}

// ===== AST =====
#[derive(Debug, Clone, Copy, PartialEq)]
enum BOP { Add, Sub, Mul, Div, Mod, Eq, Ne, Lt, Le, Gt, Ge, And, Or }

#[derive(Debug, Clone)]
enum Expr {
    IntLit(i64),
    StrLit(String),
    BoolLit(bool),
    NilLit,
    Ident(String, usize),
    BinOp(BOP, Box<Expr>, Box<Expr>, usize),
    Not(Box<Expr>, usize),
    Neg(Box<Expr>, usize),
    Call(Box<Expr>, Vec<Expr>, usize),
    Index(Box<Expr>, Box<Expr>, usize),
    ListLit(Vec<Expr>),
    FnLit(Vec<String>, Vec<Stmt>),
}

#[derive(Debug, Clone)]
enum ElseB { Block(Vec<Stmt>), If(Box<Stmt>) }

#[derive(Debug, Clone)]
enum Stmt {
    Let(String, Expr, usize),
    FnDecl(String, Vec<String>, Vec<Stmt>, usize),
    If(Expr, Vec<Stmt>, Option<Box<ElseB>>, usize),
    While(Expr, Vec<Stmt>, usize),
    For(String, Expr, Vec<Stmt>, usize),
    Ret(Option<Expr>, usize),
    Brk(usize),
    Cont(usize),
    Assign(String, Expr, usize),
    IndexAssign(Box<Expr>, Box<Expr>, Expr, usize),
    ExprStmt(Expr),
}

// ===== Values =====
#[derive(Clone)]
enum Val {
    Int(i64),
    Bool(bool),
    Str(Rc<String>),
    List(Rc<RefCell<Vec<Val>>>),
    Func(Rc<FuncVal>),
    Nil,
}

struct FuncVal {
    params: Vec<String>,
    body: Vec<Stmt>,
    scope: Rc<RefCell<Scope>>,
    builtin: Option<BuiltinInfo>,
}

struct BuiltinInfo { name: &'static str, arity: Option<usize> }

struct Scope {
    vars: HashMap<String, Val>,
    parent: Option<Rc<RefCell<Scope>>>,
}

struct ErrInfo { line: usize, msg: String }
enum CF { Normal, Break, Continue, Ret(Val) }

// ===== Parser =====
struct Parser { toks: Vec<Tok>, pos: usize }

impl Parser {
    fn new(toks: Vec<Tok>) -> Self { Parser { toks, pos: 0 } }
    fn peek(&self) -> &Tok { &self.toks[self.pos] }
    fn peek2(&self) -> &Tok { &self.toks[if self.pos+1 < self.toks.len() { self.pos+1 } else { self.toks.len()-1 }] }
    fn advance(&mut self) -> Tok { let t = self.toks[self.pos].clone(); self.pos += 1; t }
    fn at(&self, k: TK) -> bool { self.peek().kind == k }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut v = Vec::new();
        while !self.at(TK::EOF) { v.push(self.parse_stmt()); }
        v
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.advance(); // {
        let mut v = Vec::new();
        while !self.at(TK::RC) && !self.at(TK::EOF) { v.push(self.parse_stmt()); }
        self.advance(); // }
        v
    }

    fn parse_params(&mut self) -> Vec<String> {
        let mut v = Vec::new();
        if !self.at(TK::RP) {
            v.push(self.advance().text);
            while self.at(TK::Comma) { self.advance(); v.push(self.advance().text); }
        }
        v
    }

    fn parse_stmt(&mut self) -> Stmt {
        match self.peek().kind {
            TK::Let => {
                self.advance();
                let name = self.advance().text;
                self.advance(); // =
                let expr = self.parse_expr();
                self.advance(); // ;
                Stmt::Let(name, expr, 0)
            }
            TK::Fn => {
                self.advance();
                let name = self.advance().text;
                self.advance(); // (
                let params = self.parse_params();
                self.advance(); // )
                let body = self.parse_block();
                Stmt::FnDecl(name, params, body, 0)
            }
            TK::If => {
                let line = self.peek().line;
                self.advance();
                let cond = self.parse_expr();
                let then_b = self.parse_block();
                let else_b = if self.at(TK::Else) {
                    self.advance();
                    if self.at(TK::If) { Some(Box::new(ElseB::If(Box::new(self.parse_stmt())))) }
                    else { Some(Box::new(ElseB::Block(self.parse_block()))) }
                } else { None };
                Stmt::If(cond, then_b, else_b, line)
            }
            TK::While => {
                let line = self.peek().line;
                self.advance();
                let cond = self.parse_expr();
                let body = self.parse_block();
                Stmt::While(cond, body, line)
            }
            TK::For => {
                let line = self.peek().line;
                self.advance();
                let var = self.advance().text;
                self.advance(); // in
                let iter = self.parse_expr();
                let body = self.parse_block();
                Stmt::For(var, iter, body, line)
            }
            TK::Return => {
                let line = self.peek().line;
                self.advance();
                let expr = if self.at(TK::Semi) { None } else { Some(self.parse_expr()) };
                self.advance(); // ;
                Stmt::Ret(expr, line)
            }
            TK::Break => { let l = self.peek().line; self.advance(); self.advance(); Stmt::Brk(l) }
            TK::Continue => { let l = self.peek().line; self.advance(); self.advance(); Stmt::Cont(l) }
            TK::Ident if self.peek2().kind == TK::Assign => {
                let line = self.peek().line;
                let name = self.advance().text;
                self.advance(); // =
                let expr = self.parse_expr();
                self.advance(); // ;
                Stmt::Assign(name, expr, line)
            }
            _ => {
                let expr = self.parse_expr();
                if self.at(TK::Assign) {
                    let line = self.peek().line;
                    self.advance(); // =
                    let val = self.parse_expr();
                    self.advance(); // ;
                    match expr {
                        Expr::Index(obj, idx, _) => Stmt::IndexAssign(obj, idx, val, line),
                        _ => Stmt::ExprStmt(val),
                    }
                } else {
                    self.advance(); // ;
                    Stmt::ExprStmt(expr)
                }
            }
        }
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }

    fn parse_or(&mut self) -> Expr {
        let mut left = self.parse_and();
        while self.at(TK::Or) {
            let line = self.peek().line;
            self.advance();
            let right = self.parse_and();
            left = Expr::BinOp(BOP::Or, Box::new(left), Box::new(right), line);
        }
        left
    }

    fn parse_and(&mut self) -> Expr {
        let mut left = self.parse_not();
        while self.at(TK::And) {
            let line = self.peek().line;
            self.advance();
            let right = self.parse_not();
            left = Expr::BinOp(BOP::And, Box::new(left), Box::new(right), line);
        }
        left
    }

    fn parse_not(&mut self) -> Expr {
        if self.at(TK::Not) {
            let line = self.peek().line;
            self.advance();
            let inner = self.parse_not();
            Expr::Not(Box::new(inner), line)
        } else {
            self.parse_cmp()
        }
    }

    fn parse_cmp(&mut self) -> Expr {
        let mut left = self.parse_add();
        loop {
            let (op, line) = match self.peek().kind {
                TK::Eq => (BOP::Eq, self.peek().line),
                TK::Ne => (BOP::Ne, self.peek().line),
                TK::Lt => (BOP::Lt, self.peek().line),
                TK::Le => (BOP::Le, self.peek().line),
                TK::Gt => (BOP::Gt, self.peek().line),
                TK::Ge => (BOP::Ge, self.peek().line),
                _ => break,
            };
            self.advance();
            let right = self.parse_add();
            left = Expr::BinOp(op, Box::new(left), Box::new(right), line);
        }
        left
    }

    fn parse_add(&mut self) -> Expr {
        let mut left = self.parse_mul();
        loop {
            let (op, line) = match self.peek().kind {
                TK::Plus => (BOP::Add, self.peek().line),
                TK::Minus => (BOP::Sub, self.peek().line),
                _ => break,
            };
            self.advance();
            let right = self.parse_mul();
            left = Expr::BinOp(op, Box::new(left), Box::new(right), line);
        }
        left
    }

    fn parse_mul(&mut self) -> Expr {
        let mut left = self.parse_neg();
        loop {
            let (op, line) = match self.peek().kind {
                TK::Star => (BOP::Mul, self.peek().line),
                TK::Slash => (BOP::Div, self.peek().line),
                TK::Percent => (BOP::Mod, self.peek().line),
                _ => break,
            };
            self.advance();
            let right = self.parse_neg();
            left = Expr::BinOp(op, Box::new(left), Box::new(right), line);
        }
        left
    }

    fn parse_neg(&mut self) -> Expr {
        if self.at(TK::Minus) {
            let line = self.peek().line;
            self.advance();
            let inner = self.parse_neg();
            Expr::Neg(Box::new(inner), line)
        } else {
            self.parse_postfix()
        }
    }

    fn parse_postfix(&mut self) -> Expr {
        let mut expr = self.parse_primary();
        loop {
            if self.at(TK::LP) {
                let line = self.peek().line;
                self.advance(); // (
                let mut args = Vec::new();
                if !self.at(TK::RP) {
                    args.push(self.parse_expr());
                    while self.at(TK::Comma) { self.advance(); args.push(self.parse_expr()); }
                }
                self.advance(); // )
                expr = Expr::Call(Box::new(expr), args, line);
            } else if self.at(TK::LB) {
                let line = self.peek().line;
                self.advance(); // [
                let idx = self.parse_expr();
                self.advance(); // ]
                expr = Expr::Index(Box::new(expr), Box::new(idx), line);
            } else {
                break;
            }
        }
        expr
    }

    fn parse_primary(&mut self) -> Expr {
        match self.peek().kind {
            TK::Int => { let t = self.advance(); Expr::IntLit(t.text.parse::<i64>().unwrap()) }
            TK::Str => { let t = self.advance(); Expr::StrLit(t.text) }
            TK::True => { self.advance(); Expr::BoolLit(true) }
            TK::False => { self.advance(); Expr::BoolLit(false) }
            TK::Nil => { self.advance(); Expr::NilLit }
            TK::Ident => { let t = self.advance(); Expr::Ident(t.text, t.line) }
            TK::LP => {
                self.advance(); // (
                let e = self.parse_expr();
                self.advance(); // )
                e
            }
            TK::LB => {
                self.advance(); // [
                let mut items = Vec::new();
                if !self.at(TK::RB) {
                    items.push(self.parse_expr());
                    while self.at(TK::Comma) { self.advance(); items.push(self.parse_expr()); }
                }
                self.advance(); // ]
                Expr::ListLit(items)
            }
            TK::Fn => {
                self.advance(); // fn
                self.advance(); // (
                let params = self.parse_params();
                self.advance(); // )
                let body = self.parse_block();
                Expr::FnLit(params, body)
            }
            _ => { self.advance(); Expr::NilLit }
        }
    }
}

// ===== Interpreter =====
struct Interp { out: String }

fn type_name(v: &Val) -> &'static str {
    match v {
        Val::Int(_) => "int", Val::Bool(_) => "bool", Val::Str(_) => "string",
        Val::List(_) => "list", Val::Func(_) => "function", Val::Nil => "nil",
    }
}

fn truthy(v: &Val) -> bool {
    match v {
        Val::Bool(b) => *b,
        Val::Nil => false,
        Val::Int(i) => *i != 0,
        Val::Str(s) => !s.is_empty(),
        Val::List(l) => !l.borrow().is_empty(),
        Val::Func(_) => true,
    }
}

fn escape_str(s: &str) -> String {
    let mut r = String::new();
    for c in s.chars() {
        match c {
            '\\' => r.push_str("\\\\"),
            '"' => r.push_str("\\\""),
            '\n' => r.push_str("\\n"),
            '\t' => r.push_str("\\t"),
            _ => r.push(c),
        }
    }
    r
}

impl Interp {
    fn new() -> Self { Interp { out: String::new() } }

    fn display(&self, v: &Val, in_list: bool, anc: &mut Vec<usize>) -> String {
        match v {
            Val::Int(n) => n.to_string(),
            Val::Bool(b) => if *b { "true" } else { "false" }.to_string(),
            Val::Nil => "nil".to_string(),
            Val::Func(_) => "<fn>".to_string(),
            Val::Str(s) => {
                if in_list { format!("\"{}\"", escape_str(s)) } else { s.as_str().to_string() }
            }
            Val::List(items) => {
                let ptr = Rc::as_ptr(items) as usize;
                if anc.contains(&ptr) { return "[...]".to_string(); }
                anc.push(ptr);
                let parts: Vec<String> = items.borrow().iter().map(|v| self.display(v, true, anc)).collect();
                anc.pop();
                format!("[{}]", parts.join(", "))
            }
        }
    }

    fn display_val(&self, v: &Val) -> String {
        self.display(v, false, &mut Vec::new())
    }

    fn lookup(&self, name: &str, scope: &Rc<RefCell<Scope>>) -> Option<Val> {
        let s = scope.borrow();
        if let Some(v) = s.vars.get(name) { return Some(v.clone()); }
        if let Some(ref p) = s.parent { let p = p.clone(); drop(s); return self.lookup(name, &p); }
        None
    }

    fn assign_var(&self, name: &str, val: Val, scope: &Rc<RefCell<Scope>>) -> Result<(), ()> {
        let s = scope.borrow();
        if s.vars.contains_key(name) {
            drop(s);
            scope.borrow_mut().vars.insert(name.to_string(), val);
            return Ok(());
        }
        if let Some(ref p) = s.parent {
            let p = p.clone();
            drop(s);
            return self.assign_var(name, val, &p);
        }
        drop(s);
        Err(())
    }

    fn eval(&mut self, e: &Expr, scope: &Rc<RefCell<Scope>>) -> Result<Val, ErrInfo> {
        match e {
            Expr::IntLit(n) => Ok(Val::Int(*n)),
            Expr::StrLit(s) => Ok(Val::Str(Rc::new(s.clone()))),
            Expr::BoolLit(b) => Ok(Val::Bool(*b)),
            Expr::NilLit => Ok(Val::Nil),
            Expr::Ident(name, line) => {
                self.lookup(name, scope).ok_or_else(|| ErrInfo { line: *line, msg: format!("undefined variable {}", name) })
            }
            Expr::BinOp(op, left, right, line) => {
                match op {
                    BOP::And => {
                        let l = self.eval(left, scope)?;
                        if !truthy(&l) { Ok(l) } else { self.eval(right, scope) }
                    }
                    BOP::Or => {
                        let l = self.eval(left, scope)?;
                        if truthy(&l) { Ok(l) } else { self.eval(right, scope) }
                    }
                    _ => {
                        let l = self.eval(left, scope)?;
                        let r = self.eval(right, scope)?;
                        self.apply_binop(*op, &l, &r, *line)
                    }
                }
            }
            Expr::Not(inner, line) => {
                let v = self.eval(inner, scope)?;
                Ok(Val::Bool(!truthy(&v)))
            }
            Expr::Neg(inner, line) => {
                let v = self.eval(inner, scope)?;
                match v {
                    Val::Int(n) => {
                        if n == i64::MIN { return Err(ErrInfo { line: *line, msg: "integer overflow".into() }); }
                        Ok(Val::Int(-n))
                    }
                    ref other => Err(ErrInfo { line: *line, msg: format!("cannot apply - to {}", type_name(other)) }),
                }
            }
            Expr::Call(callee, args, line) => {
                let cv = self.eval(callee, scope)?;
                let mut arg_vals = Vec::with_capacity(args.len());
                for a in args { arg_vals.push(self.eval(a, scope)?); }
                self.call_func(cv, arg_vals, *line)
            }
            Expr::Index(obj, idx, line) => {
                let ov = self.eval(obj, scope)?;
                let iv = self.eval(idx, scope)?;
                self.index_read(&ov, &iv, *line)
            }
            Expr::ListLit(items) => {
                let mut vals = Vec::with_capacity(items.len());
                for it in items { vals.push(self.eval(it, scope)?); }
                Ok(Val::List(Rc::new(RefCell::new(vals))))
            }
            Expr::FnLit(params, body) => {
                Ok(Val::Func(Rc::new(FuncVal {
                    params: params.clone(), body: body.clone(), scope: scope.clone(), builtin: None,
                })))
            }
        }
    }

    fn apply_binop(&mut self, op: BOP, l: &Val, r: &Val, line: usize) -> Result<Val, ErrInfo> {
        match op {
            BOP::Add => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => a.checked_add(*b).map(Val::Int).ok_or(ErrInfo{line,msg:"integer overflow".into()}),
                    (Val::Str(a), Val::Str(b)) => Ok(Val::Str(Rc::new(format!("{}{}", a, b)))),
                    (Val::List(a), Val::List(b)) => {
                        let mut new_items: Vec<Val> = Vec::with_capacity(a.borrow().len() + b.borrow().len());
                        new_items.extend(a.borrow().iter().cloned());
                        new_items.extend(b.borrow().iter().cloned());
                        Ok(Val::List(Rc::new(RefCell::new(new_items))))
                    }
                    _ => Err(ErrInfo { line, msg: format!("cannot apply + to {} and {}", type_name(l), type_name(r)) }),
                }
            }
            BOP::Sub => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => a.checked_sub(*b).map(Val::Int).ok_or(ErrInfo{line,msg:"integer overflow".into()}),
                    _ => Err(ErrInfo { line, msg: format!("cannot apply - to {} and {}", type_name(l), type_name(r)) }),
                }
            }
            BOP::Mul => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => a.checked_mul(*b).map(Val::Int).ok_or(ErrInfo{line,msg:"integer overflow".into()}),
                    _ => Err(ErrInfo { line, msg: format!("cannot apply * to {} and {}", type_name(l), type_name(r)) }),
                }
            }
            BOP::Div => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => {
                        if *b == 0 { return Err(ErrInfo { line, msg: "division by zero".into() }); }
                        if *a == i64::MIN && *b == -1 { return Err(ErrInfo { line, msg: "integer overflow".into() }); }
                        Ok(Val::Int(a / b))
                    }
                    _ => Err(ErrInfo { line, msg: format!("cannot apply / to {} and {}", type_name(l), type_name(r)) }),
                }
            }
            BOP::Mod => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => {
                        if *b == 0 { return Err(ErrInfo { line, msg: "division by zero".into() }); }
                        if *b == -1 { return Ok(Val::Int(0)); }
                        Ok(Val::Int(a % b))
                    }
                    _ => Err(ErrInfo { line, msg: format!("cannot apply % to {} and {}", type_name(l), type_name(r)) }),
                }
            }
            BOP::Eq => Ok(Val::Bool(self.val_eq(l, r))),
            BOP::Ne => Ok(Val::Bool(!self.val_eq(l, r))),
            BOP::Lt | BOP::Le | BOP::Gt | BOP::Ge => {
                match (l, r) {
                    (Val::Int(a), Val::Int(b)) => {
                        let ord = a.cmp(b);
                        Ok(Val::Bool(match op {
                            BOP::Lt => ord == std::cmp::Ordering::Less,
                            BOP::Le => ord != std::cmp::Ordering::Greater,
                            BOP::Gt => ord == std::cmp::Ordering::Greater,
                            _ => ord != std::cmp::Ordering::Less,
                        }))
                    }
                    (Val::Str(a), Val::Str(b)) => {
                        let ord = a.as_bytes().cmp(b.as_bytes());
                        Ok(Val::Bool(match op {
                            BOP::Lt => ord == std::cmp::Ordering::Less,
                            BOP::Le => ord != std::cmp::Ordering::Greater,
                            BOP::Gt => ord == std::cmp::Ordering::Greater,
                            _ => ord != std::cmp::Ordering::Less,
                        }))
                    }
                    _ => {
                        let op_str = match op { BOP::Lt => "<", BOP::Le => "<=", BOP::Gt => ">", _ => ">=" };
                        Err(ErrInfo { line, msg: format!("cannot apply {} to {} and {}", op_str, type_name(l), type_name(r)) })
                    }
                }
            }
            BOP::And | BOP::Or => unreachable!(),
        }
    }

    fn val_eq(&self, a: &Val, b: &Val) -> bool {
        match (a, b) {
            (Val::Int(x), Val::Int(y)) => x == y,
            (Val::Bool(x), Val::Bool(y)) => x == y,
            (Val::Str(x), Val::Str(y)) => x == y,
            (Val::Nil, Val::Nil) => true,
            (Val::List(x), Val::List(y)) => {
                if Rc::ptr_eq(x, y) { return true; }
                let xa = x.borrow();
                let yb = y.borrow();
                if xa.len() != yb.len() { return false; }
                for (i, j) in xa.iter().zip(yb.iter()) {
                    if !self.val_eq(i, j) { return false; }
                }
                true
            }
            (Val::Func(x), Val::Func(y)) => Rc::ptr_eq(x, y),
            _ => false,
        }
    }

    fn index_read(&self, obj: &Val, idx: &Val, line: usize) -> Result<Val, ErrInfo> {
        match obj {
            Val::List(items) => {
                match idx {
                    Val::Int(i) => {
                        let len = items.borrow().len() as i64;
                        if *i < 0 || *i >= len {
                            return Err(ErrInfo { line, msg: format!("index {} out of range for length {}", i, len) });
                        }
                        Ok(items.borrow()[*i as usize].clone())
                    }
                    other => Err(ErrInfo { line, msg: format!("cannot index list with {}", type_name(other)) }),
                }
            }
            Val::Str(s) => {
                match idx {
                    Val::Int(i) => {
                        let len = s.len() as i64;
                        if *i < 0 || *i >= len {
                            return Err(ErrInfo { line, msg: format!("index {} out of range for length {}", i, len) });
                        }
                        Ok(Val::Str(Rc::new(vec![s.as_bytes()[*i as usize]].into_iter().map(|b| b as char).collect::<String>())))
                    }
                    other => Err(ErrInfo { line, msg: format!("cannot index string with {}", type_name(other)) }),
                }
            }
            other => Err(ErrInfo { line, msg: format!("cannot index {} with {}", type_name(other), type_name(idx)) }),
        }
    }

    fn index_write(&self, obj: &Val, idx: &Val, val: Val, line: usize) -> Result<(), ErrInfo> {
        match obj {
            Val::List(items) => {
                match idx {
                    Val::Int(i) => {
                        let len = items.borrow().len() as i64;
                        if *i < 0 || *i >= len {
                            return Err(ErrInfo { line, msg: format!("index {} out of range for length {}", i, len) });
                        }
                        items.borrow_mut()[*i as usize] = val;
                        Ok(())
                    }
                    other => Err(ErrInfo { line, msg: format!("cannot index list with {}", type_name(other)) }),
                }
            }
            other => Err(ErrInfo { line, msg: format!("cannot assign into {}", type_name(other)) }),
        }
    }

    fn call_func(&mut self, func: Val, args: Vec<Val>, line: usize) -> Result<Val, ErrInfo> {
        match func {
            Val::Func(fv) => {
                if let Some(ref bi) = fv.builtin {
                    if let Some(expected) = bi.arity {
                        if args.len() != expected {
                            return Err(ErrInfo { line, msg: format!("expected {} arguments, got {}", expected, args.len()) });
                        }
                    }
                    self.call_builtin(bi.name, args, line)
                } else {
                    if args.len() != fv.params.len() {
                        return Err(ErrInfo { line, msg: format!("expected {} arguments, got {}", fv.params.len(), args.len()) });
                    }
                    let mut vars = HashMap::new();
                    for (p, a) in fv.params.iter().zip(args.into_iter()) {
                        vars.insert(p.clone(), a);
                    }
                    let call_scope = Rc::new(RefCell::new(Scope { vars, parent: Some(fv.scope.clone()) }));
                    match self.exec_block(&fv.body, &call_scope) {
                        Ok(CF::Ret(v)) => Ok(v),
                        Ok(_) => Ok(Val::Nil),
                        Err(e) => Err(e),
                    }
                }
            }
            ref other => Err(ErrInfo { line, msg: format!("cannot call {}", type_name(other)) }),
        }
    }

    fn call_builtin(&mut self, name: &str, args: Vec<Val>, line: usize) -> Result<Val, ErrInfo> {
        match name {
            "print" => {
                let parts: Vec<String> = args.iter().map(|v| self.display_val(v)).collect();
                self.out.push_str(&parts.join(" "));
                self.out.push('\n');
                Ok(Val::Nil)
            }
            "str" => Ok(Val::Str(Rc::new(self.display_val(&args[0])))),
            "type" => Ok(Val::Str(Rc::new(type_name(&args[0]).to_string()))),
            "len" => {
                match &args[0] {
                    Val::Str(s) => Ok(Val::Int(s.len() as i64)),
                    Val::List(l) => Ok(Val::Int(l.borrow().len() as i64)),
                    _ => Err(ErrInfo { line, msg: format!("bad argument to {}", name) }),
                }
            }
            "push" => {
                match &args[0] {
                    Val::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Val::Nil) }
                    _ => Err(ErrInfo { line, msg: format!("bad argument to {}", name) }),
                }
            }
            "pop" => {
                match &args[0] {
                    Val::List(l) => {
                        let mut items = l.borrow_mut();
                        if items.is_empty() { return Err(ErrInfo { line, msg: format!("bad argument to {}", name) }); }
                        Ok(items.pop().unwrap())
                    }
                    _ => Err(ErrInfo { line, msg: format!("bad argument to {}", name) }),
                }
            }
            "range" => {
                match (&args[0], &args[1]) {
                    (Val::Int(a), Val::Int(b)) => {
                        let mut v = Vec::new();
                        let mut i = *a;
                        while i < *b { v.push(Val::Int(i)); i += 1; }
                        Ok(Val::List(Rc::new(RefCell::new(v))))
                    }
                    _ => Err(ErrInfo { line, msg: format!("bad argument to {}", name) }),
                }
            }
            "slice" => {
                match (&args[0], &args[1], &args[2]) {
                    (Val::Str(s), Val::Int(a), Val::Int(b)) => {
                        let a = *a as usize; let b = *b as usize;
                        if a > b || b > s.len() { return Err(ErrInfo { line, msg: format!("bad argument to {}", name) }); }
                        Ok(Val::Str(Rc::new(s[a..b].to_string())))
                    }
                    (Val::List(l), Val::Int(a), Val::Int(b)) => {
                        let a = *a as usize; let b = *b as usize;
                        let items = l.borrow();
                        if a > b || b > items.len() { return Err(ErrInfo { line, msg: format!("bad argument to {}", name) }); }
                        Ok(Val::List(Rc::new(RefCell::new(items[a..b].to_vec()))))
                    }
                    _ => Err(ErrInfo { line, msg: format!("bad argument to {}", name) }),
                }
            }
            _ => unreachable!(),
        }
    }

    fn exec_block(&mut self, stmts: &[Stmt], scope: &Rc<RefCell<Scope>>) -> Result<CF, ErrInfo> {
        for stmt in stmts {
            match self.exec_stmt(stmt, scope)? {
                CF::Normal => {},
                other => return Ok(other),
            }
        }
        Ok(CF::Normal)
    }

    fn exec_stmt(&mut self, stmt: &Stmt, scope: &Rc<RefCell<Scope>>) -> Result<CF, ErrInfo> {
        match stmt {
            Stmt::Let(name, expr, _line) => {
                let v = self.eval(expr, scope)?;
                scope.borrow_mut().vars.insert(name.clone(), v);
                Ok(CF::Normal)
            }
            Stmt::FnDecl(name, params, body, _line) => {
                let fv = Rc::new(FuncVal {
                    params: params.clone(), body: body.clone(), scope: scope.clone(), builtin: None,
                });
                scope.borrow_mut().vars.insert(name.clone(), Val::Func(fv));
                Ok(CF::Normal)
            }
            Stmt::If(cond, then_body, else_body, _line) => {
                let cv = self.eval(cond, scope)?;
                if truthy(&cv) {
                    let ns = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(scope.clone()) }));
                    self.exec_block(then_body, &ns)
                } else {
                    match else_body {
                        Some(b) => match **b {
                            ElseB::Block(ref body) => {
                                let ns = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(scope.clone()) }));
                                self.exec_block(body, &ns)
                            }
                            ElseB::If(ref s) => self.exec_stmt(s, scope),
                        },
                        None => Ok(CF::Normal),
                    }
                }
            }
            Stmt::While(cond, body, _line) => {
                loop {
                    let cv = self.eval(cond, scope)?;
                    if !truthy(&cv) { break; }
                    let ns = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(scope.clone()) }));
                    match self.exec_block(body, &ns)? {
                        CF::Normal => {},
                        CF::Break => break,
                        CF::Continue => {},
                        CF::Ret(v) => return Ok(CF::Ret(v)),
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::For(var, iter, body, line) => {
                let list_val = self.eval(iter, scope)?;
                match &list_val {
                    Val::List(items) => {
                        let mut i: usize = 0;
                        loop {
                            let len = items.borrow().len();
                            if i >= len { break; }
                            let elem = items.borrow()[i].clone();
                            let mut vars = HashMap::new();
                            vars.insert(var.clone(), elem);
                            let ns = Rc::new(RefCell::new(Scope { vars, parent: Some(scope.clone()) }));
                            match self.exec_block(body, &ns)? {
                                CF::Normal => {},
                                CF::Break => break,
                                CF::Continue => {},
                                CF::Ret(v) => return Ok(CF::Ret(v)),
                            }
                            i += 1;
                        }
                        Ok(CF::Normal)
                    }
                    other => Err(ErrInfo { line: *line, msg: format!("cannot iterate {}", type_name(other)) }),
                }
            }
            Stmt::Ret(expr, _line) => {
                let v = match expr {
                    Some(e) => self.eval(e, scope)?,
                    None => Val::Nil,
                };
                Ok(CF::Ret(v))
            }
            Stmt::Brk(_) => Ok(CF::Break),
            Stmt::Cont(_) => Ok(CF::Continue),
            Stmt::Assign(name, expr, line) => {
                let v = self.eval(expr, scope)?;
                self.assign_var(name, v, scope).map_err(|_| ErrInfo { line: *line, msg: format!("undefined variable {}", name) })?;
                Ok(CF::Normal)
            }
            Stmt::IndexAssign(obj, idx, val, line) => {
                let ov = self.eval(obj, scope)?;
                let iv = self.eval(idx, scope)?;
                let vv = self.eval(val, scope)?;
                self.index_write(&ov, &iv, vv, *line)?;
                Ok(CF::Normal)
            }
            Stmt::ExprStmt(expr) => {
                self.eval(expr, scope)?;
                Ok(CF::Normal)
            }
        }
    }
}

fn make_builtins() -> Scope {
    let mut vars = HashMap::new();
    let builtins: Vec<(&str, Option<usize>)> = vec![
        ("print", None), ("str", Some(1)), ("type", Some(1)),
        ("len", Some(1)), ("push", Some(2)), ("pop", Some(1)),
        ("range", Some(2)), ("slice", Some(3)),
    ];
    for (name, arity) in builtins {
        vars.insert(name.to_string(), Val::Func(Rc::new(FuncVal {
            params: vec![],
            body: vec![],
            scope: Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: None })),
            builtin: Some(BuiltinInfo { name, arity }),
        })));
    }
    Scope { vars, parent: None }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { process::exit(1); }
    let dir = &args[1];
    let path = format!("{}/program.tern", dir);
    let src = fs::read_to_string(&path).expect("cannot read program");

    let tokens = lex(&src);
    let mut parser = Parser::new(tokens);
    let program = parser.parse_program();

    let builtin_scope = Rc::new(RefCell::new(make_builtins()));
    let global_scope = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(builtin_scope) }));

    let mut interp = Interp::new();
    match interp.exec_block(&program, &global_scope) {
        Ok(_) => {},
        Err(e) => {
            interp.out.push_str(&format!("error at line {}: {}\n", e.line, e.msg));
        }
    }
    print!("{}", interp.out);
    process::exit(0);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdarg.h>

typedef struct Value Value;
typedef struct List List;
typedef struct Func Func;
typedef struct Scope Scope;
typedef struct ASTNode ASTNode;

typedef enum { T_INT, T_BOOL, T_STRING, T_LIST, T_FUNC, T_NIL } VType;

struct List { Value *items; int len, cap; };
struct Func { char **params; int nparams; ASTNode **body; int nbody; Scope *captured; int builtin_id; };
struct Value { VType type; union { int64_t ival; bool bval; struct{char*data;int len;}sval; List*lval; Func*fval; }; };

typedef struct { char *name; Value val; } Binding;
struct Scope { Scope *parent; Binding *bindings; int n, cap; };

typedef enum { AST_INT,AST_STR,AST_BOOL,AST_NIL,AST_VAR,AST_ASSIGN,AST_IDX_ASSIGN,
    AST_LET,AST_FN_DEF,AST_FN_LIT,AST_IF,AST_WHILE,AST_FOR,AST_RETURN,AST_BREAK,AST_CONTINUE,
    AST_BINOP,AST_UNOP,AST_CALL,AST_INDEX,AST_LISTLIT } ASTType;
enum {OP_ADD,OP_SUB,OP_MUL,OP_DIV,OP_MOD,OP_EQ,OP_NE,OP_LT,OP_LE,OP_GT,OP_GE,OP_AND,OP_OR};
enum {UN_NEG,UN_NOT};

struct ASTNode {
    ASTType type; int line;
    union {
        int64_t ival;
        struct{char*data;int len;}sval;
        char *name;
        struct{ASTNode*l,*r;int op;}bin;
        struct{ASTNode*operand;int op;}un;
        struct{ASTNode*callee;ASTNode**args;int nargs;}call;
        struct{ASTNode*obj,*idx;}index;
        struct{ASTNode**elems;int nelems;}list_lit;
        struct{ASTNode*cond;ASTNode**then_body;int n_then;ASTNode**else_body;int n_else;}if_node;
        struct{ASTNode*cond;ASTNode**body;int nbody;}while_node;
        struct{char*var;ASTNode*iter;ASTNode**body;int nbody;}for_node;
        struct{ASTNode*expr;}ret;
        struct{char**params;int nparams;ASTNode**body;int nbody;char*name;}fn;
        struct{ASTNode*obj,*idx,*val;}idx_assign;
    };
};

typedef enum {
    TK_INT,TK_STR,TK_IDENT,TK_FN,TK_LET,TK_IF,TK_ELSE,TK_WHILE,TK_FOR,TK_IN,
    TK_RETURN,TK_BREAK,TK_CONTINUE,TK_AND,TK_OR,TK_NOT,TK_TRUE,TK_FALSE,TK_NIL,
    TK_LPAREN,TK_RPAREN,TK_LBRACKET,TK_RBRACKET,TK_LBRACE,TK_RBRACE,
    TK_COMMA,TK_SEMI,TK_ASSIGN,TK_EQ,TK_NE,TK_LT,TK_LE,TK_GT,TK_GE,
    TK_PLUS,TK_MINUS,TK_STAR,TK_SLASH,TK_PERCENT,TK_EOF
} TokType;

typedef struct { TokType type; int64_t ival; char*sdata; int slen; int line; } Token;

static Token *tokens; static int ntok, tok_cap, tok_pos;
static Scope *global_scope;
typedef enum {CF_NORMAL,CF_BREAK,CF_CONTINUE,CF_RETURN} CF;
static CF cf; static Value return_val;
static List *disp_stack[512]; static int disp_len;

static void die(int line, const char *fmt, ...) {
    va_list ap; printf("error at line %d: ",line);
    va_start(ap,fmt); vprintf(fmt,ap); va_end(ap);
    printf("\n"); fflush(stdout); exit(0);
}

static const char *tname(VType t){
    switch(t){case T_INT:return"int";case T_BOOL:return"bool";case T_STRING:return"string";
    case T_LIST:return"list";case T_FUNC:return"function";case T_NIL:return"nil";}return"?";
}
static const char *opname(int op){
    switch(op){case OP_ADD:return"+";case OP_SUB:return"-";case OP_MUL:return"*";
    case OP_DIV:return"/";case OP_MOD:return"%";case OP_EQ:return"==";case OP_NE:return"!=";
    case OP_LT:return"<";case OP_LE:return"<=";case OP_GT:return">";case OP_GE:return">=";}return"?";
}

static void*xm(size_t n){void*p=malloc(n);if(!p)exit(1);return p;}
static void*xr(void*p,size_t n){void*q=realloc(p,n);if(!q)exit(1);return q;}

/* ===== Lexer ===== */
static char *src; static int slen,spos,cur_line;
static void tok_add(TokType t,int line){
    if(ntok>=tok_cap){tok_cap=tok_cap?tok_cap*2:256;tokens=xr(tokens,tok_cap*sizeof(Token));}
    tokens[ntok].type=t;tokens[ntok].line=line;tokens[ntok].ival=0;tokens[ntok].sdata=NULL;tokens[ntok].slen=0;ntok++;
}
static void tok_add_int(int64_t v,int line){tok_add(TK_INT,line);tokens[ntok-1].ival=v;}
static void tok_add_str(char*d,int l,int line){tok_add(TK_STR,line);tokens[ntok-1].sdata=d;tokens[ntok-1].slen=l;}
static void tok_add_id(char*d,int l,int line){tok_add(TK_IDENT,line);tokens[ntok-1].sdata=d;tokens[ntok-1].slen=l;}

static void tokenize(void){
    cur_line=1;spos=0;
    while(spos<slen){
        char c=src[spos];
        if(c==' '||c=='\t'||c=='\r'){spos++;continue;}
        if(c=='\n'){cur_line++;spos++;continue;}
        if(c=='#'){while(spos<slen&&src[spos]!='\n')spos++;continue;}
        int line=cur_line;
        if(c>='0'&&c<='9'){
            int64_t v=0;while(spos<slen&&src[spos]>='0'&&src[spos]<='9'){v=v*10+(src[spos]-'0');spos++;}
            tok_add_int(v,line);continue;
        }
        if(c=='"'){
            spos++;int cap=16,len=0;char*buf=xm(cap);
            while(spos<slen&&src[spos]!='"'){
                if(src[spos]=='\\'&&spos+1<slen){
                    spos++;char e=src[spos];spos++;
                    char r=e;
                    if(e=='n')r='\n';else if(e=='t')r='\t';else if(e=='"')r='"';else if(e=='\\')r='\\';
                    if(len>=cap){cap*=2;buf=xr(buf,cap);}buf[len++]=r;
                } else {
                    if(len>=cap){cap*=2;buf=xr(buf,cap);}buf[len++]=src[spos];spos++;
                }
            }
            if(spos<slen)spos++;/* skip closing " */
            tok_add_str(buf,len,line);continue;
        }
        if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||c=='_'){
            int st=spos;while(spos<slen&&((src[spos]>='a'&&src[spos]<='z')||(src[spos]>='A'&&src[spos]<='Z')||(src[spos]>='0'&&src[spos]<='9')||src[spos]=='_'))spos++;
            int l=spos-st;char*id=xm(l+1);memcpy(id,src+st,l);id[l]=0;
            TokType t=TK_IDENT;
            if(!strcmp(id,"fn"))t=TK_FN;else if(!strcmp(id,"let"))t=TK_LET;
            else if(!strcmp(id,"if"))t=TK_IF;else if(!strcmp(id,"else"))t=TK_ELSE;
            else if(!strcmp(id,"while"))t=TK_WHILE;else if(!strcmp(id,"for"))t=TK_FOR;
            else if(!strcmp(id,"in"))t=TK_IN;else if(!strcmp(id,"return"))t=TK_RETURN;
            else if(!strcmp(id,"break"))t=TK_BREAK;else if(!strcmp(id,"continue"))t=TK_CONTINUE;
            else if(!strcmp(id,"and"))t=TK_AND;else if(!strcmp(id,"or"))t=TK_OR;
            else if(!strcmp(id,"not"))t=TK_NOT;else if(!strcmp(id,"true"))t=TK_TRUE;
            else if(!strcmp(id,"false"))t=TK_FALSE;else if(!strcmp(id,"nil"))t=TK_NIL;
            if(t!=TK_IDENT){tok_add(t,line);}
            else tok_add_id(id,l,line);
            continue;
        }
        spos++;
        switch(c){
            case '(':tok_add(TK_LPAREN,line);break;case ')':tok_add(TK_RPAREN,line);break;
            case '[':tok_add(TK_LBRACKET,line);break;case ']':tok_add(TK_RBRACKET,line);break;
            case '{':tok_add(TK_LBRACE,line);break;case '}':tok_add(TK_RBRACE,line);break;
            case ',':tok_add(TK_COMMA,line);break;case ';':tok_add(TK_SEMI,line);break;
            case '+':tok_add(TK_PLUS,line);break;case '-':tok_add(TK_MINUS,line);break;
            case '*':tok_add(TK_STAR,line);break;case '/':tok_add(TK_SLASH,line);break;
            case '%':tok_add(TK_PERCENT,line);break;
            case '=':if(spos<slen&&src[spos]=='='){spos++;tok_add(TK_EQ,line);}else tok_add(TK_ASSIGN,line);break;
            case '!':if(spos<slen&&src[spos]=='='){spos++;tok_add(TK_NE,line);}else tok_add(TK_NOT,line);break;
            case '<':if(spos<slen&&src[spos]=='='){spos++;tok_add(TK_LE,line);}else tok_add(TK_LT,line);break;
            case '>':if(spos<slen&&src[spos]=='='){spos++;tok_add(TK_GE,line);}else tok_add(TK_GT,line);break;
            default:break;
        }
    }
    tok_add(TK_EOF,cur_line);
}

/* ===== Parser ===== */
static Token*cur(void){return&tokens[tok_pos];}
static TokType ct(void){return tokens[tok_pos].type;}
static TokType consume(void){return tokens[tok_pos++].type;}
static void expect(TokType t){if(ct()==t)tok_pos++;else die(tokens[tok_pos].line,"syntax error");}

static ASTNode*nnew(ASTType t){ASTNode*n=xm(sizeof(ASTNode));memset(n,0,sizeof(ASTNode));n->type=t;n->line=tokens[tok_pos].line;return n;}

static ASTNode**parse_block(int*np){
    expect(TK_LBRACE);
    int cap=8,n=0;ASTNode**stmts=xm(cap*sizeof(ASTNode*));
    while(ct()!=TK_RBRACE&&ct()!=TK_EOF){
        if(n>=cap){cap*=2;stmts=xr(stmts,cap*sizeof(ASTNode*));}
        stmts[n++]=parse_stmt();
    }
    expect(TK_RBRACE);*np=n;return stmts;
}

static ASTNode*parse_expr(void);
static ASTNode*parse_primary(void);

static ASTNode*parse_primary(void){
    Token*t=cur();int line=t->line;
    switch(t->type){
        case TK_INT:{ASTNode*n=nnew(AST_INT);n->line=line;n->ival=t->ival;tok_pos++;return n;}
        case TK_STR:{ASTNode*n=nnew(AST_STR);n->line=line;n->sval.data=t->sdata;n->sval.slen=t->slen;tok_pos++;return n;}
        case TK_TRUE:{ASTNode*n=nnew(AST_BOOL);n->line=line;n->ival=1;tok_pos++;return n;}
        case TK_FALSE:{ASTNode*n=nnew(AST_BOOL);n->line=line;n->ival=0;tok_pos++;return n;}
        case TK_NIL:{ASTNode*n=nnew(AST_NIL);n->line=line;tok_pos++;return n;}
        case TK_IDENT:{ASTNode*n=nnew(AST_VAR);n->line=line;n->name=t->sdata;tok_pos++;return n;}
        case TK_LPAREN:{tok_pos++;ASTNode*e=parse_expr();expect(TK_RPAREN);return e;}
        case TK_LBRACKET:{
            int line2=t->line;tok_pos++;
            int cap=8,n=0;ASTNode**elems=NULL;
            if(ct()!=TK_RBRACKET){
                elems=xm(cap*sizeof(ASTNode*));elems[n++]=parse_expr();
                while(ct()==TK_COMMA){tok_pos++;if(n>=cap){cap*=2;elems=xr(elems,cap*sizeof(ASTNode*));}elems[n++]=parse_expr();}
            }
            expect(TK_RBRACKET);
            ASTNode*nd=nnew(AST_LISTLIT);nd->line=line2;nd->list_lit.elems=elems;nd->list_lit.nelems=n;return nd;
        }
        case TK_FN:{
            int fnline=t->line;tok_pos++;expect(TK_LPAREN);
            char**params=NULL;int np=0,cap=4;
            if(ct()!=TK_RPAREN){
                params=xm(cap*sizeof(char*));
                params[np++]=cur()->sdata;tok_pos++;
                while(ct()==TK_COMMA){tok_pos++;if(np>=cap){cap*=2;params=xr(params,cap*sizeof(char*));}params[np++]=cur()->sdata;tok_pos++;}
            }
            expect(TK_RPAREN);
            int nb;ASTNode**body=parse_block(&nb);
            ASTNode*nd=nnew(AST_FN_LIT);nd->line=fnline;nd->fn.params=params;nd->fn.nparams=np;nd->fn.body=body;nd->fn.nbody=nb;nd->fn.name=NULL;
            return nd;
        }
        default:die(line,"syntax error");return NULL;
    }
}

static ASTNode*parse_postfix(void){
    ASTNode*e=parse_primary();
    while(1){
        if(ct()==TK_LPAREN){
            int line=cur()->line;tok_pos++;
            int cap=4,n=0;ASTNode**args=NULL;
            if(ct()!=TK_RPAREN){
                args=xm(cap*sizeof(ASTNode*));args[n++]=parse_expr();
                while(ct()==TK_COMMA){tok_pos++;if(n>=cap){cap*=2;args=xr(args,cap*sizeof(ASTNode*));}args[n++]=parse_expr();}
            }
            expect(TK_RPAREN);
            ASTNode*nd=nnew(AST_CALL);nd->line=line;nd->call.callee=e;nd->call.args=args;nd->call.nargs=n;e=nd;
        } else if(ct()==TK_LBRACKET){
            int line=cur()->line;tok_pos++;ASTNode*idx=parse_expr();expect(TK_RBRACKET);
            ASTNode*nd=nnew(AST_INDEX);nd->line=line;nd->index.obj=e;nd->index.idx=idx;e=nd;
        } else break;
    }
    return e;
}

static ASTNode*parse_unary(void){
    if(ct()==TK_MINUS){int line=cur()->line;tok_pos++;ASTNode*e=parse_unary();ASTNode*n=nnew(AST_UNOP);n->line=line;n->un.operand=e;n->un.op=UN_NEG;return n;}
    return parse_postfix();
}
static ASTNode*parse_mul(void){
    ASTNode*l=parse_unary();
    while(ct()==TK_STAR||ct()==TK_SLASH||ct()==TK_PERCENT){
        int op=ct()==TK_STAR?OP_MUL:ct()==TK_SLASH?OP_DIV:OP_MOD;int line=cur()->line;tok_pos++;
        ASTNode*r=parse_unary();ASTNode*n=nnew(AST_BINOP);n->line=line;n->bin.l=l;n->bin.r=r;n->bin.op=op;l=n;
    }
    return l;
}
static ASTNode*parse_add(void){
    ASTNode*l=parse_mul();
    while(ct()==TK_PLUS||ct()==TK_MINUS){
        int op=ct()==TK_PLUS?OP_ADD:OP_SUB;int line=cur()->line;tok_pos++;
        ASTNode*r=parse_mul();ASTNode*n=nnew(AST_BINOP);n->line=line;n->bin.l=l;n->bin.r=r;n->bin.op=op;l=n;
    }
    return l;
}
static ASTNode*parse_cmp(void){
    ASTNode*l=parse_add();
    while(ct()==TK_EQ||ct()==TK_NE||ct()==TK_LT||ct()==TK_LE||ct()==TK_GT||ct()==TK_GE){
        int op;switch(ct()){case TK_EQ:op=OP_EQ;break;case TK_NE:op=OP_NE;break;case TK_LT:op=OP_LT;break;
            case TK_LE:op=OP_LE;break;case TK_GT:op=OP_GT;break;default:op=OP_GE;break;}
        int line=cur()->line;tok_pos++;
        ASTNode*r=parse_add();ASTNode*n=nnew(AST_BINOP);n->line=line;n->bin.l=l;n->bin.r=r;n->bin.op=op;l=n;
    }
    return l;
}
static ASTNode*parse_not(void){
    if(ct()==TK_NOT){int line=cur()->line;tok_pos++;ASTNode*e=parse_not();ASTNode*n=nnew(AST_UNOP);n->line=line;n->un.operand=e;n->un.op=UN_NOT;return n;}
    return parse_cmp();
}
static ASTNode*parse_and(void){
    ASTNode*l=parse_not();
    while(ct()==TK_AND){int line=cur()->line;tok_pos++;ASTNode*r=parse_not();ASTNode*n=nnew(AST_BINOP);n->line=line;n->bin.l=l;n->bin.r=r;n->bin.op=OP_AND;l=n;}
    return l;
}
static ASTNode*parse_or(void){
    ASTNode*l=parse_and();
    while(ct()==TK_OR){int line=cur()->line;tok_pos++;ASTNode*r=parse_and();ASTNode*n=nnew(AST_BINOP);n->line=line;n->bin.l=l;n->bin.r=r;n->bin.op=OP_OR;l=n;}
    return l;
}
static ASTNode*parse_expr(void){return parse_or();}

static ASTNode*parse_stmt(void){
    Token*t=cur();int line=t->line;
    switch(t->type){
        case TK_LET:{
            tok_pos++;char*name=cur()->sdata;int nline=cur()->line;tok_pos++;expect(TK_ASSIGN);
            ASTNode*val=parse_expr();expect(TK_SEMI);
            ASTNode*n=nnew(AST_LET);n->line=nline;n->name=name;n->bin.r=val;return n;
        }
        case TK_FN:{
            tok_pos++;char*name=cur()->sdata;int nline=cur()->line;tok_pos++;expect(TK_LPAREN);
            char**params=NULL;int np=0,cap=4;
            if(ct()!=TK_RPAREN){
                params=xm(cap*sizeof(char*));params[np++]=cur()->sdata;tok_pos++;
                while(ct()==TK_COMMA){tok_pos++;if(np>=cap){cap*=2;params=xr(params,cap*sizeof(char*));}params[np++]=cur()->sdata;tok_pos++;}
            }
            expect(TK_RPAREN);int nb;ASTNode**body=parse_block(&nb);
            ASTNode*n=nnew(AST_FN_DEF);n->line=nline;n->fn.params=params;n->fn.nparams=np;n->fn.body=body;n->fn.nbody=nb;n->fn.name=name;
            return n;
        }
        case TK_IF:{
            int ifline=t->line;tok_pos++;ASTNode*cond=parse_expr();
            int nt;ASTNode**tb=parse_block(&nt);
            ASTNode**eb=NULL;int ne=0;
            if(ct()==TK_ELSE){
                tok_pos++;
                if(ct()==TK_IF){ASTNode**tmp=xm(sizeof(ASTNode*));tmp[0]=parse_stmt();eb=tmp;ne=1;}
                else{eb=parse_block(&ne);}
            }
            ASTNode*n=nnew(AST_IF);n->line=ifline;n->if_node.cond=cond;n->if_node.then_body=tb;n->if_node.n_then=nt;
            n->if_node.else_body=eb;n->if_node.n_else=ne;return n;
        }
        case TK_WHILE:{
            int wline=t->line;tok_pos++;ASTNode*cond=parse_expr();int nb;ASTNode**body=parse_block(&nb);
            ASTNode*n=nnew(AST_WHILE);n->line=wline;n->while_node.cond=cond;n->while_node.body=body;n->while_node.nbody=nb;return n;
        }
        case TK_FOR:{
            int fline=t->line;tok_pos++;char*var=cur()->sdata;tok_pos++;expect(TK_IN);ASTNode*iter=parse_expr();
            int nb;ASTNode**body=parse_block(&nb);
            ASTNode*n=nnew(AST_FOR);n->line=fline;n->for_node.var=var;n->for_node.iter=iter;n->for_node.body=body;n->for_node.nbody=nb;return n;
        }
        case TK_RETURN:{
            tok_pos++;ASTNode*expr=NULL;if(ct()!=TK_SEMI)expr=parse_expr();expect(TK_SEMI);
            ASTNode*n=nnew(AST_RETURN);n->line=line;n->ret.expr=expr;return n;
        }
        case TK_BREAK:{tok_pos++;expect(TK_SEMI);ASTNode*n=nnew(AST_BREAK);n->line=line;return n;}
        case TK_CONTINUE:{tok_pos++;expect(TK_SEMI);ASTNode*n=nnew(AST_CONTINUE);n->line=line;return n;}
        case TK_IDENT:{
            if(tokens[tok_pos+1].type==TK_ASSIGN){
                char*name=t->sdata;tok_pos+=2;ASTNode*val=parse_expr();expect(TK_SEMI);
                ASTNode*n=nnew(AST_ASSIGN);n->line=line;n->name=name;n->bin.r=val;return n;
            }
            /* fall through to expression */
        }
        /* fall through */
        default:{
            ASTNode*e=parse_expr();
            if(ct()==TK_ASSIGN){
                tok_pos++;ASTNode*val=parse_expr();expect(TK_SEMI);
                ASTNode*n=nnew(AST_IDX_ASSIGN);n->line=e->line;n->idx_assign.obj=e->index.obj;n->idx_assign.idx=e->index.idx;n->idx_assign.val=val;
                return n;
            }
            expect(TK_SEMI);return e;
        }
    }
}

/* ===== Scope ===== */
static Scope*scope_new(Scope*parent){Scope*s=xm(sizeof(Scope));s->parent=parent;s->bindings=NULL;s->n=0;s->cap=0;return s;}
static void scope_bind(Scope*s,const char*name,Value v){
    if(s->n>=s->cap){s->cap=s->cap?s->cap*2:8;s->bindings=xr(s->bindings,s->cap*sizeof(Binding));}
    s->bindings[s->n].name=(char*)name;s->bindings[s->n].val=v;s->n++;
}
static Value*scope_lookup(Scope*s,const char*name){
    while(s){for(int i=s->n-1;i>=0;i--)if(!strcmp(s->bindings[i].name,name))return&s->bindings[i].val;s=s->parent;}
    return NULL;
}

/* ===== Value helpers ===== */
static Value mk_int(int64_t v){Value r;r.type=T_INT;r.ival=v;return r;}
static Value mk_bool(bool v){Value r;r.type=T_BOOL;r.bval=v;return r;}
static Value mk_nil(void){Value r;r.type=T_NIL;return r;}
static Value mk_str(const char*d,int len){Value r;r.type=T_STRING;r.sval.data=(char*)d;r.sval.len=len;return r;}
static Value mk_list(List*l){Value r;r.type=T_LIST;r.lval=l;return r;}
static Value mk_func(Func*f){Value r;r.type=T_FUNC;r.fval=f;return r;}

static List*list_new(void){List*l=xm(sizeof(List));l->items=NULL;l->len=0;l->cap=0;return l;}
static void list_push(List*l,Value v){
    if(l->len>=l->cap){l->cap=l->cap?l->cap*2:4;l->items=xr(l->items,l->cap*sizeof(Value));}
    l->items[l->len++]=v;
}

static bool truthy(Value v){
    switch(v.type){
        case T_BOOL:return v.bval;
        case T_INT:return v.ival!=0;
        case T_STRING:return v.sval.len!=0;
        case T_LIST:return v.lval->len!=0;
        case T_NIL:return false;
        case T_FUNC:return true;
    }
    return false;
}

/* ===== Display ===== */
typedef struct{char*data;int len,cap;}Buf;
static void buf_init(Buf*b){b->data=NULL;b->len=0;b->cap=0;}
static void buf_putc(Buf*b,char c){if(b->len>=b->cap){b->cap=b->cap?b->cap*2:64;b->data=xr(b->data,b->cap);}b->data[b->len++]=c;}
static void buf_puts(Buf*b,const char*s){while(*s)buf_putc(b,*s++);}
static void buf_putn(Buf*b,const char*s,int n){for(int i=0;i<n;i++)buf_putc(b,s[i]);}
static void buf_int(Buf*b,int64_t v){
    char tmp[24];int pos=0;bool neg=false;
    if(v<0){neg=true;/* handle INT64_MIN */
        unsigned long long uv;if(v==INT64_MIN){uv=9223372036854775808ULL;}else uv=(unsigned long long)(-v);
        if(uv==0)tmp[pos++]='0';else{while(uv){tmp[pos++]='0'+(uv%10);uv/=10;}}
    } else {
        unsigned long long uv=(unsigned long long)v;
        if(uv==0)tmp[pos++]='0';else{while(uv){tmp[pos++]='0'+(uv%10);uv/=10;}}
    }
    if(neg)buf_putc(b,'-');
    for(int i=pos-1;i>=0;i--)buf_putc(b,tmp[i]);
}

static void display(Buf*b,Value v,int in_list){
    switch(v.type){
        case T_INT:buf_int(b,v.ival);break;
        case T_BOOL:buf_puts(b,v.bval?"true":"false");break;
        case T_NIL:buf_puts(b,"nil");break;
        case T_FUNC:buf_puts(b,"<fn>");break;
        case T_STRING:
            if(in_list){
                buf_putc(b,'"');
                for(int i=0;i<v.sval.len;i++){
                    char c=v.sval.data[i];
                    if(c=='\\')buf_puts(b,"\\\\");
                    else if(c=='"')buf_puts(b,"\\\"");
                    else if(c=='\n')buf_puts(b,"\\n");
                    else if(c=='\t')buf_puts(b,"\\t");
                    else buf_putc(b,c);
                }
                buf_putc(b,'"');
            } else buf_putn(b,v.sval.data,v.sval.len);
            break;
        case T_LIST:{
            List*l=v.lval;
            for(int i=0;i<disp_len;i++)if(disp_stack[i]==l){buf_puts(b,"[...]");return;}
            if(disp_len<512)disp_stack[disp_len++]=l;
            buf_putc(b,'[');
            for(int i=0;i<l->len;i++){
                if(i)buf_puts(b,", ");
                display(b,l->items[i],1);
            }
            buf_putc(b,']');
            disp_len--;
            break;
        }
    }
}

static Value str_to_value(Buf*b){
    Value r;r.type=T_STRING;r.sval.data=b->data;r.sval.len=b->len;return r;
}

/* ===== Comparison ===== */
static bool val_eq(Value a,Value b){
    if(a.type!=b.type)return false;
    switch(a.type){
        case T_INT:return a.ival==b.ival;
        case T_BOOL:return a.bval==b.bval;
        case T_NIL:return true;
        case T_FUNC:return a.fval==b.fval;
        case T_STRING:
            if(a.sval.len!=b.sval.len)return false;
            return memcmp(a.sval.data,b.sval.data,a.sval.len)==0;
        case T_LIST:{
            List*la=a.lval,*lb=b.lval;
            if(la->len!=lb->len)return false;
            for(int i=0;i<la->len;i++)if(!val_eq(la->items[i],lb->items[i]))return false;
            return true;
        }
    }
    return false;
}

static int str_cmp(Value a,Value b){
    int ml=a.sval.len<b.sval.len?a.sval.len:b.sval.len;
    for(int i=0;i<ml;i++){
        unsigned char ca=(unsigned char)a.sval.data[i],cb=(unsigned char)b.sval.data[i];
        if(ca!=cb)return ca<cb?-1:1;
    }
    if(a.sval.len==b.sval.len)return 0;
    return a.sval.len<b.sval.len?-1:1;
}

/* ===== Overflow check ===== */
static void check_overflow(int64_t r){
    /* we use __builtin which detects it before storing, but we'll just check after */
    (void)r;
}

/* ===== Builtins ===== */
enum{BI_PRINT,BI_STR,BI_TYPE,BI_LEN,BI_PUSH,BI_POP,BI_RANGE,BI_SLICE};
static const char*bi_names[]={"print","str","type","len","push","pop","range","slice"};
static const int bi_nparams[]={-1,1,1,1,2,1,2,3};

static Value call_builtin(int id,Value*args,int nargs,int line){
    if(bi_nparams[id]!=-1&&nargs!=bi_nparams[id])
        die(line,"expected %d arguments, got %d",bi_nparams[id],nargs);
    switch(id){
        case BI_PRINT:{
            Buf b;buf_init(&b);
            for(int i=0;i<nargs;i++){if(i)buf_putc(&b,' ');display(&b,args[i],0);}
            buf_putc(&b,'\n');
            fwrite(b.data,1,b.len,stdout);free(b.data);
            return mk_nil();
        }
        case BI_STR:{
            Buf b;buf_init(&b);display(&b,args[0],0);return str_to_value(&b);
        }
        case BI_TYPE:{return mk_str(tname(args[0].type),strlen(tname(args[0].type)));}
        case BI_LEN:{
            if(args[0].type!=T_STRING&&args[0].type!=T_LIST)die(line,"bad argument to len");
            return mk_int(args[0].type==T_STRING?args[0].sval.len:args[0].lval->len);
        }
        case BI_PUSH:{
            if(args[0].type!=T_LIST)die(line,"bad argument to push");
            list_push(args[0].lval,args[1]);return mk_nil();
        }
        case BI_POP:{
            if(args[0].type!=T_LIST||args[0].lval->len==0)die(line,"bad argument to pop");
            List*l=args[0].lval;return l->items[--l->len];
        }
        case BI_RANGE:{
            if(args[0].type!=T_INT||args[1].type!=T_INT)die(line,"bad argument to range");
            int64_t a=args[0].ival,b=args[1].ival;
            List*l=list_new();
            if(b>a){
                int64_t n=b-a;
                l->cap=(int)n;l->items=xm(n*sizeof(Value));
                for(int64_t i=0;i<n;i++)l->items[i]=mk_int(a+i);
                l->len=(int)n;
            }
            return mk_list(l);
        }
        case BI_SLICE:{
            if(args[0].type!=T_STRING&&args[0].type!=T_LIST)die(line,"bad argument to slice");
            if(args[1].type!=T_INT||args[2].type!=T_INT)die(line,"bad argument to slice");
            int64_t a=args[1].ival,b=args[2].ival;
            if(args[0].type==T_STRING){
                int len=args[0].sval.len;
                if(a<0||b>len||a>b)die(line,"bad argument to slice");
                char*nd=xm((int)(b-a)+1);memcpy(nd,args[0].sval.data+(int)a,(int)(b-a));nd[(int)(b-a)]=0;
                return mk_str(nd,(int)(b-a));
            } else {
                List*l=args[0].lval;int len=l->len;
                if(a<0||b>len||a>b)die(line,"bad argument to slice");
                List*nl=list_new();nl->cap=(int)(b-a);nl->items=xm((b-a)*sizeof(Value));
                for(int64_t i=a;i<b;i++)nl->items[(int)(i-a)]=l->items[(int)i];
                nl->len=(int)(b-a);return mk_list(nl);
            }
        }
    }
    return mk_nil();
}

/* ===== Interpreter ===== */
static void init_builtins(void){
    global_scope=scope_new(NULL);
    for(int i=0;i<8;i++){
        Func*f=xm(sizeof(Func));f->builtin_id=i;f->nparams=bi_nparams[i];f->params=NULL;f->body=NULL;f->nbody=0;f->captured=NULL;
        scope_bind(global_scope,bi_names[i],mk_func(f));
    }
}

static Value eval(ASTNode*n,Scope*sc);
static CF exec_block(ASTNode**stmts,int n,Scope*sc);

static CF exec_stmt(ASTNode*n,Scope*sc){
    switch(n->type){
        case AST_LET:{
            Value v=eval(n->bin.r,sc);scope_bind(sc,n->name,v);return CF_NORMAL;
        }
        case AST_FN_DEF:{
            Func*f=xm(sizeof(Func));f->params=n->fn.params;f->nparams=n->fn.nparams;f->body=n->fn.body;f->nbody=n->fn.nbody;f->captured=sc;f->builtin_id=-1;
            scope_bind(sc,n->fn.name,mk_func(f));return CF_NORMAL;
        }
        case AST_ASSIGN:{
            Value v=eval(n->bin.r,sc);
            Value*loc=scope_lookup(sc,n->name);
            if(!loc)die(n->line,"undefined variable %s",n->name);
            *loc=v;return CF_NORMAL;
        }
        case AST_IDX_ASSIGN:{
            Value obj=eval(n->idx_assign.obj,sc);
            Value idx=eval(n->idx_assign.idx,sc);
            Value val=eval(n->idx_assign.val,sc);
            if(obj.type!=T_LIST)die(n->line,"cannot assign into %s",tname(obj.type));
            if(idx.type!=T_INT)die(n->line,"cannot index list with %s",tname(idx.type));
            int64_t i=idx.ival;int len=obj.lval->len;
            if(i<0||i>=len)die(n->line,"index %lld out of range for length %d",(long long)i,len);
            obj.lval->items[i]=val;return CF_NORMAL;
        }
        case AST_IF:{
            Value c=eval(n->if_node.cond,sc);
            if(truthy(c))return exec_block(n->if_node.then_body,n->if_node.n_then,scope_new(sc));
            else if(n->if_node.else_body)return exec_block(n->if_node.else_body,n->if_node.n_else,scope_new(sc));
            return CF_NORMAL;
        }
        case AST_WHILE:{
            while(truthy(eval(n->while_node.cond,sc))){
                CF c=exec_block(n->while_node.body,n->while_node.nbody,scope_new(sc));
                if(c==CF_BREAK)break;
                if(c==CF_RETURN)return c;
            }
            return CF_NORMAL;
        }
        case AST_FOR:{
            Value iter=eval(n->for_node.iter,sc);
            if(iter.type!=T_LIST)die(n->line,"cannot iterate %s",tname(iter.type));
            List*l=iter.lval;int64_t i=0;
            while(i<l->len){
                Scope*bs=scope_new(sc);
                scope_bind(bs,n->for_node.var,l->items[i]);
                CF c=exec_block(n->for_node.body,n->for_node.nbody,bs);
                if(c==CF_BREAK)break;
                if(c==CF_RETURN)return c;
                i++;
            }
            return CF_NORMAL;
        }
        case AST_RETURN:{
            return_val=n->ret.expr?eval(n->ret.expr,sc):mk_nil();cf=CF_RETURN;return CF_RETURN;
        }
        case AST_BREAK:{cf=CF_BREAK;return CF_BREAK;}
        case AST_CONTINUE:{cf=CF_CONTINUE;return CF_CONTINUE;}
        default:return CF_NORMAL;
    }
}

static CF exec_block(ASTNode**stmts,int n,Scope*sc){
    for(int i=0;i<n;i++){
        CF c=exec_stmt(stmts[i],sc);
        if(c!=CF_NORMAL)return c;
    }
    return CF_NORMAL;
}

static Value eval(ASTNode*n,Scope*sc){
    switch(n->type){
        case AST_INT:return mk_int(n->ival);
        case AST_STR:return mk_str(n->sval.data,n->sval.len);
        case AST_BOOL:return mk_bool(n->ival!=0);
        case AST_NIL:return mk_nil();
        case AST_VAR:{
            Value*loc=scope_lookup(sc,n->name);
            if(!loc)die(n->line,"undefined variable %s",n->name);
            return*loc;
        }
        case AST_LISTLIT:{
            List*l=list_new();l->cap=n->list_lit.nelems;
            if(n->list_lit.nelems>0){l->items=xm(n->list_lit.nelems*sizeof(Value));
                for(int i=0;i<n->list_lit.nelems;i++)l->items[i]=eval(n->list_lit.elems[i],sc);
            }
            l->len=n->list_lit.nelems;return mk_list(l);
        }
        case AST_FN_LIT:{
            Func*f=xm(sizeof(Func));f->params=n->fn.params;f->nparams=n->fn.nparams;f->body=n->fn.body;f->nbody=n->fn.nbody;f->captured=sc;f->builtin_id=-1;
            return mk_func(f);
        }
        case AST_BINOP:{
            int op=n->bin.op;
            if(op==OP_AND){Value l=eval(n->bin.l,sc);if(!truthy(l))return l;return eval(n->bin.r,sc);}
            if(op==OP_OR){Value l=eval(n->bin.l,sc);if(truthy(l))return l;return eval(n->bin.r,sc);}
            Value l=eval(n->bin.l,sc);Value r=eval(n->bin.r,sc);
            if(op==OP_EQ)return mk_bool(val_eq(l,r));
            if(op==OP_NE)return mk_bool(!val_eq(l,r));
            if(op==OP_ADD){
                if(l.type==T_INT&&r.type==T_INT){
                    int64_t res;if(__builtin_add_overflow(l.ival,r.ival,&res))die(n->line,"integer overflow");return mk_int(res);
                }
                if(l.type==T_STRING&&r.type==T_STRING){
                    int nl=l.sval.len+r.sval.len;char*nd=xm(nl);memcpy(nd,l.sval.data,l.sval.len);memcpy(nd+l.sval.len,r.sval.data,r.sval.len);
                    return mk_str(nd,nl);
                }
                if(l.type==T_LIST&&r.type==T_LIST){
                    List*nw=list_new();nw->len=l.lval->len+r.lval->len;nw->cap=nw->len;
                    nw->items=xm(nw->len*sizeof(Value));
                    memcpy(nw->items,l.lval->items,l.lval->len*sizeof(Value));
                    memcpy(nw->items+l.lval->len,r.lval->items,r.lval->len*sizeof(Value));
                    return mk_list(nw);
                }
                die(n->line,"cannot apply + to %s and %s",tname(l.type),tname(r.type));
            }
            if(op==OP_SUB||op==OP_MUL||op==OP_DIV||op==OP_MOD){
                if(l.type!=T_INT||r.type!=T_INT)die(n->line,"cannot apply %s to %s and %s",opname(op),tname(l.type),tname(r.type));
                if(op==OP_SUB){int64_t res;if(__builtin_sub_overflow(l.ival,r.ival,&res))die(n->line,"integer overflow");return mk_int(res);}
                if(op==OP_MUL){int64_t res;if(__builtin_mul_overflow(l.ival,r.ival,&res))die(n->line,"integer overflow");return mk_int(res);}
                if(op==OP_DIV){
                    if(r.ival==0)die(n->line,"division by zero");
                    if(l.ival==INT64_MIN&&r.ival==-1)die(n->line,"integer overflow");
                    return mk_int(l.ival/r.ival);
                }
                if(op==OP_MOD){
                    if(r.ival==0)die(n->line,"division by zero");
                    if(r.ival==-1)return mk_int(0);
                    return mk_int(l.ival%r.ival);
                }
            }
            if(op==OP_LT||op==OP_LE||op==OP_GT||op==OP_GE){
                if(l.type==T_INT&&r.type==T_INT){
                    switch(op){case OP_LT:return mk_bool(l.ival<r.ival);case OP_LE:return mk_bool(l.ival<=r.ival);
                        case OP_GT:return mk_bool(l.ival>r.ival);default:return mk_bool(l.ival>=r.ival);}
                }
                if(l.type==T_STRING&&r.type==T_STRING){
                    int c=str_cmp(l,r);
                    switch(op){case OP_LT:return mk_bool(c<0);case OP_LE:return mk_bool(c<=0);
                        case OP_GT:return mk_bool(c>0);default:return mk_bool(c>=0);}
                }
                die(n->line,"cannot apply %s to %s and %s",opname(op),tname(l.type),tname(r.type));
            }
            die(n->line,"cannot apply %s to %s and %s",opname(op),tname(l.type),tname(r.type));
        }
        case AST_UNOP:{
            Value v=eval(n->un.operand,sc);
            if(n->un.op==UN_NOT)return mk_bool(!truthy(v));
            if(n->un.op==UN_NEG){
                if(v.type!=T_INT)die(n->line,"cannot apply - to %s",tname(v.type));
                if(v.ival==INT64_MIN)die(n->line,"integer overflow");
                return mk_int(-v.ival);
            }
            return mk_nil();
        }
        case AST_CALL:{
            Value callee=eval(n->call.callee,sc);
            Value*args=NULL;int nargs=n->call.nargs;
            if(nargs>0){args=xm(nargs*sizeof(Value));for(int i=0;i<nargs;i++)args[i]=eval(n->call.args[i],sc);}
            if(callee.type!=T_FUNC)die(n->line,"cannot call %s",tname(callee.type));
            Func*f=callee.fval;
            if(f->builtin_id>=0)return call_builtin(f->builtin_id,args,nargs,n->line);
            if(nargs!=f->nparams)die(n->line,"expected %d arguments, got %d",f->nparams,nargs);
            Scope*cs=scope_new(f->captured);
            for(int i=0;i<nargs;i++)scope_bind(cs,f->params[i],args[i]);
            CF c=exec_block(f->body,f->nbody,cs);
            if(c==CF_RETURN){cf=CF_NORMAL;return return_val;}
            cf=CF_NORMAL;return mk_nil();
        }
        case AST_INDEX:{
            Value obj=eval(n->index.obj,sc);Value idx=eval(n->index.idx,sc);
            if(obj.type!=T_LIST&&obj.type!=T_STRING)die(n->line,"cannot index %s with %s",tname(obj.type),tname(idx.type));
            if(idx.type!=T_INT)die(n->line,"cannot index %s with %s",tname(obj.type),tname(idx.type));
            int64_t i=idx.ival;int len=obj.type==T_LIST?obj.lval->len:obj.sval.len;
            if(i<0||i>=len)die(n->line,"index %lld out of range for length %d",(long long)i,len);
            if(obj.type==T_LIST)return obj.lval->items[i];
            return mk_str(obj.sval.data+i,1);
        }
        default:return mk_nil();
    }
}

/* ===== Main ===== */
int main(int argc,char**argv){
    if(argc<2)return 1;
    char path[4096];snprintf(path,sizeof(path),"%s/program.tern",argv[1]);
    FILE*fp=fopen(path,"rb");if(!fp)return 1;
    fseek(fp,0,SEEK_END);long fsz=ftell(fp);fseek(fp,0,SEEK_SET);
    src=xm(fsz+1);fread(src,1,fsz,fp);src[fsz]=0;fclose(fp);slen=(int)fsz;
    tok_cap=4096;tokens=xm(tok_cap*sizeof(Token));ntok=0;
    tokenize();tok_pos=0;
    init_builtins();
    /* parse all statements */
    int cap=64,n=0;ASTNode**prog=xm(cap*sizeof(ASTNode*));
    while(ct()!=TK_EOF){
        if(n>=cap){cap*=2;prog=xr(prog,cap*sizeof(ASTNode*));}
        prog[n++]=parse_stmt();
    }
    cf=CF_NORMAL;
    exec_block(prog,n,global_scope);
    fflush(stdout);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdarg.h>

typedef struct Value Value;
typedef struct List List;
typedef struct Func Func;
typedef struct Scope Scope;
typedef struct ASTNode ASTNode;

typedef enum { T_INT, T_BOOL, T_STRING, T_LIST, T_FUNC, T_NIL } VType;

struct List { Value *items; int len, cap; };
struct Func { char **params; int nparams; ASTNode **body; int nbody; Scope *captured; int builtin_id; };
struct Value { VType type; union { int64_t ival; bool bval; struct{char*data;int len;}sval; List*lval; Func*fval; }; };

typedef struct { char *name; Value val; } Binding;
struct Scope { Scope *parent; Binding *bindings; int n, cap; };

typedef enum { AST_INT,AST_STR,AST_BOOL,AST_NIL,AST_VAR,AST_ASSIGN,AST_IDX_ASSIGN,
    AST_LET,AST_FN_DEF,AST_FN_LIT,AST_IF,AST_WHILE,AST_FOR,AST_RETURN,AST_BREAK,AST_CONTINUE,
    AST_BINOP,AST_UNOP,AST_CALL,AST_INDEX,AST_LISTLIT } ASTType;
enum {OP_ADD,OP_SUB,OP_MUL,OP_DIV,OP_MOD,OP_EQ,OP_NE,OP_LT,OP_LE,OP_GT,OP_GE,OP_AND,OP_OR};
enum {UN_NEG,UN_NOT};

struct ASTNode {
    ASTType type; int line;
    union {
        int64_t ival;
        struct{char*data;int len;}sval;
        char *name;
        struct{ASTNode*l,*r;int op;}bin;
        struct{ASTNode*operand;int op;}un;
        struct{ASTNode*callee;ASTNode**args;int nargs;}call;
        struct{ASTNode*obj,*idx;}index;
        struct{ASTNode**elems;int nelems;}list_lit;
        struct{ASTNode*cond;ASTNode**then_body;int n_then;ASTNode**else_body;int n_else;}if_node;
        struct{ASTNode*cond;ASTNode**body;int nbody;}while_node;
        struct{char*var;ASTNode*iter;ASTNode**body;int nbody;}for_node;
        struct{ASTNode*expr;}ret;
        struct{char**params;int nparams;ASTNode**body;int nbody;char*name;}fn;
        struct{ASTNode*obj,*idx,*val;}idx_assign;
    };
};

typedef enum {
    TK_INT,TK_STR,TK_IDENT,TK_FN,TK_LET,TK_IF,TK_ELSE,TK_WHILE,TK_FOR,TK_IN,
    TK_RETURN,TK_BREAK,TK_CONTINUE,TK_AND,TK_OR,TK_NOT,TK_TRUE,TK_FALSE,TK_NIL,
    TK_LPAREN,TK_RPAREN,TK_LBRACKET,TK_RBRACKET,TK_LBRACE,TK_RBRACE,
    TK_COMMA,TK_SEMI,TK_ASSIGN,TK_EQ,TK_NE,TK_LT,TK_LE,TK_GT,TK_GE,
    TK_PLUS,TK_MINUS,TK_STAR,TK_SLASH,TK_PERCENT,TK_EOF
} TokType;

typedef struct { TokType type; int64_t ival; char*sdata; int slen; int line; } Token;

static Token *tokens; static int ntok, tok_cap, tok_pos;
static Scope *global_scope;
typedef enum {CF_NORMAL,CF_BREAK,CF_CONTINUE,CF_RETURN} CF;
static CF cf; static Value return_val;
static List *disp_stack[512]; static int disp_len;

static void die(int line, const char *fmt, ...) {
    va_list ap; printf("error at line %d: ",line);
    va_start(ap,fmt); vprintf(fmt,ap); va_end(ap);
    printf("\n"); fflush(stdout); exit(0);
}

static const char *tname(VType t){
    switch(t){case T_INT:return"int";case T_BOOL:return"bool";case T_STRING:return"string";
    case T_LIST:return"list";case T_FUNC:return"function";case T_NIL:return"nil";}return"?";
}
static const char *opname(int op){
    switch(op){case OP_ADD:return"+";case OP_SUB:return"-";case OP_MUL:return"*";
    case OP_DIV:return"/";case OP_MOD:return"%";case OP_EQ:return"==";case OP_NE:return"!=";
    case OP_LT:return"<";case OP_LE:return"<=";case OP_GT:return">";case OP_GE:return">=";}return"?";
}

static void*xm(size_t n){void*p=malloc(n);if(!p)exit(1);return p;}
static void*xr(void*p,size_t n){void*q=realloc(p,n);if(!q)exit(1);return q;}

/* ===== Lexer ===== */
static char *src; static int slen,spos,cur_line;
static void tok_add(TokType t,int line){
    if(ntok>=tok_cap){tok_cap=tok_cap?tok_cap*2:256;tokens=xr(tokens,tok_cap*sizeof(Token));}
    tokens[ntok].type=t;tokens[ntok].line=line;tokens[ntok].ival=0;tokens[ntok].sdata=NULL;tokens[ntok].slen=0;ntok++;
}
static void tok_add_int(int64_t v,int line){tok_add(TK_INT,line);tokens[ntok-1].ival=v;}
static void tok_add_str(char*d,int l,int line){tok_add(TK_STR,line);tokens[ntok-1].sdata=d;tokens[ntok-1].slen=l;}
static void tok_add_id(char*d,int l,int line){tok_add(TK_IDENT,line);tokens[ntok-1].sdata=d;tokens[ntok-1].slen=l;}

static void tokenize(void){
    cur_line=1;spos=0;
    while(spos<slen){
        char c=src[spos];
        if(c==' '||c=='\t'||c=='\r'){spos++;continue;}
        if(c=='\n'){cur_line++;spos++;continue;}
        if(c=='#'){while(spos<slen&&src[spos]!='\n')spos++;continue;}
        int line=cur_line;
        if(c>='0'&&c<='9'){
            int64_t v=0;while(spos<slen&&src[spos]>='0'&&src[spos]<='9'){v=v*10+(src[spos]-'0');spos++;}
            tok_add_int(v,line);continue;
        }
        if(c=='"'){
            spos++;int cap=16,len=0;char*buf=xm(cap);
            while(spos<slen&&src[spos]!='"'){
                if(src[spos]=='\\'&&spos+1<slen){
                    spos++;char e=src[spos];spos++;
                    char r=e;
                    if(e=='n')r='\n';else if(e=='t')r='\t';else if(e=='"')r='"';else if(e=='\\')r='\\';
                    if(len>=cap){cap*=2;buf=xr(buf,cap);}buf[len++]=r;
                } else {
                    if(len>=cap){cap*=2;buf=xr(buf,cap);}buf[len++]=src[spos];spos++;
                }
            }
            if(spos<slen)spos++;
            tok_add_str(buf,len,line);continue;
        }
        if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||c=='_'){
            int st=spos;while(spos<slen&&((src[spos]>='a'&&src[spos]<='z')||(src[spos]>='A'&&src[spos]<='Z')||(src[spos]>='0'&&src[spos]<='9')||src[spos]=='_'))spos++;
            int l=spos-st;char*id=xm(l+1);memcpy(id,src+st,l);id[l]=0;
            TokType t=TK_IDENT;
            if(!strcmp(id,"fn"))t=TK_FN;else if(!strcmp(id,"let"))t=TK_LET;
            else if(!strcmp(id,"if"))t=TK_IF;else if(!strcmp(id,"else"))t=TK_ELSE;
            else if(!strcmp(id,"while"))t=TK_WHILE;else if(!strcmp(id,"for"))t=TK_FOR;
            else if(!strcmp(id,"in"))t=TK_IN;else if(!strcmp(id,"return"))t=TK_RETURN;
            else if(!strcmp(id,"break"))t=TK_BREAK;else if(!strcmp(id,"continue"))t=TK_CONTINUE;
            else if(!strcmp(id,"and"))t=TK_AND;else if(!strcmp(id,"or"))t=TK_OR;
            else if(!strcmp(id,"not"))t=TK_NOT;else if(!strcmp(id,"true"))t=TK_TRUE;
            else if(!strcmp(id,"false"))t=TK_FALSE;else if(!strcmp(id,"nil"))t=TK_NIL;
            if(t!=TK_IDENT){tok_add(t,line);}
            else tok_add_id(id,l,line);
            continue;
        }
        spos++;
        switch(c){
            case '(':tok_add(TK_LPAREN,line);break;case ')':tok_add(TK_RPAREN,line);break;
            case '[':tok_add(TK_LBRACKET,line);break;case ']':tok_add(TK_RBRACKET,line);break;
            case '{':tok_add(TK_LBRACE,line);break;case '}':tok_add(TK_RBRACE,line);break;
            case ',':tok_add(TK_COMMA,line);break;case ';':tok_add(TK_SEMI,line);break;
            case '+':tok_add(TK_PLUS,line);break;case '-':tok_add(TK_MINUS,line);break;
            case '*':tok_add(TK_STAR,line);break;case '/':tok_add(TK_SLASH,line);break;
            case '%':tok_add(TK_PERCENT,line);break;
            case '=':if(spos<slen&&src[spos]=='='){spos++;tok_add(TK_EQ,line);}else tok_add(TK_ASSIGN,line);break;
            case '!':if(spos<slen&&src[spos]=='='){spos++;tok_add(TK_NE,line);}else tok_add(TK_NOT,line);break;
            case '<':if(spos<slen&&src[spos]=='='){spos++;tok_add(TK_LE,line);}else tok_add(TK_LT,line);break;
            case '>':if(spos<slen&&src[spos]=='='){spos++;tok_add(TK_GE,line);}else tok_add(TK_GT,line);break;
            default:break;
        }
    }
    tok_add(TK_EOF,cur_line);
}

/* ===== Parser ===== */
static ASTNode*parse_stmt(void);
static ASTNode*parse_expr(void);
static ASTNode*parse_primary(void);

static Token*cur(void){return&tokens[tok_pos];}
static TokType ct(void){return tokens[tok_pos].type;}
static TokType consume(void){return tokens[tok_pos++].type;}
static void expect(TokType t){if(ct()==t)tok_pos++;else die(tokens[tok_pos].line,"syntax error");}

static ASTNode*nnew(ASTType t){ASTNode*n=xm(sizeof(ASTNode));memset(n,0,sizeof(ASTNode));n->type=t;n->line=tokens[tok_pos].line;return n;}

static ASTNode**parse_block(int*np){
    expect(TK_LBRACE);
    int cap=8,n=0;ASTNode**stmts=xm(cap*sizeof(ASTNode*));
    while(ct()!=TK_RBRACE&&ct()!=TK_EOF){
        if(n>=cap){cap*=2;stmts=xr(stmts,cap*sizeof(ASTNode*));}
        stmts[n++]=parse_stmt();
    }
    expect(TK_RBRACE);*np=n;return stmts;
}

static ASTNode*parse_primary(void){
    Token*t=cur();int line=t->line;
    switch(t->type){
        case TK_INT:{ASTNode*n=nnew(AST_INT);n->line=line;n->ival=t->ival;tok_pos++;return n;}
        case TK_STR:{ASTNode*n=nnew(AST_STR);n->line=line;n->sval.data=t->sdata;n->sval.len=t->slen;tok_pos++;return n;}
        case TK_TRUE:{ASTNode*n=nnew(AST_BOOL);n->line=line;n->ival=1;tok_pos++;return n;}
        case TK_FALSE:{ASTNode*n=nnew(AST_BOOL);n->line=line;n->ival=0;tok_pos++;return n;}
        case TK_NIL:{ASTNode*n=nnew(AST_NIL);n->line=line;tok_pos++;return n;}
        case TK_IDENT:{ASTNode*n=nnew(AST_VAR);n->line=line;n->name=t->sdata;tok_pos++;return n;}
        case TK_LPAREN:{tok_pos++;ASTNode*e=parse_expr();expect(TK_RPAREN);return e;}
        case TK_LBRACKET:{
            int line2=t->line;tok_pos++;
            int cap=8,n=0;ASTNode**elems=NULL;
            if(ct()!=TK_RBRACKET){
                elems=xm(cap*sizeof(ASTNode*));elems[n++]=parse_expr();
                while(ct()==TK_COMMA){tok_pos++;if(n>=cap){cap*=2;elems=xr(elems,cap*sizeof(ASTNode*));}elems[n++]=parse_expr();}
            }
            expect(TK_RBRACKET);
            ASTNode*nd=nnew(AST_LISTLIT);nd->line=line2;nd->list_lit.elems=elems;nd->list_lit.nelems=n;return nd;
        }
        case TK_FN:{
            int fnline=t->line;tok_pos++;expect(TK_LPAREN);
            char**params=NULL;int np=0,cap=4;
            if(ct()!=TK_RPAREN){
                params=xm(cap*sizeof(char*));
                params[np++]=cur()->sdata;tok_pos++;
                while(ct()==TK_COMMA){tok_pos++;if(np>=cap){cap*=2;params=xr(params,cap*sizeof(char*));}params[np++]=cur()->sdata;tok_pos++;}
            }
            expect(TK_RPAREN);
            int nb;ASTNode**body=parse_block(&nb);
            ASTNode*nd=nnew(AST_FN_LIT);nd->line=fnline;nd->fn.params=params;nd->fn.nparams=np;nd->fn.body=body;nd->fn.nbody=nb;nd->fn.name=NULL;
            return nd;
        }
        default:die(line,"syntax error");return NULL;
    }
}

static ASTNode*parse_postfix(void){
    ASTNode*e=parse_primary();
    while(1){
        if(ct()==TK_LPAREN){
            int line=cur()->line;tok_pos++;
            int cap=4,n=0;ASTNode**args=NULL;
            if(ct()!=TK_RPAREN){
                args=xm(cap*sizeof(ASTNode*));args[n++]=parse_expr();
                while(ct()==TK_COMMA){tok_pos++;if(n>=cap){cap*=2;args=xr(args,cap*sizeof(ASTNode*));}args[n++]=parse_expr();}
            }
            expect(TK_RPAREN);
            ASTNode*nd=nnew(AST_CALL);nd->line=line;nd->call.callee=e;nd->call.args=args;nd->call.nargs=n;e=nd;
        } else if(ct()==TK_LBRACKET){
            int line=cur()->line;tok_pos++;ASTNode*idx=parse_expr();expect(TK_RBRACKET);
            ASTNode*nd=nnew(AST_INDEX);nd->line=line;nd->index.obj=e;nd->index.idx=idx;e=nd;
        } else break;
    }
    return e;
}

static ASTNode*parse_unary(void){
    if(ct()==TK_MINUS){int line=cur()->line;tok_pos++;ASTNode*e=parse_unary();ASTNode*n=nnew(AST_UNOP);n->line=line;n->un.operand=e;n->un.op=UN_NEG;return n;}
    return parse_postfix();
}
static ASTNode*parse_mul(void){
    ASTNode*l=parse_unary();
    while(ct()==TK_STAR||ct()==TK_SLASH||ct()==TK_PERCENT){
        int op=ct()==TK_STAR?OP_MUL:ct()==TK_SLASH?OP_DIV:OP_MOD;int line=cur()->line;tok_pos++;
        ASTNode*r=parse_unary();ASTNode*n=nnew(AST_BINOP);n->line=line;n->bin.l=l;n->bin.r=r;n->bin.op=op;l=n;
    }
    return l;
}
static ASTNode*parse_add(void){
    ASTNode*l=parse_mul();
    while(ct()==TK_PLUS||ct()==TK_MINUS){
        int op=ct()==TK_PLUS?OP_ADD:OP_SUB;int line=cur()->line;tok_pos++;
        ASTNode*r=parse_mul();ASTNode*n=nnew(AST_BINOP);n->line=line;n->bin.l=l;n->bin.r=r;n->bin.op=op;l=n;
    }
    return l;
}
static ASTNode*parse_cmp(void){
    ASTNode*l=parse_add();
    while(ct()==TK_EQ||ct()==TK_NE||ct()==TK_LT||ct()==TK_LE||ct()==TK_GT||ct()==TK_GE){
        int op;switch(ct()){case TK_EQ:op=OP_EQ;break;case TK_NE:op=OP_NE;break;case TK_LT:op=OP_LT;break;
            case TK_LE:op=OP_LE;break;case TK_GT:op=OP_GT;break;default:op=OP_GE;break;}
        int line=cur()->line;tok_pos++;
        ASTNode*r=parse_add();ASTNode*n=nnew(AST_BINOP);n->line=line;n->bin.l=l;n->bin.r=r;n->bin.op=op;l=n;
    }
    return l;
}
static ASTNode*parse_not(void){
    if(ct()==TK_NOT){int line=cur()->line;tok_pos++;ASTNode*e=parse_not();ASTNode*n=nnew(AST_UNOP);n->line=line;n->un.operand=e;n->un.op=UN_NOT;return n;}
    return parse_cmp();
}
static ASTNode*parse_and(void){
    ASTNode*l=parse_not();
    while(ct()==TK_AND){int line=cur()->line;tok_pos++;ASTNode*r=parse_not();ASTNode*n=nnew(AST_BINOP);n->line=line;n->bin.l=l;n->bin.r=r;n->bin.op=OP_AND;l=n;}
    return l;
}
static ASTNode*parse_or(void){
    ASTNode*l=parse_and();
    while(ct()==TK_OR){int line=cur()->line;tok_pos++;ASTNode*r=parse_and();ASTNode*n=nnew(AST_BINOP);n->line=line;n->bin.l=l;n->bin.r=r;n->bin.op=OP_OR;l=n;}
    return l;
}
static ASTNode*parse_expr(void){return parse_or();}

static ASTNode*parse_stmt(void){
    Token*t=cur();int line=t->line;
    switch(t->type){
        case TK_LET:{
            tok_pos++;char*name=cur()->sdata;int nline=cur()->line;tok_pos++;expect(TK_ASSIGN);
            ASTNode*val=parse_expr();expect(TK_SEMI);
            ASTNode*n=nnew(AST_LET);n->line=nline;n->name=name;n->bin.r=val;return n;
        }
        case TK_FN:{
            tok_pos++;char*name=cur()->sdata;int nline=cur()->line;tok_pos++;expect(TK_LPAREN);
            char**params=NULL;int np=0,cap=4;
            if(ct()!=TK_RPAREN){
                params=xm(cap*sizeof(char*));params[np++]=cur()->sdata;tok_pos++;
                while(ct()==TK_COMMA){tok_pos++;if(np>=cap){cap*=2;params=xr(params,cap*sizeof(char*));}params[np++]=cur()->sdata;tok_pos++;}
            }
            expect(TK_RPAREN);int nb;ASTNode**body=parse_block(&nb);
            ASTNode*n=nnew(AST_FN_DEF);n->line=nline;n->fn.params=params;n->fn.nparams=np;n->fn.body=body;n->fn.nbody=nb;n->fn.name=name;
            return n;
        }
        case TK_IF:{
            int ifline=t->line;tok_pos++;ASTNode*cond=parse_expr();
            int nt;ASTNode**tb=parse_block(&nt);
            ASTNode**eb=NULL;int ne=0;
            if(ct()==TK_ELSE){
                tok_pos++;
                if(ct()==TK_IF){ASTNode**tmp=xm(sizeof(ASTNode*));tmp[0]=parse_stmt();eb=tmp;ne=1;}
                else{eb=parse_block(&ne);}
            }
            ASTNode*n=nnew(AST_IF);n->line=ifline;n->if_node.cond=cond;n->if_node.then_body=tb;n->if_node.n_then=nt;
            n->if_node.else_body=eb;n->if_node.n_else=ne;return n;
        }
        case TK_WHILE:{
            int wline=t->line;tok_pos++;ASTNode*cond=parse_expr();int nb;ASTNode**body=parse_block(&nb);
            ASTNode*n=nnew(AST_WHILE);n->line=wline;n->while_node.cond=cond;n->while_node.body=body;n->while_node.nbody=nb;return n;
        }
        case TK_FOR:{
            int fline=t->line;tok_pos++;char*var=cur()->sdata;tok_pos++;expect(TK_IN);ASTNode*iter=parse_expr();
            int nb;ASTNode**body=parse_block(&nb);
            ASTNode*n=nnew(AST_FOR);n->line=fline;n->for_node.var=var;n->for_node.iter=iter;n->for_node.body=body;n->for_node.nbody=nb;return n;
        }
        case TK_RETURN:{
            tok_pos++;ASTNode*expr=NULL;if(ct()!=TK_SEMI)expr=parse_expr();expect(TK_SEMI);
            ASTNode*n=nnew(AST_RETURN);n->line=line;n->ret.expr=expr;return n;
        }
        case TK_BREAK:{tok_pos++;expect(TK_SEMI);ASTNode*n=nnew(AST_BREAK);n->line=line;return n;}
        case TK_CONTINUE:{tok_pos++;expect(TK_SEMI);ASTNode*n=nnew(AST_CONTINUE);n->line=line;return n;}
        case TK_IDENT:{
            if(tokens[tok_pos+1].type==TK_ASSIGN){
                char*name=t->sdata;tok_pos+=2;ASTNode*val=parse_expr();expect(TK_SEMI);
                ASTNode*n=nnew(AST_ASSIGN);n->line=line;n->name=name;n->bin.r=val;return n;
            }
            /* fall through to expression */
        }
        /* fall through */
        default:{
            ASTNode*e=parse_expr();
            if(ct()==TK_ASSIGN){
                tok_pos++;ASTNode*val=parse_expr();expect(TK_SEMI);
                ASTNode*n=nnew(AST_IDX_ASSIGN);n->line=e->line;n->idx_assign.obj=e->index.obj;n->idx_assign.idx=e->index.idx;n->idx_assign.val=val;
                return n;
            }
            expect(TK_SEMI);return e;
        }
    }
}

/* ===== Scope ===== */
static Scope*scope_new(Scope*parent){Scope*s=xm(sizeof(Scope));s->parent=parent;s->bindings=NULL;s->n=0;s->cap=0;return s;}
static void scope_bind(Scope*s,const char*name,Value v){
    if(s->n>=s->cap){s->cap=s->cap?s->cap*2:8;s->bindings=xr(s->bindings,s->cap*sizeof(Binding));}
    s->bindings[s->n].name=(char*)name;s->bindings[s->n].val=v;s->n++;
}
static Value*scope_lookup(Scope*s,const char*name){
    while(s){for(int i=s->n-1;i>=0;i--)if(!strcmp(s->bindings[i].name,name))return&s->bindings[i].val;s=s->parent;}
    return NULL;
}

/* ===== Value helpers ===== */
static Value mk_int(int64_t v){Value r;r.type=T_INT;r.ival=v;return r;}
static Value mk_bool(bool v){Value r;r.type=T_BOOL;r.bval=v;return r;}
static Value mk_nil(void){Value r;r.type=T_NIL;return r;}
static Value mk_str(const char*d,int len){Value r;r.type=T_STRING;r.sval.data=(char*)d;r.sval.len=len;return r;}
static Value mk_list(List*l){Value r;r.type=T_LIST;r.lval=l;return r;}
static Value mk_func(Func*f){Value r;r.type=T_FUNC;r.fval=f;return r;}

static List*list_new(void){List*l=xm(sizeof(List));l->items=NULL;l->len=0;l->cap=0;return l;}
static void list_push(List*l,Value v){
    if(l->len>=l->cap){l->cap=l->cap?l->cap*2:4;l->items=xr(l->items,l->cap*sizeof(Value));}
    l->items[l->len++]=v;
}

static bool truthy(Value v){
    switch(v.type){
        case T_BOOL:return v.bval;
        case T_INT:return v.ival!=0;
        case T_STRING:return v.sval.len!=0;
        case T_LIST:return v.lval->len!=0;
        case T_NIL:return false;
        case T_FUNC:return true;
    }
    return false;
}

/* ===== Display ===== */
typedef struct{char*data;int len,cap;}Buf;
static void buf_init(Buf*b){b->data=NULL;b->len=0;b->cap=0;}
static void buf_putc(Buf*b,char c){if(b->len>=b->cap){b->cap=b->cap?b->cap*2:64;b->data=xr(b->data,b->cap);}b->data[b->len++]=c;}
static void buf_puts(Buf*b,const char*s){while(*s)buf_putc(b,*s++);}
static void buf_putn(Buf*b,const char*s,int n){for(int i=0;i<n;i++)buf_putc(b,s[i]);}
static void buf_int(Buf*b,int64_t v){
    char tmp[24];int pos=0;bool neg=false;
    if(v<0){neg=true;
        unsigned long long uv;if(v==INT64_MIN){uv=9223372036854775808ULL;}else uv=(unsigned long long)(-v);
        if(uv==0)tmp[pos++]='0';else{while(uv){tmp[pos++]='0'+(uv%10);uv/=10;}}
    } else {
        unsigned long long uv=(unsigned long long)v;
        if(uv==0)tmp[pos++]='0';else{while(uv){tmp[pos++]='0'+(uv%10);uv/=10;}}
    }
    if(neg)buf_putc(b,'-');
    for(int i=pos-1;i>=0;i--)buf_putc(b,tmp[i]);
}

static void display(Buf*b,Value v,int in_list){
    switch(v.type){
        case T_INT:buf_int(b,v.ival);break;
        case T_BOOL:buf_puts(b,v.bval?"true":"false");break;
        case T_NIL:buf_puts(b,"nil");break;
        case T_FUNC:buf_puts(b,"<fn>");break;
        case T_STRING:
            if(in_list){
                buf_putc(b,'"');
                for(int i=0;i<v.sval.len;i++){
                    char c=v.sval.data[i];
                    if(c=='\\')buf_puts(b,"\\\\");
                    else if(c=='"')buf_puts(b,"\\\"");
                    else if(c=='\n')buf_puts(b,"\\n");
                    else if(c=='\t')buf_puts(b,"\\t");
                    else buf_putc(b,c);
                }
                buf_putc(b,'"');
            } else buf_putn(b,v.sval.data,v.sval.len);
            break;
        case T_LIST:{
            List*l=v.lval;
            for(int i=0;i<disp_len;i++)if(disp_stack[i]==l){buf_puts(b,"[...]");return;}
            if(disp_len<512)disp_stack[disp_len++]=l;
            buf_putc(b,'[');
            for(int i=0;i<l->len;i++){
                if(i)buf_puts(b,", ");
                display(b,l->items[i],1);
            }
            buf_putc(b,']');
            disp_len--;
            break;
        }
    }
}

static Value str_to_value(Buf*b){
    Value r;r.type=T_STRING;r.sval.data=b->data;r.sval.len=b->len;return r;
}

/* ===== Comparison ===== */
static bool val_eq(Value a,Value b){
    if(a.type!=b.type)return false;
    switch(a.type){
        case T_INT:return a.ival==b.ival;
        case T_BOOL:return a.bval==b.bval;
        case T_NIL:return true;
        case T_FUNC:return a.fval==b.fval;
        case T_STRING:
            if(a.sval.len!=b.sval.len)return false;
            return memcmp(a.sval.data,b.sval.data,a.sval.len)==0;
        case T_LIST:{
            List*la=a.lval,*lb=b.lval;
            if(la->len!=lb->len)return false;
            for(int i=0;i<la->len;i++)if(!val_eq(la->items[i],lb->items[i]))return false;
            return true;
        }
    }
    return false;
}

static int str_cmp(Value a,Value b){
    int ml=a.sval.len<b.sval.len?a.sval.len:b.sval.len;
    for(int i=0;i<ml;i++){
        unsigned char ca=(unsigned char)a.sval.data[i],cb=(unsigned char)b.sval.data[i];
        if(ca!=cb)return ca<cb?-1:1;
    }
    if(a.sval.len==b.sval.len)return 0;
    return a.sval.len<b.sval.len?-1:1;
}

/* ===== Builtins ===== */
enum{BI_PRINT,BI_STR,BI_TYPE,BI_LEN,BI_PUSH,BI_POP,BI_RANGE,BI_SLICE};
static const char*bi_names[]={"print","str","type","len","push","pop","range","slice"};
static const int bi_nparams[]={-1,1,1,1,2,1,2,3};

static Value call_builtin(int id,Value*args,int nargs,int line){
    if(bi_nparams[id]!=-1&&nargs!=bi_nparams[id])
        die(line,"expected %d arguments, got %d",bi_nparams[id],nargs);
    switch(id){
        case BI_PRINT:{
            Buf b;buf_init(&b);
            for(int i=0;i<nargs;i++){if(i)buf_putc(&b,' ');display(&b,args[i],0);}
            buf_putc(&b,'\n');
            fwrite(b.data,1,b.len,stdout);free(b.data);
            return mk_nil();
        }
        case BI_STR:{
            Buf b;buf_init(&b);display(&b,args[0],0);return str_to_value(&b);
        }
        case BI_TYPE:{return mk_str(tname(args[0].type),(int)strlen(tname(args[0].type)));}
        case BI_LEN:{
            if(args[0].type!=T_STRING&&args[0].type!=T_LIST)die(line,"bad argument to len");
            return mk_int(args[0].type==T_STRING?args[0].sval.len:args[0].lval->len);
        }
        case BI_PUSH:{
            if(args[0].type!=T_LIST)die(line,"bad argument to push");
            list_push(args[0].lval,args[1]);return mk_nil();
        }
        case BI_POP:{
            if(args[0].type!=T_LIST||args[0].lval->len==0)die(line,"bad argument to pop");
            List*l=args[0].lval;return l->items[--l->len];
        }
        case BI_RANGE:{
            if(args[0].type!=T_INT||args[1].type!=T_INT)die(line,"bad argument to range");
            int64_t a=args[0].ival,b=args[1].ival;
            List*l=list_new();
            if(b>a){
                int64_t n=b-a;
                l->cap=(int)n;l->items=xm(n*sizeof(Value));
                for(int64_t i=0;i<n;i++)l->items[i]=mk_int(a+i);
                l->len=(int)n;
            }
            return mk_list(l);
        }
        case BI_SLICE:{
            if(args[0].type!=T_STRING&&args[0].type!=T_LIST)die(line,"bad argument to slice");
            if(args[1].type!=T_INT||args[2].type!=T_INT)die(line,"bad argument to slice");
            int64_t a=args[1].ival,b=args[2].ival;
            if(args[0].type==T_STRING){
                int len=args[0].sval.len;
                if(a<0||b>len||a>b)die(line,"bad argument to slice");
                char*nd=xm((int)(b-a)+1);memcpy(nd,args[0].sval.data+(int)a,(int)(b-a));nd[(int)(b-a)]=0;
                return mk_str(nd,(int)(b-a));
            } else {
                List*l=args[0].lval;int len=l->len;
                if(a<0||b>len||a>b)die(line,"bad argument to slice");
                List*nl=list_new();nl->cap=(int)(b-a);nl->items=xm((b-a)*sizeof(Value));
                for(int64_t i=a;i<b;i++)nl->items[(int)(i-a)]=l->items[(int)i];
                nl->len=(int)(b-a);return mk_list(nl);
            }
        }
    }
    return mk_nil();
}

/* ===== Interpreter ===== */
static void init_builtins(void){
    global_scope=scope_new(NULL);
    for(int i=0;i<8;i++){
        Func*f=xm(sizeof(Func));f->builtin_id=i;f->nparams=bi_nparams[i];f->params=NULL;f->body=NULL;f->nbody=0;f->captured=NULL;
        scope_bind(global_scope,bi_names[i],mk_func(f));
    }
}

static Value eval(ASTNode*n,Scope*sc);
static CF exec_block(ASTNode**stmts,int n,Scope*sc);

static CF exec_stmt(ASTNode*n,Scope*sc){
    switch(n->type){
        case AST_LET:{
            Value v=eval(n->bin.r,sc);scope_bind(sc,n->name,v);return CF_NORMAL;
        }
        case AST_FN_DEF:{
            Func*f=xm(sizeof(Func));f->params=n->fn.params;f->nparams=n->fn.nparams;f->body=n->fn.body;f->nbody=n->fn.nbody;f->captured=sc;f->builtin_id=-1;
            scope_bind(sc,n->fn.name,mk_func(f));return CF_NORMAL;
        }
        case AST_ASSIGN:{
            Value v=eval(n->bin.r,sc);
            Value*loc=scope_lookup(sc,n->name);
            if(!loc)die(n->line,"undefined variable %s",n->name);
            *loc=v;return CF_NORMAL;
        }
        case AST_IDX_ASSIGN:{
            Value obj=eval(n->idx_assign.obj,sc);
            Value idx=eval(n->idx_assign.idx,sc);
            Value val=eval(n->idx_assign.val,sc);
            if(obj.type!=T_LIST)die(n->line,"cannot assign into %s",tname(obj.type));
            if(idx.type!=T_INT)die(n->line,"cannot index list with %s",tname(idx.type));
            int64_t i=idx.ival;int len=obj.lval->len;
            if(i<0||i>=len)die(n->line,"index %lld out of range for length %d",(long long)i,len);
            obj.lval->items[i]=val;return CF_NORMAL;
        }
        case AST_IF:{
            Value c=eval(n->if_node.cond,sc);
            if(truthy(c))return exec_block(n->if_node.then_body,n->if_node.n_then,scope_new(sc));
            else if(n->if_node.else_body)return exec_block(n->if_node.else_body,n->if_node.n_else,scope_new(sc));
            return CF_NORMAL;
        }
        case AST_WHILE:{
            while(truthy(eval(n->while_node.cond,sc))){
                CF c=exec_block(n->while_node.body,n->while_node.nbody,scope_new(sc));
                if(c==CF_BREAK)break;
                if(c==CF_RETURN)return c;
            }
            return CF_NORMAL;
        }
        case AST_FOR:{
            Value iter=eval(n->for_node.iter,sc);
            if(iter.type!=T_LIST)die(n->line,"cannot iterate %s",tname(iter.type));
            List*l=iter.lval;int64_t i=0;
            while(i<l->len){
                Scope*bs=scope_new(sc);
                scope_bind(bs,n->for_node.var,l->items[i]);
                CF c=exec_block(n->for_node.body,n->for_node.nbody,bs);
                if(c==CF_BREAK)break;
                if(c==CF_RETURN)return c;
                i++;
            }
            return CF_NORMAL;
        }
        case AST_RETURN:{
            return_val=n->ret.expr?eval(n->ret.expr,sc):mk_nil();cf=CF_RETURN;return CF_RETURN;
        }
        case AST_BREAK:{cf=CF_BREAK;return CF_BREAK;}
        case AST_CONTINUE:{cf=CF_CONTINUE;return CF_CONTINUE;}
        default:return CF_NORMAL;
    }
}

static CF exec_block(ASTNode**stmts,int n,Scope*sc){
    for(int i=0;i<n;i++){
        CF c=exec_stmt(stmts[i],sc);
        if(c!=CF_NORMAL)return c;
    }
    return CF_NORMAL;
}

static Value eval(ASTNode*n,Scope*sc){
    switch(n->type){
        case AST_INT:return mk_int(n->ival);
        case AST_STR:return mk_str(n->sval.data,n->sval.len);
        case AST_BOOL:return mk_bool(n->ival!=0);
        case AST_NIL:return mk_nil();
        case AST_VAR:{
            Value*loc=scope_lookup(sc,n->name);
            if(!loc)die(n->line,"undefined variable %s",n->name);
            return*loc;
        }
        case AST_LISTLIT:{
            List*l=list_new();l->cap=n->list_lit.nelems;
            if(n->list_lit.nelems>0){l->items=xm(n->list_lit.nelems*sizeof(Value));
                for(int i=0;i<n->list_lit.nelems;i++)l->items[i]=eval(n->list_lit.elems[i],sc);
            }
            l->len=n->list_lit.nelems;return mk_list(l);
        }
        case AST_FN_LIT:{
            Func*f=xm(sizeof(Func));f->params=n->fn.params;f->nparams=n->fn.nparams;f->body=n->fn.body;f->nbody=n->fn.nbody;f->captured=sc;f->builtin_id=-1;
            return mk_func(f);
        }
        case AST_BINOP:{
            int op=n->bin.op;
            if(op==OP_AND){Value l=eval(n->bin.l,sc);if(!truthy(l))return l;return eval(n->bin.r,sc);}
            if(op==OP_OR){Value l=eval(n->bin.l,sc);if(truthy(l))return l;return eval(n->bin.r,sc);}
            Value l=eval(n->bin.l,sc);Value r=eval(n->bin.r,sc);
            if(op==OP_EQ)return mk_bool(val_eq(l,r));
            if(op==OP_NE)return mk_bool(!val_eq(l,r));
            if(op==OP_ADD){
                if(l.type==T_INT&&r.type==T_INT){
                    int64_t res;if(__builtin_add_overflow(l.ival,r.ival,&res))die(n->line,"integer overflow");return mk_int(res);
                }
                if(l.type==T_STRING&&r.type==T_STRING){
                    int nl=l.sval.len+r.sval.len;char*nd=xm(nl);memcpy(nd,l.sval.data,l.sval.len);memcpy(nd+l.sval.len,r.sval.data,r.sval.len);
                    return mk_str(nd,nl);
                }
                if(l.type==T_LIST&&r.type==T_LIST){
                    List*nw=list_new();nw->len=l.lval->len+r.lval->len;nw->cap=nw->len;
                    nw->items=xm(nw->len*sizeof(Value));
                    memcpy(nw->items,l.lval->items,l.lval->len*sizeof(Value));
                    memcpy(nw->items+l.lval->len,r.lval->items,r.lval->len*sizeof(Value));
                    return mk_list(nw);
                }
                die(n->line,"cannot apply + to %s and %s",tname(l.type),tname(r.type));
            }
            if(op==OP_SUB||op==OP_MUL||op==OP_DIV||op==OP_MOD){
                if(l.type!=T_INT||r.type!=T_INT)die(n->line,"cannot apply %s to %s and %s",opname(op),tname(l.type),tname(r.type));
                if(op==OP_SUB){int64_t res;if(__builtin_sub_overflow(l.ival,r.ival,&res))die(n->line,"integer overflow");return mk_int(res);}
                if(op==OP_MUL){int64_t res;if(__builtin_mul_overflow(l.ival,r.ival,&res))die(n->line,"integer overflow");return mk_int(res);}
                if(op==OP_DIV){
                    if(r.ival==0)die(n->line,"division by zero");
                    if(l.ival==INT64_MIN&&r.ival==-1)die(n->line,"integer overflow");
                    return mk_int(l.ival/r.ival);
                }
                if(op==OP_MOD){
                    if(r.ival==0)die(n->line,"division by zero");
                    if(r.ival==-1)return mk_int(0);
                    return mk_int(l.ival%r.ival);
                }
            }
            if(op==OP_LT||op==OP_LE||op==OP_GT||op==OP_GE){
                if(l.type==T_INT&&r.type==T_INT){
                    switch(op){case OP_LT:return mk_bool(l.ival<r.ival);case OP_LE:return mk_bool(l.ival<=r.ival);
                        case OP_GT:return mk_bool(l.ival>r.ival);default:return mk_bool(l.ival>=r.ival);}
                }
                if(l.type==T_STRING&&r.type==T_STRING){
                    int c=str_cmp(l,r);
                    switch(op){case OP_LT:return mk_bool(c<0);case OP_LE:return mk_bool(c<=0);
                        case OP_GT:return mk_bool(c>0);default:return mk_bool(c>=0);}
                }
                die(n->line,"cannot apply %s to %s and %s",opname(op),tname(l.type),tname(r.type));
            }
            die(n->line,"cannot apply %s to %s and %s",opname(op),tname(l.type),tname(r.type));
        }
        case AST_UNOP:{
            Value v=eval(n->un.operand,sc);
            if(n->un.op==UN_NOT)return mk_bool(!truthy(v));
            if(n->un.op==UN_NEG){
                if(v.type!=T_INT)die(n->line,"cannot apply - to %s",tname(v.type));
                if(v.ival==INT64_MIN)die(n->line,"integer overflow");
                return mk_int(-v.ival);
            }
            return mk_nil();
        }
        case AST_CALL:{
            Value callee=eval(n->call.callee,sc);
            Value*args=NULL;int nargs=n->call.nargs;
            if(nargs>0){args=xm(nargs*sizeof(Value));for(int i=0;i<nargs;i++)args[i]=eval(n->call.args[i],sc);}
            if(callee.type!=T_FUNC)die(n->line,"cannot call %s",tname(callee.type));
            Func*f=callee.fval;
            if(f->builtin_id>=0)return call_builtin(f->builtin_id,args,nargs,n->line);
            if(nargs!=f->nparams)die(n->line,"expected %d arguments, got %d",f->nparams,nargs);
            Scope*cs=scope_new(f->captured);
            for(int i=0;i<nargs;i++)scope_bind(cs,f->params[i],args[i]);
            CF c=exec_block(f->body,f->nbody,cs);
            if(c==CF_RETURN){cf=CF_NORMAL;return return_val;}
            cf=CF_NORMAL;return mk_nil();
        }
        case AST_INDEX:{
            Value obj=eval(n->index.obj,sc);Value idx=eval(n->index.idx,sc);
            if(obj.type!=T_LIST&&obj.type!=T_STRING)die(n->line,"cannot index %s with %s",tname(obj.type),tname(idx.type));
            if(idx.type!=T_INT)die(n->line,"cannot index %s with %s",tname(obj.type),tname(idx.type));
            int64_t i=idx.ival;int len=obj.type==T_LIST?obj.lval->len:obj.sval.len;
            if(i<0||i>=len)die(n->line,"index %lld out of range for length %d",(long long)i,len);
            if(obj.type==T_LIST)return obj.lval->items[i];
            return mk_str(obj.sval.data+i,1);
        }
        default:return mk_nil();
    }
}

