import Foundation

// CRC-32 lookup table
let crcTable: [UInt32] = {
    var table = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 {
            if c & 1 != 0 {
                c = 0xEDB88320 ^ (c >> 1)
            } else {
                c = c >> 1
            }
        }
        table[i] = c
    }
    return table
}()

func crc32(_ data: [UInt8]) -> UInt32 {
    var c: UInt32 = 0xFFFFFFFF
    for b in data {
        c = crcTable[Int((c ^ UInt32(b)) & 0xFF)] ^ (c >> 8)
    }
    return c ^ 0xFFFFFFFF
}

func adler32(_ data: [UInt8]) -> UInt32 {
    var a: UInt32 = 1
    var b: UInt32 = 0
    for byte in data {
        a = (a + UInt32(byte)) % 65521
        b = (b + a) % 65521
    }
    return (b << 16) | a
}

func writeBE32(_ value: UInt32) -> [UInt8] {
    return [UInt8(value >> 24), UInt8(value >> 16), UInt8(value >> 8), UInt8(value & 0xFF)]
}

func writeLE16(_ value: UInt16) -> [UInt8] {
    return [UInt8(value & 0xFF), UInt8(value >> 8)]
}

func makeChunk(type: String, data: [UInt8]) -> [UInt8] {
    var chunk: [UInt8] = []
    let typeBytes = Array(type.utf8)
    chunk.append(contentsOf: writeBE32(UInt32(data.count)))
    chunk.append(contentsOf: typeBytes)
    chunk.append(contentsOf: data)
    let crcData = typeBytes + data
    chunk.append(contentsOf: writeBE32(crc32(crcData)))
    return chunk
}

func blend(_ s: Int, _ d: Int, _ a: Int) -> Int {
    return (s * a + d * (255 - a) + 127) / 255
}

// Main program
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }

let dir = args[1]
let jsonPath = dir + "/scene.json"

guard let jsonData = FileManager.default.contents(atPath: jsonPath) else { exit(1) }
guard let scene = try? JSONSerialization.jsonObject(with: jsonData) as? [String: Any] else { exit(1) }

let width = scene["width"] as! Int
let height = scene["height"] as! Int
let bgArr = scene["background"] as! [Int]
let bgR = bgArr[0], bgG = bgArr[1], bgB = bgArr[2]
let shapesJSON = scene["shapes"] as! [[String: Any]]

// Canvas: flat array [height * width * 3]
var canvas = [Int](repeating: 0, count: height * width * 3)
for y in 0..<height {
    for x in 0..<width {
        let idx = (y * width + x) * 3
        canvas[idx] = bgR
        canvas[idx + 1] = bgG
        canvas[idx + 2] = bgB
    }
}

var shapeCounts: [Int] = []

for shape in shapesJSON {
    let type = shape["type"] as! String
    let color = shape["color"] as! [Int]
    let sR = color[0], sG = color[1], sB = color[2], A = color[3]

    var count = 0

    if type == "rect" {
        let rx = shape["x"] as! Int
        let ry = shape["y"] as! Int
        let w = shape["w"] as! Int
        let h = shape["h"] as! Int

        let xStart = max(0, rx)
        let xEnd = min(width, rx + w)
        let yStart = max(0, ry)
        let yEnd = min(height, ry + h)

        if xStart < xEnd && yStart < yEnd {
            for y in yStart..<yEnd {
                for x in xStart..<xEnd {
                    count += 1
                    if A > 0 {
                        let idx = (y * width + x) * 3
                        canvas[idx] = blend(sR, canvas[idx], A)
                        canvas[idx + 1] = blend(sG, canvas[idx + 1], A)
                        canvas[idx + 2] = blend(sB, canvas[idx + 2], A)
                    }
                }
            }
        }
    } else if type == "circle" {
        let cx = shape["cx"] as! Int
        let cy = shape["cy"] as! Int
        let r = shape["r"] as! Int
        let r2 = Int64(r) * Int64(r)

        let xStart = max(0, cx - r)
        let xEnd = min(width - 1, cx + r)
        let yStart = max(0, cy - r)
        let yEnd = min(height - 1, cy + r)

        if xStart <= xEnd && yStart <= yEnd {
            for y in yStart...yEnd {
                let dy = Int64(y - cy)
                let dy2 = dy * dy
                for x in xStart...xEnd {
                    let dx = Int64(x - cx)
                    if dx * dx + dy2 <= r2 {
                        count += 1
                        if A > 0 {
                            let idx = (y * width + x) * 3
                            canvas[idx] = blend(sR, canvas[idx], A)
                            canvas[idx + 1] = blend(sG, canvas[idx + 1], A)
                            canvas[idx + 2] = blend(sB, canvas[idx + 2], A)
                        }
                    }
                }
            }
        }
    } else if type == "triangle" {
        let pts = shape["points"] as! [[Int]]
        let px0 = pts[0][0], py0 = pts[0][1]
        let px1 = pts[1][0], py1 = pts[1][1]
        let px2 = pts[2][0], py2 = pts[2][1]

        let minX = min(px0, min(px1, px2))
        let maxX = max(px0, max(px1, px2))
        let minY = min(py0, min(py1, py2))
        let maxY = max(py0, max(py1, py2))

        let xStart = max(0, minX)
        let xEnd = min(width - 1, maxX)
        let yStart = max(0, minY)
        let yEnd = min(height - 1, maxY)

        let ex0 = Int64(px1 - px0), ey0 = Int64(py1 - py0)
        let ex1 = Int64(px2 - px1), ey1 = Int64(py2 - py1)
        let ex2 = Int64(px0 - px2), ey2 = Int64(py0 - py2)

        if xStart <= xEnd && yStart <= yEnd {
            for y in yStart...yEnd {
                let iy0 = Int64(y - py0)
                let iy1 = Int64(y - py1)
                let iy2 = Int64(y - py2)
                for x in xStart...xEnd {
                    let e0 = ex0 * iy0 - ey0 * Int64(x - px0)
                    let e1 = ex1 * iy1 - ey1 * Int64(x - px1)
                    let e2 = ex2 * iy2 - ey2 * Int64(x - px2)

                    if (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0) {
                        count += 1
                        if A > 0 {
                            let idx = (y * width + x) * 3
                            canvas[idx] = blend(sR, canvas[idx], A)
                            canvas[idx + 1] = blend(sG, canvas[idx + 1], A)
                            canvas[idx + 2] = blend(sB, canvas[idx + 2], A)
                        }
                    }
                }
            }
        }
    } else if type == "line" {
        let x1 = shape["x1"] as! Int
        let y1 = shape["y1"] as! Int
        let x2 = shape["x2"] as! Int
        let y2 = shape["y2"] as! Int
        let r = shape["r"] as! Int

        let dx = Int64(x2 - x1)
        let dy = Int64(y2 - y1)
        let L = dx * dx + dy * dy
        let r2 = Int64(r) * Int64(r)

        let xStart = max(0, min(x1, x2) - r)
        let xEnd = min(width - 1, max(x1, x2) + r)
        let yStart = max(0, min(y1, y2) - r)
        let yEnd = min(height - 1, max(y1, y2) + r)

        if xStart <= xEnd && yStart <= yEnd {
            for y in yStart...yEnd {
                let iy1 = Int64(y - y1)
                let iy2 = Int64(y - y2)
                for x in xStart...xEnd {
                    let ix1 = Int64(x - x1)
                    let ix2 = Int64(x - x2)
                    var covered = false

                    if L == 0 {
                        covered = ix1 * ix1 + iy1 * iy1 <= r2
                    } else {
                        let t = ix1 * dx + iy1 * dy
                        if t <= 0 {
                            covered = ix1 * ix1 + iy1 * iy1 <= r2
                        } else if t >= L {
                            covered = ix2 * ix2 + iy2 * iy2 <= r2
                        } else {
                            let c = ix1 * dy - iy1 * dx
                            covered = c * c <= r2 * L
                        }
                    }

                    if covered {
                        count += 1
                        if A > 0 {
                            let idx = (y * width + x) * 3
                            canvas[idx] = blend(sR, canvas[idx], A)
                            canvas[idx + 1] = blend(sG, canvas[idx + 1], A)
                            canvas[idx + 2] = blend(sB, canvas[idx + 2], A)
                        }
                    }
                }
            }
        }
    }

    shapeCounts.append(count)
}

// Print summary
for (i, cnt) in shapeCounts.enumerated() {
    let t = shapesJSON[i]["type"] as! String
    print("\(i + 1) \(t) \(cnt)")
}

// Count distinct colors
var colorSet = Set<Int>()
for y in 0..<height {
    for x in 0..<width {
        let idx = (y * width + x) * 3
        let r = canvas[idx]
        let g = canvas[idx + 1]
        let b = canvas[idx + 2]
        colorSet.insert(r * 65536 + g * 256 + b)
    }
}
print("colors \(colorSet.count)")

// Encode PNG
var pngData: [UInt8] = []

// PNG signature
pngData.append(contentsOf: [137, 80, 78, 71, 13, 10, 26, 10])

// IHDR chunk
var ihdrData: [UInt8] = []
ihdrData.append(contentsOf: writeBE32(UInt32(width)))
ihdrData.append(contentsOf: writeBE32(UInt32(height)))
ihdrData.append(8)  // bit depth
ihdrData.append(2)  // color type: RGB
ihdrData.append(0)  // compression method
ihdrData.append(0)  // filter method
ihdrData.append(0)  // interlace method
pngData.append(contentsOf: makeChunk(type: "IHDR", data: ihdrData))

// Build raw image data (scanlines with filter byte 0)
var rawData: [UInt8] = []
rawData.reserveCapacity(height * (1 + width * 3))
for y in 0..<height {
    rawData.append(0) // filter type None
    let rowStart = y * width * 3
    for x in 0..<width {
        let idx = rowStart + x * 3
        rawData.append(UInt8(canvas[idx]))
        rawData.append(UInt8(canvas[idx + 1]))
        rawData.append(UInt8(canvas[idx + 2]))
    }
}

// Zlib encode with stored blocks
var zlibData: [UInt8] = []
zlibData.append(0x78) // CMF: deflate, window 32K
zlibData.append(0x01) // FLG: check bits so (CMF*256+FLG)%31==0

let maxBlock = 65535
var offset = 0
if rawData.isEmpty {
    zlibData.append(0x01) // BFINAL=1, BTYPE=00
    zlibData.append(contentsOf: writeLE16(0))
    zlibData.append(contentsOf: writeLE16(0xFFFF))
} else {
    while offset < rawData.count {
        let blockLen = min(maxBlock, rawData.count - offset)
        let isFinal: UInt8 = (offset + blockLen >= rawData.count) ? 1 : 0
        zlibData.append(isFinal) // BFINAL in bit 0, BTYPE=00
        zlibData.append(contentsOf: writeLE16(UInt16(blockLen)))
        zlibData.append(contentsOf: writeLE16(~UInt16(blockLen)))
        zlibData.append(contentsOf: rawData[offset..<(offset + blockLen)])
        offset += blockLen
    }
}

// Adler-32 checksum of uncompressed data
zlibData.append(contentsOf: writeBE32(adler32(rawData)))

pngData.append(contentsOf: makeChunk(type: "IDAT", data: zlibData))

// IEND chunk
pngData.append(contentsOf: makeChunk(type: "IEND", data: []))

// Write output file
FileManager.default.createFile(atPath: "out.png", contents: Data(pngData))

