// MARK: - HTTP via raw sockets

func httpReq(host: String, port: Int, method: String, path: String,
             headers: [(String, String)], body: String?) -> (Int, [String: String], Data) {
    let sock = socket(AF_INET, SOCK_STREAM, 0)
    guard sock >= 0 else { fatalError("socket") }

    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = in_port_t(port).bigEndian
    inet_pton(AF_INET, host, &addr.sin_addr)

    let ret = withUnsafePointer(to: &addr) { p in
        p.withMemoryRebound(to: sockaddr.self, capacity: 1) { pp in
            connect(sock, pp, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    guard ret == 0 else { fatalError("connect") }

    var req = "\(method) \(path) HTTP/1.1\r\n"
    req += "Host: \(host):\(port)\r\n"
    for (k, v) in headers { req += "\(k): \(v)\r\n" }
    if let b = body {
        let bd = Data(b.utf8)
        req += "Content-Length: \(bd.count)\r\n"
        req += "\r\n"
        req += b
    } else {
        req += "\r\n"
    }

    let reqData = Data(req.utf8)
    var sent = 0
    while sent < reqData.count {
        let n = reqData.withUnsafeBytes { ptr in
            send(sock, ptr.baseAddress! + sent, reqData.count - sent, 0)
        }
        if n <= 0 { break }
        sent += n
    }

    var respData = Data()
    var buf = [UInt8](repeating: 0, count: 65536)
    while true {
        let n = recv(sock, &buf, buf.count, 0)
        if n <= 0 { break }
        respData.append(contentsOf: buf[0..<n])
    }
    close(sock)

    // Find \r\n\r\n
    let rd = [UInt8](respData)
    var headerEnd = -1
    for i in 0..<(rd.count &- 3) {
        if rd[i] == 13 && rd[i+1] == 10 && rd[i+2] == 13 && rd[i+3] == 10 {
            headerEnd = i + 4
            break
        }
    }
    guard headerEnd > 0 else { return (0, [:], Data()) }

    let headerStr = String(data: respData[0..<headerEnd], encoding: .utf8)!
    let lines = headerStr.components(separatedBy: "\r\n")
    let status = Int(lines[0].split(separator: " ")[1])!

    var hdrs: [String: String] = [:]
    for i in 1..<lines.count {
        if lines[i].isEmpty { continue }
        if let ci = lines[i].firstIndex(of: ":") {
            let k = String(lines[i][lines[i].startIndex..<ci]).lowercased()
            let v = String(lines[i][lines[i].index(after: ci)...]).trimmingCharacters(in: .whitespaces)
            hdrs[k] = v
        }
    }

    var bodyData = Data()
    let rawBody = rd[headerEnd...]

    if let te = hdrs["transfer-encoding"], te.lowercased().contains("chunked") {
        var pos = 0
        while pos < rawBody.count {
            var lineEnd = pos
            while lineEnd + 1 < rawBody.count {
                if rawBody[lineEnd] == 13 && rawBody[lineEnd + 1] == 10 { break }
                lineEnd += 1
            }
            guard lineEnd < rawBody.count else { break }
            let sizeStr = String(data: Data(rawBody[pos..<lineEnd]), encoding: .utf8)!
                .trimmingCharacters(in: .whitespaces)
            // Handle chunk extensions (e.g., "5;ext")
            let cleanSize = sizeStr.split(separator: ";").first.map(String.init) ?? sizeStr
            let chunkSize = Int(cleanSize, radix: 16) ?? 0
            if chunkSize == 0 { break }
            let chunkStart = lineEnd + 2
            let chunkEnd = min(chunkStart + chunkSize, rawBody.count)
            bodyData.append(contentsOf: rawBody[chunkStart..<chunkEnd])
            pos = chunkEnd + 2
        }
    } else if let cl = hdrs["content-length"] {
        let len = Int(cl)!
        let end = min(len, rawBody.count)
        bodyData = Data(rawBody[0..<end])
    } else {
        bodyData = Data(rawBody)
    }

    return (status, hdrs, bodyData)
}

// MARK: - Amount parsing and formatting

func parseAmount(_ s: String) -> Int64 {
    let chars = Array(s)
    var i = 0
    var negative = false
    if chars[0] == "-" { negative = true; i = 1 }
    var intPart: Int64 = 0
    while i < chars.count && chars[i] != "." {
        intPart = intPart * 10 + Int64(chars[i].wholeNumberValue!)
        i += 1
    }
    var fracPart: Int64 = 0
    if i < chars.count && chars[i] == "." {
        i += 1
        var d = 0
        while i < chars.count && d < 2 {
            fracPart = fracPart * 10 + Int64(chars[i].wholeNumberValue!)
            d += 1; i += 1
        }
        if d == 1 { fracPart *= 10 }
    }
    let cents = intPart * 100 + fracPart
    return negative ? -cents : cents
}

func formatCents(_ cents: Int64) -> String {
    let neg = cents < 0
    let ac: Int64 = neg ? -cents : cents
    let ip = ac / 100
    let fp = ac % 100
    let sign = neg ? "-" : ""
    return "\(sign)\(ip).\(String(format: "%02d", fp))"
}

