import Foundation

// MARK: - URL Parsing

func parseBaseURL(_ url: String) -> (host: String, port: Int, basePath: String) {
    var s = url
    if s.hasPrefix("http://") { s = String(s.dropFirst(7)) }
    else if s.hasPrefix("https://") { s = String(s.dropFirst(8)) }
    let slashIdx = s.firstIndex(of: "/")
    let hostPort: Substring
    let basePath: String
    if let idx = slashIdx {
        hostPort = s[s.startIndex..<idx]
        basePath = String(s[idx...])
    } else {
        hostPort = s[s.startIndex...]
        basePath = ""
    }
    let colonIdx = hostPort.lastIndex(of: ":")
    let host: String
    let port: Int
    if let idx = colonIdx {
        host = String(hostPort[hostPort.startIndex..<idx])
        port = Int(hostPort[hostPort.index(after: idx)...])!
    } else {
        host = String(hostPort)
        port = 80
    }
    return (host, port, basePath)
}

// MARK: - Encoding

func formURLEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 0x41 && byte <= 0x5A) ||
           (byte >= 0x61 && byte <= 0x7A) ||
           (byte >= 0x30 && byte <= 0x39) ||
           byte == 0x2D || byte == 0x2E || byte == 0x5F || byte == 0x2A {
            result.append(Character(UnicodeScalar(byte)))
        } else if byte == 0x20 {
            result.append("+")
        } else {
            result += String(format: "%%%02X", byte)
        }
    }
    return result
}

func percentEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 0x41 && byte <= 0x5A) ||
           (byte >= 0x61 && byte <= 0x7A) ||
           (byte >= 0x30 && byte <= 0x39) ||
           byte == 0x2D || byte == 0x2E || byte == 0x5F || byte == 0x7E {
            result.append(Character(UnicodeScalar(byte)))
        } else {
            result += String(format: "%%%02X", byte)
        }
    }
    return result
}

// MARK: - Lexicographic byte comparison

func lexicographicCompare(_ a: [UInt8], _ b: [UInt8]) -> Bool {
    let minLen = min(a.count, b.count)
    for i in 0..<minLen {
        if a[i] < b[i] { return true }
        if a[i] > b[i] { return false }
    }
    return a.count < b.count
}

