#!/usr/bin/env python3
import sys
import os
import base64
import struct

# ==================== TOKENIZER ====================

def remove_comments(text):
    result = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == '"':
            result.append(text[i])
            i += 1
            while i < n and text[i] != '"':
                result.append(text[i])
                i += 1
            if i < n:
                result.append(text[i])
                i += 1
        elif text[i:i+2] == '//':
            while i < n and text[i] != '\n':
                i += 1
        elif text[i:i+2] == '/*':
            i += 2
            while i < n and text[i:i+2] != '*/':
                i += 1
            if i < n:
                i += 2
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

def tokenize(text):
    text = remove_comments(text)
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c in ' \t\r\n':
            i += 1
        elif c == '"':
            j = i + 1
            while j < n and text[j] != '"':
                j += 1
            tokens.append(('STRING', text[i+1:j]))
            i = j + 1
        elif c in '{}[]=,;<>().':
            tokens.append(('PUNCT', c))
            i += 1
        elif c == '-' or c.isdigit():
            j = i
            if text[j] == '-':
                j += 1
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(('NUMBER', int(text[i:j])))
            i = j
        elif c.isalpha() or c == '_':
            j = i
            while j < n and (text[j].isalnum() or text[j] == '_'):
                j += 1
            tokens.append(('IDENT', text[i:j]))
            i = j
        else:
            i += 1
    return tokens

