        self.enum_def = None
        self.message_def = None

class MessageDef:
    def __init__(self):
        self.name = ""
        self.fields = {}
        self.oneofs = {}

class EnumDef:
    def __init__(self):
        self.name = ""
        self.values = {}

class Schema:
    def __init__(self):
        self.root_message = None
        self.messages = {}
        self.enums = {}

# ==================== PARSER ====================

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return ('EOF', None)

    def next(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind, value=None):
        tok = self.next()
        if tok[0] != kind:
            raise ValueError(f"Expected {kind} but got {tok}")
        if value is not None and tok[1] != value:
            raise ValueError(f"Expected '{value}' but got '{tok[1]}'")
        return tok

    def parse_file(self):
        schema = Schema()
        while self.pos < len(self.tokens):
            tok = self.peek()
            if tok[0] == 'IDENT':
                name = tok[1]
                if name == 'syntax':
                    self.parse_syntax()
                elif name == 'package':
                    self.parse_package()
                elif name == 'option':
                    self.parse_option()
                elif name == 'message':
                    msg = self.parse_message(schema)
                    if schema.root_message is None:
                        schema.root_message = msg
                elif name == 'enum':
                    self.parse_enum(schema)
                else:
                    self.pos += 1
            else:
                self.pos += 1
        return schema

    def parse_syntax(self):
        self.expect('IDENT', 'syntax')
        self.expect('PUNCT', '=')
        self.next()
        self.expect('PUNCT', ';')

    def parse_package(self):
        self.expect('IDENT', 'package')
        while self.pos < len(self.tokens) and self.peek() != ('PUNCT', ';'):
            self.pos += 1
        self.expect('PUNCT', ';')

    def parse_option(self):
        self.expect('IDENT', 'option')
        while self.pos < len(self.tokens) and self.peek() != ('PUNCT', ';'):
            self.pos += 1
        self.expect('PUNCT', ';')

    def parse_field_options(self):
        self.expect('PUNCT', '[')
        depth = 1
        while self.pos < len(self.tokens) and depth > 0:
            tok = self.peek()
            if tok == ('PUNCT', '['):
                depth += 1
            elif tok == ('PUNCT', ']'):
                depth -= 1
                if depth == 0:
                    self.pos += 1
                    return
            self.pos += 1

    def parse_message(self, schema):
        self.expect('IDENT', 'message')
        name_tok = self.expect('IDENT')
        msg = MessageDef()
        msg.name = name_tok[1]
        schema.messages[msg.name] = msg
        self.expect('PUNCT', '{')
        self.parse_message_body(msg, schema)
        self.expect('PUNCT', '}')
        return msg

    def parse_message_body(self, msg, schema):
        while self.peek() != ('PUNCT', '}'):
            tok = self.peek()
            if tok[0] != 'IDENT':
                self.pos += 1
                continue
            name = tok[1]
            if name == 'message':
                self.parse_message(schema)
            elif name == 'enum':
                self.parse_enum(schema)
            elif name == 'oneof':
                self.parse_oneof(msg, schema)
            elif name == 'reserved':
                self.parse_reserved()
            elif name == 'option':
                self.parse_option()
            elif name == 'map':
                self.parse_map_field(msg, schema)
            elif name in ('repeated', 'optional'):
                self.parse_field(msg, schema)
            else:
                self.parse_field(msg, schema)

    def parse_field(self, msg, schema):
        field = FieldDef()
        tok = self.peek()
        if tok[0] == 'IDENT' and tok[1] in ('repeated', 'optional'):
            field.label = tok[1]
            self.pos += 1
        type_tok = self.expect('IDENT')
        field.type_name = type_tok[1]
        name_tok = self.expect('IDENT')
        field.name = name_tok[1]
        self.expect('PUNCT', '=')
        num_tok = self.expect('NUMBER')
        field.number = num_tok[1]
        if self.peek() == ('PUNCT', '['):
            self.parse_field_options()
        self.expect('PUNCT', ';')
        msg.fields[field.number] = field

    def parse_map_field(self, msg, schema):
        field = FieldDef()
        field.is_map = True
        field.label = "repeated"
        self.expect('IDENT', 'map')
        self.expect('PUNCT', '<')
        key_tok = self.expect('IDENT')
        field.map_key_type = key_tok[1]
        self.expect('PUNCT', ',')
        val_tok = self.expect('IDENT')
        field.map_value_type = val_tok[1]
        self.expect('PUNCT', '>')
        name_tok = self.expect('IDENT')
        field.name = name_tok[1]
        self.expect('PUNCT', '=')
        num_tok = self.expect('NUMBER')
        field.number = num_tok[1]
        if self.peek() == ('PUNCT', '['):
            self.parse_field_options()
        self.expect('PUNCT', ';')
        msg.fields[field.number] = field

    def parse_oneof(self, msg, schema):
        self.expect('IDENT', 'oneof')
        name_tok = self.expect('IDENT')
        oneof_name = name_tok[1]
        msg.oneofs[oneof_name] = set()
        self.expect('PUNCT', '{')
        while self.peek() != ('PUNCT', '}'):
            tok = self.peek()
            if tok[0] == 'IDENT':
                if tok[1] == 'option':
                    self.parse_option()
                elif tok[1] == 'reserved':
                    self.parse_reserved()
                else:
                    field = FieldDef()
                    field.oneof = oneof_name
                    type_tok = self.expect('IDENT')
                    field.type_name = type_tok[1]
                    name_tok2 = self.expect('IDENT')
                    field.name = name_tok2[1]
                    self.expect('PUNCT', '=')
                    num_tok = self.expect('NUMBER')
                    field.number = num_tok[1]
                    if self.peek() == ('PUNCT', '['):
                        self.parse_field_options()
                    self.expect('PUNCT', ';')
                    msg.fields[field.number] = field
                    msg.oneofs[oneof_name].add(field.number)
            else:
                self.pos += 1
        self.expect('PUNCT', '}')

    def parse_reserved(self):
        self.expect('IDENT', 'reserved')
        while self.pos < len(self.tokens) and self.peek() != ('PUNCT', ';'):
            self.pos += 1
        self.expect('PUNCT', ';')

    def parse_enum(self, schema):
        self.expect('IDENT', 'enum')
        name_tok = self.expect('IDENT')
        enum = EnumDef()
        enum.name = name_tok[1]
        schema.enums[enum.name] = enum
        self.expect('PUNCT', '{')
        while self.peek() != ('PUNCT', '}'):
            tok = self.peek()
            if tok[0] == 'IDENT':
                if tok[1] == 'option':
                    self.parse_option()
                elif tok[1] == 'reserved':
                    self.parse_reserved()
                else:
                    val_name = self.expect('IDENT')
                    self.expect('PUNCT', '=')
                    num_tok = self.expect('NUMBER')
                    if self.peek() == ('PUNCT', '['):
                        self.parse_field_options()
                    self.expect('PUNCT', ';')
                    enum.values[num_tok[1]] = val_name[1]
            else:
                self.pos += 1
        self.expect('PUNCT', '}')

# ==================== TYPE RESOLUTION ====================

SCALAR_TYPES = frozenset({'int32', 'int64', 'uint32', 'uint64', 'sint32', 'sint64',
                          'bool', 'string', 'bytes', 'fixed32', 'fixed64',
                          'sfixed32', 'sfixed64'})

def resolve_types(schema):
    for msg in schema.messages.values():
        for field in msg.fields.values():
            if field.is_map:
                vtype = field.map_value_type
                if vtype not in SCALAR_TYPES:
                    if vtype in schema.messages:
                        field.is_message = True
                        field.message_def = schema.messages[vtype]
                    elif vtype in schema.enums:
                        field.is_enum = True
                        field.enum_def = schema.enums[vtype]
            else:
                tname = field.type_name
                if tname not in SCALAR_TYPES:
                    if tname in schema.messages:
                        field.is_message = True
                        field.message_def = schema.messages[tname]
                    elif tname in schema.enums:
                        field.is_enum = True
                        field.enum_def = schema.enums[tname]

# ==================== VARINT / PROTOBUF DECODING ====================

def read_varint(data, offset):
    result = 0
    shift = 0
    while True:
        byte = data[offset]
        offset += 1
        result |= (byte & 0x7F) << shift
        if (byte & 0x80) == 0:
            break
        shift += 7
    return result, offset

def to_signed_32(n):
    n = n & 0xFFFFFFFF
    if n >= 0x80000000:
        n -= 0x100000000
    return n

def to_signed_64(n):
    n = n & 0xFFFFFFFFFFFFFFFF
    if n >= 0x8000000000000000:
        n -= 0x10000000000000000
    return n

def zigzag_decode(n):
    return (n >> 1) ^ -(n & 1)

def skip_value(data, offset, wire_type):
    if wire_type == 0:
        _, offset = read_varint(data, offset)
    elif wire_type == 1:
        offset += 8
    elif wire_type == 2:
        length, offset = read_varint(data, offset)
        offset += length
    elif wire_type == 5:
        offset += 4
    elif wire_type == 3:
        offset = skip_group(data, offset)
    elif wire_type == 4:
        pass
    return offset

def skip_group(data, offset):
    while offset < len(data):
        key, offset = read_varint(data, offset)
        wt = key & 7
        if wt == 4:
            break
        offset = skip_value(data, offset, wt)
    return offset

def decode_varint_as_type(raw, type_name):
    if type_name == 'int32':
        return to_signed_32(raw)
    elif type_name == 'int64':
        return to_signed_64(raw)
    elif type_name == 'uint32':
        return raw
    elif type_name == 'uint64':
        return raw
    elif type_name == 'sint32':
        return zigzag_decode(raw)
    elif type_name == 'sint64':
        return zigzag_decode(raw)
    elif type_name == 'bool':
        return raw != 0
    return raw

def decode_fixed32_as_type(data, offset, type_name):
    val = struct.unpack_from('<I', data, offset)[0]
    if type_name == 'sfixed32':
        return struct.unpack_from('<i', data, offset)[0]
    return val

def decode_fixed64_as_type(data, offset, type_name):
    val = struct.unpack_from('<Q', data, offset)[0]
    if type_name == 'sfixed64':
        return struct.unpack_from('<q', data, offset)[0]
    return val

def decode_packed_element(data, offset, type_name):
    if type_name in ('int32', 'int64', 'uint32', 'uint64', 'sint32', 'sint64', 'bool'):
        raw, offset = read_varint(data, offset)
        return decode_varint_as_type(raw, type_name), offset
    elif type_name in ('fixed32', 'sfixed32'):
        val = decode_fixed32_as_type(data, offset, type_name)
        return val, offset + 4
    elif type_name in ('fixed64', 'sfixed64'):
        val = decode_fixed64_as_type(data, offset, type_name)
        return val, offset + 8
    return 0, offset

# ==================== MESSAGE DECODING ====================

def decode_message(data, msg_def, schema):
    values = {}
    present = set()
    oneof_set = {}
    offset = 0
    n = len(data)

    while offset < n:
        key, offset = read_varint(data, offset)
        field_num = key >> 3
        wire_type = key & 7

        if field_num not in msg_def.fields:
            offset = skip_value(data, offset, wire_type)
            continue

        field = msg_def.fields[field_num]

        if field.oneof is not None:
            prev = oneof_set.get(field.oneof)
            if prev is not None and prev != field_num:
                present.discard(prev)
                values.pop(prev, None)
            oneof_set[field.oneof] = field_num

        if field.is_map:
            if wire_type == 2:
                length, offset = read_varint(data, offset)
                entry_data = data[offset:offset+length]
                offset += length
                key_val, val_val = decode_map_entry(entry_data, field, schema)
                if field_num not in values:
                    values[field_num] = {}
                values[field_num][key_val] = val_val
                present.add(field_num)
            else:
                offset = skip_value(data, offset, wire_type)

        elif field.label == 'repeated':
            if field_num not in values:
                values[field_num] = []

            if field.is_message:
                if wire_type == 2:
                    length, offset = read_varint(data, offset)
                    sub_data = data[offset:offset+length]
                    offset += length
                    values[field_num].append(decode_message(sub_data, field.message_def, schema))
                else:
                    offset = skip_value(data, offset, wire_type)
            elif field.is_enum:
                if wire_type == 2:
                    length, offset = read_varint(data, offset)
                    end = offset + length
                    while offset < end:
                        raw, offset = read_varint(data, offset)
                        values[field_num].append(to_signed_32(raw))
                elif wire_type == 0:
                    raw, offset = read_varint(data, offset)
                    values[field_num].append(to_signed_32(raw))
                else:
                    offset = skip_value(data, offset, wire_type)
            elif field.type_name in ('string', 'bytes'):
                if wire_type == 2:
                    length, offset = read_varint(data, offset)
                    raw_bytes = data[offset:offset+length]
                    offset += length
                    if field.type_name == 'string':
                        values[field_num].append(raw_bytes.decode('utf-8'))
                    else:
                        values[field_num].append(raw_bytes)
                else:
                    offset = skip_value(data, offset, wire_type)
            else:
                if wire_type == 2:
                    length, offset = read_varint(data, offset)
                    end = offset + length
                    while offset < end:
                        val, offset = decode_packed_element(data, offset, field.type_name)
                        values[field_num].append(val)
                elif wire_type == 0:
                    raw, offset = read_varint(data, offset)
                    values[field_num].append(decode_varint_as_type(raw, field.type_name))
                elif wire_type == 5:
                    val = decode_fixed32_as_type(data, offset, field.type_name)
                    offset += 4
                    values[field_num].append(val)
                elif wire_type == 1:
                    val = decode_fixed64_as_type(data, offset, field.type_name)
                    offset += 8
                    values[field_num].append(val)
                else:
                    offset = skip_value(data, offset, wire_type)
            present.add(field_num)

        elif field.is_message:
            if wire_type == 2:
                length, offset = read_varint(data, offset)
                sub_data = data[offset:offset+length]
                offset += length
                if field_num in values:
                    old_result = values[field_num]
                    new_result = decode_message(sub_data, field.message_def, schema)
                    values[field_num] = merge_messages(old_result, new_result, field.message_def, schema)
                else:
                    values[field_num] = decode_message(sub_data, field.message_def, schema)
                present.add(field_num)
            else:
                offset = skip_value(data, offset, wire_type)

        else:
            # singular scalar
            if field.type_name == 'string':
                if wire_type == 2:
                    length, offset = read_varint(data, offset)
                    raw_bytes = data[offset:offset+length]
                    offset += length
                    values[field_num] = raw_bytes.decode('utf-8')
                else:
                    offset = skip_value(data, offset, wire_type)
            elif field.type_name == 'bytes':
                if wire_type == 2:
                    length, offset = read_varint(data, offset)
                    raw_bytes = data[offset:offset+length]
                    offset += length
                    values[field_num] = raw_bytes
                else:
                    offset = skip_value(data, offset, wire_type)
            elif field.is_enum:
                if wire_type == 0:
                    raw, offset = read_varint(data, offset)
                    values[field_num] = to_signed_32(raw)
                else:
                    offset = skip_value(data, offset, wire_type)
            else:
                if wire_type == 0:
                    raw, offset = read_varint(data, offset)
                    values[field_num] = decode_varint_as_type(raw, field.type_name)
                elif wire_type == 5:
                    values[field_num] = decode_fixed32_as_type(data, offset, field.type_name)
                    offset += 4
                elif wire_type == 1:
                    values[field_num] = decode_fixed64_as_type(data, offset, field.type_name)
                    offset += 8
                else:
                    offset = skip_value(data, offset, wire_type)
            present.add(field_num)

    return values, present, oneof_set

def merge_messages(old_result, new_result, msg_def, schema):
    old_values, old_present, old_oneof = old_result
    new_values, new_present, new_oneof = new_result

    merged_values = dict(old_values)
    merged_present = set(old_present)
    merged_oneof = dict(old_oneof)

    for oneof_name, new_field in new_oneof.items():
        old_field = merged_oneof.get(oneof_name)
        if old_field is not None and old_field != new_field:
            merged_present.discard(old_field)
            merged_values.pop(old_field, None)
        merged_oneof[oneof_name] = new_field

    for field_num in new_values:
        field = msg_def.fields.get(field_num)
        if field is None:
            continue
        if field.label == 'repeated':
            if field_num in merged_values:
                merged_values[field_num].extend(new_values[field_num])
            else:
                merged_values[field_num] = list(new_values[field_num])
        elif field.is_map:
            if field_num in merged_values:
                merged_values[field_num].update(new_values[field_num])
            else:
                merged_values[field_num] = dict(new_values[field_num])
        elif field.is_message:
            if field_num in merged_values:
                merged_values[field_num] = merge_messages(
                    merged_values[field_num], new_values[field_num],
                    field.message_def, schema)
            else:
                merged_values[field_num] = new_values[field_num]
        else:
            merged_values[field_num] = new_values[field_num]

    merged_present.update(new_present)
    return merged_values, merged_present, merged_oneof

def decode_map_entry(data, field, schema):
    key = None
    val = None
    offset = 0
    n = len(data)

    while offset < n:
        k, offset = read_varint(data, offset)
        fn = k >> 3
        wt = k & 7

        if fn == 1:
            if field.map_key_type == 'string':
                if wt == 2:
                    length, offset = read_varint(data, offset)
                    key = data[offset:offset+length].decode('utf-8')
                    offset += length
                else:
                    offset = skip_value(data, offset, wt)
            elif field.map_key_type == 'int32':
                if wt == 0:
                    raw, offset = read_varint(data, offset)
                    key = to_signed_32(raw)
                else:
                    offset = skip_value(data, offset, wt)
            else:
                offset = skip_value(data, offset, wt)
        elif fn == 2:
            if field.is_message:
                if wt == 2:
                    length, offset = read_varint(data, offset)
                    sub_data = data[offset:offset+length]
                    offset += length
                    val = decode_message(sub_data, field.message_def, schema)
                else:
                    offset = skip_value(data, offset, wt)
            elif field.is_enum:
                if wt == 0:
                    raw, offset = read_varint(data, offset)
                    val = to_signed_32(raw)
                else:
                    offset = skip_value(data, offset, wt)
            elif field.map_value_type == 'string':
                if wt == 2:
                    length, offset = read_varint(data, offset)
                    val = data[offset:offset+length].decode('utf-8')
                    offset += length
                else:
                    offset = skip_value(data, offset, wt)
            elif field.map_value_type == 'bytes':
                if wt == 2:
                    length, offset = read_varint(data, offset)
                    val = data[offset:offset+length]
                    offset += length
                else:
                    offset = skip_value(data, offset, wt)
            elif field.map_value_type in ('fixed32', 'sfixed32'):
                if wt == 5:
                    val = decode_fixed32_as_type(data, offset, field.map_value_type)
                    offset += 4
                else:
                    offset = skip_value(data, offset, wt)
            elif field.map_value_type in ('fixed64', 'sfixed64'):
                if wt == 1:
                    val = decode_fixed64_as_type(data, offset, field.map_value_type)
                    offset += 8
                else:
                    offset = skip_value(data, offset, wt)
            else:
                if wt == 0:
                    raw, offset = read_varint(data, offset)
                    val = decode_varint_as_type(raw, field.map_value_type)
                else:
                    offset = skip_value(data, offset, wt)
        else:
            offset = skip_value(data, offset, wt)

    if key is None:
        key = "" if field.map_key_type == 'string' else 0
    if val is None:
        if field.is_message:
            val = ({}, set(), {})
        elif field.is_enum:
            val = 0
        elif field.map_value_type == 'string':
            val = ""
        elif field.map_value_type == 'bytes':
            val = b""
        elif field.map_value_type == 'bool':
            val = False
        else:
            val = 0
    return key, val

# ==================== JSON OUTPUT ====================

def lower_camel_case(name):
    result = []
    i = 0
    while i < len(name):
        if name[i] == '_':
            i += 1
            if i < len(name) and name[i].islower() and name[i].isascii():
                result.append(name[i].upper())
                i += 1
        else:
            result.append(name[i])
            i += 1
    return ''.join(result)

def escape_json_string(s):
    parts = []
    for c in s:
        if c == '"':
            parts.append('\\"')
        elif c == '\\':
            parts.append('\\\\')
        elif c == '\b':
            parts.append('\\b')
        elif c == '\t':
            parts.append('\\t')
        elif c == '\n':
            parts.append('\\n')
        elif c == '\f':
            parts.append('\\f')
        elif c == '\r':
            parts.append('\\r')
        elif ord(c) < 0x20:
            parts.append('\\u{:04x}'.format(ord(c)))
        else:
            parts.append(c)
    return '"' + ''.join(parts) + '"'

def is_default_scalar(value, field):
    if field.type_name == 'string':
        return value == ""
    elif field.type_name == 'bytes':
        return value == b""
    elif field.type_name == 'bool':
        return value == False
    elif field.is_enum:
        return value == 0
    else:
        return value == 0

def encode_scalar_json(value, type_name, field):
    if field.is_enum:
        enum_def = field.enum_def
        if value in enum_def.values:
            return escape_json_string(enum_def.values[value])
        else:
            return str(value)
    elif type_name == 'string':
        return escape_json_string(value)
    elif type_name == 'bytes':
        return escape_json_string(base64.b64encode(value).decode('ascii'))
    elif type_name == 'bool':
        return 'true' if value else 'false'
    elif type_name in ('int64', 'uint64', 'sint64', 'fixed64', 'sfixed64'):
        return '"{}"'.format(value)
    elif type_name in ('int32', 'uint32', 'sint32', 'fixed32', 'sfixed32'):
        return str(value)
    return str(value)

def encode_map_value_json(value, field):
    if field.is_message:
        return message_to_json(value[0], value[1], value[2], field.message_def)
    elif field.is_enum:
        if value in field.enum_def.values:
            return escape_json_string(field.enum_def.values[value])
        else:
            return str(value)
    elif field.map_value_type == 'string':
        return escape_json_string(value)
    elif field.map_value_type == 'bytes':
        return escape_json_string(base64.b64encode(value).decode('ascii'))
    elif field.map_value_type == 'bool':
        return 'true' if value else 'false'
    elif field.map_value_type in ('int64', 'uint64', 'sint64', 'fixed64', 'sfixed64'):
        return '"{}"'.format(value)
    else:
        return str(value)

def message_to_json(values, present, oneof_set, msg_def):
    parts = []
    for field_num in sorted(msg_def.fields.keys()):
        field = msg_def.fields[field_num]

