// ============ Binary Decoder Helpers ============

func readVarint(_ data: [UInt8], _ pos: inout Int) -> UInt64 {
    var result: UInt64 = 0
    var shift: UInt64 = 0
    while pos < data.count {
        let byte = data[pos]; pos += 1
        result |= UInt64(byte & 0x7F) << shift
        if byte & 0x80 == 0 { break }
        shift += 7
    }
    return result
}

func isNumericType(_ name: String) -> Bool {
