    case "int32","int64","uint32","uint64","sint32","sint64","bool": return 0
    case "fixed32","sfixed32": return 5
    case "fixed64","sfixed64": return 1
    default: return enums[name] != nil ? 0 : 2
    }
}

func skipGroup(_ data: [UInt8], _ pos: inout Int, _ fieldNumber: Int) {
    while pos < data.count {
        let key = readVarint(data, &pos)
        let fn = Int(key >> 3)
        let wt = Int(key & 0x07)
        if wt == 4 && fn == fieldNumber { return }
        switch wt {
        case 0: _ = readVarint(data, &pos)
        case 1: pos += 8
        case 2: let len = Int(readVarint(data, &pos)); pos += len
        case 3: skipGroup(data, &pos, fn)
        case 5: pos += 4
        default: break
        }
    }
}

func clearField(_ msg: DMsg, _ fn: Int) {
