        case 2:
            let len = Int(readVarint(data, &pos))
            if pos + len <= data.count { rawVal = .bytes(Array(data[pos..<pos+len])); pos += len }
            else { rawVal = nil }
        case 5:
            if pos + 4 <= data.count {
                var v: UInt32 = 0
                for i in 0..<4 { v |= UInt32(data[pos+i]) << (8*i) }
                pos += 4; rawVal = .fixed32(v)
