        case "int64": return "\"\(Int64(bitPattern: v))\""
        case "uint32": return "\(UInt32(truncatingIfNeeded: v))"
        case "uint64": return "\"\(v)\""
        case "sint32":
            let u = UInt32(truncatingIfNeeded: v)
            return "\(Int32(bitPattern: (u >> 1) ^ (0 &- (u & 1))))"
        case "sint64":
            return "\"\(Int64(bitPattern: (v >> 1) ^ (0 &- (v & 1))))\""
        case "bool": return v != 0 ? "true" : "false"
        default:
            if let ed = enums[typeName] {
                let ev = Int(Int32(truncatingIfNeeded: v))
                if let n = ed.values[ev] { return "\"\(n)\"" }
                return "\(ev)"
            }
            return "\(v)"
        }
    case .fixed64(let v):
        switch typeName {
        case "sfixed64": return "\"\(Int64(bitPattern: v))\""
        default: return "\"\(v)\""
        }
    case .fixed32(let v):
        switch typeName {
        case "sfixed32": return "\(Int32(bitPattern: v))"
        default: return "\(v)"
        }
    case .bytes(let v):
        switch typeName {
        case "string":
            let s = String(bytes: v, encoding: .utf8) ?? ""
            return escapeJSONString(s)
        default:
            return "\"\(Data(v).base64EncodedString())\""
        }
    }
}

func defaultScalarJSON(_ typeName: String) -> String {
    switch typeName {
    case "string","bytes": return "\"\""
    case "bool": return "false"
    case "int32","uint32","sint32","fixed32","sfixed32": return "0"
    case "int64","uint64","sint64","fixed64","sfixed64": return "\"0\""
    default:
        if let ed = enums[typeName] { if let n = ed.values[0] { return "\"\(n)\"" } }
        return "0"
    }
}

func outputSingularValue(_ msg: DMsg, fn: Int, fd: FieldDef) -> String {
    if isMessageType(fd.typeName) {
        if let sub = msg.msgFields[fn] { return outputMessage(sub, schema: messages[fd.typeName]!) }
        return "{}"
    } else {
        if let val = msg.scalarFields[fn] { return outputScalar(val, typeName: fd.typeName) }
        return defaultScalarJSON(fd.typeName)
    }
}

func outputRepeated(_ msg: DMsg, fn: Int, fd: FieldDef) -> String {
    var parts: [String] = []
    if let scalars = msg.repeatedScalarFields[fn] {
        for val in scalars { parts.append(outputScalar(val, typeName: fd.typeName)) }
    }
    if let msgs = msg.repeatedMsgFields[fn] {
        let subSchema = messages[fd.typeName]!
        for m in msgs { parts.append(outputMessage(m, schema: subSchema)) }
    }
    return "[" + parts.joined(separator: ",") + "]"
}

func outputMap(_ entries: [MapEntry], fd: FieldDef) -> String {
    let kt = fd.keyType!
    var sorted = entries
    if kt == "int32" {
        sorted.sort { a, b in
            let ka: Int32
            let kb: Int32
            if case .varint(let v) = a.key { ka = Int32(truncatingIfNeeded: v) } else { ka = 0 }
            if case .varint(let v) = b.key { kb = Int32(truncatingIfNeeded: v) } else { kb = 0 }
            return ka < kb
        }
    } else {
        sorted.sort { a, b in
            let ba: [UInt8]
            let bb: [UInt8]
            if case .bytes(let v) = a.key { ba = v } else { ba = [] }
            if case .bytes(let v) = b.key { bb = v } else { bb = [] }
            return ba.lexicographicallyPrecedes(bb)
        }
    }
    var parts: [String] = []
    for entry in sorted {
        let keyJSON: String
        if kt == "int32" {
            let k: Int32
            if case .varint(let v) = entry.key { k = Int32(truncatingIfNeeded: v) } else { k = 0 }
            keyJSON = "\"\(k)\""
        } else {
            let s: String
            if case .bytes(let v) = entry.key { s = String(bytes: v, encoding: .utf8) ?? "" } else { s = "" }
            keyJSON = escapeJSONString(s)
        }
        let valStr: String
        switch entry.value {
        case .scalar(let sv): valStr = outputScalar(sv, typeName: fd.typeName)
        case .message(let m): valStr = outputMessage(m, schema: messages[fd.typeName]!)
        }
        parts.append("\(keyJSON):\(valStr)")
    }
    return "{" + parts.joined(separator: ",") + "}"
}

func outputMessage(_ msg: DMsg, schema: MessageDef) -> String {
    var parts: [String] = []
    let fieldNumbers = schema.fields.keys.sorted()
    for fn in fieldNumbers {
        let fd = schema.fields[fn]!
        let jn = toCamelCase(fd.name)
        if fd.isMap {
            guard let entries = msg.mapFields[fn], !entries.isEmpty else { continue }
            parts.append("\"\(jn)\":\(outputMap(entries, fd: fd))")
        } else if fd.label == .repeated {
            let sc = msg.repeatedScalarFields[fn]?.count ?? 0
            let mc = msg.repeatedMsgFields[fn]?.count ?? 0
            if sc + mc == 0 { continue }
            parts.append("\"\(jn)\":\(outputRepeated(msg, fn: fn, fd: fd))")
        } else if fd.oneofName != nil {
            if let sf = msg.oneofSet[fd.oneofName!], sf == fn {
                parts.append("\"\(jn)\":\(outputSingularValue(msg, fn: fn, fd: fd))")
            }
        } else if fd.label == .optional {
            if msg.seen.contains(fn) {
                parts.append("\"\(jn)\":\(outputSingularValue(msg, fn: fn, fd: fd))")
            }
        } else {
            if isMessageType(fd.typeName) {
                if msg.msgFields[fn] != nil {
                    parts.append("\"\(jn)\":\(outputMessage(msg.msgFields[fn]!, schema: messages[fd.typeName]!))")
                }
            } else {
                if let val = msg.scalarFields[fn] {
                    if !isDefaultValue(val) {
                        parts.append("\"\(jn)\":\(outputScalar(val, typeName: fd.typeName))")
                    }
                }
            }
        }
    }
    return "{" + parts.joined(separator: ",") + "}"
}

// ============ Main ============

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

guard let schemaData = FileManager.default.contents(atPath: dir + "/schema.proto"),
      let schemaStr = String(data: schemaData, encoding: .utf8) else { exit(1) }

let toks = protoTokenize(schemaStr)
let parser = ProtoParser(toks)
parser.parseFile()

guard let binData = FileManager.default.contents(atPath: dir + "/messages.bin") else { exit(1) }
let bytes = [UInt8](binData)

let rootSchema = messages[rootMessageName]!
var pos = 0
while pos < bytes.count {
    let len = Int(readVarint(bytes, &pos))
    if pos + len > bytes.count { break }
    let recordBytes = Array(bytes[pos..<pos+len])
    pos += len
    let decoded = DMsg()
    decodeMessageInto(decoded, recordBytes, rootSchema)
    print(outputMessage(decoded, schema: rootSchema))
}

exit(0)

import Foundation

// ============ Schema Types ============

struct FieldDef {
    let number: Int
    let name: String
    let typeName: String
    let label: FieldLabel
    let isMap: Bool
    let keyType: String?
    let oneofName: String?
}

enum FieldLabel { case singular, optional, repeated }

struct MessageDef {
    let name: String
    var fields: [Int: FieldDef] = [:]
    var oneofs: [String: [Int]] = [:]
}

struct EnumDef {
    let name: String
    var values: [Int: String] = [:]
}

// ============ Decoded Values ============

enum RawVal {
    case varint(UInt64)
    case fixed64(UInt64)
    case fixed32(UInt32)
    case bytes([UInt8])
}

enum MapValue {
    case scalar(RawVal)
    case message(DMsg)
}

struct MapEntry {
    let key: RawVal
    let value: MapValue
}

final class DMsg {
    var scalarFields: [Int: RawVal] = [:]
    var msgFields: [Int: DMsg] = [:]
    var repeatedScalarFields: [Int: [RawVal]] = [:]
    var repeatedMsgFields: [Int: [DMsg]] = [:]
    var mapFields: [Int: [MapEntry]] = [:]
    var seen: Set<Int> = []
    var oneofSet: [String: Int] = [:]
}

// ============ Globals ============

var messages: [String: MessageDef] = [:]
var enums: [String: EnumDef] = [:]
var rootMessageName: String = ""
var rootFound = false
var msgDepth = 0

// ============ Proto Tokenizer ============

enum Tok {
    case ident(String)
    case number(Int)
    case str(String)
    case sym(Character)
    case eof
}

func protoTokenize(_ input: String) -> [Tok] {
    var toks: [Tok] = []
    let chars = Array(input)
    var i = 0
    while i < chars.count {
        let c = chars[i]
        if c == " " || c == "\t" || c == "\n" || c == "\r" { i += 1; continue }
        if c == "/" && i + 1 < chars.count {
            if chars[i+1] == "/" {
                i += 2
                while i < chars.count && chars[i] != "\n" { i += 1 }
                continue
            } else if chars[i+1] == "*" {
                i += 2
                while i < chars.count {
                    if chars[i] == "*" && i + 1 < chars.count && chars[i+1] == "/" { i += 2; break }
                    i += 1
                }
                continue
            }
        }
        if c == "\"" {
            i += 1
            var s = ""
            while i < chars.count && chars[i] != "\"" { s.append(chars[i]); i += 1 }
            if i < chars.count { i += 1 }
            toks.append(.str(s))
            continue
        }
        if c.isLetter || c == "_" {
            var s = ""
            while i < chars.count && (chars[i].isLetter || chars[i].isNumber || chars[i] == "_") {
                s.append(chars[i]); i += 1
            }
            toks.append(.ident(s))
            continue
        }
        if c.isNumber {
            var s = ""
            while i < chars.count && chars[i].isNumber { s.append(chars[i]); i += 1 }
            toks.append(.number(Int(s)!))
            continue
        }
        if c == "-" && i + 1 < chars.count && chars[i+1].isNumber {
            i += 1
            var s = "-"
            while i < chars.count && chars[i].isNumber { s.append(chars[i]); i += 1 }
            toks.append(.number(Int(s)!))
            continue
        }
        toks.append(.sym(c))
        i += 1
    }
    toks.append(.eof)
    return toks
}

// ============ Proto Parser ============

final class ProtoParser {
    var toks: [Tok]
    var pos: Int = 0
    init(_ t: [Tok]) { toks = t }
    func cur() -> Tok { pos < toks.count ? toks[pos] : .eof }
    func advance() { pos += 1 }
    func expectIdent() -> String {
        if case .ident(let s) = cur() { advance(); return s }
        fatalError("expected ident")
    }
    func expectNumber() -> Int {
        if case .number(let n) = cur() { advance(); return n }
        fatalError("expected number")
    }
    func expectSym(_ c: Character) {
        if case .sym(let s) = cur(), s == c { advance(); return }
        fatalError("expected \(c)")
    }
    func skipBalanced(_ open: Character, _ close: Character) {
        var depth = 0
        while true {
            if case .sym(let c) = cur() {
                if c == open { depth += 1; advance(); continue }
                if c == close { depth -= 1; advance(); if depth == 0 { return }; continue }
            }
            if case .eof = cur() { return }
            advance()
        }
    }
    func skipToSemicolon() {
        while true {
            if case .sym(";") = cur() { advance(); return }
            if case .eof = cur() { return }
            advance()
        }
    }
    func parseFile() {
        while true {
            switch cur() {
            case .eof: return
            case .ident(let s):
                switch s {
                case "syntax": advance(); expectSym("="); skipToSemicolon()
                case "package": advance(); skipToSemicolon()
                case "option": advance(); skipToSemicolon()
                case "message": parseMessage()
                case "enum": parseEnum()
                default: advance()
                }
            default: advance()
            }
        }
    }
    func parseMessage() {
        msgDepth += 1
        advance() // "message"
        let name = expectIdent()
        expectSym("{")
        var msgDef = MessageDef(name: name)
        while true {
            switch cur() {
            case .sym("}"):
                advance()
                messages[name] = msgDef
                if msgDepth == 1 && !rootFound { rootMessageName = name; rootFound = true }
                msgDepth -= 1
                return
            case .ident(let s):
                switch s {
                case "message": parseMessage()
                case "enum": parseEnum()
                case "oneof": parseOneof(into: &msgDef)
                case "option": advance(); skipToSemicolon()
                case "reserved": advance(); skipToSemicolon()
                case "map": parseMapField(into: &msgDef)
                case "repeated": advance(); parseFieldBody(label: .repeated, into: &msgDef)
                case "optional": advance(); parseFieldBody(label: .optional, into: &msgDef)
                default: parseFieldBody(label: .singular, into: &msgDef)
                }
            default: advance()
            }
        }
    }
    func parseFieldBody(label: FieldLabel, into msgDef: inout MessageDef) {
        let typeName = expectIdent()
        let fieldName = expectIdent()
        expectSym("=")
        let fieldNumber = expectNumber()
        if case .sym("[") = cur() { skipBalanced("[", "]") }
        expectSym(";")
        msgDef.fields[fieldNumber] = FieldDef(number: fieldNumber, name: fieldName, typeName: typeName,
            label: label, isMap: false, keyType: nil, oneofName: nil)
    }
    func parseMapField(into msgDef: inout MessageDef) {
        advance() // "map"
        expectSym("<")
        let keyType = expectIdent()
        expectSym(",")
        let valueType = expectIdent()
        expectSym(">")
        let fieldName = expectIdent()
        expectSym("=")
        let fieldNumber = expectNumber()
        if case .sym("[") = cur() { skipBalanced("[", "]") }
        expectSym(";")
        msgDef.fields[fieldNumber] = FieldDef(number: fieldNumber, name: fieldName, typeName: valueType,
            label: .repeated, isMap: true, keyType: keyType, oneofName: nil)
    }
    func parseOneof(into msgDef: inout MessageDef) {
        advance() // "oneof"
        let oneofName = expectIdent()
        expectSym("{")
        var fieldNumbers: [Int] = []
        while true {
            switch cur() {
            case .sym("}"):
                advance()
                msgDef.oneofs[oneofName] = fieldNumbers
                return
            case .ident(let s):
                if s == "option" { advance(); skipToSemicolon() }
                else {
                    let typeName = expectIdent()
                    let fieldName = expectIdent()
                    expectSym("=")
                    let fieldNumber = expectNumber()
                    if case .sym("[") = cur() { skipBalanced("[", "]") }
                    expectSym(";")
                    msgDef.fields[fieldNumber] = FieldDef(number: fieldNumber, name: fieldName, typeName: typeName,
                        label: .singular, isMap: false, keyType: nil, oneofName: oneofName)
                    fieldNumbers.append(fieldNumber)
                }
            default: advance()
            }
        }
    }
    func parseEnum() {
        advance() // "enum"
        let name = expectIdent()
        expectSym("{")
        var enumDef = EnumDef(name: name)
        while true {
            switch cur() {
            case .sym("}"):
                advance()
                enums[name] = enumDef
                return
            case .ident(let s):
                if s == "option" || s == "reserved" { advance(); skipToSemicolon() }
                else {
                    let valueName = expectIdent()
                    expectSym("=")
                    let valueNumber = expectNumber()
                    if case .sym("[") = cur() { skipBalanced("[", "]") }
                    expectSym(";")
                    enumDef.values[valueNumber] = valueName
                }
            default: advance()
            }
        }
    }
}

// ============ Binary Decoder Helpers ============

func readVarint(_ data: [UInt8], _ pos: inout Int) -> UInt64 {
    var result: UInt64 = 0
    var shift: UInt64 = 0
    while pos < data.count {
        let byte = data[pos]; pos += 1
        result |= UInt64(byte & 0x7F) << shift
        if byte & 0x80 == 0 { break }
        shift += 7
    }
    return result
}

func isNumericType(_ name: String) -> Bool {
    switch name {
    case "int32","int64","uint32","uint64","sint32","sint64","bool","fixed32","fixed64","sfixed32","sfixed64":
        return true
    default: return enums[name] != nil
    }
}

func isMessageType(_ name: String) -> Bool { return messages[name] != nil }

func wireTypeForType(_ name: String) -> Int {
    switch name {
    case "int32","int64","uint32","uint64","sint32","sint64","bool": return 0
    case "fixed32","sfixed32": return 5
    case "fixed64","sfixed64": return 1
    default: return enums[name] != nil ? 0 : 2
    }
}

func skipGroup(_ data: [UInt8], _ pos: inout Int, _ fieldNumber: Int) {
    while pos < data.count {
        let key = readVarint(data, &pos)
        let fn = Int(key >> 3)
        let wt = Int(key & 0x07)
        if wt == 4 && fn == fieldNumber { return }
        switch wt {
        case 0: _ = readVarint(data, &pos)
        case 1: pos += 8
        case 2: let len = Int(readVarint(data, &pos)); pos += len
        case 3: skipGroup(data, &pos, fn)
        case 5: pos += 4
        default: break
        }
    }
}

func clearField(_ msg: DMsg, _ fn: Int) {
    msg.scalarFields.removeValue(forKey: fn)
    msg.msgFields.removeValue(forKey: fn)
    msg.repeatedScalarFields.removeValue(forKey: fn)
    msg.repeatedMsgFields.removeValue(forKey: fn)
    msg.mapFields.removeValue(forKey: fn)
    msg.seen.remove(fn)
}

func defaultScalarForType(_ name: String) -> RawVal {
    switch name {
    case "string","bytes": return .bytes([])
    default: return .varint(0)
    }
}

// ============ Binary Decoder ============

func decodeMessageInto(_ msg: DMsg, _ data: [UInt8], _ schema: MessageDef) {
    var pos = 0
    while pos < data.count {
        let key = readVarint(data, &pos)
        let fieldNumber = Int(key >> 3)
        let wireType = Int(key & 0x07)
        let rawVal: RawVal?
        switch wireType {
        case 0: rawVal = .varint(readVarint(data, &pos))
        case 1:
            if pos + 8 <= data.count {
                var v: UInt64 = 0
                for i in 0..<8 { v |= UInt64(data[pos+i]) << (8*i) }
                pos += 8; rawVal = .fixed64(v)
            } else { rawVal = nil }
        case 2:
            let len = Int(readVarint(data, &pos))
            if pos + len <= data.count { rawVal = .bytes(Array(data[pos..<pos+len])); pos += len }
            else { rawVal = nil }
        case 5:
            if pos + 4 <= data.count {
                var v: UInt32 = 0
                for i in 0..<4 { v |= UInt32(data[pos+i]) << (8*i) }
                pos += 4; rawVal = .fixed32(v)
            } else { rawVal = nil }
        case 3: skipGroup(data, &pos, fieldNumber); rawVal = nil
        case 4: rawVal = nil
        default: rawVal = nil
        }
        guard let val = rawVal else { continue }
        guard let fd = schema.fields[fieldNumber] else { continue }
        msg.seen.insert(fieldNumber)
        if let on = fd.oneofName {
            if let prev = msg.oneofSet[on], prev != fieldNumber { clearField(msg, prev) }
            msg.oneofSet[on] = fieldNumber
        }
        if fd.isMap {
            decodeMapEntry(msg, fd: fd, val: val)
        } else if fd.label == .repeated {
            decodeRepeated(msg, fd: fd, val: val, wireType: wireType)
        } else {
            decodeSingular(msg, fd: fd, val: val)
        }
    }
}

func decodeSingular(_ msg: DMsg, fd: FieldDef, val: RawVal) {
    if isMessageType(fd.typeName) {
        if case .bytes(let subData) = val {
            let subSchema = messages[fd.typeName]!
            if msg.msgFields[fd.number] == nil { msg.msgFields[fd.number] = DMsg() }
            decodeMessageInto(msg.msgFields[fd.number]!, subData, subSchema)
        }
    } else {
        msg.scalarFields[fd.number] = val
    }
}

func decodeRepeated(_ msg: DMsg, fd: FieldDef, val: RawVal, wireType: Int) {
    let numeric = isNumericType(fd.typeName)
    if numeric && wireType == 2 {
        if case .bytes(let payload) = val {
            var ppos = 0
            let wt = wireTypeForType(fd.typeName)
            while ppos < payload.count {
                let elemVal: RawVal
                switch wt {
                case 0:
                    elemVal = .varint(readVarint(payload, &ppos))
                case 1:
                    var v: UInt64 = 0
                    for i in 0..<8 { v |= UInt64(payload[ppos+i]) << (8*i) }
                    ppos += 8
                    elemVal = .fixed64(v)
                case 5:
                    var v: UInt32 = 0
                    for i in 0..<4 { v |= UInt32(payload[ppos+i]) << (8*i) }
                    ppos += 4
                    elemVal = .fixed32(v)
                default:
                    return
                }
                msg.repeatedScalarFields[fd.number, default: []].append(elemVal)
            }
        }
    } else if numeric || fd.typeName == "string" || fd.typeName == "bytes" {
        msg.repeatedScalarFields[fd.number, default: []].append(val)
    } else {
        if case .bytes(let subData) = val {
            let subSchema = messages[fd.typeName]!
            let subMsg = DMsg()
            decodeMessageInto(subMsg, subData, subSchema)
            msg.repeatedMsgFields[fd.number, default: []].append(subMsg)
        }
    }
}

func decodeMapEntry(_ msg: DMsg, fd: FieldDef, val: RawVal) {
    guard case .bytes(let entryData) = val else { return }
    var key: RawVal? = nil
    var value: RawVal? = nil
    var valueMsg: DMsg? = nil
    var pos = 0
    while pos < entryData.count {
        let k = readVarint(entryData, &pos)
        let fn = Int(k >> 3)
        let wt = Int(k & 0x07)
        let v: RawVal?
        switch wt {
        case 0: v = .varint(readVarint(entryData, &pos))
        case 1:
            if pos + 8 <= entryData.count {
                var x: UInt64 = 0; for i in 0..<8 { x |= UInt64(entryData[pos+i]) << (8*i) }
                pos += 8; v = .fixed64(x)
            } else { v = nil }
        case 2:
            let len = Int(readVarint(entryData, &pos))
            if pos + len <= entryData.count { v = .bytes(Array(entryData[pos..<pos+len])); pos += len }
            else { v = nil }
        case 5:
            if pos + 4 <= entryData.count {
                var x: UInt32 = 0; for i in 0..<4 { x |= UInt32(entryData[pos+i]) << (8*i) }
                pos += 4; v = .fixed32(x)
            } else { v = nil }
        case 3: skipGroup(entryData, &pos, fn); v = nil
        case 4: v = nil
        default: v = nil
        }
        if fn == 1 { key = v }
        else if fn == 2 {
            if isMessageType(fd.typeName) {
                if case .bytes(let subData) = v {
                    let subSchema = messages[fd.typeName]!
                    let m = DMsg(); decodeMessageInto(m, subData, subSchema); valueMsg = m
                }
            } else { value = v }
        }
    }
    let mapKey: RawVal
    if let k = key { mapKey = k }
    else { mapKey = fd.keyType == "int32" ? .varint(0) : .bytes([]) }
    let mapVal: MapValue
    if let m = valueMsg { mapVal = .message(m) }
    else if let v = value { mapVal = .scalar(v) }
    else {
        if isMessageType(fd.typeName) { mapVal = .message(DMsg()) }
        else { mapVal = .scalar(defaultScalarForType(fd.typeName)) }
    }
    let entry = MapEntry(key: mapKey, value: mapVal)
    var entries = msg.mapFields[fd.number] ?? []
    let ks = keyToString(mapKey)
    var found = false
    for i in 0..<entries.count {
        if keyToString(entries[i].key) == ks { entries[i] = entry; found = true; break }
    }
    if !found { entries.append(entry) }
    msg.mapFields[fd.number] = entries
}

func keyToString(_ key: RawVal) -> String {
    switch key {
    case .varint(let v): return "\(v)"
    case .bytes(let v): return String(bytes: v, encoding: .utf8) ?? ""
    default: return ""
    }
}

// ============ JSON Output ============

func toCamelCase(_ name: String) -> String {
    var result = ""
    var nextUpper = false
    for scalar in name.unicodeScalars {
        if scalar == "_" { nextUpper = true }
        else {
            if nextUpper && scalar.value >= 0x61 && scalar.value <= 0x7A {
                result.unicodeScalars.append(UnicodeScalar(scalar.value - 32)!)
            } else { result.unicodeScalars.append(scalar) }
            nextUpper = false
        }
    }
    return result
}

func escapeJSONString(_ s: String) -> String {
    var result = "\""
    for scalar in s.unicodeScalars {
        switch scalar {
        case "\"": result += "\\\""
        case "\\": result += "\\\\"
        case "\u{08}": result += "\\b"
        case "\t": result += "\\t"
        case "\n": result += "\\n"
        case "\u{0C}": result += "\\f"
        case "\r": result += "\\r"
        default:
            if scalar.value < 0x20 { result += String(format: "\\u%04x", scalar.value) }
            else { result.unicodeScalars.append(scalar) }
        }
    }
    result += "\""
    return result
}

func isDefaultValue(_ val: RawVal) -> Bool {
    switch val {
    case .varint(let v): return v == 0
    case .fixed64(let v): return v == 0
    case .fixed32(let v): return v == 0
    case .bytes(let v): return v.isEmpty
    }
}

func outputScalar(_ val: RawVal, typeName: String) -> String {
    switch val {
    case .varint(let v):
        switch typeName {
        case "int32": return "\(Int32(truncatingIfNeeded: v))"
        case "int64": return "\"\(Int64(bitPattern: v))\""
        case "uint32": return "\(UInt32(truncatingIfNeeded: v))"
        case "uint64": return "\"\(v)\""
        case "sint32":
            let u = UInt32(truncatingIfNeeded: v)
            return "\(Int32(bitPattern: (u >> 1) ^ (0 &- (u & 1))))"
        case "sint64":
            return "\"\(Int64(bitPattern: (v >> 1) ^ (0 &- (v & 1))))\""
        case "bool": return v != 0 ? "true" : "false"
        default:
            if let ed = enums[typeName] {
                let ev = Int(Int32(truncatingIfNeeded: v))
                if let n = ed.values[ev] { return "\"\(n)\"" }
                return "\(ev)"
            }
            return "\(v)"
        }
    case .fixed64(let v):
        switch typeName {
        case "sfixed64": return "\"\(Int64(bitPattern: v))\""
        default: return "\"\(v)\""
        }
    case .fixed32(let v):
        switch typeName {
        case "sfixed32": return "\(Int32(bitPattern: v))"
        default: return "\(v)"
        }
    case .bytes(let v):
        switch typeName {
        case "string":
            let s = String(bytes: v, encoding: .utf8) ?? ""
            return escapeJSONString(s)
        default:
            return "\"\(Data(v).base64EncodedString())\""
        }
    }
}

func defaultScalarJSON(_ typeName: String) -> String {
    switch typeName {
    case "string","bytes": return "\"\""
    case "bool": return "false"
    case "int32","uint32","sint32","fixed32","sfixed32": return "0"
    case "int64","uint64","sint64","fixed64","sfixed64": return "\"0\""
    default:
        if let ed = enums[typeName] { if let n = ed.values[0] { return "\"\(n)\"" } }
        return "0"
    }
}

func outputSingularValue(_ msg: DMsg, fn: Int, fd: FieldDef) -> String {
    if isMessageType(fd.typeName) {
        if let sub = msg.msgFields[fn] { return outputMessage(sub, schema: messages[fd.typeName]!) }
        return "{}"
    } else {
        if let val = msg.scalarFields[fn] { return outputScalar(val, typeName: fd.typeName) }
        return defaultScalarJSON(fd.typeName)
    }
}

func outputRepeated(_ msg: DMsg, fn: Int, fd: FieldDef) -> String {
    var parts: [String] = []
    if let scalars = msg.repeatedScalarFields[fn] {
        for val in scalars { parts.append(outputScalar(val, typeName: fd.typeName)) }
    }
    if let msgs = msg.repeatedMsgFields[fn] {
        let subSchema = messages[fd.typeName]!
        for m in msgs { parts.append(outputMessage(m, schema: subSchema)) }
    }
    return "[" + parts.joined(separator: ",") + "]"
}

func outputMap(_ entries: [MapEntry], fd: FieldDef) -> String {
    let kt = fd.keyType!
    var sorted = entries
    if kt == "int32" {
        sorted.sort { a, b in
            let ka: Int32
            let kb: Int32
            if case .varint(let v) = a.key { ka = Int32(truncatingIfNeeded: v) } else { ka = 0 }
            if case .varint(let v) = b.key { kb = Int32(truncatingIfNeeded: v) } else { kb = 0 }
            return ka < kb
        }
    } else {
        sorted.sort { a, b in
            let ba: [UInt8]
            let bb: [UInt8]
            if case .bytes(let v) = a.key { ba = v } else { ba = [] }
            if case .bytes(let v) = b.key { bb = v } else { bb = [] }
            return ba.lexicographicallyPrecedes(bb)
        }
    }
    var parts: [String] = []
    for entry in sorted {
        let keyJSON: String
        if kt == "int32" {
            let k: Int32
            if case .varint(let v) = entry.key { k = Int32(truncatingIfNeeded: v) } else { k = 0 }
            keyJSON = "\"\(k)\""
        } else {
            let s: String
            if case .bytes(let v) = entry.key { s = String(bytes: v, encoding: .utf8) ?? "" } else { s = "" }
            keyJSON = escapeJSONString(s)
        }
        let valStr: String
        switch entry.value {
        case .scalar(let sv): valStr = outputScalar(sv, typeName: fd.typeName)
        case .message(let m): valStr = outputMessage(m, schema: messages[fd.typeName]!)
        }
        parts.append("\(keyJSON):\(valStr)")
    }
    return "{" + parts.joined(separator: ",") + "}"
}

func outputMessage(_ msg: DMsg, schema: MessageDef) -> String {
    var parts: [String] = []
    let fieldNumbers = schema.fields.keys.sorted()
    for fn in fieldNumbers {
        let fd = schema.fields[fn]!
        let jn = toCamelCase(fd.name)
        if fd.isMap {
            guard let entries = msg.mapFields[fn], !entries.isEmpty else { continue }
            parts.append("\"\(jn)\":\(outputMap(entries, fd: fd))")
        } else if fd.label == .repeated {
            let sc = msg.repeatedScalarFields[fn]?.count ?? 0
            let mc = msg.repeatedMsgFields[fn]?.count ?? 0
            if sc + mc == 0 { continue }
            parts.append("\"\(jn)\":\(outputRepeated(msg, fn: fn, fd: fd))")
        } else if fd.oneofName != nil {
            if let sf = msg.oneofSet[fd.oneofName!], sf == fn {
                parts.append("\"\(jn)\":\(outputSingularValue(msg, fn: fn, fd: fd))")
            }
        } else if fd.label == .optional {
            if msg.seen.contains(fn) {
                parts.append("\"\(jn)\":\(outputSingularValue(msg, fn: fn, fd: fd))")
            }
        } else {
            if isMessageType(fd.typeName) {
                if msg.msgFields[fn] != nil {
                    parts.append("\"\(jn)\":\(outputMessage(msg.msgFields[fn]!, schema: messages[fd.typeName]!))")
                }
            } else {
                if let val = msg.scalarFields[fn] {
                    if !isDefaultValue(val) {
                        parts.append("\"\(jn)\":\(outputScalar(val, typeName: fd.typeName))")
                    }
                }
            }
        }
    }
    return "{" + parts.joined(separator: ",") + "}"
}

