/* ============ Dynamic String Buffer ============ */
typedef struct { char *data; int len, cap; } strbuf;
static void sb_init(strbuf *sb){sb->cap=512;sb->data=malloc(sb->cap);sb->len=0;sb->data[0]=0;}
static void sb_ensure(strbuf *sb,int n){if(sb->len+n>=sb->cap){while(sb->len+n>=sb->cap)sb->cap*=2;sb->data=realloc(sb->data,sb->cap);}}
static void sb_put(strbuf *sb,const char*s,int n){sb_ensure(sb,n);memcpy(sb->data+sb->len,s,n);sb->len+=n;sb->data[sb->len]=0;}
static void sb_putc(strbuf *sb,char c){sb_ensure(sb,1);sb->data[sb->len++]=c;sb->data[sb->len]=0;}
static void sb_puts(strbuf *sb,const char*s){sb_put(sb,s,(int)strlen(s));}
static char*sb_detach(strbuf *sb){sb->data[sb->len]=0;char*r=sb->data;sb->data=NULL;return r;}

/* ============ Base64 Encode ============ */
static const char b64tab[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static char*base64_encode(const unsigned char*data,int len){
    strbuf sb;sb_init(&sb);
    for(int i=0;i<len;i+=3){
        int n=((unsigned char)data[i]<<16);
        if(i+1<len)n|=(unsigned char)data[i+1]<<8;
        if(i+2<len)n|=(unsigned char)data[i+2];
        sb_putc(&sb,b64tab[(n>>18)&63]);
        sb_putc(&sb,b64tab[(n>>12)&63]);
        sb_putc(&sb,(i+1<len)?b64tab[(n>>6)&63]:'=');
        sb_putc(&sb,(i+2<len)?b64tab[n&63]:'=');
    }
    return sb_detach(&sb);
}

/* ============ Form URL Encode (for form body and Authorization) ============ */
static void form_encode(strbuf *sb,const char*s,int len){
    for(int i=0;i<len;i++){
        unsigned char c=(unsigned char)s[i];
        if(isalnum(c)||c=='-'||c=='.'||c=='_'||c=='*')sb_putc(sb,(char)c);
        else if(c==' ')sb_putc(sb,'+');
        else{sb_putc(sb,'%');sb_putc(sb,"0123456789ABCDEF"[(c>>4)&0xF]);sb_putc(sb,"0123456789ABCDEF"[c&0xF]);}
    }
}

/* ============ Percent-encode for query string (cursor) ============ */
static void query_encode(strbuf *sb,const char*s,int len){
    for(int i=0;i<len;i++){
        unsigned char c=(unsigned char)s[i];
        if(isalnum(c)||c=='-'||c=='.'||c=='_'||c=='~')sb_putc(sb,(char)c);
        else{sb_putc(sb,'%');sb_putc(sb,"0123456789ABCDEF"[(c>>4)&0xF]);sb_putc(sb,"0123456789ABCDEF"[c&0xF]);}
    }
}

/* ============ JSON Parser ============ */
typedef enum{JNULL,JBOOL,JNUM,JSTR,JARR,JOBJ}JType;
typedef struct JVal{
    JType type;
    union{
        int bval;
        double nval;
        char*sval;
        struct{struct JVal**items;int count;}arr;
        struct{char**keys;struct JVal**vals;int count;}obj;
    };
}JVal;

static const char*j_skip_ws(const char*p){while(*p&&(*p==' '||*p=='\t'||*p=='\n'||*p=='\r'))p++;return p;}

static JVal*j_parse(const char**pp);

static char*parse_json_string_raw(const char**pp){
    const char*p=*pp;
    if(*p!='"')return NULL;
    p++;
    strbuf sb;sb_init(&sb);
    while(*p&&*p!='"'){
        if(*p=='\\'){
            p++;
            switch(*p){
                case '"':sb_putc(&sb,'"');p++;break;
                case '\\':sb_putc(&sb,'\\');p++;break;
                case '/':sb_putc(&sb,'/');p++;break;
                case 'b':sb_putc(&sb,'\b');p++;break;
                case 'f':sb_putc(&sb,'\f');p++;break;
                case 'n':sb_putc(&sb,'\n');p++;break;
                case 'r':sb_putc(&sb,'\r');p++;break;
                case 't':sb_putc(&sb,'\t');p++;break;
                case 'u':{
                    p++;
                    unsigned int cp=0;
                    for(int i=0;i<4;i++){
                        cp<<=4;
                        char h=*p++;
                        if(h>='0'&&h<='9')cp|=h-'0';
                        else if(h>='a'&&h<='f')cp|=h-'a'+10;
                        else if(h>='A'&&h<='F')cp|=h-'A'+10;
                    }
                    /* surrogate pair */
                    if(cp>=0xD800&&cp<=0xDBFF&&*p=='\\'&&*(p+1)=='u'){
                        p+=2;
                        unsigned int lo=0;
                        for(int i=0;i<4;i++){
                            lo<<=4;
                            char h=*p++;
                            if(h>='0'&&h<='9')lo|=h-'0';
                            else if(h>='a'&&h<='f')lo|=h-'a'+10;
                            else if(h>='A'&&h<='F')lo|=h-'A'+10;
                        }
                        cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    }
                    /* encode UTF-8 */
                    if(cp<0x80)sb_putc(&sb,(char)cp);
                    else if(cp<0x800){sb_putc(&sb,(char)(0xC0|(cp>>6)));sb_putc(&sb,(char)(0x80|(cp&0x3F)));}
                    else if(cp<0x10000){sb_putc(&sb,(char)(0xE0|(cp>>12)));sb_putc(&sb,(char)(0x80|((cp>>6)&0x3F)));sb_putc(&sb,(char)(0x80|(cp&0x3F)));}
                    else{sb_putc(&sb,(char)(0xF0|(cp>>18)));sb_putc(&sb,(char)(0x80|((cp>>12)&0x3F)));sb_putc(&sb,(char)(0x80|((cp>>6)&0x3F)));sb_putc(&sb,(char)(0x80|(cp&0x3F)));}
                    break;
                }
                default:sb_putc(&sb,*p);p++;break;
            }
        }else{
            sb_putc(&sb,*p);p++;
        }
    }
    if(*p=='"')p++;
    *pp=p;
    return sb_detach(&sb);
}

static JVal*j_parse(const char**pp){
    const char*p=j_skip_ws(*pp);
    JVal*v=malloc(sizeof(JVal));
    if(*p=='"'){v->type=JSTR;v->sval=parse_json_string_raw(&p);*pp=p;return v;}
    if(*p=='{'){
        p++;v->type=JOBJ;
        int cap=8;v->obj.keys=malloc(cap*sizeof(char*));v->obj.vals=malloc(cap*sizeof(JVal*));v->obj.count=0;
        p=j_skip_ws(p);
        if(*p=='}'){p++;*pp=p;return v;}
        while(1){
            p=j_skip_ws(p);
            char*key=parse_json_string_raw(&p);
            p=j_skip_ws(p);
            if(*p==':')p++;
            p=j_skip_ws(p);
            JVal*val=j_parse(&p);
            if(v->obj.count>=cap){cap*=2;v->obj.keys=realloc(v->obj.keys,cap*sizeof(char*));v->obj.vals=realloc(v->obj.vals,cap*sizeof(JVal*));}
            v->obj.keys[v->obj.count]=key;v->obj.vals[v->obj.count]=val;v->obj.count++;
            p=j_skip_ws(p);
            if(*p==','){p++;continue;}
            if(*p=='}'){p++;break;}
            break;
        }
        *pp=p;return v;
    }
    if(*p=='['){
        p++;v->type=JARR;
        int cap=8;v->arr.items=malloc(cap*sizeof(JVal*));v->arr.count=0;
        p=j_skip_ws(p);
        if(*p==']'){p++;*pp=p;return v;}
        while(1){
            p=j_skip_ws(p);
            JVal*val=j_parse(&p);
            if(v->arr.count>=cap){cap*=2;v->arr.items=realloc(v->arr.items,cap*sizeof(JVal*));}
            v->arr.items[v->arr.count++]=val;
            p=j_skip_ws(p);
            if(*p==','){p++;continue;}
            if(*p==']'){p++;break;}
            break;
        }
        *pp=p;return v;
    }
    if(*p=='t'){v->type=JBOOL;v->bval=1;p+=4;*pp=p;return v;}
    if(*p=='f'){v->type=JBOOL;v->bval=0;p+=5;*pp=p;return v;}
    if(*p=='n'){v->type=JNULL;p+=4;*pp=p;return v;}
    /* number */
    {
        const char*start=p;
        if(*p=='-')p++;
        while(isdigit(*p))p++;
        if(*p=='.'){p++;while(isdigit(*p))p++;}
        if(*p=='e'||*p=='E'){p++;if(*p=='+'||*p=='-')p++;while(isdigit(*p))p++;}
        v->type=JNUM;
        int n=(int)(p-start);
        char*tmp=malloc(n+1);memcpy(tmp,start,n);tmp[n]=0;
        v->nval=atof(tmp);free(tmp);
        *pp=p;return v;
    }
}

static JVal*j_obj_get(JVal*obj,const char*key){
    if(!obj||obj->type!=JOBJ)return NULL;
    for(int i=0;i<obj->obj.count;i++)
        if(strcmp(obj->obj.keys[i],key)==0)return obj->obj.vals[i];
    return NULL;
}

/* ============ HTTP Client ============ */
typedef struct{
    int status;
    char*body;
    char*retry_after;
    char*www_auth;
}HttpResponse;

static char*read_file(const char*path){
    FILE*f=fopen(path,"rb");
    if(!f)return NULL;
    fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
    char*buf=malloc(sz+1);
    fread(buf,1,sz,f);buf[sz]=0;fclose(f);
    return buf;
}

static int parse_url(const char*url,char*host,int*port,char*path,int pathsz){
    const char*p=url;
    if(strncmp(p,"http://",7)==0)p+=7;
    const char*slash=strchr(p,'/');
    const char*colon=strchr(p,':');
    int hlen;
    if(slash&&colon&&colon<slash){
        hlen=(int)(colon-p);
        *port=atoi(colon+1);
    }else if(slash){
        hlen=(int)(slash-p);
        *port=80;
    }else if(colon){
        hlen=(int)(colon-p);
        *port=atoi(colon+1);
    }else{
        hlen=(int)strlen(p);
        *port=80;
    }
    memcpy(host,p,hlen);host[hlen]=0;
    if(slash)strncpy(path,slash,pathsz-1);else{path[0]='/';path[1]=0;}
    path[pathsz-1]=0;
    return 0;
}

/* case-insensitive substring search */
static const char*ci_strstr(const char*haystack,const char*needle){
    size_t nlen=strlen(needle);
    if(nlen==0)return haystack;
    for(;*haystack;haystack++){
        if(strncasecmp(haystack,needle,nlen)==0)return haystack;
    }
    return NULL;
}

/* strndup replacement */
static char*my_strndup(const char*s,int n){
    char*r=malloc(n+1);
    memcpy(r,s,n);r[n]=0;return r;
}

static HttpResponse http_request(const char*method,const char*url,const char*extra_headers,const char*body){
    HttpResponse resp={0};
    resp.body=NULL;resp.retry_after=NULL;resp.www_auth=NULL;
    char host[256],path[8192];int port;
    parse_url(url,host,&port,path,8192);

    struct addrinfo hints={0},*res=NULL;
    hints.ai_family=AF_INET;hints.ai_socktype=SOCK_STREAM;
    char ports[16];snprintf(ports,sizeof(ports),"%d",port);
    if(getaddrinfo(host,ports,&hints,&res)!=0){resp.status=-1;return resp;}

    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(fd<0){freeaddrinfo(res);resp.status=-1;return resp;}
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){close(fd);freeaddrinfo(res);resp.status=-1;return resp;}
    freeaddrinfo(res);

    /* build request */
    strbuf req;sb_init(&req);
    sb_puts(&req,method);sb_putc(&req,' ');sb_puts(&req,path);sb_puts(&req," HTTP/1.1\r\n");
    sb_puts(&req,"Host: ");sb_puts(&req,host);
    if(port!=80){char ps[16];snprintf(ps,sizeof(ps),":%d",port);sb_puts(&req,ps);}
    sb_puts(&req,"\r\n");
    if(extra_headers)sb_puts(&req,extra_headers);
    if(body){
        sb_puts(&req,"Content-Length: ");
        char cl[32];snprintf(cl,sizeof(cl),"%d",(int)strlen(body));
        sb_puts(&req,cl);sb_puts(&req,"\r\n");
    }
    sb_puts(&req,"Connection: close\r\n\r\n");
    if(body)sb_puts(&req,body);

    /* send */
    int total=req.len,sent=0;
    while(sent<total){
        int n=write(fd,req.data+sent,total-sent);
        if(n<=0)break;
        sent+=n;
    }
    free(req.data);

    /* read response */
    strbuf raw;sb_init(&raw);
    char tmp[8192];
    while(1){
        int n=read(fd,tmp,sizeof(tmp));
        if(n<=0)break;
        sb_put(&raw,tmp,n);
    }
    close(fd);

    /* parse */
    raw.data[raw.len]=0;
    char*hdr_end=strstr(raw.data,"\r\n\r\n");
    if(!hdr_end){free(raw.data);resp.status=-1;return resp;}
    int hdr_len=(int)(hdr_end-raw.data);
    char*hdrs=my_strndup(raw.data,hdr_len);
    char*raw_body=hdr_end+4;
    int raw_body_len=raw.len-hdr_len-4;

    /* status line */
    resp.status=atoi(hdrs+9);

    /* parse headers */
    char*line=hdrs;
    /* skip status line */
    char*nl=strstr(line,"\r\n");
    if(nl)line=nl+2;
    int is_chunked=0;
    int content_length=-1;
    while(line&&*line){
        nl=strstr(line,"\r\n");
        if(!nl)nl=line+strlen(line);
        if(strncasecmp(line,"Transfer-Encoding:",18)==0){
            char*val=line+18;while(*val==' ')val++;
            if(ci_strstr(val,"chunked"))is_chunked=1;
        }else if(strncasecmp(line,"Content-Length:",15)==0){
            char*val=line+15;while(*val==' ')val++;
            content_length=atoi(val);
        }else if(strncasecmp(line,"Retry-After:",12)==0){
            char*val=line+12;while(*val==' ')val++;
            int vlen=(int)(nl-val);
            resp.retry_after=my_strndup(val,vlen);
        }else if(strncasecmp(line,"WWW-Authenticate:",17)==0){
            char*val=line+17;while(*val==' ')val++;
            int vlen=(int)(nl-val);
            resp.www_auth=my_strndup(val,vlen);
        }
        if(!*nl)break;
        line=nl+2;
    }

    /* extract body */
    if(is_chunked){
        strbuf out;sb_init(&out);
        char*bp=raw_body;
        int remaining=raw_body_len;
        while(remaining>0){
            char*nl2=strstr(bp,"\r\n");
            if(!nl2)break;
            char hex[32]={0};
            int hlen2=(int)(nl2-bp);
            if(hlen2>31)hlen2=31;
            memcpy(hex,bp,hlen2);
            unsigned int csz=(unsigned int)strtoul(hex,NULL,16);
            bp=nl2+2;remaining-=(int)(bp-raw_body);
            if(csz==0)break;
            if((int)csz<=remaining){
                sb_put(&out,bp,(int)csz);
                bp+=csz;remaining-=(int)csz;
                if(remaining>=2&&bp[0]=='\r'&&bp[1]=='\n'){bp+=2;remaining-=2;}
            }else{
                sb_put(&out,bp,remaining);
                bp+=remaining;remaining=0;
            }
        }
        resp.body=sb_detach(&out);
    }else if(content_length>=0){
        int blen=content_length;
        if(blen>raw_body_len)blen=raw_body_len;
        resp.body=malloc(blen+1);memcpy(resp.body,raw_body,blen);resp.body[blen]=0;
    }else{
        resp.body=malloc(raw_body_len+1);
        memcpy(resp.body,raw_body,raw_body_len);
        resp.body[raw_body_len]=0;
    }

    free(hdrs);free(raw.data);
    return resp;
}

/* ============ Amount Parsing ============ */
static int64_t parse_amount(const char*s){
    int64_t cents=0;
    int neg=0;
    const char*p=s;
    if(*p=='-'){neg=1;p++;}
    /* integer part */
    int64_t ipart=0;
    while(isdigit(*p)){ipart=ipart*10+(*p-'0');p++;}
    cents=ipart*100;
    /* fractional part */
    if(*p=='.'){
        p++;
        int fpart=0,fdigits=0;
        while(isdigit(*p)&&fdigits<2){fpart=fpart*10+(*p-'0');fdigits++;p++;}
        while(fdigits<2){fpart*=10;fdigits++;}
        cents+=fpart;
    }
    return neg?-cents:cents;
}

static void format_cents(int64_t cents,char*out,int outsz){
    if(cents<0){
        snprintf(out,outsz,"-%lld.%02lld",(long long)((-cents)/100),(long long)((-cents)%100));
    }else{
        snprintf(out,outsz,"%lld.%02lld",(long long)(cents/100),(long long)(cents%100));
    }
}

/* ============ Totals / Status tracking ============ */
typedef struct{char*name;char*currency;int64_t cents;}TotalEntry;
typedef struct{char*status;int count;}StatusEntry;

static TotalEntry*totals=NULL;static int total_count=0,total_cap=0;
static StatusEntry*statuses=NULL;static int status_count=0,status_cap=0;

static void add_total(const char*name,const char*currency,int64_t cents){
    for(int i=0;i<total_count;i++){
        if(strcmp(totals[i].name,name)==0&&strcmp(totals[i].currency,currency)==0){
            totals[i].cents+=cents;return;
        }
    }
    if(total_count>=total_cap){total_cap=total_cap?total_cap*2:64;totals=realloc(totals,total_cap*sizeof(TotalEntry));}
    totals[total_count].name=strdup(name);
    totals[total_count].currency=strdup(currency);
    totals[total_count].cents=cents;
    total_count++;
}

static void add_status(const char*status){
    for(int i=0;i<status_count;i++){
        if(strcmp(statuses[i].status,status)==0){statuses[i].count++;return;}
    }
    if(status_count>=status_cap){status_cap=status_cap?status_cap*2:16;statuses=realloc(statuses,status_cap*sizeof(StatusEntry));}
    statuses[status_count].status=strdup(status);
    statuses[status_count].count=1;
    status_count++;
}

static int cmp_total(const void*a,const void*b){
    TotalEntry*ta=(TotalEntry*)a,*tb=(TotalEntry*)b;
    int c=strcmp(ta->name,tb->name);
    if(c)return c;
    return strcmp(ta->currency,tb->currency);
}
static int cmp_status(const void*a,const void*b){
    return strcmp(((StatusEntry*)a)->status,((StatusEntry*)b)->status);
}

/* ============ Fatal error ============ */
static void fatal(int status,const char*body){
    printf("ERROR %d %s\n",status,body?body:"");
    exit(0);
}

/* ============ Token fetch helper ============ */
static char* get_token(const char*token_url,const char*client_id,const char*client_secret,const char*scope){
    strbuf cred;sb_init(&cred);
    form_encode(&cred,client_id,(int)strlen(client_id));
    sb_putc(&cred,':');
    form_encode(&cred,client_secret,(int)strlen(client_secret));
    char*cred_str=sb_detach(&cred);
    char*b64=base64_encode((unsigned char*)cred_str,(int)strlen(cred_str));
    free(cred_str);

    strbuf tok_hdr;sb_init(&tok_hdr);
    sb_puts(&tok_hdr,"Content-Type: application/x-www-form-urlencoded\r\n");
    sb_puts(&tok_hdr,"Authorization: Basic ");sb_puts(&tok_hdr,b64);sb_puts(&tok_hdr,"\r\n");
    char*hdr_str=sb_detach(&tok_hdr);
    free(b64);

    strbuf tok_body;sb_init(&tok_body);
    sb_puts(&tok_body,"grant_type=client_credentials&scope=");
    form_encode(&tok_body,scope,(int)strlen(scope));
    char*body_str=sb_detach(&tok_body);

    HttpResponse tok_resp=http_request("POST",token_url,hdr_str,body_str);
    free(hdr_str);free(body_str);

    if(tok_resp.status!=200)fatal(tok_resp.status,tok_resp.body);

    const char*tp=tok_resp.body;
    JVal*tok_json=j_parse(&tp);
    JVal*jat=j_obj_get(tok_json,"access_token");
    if(!jat||jat->type!=JSTR)fatal(0,"");
    char*access_token=strdup(jat->sval);
    free(tok_resp.body);free(tok_resp.retry_after);free(tok_resp.www_auth);
    return access_token;
}

/* ============ Main ============ */
int main(int argc,char**argv){
    if(argc<3){return 1;}
    char*data_dir=argv[1];
    char*base_url=argv[2];

    /* Read client.json */
    char cpath[4096];
    snprintf(cpath,sizeof(cpath),"%s/client.json",data_dir);
    char*cjson=read_file(cpath);
    if(!cjson){printf("ERROR 0 \n");return 0;}

    const char*jp=cjson;
    JVal*cfg=j_parse(&jp);

    JVal*jcid=j_obj_get(cfg,"client_id");
    JVal*jsec=j_obj_get(cfg,"client_secret");
    JVal*jscope=j_obj_get(cfg,"scope");
    JVal*jps=j_obj_get(cfg,"page_size");

    const char*client_id=jcid->sval;
    const char*client_secret=jsec->sval;
    const char*scope=jscope->sval;
    int page_size=(int)jps->nval;

    /* Build token URL */
    char token_url[4096];
    snprintf(token_url,sizeof(token_url),"%s/oauth/token",base_url);

    /* Step 1: get token */
    char*access_token=get_token(token_url,client_id,client_secret,scope);

    /* Counters */
    int orders_received=0,pages_ok=0,retries=0,reauth=0;

    /* Step 2: fetch orders */
    char*cursor=NULL;
    int token_used_ok=0; /* whether current token has been used successfully on /orders */

    while(1){
        /* Build orders URL */
        char orders_url[8192];
        if(cursor){
            strbuf q;sb_init(&q);
            query_encode(&q,cursor,(int)strlen(cursor));
            char*enc=sb_detach(&q);
            snprintf(orders_url,sizeof(orders_url),"%s/orders?limit=%d&cursor=%s",base_url,page_size,enc);
            free(enc);
        }else{
            snprintf(orders_url,sizeof(orders_url),"%s/orders?limit=%d",base_url,page_size);
        }

        /* Build auth header */
        strbuf ah;sb_init(&ah);
        sb_puts(&ah,"Authorization: Bearer ");sb_puts(&ah,access_token);sb_puts(&ah,"\r\n");
        char*auth_hdr=sb_detach(&ah);

        HttpResponse resp=http_request("GET",orders_url,auth_hdr,NULL);
        free(auth_hdr);

        if(resp.status==429){
            retries++;
            int wait=1;
            if(resp.retry_after)wait=atoi(resp.retry_after);
            free(resp.body);free(resp.retry_after);free(resp.www_auth);
            sleep(wait);
            continue;
        }
        if(resp.status==503){
            retries++;
            free(resp.body);free(resp.retry_after);free(resp.www_auth);
            usleep(500000);
            continue;
        }
        if(resp.status==401){
            if(!token_used_ok){
                /* first request with this token got 401 -> fatal */
                fatal(401,resp.body);
            }
            /* re-auth */
            reauth++;
            free(resp.body);free(resp.retry_after);free(resp.www_auth);

            free(access_token);
            access_token=get_token(token_url,client_id,client_secret,scope);
            token_used_ok=0;
            continue;
        }
        if(resp.status!=200){
            fatal(resp.status,resp.body);
        }

        /* 200 OK */
        token_used_ok=1;
        pages_ok++;

        const char*bp=resp.body;
        JVal*page=j_parse(&bp);
        JVal*jdata=j_obj_get(page,"data");
        JVal*jnext=j_obj_get(page,"next_cursor");

        if(jdata&&jdata->type==JARR){
            for(int i=0;i<jdata->arr.count;i++){
                JVal*ord=jdata->arr.items[i];
                orders_received++;

                JVal*jstatus=j_obj_get(ord,"status");
                const char*status_str=jstatus&&jstatus->type==JSTR?jstatus->sval:"";
                add_status(status_str);

                if(strcmp(status_str,"cancelled")!=0){
                    JVal*jcust=j_obj_get(ord,"customer");
                    JVal*jname=jcust?j_obj_get(jcust,"name"):NULL;
                    JVal*jcurrency=j_obj_get(ord,"currency");
                    JVal*jamount=j_obj_get(ord,"amount");
                    if(jname&&jname->type==JSTR&&jcurrency&&jcurrency->type==JSTR&&jamount&&jamount->type==JSTR){
                        int64_t cents=parse_amount(jamount->sval);
                        add_total(jname->sval,jcurrency->sval,cents);
                    }
                }
            }
        }

        free(resp.body);free(resp.retry_after);free(resp.www_auth);

        if(jnext&&jnext->type==JSTR){
            free(cursor);
            cursor=strdup(jnext->sval);
        }else{
            /* next_cursor is null or missing -> last page */
            free(cursor);cursor=NULL;
            break;
        }
    }

    /* Output */
    qsort(totals,total_count,sizeof(TotalEntry),cmp_total);
    qsort(statuses,status_count,sizeof(StatusEntry),cmp_status);

    for(int i=0;i<total_count;i++){
        char amt[64];
        format_cents(totals[i].cents,amt,sizeof(amt));
        printf("total %s %s %s\n",totals[i].currency,amt,totals[i].name);
    }
    for(int i=0;i<status_count;i++){
        printf("status %s %d\n",statuses[i].status,statuses[i].count);
    }
    printf("orders %d pages %d retries %d reauth %d\n",orders_received,pages_ok,retries,reauth);

    return 0;
}

import * as fs from 'fs';
import * as path from 'path';

// --- Schema types ---
interface FieldDef {
  name: string;
  number: number;
  type: string;
  label: 'singular' | 'repeated' | 'optional';
  isMap: boolean;
  mapKeyType?: string;
  mapValueType?: string;
  oneofName?: string;
}

interface MessageDef {
  name: string;
  fields: Map<number, FieldDef>;
  oneofs: Map<string, number[]>;
}

interface EnumDef {
  name: string;
  values: Map<number, string>;
}

interface DecodedMsg {
  fields: Map<number, any>;
  present: Set<number>;
  oneofSet: Map<string, number>;
}

let messages = new Map<string, MessageDef>();
let enums = new Map<string, EnumDef>();
let rootMessageName = '';

// --- Proto Parser ---
function stripComments(input: string): string {
  let result = '';
  let i = 0;
  while (i < input.length) {
    if (input[i] === '/' && i + 1 < input.length && input[i + 1] === '/') {
      i += 2;
      while (i < input.length && input[i] !== '\n') i++;
    } else if (input[i] === '/' && i + 1 < input.length && input[i + 1] === '*') {
      i += 2;
      while (i + 1 < input.length && !(input[i] === '*' && input[i + 1] === '/')) i++;
      i += 2;
    } else if (input[i] === '"') {
      result += input[i]; i++;
      while (i < input.length && input[i] !== '"') {
        if (input[i] === '\\') { result += input[i]; i++; }
        if (i < input.length) { result += input[i]; i++; }
      }
      if (i < input.length) { result += input[i]; i++; }
    } else {
      result += input[i]; i++;
    }
  }
  return result;
}

type Token = { type: 'ident' | 'string' | 'number' | 'punct'; value: string };

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < input.length) {
    if (/\s/.test(input[i])) { i++; continue; }
    if (input[i] === '"') {
      let s = ''; i++;
      while (i < input.length && input[i] !== '"') {
        if (input[i] === '\\') { i++; }
        if (i < input.length) { s += input[i]; i++; }
      }
      if (i < input.length) i++;
      tokens.push({ type: 'string', value: s });
    } else if (/[a-zA-Z_]/.test(input[i])) {
      let s = '';
      while (i < input.length && /[a-zA-Z0-9_.]/.test(input[i])) { s += input[i]; i++; }
      tokens.push({ type: 'ident', value: s });
    } else if (/[0-9]/.test(input[i]) || (input[i] === '-' && i + 1 < input.length && /[0-9]/.test(input[i + 1]))) {
      let s = '';
      if (input[i] === '-') { s += '-'; i++; }
      while (i < input.length && /[0-9]/.test(input[i])) { s += input[i]; i++; }
      tokens.push({ type: 'number', value: s });
    } else {
      tokens.push({ type: 'punct', value: input[i] }); i++;
    }
  }
  tokens.push({ type: 'punct', value: 'EOF' });
  return tokens;
}

class ProtoParser {
  tokens: Token[];
  pos = 0;
  constructor(tokens: Token[]) { this.tokens = tokens; }
  peek(): Token { return this.tokens[this.pos]; }
  next(): Token { return this.tokens[this.pos++]; }
  atIdent(name: string): boolean { return this.peek().type === 'ident' && this.peek().value === name; }
  atPunct(p: string): boolean { return this.peek().type === 'punct' && this.peek().value === p; }

  expectPunct(p: string): void {
    const t = this.next();
    if (t.type !== 'punct' || t.value !== p) throw new Error(`Expected '${p}' got '${t.value}'`);
  }

  skipToSemicolon(): void {
    while (!this.atPunct(';') && !this.atPunct('EOF')) this.next();
    if (this.atPunct(';')) this.next();
  }

  skipFieldOptions(): void {
    if (this.atPunct('[')) {
      this.next();
      let depth = 1;
      while (!this.atPunct('EOF') && depth > 0) {
        if (this.atPunct('[')) depth++;
        else if (this.atPunct(']')) { depth--; if (depth === 0) break; }
        this.next();
      }
      if (this.atPunct(']')) this.next();
    }
  }

  parseProto(): void {
    while (!this.atPunct('EOF')) {
      if (this.atIdent('syntax') || this.atIdent('package') || this.atIdent('option')) {
        this.skipToSemicolon();
      } else if (this.atIdent('message')) {
        this.parseMessage();
      } else if (this.atIdent('enum')) {
        this.parseEnum();
      } else {
        this.skipToSemicolon();
      }
    }
  }

  parseMessage(): void {
    this.next();
    const name = this.next().value;
    this.expectPunct('{');
    const msgDef: MessageDef = { name, fields: new Map(), oneofs: new Map() };
    messages.set(name, msgDef);
    if (!rootMessageName) rootMessageName = name;

    while (!this.atPunct('}') && !this.atPunct('EOF')) {
      if (this.atIdent('message')) this.parseMessage();
      else if (this.atIdent('enum')) this.parseEnum();
      else if (this.atIdent('oneof')) this.parseOneof(msgDef);
      else if (this.atIdent('reserved')) { this.next(); this.skipToSemicolon(); }
      else if (this.atIdent('option')) this.skipToSemicolon();
      else if (this.atIdent('map')) this.parseMapField(msgDef);
      else this.parseField(msgDef);
    }
    this.expectPunct('}');
  }

  parseEnum(): void {
    this.next();
    const name = this.next().value;
    this.expectPunct('{');
    const enumDef: EnumDef = { name, values: new Map() };
    enums.set(name, enumDef);

    while (!this.atPunct('}') && !this.atPunct('EOF')) {
      if (this.atIdent('option') || this.atIdent('reserved')) { this.next(); this.skipToSemicolon(); }
      else if (this.peek().type === 'ident') {
        const valueName = this.next().value;
        this.expectPunct('=');
        const num = parseInt(this.next().value, 10);
        enumDef.values.set(num, valueName);
        this.skipFieldOptions();
        if (this.atPunct(';')) this.next();
      } else {
        this.next();
      }
    }
    this.expectPunct('}');
  }

  parseOneof(msgDef: MessageDef): void {
    this.next();
    const name = this.next().value;
    this.expectPunct('{');
    const fieldNumbers: number[] = [];

    while (!this.atPunct('}') && !this.atPunct('EOF')) {
      if (this.atIdent('option')) { this.skipToSemicolon(); }
      else if (this.atIdent('map')) {
        const num = this.parseMapField(msgDef, name);
        fieldNumbers.push(num);
      } else {
        const type = this.next().value;
        const fname = this.next().value;
        this.expectPunct('=');
        const number = parseInt(this.next().value, 10);
        this.skipFieldOptions();
        if (this.atPunct(';')) this.next();
        msgDef.fields.set(number, { name: fname, number, type, label: 'singular', isMap: false, oneofName: name });
        fieldNumbers.push(number);
      }
    }
    this.expectPunct('}');
    msgDef.oneofs.set(name, fieldNumbers);
  }

  parseField(msgDef: MessageDef): void {
    let label: 'singular' | 'repeated' | 'optional' = 'singular';
    if (this.atIdent('repeated') || this.atIdent('optional')) {
      label = this.next().value as 'repeated' | 'optional';
    }
    const type = this.next().value;
    const name = this.next().value;
    this.expectPunct('=');
    const number = parseInt(this.next().value, 10);
    this.skipFieldOptions();
    if (this.atPunct(';')) this.next();
    msgDef.fields.set(number, { name, number, type, label, isMap: false });
  }

  parseMapField(msgDef: MessageDef, oneofName?: string): number {
    this.next(); // 'map'
    this.expectPunct('<');
    const keyType = this.next().value;
    this.expectPunct(',');
    const valueType = this.next().value;
    this.expectPunct('>');
    const name = this.next().value;
    this.expectPunct('=');
    const number = parseInt(this.next().value, 10);
    this.skipFieldOptions();
    if (this.atPunct(';')) this.next();
    msgDef.fields.set(number, { name, number, type: 'map', label: 'repeated', isMap: true, mapKeyType: keyType, mapValueType: valueType, oneofName });
    return number;
  }
}

// --- Wire Format ---
class WireReader {
  buffer: Buffer;
  pos: number;
  constructor(buffer: Buffer) { this.buffer = buffer; this.pos = 0; }
  hasMore(): boolean { return this.pos < this.buffer.length; }

  readVarint(): bigint {
    let result = 0n;
    let shift = 0n;
    let byte: number;
    let count = 0;
    do {
      byte = this.buffer[this.pos++];
      result |= BigInt(byte & 0x7F) << shift;
      shift += 7n;
      count++;
    } while ((byte & 0x80) !== 0 && count < 10);
    return result;
  }

  readTag(): { fieldNumber: number; wireType: number } {
    const key = this.readVarint();
    return { fieldNumber: Number(key >> 3), wireType: Number(key & 7n) };
  }

  readFixed32(): number {
    const v = this.buffer.readUInt32LE(this.pos);
    this.pos += 4;
    return v;
  }

  readFixed64(): bigint {
    const v = this.buffer.readBigUInt64LE(this.pos);
    this.pos += 8;
    return v;
  }

  readLengthDelimited(): Buffer {
    const len = Number(this.readVarint());
    const data = this.buffer.subarray(this.pos, this.pos + len);
    this.pos += len;
    return data;
  }

  skipField(fieldNumber: number, wireType: number): void {
    switch (wireType) {
      case 0: this.readVarint(); break;
      case 1: this.pos += 8; break;
      case 2: { const len = Number(this.readVarint()); this.pos += len; break; }
      case 5: this.pos += 4; break;
      case 3: {
        while (this.hasMore()) {
          const tag = this.readTag();
          if (tag.wireType === 4 && tag.fieldNumber === fieldNumber) break;
          this.skipField(tag.fieldNumber, tag.wireType);
        }
        break;
      }
      case 4: break;
    }
  }
}

// --- Type helpers ---
function isMessageType(type: string): boolean { return messages.has(type); }

function isPackableType(type: string): boolean {
  return ['int32','int64','uint32','uint64','sint32','sint64','fixed32','fixed64','sfixed32','sfixed64','bool'].includes(type) || enums.has(type);
}

const VARINT_TYPES = new Set(['int32','int64','uint32','uint64','sint32','sint64','bool']);
const FIXED32_TYPES = new Set(['fixed32','sfixed32']);
const FIXED64_TYPES = new Set(['fixed64','sfixed64']);
const INT32_OUT = new Set(['int32','uint32','sint32','fixed32','sfixed32']);
const INT64_OUT = new Set(['int64','uint64','sint64','fixed64','sfixed64']);

function decodeInt32(v: bigint): number {
  const low = Number(v & 0xFFFFFFFFn);
  return low >= 0x80000000 ? low - 0x100000000 : low;
}

function decodeUint32(v: bigint): number {
  return Number(v & 0xFFFFFFFFn);
}

function decodeSint32(v: bigint): number {
  const n = Number(v & 0xFFFFFFFFn);
  return (n >>> 1) ^ -(n & 1);
}

function decodeInt64(v: bigint): bigint {
  const MASK = (1n << 64n) - 1n;
  const n = v & MASK;
  return n >= (1n << 63n) ? n - (1n << 64n) : n;
}

function decodeSint64(v: bigint): bigint {
  return (v >> 1n) ^ -(v & 1n);
}

function decodeVarintScalar(v: bigint, type: string): any {
  switch (type) {
    case 'int32': return decodeInt32(v);
    case 'uint32': return decodeUint32(v);
    case 'sint32': return decodeSint32(v);
    case 'int64': return decodeInt64(v);
    case 'uint64': return v & ((1n << 64n) - 1n);
    case 'sint64': return decodeSint64(v);
    case 'bool': return v !== 0n;
    default: return decodeInt32(v); // enum
  }
}

function decodeFixed32Scalar(v: number, type: string): any {
  if (type === 'sfixed32') return v | 0;
  return v; // fixed32
}

function decodeFixed64Scalar(v: bigint, type: string): any {
  if (type === 'sfixed64') {
    const MASK = (1n << 64n) - 1n;
    const n = v & MASK;
    return n >= (1n << 63n) ? n - (1n << 64n) : n;
  }
  return v; // fixed64
}

function decodeFieldValue(reader: WireReader, type: string, wireType: number): any {
  if (isMessageType(type)) {
    const data = reader.readLengthDelimited();
    return decodeMessage(new WireReader(data), messages.get(type)!);
  }
  if (type === 'string') return reader.readLengthDelimited().toString('utf8');
  if (type === 'bytes') return reader.readLengthDelimited();
  switch (wireType) {
    case 0: return decodeVarintScalar(reader.readVarint(), type);
    case 1: return decodeFixed64Scalar(reader.readFixed64(), type);
    case 5: return decodeFixed32Scalar(reader.readFixed32(), type);
    default: throw new Error(`Unexpected wire type ${wireType} for type ${type}`);
  }
}

function getDefault(type: string): any {
  if (isMessageType(type)) return { fields: new Map(), present: new Set(), oneofSet: new Map() };
  if (type === 'string') return '';
  if (type === 'bytes') return Buffer.alloc(0);
  if (type === 'bool') return false;
  if (INT64_OUT.has(type)) return 0n;
  return 0;
}

// --- Message Decoder ---
function decodeMessage(reader: WireReader, msgDef: MessageDef): DecodedMsg {
  const result: DecodedMsg = { fields: new Map(), present: new Set(), oneofSet: new Map() };

  while (reader.hasMore()) {
    const tag = reader.readTag();
    const { fieldNumber, wireType } = tag;
    const fieldDef = msgDef.fields.get(fieldNumber);

    if (!fieldDef) {
      reader.skipField(fieldNumber, wireType);
      continue;
    }

    if (fieldDef.isMap) {
      const entryData = reader.readLengthDelimited();
      const entryReader = new WireReader(entryData);
      let key = getDefault(fieldDef.mapKeyType!);
      let value = getDefault(fieldDef.mapValueType!);
      while (entryReader.hasMore()) {
        const etag = entryReader.readTag();
        if (etag.fieldNumber === 1) {
          key = decodeFieldValue(entryReader, fieldDef.mapKeyType!, etag.wireType);
        } else if (etag.fieldNumber === 2) {
          value = decodeFieldValue(entryReader, fieldDef.mapValueType!, etag.wireType);
        } else {
          entryReader.skipField(etag.fieldNumber, etag.wireType);
        }
      }
      let map = result.fields.get(fieldNumber) as Map<any, any>;
      if (!map) { map = new Map(); result.fields.set(fieldNumber, map); }
      map.set(key, value);
      result.present.add(fieldNumber);
    } else if (fieldDef.label === 'repeated') {
      if (isPackableType(fieldDef.type) && wireType === 2) {
        const packedData = reader.readLengthDelimited();
        const packedReader = new WireReader(packedData);
        let arr = result.fields.get(fieldNumber) as any[];
        if (!arr) { arr = []; result.fields.set(fieldNumber, arr); }
        while (packedReader.hasMore()) {
          arr.push(decodeFieldValue(packedReader, fieldDef.type, packedReader.readTag().wireType));
        }
      } else {
        let arr = result.fields.get(fieldNumber) as any[];
        if (!arr) { arr = []; result.fields.set(fieldNumber, arr); }
        arr.push(decodeFieldValue(reader, fieldDef.type, wireType));
      }
      result.present.add(fieldNumber);
    } else if (fieldDef.oneofName) {
      const prevMember = result.oneofSet.get(fieldDef.oneofName);
      if (prevMember !== undefined && prevMember !== fieldNumber) {
        result.fields.delete(prevMember);
        result.present.delete(prevMember);
      }
      result.oneofSet.set(fieldDef.oneofName, fieldNumber);
      if (isMessageType(fieldDef.type)) {
        const subData = reader.readLengthDelimited();
        const subDef = messages.get(fieldDef.type)!;
        const subMsg = decodeMessage(new WireReader(subData), subDef);
        if (prevMember === fieldNumber && result.fields.has(fieldNumber)) {
          mergeMessages(result.fields.get(fieldNumber) as DecodedMsg, subMsg, subDef);
        } else {
          result.fields.set(fieldNumber, subMsg);
        }
      } else {
        result.fields.set(fieldNumber, decodeFieldValue(reader, fieldDef.type, wireType));
      }
      result.present.add(fieldNumber);
    } else {
      // singular, not in oneof
      if (isMessageType(fieldDef.type)) {
        const subData = reader.readLengthDelimited();
        const subDef = messages.get(fieldDef.type)!;
        const subMsg = decodeMessage(new WireReader(subData), subDef);
        if (result.fields.has(fieldNumber)) {
          mergeMessages(result.fields.get(fieldNumber) as DecodedMsg, subMsg, subDef);
        } else {
          result.fields.set(fieldNumber, subMsg);
        }
      } else {
        result.fields.set(fieldNumber, decodeFieldValue(reader, fieldDef.type, wireType));
      }
      result.present.add(fieldNumber);
    }
  }
  return result;
}

function mergeMessages(dst: DecodedMsg, src: DecodedMsg, msgDef: MessageDef): void {
  for (const fieldNum of src.present) {
    const fieldDef = msgDef.fields.get(fieldNum);
    if (!fieldDef) continue;

    if (fieldDef.isMap) {
      const srcMap = src.fields.get(fieldNum) as Map<any, any>;
      let dstMap = dst.fields.get(fieldNum) as Map<any, any>;
      if (!dstMap) { dstMap = new Map(); dst.fields.set(fieldNum, dstMap); }
      for (const [k, v] of srcMap) dstMap.set(k, v);
    } else if (fieldDef.label === 'repeated') {
      const srcArr = src.fields.get(fieldNum) as any[];
      let dstArr = dst.fields.get(fieldNum) as any[];
      if (!dstArr) { dstArr = []; dst.fields.set(fieldNum, dstArr); }
      dstArr.push(...srcArr);
    } else if (isMessageType(fieldDef.type)) {
      const srcVal = src.fields.get(fieldNum) as DecodedMsg;
      const dstVal = dst.fields.get(fieldNum);
      if (dstVal !== undefined) {
        mergeMessages(dstVal as DecodedMsg, srcVal, messages.get(fieldDef.type)!);
      } else {
        dst.fields.set(fieldNum, srcVal);
      }
    } else {
      dst.fields.set(fieldNum, src.fields.get(fieldNum));
    }
    dst.present.add(fieldNum);
  }

  for (const [oneofName, fieldNum] of src.oneofSet) {
    if (src.present.has(fieldNum)) {
      const prevMember = dst.oneofSet.get(oneofName);
      if (prevMember !== undefined && prevMember !== fieldNum) {
        dst.fields.delete(prevMember);
        dst.present.delete(prevMember);
      }
      dst.oneofSet.set(oneofName, fieldNum);
    }
  }
}

// --- JSON Output ---
function toCamelCase(name: string): string {
  let result = '';
  let upperNext = false;
  for (const ch of name) {
    if (ch === '_') { upperNext = true; }
    else {
      if (upperNext && ch >= 'a' && ch <= 'z') result += ch.toUpperCase();
      else result += ch;
      upperNext = false;
    }
  }
  return result;
}

function escapeJsonString(s: string): string {
  let result = '';
  for (let i = 0; i < s.length; i++) {
    const code = s.codePointAt(i)!;
    if (s[i] === '"') result += '\\"';
    else if (s[i] === '\\') result += '\\\\';
    else if (code === 8) result += '\\b';
    else if (code === 9) result += '\\t';
    else if (code === 10) result += '\\n';
    else if (code === 12) result += '\\f';
    else if (code === 13) result += '\\r';
    else if (code < 0x20) result += '\\u' + code.toString(16).padStart(4, '0');
    else result += s[i];
  }
  return '"' + result + '"';
}

function isDefaultScalar(value: any, type: string): boolean {
  if (type === 'bool') return value === false;
  if (type === 'string') return value === '';
  if (type === 'bytes') return value.length === 0;
  if (enums.has(type)) return value === 0;
  if (INT64_OUT.has(type)) return value === 0n;
  return value === 0;
}

function valueToJson(value: any, type: string): string {
  if (isMessageType(type)) return messageToJson(value as DecodedMsg, messages.get(type)!);
  if (type === 'string') return escapeJsonString(value as string);
  if (type === 'bytes') return '"' + (value as Buffer).toString('base64') + '"';
  if (type === 'bool') return value ? 'true' : 'false';
  if (enums.has(type)) {
    const enumDef = enums.get(type)!;
    const name = enumDef.values.get(value as number);
    return name !== undefined ? '"' + name + '"' : String(value);
  }
  if (INT64_OUT.has(type)) return '"' + (value as bigint).toString() + '"';
  return String(value);
}

function compareStringsByCodePoint(a: string, b: string): number {
  const arrA = [...a];
  const arrB = [...b];
  const minLen = Math.min(arrA.length, arrB.length);
  for (let i = 0; i < minLen; i++) {
    const cpA = arrA[i].codePointAt(0)!;
    const cpB = arrB[i].codePointAt(0)!;
    if (cpA !== cpB) return cpA < cpB ? -1 : 1;
  }
  return arrA.length - arrB.length;
}

function mapToJson(map: Map<any, any>, fieldDef: FieldDef): string {
  const entries: [string, string][] = [];
  const isIntKey = fieldDef.mapKeyType === 'int32';
  const isStringKey = fieldDef.mapKeyType === 'string';

  for (const [k, v] of map) {
    const keyStr = isIntKey ? String(k) : escapeJsonString(k as string);
    const valStr = valueToJson(v, fieldDef.mapValueType!);
    entries.push([keyStr, valStr]);
  }

  if (isStringKey) {
    entries.sort((a, b) => compareStringsByCodePoint(a[0], b[0]));
  } else {
    entries.sort((a, b) => Number(a[0]) - Number(b[0]));
  }

  return '{' + entries.map(([k, v]) => k + ':' + v).join(',') + '}';
}

function arrayToJson(arr: any[], fieldDef: FieldDef): string {
  return '[' + arr.map(el => valueToJson(el, fieldDef.type)).join(',') + ']';
}

function messageToJson(msg: DecodedMsg, msgDef: MessageDef): string {
  const parts: string[] = [];
  const fieldNumbers = [...msgDef.fields.keys()].sort((a, b) => a - b);

  for (const fieldNum of fieldNumbers) {
    const fieldDef = msgDef.fields.get(fieldNum)!;
    const jsonName = toCamelCase(fieldDef.name);

    if (fieldDef.isMap) {
      const map = msg.fields.get(fieldNum) as Map<any, any> | undefined;
      if (!map || map.size === 0) continue;
      parts.push('"' + jsonName + '":' + mapToJson(map, fieldDef));
    } else if (fieldDef.label === 'repeated') {
      const arr = msg.fields.get(fieldNum) as any[] | undefined;
      if (!arr || arr.length === 0) continue;
      parts.push('"' + jsonName + '":' + arrayToJson(arr, fieldDef));
    } else if (fieldDef.oneofName) {
      const setMember = msg.oneofSet.get(fieldDef.oneofName);
      if (setMember !== fieldNum) continue;
      const value = msg.fields.get(fieldNum);
      if (value === undefined) continue;
      parts.push('"' + jsonName + '":' + valueToJson(value, fieldDef.type));
    } else if (isMessageType(fieldDef.type)) {
      if (!msg.present.has(fieldNum)) continue;
      const value = msg.fields.get(fieldNum);
      parts.push('"' + jsonName + '":' + valueToJson(value, fieldDef.type));
    } else {
      // singular scalar, not in oneof
      if (!msg.present.has(fieldNum)) continue;
      const value = msg.fields.get(fieldNum);
      if (fieldDef.label !== 'optional' && isDefaultScalar(value, fieldDef.type)) continue;
      parts.push('"' + jsonName + '":' + valueToJson(value, fieldDef.type));
    }
  }

  return '{' + parts.join(',') + '}';
}

// --- Main ---
function main(): void {
  const dir = process.argv[2];
  const schemaPath = path.join(dir, 'schema.proto');
  const messagesPath = path.join(dir, 'messages.bin');

  const schemaContent = fs.readFileSync(schemaPath, 'utf8');
  const stripped = stripComments(schemaContent);
  const tokens = tokenize(stripped);
  const parser = new ProtoParser(tokens);
  parser.parseProto();

  const binData = fs.readFileSync(messagesPath);
  let pos = 0;
  const rootDef = messages.get(rootMessageName)!;
  const lines: string[] = [];

  while (pos < binData.length) {
    // Read varint length
    let len = 0;
    let shift = 0;
    let byte: number;
    do {
      byte = binData[pos++];
      len |= (byte & 0x7F) << shift;
      shift += 7;
    } while ((byte & 0x80) !== 0);

    const msgData = binData.subarray(pos, pos + len);
    pos += len;

    const reader = new WireReader(msgData);
    const decoded = decodeMessage(reader, rootDef);
    lines.push(messageToJson(decoded, rootDef));
  }

  if (lines.length > 0) {
    process.stdout.write(lines.join('\n') + '\n');
  }
}

main();

import * as fs from 'fs';
import * as path from 'path';

// --- Schema types ---
interface FieldDef {
  name: string;
  number: number;
  type: string;
  label: 'singular' | 'repeated' | 'optional';
  isMap: boolean;
  mapKeyType?: string;
  mapValueType?: string;
  oneofName?: string;
}

interface MessageDef {
  name: string;
  fields: Map<number, FieldDef>;
  oneofs: Map<string, number[]>;
}

interface EnumDef {
  name: string;
  values: Map<number, string>;
}

interface DecodedMsg {
  fields: Map<number, any>;
  present: Set<number>;
  oneofSet: Map<string, number>;
}

let messages = new Map<string, MessageDef>();
let enums = new Map<string, EnumDef>();
let rootMessageName = '';

// --- Proto Parser ---
function stripComments(input: string): string {
  let result = '';
  let i = 0;
  while (i < input.length) {
    if (input[i] === '/' && i + 1 < input.length && input[i + 1] === '/') {
      i += 2;
      while (i < input.length && input[i] !== '\n') i++;
    } else if (input[i] === '/' && i + 1 < input.length && input[i + 1] === '*') {
      i += 2;
      while (i + 1 < input.length && !(input[i] === '*' && input[i + 1] === '/')) i++;
      i += 2;
    } else if (input[i] === '"') {
      result += input[i]; i++;
      while (i < input.length && input[i] !== '"') {
        if (input[i] === '\\') { result += input[i]; i++; }
        if (i < input.length) { result += input[i]; i++; }
      }
      if (i < input.length) { result += input[i]; i++; }
    } else {
      result += input[i]; i++;
    }
  }
  return result;
}

type Token = { type: 'ident' | 'string' | 'number' | 'punct'; value: string };

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < input.length) {
    if (/\s/.test(input[i])) { i++; continue; }
    if (input[i] === '"') {
      let s = ''; i++;
      while (i < input.length && input[i] !== '"') {
        if (input[i] === '\\') { i++; }
        if (i < input.length) { s += input[i]; i++; }
      }
      if (i < input.length) i++;
      tokens.push({ type: 'string', value: s });
    } else if (/[a-zA-Z_]/.test(input[i])) {
      let s = '';
      while (i < input.length && /[a-zA-Z0-9_.]/.test(input[i])) { s += input[i]; i++; }
      tokens.push({ type: 'ident', value: s });
    } else if (/[0-9]/.test(input[i]) || (input[i] === '-' && i + 1 < input.length && /[0-9]/.test(input[i + 1]))) {
      let s = '';
      if (input[i] === '-') { s += '-'; i++; }
      while (i < input.length && /[0-9]/.test(input[i])) { s += input[i]; i++; }
      tokens.push({ type: 'number', value: s });
    } else {
      tokens.push({ type: 'punct', value: input[i] }); i++;
    }
  }
  tokens.push({ type: 'punct', value: 'EOF' });
  return tokens;
}

class ProtoParser {
  tokens: Token[];
  pos = 0;
  constructor(tokens: Token[]) { this.tokens = tokens; }
  peek(): Token { return this.tokens[this.pos]; }
  next(): Token { return this.tokens[this.pos++]; }
  atIdent(name: string): boolean { return this.peek().type === 'ident' && this.peek().value === name; }
  atPunct(p: string): boolean { return this.peek().type === 'punct' && this.peek().value === p; }

  expectPunct(p: string): void {
    const t = this.next();
    if (t.type !== 'punct' || t.value !== p) throw new Error(`Expected '${p}' got '${t.value}'`);
  }

  skipToSemicolon(): void {
    while (!this.atPunct(';') && !this.atPunct('EOF')) this.next();
    if (this.atPunct(';')) this.next();
  }

  skipFieldOptions(): void {
    if (this.atPunct('[')) {
      this.next();
      let depth = 1;
      while (!this.atPunct('EOF') && depth > 0) {
        if (this.atPunct('[')) depth++;
        else if (this.atPunct(']')) { depth--; if (depth === 0) break; }
        this.next();
      }
      if (this.atPunct(']')) this.next();
    }
  }

  parseProto(): void {
    while (!this.atPunct('EOF')) {
      if (this.atIdent('syntax') || this.atIdent('package') || this.atIdent('option')) {
        this.skipToSemicolon();
      } else if (this.atIdent('message')) {
        this.parseMessage();
      } else if (this.atIdent('enum')) {
        this.parseEnum();
      } else {
        this.skipToSemicolon();
      }
    }
  }

  parseMessage(): void {
    this.next();
    const name = this.next().value;
    this.expectPunct('{');
    const msgDef: MessageDef = { name, fields: new Map(), oneofs: new Map() };
    messages.set(name, msgDef);
    if (!rootMessageName) rootMessageName = name;

    while (!this.atPunct('}') && !this.atPunct('EOF')) {
      if (this.atIdent('message')) this.parseMessage();
      else if (this.atIdent('enum')) this.parseEnum();
      else if (this.atIdent('oneof')) this.parseOneof(msgDef);
      else if (this.atIdent('reserved')) { this.next(); this.skipToSemicolon(); }
      else if (this.atIdent('option')) this.skipToSemicolon();
      else if (this.atIdent('map')) this.parseMapField(msgDef);
      else this.parseField(msgDef);
    }
    this.expectPunct('}');
  }

  parseEnum(): void {
    this.next();
    const name = this.next().value;
    this.expectPunct('{');
    const enumDef: EnumDef = { name, values: new Map() };
    enums.set(name, enumDef);

    while (!this.atPunct('}') && !this.atPunct('EOF')) {
      if (this.atIdent('option') || this.atIdent('reserved')) { this.next(); this.skipToSemicolon(); }
      else if (this.peek().type === 'ident') {
        const valueName = this.next().value;
        this.expectPunct('=');
        const num = parseInt(this.next().value, 10);
        enumDef.values.set(num, valueName);
        this.skipFieldOptions();
        if (this.atPunct(';')) this.next();
      } else {
        this.next();
      }
    }
    this.expectPunct('}');
  }

  parseOneof(msgDef: MessageDef): void {
    this.next();
    const name = this.next().value;
    this.expectPunct('{');
    const fieldNumbers: number[] = [];

    while (!this.atPunct('}') && !this.atPunct('EOF')) {
      if (this.atIdent('option')) { this.skipToSemicolon(); }
      else if (this.atIdent('map')) {
        const num = this.parseMapField(msgDef, name);
        fieldNumbers.push(num);
      } else {
        const type = this.next().value;
        const fname = this.next().value;
        this.expectPunct('=');
        const number = parseInt(this.next().value, 10);
        this.skipFieldOptions();
        if (this.atPunct(';')) this.next();
        msgDef.fields.set(number, { name: fname, number, type, label: 'singular', isMap: false, oneofName: name });
        fieldNumbers.push(number);
      }
    }
    this.expectPunct('}');
    msgDef.oneofs.set(name, fieldNumbers);
  }

  parseField(msgDef: MessageDef): void {
    let label: 'singular' | 'repeated' | 'optional' = 'singular';
    if (this.atIdent('repeated') || this.atIdent('optional')) {
      label = this.next().value as 'repeated' | 'optional';
    }
    const type = this.next().value;
    const name = this.next().value;
    this.expectPunct('=');
    const number = parseInt(this.next().value, 10);
    this.skipFieldOptions();
    if (this.atPunct(';')) this.next();
    msgDef.fields.set(number, { name, number, type, label, isMap: false });
  }

  parseMapField(msgDef: MessageDef, oneofName?: string): number {
    this.next(); // 'map'
    this.expectPunct('<');
    const keyType = this.next().value;
    this.expectPunct(',');
    const valueType = this.next().value;
    this.expectPunct('>');
    const name = this.next().value;
    this.expectPunct('=');
    const number = parseInt(this.next().value, 10);
    this.skipFieldOptions();
    if (this.atPunct(';')) this.next();
    msgDef.fields.set(number, { name, number, type: 'map', label: 'repeated', isMap: true, mapKeyType: keyType, mapValueType: valueType, oneofName });
    return number;
  }
}

// --- Wire Format ---
class WireReader {
  buffer: Buffer;
  pos: number;
  constructor(buffer: Buffer) { this.buffer = buffer; this.pos = 0; }
  hasMore(): boolean { return this.pos < this.buffer.length; }

  readVarint(): bigint {
    let result = 0n;
    let shift = 0n;
    let byte: number;
    let count = 0;
    do {
      byte = this.buffer[this.pos++];
      result |= BigInt(byte & 0x7F) << shift;
      shift += 7n;
      count++;
    } while ((byte & 0x80) !== 0 && count < 10);
    return result;
  }

  readTag(): { fieldNumber: number; wireType: number } {
    const key = this.readVarint();
    return { fieldNumber: Number(key >> 3n), wireType: Number(key & 7n) };
  }

  readFixed32(): number {
    const v = this.buffer.readUInt32LE(this.pos);
    this.pos += 4;
    return v;
  }

  readFixed64(): bigint {
    const v = this.buffer.readBigUInt64LE(this.pos);
    this.pos += 8;
    return v;
  }

  readLengthDelimited(): Buffer {
    const len = Number(this.readVarint());
    const data = this.buffer.subarray(this.pos, this.pos + len);
    this.pos += len;
    return data;
  }

  skipField(fieldNumber: number, wireType: number): void {
    switch (wireType) {
      case 0: this.readVarint(); break;
      case 1: this.pos += 8; break;
      case 2: { const len = Number(this.readVarint()); this.pos += len; break; }
      case 5: this.pos += 4; break;
      case 3: {
        while (this.hasMore()) {
          const tag = this.readTag();
          if (tag.wireType === 4 && tag.fieldNumber === fieldNumber) break;
          this.skipField(tag.fieldNumber, tag.wireType);
        }
        break;
      }
      case 4: break;
    }
  }
}

// --- Type helpers ---
function isMessageType(type: string): boolean { return messages.has(type); }

function isPackableType(type: string): boolean {
  return ['int32','int64','uint32','uint64','sint32','sint64','fixed32','fixed64','sfixed32','sfixed64','bool'].includes(type) || enums.has(type);
}

const VARINT_TYPES = new Set(['int32','int64','uint32','uint64','sint32','sint64','bool']);
const FIXED32_TYPES = new Set(['fixed32','sfixed32']);
const FIXED64_TYPES = new Set(['fixed64','sfixed64']);
const INT32_OUT = new Set(['int32','uint32','sint32','fixed32','sfixed32']);
const INT64_OUT = new Set(['int64','uint64','sint64','fixed64','sfixed64']);

function decodeInt32(v: bigint): number {
  const low = Number(v & 0xFFFFFFFFn);
  return low >= 0x80000000 ? low - 0x100000000 : low;
}

function decodeUint32(v: bigint): number {
  return Number(v & 0xFFFFFFFFn);
}

function decodeSint32(v: bigint): number {
  const n = Number(v & 0xFFFFFFFFn);
  return (n >>> 1) ^ -(n & 1);
}

function decodeInt64(v: bigint): bigint {
  const MASK = (1n << 64n) - 1n;
  const n = v & MASK;
  return n >= (1n << 63n) ? n - (1n << 64n) : n;
}

function decodeSint64(v: bigint): bigint {
  return (v >> 1n) ^ -(v & 1n);
}

function decodeVarintScalar(v: bigint, type: string): any {
  switch (type) {
    case 'int32': return decodeInt32(v);
    case 'uint32': return decodeUint32(v);
    case 'sint32': return decodeSint32(v);
    case 'int64': return decodeInt64(v);
    case 'uint64': return v & ((1n << 64n) - 1n);
    case 'sint64': return decodeSint64(v);
    case 'bool': return v !== 0n;
    default: return decodeInt32(v); // enum
  }
}

function decodeFixed32Scalar(v: number, type: string): any {
  if (type === 'sfixed32') return v | 0;
  return v; // fixed32
}

function decodeFixed64Scalar(v: bigint, type: string): any {
  if (type === 'sfixed64') {
    const MASK = (1n << 64n) - 1n;
    const n = v & MASK;
    return n >= (1n << 63n) ? n - (1n << 64n) : n;
  }
  return v; // fixed64
}

function decodeFieldValue(reader: WireReader, type: string, wireType: number): any {
  if (isMessageType(type)) {
    const data = reader.readLengthDelimited();
    return decodeMessage(new WireReader(data), messages.get(type)!);
  }
  if (type === 'string') return reader.readLengthDelimited().toString('utf8');
  if (type === 'bytes') return reader.readLengthDelimited();
  switch (wireType) {
    case 0: return decodeVarintScalar(reader.readVarint(), type);
    case 1: return decodeFixed64Scalar(reader.readFixed64(), type);
    case 5: return decodeFixed32Scalar(reader.readFixed32(), type);
    default: throw new Error(`Unexpected wire type ${wireType} for type ${type}`);
  }
}

function decodePackedElement(reader: WireReader, type: string): any {
  if (VARINT_TYPES.has(type) || enums.has(type)) {
    return decodeVarintScalar(reader.readVarint(), type);
  }
  if (FIXED32_TYPES.has(type)) {
    return decodeFixed32Scalar(reader.readFixed32(), type);
  }
  if (FIXED64_TYPES.has(type)) {
    return decodeFixed64Scalar(reader.readFixed64(), type);
  }
  throw new Error(`Cannot pack type ${type}`);
}

function getDefault(type: string): any {
  if (isMessageType(type)) return { fields: new Map(), present: new Set(), oneofSet: new Map() };
  if (type === 'string') return '';
  if (type === 'bytes') return Buffer.alloc(0);
  if (type === 'bool') return false;
  if (INT64_OUT.has(type)) return 0n;
  return 0;
}

// --- Message Decoder ---
function decodeMessage(reader: WireReader, msgDef: MessageDef): DecodedMsg {
  const result: DecodedMsg = { fields: new Map(), present: new Set(), oneofSet: new Map() };

  while (reader.hasMore()) {
    const tag = reader.readTag();
    const { fieldNumber, wireType } = tag;
    const fieldDef = msgDef.fields.get(fieldNumber);

    if (!fieldDef) {
      reader.skipField(fieldNumber, wireType);
      continue;
    }

    if (fieldDef.isMap) {
      const entryData = reader.readLengthDelimited();
      const entryReader = new WireReader(entryData);
      let key = getDefault(fieldDef.mapKeyType!);
      let value = getDefault(fieldDef.mapValueType!);
      while (entryReader.hasMore()) {
        const etag = entryReader.readTag();
        if (etag.fieldNumber === 1) {
          key = decodeFieldValue(entryReader, fieldDef.mapKeyType!, etag.wireType);
        } else if (etag.fieldNumber === 2) {
          value = decodeFieldValue(entryReader, fieldDef.mapValueType!, etag.wireType);
        } else {
          entryReader.skipField(etag.fieldNumber, etag.wireType);
        }
      }
      let map = result.fields.get(fieldNumber) as Map<any, any>;
      if (!map) { map = new Map(); result.fields.set(fieldNumber, map); }
      map.set(key, value);
      result.present.add(fieldNumber);
    } else if (fieldDef.label === 'repeated') {
      if (isPackableType(fieldDef.type) && wireType === 2) {
        const packedData = reader.readLengthDelimited();
        const packedReader = new WireReader(packedData);
        let arr = result.fields.get(fieldNumber) as any[];
        if (!arr) { arr = []; result.fields.set(fieldNumber, arr); }
        while (packedReader.hasMore()) {
          arr.push(decodePackedElement(packedReader, fieldDef.type));
        }
      } else {
        let arr = result.fields.get(fieldNumber) as any[];
        if (!arr) { arr = []; result.fields.set(fieldNumber, arr); }
        arr.push(decodeFieldValue(reader, fieldDef.type, wireType));
      }
      result.present.add(fieldNumber);
    } else if (fieldDef.oneofName) {
      const prevMember = result.oneofSet.get(fieldDef.oneofName);
      if (prevMember !== undefined && prevMember !== fieldNumber) {
        result.fields.delete(prevMember);
        result.present.delete(prevMember);
      }
      result.oneofSet.set(fieldDef.oneofName, fieldNumber);
      if (isMessageType(fieldDef.type)) {
        const subData = reader.readLengthDelimited();
        const subDef = messages.get(fieldDef.type)!;
        const subMsg = decodeMessage(new WireReader(subData), subDef);
        if (prevMember === fieldNumber && result.fields.has(fieldNumber)) {
          mergeMessages(result.fields.get(fieldNumber) as DecodedMsg, subMsg, subDef);
        } else {
          result.fields.set(fieldNumber, subMsg);
        }
      } else {
        result.fields.set(fieldNumber, decodeFieldValue(reader, fieldDef.type, wireType));
      }
      result.present.add(fieldNumber);
    } else {
      // singular, not in oneof
      if (isMessageType(fieldDef.type)) {
        const subData = reader.readLengthDelimited();
        const subDef = messages.get(fieldDef.type)!;
        const subMsg = decodeMessage(new WireReader(subData), subDef);
        if (result.fields.has(fieldNumber)) {
          mergeMessages(result.fields.get(fieldNumber) as DecodedMsg, subMsg, subDef);
        } else {
          result.fields.set(fieldNumber, subMsg);
        }
      } else {
        result.fields.set(fieldNumber, decodeFieldValue(reader, fieldDef.type, wireType));
      }
      result.present.add(fieldNumber);
    }
  }
  return result;
}

function mergeMessages(dst: DecodedMsg, src: DecodedMsg, msgDef: MessageDef): void {
  for (const fieldNum of src.present) {
    const fieldDef = msgDef.fields.get(fieldNum);
    if (!fieldDef) continue;

    if (fieldDef.isMap) {
      const srcMap = src.fields.get(fieldNum) as Map<any, any>;
      let dstMap = dst.fields.get(fieldNum) as Map<any, any>;
      if (!dstMap) { dstMap = new Map(); dst.fields.set(fieldNum, dstMap); }
      for (const [k, v] of srcMap) dstMap.set(k, v);
    } else if (fieldDef.label === 'repeated') {
      const srcArr = src.fields.get(fieldNum) as any[];
      let dstArr = dst.fields.get(fieldNum) as any[];
      if (!dstArr) { dstArr = []; dst.fields.set(fieldNum, dstArr); }
      dstArr.push(...srcArr);
    } else if (isMessageType(fieldDef.type)) {
      const srcVal = src.fields.get(fieldNum) as DecodedMsg;
      const dstVal = dst.fields.get(fieldNum);
      if (dstVal !== undefined) {
        mergeMessages(dstVal as DecodedMsg, srcVal, messages.get(fieldDef.type)!);
      } else {
        dst.fields.set(fieldNum, srcVal);
      }
    } else {
      dst.fields.set(fieldNum, src.fields.get(fieldNum));
    }
    dst.present.add(fieldNum);
  }

  for (const [oneofName, fieldNum] of src.oneofSet) {
    if (src.present.has(fieldNum)) {
      const prevMember = dst.oneofSet.get(oneofName);
      if (prevMember !== undefined && prevMember !== fieldNum) {
        dst.fields.delete(prevMember);
        dst.present.delete(prevMember);
      }
      dst.oneofSet.set(oneofName, fieldNum);
    }
  }
}

// --- JSON Output ---
function toCamelCase(name: string): string {
  let result = '';
  let upperNext = false;
  for (const ch of name) {
    if (ch === '_') { upperNext = true; }
    else {
      if (upperNext && ch >= 'a' && ch <= 'z') result += ch.toUpperCase();
      else result += ch;
      upperNext = false;
    }
  }
  return result;
}

function escapeJsonString(s: string): string {
  let result = '';
  for (let i = 0; i < s.length; i++) {
    const code = s.codePointAt(i)!;
    if (s[i] === '"') result += '\\"';
    else if (s[i] === '\\') result += '\\\\';
    else if (code === 8) result += '\\b';
    else if (code === 9) result += '\\t';
    else if (code === 10) result += '\\n';
    else if (code === 12) result += '\\f';
    else if (code === 13) result += '\\r';
    else if (code < 0x20) result += '\\u' + code.toString(16).padStart(4, '0');
    else result += s[i];
  }
  return '"' + result + '"';
}

function isDefaultScalar(value: any, type: string): boolean {
  if (type === 'bool') return value === false;
  if (type === 'string') return value === '';
  if (type === 'bytes') return value.length === 0;
  if (enums.has(type)) return value === 0;
  if (INT64_OUT.has(type)) return value === 0n;
  return value === 0;
}

function valueToJson(value: any, type: string): string {
  if (isMessageType(type)) return messageToJson(value as DecodedMsg, messages.get(type)!);
  if (type === 'string') return escapeJsonString(value as string);
  if (type === 'bytes') return '"' + (value as Buffer).toString('base64') + '"';
  if (type === 'bool') return value ? 'true' : 'false';
  if (enums.has(type)) {
    const enumDef = enums.get(type)!;
    const name = enumDef.values.get(value as number);
    return name !== undefined ? '"' + name + '"' : String(value);
  }
  if (INT64_OUT.has(type)) return '"' + (value as bigint).toString() + '"';
  return String(value);
}

function compareStringsByCodePoint(a: string, b: string): number {
  const arrA = [...a];
  const arrB = [...b];
  const minLen = Math.min(arrA.length, arrB.length);
  for (let i = 0; i < minLen; i++) {
    const cpA = arrA[i].codePointAt(0)!;
    const cpB = arrB[i].codePointAt(0)!;
    if (cpA !== cpB) return cpA < cpB ? -1 : 1;
  }
  return arrA.length - arrB.length;
}

function mapToJson(map: Map<any, any>, fieldDef: FieldDef): string {
  const entries: { keyStr: string; valStr: string; sortKey: any }[] = [];
  const isIntKey = fieldDef.mapKeyType === 'int32';

  for (const [k, v] of map) {
    const keyStr = isIntKey ? String(k) : escapeJsonString(k as string);
    const valStr = valueToJson(v, fieldDef.mapValueType!);
    entries.push({ keyStr, valStr, sortKey: k });
  }

  if (isIntKey) {
    entries.sort((a, b) => (a.sortKey as number) - (b.sortKey as number));
  } else {
    entries.sort((a, b) => compareStringsByCodePoint(a.keyStr.slice(1, -1), b.keyStr.slice(1, -1)));
  }

  return '{' + entries.map(e => e.keyStr + ':' + e.valStr).join(',') + '}';
}

function arrayToJson(arr: any[], fieldDef: FieldDef): string {
  return '[' + arr.map(el => valueToJson(el, fieldDef.type)).join(',') + ']';
}

function messageToJson(msg: DecodedMsg, msgDef: MessageDef): string {
  const parts: string[] = [];
  const fieldNumbers = [...msgDef.fields.keys()].sort((a, b) => a - b);

  for (const fieldNum of fieldNumbers) {
    const fieldDef = msgDef.fields.get(fieldNum)!;
    const jsonName = toCamelCase(fieldDef.name);

    if (fieldDef.isMap) {
      const map = msg.fields.get(fieldNum) as Map<any, any> | undefined;
      if (!map || map.size === 0) continue;
      parts.push('"' + jsonName + '":' + mapToJson(map, fieldDef));
    } else if (fieldDef.label === 'repeated') {
      const arr = msg.fields.get(fieldNum) as any[] | undefined;
      if (!arr || arr.length === 0) continue;
      parts.push('"' + jsonName + '":' + arrayToJson(arr, fieldDef));
    } else if (fieldDef.oneofName) {
      const setMember = msg.oneofSet.get(fieldDef.oneofName);
      if (setMember !== fieldNum) continue;
      const value = msg.fields.get(fieldNum);
      if (value === undefined) continue;
      parts.push('"' + jsonName + '":' + valueToJson(value, fieldDef.type));
    } else if (isMessageType(fieldDef.type)) {
      if (!msg.present.has(fieldNum)) continue;
      const value = msg.fields.get(fieldNum);
      parts.push('"' + jsonName + '":' + valueToJson(value, fieldDef.type));
    } else {
      // singular scalar, not in oneof
      if (!msg.present.has(fieldNum)) continue;
      const value = msg.fields.get(fieldNum);
      if (fieldDef.label !== 'optional' && isDefaultScalar(value, fieldDef.type)) continue;
      parts.push('"' + jsonName + '":' + valueToJson(value, fieldDef.type));
    }
  }

  return '{' + parts.join(',') + '}';
}

// --- Main ---
function main(): void {
  const dir = process.argv[2];
  const schemaPath = path.join(dir, 'schema.proto');
  const messagesPath = path.join(dir, 'messages.bin');

  const schemaContent = fs.readFileSync(schemaPath, 'utf8');
  const stripped = stripComments(schemaContent);
  const tokens = tokenize(stripped);
  const parser = new ProtoParser(tokens);
  parser.parseProto();

  const binData = fs.readFileSync(messagesPath);
  let pos = 0;
  const rootDef = messages.get(rootMessageName)!;
  const lines: string[] = [];

  while (pos < binData.length) {
    // Read varint length
    let len = 0;
    let shift = 0;
    let byte: number;
    do {
      byte = binData[pos++];
      len |= (byte & 0x7F) << shift;
      shift += 7;
    } while ((byte & 0x80) !== 0);

    const msgData = binData.subarray(pos, pos + len);
    pos += len;

    const reader = new WireReader(msgData);
    const decoded = decodeMessage(reader, rootDef);
    lines.push(messageToJson(decoded, rootDef));
  }

  if (lines.length > 0) {
    process.stdout.write(lines.join('\n') + '\n');
  }
}

main();

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>

/* ===== Schema ===== */
typedef enum {
    T_INT32, T_INT64, T_UINT32, T_UINT64, T_SINT32, T_SINT64,
    T_BOOL, T_STRING, T_BYTES, T_FIXED32, T_FIXED64, T_SFIXED32, T_SFIXED64,
    T_MESSAGE, T_ENUM
} TypeKind;

#define MAX_MSGS 512
#define MAX_FIELDS 512
#define MAX_ENUMS 512
#define MAX_ENUM_VALS 256
#define MAX_ONEOFS 128
#define NAMEMAX 512

typedef struct {
    char name[NAMEMAX];
    int number;
    char typeName[NAMEMAX];
    TypeKind type;
    int msgIdx;
    int enumIdx;
    int label; /* 0=singular, 1=repeated, 2=optional, 3=oneof */
    int oneofIdx;
    int isMap;
    TypeKind mapKeyType;
    TypeKind mapValueType;
    int mapValueMsgIdx;
    int mapValueEnumIdx;
} FieldDef;

typedef struct {
    char name[NAMEMAX];
    FieldDef fields[MAX_FIELDS];
    int nfields;
    char oneofNames[MAX_ONEOFS][NAMEMAX];
    int noneofs;
} MsgDef;

typedef struct {
    char name[NAMEMAX];
    struct { char name[NAMEMAX]; int number; } values[MAX_ENUM_VALS];
    int nvalues;
} EnumDef;

static MsgDef g_msgs[MAX_MSGS];
static int g_nmsgs;
static EnumDef g_enums[MAX_ENUMS];
static int g_nenums;

/* ===== Parser ===== */
static char *g_src;
static int g_srcLen, g_pos;

static void skipWS(void) {
    while (g_pos < g_srcLen) {
        char c = g_src[g_pos];
        if (isspace((unsigned char)c)) { g_pos++; continue; }
        if (c == '/' && g_pos + 1 < g_srcLen) {
            if (g_src[g_pos+1] == '/') {
                g_pos += 2;
                while (g_pos < g_srcLen && g_src[g_pos] != '\n') g_pos++;
                continue;
            }
            if (g_src[g_pos+1] == '*') {
                g_pos += 2;
                while (g_pos + 1 < g_srcLen && !(g_src[g_pos]=='*' && g_src[g_pos+1]=='/')) g_pos++;
                if (g_pos + 1 < g_srcLen) g_pos += 2;
                continue;
            }
        }
        break;
    }
}

static int peekChar(void) {
    skipWS();
    return g_pos < g_srcLen ? (unsigned char)g_src[g_pos] : -1;
}

static void readIdent(char *buf) {
    skipWS();
    int n = 0;
    while (g_pos < g_srcLen && (isalnum((unsigned char)g_src[g_pos]) || g_src[g_pos] == '_')) {
        if (n < NAMEMAX-1) buf[n++] = g_src[g_pos];
        g_pos++;
    }
    buf[n] = 0;
}

static int readIntTok(void) {
    skipWS();
    int neg = 0;
    if (g_pos < g_srcLen && g_src[g_pos] == '-') { neg = 1; g_pos++; }
    long v = 0;
    while (g_pos < g_srcLen && isdigit((unsigned char)g_src[g_pos])) {
        v = v*10 + (g_src[g_pos]-'0');
        g_pos++;
    }
    return neg ? (int)(-v) : (int)v;
}

static void skipStrLit(void) {
    skipWS();
    if (g_pos < g_srcLen && g_src[g_pos] == '"') {
        g_pos++;
        while (g_pos < g_srcLen && g_src[g_pos] != '"') {
            if (g_src[g_pos] == '\\') g_pos++;
            g_pos++;
        }
        if (g_pos < g_srcLen) g_pos++;
    }
}

static void skipToSemi(void) {
    while (g_pos < g_srcLen) {
        char c = g_src[g_pos];
        if (c == ';') { g_pos++; return; }
        if (c == '"') { skipStrLit(); continue; }
        if (c == '/' && g_pos+1 < g_srcLen) {
            if (g_src[g_pos+1]=='/') { g_pos+=2; while(g_pos<g_srcLen&&g_src[g_pos]!='\n')g_pos++; continue; }
            if (g_src[g_pos+1]=='*') { g_pos+=2; while(g_pos+1<g_srcLen&&!(g_src[g_pos]=='*'&&g_src[g_pos+1]=='/'))g_pos++; if(g_pos+1<g_srcLen)g_pos+=2; continue; }
        }
        g_pos++;
    }
}

static void skipBrackets(void) {
    skipWS();
    if (g_pos < g_srcLen && g_src[g_pos] == '[') {
        int d = 1; g_pos++;
        while (g_pos < g_srcLen && d > 0) {
            if (g_src[g_pos]=='[') d++;
            else if (g_src[g_pos]==']') d--;
            else if (g_src[g_pos]=='"') { skipStrLit(); continue; }
            g_pos++;
        }
    }
}

static void skipBraces(void) {
    skipWS();
    if (g_pos < g_srcLen && g_src[g_pos] == '{') {
        int d = 1; g_pos++;
        while (g_pos < g_srcLen && d > 0) {
            if (g_src[g_pos]=='{') d++;
            else if (g_src[g_pos]=='}') d--;
            else if (g_src[g_pos]=='"') { skipStrLit(); continue; }
            g_pos++;
        }
    }
}

static int isBuiltin(const char *n) {
    static const char *b[] = {"int32","int64","uint32","uint64","sint32","sint64",
        "bool","string","bytes","fixed32","fixed64","sfixed32","sfixed64",NULL};
    for (int i=0;b[i];i++) if(!strcmp(n,b[i])) return 1;
    return 0;
}

static TypeKind bkind(const char *n) {
    if(!strcmp(n,"int32"))return T_INT32; if(!strcmp(n,"int64"))return T_INT64;
    if(!strcmp(n,"uint32"))return T_UINT32; if(!strcmp(n,"uint64"))return T_UINT64;
    if(!strcmp(n,"sint32"))return T_SINT32; if(!strcmp(n,"sint64"))return T_SINT64;
    if(!strcmp(n,"bool"))return T_BOOL; if(!strcmp(n,"string"))return T_STRING;
    if(!strcmp(n,"bytes"))return T_BYTES; if(!strcmp(n,"fixed32"))return T_FIXED32;
    if(!strcmp(n,"fixed64"))return T_FIXED64; if(!strcmp(n,"sfixed32"))return T_SFIXED32;
    if(!strcmp(n,"sfixed64"))return T_SFIXED64;
    return T_MESSAGE;
}

static void parseMsgBody(MsgDef *md);
static void parseEnumBody(EnumDef *ed);

static void parseMsgBody(MsgDef *md) {
    for (;;) {
        int c = peekChar();
        if (c < 0 || c == '}') { if(c=='}') g_pos++; return; }
        char tok[NAMEMAX];
        readIdent(tok);
        if (!strcmp(tok,"message")) {
            char nm[NAMEMAX]; readIdent(nm); skipWS();
            if (g_pos<g_srcLen && g_src[g_pos]=='{') {
                g_pos++;
                MsgDef *n = &g_msgs[g_nmsgs]; memset(n,0,sizeof(*n));
                strcpy(n->name,nm); g_nmsgs++;
                parseMsgBody(n);
            }
        } else if (!strcmp(tok,"enum")) {
            char nm[NAMEMAX]; readIdent(nm); skipWS();
            if (g_pos<g_srcLen && g_src[g_pos]=='{') {
                g_pos++;
                EnumDef *e = &g_enums[g_nenums]; memset(e,0,sizeof(*e));
                strcpy(e->name,nm); g_nenums++;
                parseEnumBody(e);
            }
        } else if (!strcmp(tok,"oneof")) {
            char on[NAMEMAX]; readIdent(on);
            int oi = md->noneofs++; strcpy(md->oneofNames[oi],on);
            skipWS(); if(g_pos<g_srcLen&&g_src[g_pos]=='{') g_pos++;
            for(;;) {
                c=peekChar(); if(c<0||c=='}'){if(c=='}')g_pos++;break;}
                char ty[NAMEMAX],fn[NAMEMAX];
                readIdent(ty);
                if(!strcmp(ty,"option")||!strcmp(ty,"reserved")){skipToSemi();continue;}
                readIdent(fn); skipWS();
                if(g_pos<g_srcLen&&g_src[g_pos]=='=') g_pos++;
                int num=readIntTok(); skipBrackets(); skipToSemi();
                FieldDef*fd=&md->fields[md->nfields++]; memset(fd,0,sizeof(*fd));
                strcpy(fd->name,fn); fd->number=num; strcpy(fd->typeName,ty);
                fd->label=3; fd->oneofIdx=oi;
            }
        } else if (!strcmp(tok,"reserved")||!strcmp(tok,"option")) {
            skipToSemi();
        } else if (!strcmp(tok,"map")) {
            skipWS();
            if (g_pos<g_srcLen && g_src[g_pos]=='<') {
                g_pos++;
                char kt[NAMEMAX],vt[NAMEMAX];
                readIdent(kt); skipWS();
                if(g_pos<g_srcLen&&g_src[g_pos]==',') g_pos++;
                readIdent(vt); skipWS();
                if(g_pos<g_srcLen&&g_src[g_pos]=='>') g_pos++;
                char fn[NAMEMAX]; readIdent(fn); skipWS();
                if(g_pos<g_srcLen&&g_src[g_pos]=='=') g_pos++;
                int num=readIntTok(); skipBrackets(); skipToSemi();
                FieldDef*fd=&md->fields[md->nfields++]; memset(fd,0,sizeof(*fd));
                strcpy(fd->name,fn); fd->number=num; fd->isMap=1; fd->label=1;
                fd->mapKeyType=bkind(kt); strcpy(fd->typeName,vt);
            }
        } else {
            int lbl=0; char ty[NAMEMAX];
            if(!strcmp(tok,"repeated")){lbl=1;readIdent(ty);}
            else if(!strcmp(tok,"optional")){lbl=2;readIdent(ty);}
            else strcpy(ty,tok);
            char fn[NAMEMAX]; readIdent(fn); skipWS();
            if(g_pos<g_srcLen&&g_src[g_pos]=='=') g_pos++;
            int num=readIntTok(); skipBrackets(); skipToSemi();
            FieldDef*fd=&md->fields[md->nfields++]; memset(fd,0,sizeof(*fd));
            strcpy(fd->name,fn); fd->number=num; strcpy(fd->typeName,ty);
            fd->label=lbl; fd->oneofIdx=-1;
        }
    }
}

static void parseEnumBody(EnumDef *ed) {
    for(;;) {
        int c=peekChar(); if(c<0||c=='}'){if(c=='}')g_pos++;return;}
        char tok[NAMEMAX]; readIdent(tok);
        if(!strcmp(tok,"option")||!strcmp(tok,"reserved")){skipToSemi();continue;}
        skipWS(); if(g_pos<g_srcLen&&g_src[g_pos]=='=') g_pos++;
        int v=readIntTok(); skipBrackets(); skipToSemi();
        strcpy(ed->values[ed->nvalues].name,tok);
        ed->values[ed->nvalues].number=v; ed->nvalues++;
    }
}

static void parseSchema(void) {
    for(;;) {
        int c=peekChar(); if(c<0) return;
        char tok[NAMEMAX]; readIdent(tok);
        if(!strcmp(tok,"syntax")||!strcmp(tok,"package")||!strcmp(tok,"option")){skipToSemi();}
        else if(!strcmp(tok,"message")){
            char nm[NAMEMAX]; readIdent(nm); skipWS();
            if(g_pos<g_srcLen&&g_src[g_pos]=='{'){g_pos++;
                MsgDef*m=&g_msgs[g_nmsgs];memset(m,0,sizeof(*m));
                strcpy(m->name,nm);g_nmsgs++;parseMsgBody(m);}
        } else if(!strcmp(tok,"enum")){
            char nm[NAMEMAX]; readIdent(nm); skipWS();
            if(g_pos<g_srcLen&&g_src[g_pos]=='{'){g_pos++;
                EnumDef*e=&g_enums[g_nenums];memset(e,0,sizeof(*e));
                strcpy(e->name,nm);g_nenums++;parseEnumBody(e);}
        } else { skipToSemi(); }
    }
}

static void resolveTypes(void) {
    for(int m=0;m<g_nmsgs;m++){
        for(int f=0;f<g_msgs[m].nfields;f++){
            FieldDef*fd=&g_msgs[m].fields[f];
            if(fd->isMap){
                if(isBuiltin(fd->typeName)){fd->mapValueType=bkind(fd->typeName);}
                else{
                    fd->mapValueType=T_MESSAGE; fd->mapValueMsgIdx=-1; fd->mapValueEnumIdx=-1;
                    for(int i=0;i<g_nmsgs;i++) if(!strcmp(g_msgs[i].name,fd->typeName)){fd->mapValueMsgIdx=i;break;}
                    if(fd->mapValueMsgIdx<0) for(int i=0;i<g_nenums;i++) if(!strcmp(g_enums[i].name,fd->typeName)){fd->mapValueType=T_ENUM;fd->mapValueEnumIdx=i;break;}
                }
            } else {
                if(isBuiltin(fd->typeName)){fd->type=bkind(fd->typeName);}
                else{
                    fd->type=T_MESSAGE; fd->msgIdx=-1; fd->enumIdx=-1;
                    for(int i=0;i<g_nmsgs;i++) if(!strcmp(g_msgs[i].name,fd->typeName)){fd->msgIdx=i;break;}
                    if(fd->msgIdx<0) for(int i=0;i<g_nenums;i++) if(!strcmp(g_enums[i].name,fd->typeName)){fd->type=T_ENUM;fd->enumIdx=i;break;}
                }
            }
        }
    }
}

/* ===== Wire format ===== */
static uint64_t readVarint(const uint8_t *d, int len, int *pos) {
    uint64_t r=0; int shift=0;
    while(*pos<len){
        uint8_t b=d[(*pos)++];
        r|=(uint64_t)(b&0x7F)<<shift;
        if(!(b&0x80)) break;
        shift+=7;
    }
    return r;
}

static uint32_t readFixed32(const uint8_t *d, int len, int *pos) {
    uint32_t v=0;
    if(*pos+4<=len){v=(uint32_t)d[*pos]|((uint32_t)d[*pos+1]<<8)|((uint32_t)d[*pos+2]<<16)|((uint32_t)d[*pos+3]<<24);}
    *pos+=4;
    return v;
}

static uint64_t readFixed64(const uint8_t *d, int len, int *pos) {
    uint64_t v=0;
    if(*pos+8<=len){
        for(int i=0;i<8;i++) v|=(uint64_t)d[*pos+i]<<(i*8);
    }
    *pos+=8;
    return v;
}

static int64_t zigzag64(uint64_t n){return (int64_t)((n>>1)^-(int64_t)(n&1));}
static int32_t zigzag32(uint64_t n){uint32_t v=(uint32_t)n;return (int32_t)((v>>1)^-(int32_t)(v&1));}

static void skipField(const uint8_t *d, int len, int *pos, int wt, int fnum) {
    switch(wt){
        case 0: readVarint(d,len,pos); break;
        case 1: *pos+=8; break;
        case 2: { int sl=(int)readVarint(d,len,pos); *pos+=sl; break; }
        case 5: *pos+=4; break;
        case 3: /* start group: skip until matching end group */
            for(;;){
                if(*pos>=len) return;
                uint64_t k=readVarint(d,len,pos);
                int fn2=(int)(k>>3), wt2=(int)(k&7);
                if(wt2==4&&fn2==fnum) return;
                skipField(d,len,pos,wt2,fn2);
            }
        case 4: break; /* end group, shouldn't reach here normally */
        default: break;
    }
}

/* ===== Decoded message ===== */
typedef struct Val {
    int kind; /* TypeKind */
    int64_t i64;
    uint64_t u64;
    uint8_t *bytes;
    int bytesLen;
    struct DecodedMsg *msg;
} Val;

typedef struct MapEntry {
    Val key;
    Val val;
} MapEntry;

typedef struct {
    int present;
    Val *vals;
    int nvals, maxvals;
    MapEntry *entries;
    int nentries, maxentries;
} FieldData;

typedef struct DecodedMsg {
    MsgDef *def;
    FieldData flds[MAX_FIELDS];
    int oneofSet[MAX_ONEOFS];
} DecodedMsg;

static void initMsg(DecodedMsg *dm, MsgDef *def) {
    dm->def = def;
    memset(dm->flds, 0, sizeof(dm->flds));
    for(int i=0;i<MAX_ONEOFS;i++) dm->oneofSet[i]=-1;
}

static void ensureValCap(FieldData *fd, int need) {
    if(fd->maxvals<need){
        int nc=need>fd->maxvals*2?need:fd->maxvals*2;
        if(nc<4)nc=4;
        fd->vals=realloc(fd->vals,nc*sizeof(Val));
        fd->maxvals=nc;
    }
}

static void ensureMapCap(FieldData *fd, int need) {
    if(fd->maxentries<need){
        int nc=need>fd->maxentries*2?need:fd->maxentries*2;
        if(nc<4)nc=4;
        fd->entries=realloc(fd->entries,nc*sizeof(MapEntry));
        fd->maxentries=nc;
    }
}

static void clearFieldData(FieldData *fd) {
    fd->present=0;
    fd->nvals=0;
    fd->nentries=0;
}

static int isPackable(TypeKind t) {
    switch(t){
        case T_INT32:case T_INT64:case T_UINT32:case T_UINT64:
        case T_SINT32:case T_SINT64:case T_BOOL:case T_ENUM:
        case T_FIXED32:case T_FIXED64:case T_SFIXED32:case T_SFIXED64:
            return 1;
        default: return 0;
    }
}

static void decodeScalarVal(const uint8_t *d, int len, int *pos, int wt, TypeKind t, Val *v) {
    v->kind=t; v->i64=0; v->u64=0; v->bytes=NULL; v->bytesLen=0; v->msg=NULL;
    if(t==T_STRING||t==T_BYTES){
        int sl=(int)readVarint(d,len,pos);
        if(*pos+sl>len) sl=len-*pos;
        v->bytes=(uint8_t*)(d+*pos); v->bytesLen=sl;
        *pos+=sl;
    } else if(t==T_FIXED32){
        v->u64=(uint64_t)readFixed32(d,len,pos);
    } else if(t==T_SFIXED32){
        v->i64=(int64_t)(int32_t)readFixed32(d,len,pos);
    } else if(t==T_FIXED64){
        v->u64=readFixed64(d,len,pos);
    } else if(t==T_SFIXED64){
        v->i64=(int64_t)readFixed64(d,len,pos);
    } else {
        uint64_t raw=readVarint(d,len,pos);
        switch(t){
            case T_INT32: v->i64=(int64_t)(int32_t)(uint32_t)raw; break;
            case T_INT64: v->i64=(int64_t)raw; break;
            case T_UINT32: v->u64=(uint64_t)(uint32_t)raw; break;
            case T_UINT64: v->u64=raw; break;
            case T_SINT32: v->i64=(int64_t)zigzag32(raw); break;
            case T_SINT64: v->i64=zigzag64(raw); break;
            case T_BOOL: v->u64=raw!=0?1:0; break;
            case T_ENUM: v->i64=(int64_t)(int32_t)(uint32_t)raw; break;
            default: v->u64=raw; break;
        }
    }
}

static void decodeInto(DecodedMsg *dm, const uint8_t *d, int len);

static void decodeMapEntry(const uint8_t *d, int len, FieldDef *fd, Val *outKey, Val *outVal) {
    memset(outKey,0,sizeof(Val)); memset(outVal,0,sizeof(Val));
    outKey->kind=fd->mapKeyType;
    outVal->kind=fd->mapValueType;
    int pos=0;
    while(pos<len){
        uint64_t k=readVarint(d,len,&pos);
        int fn=(int)(k>>3),wt=(int)(k&7);
        if(fn==1){
            decodeScalarVal(d,len,&pos,wt,fd->mapKeyType,outKey);
        } else if(fn==2){
            if(fd->mapValueType==T_MESSAGE){
                int sl=(int)readVarint(d,len,&pos);
                if(pos+sl>len) sl=len-pos;
                outVal->kind=T_MESSAGE;
                outVal->msg=(DecodedMsg*)calloc(1,sizeof(DecodedMsg));
                initMsg(outVal->msg,&g_msgs[fd->mapValueMsgIdx]);
                decodeInto(outVal->msg,d+pos,sl);
                pos+=sl;
            } else {
                decodeScalarVal(d,len,&pos,wt,fd->mapValueType,outVal);
            }
        } else {
            skipField(d,len,&pos,wt,fn);
        }
    }
}

static int keyEqual(const Val *a, const Val *b, TypeKind kt) {
    if(kt==T_INT32) return a->i64==b->i64;
    /* string */
    if(a->bytesLen!=b->bytesLen) return 0;
    return memcmp(a->bytes,b->bytes,a->bytesLen)==0;
}

static void decodeInto(DecodedMsg *dm, const uint8_t *d, int len) {
    int pos=0;
    while(pos<len){
        uint64_t key=readVarint(d,len,&pos);
        int fnum=(int)(key>>3), wt=(int)(key&7);
        /* find field */
        int fi=-1;
        for(int i=0;i<dm->def->nfields;i++){
            if(dm->def->fields[i].number==fnum){fi=i;break;}
        }
        if(fi<0){
            skipField(d,len,&pos,wt,fnum);
            continue;
        }
        FieldDef *fd=&dm->def->fields[fi];
        FieldData *fdata=&dm->flds[fi];

        /* oneof handling */
        if(fd->label==3){
            int oi=fd->oneofIdx;
            if(dm->oneofSet[oi]!=fi){
                if(dm->oneofSet[oi]>=0) clearFieldData(&dm->flds[dm->oneofSet[oi]]);
                dm->oneofSet[oi]=fi;
                clearFieldData(fdata);
            }
        }

        if(fd->isMap){
            /* wire type 2, sub-message entry */
            int sl=(int)readVarint(d,len,&pos);
            if(pos+sl>len) sl=len-pos;
            Val k,v;
            decodeMapEntry(d+pos,sl,fd,&k,&v);
            pos+=sl;
            /* insert or replace */
            int found=-1;
            for(int i=0;i<fdata->nentries;i++){
                if(keyEqual(&fdata->entries[i].key,&k,fd->mapKeyType)){found=i;break;}
            }
            if(found>=0){
                /* replace value (free old message if any) */
                if(fdata->entries[found].val.msg) free(fdata->entries[found].val.msg);
                fdata->entries[found].val=v;
            } else {
                ensureMapCap(fdata,fdata->nentries+1);
                fdata->entries[fdata->nentries].key=k;
                fdata->entries[fdata->nentries].val=v;
                fdata->nentries++;
            }
            fdata->present=1;
        } else if(fd->label==1){
            /* repeated */
            if(isPackable(fd->type)&&wt==2){
                int sl=(int)readVarint(d,len,&pos);
                if(pos+sl>len) sl=len-pos;
                int subpos=0;
                while(subpos<sl){
                    Val v;
                    if(fd->type==T_FIXED32||fd->type==T_SFIXED32)
                        decodeScalarVal(d+pos,sl,&subpos,5,fd->type,&v);
                    else if(fd->type==T_FIXED64||fd->type==T_SFIXED64)
                        decodeScalarVal(d+pos,sl,&subpos,1,fd->type,&v);
                    else
                        decodeScalarVal(d+pos,sl,&subpos,0,fd->type,&v);
                    ensureValCap(fdata,fdata->nvals+1);
                    fdata->vals[fdata->nvals++]=v;
                }
                pos+=sl;
            } else if(fd->type==T_MESSAGE){
                int sl=(int)readVarint(d,len,&pos);
                if(pos+sl>len) sl=len-pos;
                Val v; memset(&v,0,sizeof(v));
                v.kind=T_MESSAGE;
                v.msg=(DecodedMsg*)calloc(1,sizeof(DecodedMsg));
                initMsg(v.msg,&g_msgs[fd->msgIdx]);
                decodeInto(v.msg,d+pos,sl);
                pos+=sl;
                ensureValCap(fdata,fdata->nvals+1);
                fdata->vals[fdata->nvals++]=v;
            } else {
                Val v;
                decodeScalarVal(d,len,&pos,wt,fd->type,&v);
                ensureValCap(fdata,fdata->nvals+1);
                fdata->vals[fdata->nvals++]=v;
            }
            fdata->present=1;
        } else {
            /* singular */
            if(fd->type==T_MESSAGE){
                int sl=(int)readVarint(d,len,&pos);
                if(pos+sl>len) sl=len-pos;
                if(!fdata->present){
                    fdata->present=1;
                    ensureValCap(fdata,1);
                    fdata->nvals=1;
                    memset(&fdata->vals[0],0,sizeof(Val));
                    fdata->vals[0].kind=T_MESSAGE;
                    fdata->vals[0].msg=(DecodedMsg*)calloc(1,sizeof(DecodedMsg));
                    initMsg(fdata->vals[0].msg,&g_msgs[fd->msgIdx]);
                }
                decodeInto(fdata->vals[0].msg,d+pos,sl);
                pos+=sl;
            } else {
                fdata->present=1;
                ensureValCap(fdata,1);
                fdata->nvals=1;
                decodeScalarVal(d,len,&pos,wt,fd->type,&fdata->vals[0]);
            }
        }
    }
}

/* ===== Base64 ===== */
static const char b64c[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void b64enc(const uint8_t *data, int len, char *out) {
    int j=0;
    for(int i=0;i<len;i+=3){
        uint32_t n=((uint32_t)data[i])<<16;
        if(i+1<len) n|=((uint32_t)data[i+1])<<8;
        if(i+2<len) n|=((uint32_t)data[i+2]);
        out[j++]=b64c[(n>>18)&0x3F];
        out[j++]=b64c[(n>>12)&0x3F];
        out[j++]=(i+1<len)?b64c[(n>>6)&0x3F]:'=';
        out[j++]=(i+2<len)?b64c[n&0x3F]:'=';
    }
    out[j]=0;
}

/* ===== JSON output ===== */
static void printJsonStr(const uint8_t *data, int len) {
    putchar('"');
    for(int i=0;i<len;i++){
        unsigned char c=data[i];
        if(c=='"') printf("\\\"");
        else if(c=='\\') printf("\\\\");
        else if(c=='\b') printf("\\b");
        else if(c=='\t') printf("\\t");
        else if(c=='\n') printf("\\n");
        else if(c=='\f') printf("\\f");
        else if(c=='\r') printf("\\r");
        else if(c<0x20) printf("\\u%04x",c);
        else putchar(c);
    }
    putchar('"');
}

static void camelCase(const char *in, char *out) {
    int j=0;
    for(int i=0;in[i];i++){
        if(in[i]=='_'){
            i++;
            if(in[i]&&in[i]>='a'&&in[i]<='z') out[j++]=in[i]-32;
            else if(in[i]) out[j++]=in[i];
        } else {
            out[j++]=in[i];
        }
    }
    out[j]=0;
}

static int isDefaultVal(Val *v, TypeKind t) {
    switch(t){
        case T_INT32:case T_INT64:case T_SINT32:case T_SINT64:
        case T_SFIXED32:case T_SFIXED64:
            return v->i64==0;
        case T_UINT32:case T_UINT64:case T_FIXED32:case T_FIXED64:
            return v->u64==0;
        case T_BOOL:
            return v->u64==0;
        case T_ENUM:
            return v->i64==0;
        case T_STRING:case T_BYTES:
            return v->bytesLen==0;
        default: return 1;
    }
}

static void printVal(Val *v, TypeKind t, int msgIdx, int enumIdx);

static void printMsg(DecodedMsg *dm);

static void printVal(Val *v, TypeKind t, int msgIdx, int enumIdx) {
    switch(t){
        case T_INT32: printf("%lld",(long long)v->i64); break;
        case T_INT64: printf("\"%lld\"",(long long)v->i64); break;
        case T_UINT32: printf("%llu",(unsigned long long)v->u64); break;
        case T_UINT64: printf("\"%llu\"",(unsigned long long)v->u64); break;
        case T_SINT32: printf("%lld",(long long)v->i64); break;
        case T_SINT64: printf("\"%lld\"",(long long)v->i64); break;
        case T_FIXED32: printf("%llu",(unsigned long long)v->u64); break;
        case T_FIXED64: printf("\"%llu\"",(unsigned long long)v->u64); break;
        case T_SFIXED32: printf("%lld",(long long)v->i64); break;
        case T_SFIXED64: printf("\"%lld\"",(long long)v->i64); break;
        case T_BOOL: printf(v->u64?"true":"false"); break;
        case T_STRING: printJsonStr(v->bytes,v->bytesLen); break;
        case T_BYTES: {
            char *tmp=(char*)malloc(v->bytesLen*4/3+5);
            b64enc(v->bytes,v->bytesLen,tmp);
            printf("\"%s\"",tmp);
            free(tmp);
            break;
        }
        case T_ENUM: {
            int found=0;
            for(int i=0;i<g_enums[enumIdx].nvalues;i++){
                if(g_enums[enumIdx].values[i].number==(int)v->i64){
                    printf("\"%s\"",g_enums[enumIdx].values[i].name);
                    found=1; break;
                }
            }
            if(!found) printf("%lld",(long long)v->i64);
            break;
        }
        case T_MESSAGE:
            printMsg(v->msg);
            break;
    }
}

