/* For sorting fields by number, I'll just collect indices and sort */
typedef struct { int idx; int number; } FieldSort;
static int cmpFS(const void *a, const void *b) {
    return ((FieldSort*)a)->number - ((FieldSort*)b)->number;
}

/* For map key sorting */
typedef struct { int idx; const Val *key; } MapSort;
static TypeKind g_curMapKeyType;
static int cmpMapStr(const void *a, const void *b) {
    const Val *ka=((MapSort*)a)->key, *kb=((MapSort*)b)->key;
    int la=ka->bytesLen, lb=kb->bytesLen;
    int ml=la<lb?la:lb;
    int r=memcmp(ka->bytes,kb->bytes,ml);
    if(r) return r;
    return la-lb;
}
static int cmpMapInt(const void *a, const void *b) {
    int64_t ka=((MapSort*)a)->key->i64, kb=((MapSort*)b)->key->i64;
    if(ka<kb) return -1;
    if(ka>kb) return 1;
    return 0;
}

static void printMsg(DecodedMsg *dm) {
    putchar('{');
    int first=1;
    /* collect fields to print, sorted by number */
    FieldSort fs[MAX_FIELDS];
    int nfs=0;
    for(int i=0;i<dm->def->nfields;i++){
        fs[nfs].idx=i;
        fs[nfs].number=dm->def->fields[i].number;
        nfs++;
    }
    qsort(fs,nfs,sizeof(FieldSort),cmpFS);

    for(int si=0;si<nfs;si++){
        int i=fs[si].idx;
        FieldDef *fd=&dm->def->fields[i];
        FieldData *fdata=&dm->flds[i];
        int shouldPrint=0;

        if(fd->isMap){
            shouldPrint=(fdata->nentries>0);
        } else if(fd->label==1){
            shouldPrint=(fdata->nvals>0);
        } else if(fd->label==3){
            shouldPrint=(dm->oneofSet[fd->oneofIdx]==i && fdata->present);
        } else if(fd->label==2){
            shouldPrint=fdata->present;
        } else {
            /* singular, implicit presence */
            if(fd->type==T_MESSAGE){
                shouldPrint=fdata->present;
            } else {
                shouldPrint=fdata->present && !isDefaultVal(&fdata->vals[0],fd->type);
            }
        }

        if(!shouldPrint) continue;

        if(!first) putchar(',');
        first=0;

        char jname[NAMEMAX];
        camelCase(fd->name,jname);
        printf("\"%s\":",jname);

        if(fd->isMap){
            putchar('{');
            /* sort entries */
            MapSort ms[fdata->nentries];
            for(int e=0;e<fdata->nentries;e++){
                ms[e].idx=e; ms[e].key=&fdata->entries[e].key;
            }
            if(fd->mapKeyType==T_STRING)
                qsort(ms,fdata->nentries,sizeof(MapSort),cmpMapStr);
            else
                qsort(ms,fdata->nentries,sizeof(MapSort),cmpMapInt);
            for(int e=0;e<fdata->nentries;e++){
                if(e) putchar(',');
                Val *k=&fdata->entries[ms[e].idx].key;
                Val *v=&fdata->entries[ms[e].idx].val;
                if(fd->mapKeyType==T_STRING){
                    printJsonStr(k->bytes,k->bytesLen);
                } else {
                    printf("\"%lld\"",(long long)k->i64);
                }
                putchar(':');
                if(fd->mapValueType==T_MESSAGE){
                    printVal(v,T_MESSAGE,fd->mapValueMsgIdx,0);
                } else if(fd->mapValueType==T_ENUM){
                    printVal(v,T_ENUM,0,fd->mapValueEnumIdx);
                } else {
                    printVal(v,fd->mapValueType,0,0);
                }
            }
            putchar('}');
        } else if(fd->label==1){
            putchar('[');
            for(int e=0;e<fdata->nvals;e++){
                if(e) putchar(',');
                if(fd->type==T_MESSAGE)
                    printVal(&fdata->vals[e],T_MESSAGE,fd->msgIdx,0);
                else if(fd->type==T_ENUM)
                    printVal(&fdata->vals[e],T_ENUM,0,fd->enumIdx);
                else
                    printVal(&fdata->vals[e],fd->type,0,0);
            }
            putchar(']');
        } else {
            if(fd->type==T_MESSAGE)
                printVal(&fdata->vals[0],T_MESSAGE,fd->msgIdx,0);
            else if(fd->type==T_ENUM)
                printVal(&fdata->vals[0],T_ENUM,0,fd->enumIdx);
            else
                printVal(&fdata->vals[0],fd->type,0,0);
        }
    }
    putchar('}');
}

/* ===== Main ===== */
int main(int argc, char **argv) {
    if(argc<2){fprintf(stderr,"usage: %s <dir>\n",argv[0]);return 1;}
    char path[4096];

    /* Read schema */
    snprintf(path,sizeof(path),"%s/schema.proto",argv[1]);
    FILE *f=fopen(path,"rb");
    if(!f){perror(path);return 1;}
    fseek(f,0,SEEK_END);
    g_srcLen=(int)ftell(f);
    fseek(f,0,SEEK_SET);
    g_src=(char*)malloc(g_srcLen+1);
    fread(g_src,1,g_srcLen,f);
    g_src[g_srcLen]=0;
    fclose(f);
    g_pos=0;
    parseSchema();
    resolveTypes();

    /* Read messages.bin */
    snprintf(path,sizeof(path),"%s/messages.bin",argv[1]);
    f=fopen(path,"rb");
    if(!f){perror(path);return 1;}
    fseek(f,0,SEEK_END);
    int binLen=(int)ftell(f);
    fseek(f,0,SEEK_SET);
    uint8_t *bin=(uint8_t*)malloc(binLen+1);
    fread(bin,1,binLen,f);
    fclose(f);

    int bpos=0;
    while(bpos<binLen){
        uint64_t rlen=readVarint(bin,binLen,&bpos);
        int msgLen=(int)rlen;
        if(bpos+msgLen>binLen) msgLen=binLen-bpos;
        DecodedMsg dm;
        initMsg(&dm,&g_msgs[0]);
        if(msgLen>0) decodeInto(&dm,bin+bpos,msgLen);
        bpos+=msgLen;
        printMsg(&dm);
        putchar('\n');
    }

    return 0;
}

use std::collections::HashMap;
use std::env;
use std::fs;

#[derive(Clone, Copy, Debug, PartialEq)]
enum ScalarType {
    Int32, Int64, UInt32, UInt64, SInt32, SInt64,
    Bool, Str, Bytes, Fixed32, Fixed64, SFixed32, SFixed64,
}

#[derive(Clone, Debug)]
enum TypeRef { Scalar(ScalarType), Named(String) }

#[derive(Clone, Copy, Debug, PartialEq)]
enum Label { Singular, Optional, Repeated, Map }

#[derive(Clone, Debug)]
struct FieldDef {
    name: String,
    number: u32,
    type_ref: TypeRef,
    label: Label,
    oneof: Option<String>,
    map_key: Option<ScalarType>,
}

#[derive(Clone, Debug)]
struct MessageDef {
    fields: HashMap<u32, FieldDef>,
    oneofs: HashMap<String, Vec<u32>>,
}

#[derive(Clone, Debug)]
struct EnumDef { values: HashMap<i32, String> }

#[derive(Clone, Debug)]
struct Schema {
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
    root: String,
}

#[derive(Clone, Debug)]
struct DecodedMsg {
    fields: HashMap<u32, FieldData>,
    oneof_set: HashMap<String, Option<u32>>,
}

#[derive(Clone, Debug)]
enum FieldData {
    Singular { occurred: bool, value: Option<DecodedVal> },
    Repeated(Vec<DecodedVal>),
    Map(Vec<(MapKey, DecodedVal)>),
}

#[derive(Clone, Debug)]
enum DecodedVal {
    Varint(u64), Fixed32(u32), Fixed64(u64),
    Bytes(Vec<u8>), Msg(DecodedMsg),
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum MapKey { Str(String), Int(i32) }

struct PP { src: Vec<u8>, pos: usize }

impl PP {
    fn new(s: &str) -> Self { Self { src: s.as_bytes().to_vec(), pos: 0 } }
    fn skip_ws(&mut self) {
        loop {
            while self.pos < self.src.len() && (self.src[self.pos] as char).is_ascii_whitespace() { self.pos += 1; }
            if self.pos + 1 < self.src.len() && self.src[self.pos] == b'/' && self.src[self.pos+1] == b'/' {
                while self.pos < self.src.len() && self.src[self.pos] != b'\n' { self.pos += 1; }
            } else if self.pos + 1 < self.src.len() && self.src[self.pos] == b'/' && self.src[self.pos+1] == b'*' {
                self.pos += 2;
                while self.pos + 1 < self.src.len() {
                    if self.src[self.pos] == b'*' && self.src[self.pos+1] == b'/' { self.pos += 2; break; }
                    self.pos += 1;
                }
            } else { break; }
        }
    }
    fn peek(&mut self) -> Option<u8> { self.skip_ws(); if self.pos < self.src.len() { Some(self.src[self.pos]) } else { None } }
    fn word(&mut self) -> String {
        self.skip_ws(); let s = self.pos;
        while self.pos < self.src.len() { let c = self.src[self.pos]; if c.is_ascii_alphanumeric() || c == b'_' || c == b'.' { self.pos += 1; } else { break; } }
        String::from_utf8_lossy(&self.src[s..self.pos]).to_string()
    }
    fn int(&mut self) -> i64 {
        self.skip_ws(); let s = self.pos;
        if self.pos < self.src.len() && self.src[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.src.len() && self.src[self.pos].is_ascii_digit() { self.pos += 1; }
        std::str::from_utf8(&self.src[s..self.pos]).unwrap_or("0").parse().unwrap_or(0)
    }
    fn expect(&mut self, c: u8) { self.skip_ws(); if self.pos < self.src.len() && self.src[self.pos] == c { self.pos += 1; } }
    fn skip_str(&mut self) { self.pos += 1; while self.pos < self.src.len() && self.src[self.pos] != b'"' { self.pos += 1; } if self.pos < self.src.len() { self.pos += 1; } }
    fn skip_to_semi(&mut self) {
        loop { self.skip_ws(); if self.pos >= self.src.len() { break; }
            match self.src[self.pos] { b';' => { self.pos += 1; break; } b'"' => self.skip_str(), b'{' => self.skip_br(), b'[' => self.skip_brk(), _ => { self.pos += 1; } }
        }
    }
    fn skip_br(&mut self) { self.pos += 1; let mut d = 1; while d > 0 && self.pos < self.src.len() { match self.src[self.pos] { b'{' => d+=1, b'}' => d-=1, b'"' => { self.skip_str(); continue; } _ => {} } self.pos += 1; } }
    fn skip_brk(&mut self) { self.pos += 1; let mut d = 1; while d > 0 && self.pos < self.src.len() { match self.src[self.pos] { b'[' => d+=1, b']' => d-=1, b'"' => { self.skip_str(); continue; } _ => {} } self.pos += 1; } }
}

fn st(n: &str) -> Option<ScalarType> {
    match n {
        "int32"=>Some(ScalarType::Int32),"int64"=>Some(ScalarType::Int64),"uint32"=>Some(ScalarType::UInt32),
        "uint64"=>Some(ScalarType::UInt64),"sint32"=>Some(ScalarType::SInt32),"sint64"=>Some(ScalarType::SInt64),
        "bool"=>Some(ScalarType::Bool),"string"=>Some(ScalarType::Str),"bytes"=>Some(ScalarType::Bytes),
        "fixed32"=>Some(ScalarType::Fixed32),"fixed64"=>Some(ScalarType::Fixed64),
        "sfixed32"=>Some(ScalarType::SFixed32),"sfixed64"=>Some(ScalarType::SFixed64),_=>None,
    }
}

fn tr(n: &str) -> TypeRef { if let Some(s)=st(n){TypeRef::Scalar(s)}else{TypeRef::Named(n.to_string())} }

fn parse_schema(src: &str) -> Schema {
    let mut p = PP::new(src);
    let mut msgs: HashMap<String, MessageDef> = HashMap::new();
    let mut ens: HashMap<String, EnumDef> = HashMap::new();
    let mut root = String::new(); let mut first = true;
    loop { match p.peek() { None=>break, Some(b'}')=>break, _=>{} }
        let w = p.word();
        match w.as_str() {
            "syntax"|"package"|"option"|"import" => p.skip_to_semi(),
            "message" => { let (n,d)=parse_msg(&mut p,&mut msgs,&mut ens); if first{root=n.clone();first=false;} msgs.insert(n,d); }
            "enum" => { let (n,d)=parse_enum(&mut p); ens.insert(n,d); }
            _ => p.skip_to_semi(),
        }
    }
    Schema{messages:msgs,enums:ens,root}
}

fn parse_msg(p:&mut PP,msgs:&mut HashMap<String,MessageDef>,ens:&mut HashMap<String,EnumDef>)->(String,MessageDef){
    let name=p.word(); p.expect(b'{');
    let mut fields:HashMap<u32,FieldDef>=HashMap::new(); let mut oneofs:HashMap<String,Vec<u32>>=HashMap::new();
    loop{match p.peek(){None=>break,Some(b'}')=>{p.pos+=1;break;},_=>{}}
        let w=p.word();
        match w.as_str(){
            "message"=>{let(n,d)=parse_msg(p,msgs,ens);msgs.insert(n,d);}
            "enum"=>{let(n,d)=parse_enum(p);ens.insert(n,d);}
            "oneof"=>{let on=p.word();p.expect(b'{');let mut nums=Vec::new();
                loop{match p.peek(){None=>break,Some(b'}')=>{p.pos+=1;break;},_=>{}}
                    let fw=p.word(); if fw=="option"{p.skip_to_semi();continue;}
                    let fd=parse_fb(p,fw,Some(on.clone()));nums.push(fd.number);fields.insert(fd.number,fd);}
                oneofs.insert(on,nums);}
            "reserved"|"option"|"extensions"|"extend"=>p.skip_to_semi(),
            _=>{let fd=parse_field(p,w,None);fields.insert(fd.number,fd);}
        }
    }
    (name,MessageDef{fields,oneofs})
}

fn parse_field(p:&mut PP,first:String,oneof:Option<String>)->FieldDef{
    match first.as_str(){
        "repeated"=>{let tw=p.word();
            if tw=="map"{p.expect(b'<');let kw=p.word();p.expect(b',');let vw=p.word();p.expect(b'>');
                let kt=st(&kw).unwrap_or(ScalarType::Str);let vt=tr(&vw);let nm=p.word();p.expect(b'=');let num=p.int() as u32;
                if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');
                FieldDef{name:nm,number:num,type_ref:vt,label:Label::Repeated,oneof,map_key:Some(kt)}
            }else{let vt=tr(&tw);let nm=p.word();p.expect(b'=');let num=p.int() as u32;
                if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');
                FieldDef{name:nm,number:num,type_ref:vt,label:Label::Repeated,oneof,map_key:None}}
        }
        "optional"=>{let tw=p.word();let vt=tr(&tw);let nm=p.word();p.expect(b'=');let num=p.int() as u32;
            if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');
            FieldDef{name:nm,number:num,type_ref:vt,label:Label::Optional,oneof,map_key:None}}
        "map"=>{p.expect(b'<');let kw=p.word();p.expect(b',');let vw=p.word();p.expect(b'>');
            let kt=st(&kw).unwrap_or(ScalarType::Str);let vt=tr(&vw);let nm=p.word();p.expect(b'=');let num=p.int() as u32;
            if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');
            FieldDef{name:nm,number:num,type_ref:vt,label:Label::Map,oneof,map_key:Some(kt)}}
        _=>parse_fb(p,first,oneof),
    }
}

fn parse_fb(p:&mut PP,tw:String,oneof:Option<String>)->FieldDef{
    let vt=tr(&tw);let nm=p.word();p.expect(b'=');let num=p.int() as u32;
    if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');
    FieldDef{name:nm,number:num,type_ref:vt,label:Label::Singular,oneof,map_key:None}
}

fn parse_enum(p:&mut PP)->(String,EnumDef){
    let name=p.word();p.expect(b'{');let mut vals=HashMap::new();
    loop{match p.peek(){None=>break,Some(b'}')=>{p.pos+=1;break;},_=>{}}
        let w=p.word();match w.as_str(){
            "reserved"|"option"=>p.skip_to_semi(),
            _=>{p.expect(b'=');let num=p.int() as i32;if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');vals.insert(num,w);}
        }
    }
    (name,EnumDef{values:vals})
}

fn rvar(data:&[u8],pos:&mut usize)->u64{
    let mut r=0u64;let mut s=0;
    while *pos<data.len(){let b=data[*pos];*pos+=1;r|=((b&0x7F) as u64)<<s;if b&0x80==0{break;}s+=7;if s>=70{break;}}
    r
}
fn rf32(data:&[u8],pos:&mut usize)->u32{let v=u32::from_le_bytes([data[*pos],data[*pos+1],data[*pos+2],data[*pos+3]]);*pos+=4;v}
fn rf64(data:&[u8],pos:&mut usize)->u64{let v=u64::from_le_bytes([data[*pos],data[*pos+1],data[*pos+2],data[*pos+3],data[*pos+4],data[*pos+5],data[*pos+6],data[*pos+7]]);*pos+=8;v}
fn rld(data:&[u8],pos:&mut usize)->&[u8]{let l=rvar(data,pos) as usize;let e=std::cmp::min(*pos+l,data.len());let r=&data[*pos..e];*pos=e;r}

fn skip_f(data:&[u8],pos:&mut usize,wt:u8,fn_:u32){
    match wt{
        0=>{rvar(data,pos);}
        1=>{*pos=std::cmp::min(*pos+8,data.len());}
        2=>{let l=rvar(data,pos) as usize;*pos=std::cmp::min(*pos+l,data.len());}
        5=>{*pos=std::cmp::min(*pos+4,data.len());}
        3=>{loop{if *pos>=data.len(){break;}let k=rvar(data,pos);let wt2=(k&7) as u8;let fn2=(k>>3) as u32;if wt2==4&&fn2==fn_{break;}skip_f(data,pos,wt2,fn2);}}
        _=>{}
    }
}

fn init_oo(mn:&str,sc:&Schema)->HashMap<String,Option<u32>>{
    let mut m=HashMap::new();if let Some(md)=sc.messages.get(mn){for k in md.oneofs.keys(){m.insert(k.clone(),None);}}m
}

fn decode_into(msg:&mut DecodedMsg,data:&[u8],mn:&str,sc:&Schema){
    let md=match sc.messages.get(mn){Some(m)=>m,None=>return};
    let mut pos=0;
    while pos<data.len(){
        let key=rvar(data,&mut pos);let fn_=(key>>3) as u32;let wt=(key&7) as u8;
        if let Some(fd)=md.fields.get(&fn_){apply_field(msg,md,fd,wt,data,&mut pos,sc);}
        else{skip_f(data,&mut pos,wt,fn_);}
    }
}

fn decode_msg(data:&[u8],mn:&str,sc:&Schema)->DecodedMsg{
    let mut m=DecodedMsg{fields:HashMap::new(),oneof_set:init_oo(mn,sc)};
    decode_into(&mut m,data,mn,sc);m
}

fn apply_field(msg:&mut DecodedMsg,md:&MessageDef,fd:&FieldDef,wt:u8,data:&[u8],pos:&mut usize,sc:&Schema){
    if let Some(ref on)=fd.oneof{
        let cur=*msg.oneof_set.get(on).unwrap_or(&None);
        if cur!=Some(fd.number){
            if let Some(nums)=md.oneofs.get(on){for &n in nums{if n!=fd.number{msg.fields.remove(&n);}}}
            msg.oneof_set.insert(on.clone(),Some(fd.number));
        }
    }
    match fd.label{
        Label::Singular|Label::Optional=>apply_sing(msg,fd,wt,data,pos,sc),
        Label::Repeated=>apply_rep(msg,fd,wt,data,pos,sc),
        Label::Map=>apply_map(msg,fd,wt,data,pos,sc),
    }
}

fn is_mt(tr:&TypeRef,sc:&Schema)->bool{matches!(tr,TypeRef::Named(n) if sc.messages.contains_key(n))}
fn is_pk(tr:&TypeRef,sc:&Schema)->bool{match tr{TypeRef::Scalar(st)=>!matches!(st,ScalarType::Str|ScalarType::Bytes),TypeRef::Named(n)=>sc.enums.contains_key(n)}}
fn nat_wt(tr:&TypeRef,sc:&Schema)->u8{match tr{
    TypeRef::Scalar(st)=>match st{ScalarType::Fixed32|ScalarType::SFixed32=>5,ScalarType::Fixed64|ScalarType::SFixed64=>1,ScalarType::Str|ScalarType::Bytes=>2,_=>0},
    TypeRef::Named(n)=>if sc.messages.contains_key(n){2}else{0}}}
fn get_nm(tr:&TypeRef)->&str{match tr{TypeRef::Named(n)=>n,_=>""}}

fn read_val(fd:&FieldDef,wt:u8,data:&[u8],pos:&mut usize,sc:&Schema)->DecodedVal{
    match wt{
        0=>DecodedVal::Varint(rvar(data,pos)),
        1=>DecodedVal::Fixed64(rf64(data,pos)),
        2=>{if is_mt(&fd.type_ref,sc){let b=rld(data,pos);DecodedVal::Msg(decode_msg(b,get_nm(&fd.type_ref),sc))}else{DecodedVal::Bytes(rld(data,pos).to_vec())}}
        5=>DecodedVal::Fixed32(rf32(data,pos)),
        _=>DecodedVal::Varint(0),
    }
}

fn apply_sing(msg:&mut DecodedMsg,fd:&FieldDef,wt:u8,data:&[u8],pos:&mut usize,sc:&Schema){
    if is_mt(&fd.type_ref,sc){
        let bytes=rld(data,pos);let mn=get_nm(&fd.type_ref);
        let entry=msg.fields.entry(fd.number).or_insert_with(||FieldData::Singular{occurred:false,value:None});
        if let FieldData::Singular{occurred,value}=entry{
            *occurred=true;
            if value.is_none(){*value=Some(DecodedVal::Msg(DecodedMsg{fields:HashMap::new(),oneof_set:init_oo(mn,sc)}));}
            if let Some(DecodedVal::Msg(inner))=value{decode_into(inner,bytes,mn,sc);}
        }
    }else{
        let val=read_val(fd,wt,data,pos,sc);
        msg.fields.insert(fd.number,FieldData::Singular{occurred:true,value:Some(val)});
    }
}

fn apply_rep(msg:&mut DecodedMsg,fd:&FieldDef,wt:u8,data:&[u8],pos:&mut usize,sc:&Schema){
    let pk=is_pk(&fd.type_ref,sc);
    let entry=msg.fields.entry(fd.number).or_insert_with(||FieldData::Repeated(Vec::new()));
    if let FieldData::Repeated(vec)=entry{
        if wt==2&&pk{
            let payload=rld(data,pos);let mut pp=0;let nwt=nat_wt(&fd.type_ref,sc);
            while pp<payload.len(){let v=read_val(fd,nwt,payload,&mut pp,sc);vec.push(v);}
        }else{
            let v=read_val(fd,wt,data,pos,sc);vec.push(v);
        }
    }
}

fn apply_map(msg:&mut DecodedMsg,fd:&FieldDef,_wt:u8,data:&[u8],pos:&mut usize,sc:&Schema){
    let eb=rld(data,pos);let mut key:Option<MapKey>=None;let mut val:Option<DecodedVal>=None;
    let mut ep=0;
    while ep<eb.len(){
        let ek=rvar(eb,&mut ep);let efn=(ek>>3) as u32;let ewt=(ek&7) as u8;
        if efn==1{key=Some(read_mk(fd.map_key.unwrap(),ewt,eb,&mut ep));}
        else if efn==2{val=Some(read_val(fd,ewt,eb,&mut ep,sc));}
        else{skip_f(eb,&mut ep,ewt,efn);}
    }
    let mk=key.unwrap_or_else(||def_mk(fd.map_key.unwrap()));
    let mv=val.unwrap_or_else(||def_mv(fd,sc));
    let entry=msg.fields.entry(fd.number).or_insert_with(||FieldData::Map(Vec::new()));
    if let FieldData::Map(entries)=entry{
        let mut found=false;for e in entries.iter_mut(){if e.0==mk{e.1=mv.clone();found=true;break;}}
        if !found{entries.push((mk,mv));}
    }
}

fn read_mk(kt:ScalarType,wt:u8,data:&[u8],pos:&mut usize)->MapKey{
    match kt{
        ScalarType::Str=>{let b=rld(data,pos);MapKey::Str(String::from_utf8_lossy(b).to_string())}
        _=>{let v=rvar(data,pos);MapKey::Int((v as u32) as i32)}
    }
}
fn def_mk(kt:ScalarType)->MapKey{match kt{ScalarType::Str=>MapKey::Str(String::new()),_=>MapKey::Int(0)}}
fn def_mv(fd:&FieldDef,sc:&Schema)->DecodedVal{
    match &fd.type_ref{
        TypeRef::Scalar(st)=>match st{
            ScalarType::Str|ScalarType::Bytes=>DecodedVal::Bytes(Vec::new()),
            ScalarType::Fixed32|ScalarType::SFixed32=>DecodedVal::Fixed32(0),
            ScalarType::Fixed64|ScalarType::SFixed64=>DecodedVal::Fixed64(0),
            _=>DecodedVal::Varint(0),
        },
        TypeRef::Named(n)=>{if sc.messages.contains_key(n){DecodedVal::Msg(DecodedMsg{fields:HashMap::new(),oneof_set:init_oo(n,sc)})}else{DecodedVal::Varint(0)}}
    }
}

fn should_print(msg:&DecodedMsg,fd:&FieldDef,sc:&Schema)->bool{
    if let Some(ref on)=fd.oneof{
        return match msg.oneof_set.get(on){Some(Some(&n))=>n==fd.number,_=>false};
    }
    match fd.label{
        Label::Repeated=>matches!(msg.fields.get(&fd.number),Some(FieldData::Repeated(v)) if !v.is_empty()),
        Label::Map=>matches!(msg.fields.get(&fd.number),Some(FieldData::Map(v)) if !v.is_empty()),
        Label::Optional=>matches!(msg.fields.get(&fd.number),Some(FieldData::Singular{occurred:true,..})),
        Label::Singular=>{
            match msg.fields.get(&fd.number){
                Some(FieldData::Singular{occurred,value})=>{
                    if !*occurred{return false;}
                    if is_mt(&fd.type_ref,sc){return true;}
                    match value{Some(v)=>!is_def(v),None=>false}
                }
                _=>false,
            }
        }
    }
}

fn is_def(v:&DecodedVal)->bool{
    match v{DecodedVal::Varint(x)=>*x==0,DecodedVal::Fixed32(x)=>*x==0,DecodedVal::Fixed64(x)=>*x==0,DecodedVal::Bytes(b)=>b.is_empty(),DecodedVal::Msg(_)=>false}
}

fn msg_json(msg:&DecodedMsg,mn:&str,sc:&Schema)->String{
    let md=match sc.messages.get(mn){Some(m)=>m,None=>return"{}".to_string()};
    let mut nums:Vec<u32>=md.fields.keys().cloned().collect();nums.sort();
    let mut parts:Vec<String>=Vec::new();
    for &n in &nums{
        let fd=&md.fields[&n];
        if !should_print(msg,fd,sc){continue;}
        let key=camel(&fd.name);
        let val=field_json(msg,fd,sc);
        parts.push(format!("\"{}\":{}",esc(&key),val));
    }
    format!("{{{}}}",parts.join(","))
}

fn field_json(msg:&DecodedMsg,fd:&FieldDef,sc:&Schema)->String{
    match fd.label{
        Label::Singular|Label::Optional=>{
            match msg.fields.get(&fd.number){Some(FieldData::Singular{value:Some(v),..})=>val_json(v,&fd.type_ref,sc),_=>"null".to_string()}
        }
        Label::Repeated=>{
            match msg.fields.get(&fd.number){
                Some(FieldData::Repeated(vec))=>{let items:Vec<String>=vec.iter().map(|v|val_json(v,&fd.type_ref,sc)).collect();format!("[{}]",items.join(","))}
                _=>"[]".to_string(),
            }
        }
        Label::Map=>{
            match msg.fields.get(&fd.number){
                Some(FieldData::Map(entries))=>{
                    let sorted=dedup_sort(entries,fd.map_key.unwrap());
                    let items:Vec<String>=sorted.iter().map(|(k,v)|{let ks=mk_str(k);format!("{}:{}",esc(&ks),val_json(v,&fd.type_ref,sc))}).collect();
                    format!("{{{}}}",items.join(","))
                }
                _=>"{}".to_string(),
            }
        }
    }
}

fn val_json(v:&DecodedVal,tr:&TypeRef,sc:&Schema)->String{
    match(v,tr){
        (DecodedVal::Varint(x),TypeRef::Scalar(st))=>match st{
            ScalarType::Int32=>format!("{}",(*x as u32) as i32),
            ScalarType::Int64=>format!("\"{}\"",*x as i64),
            ScalarType::UInt32=>format!("{}",*x as u32),
            ScalarType::UInt64=>format!("\"{}\"",*x),
            ScalarType::SInt32=>{let n=*x as u32;let r=((n>>1) as i32)^((n&1) as i32).wrapping_neg();format!("{}",r)}
            ScalarType::SInt64=>{let n=*x;let r=((n>>1) as i64)^((n&1) as i64).wrapping_neg();format!("\"{}\"",r)}
            ScalarType::Bool=>if *x!=0{"true".to_string()}else{"false".to_string()},
            ScalarType::Str=>format!("\"\""),
            ScalarType::Bytes=>format!("\"\""),
            ScalarType::Fixed32=>format!("{}",*x as u32),
            ScalarType::SFixed32=>format!("{}",(*x as u32) as i32),
            ScalarType::Fixed64=>format!("\"{}\"",*x),
            ScalarType::SFixed64=>format!("\"{}\"",*x as i64),
        },
        (DecodedVal::Varint(x),TypeRef::Named(n))=>{
            if let Some(ed)=sc.enums.get(n){let num=(*x as u32) as i32;match ed.values.get(&num){Some(name)=>format!("\"{}\"",name),None=>format!("{}",num)}}
            else{format!("{}",*x)}
        },
        (DecodedVal::Fixed32(x),TypeRef::Scalar(st))=>match st{
            ScalarType::SFixed32=>format!("{}",*x as i32),_=>format!("{}",x),
        },
        (DecodedVal::Fixed64(x),TypeRef::Scalar(st))=>match st{
            ScalarType::SFixed64=>format!("\"{}\"",*x as i64),_=>format!("\"{}\"",x),
        },
        (DecodedVal::Bytes(b),TypeRef::Scalar(ScalarType::Str))=>format!("\"{}\"",esc(&String::from_utf8_lossy(b))),
        (DecodedVal::Bytes(b),TypeRef::Scalar(ScalarType::Bytes))=>format!("\"{}\"",b64(b)),
        (DecodedVal::Msg(m),TypeRef::Named(n))=>msg_json(m,n,sc),
        _=>"null".to_string(),
    }
}

fn dedup_sort(entries:&[(MapKey,DecodedVal)],kt:ScalarType)->Vec<(MapKey,DecodedVal)>{
    let mut seen:HashMap<String,usize>=HashMap::new();
    for(i,(k,_))in entries.iter().enumerate(){let ks=match k{MapKey::Str(s)=>format!("s{}",s),MapKey::Int(n)=>format!("i{}",n)};seen.insert(ks,i);}
    let mut result:Vec<(MapKey,DecodedVal)>=seen.values().map(|&i|entries[i].clone()).collect();
    match kt{
        ScalarType::Str=>result.sort_by(|(k1,_),(k2,_)|match(k1,k2){(MapKey::Str(s1),MapKey::Str(s2))=>s1.as_bytes().cmp(s2.as_bytes()),_=>std::cmp::Ordering::Equal}),
        _=>result.sort_by_key(|(k,_)|match k{MapKey::Int(n)=>*n,_=>0}),
    }
    result
}

fn mk_str(k:&MapKey)->String{match k{MapKey::Str(s)=>s.clone(),MapKey::Int(n)=>format!("{}",n)}}

fn camel(name:&str)->String{
    let mut r=String::new();let mut up=false;
    for ch in name.chars(){if ch=='_'{up=true;}else{if up&&ch.is_ascii_lowercase(){r.push(ch.to_ascii_uppercase());}else{r.push(ch);}up=false;}}
    r
}

fn esc(s:&str)->String{
    let mut r=String::new();
    for ch in s.chars(){match ch{
        '"'=>r.push_str("\\\""),'\\'=>r.push_str("\\\\"),
        '\u{0008}'=>r.push_str("\\b"),'\t'=>r.push_str("\\t"),'\n'=>r.push_str("\\n"),
        '\u{000C}'=>r.push_str("\\f"),'\r'=>r.push_str("\\r"),
        c if(c as u32)<0x20=>r.push_str(&format!("\\u{:04x}",c as u32)),
        c=>r.push(c),
    }}
    r
}

fn b64(data:&[u8])->String{
    const C:&[u8]=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut r=String::new();let mut i=0;
    while i+2<data.len(){let n=((data[i] as u32)<<16)|((data[i+1] as u32)<<8)|(data[i+2] as u32);
        r.push(C[((n>>18)&63) as usize] as char);r.push(C[((n>>12)&63) as usize] as char);r.push(C[((n>>6)&63) as usize] as char);r.push(C[(n&63) as usize] as char);i+=3;}
    if i+1==data.len(){let n=(data[i] as u32)<<16;r.push(C[((n>>18)&63) as usize] as char);r.push(C[((n>>12)&63) as usize] as char);r.push('=');r.push('=');}
    else if i+2==data.len(){let n=((data[i] as u32)<<16)|((data[i+1] as u32)<<8);r.push(C[((n>>18)&63) as usize] as char);r.push(C[((n>>12)&63) as usize] as char);r.push(C[((n>>6)&63) as usize] as char);r.push('=');}
    r
}

fn main(){
    let args:Vec<String>=env::args().collect();
    let dir=&args[1];
    let schema_src=fs::read_to_string(format!("{}/schema.proto",dir)).unwrap();
    let bin=fs::read(format!("{}/messages.bin",dir)).unwrap();
    let sc=parse_schema(&schema_src);
    let mut pos=0;
    while pos<bin.len(){
        let len=rvar(&bin,&mut pos) as usize;
        if pos+len>bin.len(){break;}
        let mb=&bin[pos..pos+len];pos+=len;
        let dec=decode_msg(mb,&sc.root,&sc);
        println!("{}",msg_json(&dec,&sc.root,&sc));
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;

#[derive(Clone, Copy, Debug, PartialEq)]
enum ScalarType {
    Int32, Int64, UInt32, UInt64, SInt32, SInt64,
    Bool, Str, Bytes, Fixed32, Fixed64, SFixed32, SFixed64,
}

#[derive(Clone, Debug)]
enum TypeRef { Scalar(ScalarType), Named(String) }

#[derive(Clone, Copy, Debug, PartialEq)]
enum Label { Singular, Optional, Repeated, Map }

#[derive(Clone, Debug)]
struct FieldDef {
    name: String,
    number: u32,
    type_ref: TypeRef,
    label: Label,
    oneof: Option<String>,
    map_key: Option<ScalarType>,
}

#[derive(Clone, Debug)]
struct MessageDef {
    fields: HashMap<u32, FieldDef>,
    oneofs: HashMap<String, Vec<u32>>,
}

#[derive(Clone, Debug)]
struct EnumDef { values: HashMap<i32, String> }

#[derive(Clone, Debug)]
struct Schema {
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
    root: String,
}

#[derive(Clone, Debug)]
struct DecodedMsg {
    fields: HashMap<u32, FieldData>,
    oneof_set: HashMap<String, Option<u32>>,
}

#[derive(Clone, Debug)]
enum FieldData {
    Singular { occurred: bool, value: Option<DecodedVal> },
    Repeated(Vec<DecodedVal>),
    Map(Vec<(MapKey, DecodedVal)>),
}

#[derive(Clone, Debug)]
enum DecodedVal {
    Varint(u64), Fixed32(u32), Fixed64(u64),
    Bytes(Vec<u8>), Msg(DecodedMsg),
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum MapKey { Str(String), Int(i32) }

struct PP { src: Vec<u8>, pos: usize }

impl PP {
    fn new(s: &str) -> Self { Self { src: s.as_bytes().to_vec(), pos: 0 } }
    fn skip_ws(&mut self) {
        loop {
            while self.pos < self.src.len() && (self.src[self.pos] as char).is_ascii_whitespace() { self.pos += 1; }
            if self.pos + 1 < self.src.len() && self.src[self.pos] == b'/' && self.src[self.pos+1] == b'/' {
                while self.pos < self.src.len() && self.src[self.pos] != b'\n' { self.pos += 1; }
            } else if self.pos + 1 < self.src.len() && self.src[self.pos] == b'/' && self.src[self.pos+1] == b'*' {
                self.pos += 2;
                while self.pos + 1 < self.src.len() {
                    if self.src[self.pos] == b'*' && self.src[self.pos+1] == b'/' { self.pos += 2; break; }
                    self.pos += 1;
                }
            } else { break; }
        }
    }
    fn peek(&mut self) -> Option<u8> { self.skip_ws(); if self.pos < self.src.len() { Some(self.src[self.pos]) } else { None } }
    fn word(&mut self) -> String {
        self.skip_ws(); let s = self.pos;
        while self.pos < self.src.len() { let c = self.src[self.pos]; if c.is_ascii_alphanumeric() || c == b'_' || c == b'.' { self.pos += 1; } else { break; } }
        String::from_utf8_lossy(&self.src[s..self.pos]).to_string()
    }
    fn int(&mut self) -> i64 {
        self.skip_ws(); let s = self.pos;
        if self.pos < self.src.len() && self.src[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.src.len() && self.src[self.pos].is_ascii_digit() { self.pos += 1; }
        std::str::from_utf8(&self.src[s..self.pos]).unwrap_or("0").parse().unwrap_or(0)
    }
    fn expect(&mut self, c: u8) { self.skip_ws(); if self.pos < self.src.len() && self.src[self.pos] == c { self.pos += 1; } }
    fn skip_str(&mut self) { self.pos += 1; while self.pos < self.src.len() && self.src[self.pos] != b'"' { self.pos += 1; } if self.pos < self.src.len() { self.pos += 1; } }
    fn skip_to_semi(&mut self) {
        loop { self.skip_ws(); if self.pos >= self.src.len() { break; }
            match self.src[self.pos] { b';' => { self.pos += 1; break; } b'"' => self.skip_str(), b'{' => self.skip_br(), b'[' => self.skip_brk(), _ => { self.pos += 1; } }
        }
    }
    fn skip_br(&mut self) { self.pos += 1; let mut d = 1; while d > 0 && self.pos < self.src.len() { match self.src[self.pos] { b'{' => d+=1, b'}' => d-=1, b'"' => { self.skip_str(); continue; } _ => {} } self.pos += 1; } }
    fn skip_brk(&mut self) { self.pos += 1; let mut d = 1; while d > 0 && self.pos < self.src.len() { match self.src[self.pos] { b'[' => d+=1, b']' => d-=1, b'"' => { self.skip_str(); continue; } _ => {} } self.pos += 1; } }
}

fn st(n: &str) -> Option<ScalarType> {
    match n {
        "int32"=>Some(ScalarType::Int32),"int64"=>Some(ScalarType::Int64),"uint32"=>Some(ScalarType::UInt32),
        "uint64"=>Some(ScalarType::UInt64),"sint32"=>Some(ScalarType::SInt32),"sint64"=>Some(ScalarType::SInt64),
        "bool"=>Some(ScalarType::Bool),"string"=>Some(ScalarType::Str),"bytes"=>Some(ScalarType::Bytes),
        "fixed32"=>Some(ScalarType::Fixed32),"fixed64"=>Some(ScalarType::Fixed64),
        "sfixed32"=>Some(ScalarType::SFixed32),"sfixed64"=>Some(ScalarType::SFixed64),_=>None,
    }
}

fn tr(n: &str) -> TypeRef { if let Some(s)=st(n){TypeRef::Scalar(s)}else{TypeRef::Named(n.to_string())} }

fn parse_schema(src: &str) -> Schema {
    let mut p = PP::new(src);
    let mut msgs: HashMap<String, MessageDef> = HashMap::new();
    let mut ens: HashMap<String, EnumDef> = HashMap::new();
    let mut root = String::new(); let mut first = true;
    loop { match p.peek() { None=>break, Some(b'}')=>break, _=>{} }
        let w = p.word();
        match w.as_str() {
            "syntax"|"package"|"option"|"import" => p.skip_to_semi(),
            "message" => { let (n,d)=parse_msg(&mut p,&mut msgs,&mut ens); if first{root=n.clone();first=false;} msgs.insert(n,d); }
            "enum" => { let (n,d)=parse_enum(&mut p); ens.insert(n,d); }
            _ => p.skip_to_semi(),
        }
    }
    Schema{messages:msgs,enums:ens,root}
}

fn parse_msg(p:&mut PP,msgs:&mut HashMap<String,MessageDef>,ens:&mut HashMap<String,EnumDef>)->(String,MessageDef){
    let name=p.word(); p.expect(b'{');
    let mut fields:HashMap<u32,FieldDef>=HashMap::new(); let mut oneofs:HashMap<String,Vec<u32>>=HashMap::new();
    loop{match p.peek(){None=>break,Some(b'}')=>{p.pos+=1;break;},_=>{}}
        let w=p.word();
        match w.as_str(){
            "message"=>{let(n,d)=parse_msg(p,msgs,ens);msgs.insert(n,d);}
            "enum"=>{let(n,d)=parse_enum(p);ens.insert(n,d);}
            "oneof"=>{let on=p.word();p.expect(b'{');let mut nums=Vec::new();
                loop{match p.peek(){None=>break,Some(b'}')=>{p.pos+=1;break;},_=>{}}
                    let fw=p.word(); if fw=="option"{p.skip_to_semi();continue;}
                    let fd=parse_fb(p,fw,Some(on.clone()));nums.push(fd.number);fields.insert(fd.number,fd);}
                oneofs.insert(on,nums);}
            "reserved"|"option"|"extensions"|"extend"=>p.skip_to_semi(),
            _=>{let fd=parse_field(p,w,None);fields.insert(fd.number,fd);}
        }
    }
    (name,MessageDef{fields,oneofs})
}

fn parse_field(p:&mut PP,first:String,oneof:Option<String>)->FieldDef{
    match first.as_str(){
        "repeated"=>{let tw=p.word();
            if tw=="map"{p.expect(b'<');let kw=p.word();p.expect(b',');let vw=p.word();p.expect(b'>');
                let kt=st(&kw).unwrap_or(ScalarType::Str);let vt=tr(&vw);let nm=p.word();p.expect(b'=');let num=p.int() as u32;
                if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');
                FieldDef{name:nm,number:num,type_ref:vt,label:Label::Repeated,oneof,map_key:Some(kt)}
            }else{let vt=tr(&tw);let nm=p.word();p.expect(b'=');let num=p.int() as u32;
                if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');
                FieldDef{name:nm,number:num,type_ref:vt,label:Label::Repeated,oneof,map_key:None}}
        }
        "optional"=>{let tw=p.word();let vt=tr(&tw);let nm=p.word();p.expect(b'=');let num=p.int() as u32;
            if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');
            FieldDef{name:nm,number:num,type_ref:vt,label:Label::Optional,oneof,map_key:None}}
        "map"=>{p.expect(b'<');let kw=p.word();p.expect(b',');let vw=p.word();p.expect(b'>');
            let kt=st(&kw).unwrap_or(ScalarType::Str);let vt=tr(&vw);let nm=p.word();p.expect(b'=');let num=p.int() as u32;
            if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');
            FieldDef{name:nm,number:num,type_ref:vt,label:Label::Map,oneof,map_key:Some(kt)}}
        _=>parse_fb(p,first,oneof),
    }
}

fn parse_fb(p:&mut PP,tw:String,oneof:Option<String>)->FieldDef{
    let vt=tr(&tw);let nm=p.word();p.expect(b'=');let num=p.int() as u32;
    if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');
    FieldDef{name:nm,number:num,type_ref:vt,label:Label::Singular,oneof,map_key:None}
}

fn parse_enum(p:&mut PP)->(String,EnumDef){
    let name=p.word();p.expect(b'{');let mut vals=HashMap::new();
    loop{match p.peek(){None=>break,Some(b'}')=>{p.pos+=1;break;},_=>{}}
        let w=p.word();match w.as_str(){
            "reserved"|"option"=>p.skip_to_semi(),
            _=>{p.expect(b'=');let num=p.int() as i32;if p.peek()==Some(b'['){p.skip_brk();}p.expect(b';');vals.insert(num,w);}
        }
    }
    (name,EnumDef{values:vals})
}

fn rvar(data:&[u8],pos:&mut usize)->u64{
    let mut r=0u64;let mut s=0;
    while *pos<data.len(){let b=data[*pos];*pos+=1;r|=((b&0x7F) as u64)<<s;if b&0x80==0{break;}s+=7;if s>=70{break;}}
    r
}
fn rf32(data:&[u8],pos:&mut usize)->u32{let v=u32::from_le_bytes([data[*pos],data[*pos+1],data[*pos+2],data[*pos+3]]);*pos+=4;v}
fn rf64(data:&[u8],pos:&mut usize)->u64{let v=u64::from_le_bytes([data[*pos],data[*pos+1],data[*pos+2],data[*pos+3],data[*pos+4],data[*pos+5],data[*pos+6],data[*pos+7]]);*pos+=8;v}
fn rld<'a>(data:&'a [u8],pos:&mut usize)->&'a [u8]{let l=rvar(data,pos) as usize;let e=std::cmp::min(*pos+l,data.len());let r=&data[*pos..e];*pos=e;r}

fn skip_f(data:&[u8],pos:&mut usize,wt:u8,fn_:u32){
    match wt{
        0=>{rvar(data,pos);}
        1=>{*pos=std::cmp::min(*pos+8,data.len());}
        2=>{let l=rvar(data,pos) as usize;*pos=std::cmp::min(*pos+l,data.len());}
        5=>{*pos=std::cmp::min(*pos+4,data.len());}
        3=>{loop{if *pos>=data.len(){break;}let k=rvar(data,pos);let wt2=(k&7) as u8;let fn2=(k>>3) as u32;if wt2==4&&fn2==fn_{break;}skip_f(data,pos,wt2,fn2);}}
        _=>{}
    }
}

fn init_oo(mn:&str,sc:&Schema)->HashMap<String,Option<u32>>{
    let mut m=HashMap::new();if let Some(md)=sc.messages.get(mn){for k in md.oneofs.keys(){m.insert(k.clone(),None);}}m
}

fn decode_into(msg:&mut DecodedMsg,data:&[u8],mn:&str,sc:&Schema){
    let md=match sc.messages.get(mn){Some(m)=>m,None=>return};
    let mut pos=0;
    while pos<data.len(){
        let key=rvar(data,&mut pos);let fn_=(key>>3) as u32;let wt=(key&7) as u8;
        if let Some(fd)=md.fields.get(&fn_){apply_field(msg,md,fd,wt,data,&mut pos,sc);}
        else{skip_f(data,&mut pos,wt,fn_);}
    }
}

fn decode_msg(data:&[u8],mn:&str,sc:&Schema)->DecodedMsg{
    let mut m=DecodedMsg{fields:HashMap::new(),oneof_set:init_oo(mn,sc)};
    decode_into(&mut m,data,mn,sc);m
}

fn apply_field(msg:&mut DecodedMsg,md:&MessageDef,fd:&FieldDef,wt:u8,data:&[u8],pos:&mut usize,sc:&Schema){
    if let Some(ref on)=fd.oneof{
        let cur=*msg.oneof_set.get(on).unwrap_or(&None);
        if cur!=Some(fd.number){
            if let Some(nums)=md.oneofs.get(on){for &n in nums{if n!=fd.number{msg.fields.remove(&n);}}}
            msg.oneof_set.insert(on.clone(),Some(fd.number));
        }
    }
    match fd.label{
        Label::Singular|Label::Optional=>apply_sing(msg,fd,wt,data,pos,sc),
        Label::Repeated=>apply_rep(msg,fd,wt,data,pos,sc),
        Label::Map=>apply_map(msg,fd,wt,data,pos,sc),
    }
}

fn is_mt(tr:&TypeRef,sc:&Schema)->bool{matches!(tr,TypeRef::Named(n) if sc.messages.contains_key(n))}
fn is_pk(tr:&TypeRef,sc:&Schema)->bool{match tr{TypeRef::Scalar(st)=>!matches!(st,ScalarType::Str|ScalarType::Bytes),TypeRef::Named(n)=>sc.enums.contains_key(n)}}
fn nat_wt(tr:&TypeRef,sc:&Schema)->u8{match tr{
    TypeRef::Scalar(st)=>match st{ScalarType::Fixed32|ScalarType::SFixed32=>5,ScalarType::Fixed64|ScalarType::SFixed64=>1,ScalarType::Str|ScalarType::Bytes=>2,_=>0},
    TypeRef::Named(n)=>if sc.messages.contains_key(n){2}else{0}}}
fn get_nm(tr:&TypeRef)->&str{match tr{TypeRef::Named(n)=>n,_=>""}}

fn read_val(fd:&FieldDef,wt:u8,data:&[u8],pos:&mut usize,sc:&Schema)->DecodedVal{
    match wt{
        0=>DecodedVal::Varint(rvar(data,pos)),
        1=>DecodedVal::Fixed64(rf64(data,pos)),
        2=>{if is_mt(&fd.type_ref,sc){let b=rld(data,pos);DecodedVal::Msg(decode_msg(b,get_nm(&fd.type_ref),sc))}else{DecodedVal::Bytes(rld(data,pos).to_vec())}}
        5=>DecodedVal::Fixed32(rf32(data,pos)),
        _=>DecodedVal::Varint(0),
    }
}

fn apply_sing(msg:&mut DecodedMsg,fd:&FieldDef,wt:u8,data:&[u8],pos:&mut usize,sc:&Schema){
    if is_mt(&fd.type_ref,sc){
        let bytes=rld(data,pos);let mn=get_nm(&fd.type_ref);
        let entry=msg.fields.entry(fd.number).or_insert_with(||FieldData::Singular{occurred:false,value:None});
        if let FieldData::Singular{occurred,value}=entry{
            *occurred=true;
            if value.is_none(){*value=Some(DecodedVal::Msg(DecodedMsg{fields:HashMap::new(),oneof_set:init_oo(mn,sc)}));}
            if let Some(DecodedVal::Msg(inner))=value{decode_into(inner,bytes,mn,sc);}
        }
    }else{
        let val=read_val(fd,wt,data,pos,sc);
        msg.fields.insert(fd.number,FieldData::Singular{occurred:true,value:Some(val)});
    }
}

fn apply_rep(msg:&mut DecodedMsg,fd:&FieldDef,wt:u8,data:&[u8],pos:&mut usize,sc:&Schema){
    let pk=is_pk(&fd.type_ref,sc);
    let entry=msg.fields.entry(fd.number).or_insert_with(||FieldData::Repeated(Vec::new()));
    if let FieldData::Repeated(vec)=entry{
        if wt==2&&pk{
            let payload=rld(data,pos);let mut pp=0;let nwt=nat_wt(&fd.type_ref,sc);
            while pp<payload.len(){let v=read_val(fd,nwt,payload,&mut pp,sc);vec.push(v);}
        }else{
            let v=read_val(fd,wt,data,pos,sc);vec.push(v);
        }
    }
}

fn apply_map(msg:&mut DecodedMsg,fd:&FieldDef,_wt:u8,data:&[u8],pos:&mut usize,sc:&Schema){
    let eb=rld(data,pos);let mut key:Option<MapKey>=None;let mut val:Option<DecodedVal>=None;
    let mut ep=0;
    while ep<eb.len(){
        let ek=rvar(eb,&mut ep);let efn=(ek>>3) as u32;let ewt=(ek&7) as u8;
        if efn==1{key=Some(read_mk(fd.map_key.unwrap(),ewt,eb,&mut ep));}
        else if efn==2{val=Some(read_val(fd,ewt,eb,&mut ep,sc));}
        else{skip_f(eb,&mut ep,ewt,efn);}
    }
    let mk=key.unwrap_or_else(||def_mk(fd.map_key.unwrap()));
    let mv=val.unwrap_or_else(||def_mv(fd,sc));
    let entry=msg.fields.entry(fd.number).or_insert_with(||FieldData::Map(Vec::new()));
    if let FieldData::Map(entries)=entry{
        let mut found=false;for e in entries.iter_mut(){if e.0==mk{e.1=mv.clone();found=true;break;}}
        if !found{entries.push((mk,mv));}
    }
}

fn read_mk(kt:ScalarType,wt:u8,data:&[u8],pos:&mut usize)->MapKey{
    match kt{
        ScalarType::Str=>{let b=rld(data,pos);MapKey::Str(String::from_utf8_lossy(b).to_string())}
        _=>{let v=rvar(data,pos);MapKey::Int((v as u32) as i32)}
    }
}
fn def_mk(kt:ScalarType)->MapKey{match kt{ScalarType::Str=>MapKey::Str(String::new()),_=>MapKey::Int(0)}}
fn def_mv(fd:&FieldDef,sc:&Schema)->DecodedVal{
    match &fd.type_ref{
        TypeRef::Scalar(st)=>match st{
            ScalarType::Str|ScalarType::Bytes=>DecodedVal::Bytes(Vec::new()),
            ScalarType::Fixed32|ScalarType::SFixed32=>DecodedVal::Fixed32(0),
            ScalarType::Fixed64|ScalarType::SFixed64=>DecodedVal::Fixed64(0),
            _=>DecodedVal::Varint(0),
        },
        TypeRef::Named(n)=>{if sc.messages.contains_key(n){DecodedVal::Msg(DecodedMsg{fields:HashMap::new(),oneof_set:init_oo(n,sc)})}else{DecodedVal::Varint(0)}}
    }
}

fn should_print(msg:&DecodedMsg,fd:&FieldDef,sc:&Schema)->bool{
    if let Some(ref on)=fd.oneof{
        return match msg.oneof_set.get(on){Some(Some(n))=>*n==fd.number,_=>false};
    }
    match fd.label{
        Label::Repeated=>matches!(msg.fields.get(&fd.number),Some(FieldData::Repeated(v)) if !v.is_empty()),
        Label::Map=>matches!(msg.fields.get(&fd.number),Some(FieldData::Map(v)) if !v.is_empty()),
        Label::Optional=>matches!(msg.fields.get(&fd.number),Some(FieldData::Singular{occurred:true,..})),
        Label::Singular=>{
            match msg.fields.get(&fd.number){
                Some(FieldData::Singular{occurred,value})=>{
                    if !*occurred{return false;}
                    if is_mt(&fd.type_ref,sc){return true;}
                    match value{Some(v)=>!is_def(v),None=>false}
                }
                _=>false,
            }
        }
    }
}

fn is_def(v:&DecodedVal)->bool{
    match v{DecodedVal::Varint(x)=>*x==0,DecodedVal::Fixed32(x)=>*x==0,DecodedVal::Fixed64(x)=>*x==0,DecodedVal::Bytes(b)=>b.is_empty(),DecodedVal::Msg(_)=>false}
}

fn msg_json(msg:&DecodedMsg,mn:&str,sc:&Schema)->String{
    let md=match sc.messages.get(mn){Some(m)=>m,None=>return "{}".to_string()};
    let mut nums:Vec<u32>=md.fields.keys().cloned().collect();nums.sort();
    let mut parts:Vec<String>=Vec::new();
    for &n in &nums{
        let fd=&md.fields[&n];
        if !should_print(msg,fd,sc){continue;}
        let key=camel(&fd.name);
        let val=field_json(msg,fd,sc);
        parts.push(format!("\"{}\":{}",esc(&key),val));
    }
    format!("{{{}}}",parts.join(","))
}

fn field_json(msg:&DecodedMsg,fd:&FieldDef,sc:&Schema)->String{
    match fd.label{
        Label::Singular|Label::Optional=>{
            match msg.fields.get(&fd.number){Some(FieldData::Singular{value:Some(v),..})=>val_json(v,&fd.type_ref,sc),_=>"null".to_string()}
        }
        Label::Repeated=>{
            match msg.fields.get(&fd.number){
                Some(FieldData::Repeated(vec))=>{let items:Vec<String>=vec.iter().map(|v|val_json(v,&fd.type_ref,sc)).collect();format!("[{}]",items.join(","))}
                _=>"[]".to_string(),
            }
        }
        Label::Map=>{
            match msg.fields.get(&fd.number){
                Some(FieldData::Map(entries))=>{
                    let sorted=dedup_sort(entries,fd.map_key.unwrap());
                    let items:Vec<String>=sorted.iter().map(|(k,v)|{let ks=mk_str(k);format!("{}:{}",esc(&ks),val_json(v,&fd.type_ref,sc))}).collect();
                    format!("{{{}}}",items.join(","))
                }
                _=>"{}".to_string(),
            }
        }
    }
}

fn val_json(v:&DecodedVal,tr:&TypeRef,sc:&Schema)->String{
    match(v,tr){
        (DecodedVal::Varint(x),TypeRef::Scalar(st))=>match st{
            ScalarType::Int32=>format!("{}",(*x as u32) as i32),
            ScalarType::Int64=>format!("\"{}\"",*x as i64),
            ScalarType::UInt32=>format!("{}",*x as u32),
            ScalarType::UInt64=>format!("\"{}\"",*x),
            ScalarType::SInt32=>{let n=*x as u32;let r=((n>>1) as i32)^((n&1) as i32).wrapping_neg();format!("{}",r)}
            ScalarType::SInt64=>{let n=*x;let r=((n>>1) as i64)^((n&1) as i64).wrapping_neg();format!("\"{}\"",r)}
            ScalarType::Bool=>if *x!=0{"true".to_string()}else{"false".to_string()},
            ScalarType::Str=>format!("\"\""),
            ScalarType::Bytes=>format!("\"\""),
            ScalarType::Fixed32=>format!("{}",*x as u32),
            ScalarType::SFixed32=>format!("{}",(*x as u32) as i32),
            ScalarType::Fixed64=>format!("\"{}\"",*x),
            ScalarType::SFixed64=>format!("\"{}\"",*x as i64),
        },
        (DecodedVal::Varint(x),TypeRef::Named(n))=>{
            if let Some(ed)=sc.enums.get(n){let num=(*x as u32) as i32;match ed.values.get(&num){Some(name)=>format!("\"{}\"",name),None=>format!("{}",num)}}
            else{format!("{}",*x)}
        },
        (DecodedVal::Fixed32(x),TypeRef::Scalar(st))=>match st{
            ScalarType::SFixed32=>format!("{}",*x as i32),_=>format!("{}",x),
        },
        (DecodedVal::Fixed64(x),TypeRef::Scalar(st))=>match st{
            ScalarType::SFixed64=>format!("\"{}\"",*x as i64),_=>format!("\"{}\"",x),
        },
        (DecodedVal::Bytes(b),TypeRef::Scalar(ScalarType::Str))=>format!("\"{}\"",esc(&String::from_utf8_lossy(b))),
        (DecodedVal::Bytes(b),TypeRef::Scalar(ScalarType::Bytes))=>format!("\"{}\"",b64(b)),
        (DecodedVal::Msg(m),TypeRef::Named(n))=>msg_json(m,n,sc),
        _=>"null".to_string(),
    }
}

fn dedup_sort(entries:&[(MapKey,DecodedVal)],kt:ScalarType)->Vec<(MapKey,DecodedVal)>{
    let mut seen:HashMap<String,usize>=HashMap::new();
    for(i,(k,_))in entries.iter().enumerate(){let ks=match k{MapKey::Str(s)=>format!("s{}",s),MapKey::Int(n)=>format!("i{}",n)};seen.insert(ks,i);}
    let mut result:Vec<(MapKey,DecodedVal)>=seen.values().map(|&i|entries[i].clone()).collect();
    match kt{
        ScalarType::Str=>result.sort_by(|(k1,_),(k2,_)|match(k1,k2){(MapKey::Str(s1),MapKey::Str(s2))=>s1.as_bytes().cmp(s2.as_bytes()),_=>std::cmp::Ordering::Equal}),
        _=>result.sort_by_key(|(k,_)|match k{MapKey::Int(n)=>*n,_=>0}),
    }
    result
}

fn mk_str(k:&MapKey)->String{match k{MapKey::Str(s)=>s.clone(),MapKey::Int(n)=>format!("{}",n)}}

fn camel(name:&str)->String{
    let mut r=String::new();let mut up=false;
    for ch in name.chars(){if ch=='_'{up=true;}else{if up&&ch.is_ascii_lowercase(){r.push(ch.to_ascii_uppercase());}else{r.push(ch);}up=false;}}
    r
}

fn esc(s:&str)->String{
    let mut r=String::new();
    for ch in s.chars(){match ch{
        '"'=>r.push_str("\\\""),'\\'=>r.push_str("\\\\"),
        '\u{0008}'=>r.push_str("\\b"),'\t'=>r.push_str("\\t"),'\n'=>r.push_str("\\n"),
        '\u{000C}'=>r.push_str("\\f"),'\r'=>r.push_str("\\r"),
        c if(c as u32)<0x20=>r.push_str(&format!("\\u{:04x}",c as u32)),
        c=>r.push(c),
    }}
    r
}

fn b64(data:&[u8])->String{
    const C:&[u8]=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut r=String::new();let mut i=0;
    while i+2<data.len(){let n=((data[i] as u32)<<16)|((data[i+1] as u32)<<8)|(data[i+2] as u32);
        r.push(C[((n>>18)&63) as usize] as char);r.push(C[((n>>12)&63) as usize] as char);r.push(C[((n>>6)&63) as usize] as char);r.push(C[(n&63) as usize] as char);i+=3;}
    if i+1==data.len(){let n=(data[i] as u32)<<16;r.push(C[((n>>18)&63) as usize] as char);r.push(C[((n>>12)&63) as usize] as char);r.push('=');r.push('=');}
    else if i+2==data.len(){let n=((data[i] as u32)<<16)|((data[i+1] as u32)<<8);r.push(C[((n>>18)&63) as usize] as char);r.push(C[((n>>12)&63) as usize] as char);r.push(C[((n>>6)&63) as usize] as char);r.push('=');}
    r
}

fn main(){
    let args:Vec<String>=env::args().collect();
    let dir=&args[1];
    let schema_src=fs::read_to_string(format!("{}/schema.proto",dir)).unwrap();
    let bin=fs::read(format!("{}/messages.bin",dir)).unwrap();
    let sc=parse_schema(&schema_src);
    let mut pos=0;
    while pos<bin.len(){
        let len=rvar(&bin,&mut pos) as usize;
        if pos+len>bin.len(){break;}
        let mb=&bin[pos..pos+len];pos+=len;
        let dec=decode_msg(mb,&sc.root,&sc);
        println!("{}",msg_json(&dec,&sc.root,&sc));
    }
}

import sys

ALL_PRINTABLE = frozenset(chr(i) for i in range(0x20, 0x7F))
DIGITS = frozenset('0123456789')
WORD_CHARS = frozenset('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')
SPACE_CHARS = frozenset(' \t\n\r\f\v')

CLASS_ESCAPES = {
    'd': DIGITS,
    'w': WORD_CHARS,
    's': SPACE_CHARS,
    'D': ALL_PRINTABLE - DIGITS,
    'W': ALL_PRINTABLE - WORD_CHARS,
    'S': ALL_PRINTABLE - SPACE_CHARS,
}

# AST nodes
class Lit:
    def __init__(self, c): self.c = c

class Any:
    pass

class Anch:
    def __init__(self, typ): self.typ = typ

class Cls:
    def __init__(self, chars, negated): self.chars = chars; self.negated = negated

class Grp:
    def __init__(self, inner, num): self.inner = inner; self.num = num

class Seq:
    def __init__(self, items): self.items = items

class Br:
    def __init__(self, alts): self.alts = alts

class Quant:
    def __init__(self, atom, mn, mx, lazy): self.atom = atom; self.mn = mn; self.mx = mx; self.lazy = lazy

class Empty:
    pass

# Parser
def parse(pattern):
    state = {'pos': 0, 'group': 0}

    def peek():
        if state['pos'] < len(pattern):
            return pattern[state['pos']]
        return None

    def consume():
        c = pattern[state['pos']]
        state['pos'] += 1
        return c

    def parse_regex():
        alts = [parse_branch()]
        while peek() == '|':
            consume()
            alts.append(parse_branch())
        if len(alts) == 1:
            return alts[0]
        return Br(alts)

    def parse_branch():
        items = []
        while peek() is not None and peek() not in ('|', ')'):
            items.append(parse_piece())
        if not items:
            return Empty()
        if len(items) == 1:
            return items[0]
        return Seq(items)

    def parse_piece():
        atom = parse_atom()
        if peek() in ('*', '+', '?', '{'):
            mn, mx, lazy = parse_quant()
            return Quant(atom, mn, mx, lazy)
        return atom

    def parse_atom():
        c = peek()
        if c == '(':
            consume()
            if peek() == '?' and state['pos'] + 1 < len(pattern) and pattern[state['pos']+1] == ':':
                consume(); consume()
                inner = parse_regex()
                consume()  # )
                return Grp(inner, None)
            else:
                state['group'] += 1
                num = state['group']
                inner = parse_regex()
                consume()  # )
                return Grp(inner, num)
        elif c == '[':
            return parse_class()
        elif c == '.':
            consume()
            return Any()
        elif c == '^':
            consume()
            return Anch('^')
        elif c == '$':
            consume()
            return Anch('$')
        elif c == '\\':
            consume()
            c2 = consume()
            if c2 in 'dDwWsS':
                return Cls(CLASS_ESCAPES[c2], False)
            else:
                return Lit(c2)
        else:
            consume()
            return Lit(c)

    def parse_quant():
        c = consume()
        if c == '*':
            mn, mx = 0, None
        elif c == '+':
            mn, mx = 1, None
        elif c == '?':
            mn, mx = 0, 1
        elif c == '{':
            s = ''
            while peek() is not None and peek().isdigit():
                s += consume()
            mn = int(s)
            if peek() == ',':
                consume()
                s2 = ''
                while peek() is not None and peek().isdigit():
                    s2 += consume()
                mx = int(s2) if s2 else None
            else:
                mx = mn
            consume()  # }

        lazy = False
        if peek() == '?':
            consume()
            lazy = True

        return mn, mx, lazy

    def parse_class():
        consume()  # [
        negated = False
        if peek() == '^':
            consume()
            negated = True

        chars = set()
        first = True
        while peek() != ']' or first:
            first = False
            # parse item start
            if peek() == '\\':
                consume()
                c2 = consume()
                if c2 in 'dDwWsS':
                    chars |= CLASS_ESCAPES[c2]
                    continue  # class escape is a complete item, not a range start
                start = c2
            elif peek() == '[':
                consume()
                start = '['
            else:
                start = consume()

            # check for range
            if peek() == '-' and state['pos'] + 1 < len(pattern) and pattern[state['pos']+1] != ']':
                consume()  # -
                if peek() == '\\':
                    consume()
                    end = consume()
                elif peek() == '[':
                    consume()
                    end = '['
                else:
                    end = consume()
                for code in range(ord(start), ord(end) + 1):
                    chars.add(chr(code))
            else:
                chars.add(start)

        consume()  # ]
        return Cls(frozenset(chars), negated)

    ast = parse_regex()
    return ast, state['group']

