// Compile node, return list of open jump indices
List<Integer> compileNode(Node node) {
    switch (node.type) {
        case LITERAL:
            emit('C', node.char, 0);
            return emptyList();
        case DOT:
            emit('A', 0, 0);
            return emptyList();
        case CLASS:
            emit('K', node.classIndex, node.negated ? 1 : 0);
            return emptyList();
        case ASSERT_START:
            emit('B', 0, 0);
            return emptyList();
        case ASSERT_END:
            emit('E', 0, 0);
            return emptyList();
        case SEQUENCE:
            List<Integer> open = new ArrayList<>();
            for (Node piece : node.pieces) {
                open = compileNode(piece);
            }
            return open;
