            // A|B|C
            // SPLIT(startA, startB)
            // A
            // JUMP(open) -> patch to end
            // SPLIT(startB, startC)  [if 3+ branches]
            // B
            // JUMP(open) -> patch to end
            // C
            // end:

            // For n branches, we need n-1 splits and n-1 jumps (except the last branch)
            // Let me use a recursive approach:
            // compileAlternation(branches):
            //   if 1 branch: compile it
            //   else: emit SPLIT(here+1, after_first+2)
            //         compile first branch
            //         emit JUMP(placeholder)  // add to open list
            //         compileAlternation(rest)

            List<Integer> open = new ArrayList<>();
            compileAlt(node.branches, open);
            return open;
        case GROUP:
            emit('V', 2*node.index, 0);
            List<Integer> open = compileNode(node.child);
            emit('V', 2*node.index+1, 0);
            return open;  // wait, the open jumps from child should be patched to the SAVE after them
            // Hmm, this doesn't work. Let me reconsider.
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {

    static final int INST_MATCH = 0;
    static final int INST_CHAR = 1;      // arg1 = char
    static final int INST_ANY = 2;       // matches any char
    static final int INST_CLASS = 3;     // arg1 = class index, arg2 = negated (0 or 1)
    static final int INST_START = 4;     // assert at position 0
    static final int INST_END = 5;       // assert at end
    static final int INST_SPLIT = 6;     // arg1 = preferred target, arg2 = other target
    static final int INST_JUMP = 7;      // arg1 = target
    static final int INST_SAVE = 8;      // arg1 = capture slot

    static int[][] prog;
    static int progLen;
    static List<boolean[]> classes;
    static int numCaptures; // number of capturing groups

    // --- Parser ---

    static String pat;
    static int ppos;
    static int groupCount;

    // AST
    enum NT { LIT, DOT, CLS, ANC_S, ANC_E, GRP, SEQ, ALT, QNT }

    static class ANode {
        NT type;
        char ch;
        boolean negated;
        boolean[] classSet; // for CLS: classSet[c] = true means c is in the set (before negation)
        int gidx; // group index, -1 for non-capturing
        ANode child;
        List<ANode> list; // for SEQ and ALT
        int min, max; // for QNT, max=-1 means infinity
        boolean greedy;
    }

    static ANode newLit(char c) { ANode n = new ANode(); n.type = NT.LIT; n.ch = c; return n; }
    static ANode newDot() { ANode n = new ANode(); n.type = NT.DOT; return n; }
    static ANode newCls(boolean neg, boolean[] set) { ANode n = new ANode(); n.type = NT.CLS; n.negated = neg; n.classSet = set; return n; }
    static ANode newAncS() { ANode n = new ANode(); n.type = NT.ANC_S; return n; }
    static ANode newAncE() { ANode n = new ANode(); n.type = NT.ANC_E; return n; }
    static ANode newGrp(int idx, ANode child) { ANode n = new ANode(); n.type = NT.GRP; n.gidx = idx; n.child = child; return n; }
    static ANode newSeq(List<ANode> l) { ANode n = new ANode(); n.type = NT.SEQ; n.list = l; return n; }
    static ANode newAlt(List<ANode> l) { ANode n = new ANode(); n.type = NT.ALT; n.list = l; return n; }
    static ANode newQnt(ANode child, int min, int max, boolean gr) { ANode n = new ANode(); n.type = NT.QNT; n.child = child; n.min = min; n.max = max; n.greedy = gr; return n; }

    static ANode parse() {
        pat = null; // will be set before calling
        ppos = 0;
        groupCount = 0;
        return parseRegex();
    }

    static ANode parseRegex() {
        List<ANode> branches = new ArrayList<>();
        branches.add(parseBranch());
        while (ppos < pat.length() && pat.charAt(ppos) == '|') {
            ppos++;
            branches.add(parseBranch());
        }
        return branches.size() == 1 ? branches.get(0) : newAlt(branches);
    }

    static ANode parseBranch() {
        List<ANode> pieces = new ArrayList<>();
        while (ppos < pat.length() && pat.charAt(ppos) != '|' && pat.charAt(ppos) != ')') {
            pieces.add(parsePiece());
        }
        if (pieces.size() == 0) return newSeq(Collections.emptyList());
        if (pieces.size() == 1) return pieces.get(0);
        return newSeq(pieces);
    }

    static ANode parsePiece() {
        ANode atom = parseAtom();
        if (ppos < pat.length()) {
            char c = pat.charAt(ppos);
            if (c == '*') {
                ppos++;
                boolean gr = true;
                if (ppos < pat.length() && pat.charAt(ppos) == '?') { gr = false; ppos++; }
                return newQnt(atom, 0, -1, gr);
            } else if (c == '+') {
                ppos++;
                boolean gr = true;
                if (ppos < pat.length() && pat.charAt(ppos) == '?') { gr = false; ppos++; }
                return newQnt(atom, 1, -1, gr);
            } else if (c == '?') {
                ppos++;
                boolean gr = true;
                if (ppos < pat.length() && pat.charAt(ppos) == '?') { gr = false; ppos++; }
                return newQnt(atom, 0, 1, gr);
            } else if (c == '{') {
                int save = ppos;
                ppos++;
                if (ppos < pat.length() && Character.isDigit(pat.charAt(ppos))) {
                    int m = parseNum();
                    int n;
                    if (ppos < pat.length() && pat.charAt(ppos) == ',') {
                        ppos++;
                        if (ppos < pat.length() && Character.isDigit(pat.charAt(ppos))) {
                            n = parseNum();
                        } else {
                            n = -1;
                        }
                    } else {
                        n = m;
                    }
                    if (ppos < pat.length() && pat.charAt(ppos) == '}') {
                        ppos++;
                        boolean gr = true;
                        if (ppos < pat.length() && pat.charAt(ppos) == '?') { gr = false; ppos++; }
                        return newQnt(atom, m, n, gr);
                    } else {
                        ppos = save; // not valid, treat { as literal
                    }
                } else {
                    ppos = save; // not valid
                }
            }
        }
        return atom;
    }

    static int parseNum() {
        int start = ppos;
        while (ppos < pat.length() && Character.isDigit(pat.charAt(ppos))) ppos++;
        return Integer.parseInt(pat.substring(start, ppos));
    }

    static ANode parseAtom() {
        char c = pat.charAt(ppos);
        if (c == '(') {
            ppos++;
            int idx = -1;
            if (ppos < pat.length() && pat.charAt(ppos) == '?') {
                ppos++;
                if (ppos < pat.length() && pat.charAt(ppos) == ':') {
                    ppos++;
                }
            } else {
                idx = ++groupCount;
            }
            ANode child = parseRegex();
            ppos++; // skip ')'
            return newGrp(idx, child);
        } else if (c == '.') {
            ppos++;
            return newDot();
        } else if (c == '^') {
            ppos++;
            return newAncS();
        } else if (c == '$') {
            ppos++;
            return newAncE();
        } else if (c == '[') {
            return parseClass();
        } else if (c == '\\') {
            ppos++;
            char e = pat.charAt(ppos);
            ppos++;
            if (e == 'd' || e == 'D' || e == 'w' || e == 'W' || e == 's' || e == 'S') {
                boolean[] set = new boolean[128];
                fillEscapeSet(set, e);
                return newCls(false, set);
            } else {
                return newLit(e);
            }
        } else {
            ppos++;
            return newLit(c);
        }
    }

    static ANode parseClass() {
        ppos++; // skip '['
        boolean neg = false;
        if (ppos < pat.length() && pat.charAt(ppos) == '^') {
            neg = true;
            ppos++;
        }
        boolean[] set = new boolean[128];
        while (ppos < pat.length() && pat.charAt(ppos) != ']') {
            char lo;
            if (pat.charAt(ppos) == '\\') {
                ppos++;
                char e = pat.charAt(ppos);
                ppos++;
                if (e == 'd' || e == 'D' || e == 'w' || e == 'W' || e == 's' || e == 'S') {
                    fillEscapeSet(set, e);
                    continue; // class escape, can't be part of range
                } else {
                    lo = e;
                }
            } else {
                lo = pat.charAt(ppos);
                ppos++;
            }
            // Check for range
            if (ppos < pat.length() && pat.charAt(ppos) == '-' && 
                ppos + 1 < pat.length() && pat.charAt(ppos + 1) != ']') {
                ppos++; // skip '-'
                char hi;
                if (pat.charAt(ppos) == '\\') {
                    ppos++;
                    hi = pat.charAt(ppos);
                    ppos++;
                } else {
                    hi = pat.charAt(ppos);
                    ppos++;
                }
                for (int i = lo; i <= hi; i++) set[i] = true;
            } else {
                set[lo] = true;
            }
        }
        ppos++; // skip ']'
        return newCls(neg, set);
    }

    static void fillEscapeSet(boolean[] set, char e) {
        switch (e) {
            case 'd': for (int i = '0'; i <= '9'; i++) set[i] = true; break;
            case 'D': for (int i = 0; i < 128; i++) set[i] = true; for (int i = '0'; i <= '9'; i++) set[i] = false; break;
            case 'w': for (int i = '0'; i <= '9'; i++) set[i] = true; for (int i = 'A'; i <= 'Z'; i++) set[i] = true; set['_'] = true; for (int i = 'a'; i <= 'z'; i++) set[i] = true; break;
            case 'W': for (int i = 0; i < 128; i++) set[i] = true; for (int i = '0'; i <= '9'; i++) set[i] = false; for (int i = 'A'; i <= 'Z'; i++) set[i] = false; set['_'] = false; for (int i = 'a'; i <= 'z'; i++) set[i] = false; break;
            case 's': set[' '] = true; set['\t'] = true; set['\n'] = true; set['\r'] = true; set['\f'] = true; set['\v'] = true; break;
            case 'S': for (int i = 0; i < 128; i++) set[i] = true; set[' '] = false; set['\t'] = false; set['\n'] = false; set['\r'] = false; set['\f'] = false; set['\v'] = false; break;
        }
    }

    // --- Compiler ---

    static List<int[]> instructions;

    static void compile(ANode node) {
        instructions = new ArrayList<>();
        compileNode(node);
        instructions.add(new int[]{INST_MATCH, 0, 0});
        progLen = instructions.size();
        prog = instructions.toArray(new int[0][]);
    }

    static void compileNode(ANode node) {
        switch (node.type) {
            case LIT:
                instructions.add(new int[]{INST_CHAR, node.ch, 0});
                break;
            case DOT:
                instructions.add(new int[]{INST_ANY, 0, 0});
                break;
            case CLS: {
                int idx = classes.size();
                classes.add(node.classSet);
                instructions.add(new int[]{INST_CLASS, idx, node.negated ? 1 : 0});
                break;
            }
            case ANC_S:
                instructions.add(new int[]{INST_START, 0, 0});
                break;
            case ANC_E:
                instructions.add(new int[]{INST_END, 0, 0});
                break;
            case GRP:
                if (node.gidx >= 0) {
                    instructions.add(new int[]{INST_SAVE, 2 * node.gidx, 0});
                }
                compileNode(node.child);
                if (node.gidx >= 0) {
                    instructions.add(new int[]{INST_SAVE, 2 * node.gidx + 1, 0});
                }
                break;
            case SEQ:
                for (ANode piece : node.list) {
                    compileNode(piece);
                }
                break;
            case ALT:
                compileAlt(node.list);
                break;
            case QNT:
                compileQuant(node);
                break;
        }
    }

    static void compileAlt(List<ANode> branches) {
        if (branches.size() == 1) {
            compileNode(branches.get(0));
            return;
        }
        // For n branches: SPLIT(b1, split(b2, split(b3, ...)))
        // b1 JUMP(end)
        // b2 JUMP(end)
        // ...
        // bn
        // end:
        // 
        // Use recursive approach:
        // SPLIT(start_b1, start_rest)
        // b1
        // JUMP(end)
        // rest (which is the alternation of b2, b3, ...)

        int splitIdx = instructions.size();
        instructions.add(new int[]{INST_SPLIT, 0, 0}); // placeholder

        compileNode(branches.get(0));

        int jumpIdx = instructions.size();
        instructions.add(new int[]{INST_JUMP, 0, 0}); // placeholder

        // Patch split: first target is current position (start of branch 1)
        // Wait, the split should have been emitted BEFORE branch 1.
        // Let me fix: split target1 = splitIdx + 1 (which is start of branch 1)
        // split target2 = after the jump (which is start of rest)

        // Hmm, I need to restructure. Let me emit the split first, then branch 1, then jump, then rest.
        // But the split's first target should be splitIdx + 1.

        instructions.get(splitIdx)[1] = splitIdx + 1; // preferred: branch 1
        instructions.get(splitIdx)[2] = jumpIdx + 1;   // other: rest

        compileAlt(branches.subList(1, branches.size()));

        // Patch jump to end
        instructions.get(jumpIdx)[1] = instructions.size();
    }

    static void compileQuant(ANode node) {
        int min = node.min;
        int max = node.max;
        boolean greedy = node.greedy;

        if (max == -1) {
            // Unbounded: X{min,}
            // Emit min mandatory copies
            for (int i = 0; i < min; i++) {
                compileNode(node.child);
            }
            // Then unbounded optional
            if (greedy) {
                // loop: SPLIT(body, end)
                // body: <X> JUMP(loop)
                // end:
                int loopIdx = instructions.size();
                instructions.add(new int[]{INST_SPLIT, 0, 0}); // placeholder
                int bodyStart = instructions.size();
                compileNode(node.child);
                instructions.add(new int[]{INST_JUMP, loopIdx, 0});
                int endIdx = instructions.size();
                instructions.get(loopIdx)[1] = bodyStart; // preferred: body
                instructions.get(loopIdx)[2] = endIdx;     // other: end
            } else {
                // loop: SPLIT(end, body)
                // body: <X> JUMP(loop)
                // end:
                int loopIdx = instructions.size();
                instructions.add(new int[]{INST_SPLIT, 0, 0}); // placeholder
                int bodyStart = instructions.size();
                compileNode(node.child);
                instructions.add(new int[]{INST_JUMP, loopIdx, 0});
                int endIdx = instructions.size();
                instructions.get(loopIdx)[1] = endIdx;     // preferred: end (lazy)
                instructions.get(loopIdx)[2] = bodyStart;   // other: body
            }
        } else if (min == max) {
            // Exact count: X{m}
            for (int i = 0; i < min; i++) {
                compileNode(node.child);
            }
        } else {
            // Bounded: X{min,max} where min < max
            // Emit min mandatory copies
            for (int i = 0; i < min; i++) {
                compileNode(node.child);
            }
            // Emit (max - min) optional copies
            int numOptional = max - min;
            if (greedy) {
                // SPLIT(body1, end)
                // body1: <X>
                // SPLIT(body2, end)
                // body2: <X>
                // ...
                // end:
                List<Integer> splitIndices = new ArrayList<>();
                for (int i = 0; i < numOptional; i++) {
                    int splitIdx = instructions.size();
                    instructions.add(new int[]{INST_SPLIT, 0, 0}); // placeholder
                    splitIndices.add(splitIdx);
                    compileNode(node.child);
                }
                int endIdx = instructions.size();
                for (int i = 0; i < numOptional; i++) {
                    if (i == 0) {
                        instructions.get(splitIndices.get(i))[1] = splitIndices.get(i) + 1; // body
                    } else {
                        instructions.get(splitIndices.get(i))[1] = splitIndices.get(i) + 1; // body (which starts right after the split)
                    }
                    instructions.get(splitIndices.get(i))[2] = endIdx; // skip to end
                }
            } else {
                // Lazy
                // SPLIT(end, body1)
                // body1: <X>
                // SPLIT(end, body2)
                // body2: <X>
                // ...
                // end:
                List<Integer> splitIndices = new ArrayList<>();
                for (int i = 0; i < numOptional; i++) {
                    int splitIdx = instructions.size();
                    instructions.add(new int[]{INST_SPLIT, 0, 0}); // placeholder
                    splitIndices.add(splitIdx);
                    compileNode(node.child);
                }
                int endIdx = instructions.size();
                for (int i = 0; i < numOptional; i++) {
                    instructions.get(splitIndices.get(i))[1] = endIdx; // preferred: end (lazy)
                    instructions.get(splitIndices.get(i))[2] = splitIndices.get(i) + 1; // body
                }
            }
        }
    }

    // --- Pike VM ---

    static int[] runVM(String subject, int startPos) {
        int len = subject.length();
        int numSlots = numCaptures * 2;

        // Thread: [pc, cap0, cap1, ...]
        List<int[]> current = new ArrayList<>();
        boolean[] seen = new boolean[progLen];

        int[] initCaps = new int[numSlots];
        Arrays.fill(initCaps, -1);

        addThread(current, seen, 0, initCaps, startPos);

        for (int pos = startPos; pos <= len; pos++) {
            // Check for match
            for (int[] thread : current) {
                if (thread[0] == INST_MATCH) {
                    int[] result = new int[numSlots + 1];
                    result[0] = pos;
                    System.arraycopy(thread, 1, result, 1, numSlots);
                    return result;
                }
            }

            if (pos == len) break;

            char c = subject.charAt(pos);
            List<int[]> next = new ArrayList<>();
            boolean[] nextSeen = new boolean[progLen];

            for (int[] thread : current) {
                int pc = thread[0];
                if (canMatch(pc, c)) {
                    int[] caps = new int[numSlots];
                    System.arraycopy(thread, 1, caps, 0, numSlots);
                    addThread(next, nextSeen, pc + 1, caps, pos + 1);
                }
            }

            current = next;
        }

        return null;
    }

    static void addThread(List<int[]> list, boolean[] seen, int pc, int[] caps, int pos) {
        if (pc >= progLen) return;

        switch (prog[pc][0]) {
            case INST_SPLIT:
                addThread(list, seen, prog[pc][1], caps, pos);
                addThread(list, seen, prog[pc][2], caps, pos);
                break;
            case INST_JUMP:
                addThread(list, seen, prog[pc][1], caps, pos);
                break;
            case INST_SAVE:
                int[] newCaps = caps.clone();
                newCaps[prog[pc][1]] = pos;
                addThread(list, seen, pc + 1, newCaps, pos);
                break;
            default:
                if (!seen[pc]) {
                    seen[pc] = true;
                    int[] thread = new int[1 + caps.length];
                    thread[0] = pc;
                    System.arraycopy(caps, 0, thread, 1, caps.length);
                    list.add(thread);
                }
                break;
        }
    }

    static boolean canMatch(int pc, char c) {
        switch (prog[pc][0]) {
            case INST_CHAR: return prog[pc][1] == c;
            case INST_ANY: return true;
            case INST_CLASS: {
                boolean inSet = classes.get(prog[pc][1])[c];
                boolean negated = prog[pc][2] == 1;
                return negated ? !inSet : inSet;
            }
            case INST_START: return pc == 0; // Hmm, this is wrong. START asserts position 0, not pc 0.
            case INST_END: return false; // Will handle differently
            default: return false;
        }
    }

    // ...
}

