// ─── Base64 ────────────────────────────────────────────────────────────────────
fn base64_encode(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    let mut i = 0;
    while i < data.len() {
        let b0 = data[i] as u32;
        let b1 = if i + 1 < data.len() { data[i + 1] as u32 } else { 0 };
        let b2 = if i + 2 < data.len() { data[i + 2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(T[(n >> 18) as usize] as char);
        out.push(T[(n >> 12) as usize] as char);
        out.push(if i + 1 < data.len() { T[(n >> 6) as usize] as char } else { '=' });
        out.push(if i + 2 < data.len() { T[(n) as usize] as char } else { '=' });
        i += 3;
    }
    out
}

// ─── RFC 6749 §2.3.1 encoding ────────────────────────────────────────────────
fn rfc6749_enc(s: &str) -> String {
    let mut o = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'*' => o.push(b as char),
            b' ' => o.push('+'),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

// ─── Percent-encode for query param values ────────────────────────────────────
fn pct_enc(s: &str) -> String {
    let mut o = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => o.push(b as char),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

// ─── JSON ─────────────────────────────────────────────────────────────────────
#[derive(Debug, Clone)]
enum J {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

struct JP<'a> { s: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(s: &'a str) -> Self { JP { s: s.as_bytes(), p: 0 } }
    fn ws(&mut self) { while self.p < self.s.len() && matches!(self.s[self.p], b' '|b'\t'|b'\n'|b'\r') { self.p += 1; } }
    fn pk(&self) -> Option<u8> { if self.p < self.s.len() { Some(self.s[self.p]) } else { None } }
    fn eat(&mut self) -> u8 { let b = self.s[self.p]; self.p += 1; b }
    fn expect(&mut self, b: u8) { assert_eq!(self.eat(), b); }
    fn lit(&mut self, l: &[u8]) { for &b in l { assert_eq!(self.eat(), b); } }

    fn parse(&mut self) -> J { self.ws(); self.val() }

    fn val(&mut self) -> J {
        self.ws();
        match self.pk() {
            Some(b'{') => J::Obj(self.obj()),
            Some(b'[') => J::Arr(self.arr()),
            Some(b'"') => J::Str(self.string()),
            Some(b't') => { self.lit(b"true"); J::Bool(true) }
            Some(b'f') => { self.lit(b"false"); J::Bool(false) }
            Some(b'n') => { self.lit(b"null"); J::Null }
            _ => J::Num(self.number()),
        }
    }

    fn obj(&mut self) -> Vec<(String, J)> {
        self.expect(b'{');
        let mut v = Vec::new();
        self.ws();
        if self.pk() == Some(b'}') { self.p += 1; return v; }
        loop {
            self.ws();
            let k = self.string();
            self.ws();
            self.expect(b':');
            let val = self.val();
            v.push((k, val));
            self.ws();
            if self.pk() == Some(b',') { self.p += 1; } else { break; }
        }
        self.ws();
        self.expect(b'}');
        v
    }

    fn arr(&mut self) -> Vec<J> {
        self.expect(b'[');
        let mut v = Vec::new();
        self.ws();
        if self.pk() == Some(b']') { self.p += 1; return v; }
        loop {
            v.push(self.val());
            self.ws();
            if self.pk() == Some(b',') { self.p += 1; } else { break; }
        }
        self.ws();
        self.expect(b']');
        v
    }

    fn string(&mut self) -> String {
        self.expect(b'"');
        let mut buf: Vec<u8> = Vec::new();
        loop {
            let b = self.eat();
            if b == b'"' { break; }
            if b == b'\\' {
                let e = self.eat();
                match e {
                    b'"' => buf.push(b'"'),
                    b'\\' => buf.push(b'\\'),
                    b'/' => buf.push(b'/'),
                    b'b' => buf.push(0x08),
                    b'f' => buf.push(0x0C),
                    b'n' => buf.push(b'\n'),
                    b'r' => buf.push(b'\r'),
                    b't' => buf.push(b'\t'),
                    b'u' => {
                        let cp = self.hex4();
                        let code = if cp >= 0xD800 && cp <= 0xDBFF {
                            self.expect(b'\\'); self.expect(b'u');
                            let lo = self.hex4();
                            0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)
                        } else { cp };
                        let mut tmp = [0u8; 4];
                        let s = char::from_u32(code).unwrap().encode_utf8(&mut tmp);
                        buf.extend_from_slice(s.as_bytes());
                    }
                    _ => unreachable!(),
                }
            } else {
                buf.push(b);
            }
        }
        String::from_utf8(buf).unwrap()
    }

    fn hex4(&mut self) -> u32 {
        let mut v: u32 = 0;
        for _ in 0..4 {
            let b = self.eat();
            let d = match b {
                b'0'..=b'9' => (b - b'0') as u32,
                b'a'..=b'f' => (b - b'a') as u32 + 10,
                b'A'..=b'F' => (b - b'A') as u32 + 10,
                _ => unreachable!(),
            };
            v = v * 16 + d;
        }
        v
    }

    fn number(&mut self) -> f64 {
        let st = self.p;
        if self.pk() == Some(b'-') { self.p += 1; }
        while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; }
        if self.p < self.s.len() && self.s[self.p] == b'.' { self.p += 1; while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; } }
        if self.p < self.s.len() && (self.s[self.p] == b'e' || self.s[self.p] == b'E') {
            self.p += 1;
            if self.p < self.s.len() && (self.s[self.p] == b'+' || self.s[self.p] == b'-') { self.p += 1; }
            while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; }
        }
        std::str::from_utf8(&self.s[st..self.p]).unwrap().parse().unwrap()
    }
}

fn jg<'a>(o: &'a J, k: &str) -> Option<&'a J> {
    if let J::Obj(f) = o { f.iter().find(|(kk, _)| kk == k).map(|(_, v)| v) } else { None }
}
fn jgs(o: &J, k: &str) -> String { match jg(o, k) { Some(J::Str(s)) => s.clone(), _ => panic!("!str {}", k) } }
fn jgn(o: &J, k: &str) -> f64 { match jg(o, k) { Some(J::Num(n)) => *n, _ => panic!("!num {}", k) } }
fn jga(o: &J, k: &str) -> Vec<J> { match jg(o, k) { Some(J::Arr(a)) => a.clone(), _ => vec![] } }
fn jgo(o: &J, k: &str) -> Option<String> {
    match jg(o, k) { Some(J::Str(s)) => Some(s.clone()), _ => None }
}

// ─── Amount ───────────────────────────────────────────────────────────────────
fn parse_amt(s: &str) -> i64 {
    let (neg, r) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
    let cents = if let Some(dp) = r.find('.') {
        let ip = &r[..dp];
        let fp = &r[dp + 1..];
        let iv: i64 = if ip.is_empty() { 0 } else { ip.parse().unwrap() };
        let fv: i64 = match fp.len() {
            1 => fp.parse::<i64>().unwrap() * 10,
            2 => fp.parse::<i64>().unwrap(),
            _ => unreachable!(),
        };
        iv * 100 + fv
    } else {
        r.parse::<i64>().unwrap() * 100
    };
    if neg { -cents } else { cents }
}

fn fmt_amt(c: i64) -> String {
    let neg = c < 0;
    let a = c.abs();
    let ip = a / 100;
    let fp = a % 100;
    if neg { format!("-{}.{:02}", ip, fp) } else { format!("{}.{:02}", ip, fp) }
}

// ─── URL ──────────────────────────────────────────────────────────────────────
fn parse_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("http://").unwrap_or(url);
    let sp = rest.find('/').unwrap_or(rest.len());
    let hp = &rest[..sp];
    let path = &rest[sp..];
    let (host, port) = match hp.rfind(':') {
        Some(i) => (&hp[..i], hp[i + 1..].parse::<u16>().unwrap_or(80)),
        None => (hp, 80u16),
    };
    (host.to_string(), port, path.to_string())
}

// ─── HTTP ─────────────────────────────────────────────────────────────────────
struct Resp { status: u16, headers: Vec<(String, String)>, body: String }

fn hdr(resp: &Resp, name: &str) -> Option<String> {
    resp.headers.iter().find(|(k, _)| k == name).map(|(_, v)| v.clone())
}

fn do_req(host: &str, port: u16, method: &str, path: &str, extra: &[String], body: Option<&str>) -> Resp {
    let mut s = TcpStream::connect((host, port)).unwrap();
    s.set_read_timeout(Some(Duration::from_secs(30))).unwrap();
    s.set_write_timeout(Some(Duration::from_secs(30))).unwrap();

    let mut req = format!("{} {} HTTP/1.1\r\n", method, path);
    req.push_str(&format!("Host: {}:{}\r\n", host, port));
    for h in extra { req.push_str(h); req.push_str("\r\n"); }
    if let Some(b) = body { req.push_str(&format!("Content-Length: {}\r\n", b.len())); }
    req.push_str("Connection: close\r\n\r\n");
    if let Some(b) = body { req.push_str(b); }

    s.write_all(req.as_bytes()).unwrap();
    s.flush().unwrap();

    let mut r = BufReader::new(s);

    let mut sl = String::new();
    r.read_line(&mut sl).unwrap();
    let status: u16 = sl.split_whitespace().nth(1).unwrap().parse().unwrap();

    let mut headers = Vec::new();
    loop {
        let mut ln = String::new();
        r.read_line(&mut ln).unwrap();
        if ln.is_empty() || ln == "\r\n" || ln == "\n" { break; }
        if let Some(ci) = ln.find(':') {
            headers.push((ln[..ci].trim().to_lowercase(), ln[ci + 1..].trim().to_string()));
        }
    }

    let body_str = if headers.iter().any(|(k, v)| k == "transfer-encoding" && v.to_lowercase().contains("chunked")) {
        let mut buf = Vec::new();
        loop {
            let mut ln = String::new();
            r.read_line(&mut ln).unwrap();
            let sz = usize::from_str_radix(ln.trim().split(';').next().unwrap(), 16).unwrap();
            if sz == 0 {
                loop { let mut t = String::new(); r.read_line(&mut t).unwrap(); if t.is_empty() || t == "\r\n" || t == "\n" { break; } }
                break;
            }
            let mut d = vec![0u8; sz];
            r.read_exact(&mut d).unwrap();
            buf.extend_from_slice(&d);
            let mut crlf = [0u8; 2];
            r.read_exact(&mut crlf).unwrap();
        }
        String::from_utf8(buf).unwrap()
    } else if let Some((_, cl)) = headers.iter().find(|(k, _)| k == "content-length") {
        let n: usize = cl.parse().unwrap();
        let mut d = vec![0u8; n];
        if n > 0 { r.read_exact(&mut d).unwrap(); }
        String::from_utf8(d).unwrap()
    } else {
        let mut d = String::new();
        r.read_to_string(&mut d).unwrap();
        d
    };

    Resp { status, headers, body: body_str }
}

// ─── Token ────────────────────────────────────────────────────────────────────
fn get_token(host: &str, port: u16, prefix: &str, cid: &str, csec: &str, scope: &str) -> String {
    let path = format!("{}/oauth/token", prefix);
    let auth = format!("Authorization: Basic {}", base64_encode(format!("{}:{}", rfc6749_enc(cid), rfc6749_enc(csec)).as_bytes()));
    let body = format!("grant_type=client_credentials&scope={}", rfc6749_enc(scope));
    let resp = do_req(host, port, "POST", &path, &[auth, "Content-Type: application/x-www-form-urlencoded".into()], Some(&body));
    if resp.status != 200 {
        println!("ERROR {} {}", resp.status, resp.body);
        std::process::exit(0);
    }
    let j = JP::new(&resp.body).parse();
    jgs(&j, "access_token")
}

// ─── Main ─────────────────────────────────────────────────────────────────────
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let cj_str = std::fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let cj = JP::new(&cj_str).parse();
    let client_id = jgs(&cj, "client_id");
    let client_secret = jgs(&cj, "client_secret");
    let scope = jgs(&cj, "scope");
    let page_size = jgn(&cj, "page_size") as i64;

    let (host, port, prefix) = parse_url(base_url);

    let mut token = get_token(&host, port, &prefix, &client_id, &client_secret, &scope);

    let mut all_orders: Vec<J> = Vec::new();
    let mut pages: i64 = 0;
    let mut retries: i64 = 0;
    let mut reauths: i64 = 0;
    let mut cursor: Option<String> = None;
    let mut first_with_token = true;

    loop {
        let mut path = format!("{}/orders?limit={}", prefix, page_size);
        if let Some(ref c) = cursor {
            path.push_str(&format!("&cursor={}", pct_enc(c)));
        }

        let resp = do_req(&host, port, "GET", &path, &[format!("Authorization: Bearer {}", token)], None);

        if resp.status == 429 {
            retries += 1;
            let ra: u64 = hdr(&resp, "retry-after").unwrap_or_else(|| "1".into()).parse().unwrap_or(1);
            thread::sleep(Duration::from_secs(ra));
            continue;
        }
        if resp.status == 503 {
            retries += 1;
            thread::sleep(Duration::from_millis(200));
            continue;
        }
        if resp.status == 401 {
            if first_with_token {
                println!("ERROR {} {}", resp.status, resp.body);
                std::process::exit(0);
            }
            reauths += 1;
            token = get_token(&host, port, &prefix, &client_id, &client_secret, &scope);
            first_with_token = true;
            continue;
        }
        if resp.status != 200 {
            println!("ERROR {} {}", resp.status, resp.body);
            std::process::exit(0);
        }

        pages += 1;
        first_with_token = false;

        let j = JP::new(&resp.body).parse();
        all_orders.extend(jga(&j, "data"));
        cursor = jgo(&j, "next_cursor");
        if cursor.is_none() { break; }
    }

    // Aggregate
    let mut totals: BTreeMap<(String, String), i64> = BTreeMap::new();
    let mut statuses: BTreeMap<String, i64> = BTreeMap::new();

    for o in &all_orders {
        let st = jgs(o, "status");
        *statuses.entry(st.clone()).or_insert(0) += 1;
        if st != "cancelled" {
            let cur = jgs(o, "currency");
            let amt = parse_amt(&jgs(o, "amount"));
            let cust = jg(o, "customer").unwrap();
            let name = jgs(cust, "name");
            *totals.entry((name, cur)).or_insert(0) += amt;
        }
    }

    // Output
    let mut out = String::new();
    for ((name, cur), cents) in &totals {
        out.push_str(&format!("total {} {} {}\n", cur, fmt_amt(*cents), name));
    }
    for (st, cnt) in &statuses {
        out.push_str(&format!("status {} {}\n", st, cnt));
    }
    out.push_str(&format!("orders {} pages {} retries {} reauth {}\n", all_orders.len(), pages, retries, reauths));
    print!("{}", out);
}

