// ─── Base64 ────────────────────────────────────────────────────────────────────
fn base64_encode(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    let mut i = 0;
    while i < data.len() {
        let b0 = data[i] as u32;
        let b1 = if i + 1 < data.len() { data[i + 1] as u32 } else { 0 };
        let b2 = if i + 2 < data.len() { data[i + 2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(T[((n >> 18) & 0x3F) as usize] as char);
        out.push(T[((n >> 12) & 0x3F) as usize] as char);
        out.push(if i + 1 < data.len() { T[((n >> 6) & 0x3F) as usize] as char } else { '=' });
        out.push(if i + 2 < data.len() { T[(n & 0x3F) as usize] as char } else { '=' });
        i += 3;
    }
    out
}

// ─── RFC 6749 §2.3.1 encoding ────────────────────────────────────────────────
fn rfc6749_enc(s: &str) -> String {
    let mut o = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'*' => o.push(b as char),
            b' ' => o.push('+'),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

// ─── Percent-encode for query param values ────────────────────────────────────
fn pct_enc(s: &str) -> String {
    let mut o = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => o.push(b as char),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

// ─── JSON ─────────────────────────────────────────────────────────────────────
#[derive(Debug, Clone)]
enum J {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

struct JP<'a> { s: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(s: &'a str) -> Self { JP { s: s.as_bytes(), p: 0 } }
    fn ws(&mut self) { while self.p < self.s.len() && matches!(self.s[self.p], b' '|b'\t'|b'\n'|b'\r') { self.p += 1; } }
    fn pk(&self) -> Option<u8> { if self.p < self.s.len() { Some(self.s[self.p]) } else { None } }
    fn eat(&mut self) -> u8 { let b = self.s[self.p]; self.p += 1; b }
    fn expect(&mut self, b: u8) { assert_eq!(self.eat(), b); }
    fn lit(&mut self, l: &[u8]) { for &b in l { assert_eq!(self.eat(), b); } }

    fn parse(&mut self) -> J { self.ws(); self.val() }

    fn val(&mut self) -> J {
        self.ws();
        match self.pk() {
            Some(b'{') => J::Obj(self.obj()),
            Some(b'[') => J::Arr(self.arr()),
            Some(b'"') => J::Str(self.string()),
            Some(b't') => { self.lit(b"true"); J::Bool(true) }
            Some(b'f') => { self.lit(b"false"); J::Bool(false) }
            Some(b'n') => { self.lit(b"null"); J::Null }
            _ => J::Num(self.number()),
        }
    }

    fn obj(&mut self) -> Vec<(String, J)> {
        self.expect(b'{');
        let mut v = Vec::new();
        self.ws();
        if self.pk() == Some(b'}') { self.p += 1; return v; }
        loop {
            self.ws();
            let k = self.string();
            self.ws();
            self.expect(b':');
            let val = self.val();
            v.push((k, val));
            self.ws();
            if self.pk() == Some(b',') { self.p += 1; } else { break; }
        }
        self.ws();
        self.expect(b'}');
        v
    }

    fn arr(&mut self) -> Vec<J> {
        self.expect(b'[');
        let mut v = Vec::new();
        self.ws();
        if self.pk() == Some(b']') { self.p += 1; return v; }
        loop {
            v.push(self.val());
            self.ws();
            if self.pk() == Some(b',') { self.p += 1; } else { break; }
        }
        self.ws();
        self.expect(b']');
        v
    }

    fn string(&mut self) -> String {
        self.expect(b'"');
        let mut buf: Vec<u8> = Vec::new();
        loop {
            let b = self.eat();
            if b == b'"' { break; }
            if b == b'\\' {
                let e = self.eat();
                match e {
                    b'"' => buf.push(b'"'),
                    b'\\' => buf.push(b'\\'),
                    b'/' => buf.push(b'/'),
                    b'b' => buf.push(0x08),
                    b'f' => buf.push(0x0C),
                    b'n' => buf.push(b'\n'),
                    b'r' => buf.push(b'\r'),
                    b't' => buf.push(b'\t'),
                    b'u' => {
                        let cp = self.hex4();
                        let code = if cp >= 0xD800 && cp <= 0xDBFF {
                            self.expect(b'\\'); self.expect(b'u');
                            let lo = self.hex4();
                            0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)
                        } else { cp };
                        let mut tmp = [0u8; 4];
                        let s = char::from_u32(code).unwrap().encode_utf8(&mut tmp);
                        buf.extend_from_slice(s.as_bytes());
                    }
                    _ => unreachable!(),
                }
            } else {
                buf.push(b);
            }
        }
        String::from_utf8(buf).unwrap()
    }

    fn hex4(&mut self) -> u32 {
        let mut v: u32 = 0;
        for _ in 0..4 {
            let b = self.eat();
            let d = match b {
                b'0'..=b'9' => (b - b'0') as u32,
                b'a'..=b'f' => (b - b'a') as u32 + 10,
                b'A'..=b'F' => (b - b'A') as u32 + 10,
                _ => unreachable!(),
            };
            v = v * 16 + d;
        }
        v
    }

    fn number(&mut self) -> f64 {
        let st = self.p;
        if self.pk() == Some(b'-') { self.p += 1; }
        while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; }
        if self.p < self.s.len() && self.s[self.p] == b'.' { self.p += 1; while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; } }
        if self.p < self.s.len() && (self.s[self.p] == b'e' || self.s[self.p] == b'E') {
            self.p += 1;
            if self.p < self.s.len() && (self.s[self.p] == b'+' || self.s[self.p] == b'-') { self.p += 1; }
            while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; }
        }
        std::str::from_utf8(&self.s[st..self.p]).unwrap().parse().unwrap()
    }
}

fn jg<'a>(o: &'a J, k: &str) -> Option<&'a J> {
    if let J::Obj(f) = o { f.iter().find(|(kk, _)| kk == k).map(|(_, v)| v) } else { None }
}
fn jgs(o: &J, k: &str) -> String { match jg(o, k) { Some(J::Str(s)) => s.clone(), _ => panic!("!str {}", k) } }
fn jgn(o: &J, k: &str) -> f64 { match jg(o, k) { Some(J::Num(n)) => *n, _ => panic!("!num {}", k) } }
fn jga(o: &J, k: &str) -> Vec<J> { match jg(o, k) { Some(J::Arr(a)) => a.clone(), _ => vec![] } }
fn jgo(o: &J, k: &str) -> Option<String> {
    match jg(o, k) { Some(J::Str(s)) => Some(s.clone()), _ => None }
