// ─── HTTP ─────────────────────────────────────────────────────────────────────
struct Resp { status: u16, headers: Vec<(String, String)>, body: String }

fn hdr(resp: &Resp, name: &str) -> Option<String> {
    resp.headers.iter().find(|(k, _)| k == name).map(|(_, v)| v.clone())
}

fn do_req(host: &str, port: u16, method: &str, path: &str, extra: &[String], body: Option<&str>) -> Resp {
    let mut s = TcpStream::connect((host, port)).unwrap();
    s.set_read_timeout(Some(Duration::from_secs(30))).unwrap();
    s.set_write_timeout(Some(Duration::from_secs(30))).unwrap();

    let host_hdr = if port == 80 {
        format!("Host: {}\r\n", host)
    } else {
        format!("Host: {}:{}\r\n", host, port)
    };

    let mut req = format!("{} {} HTTP/1.1\r\n", method, path);
    req.push_str(&host_hdr);
    for h in extra { req.push_str(h); req.push_str("\r\n"); }
    if let Some(b) = body { req.push_str(&format!("Content-Length: {}\r\n", b.len())); }
    req.push_str("Connection: close\r\n\r\n");
    if let Some(b) = body { req.push_str(b); }

    s.write_all(req.as_bytes()).unwrap();
    s.flush().unwrap();

    let mut r = BufReader::new(s);

    let mut sl = String::new();
    r.read_line(&mut sl).unwrap();
    let status: u16 = sl.split_whitespace().nth(1).unwrap().parse().unwrap();

    let mut headers = Vec::new();
    loop {
        let mut ln = String::new();
        r.read_line(&mut ln).unwrap();
        if ln.is_empty() || ln == "\r\n" || ln == "\n" { break; }
        if let Some(ci) = ln.find(':') {
            headers.push((ln[..ci].trim().to_lowercase(), ln[ci + 1..].trim().to_string()));
        }
    }

    let body_str = if headers.iter().any(|(k, v)| k == "transfer-encoding" && v.to_lowercase().contains("chunked")) {
        let mut buf = Vec::new();
        loop {
            let mut ln = String::new();
            r.read_line(&mut ln).unwrap();
            let sz = usize::from_str_radix(ln.trim().split(';').next().unwrap().trim(), 16).unwrap();
            if sz == 0 {
                // consume trailers / final CRLF
                loop {
                    let mut t = String::new();
                    r.read_line(&mut t).unwrap();
                    if t.is_empty() || t == "\r\n" || t == "\n" { break; }
                }
                break;
            }
            let mut d = vec![0u8; sz];
            r.read_exact(&mut d).unwrap();
            buf.extend_from_slice(&d);
            // consume trailing CRLF after chunk data
            loop {
                let mut b = [0u8; 1];
                r.read_exact(&mut b).unwrap();
                if b[0] == b'\n' { break; }
            }
        }
        String::from_utf8(buf).unwrap()
    } else if let Some((_, cl)) = headers.iter().find(|(k, _)| k == "content-length") {
        let n: usize = cl.parse().unwrap();
        let mut d = vec![0u8; n];
        if n > 0 { r.read_exact(&mut d).unwrap(); }
        String::from_utf8(d).unwrap()
    } else {
        let mut d = String::new();
        r.read_to_string(&mut d).unwrap();
        d
    };

    Resp { status, headers, body: body_str }
}

// ─── Token ────────────────────────────────────────────────────────────────────
fn get_token(host: &str, port: u16, prefix: &str, cid: &str, csec: &str, scope: &str) -> String {
    let path = format!("{}/oauth/token", prefix);
    let auth = format!("Authorization: Basic {}", base64_encode(format!("{}:{}", rfc6749_enc(cid), rfc6749_enc(csec)).as_bytes()));
    let body = format!("grant_type=client_credentials&scope={}", rfc6749_enc(scope));
    let resp = do_req(host, port, "POST", &path, &[auth, "Content-Type: application/x-www-form-urlencoded".into()], Some(&body));
    if resp.status != 200 {
        println!("ERROR {} {}", resp.status, resp.body);
        std::process::exit(0);
    }
    let j = JP::new(&resp.body).parse();
    jgs(&j, "access_token")
}

// ─── Main ─────────────────────────────────────────────────────────────────────
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let cj_str = std::fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let cj = JP::new(&cj_str).parse();
    let client_id = jgs(&cj, "client_id");
    let client_secret = jgs(&cj, "client_secret");
    let scope = jgs(&cj, "scope");
    let page_size = jgn(&cj, "page_size") as i64;

    let (host, port, prefix) = parse_url(base_url);

    let mut token = get_token(&host, port, &prefix, &client_id, &client_secret, &scope);

    let mut all_orders: Vec<J> = Vec::new();
    let mut pages: i64 = 0;
    let mut retries: i64 = 0;
    let mut reauths: i64 = 0;
    let mut cursor: Option<String> = None;
    let mut first_with_token = true;

    loop {
        let mut path = format!("{}/orders?limit={}", prefix, page_size);
        if let Some(ref c) = cursor {
            path.push_str(&format!("&cursor={}", pct_enc(c)));
        }

        let resp = do_req(&host, port, "GET", &path, &[format!("Authorization: Bearer {}", token)], None);

        if resp.status == 429 {
            retries += 1;
            let ra: u64 = hdr(&resp, "retry-after").unwrap_or_else(|| "1".into()).parse().unwrap_or(1);
            thread::sleep(Duration::from_secs(ra));
            continue;
        }
        if resp.status == 503 {
            retries += 1;
            thread::sleep(Duration::from_millis(200));
            continue;
        }
        if resp.status == 401 {
            if first_with_token {
                println!("ERROR {} {}", resp.status, resp.body);
                std::process::exit(0);
            }
            reauths += 1;
            token = get_token(&host, port, &prefix, &client_id, &client_secret, &scope);
            first_with_token = true;
            continue;
        }
        if resp.status != 200 {
            println!("ERROR {} {}", resp.status, resp.body);
            std::process::exit(0);
        }

        pages += 1;
        first_with_token = false;

        let j = JP::new(&resp.body).parse();
        all_orders.extend(jga(&j, "data"));
        cursor = jgo(&j, "next_cursor");
        if cursor.is_none() { break; }
    }

    // Aggregate
    let mut totals: BTreeMap<(String, String), i64> = BTreeMap::new();
    let mut statuses: BTreeMap<String, i64> = BTreeMap::new();

    for o in &all_orders {
        let st = jgs(o, "status");
        *statuses.entry(st.clone()).or_insert(0) += 1;
        if st != "cancelled" {
            let cur = jgs(o, "currency");
            let amt = parse_amt(&jgs(o, "amount"));
            let cust = jg(o, "customer").unwrap();
            let name = jgs(cust, "name");
            *totals.entry((name, cur)).or_insert(0) += amt;
        }
    }

    // Output
    let mut out = String::new();
    for ((name, cur), cents) in &totals {
        out.push_str(&format!("total {} {} {}\n", cur, fmt_amt(*cents), name));
    }
    for (st, cnt) in &statuses {
        out.push_str(&format!("status {} {}\n", st, cnt));
    }
    out.push_str(&format!("orders {} pages {} retries {} reauth {}\n", all_orders.len(), pages, retries, reauths));
    print!("{}", out);
}

