import Foundation

enum Instr {
    case char(UInt8)
    case classM(Set<UInt8>)
    case any
    case start
    case end
    case split(Int, Int)
    case jmp(Int)
    case save(Int)
    case markpos(Int)
    case checkpos(Int, Int)
    case match
}

indirect enum AST {
    case empty
    case char(UInt8)
    case anyChar
    case startAnchor
    case endAnchor
    case classMatch(Set<UInt8>)
    case concat([AST])
    case alt([AST])
    case group(AST, Int?)
    case quant(AST, Int, Int?, Bool)
}

func digitSet() -> Set<UInt8> { Set(UInt8(ascii: "0")...UInt8(ascii: "9")) }
func wordSet() -> Set<UInt8> {
    var s = Set<UInt8>()
    for c in UInt8(ascii: "0")...UInt8(ascii: "9") { s.insert(c) }
    for c in UInt8(ascii: "A")...UInt8(ascii: "Z") { s.insert(c) }
    for c in UInt8(ascii: "a")...UInt8(ascii: "z") { s.insert(c) }
    s.insert(UInt8(ascii: "_"))
    return s
}
func spaceSet() -> Set<UInt8> { Set([0x20, 0x09, 0x0A, 0x0D, 0x0C, 0x0B]) }
func complementSet(_ s: Set<UInt8>) -> Set<UInt8> {
    var r = Set<UInt8>()
    for i in UInt8(0)...UInt8(255) { if !s.contains(i) { r.insert(i) } }
    return r
}

func isNullable(_ node: AST) -> Bool {
    switch node {
    case .empty: return true
    case .char, .anyChar, .startAnchor, .endAnchor, .classMatch: return false
    case .concat(let items): return items.allSatisfy { isNullable($0) }
    case .alt(let branches): return branches.contains { isNullable($0) }
    case .group(let inner, _): return isNullable(inner)
    case .quant(let inner, let mn, _, _): return mn == 0 || isNullable(inner)
    }
}

struct RegexParser {
    let pat: [UInt8]
    var pos: Int
    var nGroups: Int

    init(_ s: String) {
        pat = Array(s.utf8)
        pos = 0
        nGroups = 0
    }

    mutating func parse() -> AST { return parseAlt() }

    mutating func parseAlt() -> AST {
        var branches = [parseBranch()]
        while pos < pat.count && pat[pos] == UInt8(ascii: "|") {
            pos += 1
            branches.append(parseBranch())
        }
        return branches.count == 1 ? branches[0] : .alt(branches)
    }

    mutating func parseBranch() -> AST {
        var pieces: [AST] = []
        while pos < pat.count && pat[pos] != UInt8(ascii: "|") && pat[pos] != UInt8(ascii: ")") {
            pieces.append(parsePiece())
        }
        if pieces.isEmpty { return .empty }
        if pieces.count == 1 { return pieces[0] }
        return .concat(pieces)
    }

    mutating func parsePiece() -> AST {
        let atom = parseAtom()
        if pos < pat.count {
            let c = pat[pos]
            if c == UInt8(ascii: "*") || c == UInt8(ascii: "+") || c == UInt8(ascii: "?") || c == UInt8(ascii: "{") {
                return parseQuant(atom)
            }
        }
        return atom
    }

    mutating func parseQuant(_ atom: AST) -> AST {
        let c = pat[pos]
        var lo = 0, hi: Int? = nil
        if c == UInt8(ascii: "*") { pos += 1; lo = 0; hi = nil }
        else if c == UInt8(ascii: "+") { pos += 1; lo = 1; hi = nil }
        else if c == UInt8(ascii: "?") { pos += 1; lo = 0; hi = 1 }
        else {
            pos += 1
            lo = parseNum()
            if pos < pat.count && pat[pos] == UInt8(ascii: ",") {
                pos += 1
                if pos < pat.count && pat[pos] != UInt8(ascii: "}") { hi = parseNum() }
                else { hi = nil }
            } else { hi = lo }
            pos += 1
        }
        var lazy = false
        if pos < pat.count && pat[pos] == UInt8(ascii: "?") { pos += 1; lazy = true }
        return .quant(atom, lo, hi, lazy)
    }

    mutating func parseNum() -> Int {
        var n = 0
        while pos < pat.count && pat[pos] >= UInt8(ascii: "0") && pat[pos] <= UInt8(ascii: "9") {
            n = n * 10 + Int(pat[pos] - UInt8(ascii: "0"))
            pos += 1
        }
        return n
    }

    mutating func parseAtom() -> AST {
        let c = pat[pos]
        switch c {
        case UInt8(ascii: "("):
            pos += 1
            if pos + 1 < pat.count && pat[pos] == UInt8(ascii: "?") && pat[pos+1] == UInt8(ascii: ":") {
                pos += 2
                let inner = parseAlt()
                pos += 1
                return .group(inner, nil)
            } else {
                nGroups += 1
                let gn = nGroups
                let inner = parseAlt()
                pos += 1
                return .group(inner, gn)
            }
        case UInt8(ascii: "["): return parseClass()
        case UInt8(ascii: "."): pos += 1; return .anyChar
        case UInt8(ascii: "^"): pos += 1; return .startAnchor
        case UInt8(ascii: "$"): pos += 1; return .endAnchor
        case UInt8(ascii: "\\"):
            pos += 1
            let e = pat[pos]; pos += 1
            switch e {
            case UInt8(ascii: "d"): return .classMatch(digitSet())
            case UInt8(ascii: "D"): return .classMatch(complementSet(digitSet()))
            case UInt8(ascii: "w"): return .classMatch(wordSet())
            case UInt8(ascii: "W"): return .classMatch(complementSet(wordSet()))
            case UInt8(ascii: "s"): return .classMatch(spaceSet())
            case UInt8(ascii: "S"): return .classMatch(complementSet(spaceSet()))
            default: return .char(e)
            }
        default: pos += 1; return .char(c)
        }
    }

    mutating func parseClass() -> AST {
        pos += 1
        var negated = false
        if pos < pat.count && pat[pos] == UInt8(ascii: "^") { negated = true; pos += 1 }
        var chars = Set<UInt8>()
        while pos < pat.count && pat[pos] != UInt8(ascii: "]") {
            var lo: UInt8
            if pat[pos] == UInt8(ascii: "\\") {
                pos += 1
                let e = pat[pos]; pos += 1
                switch e {
                case UInt8(ascii: "d"): chars.formUnion(digitSet()); continue
                case UInt8(ascii: "D"): chars.formUnion(complementSet(digitSet())); continue
                case UInt8(ascii: "w"): chars.formUnion(wordSet()); continue
                case UInt8(ascii: "W"): chars.formUnion(complementSet(wordSet())); continue
                case UInt8(ascii: "s"): chars.formUnion(spaceSet()); continue
                case UInt8(ascii: "S"): chars.formUnion(complementSet(spaceSet())); continue
                default: lo = e
                }
            } else {
                lo = pat[pos]; pos += 1
            }
            if pos < pat.count && pat[pos] == UInt8(ascii: "-") && pos + 1 < pat.count && pat[pos+1] != UInt8(ascii: "]") {
                pos += 1
                var hi: UInt8
                if pat[pos] == UInt8(ascii: "\\") { pos += 1; hi = pat[pos]; pos += 1 }
                else { hi = pat[pos]; pos += 1 }
                for c in lo...hi { chars.insert(c) }
            } else {
                chars.insert(lo)
            }
        }
        pos += 1
        if negated { chars = complementSet(chars) }
        return .classMatch(chars)
    }
}

func compile(_ ast: AST, numGroups: Int) -> ([Instr], Int) {
    var instrs: [Instr] = []
    var numLoopSlots = 0

    func emit(_ i: Instr) -> Int {
        instrs.append(i)
        return instrs.count - 1
    }

    func compileNode(_ node: AST) {
        switch node {
        case .empty: break
        case .char(let c): emit(.char(c))
        case .anyChar: emit(.any)
        case .startAnchor: emit(.start)
        case .endAnchor: emit(.end)
        case .classMatch(let s): emit(.classM(s))
        case .concat(let items): for item in items { compileNode(item) }
        case .alt(let branches):
            if branches.count == 1 {
                compileNode(branches[0])
            } else {
                let splitIdx = emit(.split(0, 0))
                let firstStart = instrs.count
                compileNode(branches[0])
                let jmpIdx = emit(.jmp(0))
                let restStart = instrs.count
                compileNode(.alt(Array(branches[1...])))
                let after = instrs.count
                instrs[splitIdx] = .split(firstStart, restStart)
                instrs[jmpIdx] = .jmp(after)
            }
        case .group(let inner, let capNum):
            if let n = capNum {
                emit(.save(2 * n))
                compileNode(inner)
                emit(.save(2 * n + 1))
            } else {
                compileNode(inner)
            }
        case .quant(let inner, let lo, let hi, let lazy):
            for _ in 0..<lo { compileNode(inner) }
            let needsCheck = isNullable(inner)
            if hi == nil {
                let loopStart = emit(.split(0, 0))
                let bodyStart = instrs.count
                let slot = numLoopSlots; numLoopSlots += 1
                if needsCheck { emit(.markpos(slot)) }
                compileNode(inner)
                var checkposIdx = -1
                if needsCheck { checkposIdx = emit(.checkpos(slot, 0)) }
                emit(.jmp(loopStart))
                let afterLoop = instrs.count
                if lazy { instrs[loopStart] = .split(afterLoop, bodyStart) }
                else { instrs[loopStart] = .split(bodyStart, afterLoop) }
                if needsCheck { instrs[checkposIdx] = .checkpos(slot, afterLoop) }
            } else {
                let optional = hi! - lo
                if optional > 0 {
                    let slot = numLoopSlots; numLoopSlots += 1
                    var checkposIndices: [Int] = []
                    for _ in 0..<optional {
                        if needsCheck { emit(.markpos(slot)) }
                        compileNode(inner)
                        if needsCheck { checkposIndices.append(emit(.checkpos(slot, 0))) }
                    }
                    let after = instrs.count
                    for idx in checkposIndices { instrs[idx] = .checkpos(slot, after) }
                }
            }
        }
    }

    emit(.save(0))
    compileNode(ast)
    emit(.save(1))
    emit(.match)
    return (instrs, numLoopSlots)
}

func runVM(instrs: [Instr], subject: [UInt8], numGroups: Int, numLoopSlots: Int) -> ((Int, Int)?, [Int?]) {
    let n = subject.count
    let numSlots = 2 * (numGroups + 1)
    let numInstrs = instrs.count

    var memo = [[Bool]](repeating: [Bool](repeating: false, count: n + 1), count: numInstrs)
    var loopPos = [Int](repeating: -1, count: max(numLoopSlots, 1))

    func tryMatch(pc: Int, pos: Int, caps: inout [Int?]) -> Bool {
        if memo[pc][pos] { return false }

        switch instrs[pc] {
        case .match:
            return true
        case .char(let c):
            if pos < n && subject[pos] == c {
                if tryMatch(pc: pc + 1, pos: pos + 1, caps: &caps) { return true }
            }
        case .classM(let s):
            if pos < n && s.contains(subject[pos]) {
                if tryMatch(pc: pc + 1, pos: pos + 1, caps: &caps) { return true }
            }
        case .any:
            if pos < n {
                if tryMatch(pc: pc + 1, pos: pos + 1, caps: &caps) { return true }
            }
        case .start:
            if pos == 0 {
                if tryMatch(pc: pc + 1, pos: pos, caps: &caps) { return true }
            }
        case .end:
            if pos == n {
                if tryMatch(pc: pc + 1, pos: pos, caps: &caps) { return true }
            }
        case .save(let slot):
            let old = caps[slot]
            caps[slot] = pos
            if tryMatch(pc: pc + 1, pos: pos, caps: &caps) { return true }
            caps[slot] = old
        case .markpos(let slot):
            let old = loopPos[slot]
            loopPos[slot] = pos
            if tryMatch(pc: pc + 1, pos: pos, caps: &caps) { return true }
            loopPos[slot] = old
        case .checkpos(let slot, let target):
            if pos == loopPos[slot] {
                if tryMatch(pc: target, pos: pos, caps: &caps) { return true }
            } else {
                if tryMatch(pc: pc + 1, pos: pos, caps: &caps) { return true }
            }
        case .jmp(let target):
            if tryMatch(pc: target, pos: pos, caps: &caps) { return true }
        case .split(let x, let y):
            if tryMatch(pc: x, pos: pos, caps: &caps) { return true }
            if tryMatch(pc: y, pos: pos, caps: &caps) { return true }
        }

        memo[pc][pos] = true
        return false
    }

    for startPos in 0...n {
        var caps = [Int?](repeating: nil, count: numSlots)
        if tryMatch(pc: 0, pos: startPos, caps: &caps) {
            return ((caps[0]!, caps[1]!), caps)
        }
    }

    return (nil, [Int?](repeating: nil, count: numSlots))
}

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]
let filePath = dir + "/cases.txt"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else { exit(1) }

var lines = content.components(separatedBy: "\n")
if lines.last == "" { lines.removeLast() }

for (idx, line) in lines.enumerated() {
    let lineNum = idx + 1
    guard let tabIdx = line.firstIndex(of: "\t") else { continue }
    let pattern = String(line[line.startIndex..<tabIdx])
    let subject = String(line[line.index(after: tabIdx)...])

    var parser = RegexParser(pattern)
    let ast = parser.parse()
    let numGroups = parser.nGroups
    let (instrs, numLoopSlots) = compile(ast, numGroups: numGroups)
    let subBytes = Array(subject.utf8)

    let (match, caps) = runVM(instrs: instrs, subject: subBytes, numGroups: numGroups, numLoopSlots: numLoopSlots)

    if let (s, e) = match {
        var output = "\(lineNum): \(s)-\(e)"
        if numGroups > 0 {
            for i in 1...numGroups {
                if let cs = caps[2*i], let ce = caps[2*i+1] {
                    output += " \(cs)-\(ce)"
                } else {
                    output += " -"
                }
            }
        }
        print(output)
    } else {
        print("\(lineNum): no match")
    }
}

import * as fs from 'fs';
import * as path from 'path';

// AST types
type ASTNode =
  | { type: 'concat'; children: ASTNode[] }
  | { type: 'alt'; alternatives: ASTNode[] }
  | { type: 'quant'; min: number; max: number; lazy: boolean; child: ASTNode }
  | { type: 'group'; index: number | null; child: ASTNode } // null = non-capturing
  | { type: 'char'; value: string }
  | { type: 'any' }
  | { type: 'start_anchor' }
  | { type: 'end_anchor' }
  | { type: 'class'; items: ClassItem[]; negated: boolean }
  | { type: 'empty' };

type ClassItem =
  | { type: 'char'; value: string }
  | { type: 'range'; from: string; to: string }
  | { type: 'escape'; kind: string }; // d, w, s, D, W, S

// Parser
class Parser {
  pattern: string;
  pos: number;
  groupCount: number;

  constructor(pattern: string) {
    this.pattern = pattern;
    this.pos = 0;
    this.groupCount = 0;
  }

  parse(): ASTNode {
    const result = this.parseRegex();
    return result;
  }

  parseRegex(): ASTNode {
    const alternatives: ASTNode[] = [];
    alternatives.push(this.parseBranch());
    while (this.pos < this.pattern.length && this.pattern[this.pos] === '|') {
      this.pos++; // consume '|'
      alternatives.push(this.parseBranch());
    }
    if (alternatives.length === 1) return alternatives[0];
    return { type: 'alt', alternatives };
  }

  parseBranch(): ASTNode {
    const pieces: ASTNode[] = [];
    while (this.pos < this.pattern.length && this.pattern[this.pos] !== '|' && this.pattern[this.pos] !== ')') {
      pieces.push(this.parsePiece());
    }
    if (pieces.length === 0) return { type: 'empty' };
    if (pieces.length === 1) return pieces[0];
    return { type: 'concat', children: pieces };
  }

  parsePiece(): ASTNode {
    const atom = this.parseAtom();
    // Check for quantifier
    if (this.pos < this.pattern.length) {
      const q = this.parseQuantifier();
      if (q) {
        return { type: 'quant', ...q, child: atom };
      }
    }
    return atom;
  }

  parseQuantifier(): { min: number; max: number; lazy: boolean } | null {
    const ch = this.pattern[this.pos];
    let min: number, max: number;
    if (ch === '*') {
      this.pos++;
      min = 0; max = Infinity;
    } else if (ch === '+') {
      this.pos++;
      min = 1; max = Infinity;
    } else if (ch === '?') {
      this.pos++;
      min = 0; max = 1;
    } else if (ch === '{') {
      // Parse {m}, {m,}, {m,n}
      const start = this.pos;
      this.pos++; // consume '{'
      min = this.parseNumber();
      if (this.pos < this.pattern.length && this.pattern[this.pos] === ',') {
        this.pos++;
        if (this.pos < this.pattern.length && this.pattern[this.pos] === '}') {
          max = Infinity;
        } else {
          max = this.parseNumber();
        }
      } else {
        max = min;
      }
      if (this.pos < this.pattern.length && this.pattern[this.pos] === '}') {
        this.pos++;
      } else {
        // Not a valid quantifier, treat '{' as literal
        this.pos = start;
        return null;
      }
    } else {
      return null;
    }
    let lazy = false;
    if (this.pos < this.pattern.length && this.pattern[this.pos] === '?') {
      this.pos++;
      lazy = true;
    }
    return { min, max, lazy };
  }

  parseNumber(): number {
    let num = 0;
    while (this.pos < this.pattern.length && this.pattern[this.pos] >= '0' && this.pattern[this.pos] <= '9') {
      num = num * 10 + (this.pattern[this.pos].charCodeAt(0) - 48);
      this.pos++;
    }
    return num;
  }

  parseAtom(): ASTNode {
    const ch = this.pattern[this.pos];
    if (ch === '(') {
      this.pos++; // consume '('
      if (this.pos < this.pattern.length && this.pattern[this.pos] === '?') {
        this.pos++; // consume '?'
        if (this.pos < this.pattern.length && this.pattern[this.pos] === ':') {
          this.pos++; // consume ':'
          const child = this.parseRegex();
          this.pos++; // consume ')'
          return { type: 'group', index: null, child };
        }
        // Could be other (?...) constructs, but problem only mentions (?:...)
        // Treat (? as start of capturing group? No, let's handle it as non-capturing for safety
        // Actually the problem says only (?:) for non-capturing, and ( for capturing
        // If we see (? without :, it might be something else, but problem guarantees only these forms
        // Let's just treat it as capturing group for safety
        const child = this.parseRegex();
        this.pos++; // consume ')'
        this.groupCount++;
        return { type: 'group', index: this.groupCount, child };
      } else {
        this.groupCount++;
        const child = this.parseRegex();
        this.pos++; // consume ')'
        return { type: 'group', index: this.groupCount, child };
      }
    } else if (ch === '.') {
      this.pos++;
      return { type: 'any' };
    } else if (ch === '^') {
      this.pos++;
      return { type: 'start_anchor' };
    } else if (ch === '$') {
      this.pos++;
      return { type: 'end_anchor' };
    } else if (ch === '[') {
      return this.parseClass();
    } else if (ch === '\\') {
      this.pos++;
      const esc = this.pattern[this.pos];
      this.pos++;
      if ('dDwWsS'.includes(esc)) {
        return { type: 'class', items: [{ type: 'escape', kind: esc }], negated: false };
      } else {
        // Literal escape
        return { type: 'char', value: esc };
      }
    } else {
      // Literal character (not in the special set)
      this.pos++;
      return { type: 'char', value: ch };
    }
  }

  parseClass(): ASTNode {
    this.pos++; // consume '['
    let negated = false;
    if (this.pos < this.pattern.length && this.pattern[this.pos] === '^') {
      negated = true;
      this.pos++;
    }
    const items: ClassItem[] = [];
    // Parse items until ']'
    while (this.pos < this.pattern.length && this.pattern[this.pos] !== ']') {
      // Parse a single item (char, range, or escape)
      const first = this.parseClassChar();
      // Check for range
      if (this.pos < this.pattern.length && this.pattern[this.pos] === '-' && 
          this.pos + 1 < this.pattern.length && this.pattern[this.pos + 1] !== ']') {
        this.pos++; // consume '-'
        const second = this.parseClassChar();
        items.push({ type: 'range', from: first, to: second });
      } else {
        items.push({ type: 'char', value: first });
      }
    }
    this.pos++; // consume ']'
    return { type: 'class', items, negated };
  }

  parseClassChar(): string {
    if (this.pattern[this.pos] === '\\') {
      this.pos++;
      const c = this.pattern[this.pos];
      this.pos++;
      return c;
    } else {
      const c = this.pattern[this.pos];
      this.pos++;
      return c;
    }
  }
}

