#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_INST 10000
#define MAX_CAP 128
#define MAX_THREADS 10000
#define MAX_LEN 200

enum { OP_CHAR, OP_CLASS, OP_DOT, OP_SPLIT, OP_JUMP, OP_SAVE, OP_MATCH, OP_BOL, OP_EOL };

typedef struct {
    int op;
    int a, b;
    unsigned char cb[16];
} Inst;

Inst prog[MAX_INST];
int nprog;
int ngroups;

char pat[MAX_LEN];
int pp, plen;

int visited[MAX_INST];
int gen;

typedef struct {
    int ip;
    int cap[MAX_CAP];
} Thread;

int emit(int op, int a, int b) {
    int i = nprog++;
    prog[i].op = op; prog[i].a = a; prog[i].b = b;
    memset(prog[i].cb, 0, 16);
    return i;
}

int emit_class(unsigned char *bitmap) {
    int i = emit(OP_CLASS, 0, 0);
    memcpy(prog[i].cb, bitmap, 16);
    return i;
}

int parse_alt();
void parse_branch();
void parse_piece();
void parse_atom();

int parse_alt() {
    int split_idx = nprog++; // reserve for SPLIT
    int branch_start = nprog;
    parse_branch();

    if (pp < plen && pat[pp] == '|') {
        pp++; // consume '|'
        int jump_idx = nprog++; // reserve for JUMP
        int rest = parse_alt(); // parse rest
        prog[split_idx].op = OP_SPLIT;
        prog[split_idx].a = branch_start;
        prog[split_idx].b = rest;
        prog[jump_idx].op = OP_JUMP;
        prog[jump_idx].a = nprog;
    } else {
        prog[split_idx].op = OP_JUMP;
        prog[split_idx].a = branch_start;
    }

    return split_idx;
}

void parse_branch() {
    while (pp < plen && pat[pp] != '|' && pat[pp] != ')') {
        parse_piece();
    }
}

void parse_piece() {
    int reserved = nprog++; // reserve for quantifier SPLIT

    int atom_start = nprog;
    parse_atom();
    int atom_end = nprog;
    int atom_len = atom_end - atom_start;

    if (pp < plen && (pat[pp] == '*' || pat[pp] == '+' || pat[pp] == '?' || pat[pp] == '{')) {
        int min, max; // max = -1 for unbounded
        int lazy = 0;

        if (pat[pp] == '*') { min = 0; max = -1; pp++; }
        else if (pat[pp] == '+') { min = 1; max = -1; pp++; }
        else if (pat[pp] == '?') { min = 0; max = 1; pp++; }
        else { // '{'
            pp++;
            min = 0;
            while (pp < plen && pat[pp] >= '0' && pat[pp] <= '9') {
                min = min * 10 + (pat[pp] - '0'); pp++;
            }
            max = min;
            if (pp < plen && pat[pp] == ',') {
                pp++;
                max = -1;
                if (pp < plen && pat[pp] >= '0' && pat[pp] <= '9') {
                    max = 0;
                    while (pp < plen && pat[pp] >= '0' && pat[pp] <= '9') {
                        max = max * 10 + (pat[pp] - '0'); pp++;
                    }
                }
            }
            pp++; // consume '}'
        }

        if (pp < plen && pat[pp] == '?') { lazy = 1; pp++; }

        // Emit mandatory copies beyond the first
        for (int i = 1; i < min; i++) {
            memcpy(&prog[nprog], &prog[atom_start], atom_len * sizeof(Inst));
            nprog += atom_len;
        }

        if (max == -1) {
            // Unbounded: X* after mandatory copies
            int split, body_start;
            if (min == 0) {
                split = reserved;
                body_start = atom_start;
            } else {
                split = nprog++;
                body_start = nprog;
                memcpy(&prog[nprog], &prog[atom_start], atom_len * sizeof(Inst));
                nprog += atom_len;
            }

            int jump_idx = nprog++;
            prog[jump_idx].op = OP_JUMP;
            prog[jump_idx].a = split;

            int exit_pos = nprog;

            if (lazy) {
                prog[split].op = OP_SPLIT;
                prog[split].a = exit_pos;
                prog[split].b = body_start;
            } else {
                prog[split].op = OP_SPLIT;
                prog[split].a = body_start;
                prog[split].b = exit_pos;
            }

            if (min > 0) {
                prog[reserved].op = OP_JUMP;
                prog[reserved].a = atom_start;
            }
        } else {
            // Bounded: (max - min) optional copies
            int opt = max - min;
            for (int i = 0; i < opt; i++) {
                int split, body_start;
                if (i == 0 && min == 0) {
                    split = reserved;
                    body_start = atom_start;
                } else {
                    split = nprog++;
                    body_start = nprog;
                    memcpy(&prog[nprog], &prog[atom_start], atom_len * sizeof(Inst));
                    nprog += atom_len;
                }

                int exit_pos = nprog;

                if (lazy) {
                    prog[split].op = OP_SPLIT;
                    prog[split].a = exit_pos;
                    prog[split].b = body_start;
                } else {
                    prog[split].op = OP_SPLIT;
                    prog[split].a = body_start;
                    prog[split].b = exit_pos;
                }
            }

            if (min == 0 && opt == 0) {
                // X{0,0}: matches nothing
                prog[reserved].op = OP_JUMP;
                prog[reserved].a = nprog;
            } else if (min > 0) {
                prog[reserved].op = OP_JUMP;
                prog[reserved].a = atom_start;
            }
        }
    } else {
        // No quantifier
        prog[reserved].op = OP_JUMP;
        prog[reserved].a = atom_start;
    }
}

void parse_atom() {
    if (pp >= plen) return;

    char c = pat[pp];

    if (c == '(') {
        pp++; // consume '('
        int is_capturing = 1;
        if (pp < plen && pat[pp] == '?') {
            pp++; // consume '?'
            is_capturing = 0;
            // (?: ...) - non-capturing
            // Could also be (?=...) etc but spec says only (?:...)
        }

        int grp = -1;
        if (is_capturing) {
            grp = ngroups++;
            emit(OP_SAVE, 2 * grp, 0); // save start
        }

        parse_alt();

        if (is_capturing) {
            emit(OP_SAVE, 2 * grp + 1, 0); // save end
        }

        pp++; // consume ')'
    } else if (c == '.') {
        pp++;
        emit(OP_DOT, 0, 0);
    } else if (c == '^') {
        pp++;
        emit(OP_BOL, 0, 0);
    } else if (c == '$') {
        pp++;
        emit(OP_EOL, 0, 0);
    } else if (c == '[') {
        pp++; // consume '['
        int negate = 0;
        if (pp < plen && pat[pp] == '^') {
            negate = 1;
            pp++;
        }

        unsigned char bitmap[16];
        memset(bitmap, 0, 16);

        // Parse items
        int first = 1;
        while (pp < plen && (pat[pp] != ']' || first)) {
            first = 0;

            int lo, hi;

            // Parse first character of item
            if (pat[pp] == '\\') {
                pp++;
                char esc = pat[pp];
                pp++;
                if (esc == 'd' || esc == 'D' || esc == 'w' || esc == 'W' || esc == 's' || esc == 'S') {
                    // Class escape
                    unsigned char tmp[16];
                    memset(tmp, 0, 16);
                    if (esc == 'd' || esc == 'D') {
                        for (int ch = '0'; ch <= '9'; ch++) tmp[ch >> 3] |= (1 << (ch & 7));
                    } else if (esc == 'w' || esc == 'W') {
                        for (int ch = '0'; ch <= '9'; ch++) tmp[ch >> 3] |= (1 << (ch & 7));
                        for (int ch = 'a'; ch <= 'z'; ch++) tmp[ch >> 3] |= (1 << (ch & 7));
                        for (int ch = 'A'; ch <= 'Z'; ch++) tmp[ch >> 3] |= (1 << (ch & 7));
                        tmp['_' >> 3] |= (1 << ('_' & 7));
                    } else { // s, S
                        tmp[' ' >> 3] |= (1 << (' ' & 7));
                        tmp['\t' >> 3] |= (1 << ('\t' & 7));
                        tmp['\n' >> 3] |= (1 << ('\n' & 7));
                        tmp['\r' >> 3] |= (1 << ('\r' & 7));
                        tmp['\f' >> 3] |= (1 << ('\f' & 7));
                        tmp['\v' >> 3] |= (1 << ('\v' & 7));
                    }
                    if (esc == 'D' || esc == 'W' || esc == 'S') {
                        for (int i = 0; i < 16; i++) tmp[i] = ~tmp[i];
                        // Mask to only consider printable ASCII? No, the spec says complements match "every character not in the set"
                        // Since we're dealing with ASCII 0-127, let's mask to 128 bits
                        // Actually our bitmap is 128 bits (16 bytes), covering chars 0-127.
                        // For complements, we want all chars NOT in the set.
                        // Since input is printable ASCII (0x20-0x7E), complement of \d includes all printable chars except digits.
                        // Let's just use the full 128-bit complement.
                        for (int i = 0; i < 16; i++) tmp[i] = ~tmp[i];
                        // Clear bit 7 of last byte if needed? No, 16 bytes = 128 bits, covers 0-127.
                    }
                    for (int i = 0; i < 16; i++) bitmap[i] |= tmp[i];
                    continue;
                } else {
                    // Escaped literal
                    lo = hi = (unsigned char)esc;
                }
            } else {
                lo = hi = (unsigned char)pat[pp];
                pp++;
            }

            // Check for range
            if (pp < plen && pat[pp] == '-' && pp + 1 < plen && pat[pp + 1] != ']') {
                pp++; // consume '-'
                if (pat[pp] == '\\') {
                    pp++;
                    hi = (unsigned char)pat[pp];
                    pp++;
                } else {
                    hi = (unsigned char)pat[pp];
                    pp++;
                }
            }

            for (int ch = lo; ch <= hi; ch++) {
                bitmap[ch >> 3] |= (1 << (ch & 7));
            }
        }

        pp++; // consume ']'

        if (negate) {
            for (int i = 0; i < 16; i++) bitmap[i] = ~bitmap[i];
        }

        emit_class(bitmap);
    } else if (c == '\\') {
        pp++;
        char esc = pat[pp];
        pp++;
        if (esc == 'd' || esc == 'w' || esc == 's' || esc == 'D' || esc == 'W' || esc == 'S') {
            unsigned char bitmap[16];
            memset(bitmap, 0, 16);
            if (esc == 'd' || esc == 'D') {
                for (int ch = '0'; ch <= '9'; ch++) bitmap[ch >> 3] |= (1 << (ch & 7));
            } else if (esc == 'w' || esc == 'W') {
                for (int ch = '0'; ch <= '9'; ch++) bitmap[ch >> 3] |= (1 << (ch & 7));
                for (int ch = 'a'; ch <= 'z'; ch++) bitmap[ch >> 3] |= (1 << (ch & 7));
                for (int ch = 'A'; ch <= 'Z'; ch++) bitmap[ch >> 3] |= (1 << (ch & 7));
                bitmap['_' >> 3] |= (1 << ('_' & 7));
            } else {
                bitmap[' ' >> 3] |= (1 << (' ' & 7));
                bitmap['\t' >> 3] |= (1 << ('\t' & 7));
                bitmap['\n' >> 3] |= (1 << ('\n' & 7));
                bitmap['\r' >> 3] |= (1 << ('\r' & 7));
                bitmap['\f' >> 3] |= (1 << ('\f' & 7));
                bitmap['\v' >> 3] |= (1 << ('\v' & 7));
            }
            if (esc == 'D' || esc == 'W' || esc == 'S') {
                for (int i = 0; i < 16; i++) bitmap[i] = ~bitmap[i];
            }
            emit_class(bitmap);
        } else {
            emit(OP_CHAR, (unsigned char)esc, 0);
        }
    } else {
        // Literal character (not a special char)
        // Special chars: \ . [ ] ( ) { } * + ? | ^ $
        // If we reach here, it's a literal
        emit(OP_CHAR, (unsigned char)c, 0);
        pp++;
    }
}

