import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';

interface ContentBlock {
  type: string;
  thinking: string;
  signature: string;
  text: string;
  id: string;
  name: string;
  inputJson: string;
  input: any;
}

interface Reply {
  blocks: ContentBlock[];
  stopReason: string;
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
}

interface ApiError {
  status: number;
  type: string;
  message: string;
}

function escapeString(s: string): string {
  let result = '';
  for (const ch of s) {
    switch (ch) {
      case '\\': result += '\\\\'; break;
      case '\n': result += '\\n'; break;
      case '\r': result += '\\r'; break;
      case '\t': result += '\\t'; break;
      default: result += ch; break;
    }
  }
  return result;
}

function executeTool(name: string, input: any): { result: string; isError: boolean } {
  if (name === 'measure') {
    const text = String(input.text ?? '');
    const unit = String(input.unit ?? '');
    if (unit === 'code_points') {
      return { result: String([...text].length), isError: false };
    } else if (unit === 'utf8_bytes') {
      return { result: String(Buffer.byteLength(text, 'utf-8')), isError: false };
    } else if (unit === 'utf16_units') {
      return { result: String(text.length), isError: false };
    } else {
      return { result: `unsupported unit: ${unit}`, isError: true };
    }
  } else if (name === 'reverse') {
    const text = String(input.text ?? '');
    return { result: [...text].reverse().join(''), isError: false };
  } else {
    return { result: `unknown tool: ${name}`, isError: true };
  }
}

function makeRequest(baseUrl: string, apiKey: string, body: any): Promise<Reply | ApiError> {
  return new Promise((resolve) => {
    const url = new URL(baseUrl + '/v1/messages');
    const bodyStr = JSON.stringify(body);
    const bodyBuf = Buffer.from(bodyStr, 'utf-8');

    const options: http.RequestOptions = {
      hostname: url.hostname,
      port: url.port ? parseInt(url.port) : 80,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Host': url.host,
        'Content-Length': String(bodyBuf.length),
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
    };

    const req = http.request(options, (res) => {
      if (res.statusCode !== 200) {
        let data = '';
        res.setEncoding('utf-8');
        res.on('data', (chunk) => { data += chunk; });
        res.on('end', () => {
          try {
            const err = JSON.parse(data);
            resolve({
              status: res.statusCode!,
              type: err.error?.type || 'unknown',
              message: err.error?.message || '',
            });
          } catch {
            resolve({ status: res.statusCode!, type: 'unknown', message: data });
          }
        });
        return;
      }

      // SSE parsing with raw byte buffer to handle split multi-byte chars
      let buffer: Buffer = Buffer.alloc(0);
      let eventType = '';
      let dataLines: string[] = [];

      const blocks = new Map<number, ContentBlock>();
      let stopReason = '';
      let inputTokens = 0;
      let outputTokens = 0;
      let cacheReadTokens = 0;

      function processBuffer() {
        while (true) {
          const lfIndex = buffer.indexOf(0x0A);
          if (lfIndex === -1) break;

          let lineBytes: Buffer;
          if (lfIndex > 0 && buffer[lfIndex - 1] === 0x0D) {
            lineBytes = buffer.slice(0, lfIndex - 1);
          } else {
            lineBytes = buffer.slice(0, lfIndex);
          }
          buffer = buffer.slice(lfIndex + 1);

          const line = lineBytes.toString('utf-8');
          processLine(line);
        }
      }

      function processLine(line: string) {
        if (line === '') {
          // Blank line dispatches the event
          if (eventType || dataLines.length > 0) {
            handleEvent(eventType, dataLines.join('\n'));
            eventType = '';
            dataLines = [];
          }
          return;
        }

        if (line.startsWith(':')) {
          return; // comment
        }

        if (line.startsWith('event:')) {
          let value = line.slice(6);
          if (value.startsWith(' ')) value = value.slice(1);
          eventType = value;
        } else if (line.startsWith('data:')) {
          let value = line.slice(5);
          if (value.startsWith(' ')) value = value.slice(1);
          dataLines.push(value);
        }
      }

      function handleEvent(event: string, data: string) {
        let obj: any;
        try {
          obj = JSON.parse(data);
        } catch {
          return;
        }

        switch (obj.type) {
          case 'message_start':
            if (obj.message?.usage) {
              inputTokens += obj.message.usage.input_tokens || 0;
              cacheReadTokens += obj.message.usage.cache_read_input_tokens || 0;
            }
            break;

          case 'content_block_start': {
            const cb = obj.content_block;
            blocks.set(obj.index, {
              type: cb.type,
              thinking: '',
              signature: '',
              text: '',
              id: cb.id || '',
              name: cb.name || '',
              inputJson: '',
              input: {},
            });
            break;
          }

          case 'content_block_delta': {
            const b = blocks.get(obj.index);
            if (!b || !obj.delta) break;
            const d = obj.delta;
            if (d.type === 'thinking_delta') {
              b.thinking += d.thinking || '';
            } else if (d.type === 'signature_delta') {
              b.signature += d.signature || '';
            } else if (d.type === 'text_delta') {
              b.text += d.text || '';
            } else if (d.type === 'input_json_delta') {
              b.inputJson += d.partial_json || '';
            }
            break;
          }

          case 'content_block_stop': {
            const b = blocks.get(obj.index);
            if (b && b.type === 'tool_use') {
              try {
                b.input = JSON.parse(b.inputJson || '{}');
              } catch {
                b.input = {};
              }
            }
            break;
          }

          case 'message_delta':
            if (obj.delta?.stop_reason) {
              stopReason = obj.delta.stop_reason;
            }
            if (obj.usage?.output_tokens !== undefined) {
              outputTokens += obj.usage.output_tokens;
            }
            break;

          case 'message_stop':
            break;

          default:
            // ping, etc. - ignore
            break;
        }
      }

      res.on('data', (chunk: Buffer) => {
        buffer = Buffer.concat([buffer, chunk]);
        processBuffer();
      });

      res.on('end', () => {
        processBuffer();
        const sortedIndices = [...blocks.keys()].sort((a, b) => a - b);
        const sortedBlockList = sortedIndices.map(i => blocks.get(i)!);
        resolve({
          blocks: sortedBlockList,
          stopReason,
          inputTokens,
          outputTokens,
          cacheReadTokens,
        });
      });
    });

    req.on('error', (err) => {
      resolve({ status: 0, type: 'connection_error', message: err.message });
    });

    req.write(bodyBuf);
    req.end();
  });
}

async function main() {
  const args = process.argv.slice(2);
  const dataDir = args[0];
  const baseUrl = args[1];

  const requestJson = JSON.parse(fs.readFileSync(path.join(dataDir, 'request.json'), 'utf-8'));
  const { api_key, model, max_tokens, thinking_budget, system, prompt, tools } = requestJson;

  // Build request 1 body
  const body1 = {
    model,
    max_tokens,
    stream: true,
    thinking: { type: 'enabled', budget_tokens: thinking_budget },
    system,
    tools,
    messages: [{ role: 'user', content: prompt }],
  };

  // Request 1
  console.log('request 1');
  const reply1 = await makeRequest(baseUrl, api_key, body1);

  if ('status' in reply1) {
    console.log(`ERROR ${reply1.status} ${reply1.type}: ${reply1.message}`);
    process.exit(0);
  }

  // Print blocks from reply 1
  for (const block of reply1.blocks) {
    if (block.type === 'thinking') {
      console.log(`thinking ${escapeString(block.thinking)}`);
      console.log(`signature ${escapeString(block.signature)}`);
    } else if (block.type === 'text') {
      console.log(`text ${escapeString(block.text)}`);
    } else if (block.type === 'tool_use') {
      console.log(`tool_use ${block.id} ${block.name} ${escapeString(block.inputJson)}`);
    }
  }
  console.log(`stop_reason ${reply1.stopReason}`);

  // Execute tools and print results
  const toolResults: Array<{ tool_use_id: string; content: string; is_error: boolean }> = [];
  for (const block of reply1.blocks) {
    if (block.type === 'tool_use') {
      const { result, isError } = executeTool(block.name, block.input);
      if (isError) {
        console.log(`error ${block.id} ${escapeString(result)}`);
      } else {
        console.log(`result ${block.id} ${escapeString(result)}`);
      }
      toolResults.push({ tool_use_id: block.id, content: result, is_error: isError });
    }
  }

  // Build assistant content blocks for request 2
  const assistantContent: any[] = [];
  for (const block of reply1.blocks) {
    if (block.type === 'thinking') {
      assistantContent.push({ type: 'thinking', thinking: block.thinking, signature: block.signature });
    } else if (block.type === 'text') {
      assistantContent.push({ type: 'text', text: block.text });
    } else if (block.type === 'tool_use') {
      assistantContent.push({ type: 'tool_use', id: block.id, name: block.name, input: block.input });
    }
  }

  // Build tool result content
  const toolResultContent: any[] = [];
  for (const tr of toolResults) {
    const block: any = { type: 'tool_result', tool_use_id: tr.tool_use_id, content: tr.content };
    if (tr.is_error) block.is_error = true;
    toolResultContent.push(block);
  }

  // Build request 2 body
  const body2 = {
    model,
    max_tokens,
    stream: true,
    thinking: { type: 'enabled', budget_tokens: thinking_budget },
    system,
    tools,
    messages: [
      { role: 'user', content: prompt },
      { role: 'assistant', content: assistantContent },
      { role: 'user', content: toolResultContent },
    ],
  };

  // Request 2
  console.log('request 2');
  const reply2 = await makeRequest(baseUrl, api_key, body2);

  if ('status' in reply2) {
    console.log(`ERROR ${reply2.status} ${reply2.type}: ${reply2.message}`);
    process.exit(0);
  }

  // Print blocks from reply 2
  for (const block of reply2.blocks) {
    if (block.type === 'thinking') {
      console.log(`thinking ${escapeString(block.thinking)}`);
      console.log(`signature ${escapeString(block.signature)}`);
    } else if (block.type === 'text') {
      console.log(`text ${escapeString(block.text)}`);
    } else if (block.type === 'tool_use') {
      console.log(`tool_use ${block.id} ${block.name} ${escapeString(block.inputJson)}`);
    }
  }
  console.log(`stop_reason ${reply2.stopReason}`);

  // Print usage
  const totalInput = reply1.inputTokens + reply2.inputTokens;
  const totalOutput = reply1.outputTokens + reply2.outputTokens;
  const totalCacheRead = reply1.cacheReadTokens + reply2.cacheReadTokens;
  console.log(`usage input=${totalInput} output=${totalOutput} cache_read=${totalCacheRead}`);
}

main();

import sys
import json
import csv
import io
import os
import urllib.request
import urllib.error
from urllib.parse import urlparse


def parse_csv(filepath):
    with open(filepath, 'rb') as f:
        raw = f.read()
    if raw.startswith(b'\xef\xbb\xbf'):
        raw = raw[3:]
    text = raw.decode('utf-8')
    reader = csv.reader(io.StringIO(text, newline=''))
    rows = list(reader)
    return rows


def json_escape_string(s):
    result = []
    for ch in s:
        cp = ord(ch)
        if ch == '"':
            result.append('\\"')
        elif ch == '\\':
            result.append('\\\\')
        elif ch == '\x08':
            result.append('\\b')
        elif ch == '\x0c':
            result.append('\\f')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
            result.append('\\t')
        elif cp < 0x20:
            result.append('\\u%04x' % cp)
        else:
            result.append(ch)
    return ''.join(result)


def serialize_result(d):
    parts = ['{']
    for i, (k, v) in enumerate(d.items()):
        if i > 0:
            parts.append(',')
        parts.append('"' + json_escape_string(k) + '"')
        parts.append(':')
        if isinstance(v, int):
            parts.append(str(v))
        elif isinstance(v, str):
            parts.append('"' + json_escape_string(v) + '"')
    parts.append('}')
    return ''.join(parts)


def execute_tool(name, args, inventory_dict, rates):
    if name == 'inventory_lookup':
        sku = args['sku']
        if sku in inventory_dict:
            row = inventory_dict[sku]
            result = {
                'sku': row['sku'],
                'name': row['name'],
                'price_cents': row['price_cents'],
                'currency': row['currency'],
                'stock': row['stock'],
            }
            return serialize_result(result)
        else:
            return serialize_result({'error': 'unknown sku: ' + sku})
    elif name == 'convert_currency':
        amount = args['amount_cents']
        from_c = args['from']
        to_c = args['to']
        rate_from = rates[from_c]
        rate_to = rates[to_c]
        converted = (2 * amount * rate_to + rate_from) // (2 * rate_from)
        return serialize_result({'amount_cents': converted, 'currency': to_c})
    else:
        return serialize_result({'error': 'unknown tool: ' + name})


def main():
    data_dir = sys.argv[1]
    base_url = sys.argv[2]

    with open(os.path.join(data_dir, 'task.json'), 'r', encoding='utf-8') as f:
        task = json.load(f)

    api_key = task['api_key']
    model = task['model']
    system_msg = task['system']
    user_msg = task['user']
    tools = task['tools']

    rows = parse_csv(os.path.join(data_dir, 'inventory.csv'))
    inventory_dict = {}
    for row in rows[1:]:
        if len(row) >= 5:
            inventory_dict[row[0]] = {
                'sku': row[0],
                'name': row[1],
                'price_cents': int(row[2]),
                'currency': row[3],
                'stock': int(row[4]),
            }

    with open(os.path.join(data_dir, 'rates.json'), 'r', encoding='utf-8') as f:
        rates_data = json.load(f)
    rates = rates_data['rates']

    messages = [
        {"role": "system", "content": system_msg},
        {"role": "user", "content": user_msg},
    ]

    total_prompt = 0
    total_completion = 0
    total_total = 0
    num_requests = 0
    output_lines = []

    url = base_url + "/chat/completions"
    parsed_url = urlparse(url)
    host = parsed_url.hostname
    port = parsed_url.port
    host_header = host if port is None else f"{host}:{port}"

    while True:
        body_obj = {
            "model": model,
            "messages": messages,
            "tools": tools,
            "tool_choice": "auto",
        }
        body_str = json.dumps(body_obj, ensure_ascii=False)
        body_bytes = body_str.encode('utf-8')

        req = urllib.request.Request(
            url,
            data=body_bytes,
            headers={
                'Authorization': 'Bearer ' + api_key,
                'Content-Type': 'application/json',
                'Host': host_header,
                'Content-Length': str(len(body_bytes)),
            },
            method='POST',
        )

        try:
            resp = urllib.request.urlopen(req)
            status = resp.getcode()
        except urllib.error.HTTPError as e:
            status = e.code
            resp = e

        num_requests += 1
        resp_body = resp.read().decode('utf-8')
        resp_json = json.loads(resp_body)

        if status != 200:
            error_msg = resp_json.get('error', {}).get('message', '')
            for line in output_lines:
                print(line)
            print(f"ERROR {status} {error_msg}")
            sys.exit(0)

        usage = resp_json.get('usage', {})
        total_prompt += usage.get('prompt_tokens', 0)
        total_completion += usage.get('completion_tokens', 0)
        total_total += usage.get('total_tokens', 0)

        choice = resp_json['choices'][0]
        finish_reason = choice['finish_reason']
        msg = choice['message']

        if finish_reason == 'tool_calls':
            content = msg.get('content')
            if isinstance(content, str):
                output_lines.append(f"SAY {content}")

            tool_calls = msg['tool_calls']

            assistant_msg = {"role": "assistant", "content": content, "tool_calls": tool_calls}
            messages.append(assistant_msg)

            for tc in tool_calls:
                call_id = tc['id']
                func_name = tc['function']['name']
                output_lines.append(f"CALL {call_id} {func_name}")

            for tc in tool_calls:
                call_id = tc['id']
                func_name = tc['function']['name']
                args_str = tc['function']['arguments']
                args = json.loads(args_str)
                result_str = execute_tool(func_name, args, inventory_dict, rates)
                output_lines.append(f"RESULT {call_id} {result_str}")
                messages.append({
                    "role": "tool",
                    "tool_call_id": call_id,
                    "content": result_str,
                })

        elif finish_reason == 'stop':
            content = msg.get('content', '')
            output_lines.append(f"FINAL {content}")
            break

    for line in output_lines:
        print(line)
    print(f"USAGE prompt={total_prompt} completion={total_completion} total={total_total} requests={num_requests}")
    sys.exit(0)


if __name__ == '__main__':
    main()

fn run(instructions, text) -> Option<(usize, Vec<Option<(usize, usize)>>)> {
    let n_caps = count_capture_groups;
    let mut memo: HashMap<(usize, usize), Option<(usize, Vec<Option<(usize, usize)>)>>> = HashMap::new();
    // memo[(pc, pos)] = Some((end_pos, captures_delta)) or None (failed)

    // Try each starting position
    for start in 0..=text.len() {
        let captures = vec![None; n_caps];
        if let Some((end, caps)) = match_from(instructions, 0, start, captures, &mut memo) {
            return Some((start, end, caps));
        }
    }
    None
}

fn match_from(instructions, pc, pos, captures, memo) -> Option<(usize, Vec<Option<(usize, usize)>)>> {
    let key = (pc, pos);
    if let Some(result) = memo.get(&key) {
        // Apply cached result
        if let Some((end, delta)) = result {
            let mut new_caps = captures.clone();
            for i in 0..delta.len() {
                if delta[i].is_some() {
                    new_caps[i] = delta[i];
                }
            }
            return Some((end, new_caps));
        } else {
            return None;
        }
    }

    // Try to match
    let result = match instructions[pc] {
        Match => Some((pos, vec![None; n_caps])),
        Char(c) => {
            if pos < text.len() && text[pos] == c {
                match_from(instructions, pc+1, pos+1, captures, memo)
            } else {
                None
            }
        }
        // ... etc
    };

    memo.insert(key, result.as_ref().map(|(end, caps)| {
        // Compute delta: captures that were set by this continuation
        let mut delta = vec![None; n_caps];
        for i in 0..caps.len() {
            if caps[i] != captures[i] {
                delta[i] = caps[i];
            }
        }
        (*end, delta)
    }));

    result
}

use std::collections::HashMap;
use std::env;
use std::fs;

#[derive(Clone, Debug)]
enum ClassItem {
    Ch(u8),
    Range(u8, u8),
    Digit,
    DigitNeg,
    Word,
    WordNeg,
    Space,
    SpaceNeg,
}

#[derive(Clone, Debug)]
enum AST {
    Empty,
    Char(u8),
    Any,
    Class(Vec<ClassItem>, bool),
    Group(Box<AST>, Option<usize>),
    Concat(Vec<AST>),
    Alt(Vec<AST>),
    Repeat(Box<AST>, usize, usize, bool),
    Start,
    End,
}

#[derive(Clone, Debug)]
enum Inst {
    Char(u8),
    Any,
    Class(Vec<ClassItem>, bool),
    Split(usize, usize),
    Jump(usize),
    Save(usize),
    Match,
    AssertStart,
    AssertEnd,
    Fail,
}

fn matches_class(items: &[ClassItem], negated: bool, c: u8) -> bool {
    let m = items.iter().any(|item| match item {
        ClassItem::Ch(ch) => c == *ch,
        ClassItem::Range(lo, hi) => c >= *lo && c <= *hi,
        ClassItem::Digit => c.is_ascii_digit(),
        ClassItem::DigitNeg => !c.is_ascii_digit(),
        ClassItem::Word => c.is_ascii_alphanumeric() || c == b'_',
        ClassItem::WordNeg => !(c.is_ascii_alphanumeric() || c == b'_'),
        ClassItem::Space => matches!(c, b' ' | b'\t' | b'\n' | b'\r' | b'\x0c' | b'\x0b'),
        ClassItem::SpaceNeg => !matches!(c, b' ' | b'\t' | b'\n' | b'\r' | b'\x0c' | b'\x0b'),
    });
    if negated { !m } else { m }
}

struct Parser<'a> {
    chars: &'a [u8],
    pos: usize,
    n_groups: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { chars: s.as_bytes(), pos: 0, n_groups: 0 }
    }

    fn peek(&self) -> Option<u8> {
        if self.pos < self.chars.len() { Some(self.chars[self.pos]) } else { None }
    }

    fn eat(&mut self) -> Option<u8> {
        let c = self.peek();
        if c.is_some() { self.pos += 1; }
        c
    }

    fn parse_regex(&mut self) -> AST {
        let mut branches = vec![self.parse_branch()];
        while self.peek() == Some(b'|') {
            self.eat();
            branches.push(self.parse_branch());
        }
        if branches.len() == 1 { branches.pop().unwrap() } else { AST::Alt(branches) }
    }

    fn parse_branch(&mut self) -> AST {
        let mut pieces = vec![];
        while let Some(c) = self.peek() {
            if c == b'|' || c == b')' { break; }
            pieces.push(self.parse_piece());
        }
        if pieces.is_empty() { AST::Empty }
        else if pieces.len() == 1 { pieces.pop().unwrap() }
        else { AST::Concat(pieces) }
    }

    fn parse_piece(&mut self) -> AST {
        let atom = self.parse_atom();
        if let Some((min, max, greedy)) = self.parse_quantifier() {
            AST::Repeat(Box::new(atom), min, max, greedy)
        } else {
            atom
        }
    }

    fn parse_quantifier(&mut self) -> Option<(usize, usize, bool)> {
        let (min, max) = match self.peek() {
            Some(b'*') => { self.eat(); (0, usize::MAX) }
            Some(b'+') => { self.eat(); (1, usize::MAX) }
            Some(b'?') => { self.eat(); (0, 1) }
            Some(b'{') => {
                let save_pos = self.pos;
                self.eat();
                let m = self.parse_number();
                let n = if self.peek() == Some(b',') {
                    self.eat();
                    if self.peek() == Some(b'}') { usize::MAX } else { self.parse_number() }
                } else { m };
                if self.peek() == Some(b'}') {
                    self.eat();
                    (m, n)
                } else {
                    self.pos = save_pos;
                    return None;
                }
            }
            _ => return None,
        };
        let greedy = if self.peek() == Some(b'?') {
            self.eat();
            false
        } else {
            true
        };
        Some((min, max, greedy))
    }

    fn parse_number(&mut self) -> usize {
        let mut n = 0usize;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                n = n * 10 + (c - b'0') as usize;
                self.eat();
            } else { break; }
        }
        n
    }

    fn parse_atom(&mut self) -> AST {
        match self.eat() {
            Some(b'(') => {
                if self.peek() == Some(b'?') && self.pos + 1 < self.chars.len() && self.chars[self.pos + 1] == b':' {
                    self.eat(); self.eat();
                    let body = self.parse_regex();
                    self.eat();
                    AST::Group(Box::new(body), None)
                } else {
                    self.n_groups += 1;
                    let gn = self.n_groups;
                    let body = self.parse_regex();
                    self.eat();
                    AST::Group(Box::new(body), Some(gn))
                }
            }
            Some(b'.') => AST::Any,
            Some(b'^') => AST::Start,
            Some(b'$') => AST::End,
            Some(b'[') => self.parse_class(),
            Some(b'\\') => self.parse_escape(),
            Some(c) => AST::Char(c),
            None => AST::Empty,
        }
    }

    fn parse_escape(&mut self) -> AST {
        match self.eat() {
            Some(b'd') => AST::Class(vec![ClassItem::Digit], false),
            Some(b'D') => AST::Class(vec![ClassItem::DigitNeg], false),
            Some(b'w') => AST::Class(vec![ClassItem::Word], false),
            Some(b'W') => AST::Class(vec![ClassItem::WordNeg], false),
            Some(b's') => AST::Class(vec![ClassItem::Space], false),
            Some(b'S') => AST::Class(vec![ClassItem::SpaceNeg], false),
            Some(c) => AST::Char(c),
            None => AST::Empty,
        }
    }

    fn parse_class(&mut self) -> AST {
        let negated = if self.peek() == Some(b'^') {
            self.eat();
            true
        } else {
            false
        };
        let mut items = vec![];
        loop {
            match self.peek() {
                Some(b']') => { self.eat(); break; }
                Some(b'\\') => {
                    self.eat();
                    match self.eat() {
                        Some(b'd') => items.push(ClassItem::Digit),
                        Some(b'D') => items.push(ClassItem::DigitNeg),
                        Some(b'w') => items.push(ClassItem::Word),
                        Some(b'W') => items.push(ClassItem::WordNeg),
                        Some(b's') => items.push(ClassItem::Space),
                        Some(b'S') => items.push(ClassItem::SpaceNeg),
                        Some(c) => {
                            if self.peek() == Some(b'-') && self.pos + 1 < self.chars.len() && self.chars[self.pos + 1] != b']' {
                                self.eat();
                                let end = self.parse_class_char();
                                items.push(ClassItem::Range(c, end));
                            } else {
                                items.push(ClassItem::Ch(c));
                            }
                        }
                        None => break,
                    }
                }
                Some(c) => {
                    self.eat();
                    if self.peek() == Some(b'-') && self.pos + 1 < self.chars.len() && self.chars[self.pos + 1] != b']' {
                        self.eat();
                        let end = self.parse_class_char();
                        items.push(ClassItem::Range(c, end));
                    } else {
                        items.push(ClassItem::Ch(c));
                    }
                }
                None => break,
            }
        }
        AST::Class(items, negated)
    }

    fn parse_class_char(&mut self) -> u8 {
        if self.peek() == Some(b'\\') {
            self.eat();
            self.eat().unwrap_or(0)
        } else {
            self.eat().unwrap_or(0)
        }
    }
}

fn count_insts(ast: &AST, max_iter: usize) -> usize {
    match ast {
        AST::Empty => 0,
        AST::Char(_) | AST::Any | AST::Class(_, _) => 1,
        AST::Group(body, cap) => {
            let c = if cap.is_some() { 2 } else { 0 };
            c + count_insts(body, max_iter)
        }
        AST::Concat(parts) => parts.iter().map(|p| count_insts(p, max_iter)).sum(),
        AST::Alt(branches) => {
            let total: usize = branches.iter().map(|b| count_insts(b, max_iter)).sum();
            total + (branches.len() - 1) * 2
        }
        AST::Repeat(body, min, max, _) => {
            let mx = if *max == usize::MAX { max_iter } else { *max };
            if *min > mx { return 1; }
            let bl = count_insts(body, max_iter);
            *min * bl + (mx - *min) * (1 + bl)
        }
        AST::Start | AST::End => 1,
    }
}

fn compile(ast: &AST, insts: &mut Vec<Inst>, max_iter: usize) {
    match ast {
        AST::Empty => {}
        AST::Char(c) => insts.push(Inst::Char(*c)),
        AST::Any => insts.push(Inst::Any),
        AST::Class(items, neg) => insts.push(Inst::Class(items.clone(), *neg)),
        AST::Group(body, cap) => {
            if let Some(n) = cap {
                insts.push(Inst::Save(2 * n));
                compile(body, insts, max_iter);
                insts.push(Inst::Save(2 * n + 1));
            } else {
                compile(body, insts, max_iter);
            }
        }
        AST::Concat(parts) => {
            for p in parts { compile(p, insts, max_iter); }
        }
        AST::Alt(branches) => {
            compile_alt(branches, insts, max_iter);
        }
        AST::Repeat(body, min, max, greedy) => {
            let mx = if *max == usize::MAX { max_iter } else { *max };
            if *min > mx {
                insts.push(Inst::Fail);
                return;
            }
            for _ in 0..*min {
                compile(body, insts, max_iter);
            }
            let n_opt = mx - *min;
            if n_opt > 0 {
                let body_len = count_insts(body, max_iter);
                let stop_pos = insts.len() + n_opt * (1 + body_len);
                for _ in 0..n_opt {
                    let body_start = insts.len() + 1;
                    if *greedy {
                        insts.push(Inst::Split(body_start, stop_pos));
                    } else {
                        insts.push(Inst::Split(stop_pos, body_start));
                    }
                    compile(body, insts, max_iter);
                }
            }
        }
        AST::Start => insts.push(Inst::AssertStart),
        AST::End => insts.push(Inst::AssertEnd),
    }
}

fn compile_alt(branches: &[AST], insts: &mut Vec<Inst>, max_iter: usize) {
    if branches.len() == 1 {
        compile(&branches[0], insts, max_iter);
        return;
    }
    let n = branches.len();
    let sizes: Vec<usize> = branches.iter().map(|b| count_insts(b, max_iter)).collect();
    let total_size: usize = sizes.iter().sum::<usize>() + 2 * (n - 1);
    let end_pos = insts.len() + total_size;
    let mut cur = insts.len();
    for i in 0..n {
        if i < n - 1 {
            let branch_start = cur + 1;
            let next_alt = branch_start + sizes[i] + 1;
            insts.push(Inst::Split(branch_start, next_alt));
            cur += 1;
            compile(&branches[i], insts, max_iter);
            cur += sizes[i];
            insts.push(Inst::Jump(end_pos));
            cur += 1;
        } else {
            compile(&branches[i], insts, max_iter);
            cur += sizes[i];
        }
    }
}

fn solve(pc: usize, pos: usize, insts: &[Inst], text: &[u8], memo: &mut HashMap<(usize, usize), Option<usize>>) -> Option<usize> {
    let key = (pc, pos);
    if let Some(&r) = memo.get(&key) {
        return r;
    }
    let result = match &insts[pc] {
        Inst::Match => Some(pos),
        Inst::Fail => None,
        Inst::Char(c) => {
            if pos < text.len() && text[pos] == *c {
                solve(pc + 1, pos + 1, insts, text, memo)
            } else { None }
        }
        Inst::Any => {
            if pos < text.len() {
                solve(pc + 1, pos + 1, insts, text, memo)
            } else { None }
        }
        Inst::Class(items, neg) => {
            if pos < text.len() && matches_class(items, *neg, text[pos]) {
                solve(pc + 1, pos + 1, insts, text, memo)
            } else { None }
        }
        Inst::Split(l1, l2) => {
            let r1 = solve(*l1, pos, insts, text, memo);
            if r1.is_some() { r1 } else { solve(*l2, pos, insts, text, memo) }
        }
        Inst::Jump(l) => solve(*l, pos, insts, text, memo),
        Inst::Save(_) => solve(pc + 1, pos, insts, text, memo),
        Inst::AssertStart => {
            if pos == 0 { solve(pc + 1, pos, insts, text, memo) } else { None }
        }
        Inst::AssertEnd => {
            if pos == text.len() { solve(pc + 1, pos, insts, text, memo) } else { None }
        }
    };
    memo.insert(key, result);
    result
}

fn find_captures(pc: usize, pos: usize, insts: &[Inst], memo: &HashMap<(usize, usize), Option<usize>>, n_caps: usize) -> Vec<Option<(usize, usize)>> {
    let total_slots = n_caps * 2;
    let mut slots = vec![None; total_slots];
    let mut cur_pc = pc;
    let mut cur_pos = pos;
    loop {
        match &insts[cur_pc] {
            Inst::Match | Inst::Fail => break,
            Inst::Char(_) | Inst::Any | Inst::Class(_, _) => {
                cur_pc += 1;
                cur_pos += 1;
            }
            Inst::Split(l1, l2) => {
                if let Some(Some(_)) = memo.get(&(*l1, cur_pos)) {
                    cur_pc = *l1;
                } else {
                    cur_pc = *l2;
                }
            }
            Inst::Jump(l) => { cur_pc = *l; }
            Inst::Save(slot) => {
                slots[*slot] = Some(cur_pos);
                cur_pc += 1;
            }
            Inst::AssertStart | Inst::AssertEnd => { cur_pc += 1; }
        }
    }
    (0..n_caps).map(|i| {
        match (slots[2 * i], slots[2 * i + 1]) {
            (Some(s), Some(e)) => Some((s, e)),
            _ => None,
        }
    }).collect()
}

fn search(insts: &[Inst], text: &[u8], n_caps: usize) -> Option<(usize, usize, Vec<Option<(usize, usize)>)> {
    let len = text.len();
    let mut memo: HashMap<(usize, usize), Option<usize>> = HashMap::new();
    for start in 0..=len {
        if let Some(end) = solve(0, start, insts, text, &mut memo) {
            let captures = find_captures(0, start, insts, &memo, n_caps);
            return Some((start, end, captures));
        }
    }
    None
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/cases.txt", dir)).unwrap();

    for (i, line) in content.lines().enumerate() {
        let tab_pos = line.find('\t').unwrap();
        let pattern = &line[..tab_pos];
        let subject = &line[tab_pos + 1..];

        let mut parser = Parser::new(pattern);
        let ast = parser.parse_regex();
        let n_caps = parser.n_groups;

        let max_iter = subject.len() + 1;
        let mut insts = vec![];
        compile(&ast, &mut insts, max_iter);
        insts.push(Inst::Match);

        let result = search(&insts, subject.as_bytes(), n_caps);

        match result {
            Some((start, end, captures)) => {
                print!("{}: {}-{}", i + 1, start, end);
                for cap in &captures {
                    match cap {
                        Some((s, e)) => print!(" {}-{}", s, e),
                        None => print!(" -"),
                    }
                }
                println!();
            }
            None => println!("{}: no match", i + 1),
        }
    }
}

