    }

    var first = true
    for table in tables {
        if !first { print("") }
        first = false

        let columns = parseColumns(sql: table.sql)
        let rows = walkTableBTree(data, table.rootPage, pageSize, reserved)

        print("TABLE \(table.name) rows=\(rows.count)")
