        Map<String, Object> body2 = new LinkedHashMap<>();
        body2.put("model", model);
        body2.put("max_tokens", maxTokens);
        body2.put("stream", true);
        Map<String, Object> th2 = new LinkedHashMap<>();
        th2.put("type", "enabled");
        th2.put("budget_tokens", thinkingBudget);
        body2.put("thinking", th2);
        body2.put("system", system);
        body2.put("tools", tools);
        body2.put("messages", messages2);

        System.out.println("request 2");
        HttpResponse resp2 = sendRequest(host, port, path, apiKey, toJson(body2));
        if (resp2.status != 200) {
            Map<String, Object> eb = (Map<String, Object>) new JsonParser(resp2.body).parse();
            Map<String, Object> er = (Map<String, Object>) eb.get("error");
            System.out.println("ERROR " + resp2.status + " " + er.get("type") + ": " + er.get("message"));
            return;
