import java.io.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {

    static final int JNULL=0, JBOOL=1, JNUM=2, JSTR=3, JOBJ=4, JARR=5;

    static class JV {
        int type;
        boolean b;
        double num;
        String numRaw;
        String str;
        String raw;
        ArrayList<Map.Entry<String,JV>> obj;
        ArrayList<JV> arr;
    }

    static class JP {
        String s; int p;
        JP(String s){this.s=s;p=0;}
        JV parse(){ws();return val();}
        void ws(){while(p<s.length()&&(s.charAt(p)==' '||s.charAt(p)=='\t'||s.charAt(p)=='\n'||s.charAt(p)=='\r'))p++;}
        JV val(){
            ws();char c=s.charAt(p);
            if(c=='{')return obj();if(c=='[')return arr();if(c=='"')return str();
            if(c=='t'){p+=4;JV v=new JV();v.type=JBOOL;v.b=true;return v;}
            if(c=='f'){p+=5;JV v=new JV();v.type=JBOOL;v.b=false;return v;}
            if(c=='n'){p+=4;JV v=new JV();v.type=JNULL;return v;}
            return num();
        }
        JV str(){
            p++;int start=p;StringBuilder sb=new StringBuilder();
            while(p<s.length()){
                char c=s.charAt(p);
                if(c=='"'){JV v=new JV();v.type=JSTR;v.str=sb.toString();v.raw=s.substring(start,p);p++;return v;}
                if(c=='\\'){p++;char e=s.charAt(p);
                    switch(e){
                        case '"':sb.append('"');p++;break;
                        case '\\':sb.append('\\');p++;break;
                        case '/':sb.append('/');p++;break;
                        case 'b':sb.append('\b');p++;break;
                        case 'f':sb.append('\f');p++;break;
                        case 'n':sb.append('\n');p++;break;
                        case 'r':sb.append('\r');p++;break;
                        case 't':sb.append('\t');p++;break;
                        case 'u':{p++;int cp=Integer.parseInt(s.substring(p,p+4),16);p+=4;
                            if(Character.isHighSurrogate((char)cp)&&p+1<s.length()&&s.charAt(p)=='\\'&&s.charAt(p+1)=='u'){
                                p+=2;int lo=Integer.parseInt(s.substring(p,p+4),16);p+=4;
                                sb.append((char)cp);sb.append((char)lo);
                            }else{sb.append((char)cp);}break;}
                        default:sb.append(e);p++;break;
                    }
                }else{sb.append(c);p++;}
            }
            JV v=new JV();v.type=JSTR;v.str=sb.toString();v.raw=s.substring(start,p);return v;
        }
        JV num(){
            int start=p;
            if(p<s.length()&&s.charAt(p)=='-')p++;
            while(p<s.length()&&s.charAt(p)>='0'&&s.charAt(p)<='9')p++;
            if(p<s.length()&&s.charAt(p)=='.'){p++;while(p<s.length()&&s.charAt(p)>='0'&&s.charAt(p)<='9')p++;}
            if(p<s.length()&&(s.charAt(p)=='e'||s.charAt(p)=='E')){p++;if(p<s.length()&&(s.charAt(p)=='+'||s.charAt(p)=='-'))p++;while(p<s.length()&&s.charAt(p)>='0'&&s.charAt(p)<='9')p++;}
            JV v=new JV();v.type=JNUM;v.numRaw=s.substring(start,p);v.num=Double.parseDouble(v.numRaw);return v;
        }
        JV obj(){
            p++;ArrayList<Map.Entry<String,JV>> list=new ArrayList<>();ws();
            if(p<s.length()&&s.charAt(p)=='}'){p++;JV v=new JV();v.type=JOBJ;v.obj=list;return v;}
            while(true){ws();JV k=str();ws();p++;JV val=val();list.add(new AbstractMap.SimpleEntry<>(k.str,val));ws();
                if(p<s.length()&&s.charAt(p)==',')p++;else break;}
            ws();p++;JV v=new JV();v.type=JOBJ;v.obj=list;return v;
        }
        JV arr(){
            p++;ArrayList<JV> list=new ArrayList<>();ws();
            if(p<s.length()&&s.charAt(p)==']'){p++;JV v=new JV();v.type=JARR;v.arr=list;return v;}
            while(true){list.add(val());ws();if(p<s.length()&&s.charAt(p)==',')p++;else break;}
            ws();p++;JV v=new JV();v.type=JARR;v.arr=list;return v;
        }
    }

    static String esc(String s){
        StringBuilder sb=new StringBuilder();
        for(int i=0;i<s.length();i++){char c=s.charAt(i);
            if(c=='"')sb.append("\\\"");
            else if(c=='\\')sb.append("\\\\");
            else if(c=='\b')sb.append("\\b");
            else if(c=='\f')sb.append("\\f");
            else if(c=='\n')sb.append("\\n");
            else if(c=='\r')sb.append("\\r");
            else if(c=='\t')sb.append("\\t");
            else if(c<0x20)sb.append(String.format("\\u%04x",(int)c));
            else sb.append(c);
        }
        return sb.toString();
    }

    static String q(String s){return "\""+esc(s)+"\"";}

    static String ser(JV v){
        if(v==null)return "null";
        switch(v.type){
            case JNULL:return "null";
            case JBOOL:return v.b?"true":"false";
            case JNUM:return v.numRaw;
            case JSTR:return "\""+v.raw+"\"";
            case JOBJ:{StringBuilder sb=new StringBuilder("{");boolean f=true;
                for(Map.Entry<String,JV> e:v.obj){if(!f)sb.append(",");sb.append(q(e.getKey())).append(":").append(ser(e.getValue()));f=false;}
                return sb+"}";}
            case JARR:{StringBuilder sb=new StringBuilder("[");boolean f=true;
                for(JV item:v.arr){if(!f)sb.append(",");sb.append(ser(item));f=false;}
                return sb+"]";}
        }
        return "null";
    }

    static JV g(JV o,String k){if(o==null||o.type!=JOBJ)return null;for(Map.Entry<String,JV> e:o.obj)if(e.getKey().equals(k))return e.getValue();return null;}
    static String gs(JV o,String k){JV v=g(o,k);return(v!=null&&v.type==JSTR)?v.str:null;}
    static long gl(JV o,String k){JV v=g(o,k);return(v!=null&&v.type==JNUM)?(long)v.num:0;}

    static List<List<String>> parseCsv(String content){
        if(content.startsWith("\uFEFF"))content=content.substring(1);
        List<List<String>> recs=new ArrayList<>();int p=0,len=content.length();
        while(p<len){
            List<String> fields=new ArrayList<>();
            while(true){String f;
                if(p<len&&content.charAt(p)=='"'){p++;StringBuilder sb=new StringBuilder();
                    while(p<len){if(content.charAt(p)=='"'){if(p+1<len&&content.charAt(p+1)=='"'){sb.append('"');p+=2;}else{p++;break;}}else{sb.append(content.charAt(p));p++;}}
                    f=sb.toString();
                }else{StringBuilder sb=new StringBuilder();
                    while(p<len&&content.charAt(p)!=','&&content.charAt(p)!='\r'&&content.charAt(p)!='\n'){sb.append(content.charAt(p));p++;}
                    f=sb.toString();}
                fields.add(f);
                if(p<len&&content.charAt(p)==',')p++;else break;}
            if(p<len&&content.charAt(p)=='\r'){p++;if(p<len&&content.charAt(p)=='\n')p++;}
            else if(p<len&&content.charAt(p)=='\n')p++;
            recs.add(fields);}
        return recs;
    }

    static JV mkStr(String s){JV v=new JV();v.type=JSTR;v.str=s;v.raw=esc(s);return v;}

    static JV mkMsg(String role,String content){
        ArrayList<Map.Entry<String,JV>> l=new ArrayList<>();
        l.add(new AbstractMap.SimpleEntry<>("role",mkStr(role)));
        l.add(new AbstractMap.SimpleEntry<>("content",mkStr(content)));
        JV v=new JV();v.type=JOBJ;v.obj=l;return v;
    }

    static String execTool(String name,String argsJson,Map<String,String[]> inv,Map<String,Long> rates){
        if(name.equals("inventory_lookup")){
            JV a=new JP(argsJson).parse();String sku=gs(a,"sku");String[] d=inv.get(sku);
            if(d==null)return "{\"error\":"+q("unknown sku: "+sku)+"}";
            return "{\"sku\":"+q(sku)+",\"name\":"+q(d[0])+",\"price_cents\":"+d[1]+",\"currency\":"+q(d[2])+",\"stock\":"+d[3]+"}";
        }else if(name.equals("convert_currency")){
            JV a=new JP(argsJson).parse();long amt=gl(a,"amount_cents");String from=gs(a,"from");String to=gs(a,"to");
            long rf=rates.get(from),rt=rates.get(to);
            long converted=(2L*amt*rt+rf)/(2L*rf);
            return "{\"amount_cents\":"+converted+",\"currency\":"+q(to)+"}";
        }else{
            return "{\"error\":"+q("unknown tool: "+name)+"}";
        }
    }

    public static void main(String[] args) throws Exception {
        String dataDir=args[0], baseUrl=args[1];

        String taskRaw=new String(Files.readAllBytes(Paths.get(dataDir,"task.json")),StandardCharsets.UTF_8);
        if(taskRaw.startsWith("\uFEFF"))taskRaw=taskRaw.substring(1);
        JV task=new JP(taskRaw).parse();
        String apiKey=gs(task,"api_key"),model=gs(task,"model"),system=gs(task,"system"),user=gs(task,"user");
        String toolsRaw=ser(g(task,"tools"));

        String csvRaw=new String(Files.readAllBytes(Paths.get(dataDir,"inventory.csv")),StandardCharsets.UTF_8);
        List<List<String>> csvRecs=parseCsv(csvRaw);
        Map<String,String[]> inv=new LinkedHashMap<>();
        for(int i=1;i<csvRecs.size();i++){List<String> r=csvRecs.get(i);
            if(r.size()>=5)inv.put(r.get(0),new String[]{r.get(1),r.get(2),r.get(3),r.get(4)});}

        String ratesRaw=new String(Files.readAllBytes(Paths.get(dataDir,"rates.json")),StandardCharsets.UTF_8);
        if(ratesRaw.startsWith("\uFEFF"))ratesRaw=ratesRaw.substring(1);
        JV ratesJson=new JP(ratesRaw).parse();JV ratesObj=g(ratesJson,"rates");
        Map<String,Long> rates=new HashMap<>();
        if(ratesObj!=null&&ratesObj.type==JOBJ)for(Map.Entry<String,JV> e:ratesObj.obj)rates.put(e.getKey(),(long)e.getValue().num);

        List<JV> msgs=new ArrayList<>();
        msgs.add(mkMsg("system",system));
        msgs.add(mkMsg("user",user));

        List<String> out=new ArrayList<>();
        long tP=0,tC=0,tT=0;int nReq=0;

        HttpClient client=HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).build();

        while(true){
            StringBuilder body=new StringBuilder();
            body.append("{\"model\":").append(q(model));
            body.append(",\"messages\":[");
            for(int i=0;i<msgs.size();i++){if(i>0)body.append(",");body.append(ser(msgs.get(i)));}
            body.append("],\"tools\":").append(toolsRaw);
            body.append(",\"tool_choice\":\"auto\"}");

            HttpRequest req=HttpRequest.newBuilder()
                .uri(URI.create(baseUrl+"/chat/completions"))
                .header("Authorization","Bearer "+apiKey)
                .header("Content-Type","application/json")
                .POST(HttpRequest.BodyPublishers.ofString(body.toString(),StandardCharsets.UTF_8))
                .build();

            HttpResponse<byte[]> resp=client.send(req,HttpResponse.BodyHandlers.ofByteArray());
            nReq++;int status=resp.statusCode();

            if(status!=200){
                String rb=new String(resp.body(),StandardCharsets.UTF_8);
                JV ej=new JP(rb).parse();String em=gs(g(ej,"error"),"message");
                for(String l:out)System.out.println(l);
                System.out.println("ERROR "+status+" "+em);
                System.exit(0);
            }

            String rb=new String(resp.body(),StandardCharsets.UTF_8);
            JV rj=new JP(rb).parse();

            JV usage=g(rj,"usage");
            tP+=gl(usage,"prompt_tokens");tC+=gl(usage,"completion_tokens");tT+=gl(usage,"total_tokens");

            JV ch0=g(rj,"choices").arr.get(0);
            String fr=gs(ch0,"finish_reason");
            JV msg=g(ch0,"message");

            if(!"tool_calls".equals(fr)){
                String content=gs(msg,"content");
                for(String l:out)System.out.println(l);
                System.out.println("FINAL "+content);
                System.out.println("USAGE prompt="+tP+" completion="+tC+" total="+tT+" requests="+nReq);
                System.exit(0);
            }

            JV cn=g(msg,"content");
            if(cn!=null&&cn.type==JSTR)out.add("SAY "+cn.str);

            JV tcs=g(msg,"tool_calls");
            for(JV tc:tcs.arr){String id=gs(tc,"id");String nm=gs(g(tc,"function"),"name");out.add("CALL "+id+" "+nm);}

            List<String> results=new ArrayList<>();
            for(JV tc:tcs.arr){
                String id=gs(tc,"id");JV fn=g(tc,"function");String nm=gs(fn,"name");
                String argStr=g(fn,"arguments").str;
                String res=execTool(nm,argStr,inv,rates);
                results.add(res);out.add("RESULT "+id+" "+res);
            }

            msgs.add(msg);

            for(int i=0;i<tcs.arr.size();i++){
                String id=gs(tcs.arr.get(i),"id");String res=results.get(i);
                ArrayList<Map.Entry<String,JV>> ml=new ArrayList<>();
                ml.add(new AbstractMap.SimpleEntry<>("role",mkStr("tool")));
                ml.add(new AbstractMap.SimpleEntry<>("tool_call_id",mkStr(id)));
                ml.add(new AbstractMap.SimpleEntry<>("content",mkStr(res)));
                JV tm=new JV();tm.type=JOBJ;tm.obj=ml;msgs.add(tm);
            }
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <errno.h>
#include <math.h>

/* ===== String Builder ===== */
typedef struct { char *data; size_t len, cap; } SB;
static void sb_init(SB *s){ s->cap=256; s->data=malloc(s->cap); s->len=0; s->data[0]=0; }
static void sb_ensure(SB *s,size_t ex){ if(s->len+ex+1>s->cap){ while(s->len+ex+1>s->cap) s->cap*=2; s->data=realloc(s->data,s->cap);} }
static void sb_ap(SB *s,const char *p,size_t n){ sb_ensure(s,n); memcpy(s->data+s->len,p,n); s->len+=n; s->data[s->len]=0; }
static void sb_puts(SB *s,const char *p){ sb_ap(s,p,strlen(p)); }
static void sb_putc(SB *s,char c){ sb_ensure(s,1); s->data[s->len++]=c; s->data[s->len]=0; }
static void sb_int(SB *s,long long n){ char t[32]; int i=0,neg=0; if(n==0){sb_putc(s,'0');return;} if(n<0){neg=1;n=-n;} while(n){t[i++]='0'+(n%10);n/=10;} if(neg)sb_putc(s,'-'); while(i--)sb_putc(s,t[i]); }

/* ===== JSON ===== */
typedef enum{J_NULL,J_BOOL,J_NUM,J_STR,J_ARR,J_OBJ}JType;
typedef struct JV{
    JType type; char *s; long long num; int bval;
    struct{char *key;struct JV *val;}*pairs; int np;
    struct JV **elems; int ne;
    int rs,re;
}JV;

static JV*jv_new(JType t){JV*v=calloc(1,sizeof(JV));v->type=t;return v;}

typedef struct{const char*src;int len;int pos;}JC;

static void jsk(JC*c){while(c->pos<c->len){char ch=c->src[c->pos];if(ch==' '||ch=='\t'||ch=='\n'||ch=='\r')c->pos++;else break;}}

static int hexv(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return 0;}

static void utf8_enc(SB*s,unsigned cp){
    if(cp<=0x7F)sb_putc(s,cp);
    else if(cp<=0x7FF){sb_putc(s,0xC0|(cp>>6));sb_putc(s,0x80|(cp&0x3F));}
    else if(cp<=0xFFFF){sb_putc(s,0xE0|(cp>>12));sb_putc(s,0x80|((cp>>6)&0x3F));sb_putc(s,0x80|(cp&0x3F));}
    else{sb_putc(s,0xF0|(cp>>18));sb_putc(s,0x80|((cp>>12)&0x3F));sb_putc(s,0x80|((cp>>6)&0x3F));sb_putc(s,0x80|(cp&0x3F));}
}

static char*parse_str(JC*c){
    c->pos++;/*skip"*/
    SB sb;sb_init(&sb);
    while(c->pos<c->len&&c->src[c->pos]!='"'){
        if(c->src[c->pos]=='\\'){
            c->pos++;
            if(c->pos>=c->len)break;
            char ch=c->src[c->pos++];
            switch(ch){
                case'"':sb_putc(&sb,'"');break;
                case'\\':sb_putc(&sb,'\\');break;
                case'/':sb_putc(&sb,'/');break;
                case'b':sb_putc(&sb,'\b');break;
                case'f':sb_putc(&sb,'\f');break;
                case'n':sb_putc(&sb,'\n');break;
                case'r':sb_putc(&sb,'\r');break;
                case't':sb_putc(&sb,'\t');break;
                case'u':{
                    unsigned cp=0;
                    for(int i=0;i<4&&c->pos<c->len;i++){cp=(cp<<4)|hexv(c->src[c->pos++]);}
                    if(cp>=0xD800&&cp<=0xDBFF){
                        if(c->pos+1<c->len&&c->src[c->pos]=='\\'&&c->src[c->pos+1]=='u'){
                            c->pos+=2;unsigned lo=0;
                            for(int i=0;i<4&&c->pos<c->len;i++){lo=(lo<<4)|hexv(c->src[c->pos++]);}
                            if(lo>=0xDC00&&lo<=0xDFFF)cp=0x10000+(cp-0xD800)*0x400+(lo-0xDC00);
                            else{utf8_enc(&sb,0xFFFD);cp=lo;}
                        }else cp=0xFFFD;
                    }
                    utf8_enc(&sb,cp);break;
                }
                default:sb_putc(&sb,ch);break;
            }
        }else{sb_putc(&sb,c->src[c->pos++]);}
    }
    if(c->pos<c->len&&c->src[c->pos]=='"')c->pos++;
    return sb.data;
}

static JV*parse_val(JC*c){
    jsk(c);
    if(c->pos>=c->len)return jv_new(J_NULL);
    int start=c->pos;
    char ch=c->src[c->pos];
    JV*v;
    if(ch=='{'){
        v=jv_new(J_OBJ);c->pos++;jsk(c);
        if(c->pos<c->len&&c->src[c->pos]=='}'){c->pos++;}
        else{
            while(1){
                jsk(c);
                if(c->pos>=c->len||c->src[c->pos]!='"')break;
                char*key=parse_str(c);
                jsk(c);
                if(c->pos<c->len&&c->src[c->pos]==':')c->pos++;
                jsk(c);
                JV*val=parse_val(c);
                v->pairs=realloc(v->pairs,(v->np+1)*sizeof(v->pairs[0]));
                v->pairs[v->np].key=key;v->pairs[v->np].val=val;v->np++;
                jsk(c);
                if(c->pos<c->len&&c->src[c->pos]==','){c->pos++;}else break;
            }
            jsk(c);if(c->pos<c->len&&c->src[c->pos]=='}')c->pos++;
        }
    }else if(ch=='['){
        v=jv_new(J_ARR);c->pos++;jsk(c);
        if(c->pos<c->len&&c->src[c->pos]==']'){c->pos++;}
        else{
            while(1){
                JV*val=parse_val(c);
                v->elems=realloc(v->elems,(v->ne+1)*sizeof(JV*));
                v->elems[v->ne++]=val;
                jsk(c);
                if(c->pos<c->len&&c->src[c->pos]==','){c->pos++;}else break;
            }
            jsk(c);if(c->pos<c->len&&c->src[c->pos]==']')c->pos++;
        }
    }else if(ch=='"'){
        v=jv_new(J_STR);v->s=parse_str(c);
    }else if(ch=='t'){
        v=jv_new(J_BOOL);v->bval=1;c->pos+=4;
    }else if(ch=='f'){
        v=jv_new(J_BOOL);v->bval=0;c->pos+=5;
    }else if(ch=='n'){
        v=jv_new(J_NULL);c->pos+=4;
    }else{
        v=jv_new(J_NUM);int neg=0;
        if(c->pos<c->len&&c->src[c->pos]=='-'){neg=1;c->pos++;}
        long long n=0;
        while(c->pos<c->len&&c->src[c->pos]>='0'&&c->src[c->pos]<='9'){n=n*10+(c->src[c->pos]-'0');c->pos++;}
        if(c->pos<c->len&&c->src[c->pos]=='.'){c->pos++;while(c->pos<c->len&&c->src[c->pos]>='0'&&c->src[c->pos]<='9')c->pos++;}
        if(c->pos<c->len&&(c->src[c->pos]=='e'||c->src[c->pos]=='E')){c->pos++;if(c->pos<c->len&&(c->src[c->pos]=='+'||c->src[c->pos]=='-'))c->pos++;while(c->pos<c->len&&c->src[c->pos]>='0'&&c->src[c->pos]<='9')c->pos++;}
        v->num=neg?-n:n;
    }
    v->rs=start;v->re=c->pos;
    return v;
}

static JV*jget(JV*o,const char*k){if(!o||o->type!=J_OBJ)return NULL;for(int i=0;i<o->np;i++)if(strcmp(o->pairs[i].key,k)==0)return o->pairs[i].val;return NULL;}

static char*jraw(JV*v,const char*src){int l=v->re-v->rs;char*r=malloc(l+1);memcpy(r,src+v->rs,l);r[l]=0;return r;}

/* ===== JSON output escaping ===== */
static void json_esc(SB*s,const char*str){
    sb_putc(s,'"');
    for(const unsigned char*p=(const unsigned char*)str;*p;p++){
        unsigned char c=*p;
        if(c=='"')sb_puts(s,"\\\"");
        else if(c=='\\')sb_puts(s,"\\\\");
        else if(c=='\b')sb_puts(s,"\\b");
        else if(c=='\f')sb_puts(s,"\\f");
        else if(c=='\n')sb_puts(s,"\\n");
        else if(c=='\r')sb_puts(s,"\\r");
        else if(c=='\t')sb_puts(s,"\\t");
        else if(c<0x20){sb_putc(s,'\\');sb_putc(s,'u');sb_putc(s,'0');sb_putc(s,'0');sb_putc(s,"0123456789abcdef"[(c>>4)&0xF]);sb_putc(s,"0123456789abcdef"[c&0xF]);}
        else sb_putc(s,c);
    }
    sb_putc(s,'"');
}

/* ===== File reading ===== */
static char*read_file(const char*path,int*olen){
    FILE*f=fopen(path,"rb");if(!f)return NULL;
    fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
    char*buf=malloc(sz+1);fread(buf,1,sz,f);buf[sz]=0;fclose(f);*olen=(int)sz;return buf;
}

/* ===== CSV ===== */
typedef struct{char*sku,*name,*currency;long long price_cents,stock;}InvEntry;

static void csv_parse(const char*data,int len,InvEntry**out,int*count){
    int pos=0;
    /* skip BOM */
    if(len>=3&&(unsigned char)data[0]==0xEF&&(unsigned char)data[1]==0xBB&&(unsigned char)data[2]==0xBF)pos=3;
    /* skip header */
    while(pos<len){
        if(data[pos]=='"'){pos++;while(pos<len){if(data[pos]=='"'){if(pos+1<len&&data[pos+1]=='"')pos+=2;else{pos++;break;}}else pos++;}}
        else{while(pos<len&&data[pos]!=','&&data[pos]!='\r'&&data[pos]!='\n')pos++;}
        if(pos<len&&data[pos]==','){pos++;continue;}
        break;
    }
    if(pos<len&&data[pos]=='\r')pos++;
    if(pos<len&&data[pos]=='\n')pos++;

    int cap=64;InvEntry*arr=malloc(cap*sizeof(InvEntry));*count=0;

    while(pos<len){
        /* parse 5 fields */
        char*fields[5];
        for(int fi=0;fi<5;fi++){
            SB sb;sb_init(&sb);
            if(pos<len&&data[pos]=='"'){
                pos++;
                while(pos<len){
                    if(data[pos]=='"'){if(pos+1<len&&data[pos+1]=='"'){sb_putc(&sb,'"');pos+=2;}else{pos++;break;}}
                    else{sb_putc(&sb,data[pos]);pos++;}
                }
            }else{
                while(pos<len&&data[pos]!=','&&data[pos]!='\r'&&data[pos]!='\n'){sb_putc(&sb,data[pos]);pos++;}
            }
            fields[fi]=sb.data;
            if(fi<4&&pos<len&&data[pos]==',')pos++;
        }
        /* skip CRLF */
        if(pos<len&&data[pos]=='\r')pos++;
        if(pos<len&&data[pos]=='\n')pos++;

        if(*count>=cap){cap*=2;arr=realloc(arr,cap*sizeof(InvEntry));}
        arr[*count].sku=fields[0];arr[*count].name=fields[1];
        arr[*count].price_cents=atoll(fields[2]);arr[*count].currency=fields[3];arr[*count].stock=atoll(fields[4]);
        (*count)++;
    }
    *out=arr;
}

