/* ===== HTTP ===== */
static char*http_post(const char*host,int port,const char*path,const char*body,int*status,int*rlen){
    struct addrinfo hints,*res=NULL;
    memset(&hints,0,sizeof(hints));hints.ai_family=AF_INET;hints.ai_socktype=SOCK_STREAM;
    char portstr[16];snprintf(portstr,sizeof(portstr),"%d",port);
    if(getaddrinfo(host,portstr,&hints,&res)!=0)return NULL;
    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(fd<0){freeaddrinfo(res);return NULL;}
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){close(fd);freeaddrinfo(res);return NULL;}
    freeaddrinfo(res);

    SB req;sb_init(&req);
    sb_puts(&req,"POST ");sb_puts(&req,path);sb_puts(&req," HTTP/1.1\r\n");
    sb_puts(&req,"Host: ");sb_puts(&req,host);sb_putc(&req,':');sb_int(&req,port);sb_puts(&req,"\r\n");
    sb_puts(&req,"Content-Type: application/json\r\n");
    sb_puts(&req,"Content-Length: ");sb_int(&req,(long long)strlen(body));sb_puts(&req,"\r\n");
    sb_puts(&req,"Connection: close\r\n");
    sb_puts(&req,"\r\n");
    sb_puts(&req,body);

    size_t total=req.len,off=0;
    while(off<total){ssize_t w=write(fd,req.data+off,total-off);if(w<=0)break;off+=w;}

    /* read response */
    SB resp;sb_init(&resp);
    char tmp[4096];
    while(1){ssize_t r=read(fd,tmp,sizeof(tmp));if(r<=0)break;sb_ap(&resp,tmp,(size_t)r);}
    close(fd);

    /* parse status */
    *status=0;
    char*nl=strstr(resp.data,"\r\n");
    if(nl){char*sp=strchr(resp.data,' ');if(sp)*status=atoi(sp+1);}

    /* find end of headers */
    char*hdr_end=strstr(resp.data,"\r\n\r\n");
    int body_start=hdr_end?((int)(hdr_end-resp.data)+4):0;

    /* find Content-Length */
    int clen=-1;
    {
        char*cl=strstr(resp.data,"Content-Length: ");
        if(!cl)cl=strstr(resp.data,"content-length: ");
        if(cl){cl+=16;clen=atoi(cl);}
    }

    int avail=resp.len-body_start;
    int blen=clen>=0?clen:avail;
    if(blen>avail)blen=avail;
    char*body_out=malloc(blen+1);memcpy(body_out,resp.data+body_start,blen);body_out[blen]=0;
    *rlen=blen;
    return body_out;
}

