    enum ValueKind { NULL, INTEGER, REAL, TEXT, BLOB }

    static class Value {
        ValueKind kind;
        long intVal;
        double realVal;
        byte[] bytes;
        Value(ValueKind k) { kind = k; }
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        fileData = Files.readAllBytes(Paths.get(dir, "db.sqlite"));

        pageSize = readBE16(16);
        if (pageSize == 1) pageSize = 65536;
        reservedBytes = fileData[20] & 0xFF;
        usableSize = pageSize - reservedBytes;

        List<Object[]> schemaRows = walkTable(1);

        List<Object[]> tables = new ArrayList<>();
        for (Object[] row : schemaRows) {
            byte[] payload = (byte[]) row[1];
            List<Value> vals = parseRecord(payload);
            if (vals.size() < 5) continue;

            String type = vals.get(0).kind == ValueKind.TEXT ? new String(vals.get(0).bytes, "UTF-8") : "";
            String name = vals.get(1).kind == ValueKind.TEXT ? new String(vals.get(1).bytes, "UTF-8") : "";
            long rootpage = vals.get(3).intVal;
            String sql = vals.get(4).kind == ValueKind.TEXT ? new String(vals.get(4).bytes, "UTF-8") : "";

            if ("table".equals(type) && !name.startsWith("sqlite_")) {
                tables.add(new Object[]{name, rootpage, sql});
            }
        }

        tables.sort((a, b) -> {
            byte[] b1 = ((String) a[0]).getBytes(java.nio.charset.StandardCharsets.UTF_8);
            byte[] b2 = ((String) b[0]).getBytes(java.nio.charset.StandardCharsets.UTF_8);
            int min = Math.min(b1.length, b2.length);
            for (int i = 0; i < min; i++) {
                int d = (b1[i] & 0xFF) - (b2[i] & 0xFF);
                if (d != 0) return d;
            }
            return b1.length - b2.length;
        });

        boolean firstTable = true;
        for (Object[] tbl : tables) {
            if (!firstTable) System.out.println();
            firstTable = false;

            String tableName = (String) tbl[0];
            long rootpage = (Long) tbl[1];
            String sql = (String) tbl[2];

            List<String> colNames = parseColumnNames(sql);
            boolean[] rowidAlias = detectRowidAliases(sql, colNames.size());

            List<Object[]> rows;
            if (rootpage == 0) {
                rows = new ArrayList<>();
            } else {
                rows = walkTable(rootpage);
            }
            rows.sort((a, b) -> Long.compare((Long) a[0], (Long) b[0]));

            System.out.println("TABLE " + tableName + " rows=" + rows.size());
            System.out.print("COLUMNS ");
            for (int i = 0; i < colNames.size(); i++) {
                if (i > 0) System.out.print(", ");
                System.out.print(colNames.get(i));
            }
            System.out.println();

            for (Object[] row : rows) {
                long rowid = (Long) row[0];
                byte[] payload = (byte[]) row[1];
                List<Value> values = parseRecord(payload);

                System.out.print(rowid + ": ");
                for (int i = 0; i < colNames.size(); i++) {
                    if (i > 0) System.out.print(", ");
                    Value v;
                    if (rowidAlias[i]) {
                        v = new Value(ValueKind.INTEGER);
                        v.intVal = rowid;
                    } else if (i < values.size()) {
                        v = values.get(i);
                    } else {
                        v = new Value(ValueKind.NULL);
                    }
                    System.out.print(formatValue(v));
                }
                System.out.println();
            }
        }
    }

    static int readBE16(int off) {
        return ((fileData[off] & 0xFF) << 8) | (fileData[off + 1] & 0xFF);
    }

    static int readBE32(int off) {
        return ((fileData[off] & 0xFF) << 24) | ((fileData[off + 1] & 0xFF) << 16)
             | ((fileData[off + 2] & 0xFF) << 8) | (fileData[off + 3] & 0xFF);
    }

    static long readVarintFromFile(int off) {
        long value = 0;
        int i;
        for (i = 0; i < 8; i++) {
            byte b = fileData[off + i];
            value = (value << 7) | (b & 0x7F);
            if ((b & 0x80) == 0) {
                varintLen = i + 1;
                return value;
            }
        }
        value = (value << 8) | (fileData[off + 8] & 0xFF);
        varintLen = 9;
        return value;
    }

    static long readVarint(byte[] a, int off) {
        long value = 0;
        int i;
        for (i = 0; i < 8; i++) {
            byte b = a[off + i];
            value = (value << 7) | (b & 0x7F);
            if ((b & 0x80) == 0) {
                varintLen = i + 1;
                return value;
            }
        }
        value = (value << 8) | (a[off + 8] & 0xFF);
        varintLen = 9;
        return value;
    }

    static int readBE16(byte[] a, int off) {
        return ((a[off] & 0xFF) << 8) | (a[off + 1] & 0xFF);
    }

    static int readBE32(byte[] a, int off) {
        return ((a[off] & 0xFF) << 24) | ((a[off + 1] & 0xFF) << 16)
             | ((a[off + 2] & 0xFF) << 8) | (a[off + 3] & 0xFF);
    }

    static long readBE64(byte[] a, int off) {
        long v = 0;
        for (int i = 0; i < 8; i++) v = (v << 8) | (a[off + i] & 0xFF);
        return v;
    }

    static List<Object[]> walkTable(long pageNum) {
        List<Object[]> result = new ArrayList<>();
        walkPage(pageNum, result);
        return result;
    }

    static void walkPage(long pageNum, List<Object[]> result) {
        if (pageNum <= 0) return;
        int pageStart = (int)((pageNum - 1) * pageSize);
        int hdrOff = (pageNum == 1) ? 100 : 0;
        int absHdr = pageStart + hdrOff;

        int pageType = fileData[absHdr] & 0xFF;
        int numCells = readBE16(absHdr + 3);

        if (pageType == 5) {
            int rightmost = readBE32(absHdr + 8);
            int cellPtrBase = absHdr + 12;

            for (int i = 0; i < numCells; i++) {
                int cellOff = pageStart + readBE16(cellPtrBase + i * 2);
                int leftChild = readBE32(cellOff);
                walkPage(leftChild, result);
            }
            walkPage(rightmost, result);
        } else if (pageType == 13) {
            int cellPtrBase = absHdr + 8;

            for (int i = 0; i < numCells; i++) {
                int cellOff = pageStart + readBE16(cellPtrBase + i * 2);

                long payloadSize = readVarintFromFile(cellOff);
                int pos = cellOff + varintLen;

                long rowid = readVarintFromFile(pos);
                pos += varintLen;

                int X = usableSize - 35;
                int localSize = (int) Math.min(payloadSize, (long) X);

                byte[] payload = new byte[(int) payloadSize];
                if (localSize > 0) {
                    System.arraycopy(fileData, pos, payload, 0, localSize);
                }

                if (payloadSize > X) {
                    pos += localSize;
                    int overflowPage = readBE32(pos);
                    int destOff = localSize;
                    int remaining = (int) (payloadSize - localSize);
                    while (overflowPage != 0 && remaining > 0) {
                        int ovfStart = (int) ((overflowPage - 1) * pageSize);
                        int bytesHere = Math.min(remaining, usableSize - 4);
                        System.arraycopy(fileData, ovfStart + 4, payload, destOff, bytesHere);
                        destOff += bytesHere;
                        remaining -= bytesHere;
                        overflowPage = readBE32(ovfStart);
                    }
                }

                result.add(new Object[]{rowid, payload});
            }
        }
    }

    static List<Value> parseRecord(byte[] payload) {
        List<Value> values = new ArrayList<>();
        if (payload.length == 0) return values;

        int pos = 0;
        long headerSize = readVarint(payload, pos);
        pos += varintLen;

        List<Long> serialTypes = new ArrayList<>();
        while (pos < headerSize) {
            long st = readVarint(payload, pos);
            serialTypes.add(st);
            pos += varintLen;
        }

        for (long st : serialTypes) {
            Value v = new Value(ValueKind.NULL);
            if (st == 0) {
                // NULL
            } else if (st == 1) {
                v.kind = ValueKind.INTEGER;
                v.intVal = (byte) payload[pos]; pos += 1;
            } else if (st == 2) {
                v.kind = ValueKind.INTEGER;
                v.intVal = (short) readBE16(payload, pos); pos += 2;
            } else if (st == 3) {
                v.kind = ValueKind.INTEGER;
                int val = ((payload[pos] & 0xFF) << 16) | ((payload[pos + 1] & 0xFF) << 8) | (payload[pos + 2] & 0xFF);
                if ((val & 0x800000) != 0) val -= 0x1000000;
                v.intVal = val; pos += 3;
            } else if (st == 4) {
                v.kind = ValueKind.INTEGER;
                v.intVal = (int) readBE32(payload, pos); pos += 4;
            } else if (st == 5) {
                v.kind = ValueKind.INTEGER;
                long val = 0;
                for (int i = 0; i < 6; i++) val = (val << 8) | (payload[pos + i] & 0xFF);
                if ((val & 0x800000000000L) != 0) val -= 0x1000000000000L;
                v.intVal = val; pos += 6;
            } else if (st == 6) {
                v.kind = ValueKind.INTEGER;
                v.intVal = readBE64(payload, pos); pos += 8;
            } else if (st == 7) {
                v.kind = ValueKind.REAL;
                v.realVal = Double.longBitsToDouble(readBE64(payload, pos)); pos += 8;
            } else if (st == 8) {
                v.kind = ValueKind.INTEGER;
                v.intVal = 0;
            } else if (st == 9) {
                v.kind = ValueKind.INTEGER;
                v.intVal = 1;
            } else if (st >= 12 && st % 2 == 0) {
                v.kind = ValueKind.BLOB;
                int len = (int) ((st - 12) / 2);
                v.bytes = Arrays.copyOfRange(payload, pos, pos + len);
                pos += len;
            } else if (st >= 13) {
                v.kind = ValueKind.TEXT;
                int len = (int) ((st - 13) / 2);
                v.bytes = Arrays.copyOfRange(payload, pos, pos + len);
                pos += len;
            }
            values.add(v);
        }
        return values;
    }

    static List<String> parseColumnNames(String sql) {
        List<String> names = new ArrayList<>();
        int openParen = sql.indexOf('(');
        if (openParen < 0) return names;

        int depth = 0;
        int closeParen = -1;
        for (int i = openParen; i < sql.length(); i++) {
            if (sql.charAt(i) == '(') depth++;
            else if (sql.charAt(i) == ')') {
                depth--;
                if (depth == 0) { closeParen = i; break; }
            }
        }
        if (closeParen < 0) return names;

        String defs = sql.substring(openParen + 1, closeParen);
        List<String> colDefs = splitTopLevel(defs);

        for (String def : colDefs) {
            def = def.trim();
            if (def.isEmpty()) continue;
            String colName;
            if (def.charAt(0) == '"') {
                int end = def.indexOf('"', 1);
                colName = def.substring(1, end);
            } else {
                int end = 0;
                while (end < def.length() && !Character.isWhitespace(def.charAt(end))
                       && def.charAt(end) != '(' && def.charAt(end) != ',') {
                    end++;
                }
                colName = def.substring(0, end);
            }
            names.add(colName);
        }
        return names;
    }

    static boolean[] detectRowidAliases(String sql, int numCols) {
        boolean[] result = new boolean[numCols];
        int openParen = sql.indexOf('(');
        if (openParen < 0) return result;

        int depth = 0;
        int closeParen = -1;
        for (int i = openParen; i < sql.length(); i++) {
            if (sql.charAt(i) == '(') depth++;
            else if (sql.charAt(i) == ')') {
                depth--;
                if (depth == 0) { closeParen = i; break; }
            }
        }
        if (closeParen < 0) return result;

        String defs = sql.substring(openParen + 1, closeParen);
        List<String> colDefs = splitTopLevel(defs);

        for (int i = 0; i < colDefs.size() && i < numCols; i++) {
            String def = colDefs.get(i).trim();
            String upperDef = def.toUpperCase().replaceAll("\\s+", " ");
            if (!upperDef.contains("PRIMARY KEY")) continue;

            String afterName;
            if (def.charAt(0) == '"') {
                int end = def.indexOf('"', 1);
                afterName = def.substring(end + 1).trim();
            } else {
                int j = 0;
                while (j < def.length() && !Character.isWhitespace(def.charAt(j)) && def.charAt(j) != '(') {
                    j++;
                }
                afterName = def.substring(j).trim();
            }

            String typeName = "";
            if (!afterName.isEmpty()) {
                int j = 0;
                while (j < afterName.length() && !Character.isWhitespace(afterName.charAt(j)) && afterName.charAt(j) != '(') {
                    j++;
                }
                typeName = afterName.substring(0, j);
            }

            if (typeName.equalsIgnoreCase("INTEGER")) {
                result[i] = true;
            }
        }
        return result;
    }

    static List<String> splitTopLevel(String s) {
        List<String> parts = new ArrayList<>();
        int depth = 0;
        int start = 0;
        boolean inQuote = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '"' && !inQuote) inQuote = true;
            else if (c == '"' && inQuote) inQuote = false;
            else if (!inQuote) {
                if (c == '(') depth++;
                else if (c == ')') depth--;
                else if (c == ',' && depth == 0) {
                    parts.add(s.substring(start, i));
                    start = i + 1;
                }
            }
        }
        parts.add(s.substring(start));
        return parts;
    }

    static String formatValue(Value v) {
        switch (v.kind) {
            case NULL: return "NULL";
            case INTEGER: return Long.toString(v.intVal);
            case REAL: return formatReal(v.realVal);
            case TEXT: return formatText(v.bytes);
            case BLOB: return formatBlob(v.bytes);
        }
        return "";
    }

    static String formatReal(double d) {
        if (d == 0.0) {
            if (Double.doubleToRawLongBits(d) < 0) return "-0.0";
            return "0.0";
        }
        if (Double.isNaN(d)) return "NaN";
        if (d == Double.POSITIVE_INFINITY) return "Infinity";
        if (d == Double.NEGATIVE_INFINITY) return "-Infinity";
        BigDecimal bd = new BigDecimal(d);
        bd = bd.stripTrailingZeros();
        String s = bd.toPlainString();
        if (!s.contains(".")) s += ".0";
        return s;
    }

    static String formatText(byte[] bytes) {
        if (bytes.length > 100) {
            CRC32 crc = new CRC32();
            crc.update(bytes);
            return "<TEXT len=" + bytes.length + " crc32=" + String.format("%08x", crc.getValue()) + ">";
        }
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        ByteArrayOutputStream raw = new ByteArrayOutputStream();
        for (byte b : bytes) {
            int c = b & 0xFF;
            if (c == '\\') { flushRaw(raw, sb); sb.append("\\\\"); }
            else if (c == '"') { flushRaw(raw, sb); sb.append("\\\""); }
            else if (c == '\n') { flushRaw(raw, sb); sb.append("\\n"); }
            else if (c == '\r') { flushRaw(raw, sb); sb.append("\\r"); }
            else if (c == '\t') { flushRaw(raw, sb); sb.append("\\t"); }
            else if (c < 0x20 || c == 0x7F) { flushRaw(raw, sb); sb.append(String.format("\\x%02X", c)); }
            else { raw.write(c); }
        }
        flushRaw(raw, sb);
        sb.append('"');
        return sb.toString();
    }

    static void flushRaw(ByteArrayOutputStream raw, StringBuilder sb) {
        if (raw.size() > 0) {
            sb.append(new String(raw.toByteArray(), java.nio.charset.StandardCharsets.UTF_8));
            raw.reset();
        }
    }

    static String formatBlob(byte[] bytes) {
        if (bytes.length > 100) {
            CRC32 crc = new CRC32();
            crc.update(bytes);
            return "<BLOB len=" + bytes.length + " crc32=" + String.format("%08x", crc.getValue()) + ">";
        }
        StringBuilder sb = new StringBuilder();
        sb.append("X'");
        for (byte b : bytes) {
            sb.append(String.format("%02X", b & 0xFF));
        }
        sb.append("'");
        return sb.toString();
    }
}

use std::io::{Read, Write, BufReader};
use std::net::TcpStream;
use std::collections::HashMap;

#[derive(Debug, Clone)]
enum J {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

impl J {
    fn get(&self, key: &str) -> Option<&J> {
        if let J::Obj(e) = self { e.iter().find(|(k,_)| k==key).map(|(_,v)|v) } else { None }
    }
    fn gs(&self) -> &str { if let J::Str(s)=self{s}else{""} }
    fn gn(&self) -> f64 { if let J::Num(n)=self{*n}else{0.0} }
}

struct P { ch: Vec<char>, p: usize }
impl P {
    fn new(s:&str)->Self{P{ch:s.chars().collect(),p:0}}
    fn ws(&mut self){while self.p<self.ch.len()&&matches!(self.ch[self.p],' '|'\t'|'\n'|'\r'){self.p+=1;}}
    fn parse(&mut self)->J{self.ws();self.val()}
    fn val(&mut self)->J{
        self.ws();
        match self.ch[self.p]{
            '{'=>self.obj(),
            '['=>self.arr(),
            '"'=>J::Str(self.string()),
            't'=>{self.p+=4;J::Bool(true)},
            'f'=>{self.p+=5;J::Bool(false)},
            'n'=>{self.p+=4;J::Null},
            _=>J::Num(self.num()),
        }
    }
    fn obj(&mut self)->J{
        self.p+=1;let mut e=Vec::new();self.ws();
        if self.ch[self.p]=='}'{self.p+=1;return J::Obj(e);}
        loop{
            self.ws();let k=self.string();self.ws();self.p+=1;let v=self.val();e.push((k,v));
            self.ws();
            if self.ch[self.p]==','{self.p+=1;}else{self.p+=1;break;}
        }
        J::Obj(e)
    }
    fn arr(&mut self)->J{
        self.p+=1;let mut a=Vec::new();self.ws();
        if self.ch[self.p]==']'{self.p+=1;return J::Arr(a);}
        loop{
            a.push(self.val());self.ws();
            if self.ch[self.p]==','{self.p+=1;}else{self.p+=1;break;}
        }
        J::Arr(a)
    }
    fn string(&mut self)->String{
        self.p+=1;let mut s=String::new();
        loop{
            let c=self.ch[self.p];
            if c=='"'{self.p+=1;return s;}
            if c=='\\'{
                self.p+=1;let e=self.ch[self.p];
                match e{
                    '"' =>{s.push('"');self.p+=1;}
                    '\\' =>{s.push('\\');self.p+=1;}
                    '/' =>{s.push('/');self.p+=1;}
                    'b' =>{s.push('\u{0008}');self.p+=1;}
                    'f' =>{s.push('\u{000C}');self.p+=1;}
                    'n' =>{s.push('\n');self.p+=1;}
                    'r' =>{s.push('\r');self.p+=1;}
                    't' =>{s.push('\t');self.p+=1;}
                    'u' =>{
                        self.p+=1;let cp=self.h4();
                        if cp>=0xD800&&cp<=0xDBFF{
                            if self.p+1<self.ch.len()&&self.ch[self.p]=='\\'&&self.ch[self.p+1]=='u'{
                                self.p+=2;let lo=self.h4();
                                if lo>=0xDC00&&lo<=0xDFFF{
                                    let c2=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                                    s.push(char::from_u32(c2).unwrap_or('\u{FFFD}'));
                                }else{s.push('\u{FFFD}');s.push('\u{FFFD}');}
                            }else{s.push('\u{FFFD}');}
                        }else{s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));}
                    }
                    _=>{s.push(e);self.p+=1;}
                }
            }else{s.push(c);self.p+=1;}
        }
    }
    fn h4(&mut self)->u32{
        let h:String=self.ch[self.p..self.p+4].iter().collect();self.p+=4;
        u32::from_str_radix(&h,16).unwrap_or(0)
    }
    fn num(&mut self)->f64{
        let st=self.p;
        if self.p<self.ch.len()&&self.ch[self.p]=='-'{self.p+=1;}
        while self.p<self.ch.len()&&self.ch[self.p].is_ascii_digit(){self.p+=1;}
        if self.p<self.ch.len()&&self.ch[self.p]=='.'{self.p+=1;while self.p<self.ch.len()&&self.ch[self.p].is_ascii_digit(){self.p+=1;}}
        if self.p<self.ch.len()&&(self.ch[self.p]=='e'||self.ch[self.p]=='E'){
            self.p+=1;
            if self.p<self.ch.len()&&(self.ch[self.p]=='+'||self.ch[self.p]=='-'){self.p+=1;}
            while self.p<self.ch.len()&&self.ch[self.p].is_ascii_digit(){self.p+=1;}
        }
        self.ch[st..self.p].iter().collect::<String>().parse().unwrap_or(0.0)
    }
}

fn pj(s:&str)->J{P::new(s).parse()}

fn ej(s:&str)->String{
    let mut r=String::new();
    for c in s.chars(){match c{
        '"' =>r.push_str("\\\""),
        '\\' =>r.push_str("\\\\"),
        '\n'=>r.push_str("\\n"),
        '\r'=>r.push_str("\\r"),
        '\t'=>r.push_str("\\t"),
        '\u{0008}'=>r.push_str("\\b"),
        '\u{000C}'=>r.push_str("\\f"),
        c if (c as u32)<0x20=>r.push_str(&format!("\\u{:04x}",c as u32)),
        c=>r.push(c),
    }}
    r
}

fn ser(j:&J)->String{
    match j{
        J::Null=>"null".into(),
        J::Bool(true)=>"true".into(),
        J::Bool(false)=>"false".into(),
        J::Num(n)=>{if*n==n.round()&&n.abs()<1e15{format!("{}",*n as i64)}else{format!("{}",n)}}
        J::Str(s)=>format!("\"{}\"",ej(s)),
        J::Arr(a)=>format!("[{}]",a.iter().map(ser).collect::<Vec<_>>().join(",")),
        J::Obj(e)=>format!("{{{}}}",e.iter().map(|(k,v)|format!("\"{}\":{}",ej(k),ser(v))).collect::<Vec<_>>().join(",")),
    }
}

fn esc(s:&str)->String{
    let mut r=String::new();
    for c in s.chars(){match c{
        '\\' =>r.push_str("\\\\"),
        '\n'=>r.push_str("\\n"),
        '\r'=>r.push_str("\\r"),
        '\t'=>r.push_str("\\t"),
        c=>r.push(c),
    }}
    r
}

fn parse_url(url:&str)->(String,u16,String){
    let rest=if url.starts_with("http://"){&url[7..]}else if url.starts_with("https://"){&url[8..]}else{url};
    let sl=rest.find('/').unwrap_or(rest.len());
    let hp=&rest[..sl];let path=&rest[sl..];
    if let Some(ci)=hp.rfind(':'){(hp[..ci].to_string(),hp[ci+1..].parse().unwrap(),path.to_string())}
    else{(hp.to_string(),80,path.to_string())}
}

fn http_post(host:&str,port:u16,path:&str,body:&str,api_key:&str)->(u16,HashMap<String,String>,Vec<u8>){
    let mut stream=TcpStream::connect((host,port)).unwrap();
    let req=format!("POST {} HTTP/1.1\r\nHost: {}:{}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n{}",path,host,port,body.len(),api_key,body);
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();
    let mut rd=BufReader::new(stream);
    let mut line=String::new();rd.read_line(&mut line).unwrap();
    let status:u16=line.split_whitespace().nth(1).unwrap().parse().unwrap();
    let mut hdrs=HashMap::new();
    loop{
        let mut l=String::new();rd.read_line(&mut l).unwrap();
        let t=l.trim_end_matches(|c|c=='\r'||c=='\n');
        if t.is_empty(){break;}
        let ci=t.find(':').unwrap();
        hdrs.insert(t[..ci].trim().to_lowercase(),t[ci+1..].trim().to_string());
    }
    let mut body_bytes=Vec::new();
    let te=hdrs.get("transfer-encoding").map(|s|s.to_lowercase());
    if te.as_deref()==Some("chunked"){
        loop{
            let mut sl=String::new();rd.read_line(&mut sl).unwrap();
            let sz=sl.trim_end_matches(|c|c=='\r'||c=='\n');
            let sz=sz.split(';').next().unwrap().trim();
            let size=usize::from_str_radix(sz,16).unwrap();
            if size==0{
                loop{
                    let mut tl=String::new();
                    let n=rd.read_line(&mut tl).unwrap();
                    if n==0||tl.trim_end_matches(|c|c=='\r'||c=='\n').is_empty(){break;}
                }
                break;
            }
            let mut buf=vec![0u8;size];
            rd.read_exact(&mut buf).unwrap();
            body_bytes.extend_from_slice(&buf);
            let mut crlf=[0u8;2];rd.read_exact(&mut crlf).unwrap();
        }
    }else if let Some(cl)=hdrs.get("content-length"){
        let len:usize=cl.parse().unwrap();
        body_bytes.resize(len,0);
        rd.read_exact(&mut body_bytes).unwrap();
    }
    (status,hdrs,body_bytes)
}

struct SseEv{event:String,data:String}

fn parse_sse(body:&[u8])->Vec<SseEv>{
    let text=String::from_utf8_lossy(body);
    let mut evts=Vec::new();
    let mut et=String::new();
    let mut dl:Vec<String>=Vec::new();
    for line in text.lines(){
        if line.is_empty(){
            if !et.is_empty()||!dl.is_empty(){
                evts.push(SseEv{event:et.clone(),data:dl.join("\n")});
                et.clear();dl.clear();
            }
        }else if line.starts_with(':'){}
        else if line.starts_with("event:"){
            let v=&line[6..];
            et=if v.starts_with(' '){v[1..].to_string()}else{v.to_string()};
        }else if line.starts_with("data:"){
            let v=&line[5..];
            dl.push(if v.starts_with(' '){v[1..].to_string()}else{v.to_string()});
        }
    }
    evts
}

struct BB{btype:String,thinking:String,signature:String,text:String,id:String,name:String,input_json:String}
impl BB{fn new()->Self{BB{btype:String::new(),thinking:String::new(),signature:String::new(),text:String::new(),id:String::new(),name:String::new(),input_json:String::new()}}}

struct Reply{blocks:Vec<BB>,stop_reason:String,input_tokens:u64,output_tokens:u64,cache_read:u64}

fn process_reply(events:&[SseEv])->Reply{
    let mut blocks:Vec<BB>=Vec::new();
    let mut stop_reason=String::new();
    let mut input_tokens=0u64;let mut output_tokens=0u64;let mut cache_read=0u64;
    for ev in events{
        match ev.event.as_str(){
            "message_start"=>{
                let d=pj(&ev.data);
                if let Some(msg)=d.get("message"){
                    if let Some(u)=msg.get("usage"){
                        input_tokens+=u.get("input_tokens").map(|v|v.gn() as u64).unwrap_or(0);
                        cache_read+=u.get("cache_read_input_tokens").map(|v|v.gn() as u64).unwrap_or(0);
                    }
                }
            }
            "content_block_start"=>{
                let d=pj(&ev.data);
                let idx=d.get("index").map(|v|v.gn() as usize).unwrap_or(0);
                let cb=d.get("content_block").unwrap();
                let bt=cb.get("type").map(|v|v.gs()).unwrap_or("").to_string();
                let mut b=BB::new();b.btype=bt;
                if let Some(id)=cb.get("id"){b.id=id.gs().to_string();}
                if let Some(nm)=cb.get("name"){b.name=nm.gs().to_string();}
                while blocks.len()<=idx{blocks.push(BB::new());}
                blocks[idx]=b;
            }
            "content_block_delta"=>{
                let d=pj(&ev.data);
                let idx=d.get("index").map(|v|v.gn() as usize).unwrap_or(0);
                let delta=d.get("delta").unwrap();
                let dt=delta.get("type").map(|v|v.gs()).unwrap_or("");
                match dt{
                    "thinking_delta"=>{blocks[idx].thinking.push_str(delta.get("thinking").map(|v|v.gs()).unwrap_or(""));}
                    "signature_delta"=>{blocks[idx].signature.push_str(delta.get("signature").map(|v|v.gs()).unwrap_or(""));}
                    "text_delta"=>{blocks[idx].text.push_str(delta.get("text").map(|v|v.gs()).unwrap_or(""));}
                    "input_json_delta"=>{blocks[idx].input_json.push_str(delta.get("partial_json").map(|v|v.gs()).unwrap_or(""));}
                    _=>{}
                }
            }
            "message_delta"=>{
                let d=pj(&ev.data);
                if let Some(dd)=d.get("delta"){
                    if let Some(sr)=dd.get("stop_reason"){stop_reason=sr.gs().to_string();}
                }
                if let Some(u)=d.get("usage"){
                    output_tokens+=u.get("output_tokens").map(|v|v.gn() as u64).unwrap_or(0);
                }
            }
            "message_stop"=>{}
            _=>{}
        }
    }
    Reply{blocks,stop_reason,input_tokens,output_tokens,cache_read}
}

fn run_tool(name:&str,input:&J)->(String,bool){
    match name{
        "measure"=>{
            let text=input.get("text").map(|v|v.gs()).unwrap_or("");
            let unit=input.get("unit").map(|v|v.gs()).unwrap_or("");
            match unit{
                "code_points"=>(text.chars().count().to_string(),false),
                "utf8_bytes"=>(text.len().to_string(),false),
                "utf16_units"=>(text.encode_utf16().count().to_string(),false),
                _=>(format!("unsupported unit: {}",unit),true),
            }
        }
        "reverse"=>{
            let text=input.get("text").map(|v|v.gs()).unwrap_or("");
            (text.chars().rev().collect::<String>(),false)
        }
        _=>(format!("unknown tool: {}",name),true),
    }
}

fn print_blocks(blocks:&[BB]){
    for b in blocks{
        match b.btype.as_str(){
            "thinking"=>{println!("thinking {}",esc(&b.thinking));println!("signature {}",esc(&b.signature));}
            "text"=>{println!("text {}",esc(&b.text));}
            "tool_use"=>{println!("tool_use {} {} {}",b.id,b.name,esc(&b.input_json));}
            _=>{}
        }
    }
}

fn main(){
    let args:Vec<String>=std::env::args().collect();
    let data_dir=&args[1];
    let base_url=&args[2];

    let req_content=std::fs::read_to_string(format!("{}/request.json",data_dir)).unwrap();
    let req=pj(&req_content);

    let api_key=req.get("api_key").map(|v|v.gs()).unwrap_or("").to_string();
    let model=req.get("model").map(|v|v.gs()).unwrap_or("").to_string();
    let max_tokens=req.get("max_tokens").map(|v|v.gn() as i64).unwrap_or(0);
    let thinking_budget=req.get("thinking_budget").map(|v|v.gn() as i64).unwrap_or(0);
    let system=req.get("system").cloned().unwrap_or(J::Null);
    let prompt=req.get("prompt").cloned().unwrap_or(J::Null);
    let tools=req.get("tools").cloned().unwrap_or(J::Arr(vec![]));

    let (host,port,base_path)=parse_url(base_url);
    let path=format!("{}/v1/messages",base_path);

    let body1=ser(&J::Obj(vec![
        ("model".into(),J::Str(model.clone())),
        ("max_tokens".into(),J::Num(max_tokens as f64)),
        ("stream".into(),J::Bool(true)),
        ("thinking".into(),J::Obj(vec![("type".into(),J::Str("enabled".into())),("budget_tokens".into(),J::Num(thinking_budget as f64))])),
        ("system".into(),system.clone()),
        ("tools".into(),tools.clone()),
        ("messages".into(),J::Arr(vec![J::Obj(vec![("role".into(),J::Str("user".into())),("content".into(),prompt.clone())])])),
    ]));

    println!("request 1");
    let (status,_,body_bytes)=http_post(&host,port,&path,&body1,&api_key);
    if status!=200{
        let eb=String::from_utf8_lossy(&body_bytes);
        let ej=pj(&eb);
        let et=ej.get("error").and_then(|e|e.get("type")).map(|v|v.gs()).unwrap_or("");
        let em=ej.get("error").and_then(|e|e.get("message")).map(|v|v.gs()).unwrap_or("");
        println!("ERROR {} {}: {}",status,et,em);
        std::process::exit(0);
    }

    let events1=parse_sse(&body_bytes);
    let reply1=process_reply(&events1);
    print_blocks(&reply1.blocks);
    println!("stop_reason {}",reply1.stop_reason);

    let mut tool_results:Vec<(String,String,bool)>=Vec::new();
    for b in &reply1.blocks{
        if b.btype=="tool_use"{
            let input=pj(&b.input_json);
            let (result,is_err)=run_tool(&b.name,&input);
            println!("{} {} {}",if is_err{"error"}else{"result"},b.id,esc(&result));
            tool_results.push((b.id.clone(),result,is_err));
        }
    }

    let mut asst_blocks:Vec<J>=Vec::new();
    for b in &reply1.blocks{
        match b.btype.as_str(){
            "thinking"=>asst_blocks.push(J::Obj(vec![("type".into(),J::Str("thinking".into())),("thinking".into(),J::Str(b.thinking.clone())),("signature".into(),J::Str(b.signature.clone()))])),
            "text"=>asst_blocks.push(J::Obj(vec![("type".into(),J::Str("text".into())),("text".into(),J::Str(b.text.clone()))])),
            "tool_use"=>{
                let inp=pj(&b.input_json);
                asst_blocks.push(J::Obj(vec![("type".into(),J::Str("tool_use".into())),("id".into(),J::Str(b.id.clone())),("name".into(),J::Str(b.name.clone())),("input".into(),inp)]));
            }
            _=>{}
        }
    }

    let mut tr_blocks:Vec<J>=Vec::new();
    for (id,result,is_err) in &tool_results{
        let mut blk=vec![("type".into(),J::Str("tool_result".into())),("tool_use_id".into(),J::Str(id.clone())),("content".into(),J::Str(result.clone()))];
        if *is_err{blk.push(("is_error".into(),J::Bool(true)));}
        tr_blocks.push(J::Obj(blk));
    }

    let body2=ser(&J::Obj(vec![
        ("model".into(),J::Str(model.clone())),
        ("max_tokens".into(),J::Num(max_tokens as f64)),
        ("stream".into(),J::Bool(true)),
        ("thinking".into(),J::Obj(vec![("type".into(),J::Str("enabled".into())),("budget_tokens".into(),J::Num(thinking_budget as f64))])),
        ("system".into(),system.clone()),
        ("tools".into(),tools.clone()),
        ("messages".into(),J::Arr(vec![
            J::Obj(vec![("role".into(),J::Str("user".into())),("content".into(),prompt.clone())]),
            J::Obj(vec![("role".into(),J::Str("assistant".into())),("content".into(),J::Arr(asst_blocks))]),
            J::Obj(vec![("role".into(),J::Str("user".into())),("content".into(),J::Arr(tr_blocks))]),
        ])),
    ]));

    println!("request 2");
    let (status2,_,body_bytes2)=http_post(&host,port,&path,&body2,&api_key);
    if status2!=200{
        let eb=String::from_utf8_lossy(&body_bytes2);
        let ej=pj(&eb);
        let et=ej.get("error").and_then(|e|e.get("type")).map(|v|v.gs()).unwrap_or("");
        let em=ej.get("error").and_then(|e|e.get("message")).map(|v|v.gs()).unwrap_or("");
        println!("ERROR {} {}: {}",status2,et,em);
        std::process::exit(0);
    }

    let events2=parse_sse(&body_bytes2);
    let reply2=process_reply(&events2);
    print_blocks(&reply2.blocks);
    println!("stop_reason {}",reply2.stop_reason);

    let ti=reply1.input_tokens+reply2.input_tokens;
    let to=reply1.output_tokens+reply2.output_tokens;
    let tc=reply1.cache_read+reply2.cache_read;
    println!("usage input={} output={} cache_read={}",ti,to,tc);
}

use std::io::{Read, Write, BufReader, BufRead};
use std::net::TcpStream;
use std::collections::HashMap;

#[derive(Debug, Clone)]
enum J {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

impl J {
    fn get(&self, key: &str) -> Option<&J> {
        if let J::Obj(e) = self { e.iter().find(|(k,_)| k==key).map(|(_,v)|v) } else { None }
    }
    fn gs(&self) -> &str { if let J::Str(s)=self{s}else{""} }
    fn gn(&self) -> f64 { if let J::Num(n)=self{*n}else{0.0} }
}

struct P { ch: Vec<char>, p: usize }
impl P {
    fn new(s:&str)->Self{P{ch:s.chars().collect(),p:0}}
    fn ws(&mut self){while self.p<self.ch.len()&&matches!(self.ch[self.p],' '|'\t'|'\n'|'\r'){self.p+=1;}}
    fn parse(&mut self)->J{self.ws();self.val()}
    fn val(&mut self)->J{
        self.ws();
        match self.ch[self.p]{
            '{'=>self.obj(),
            '['=>self.arr(),
            '"'=>J::Str(self.string()),
            't'=>{self.p+=4;J::Bool(true)},
            'f'=>{self.p+=5;J::Bool(false)},
            'n'=>{self.p+=4;J::Null},
            _=>J::Num(self.num()),
        }
    }
    fn obj(&mut self)->J{
        self.p+=1;let mut e=Vec::new();self.ws();
        if self.ch[self.p]=='}'{self.p+=1;return J::Obj(e);}
        loop{
            self.ws();let k=self.string();self.ws();self.p+=1;let v=self.val();e.push((k,v));
            self.ws();
            if self.ch[self.p]==','{self.p+=1;}else{self.p+=1;break;}
        }
        J::Obj(e)
    }
    fn arr(&mut self)->J{
        self.p+=1;let mut a=Vec::new();self.ws();
        if self.ch[self.p]==']'{self.p+=1;return J::Arr(a);}
        loop{
            a.push(self.val());self.ws();
            if self.ch[self.p]==','{self.p+=1;}else{self.p+=1;break;}
        }
        J::Arr(a)
    }
    fn string(&mut self)->String{
        self.p+=1;let mut s=String::new();
        loop{
            let c=self.ch[self.p];
            if c=='"'{self.p+=1;return s;}
            if c=='\\'{
                self.p+=1;let e=self.ch[self.p];
                match e{
                    '"' =>{s.push('"');self.p+=1;}
                    '\\' =>{s.push('\\');self.p+=1;}
                    '/' =>{s.push('/');self.p+=1;}
                    'b' =>{s.push('\u{0008}');self.p+=1;}
                    'f' =>{s.push('\u{000C}');self.p+=1;}
                    'n' =>{s.push('\n');self.p+=1;}
                    'r' =>{s.push('\r');self.p+=1;}
                    't' =>{s.push('\t');self.p+=1;}
                    'u' =>{
                        self.p+=1;let cp=self.h4();
                        if cp>=0xD800&&cp<=0xDBFF{
                            if self.p+1<self.ch.len()&&self.ch[self.p]=='\\'&&self.ch[self.p+1]=='u'{
                                self.p+=2;let lo=self.h4();
                                if lo>=0xDC00&&lo<=0xDFFF{
                                    let c2=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                                    s.push(char::from_u32(c2).unwrap_or('\u{FFFD}'));
                                }else{s.push('\u{FFFD}');s.push('\u{FFFD}');}
                            }else{s.push('\u{FFFD}');}
                        }else{s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));}
                    }
                    _=>{s.push(e);self.p+=1;}
                }
            }else{s.push(c);self.p+=1;}
        }
    }
    fn h4(&mut self)->u32{
        let h:String=self.ch[self.p..self.p+4].iter().collect();self.p+=4;
        u32::from_str_radix(&h,16).unwrap_or(0)
    }
    fn num(&mut self)->f64{
        let st=self.p;
        if self.p<self.ch.len()&&self.ch[self.p]=='-'{self.p+=1;}
        while self.p<self.ch.len()&&self.ch[self.p].is_ascii_digit(){self.p+=1;}
        if self.p<self.ch.len()&&self.ch[self.p]=='.'{self.p+=1;while self.p<self.ch.len()&&self.ch[self.p].is_ascii_digit(){self.p+=1;}}
        if self.p<self.ch.len()&&(self.ch[self.p]=='e'||self.ch[self.p]=='E'){
            self.p+=1;
            if self.p<self.ch.len()&&(self.ch[self.p]=='+'||self.ch[self.p]=='-'){self.p+=1;}
            while self.p<self.ch.len()&&self.ch[self.p].is_ascii_digit(){self.p+=1;}
        }
        self.ch[st..self.p].iter().collect::<String>().parse().unwrap_or(0.0)
    }
}

fn pj(s:&str)->J{P::new(s).parse()}

fn ej(s:&str)->String{
    let mut r=String::new();
    for c in s.chars(){match c{
        '"' =>r.push_str("\\\""),
        '\\' =>r.push_str("\\\\"),
        '\n'=>r.push_str("\\n"),
        '\r'=>r.push_str("\\r"),
        '\t'=>r.push_str("\\t"),
        '\u{0008}'=>r.push_str("\\b"),
        '\u{000C}'=>r.push_str("\\f"),
        c if (c as u32)<0x20=>r.push_str(&format!("\\u{:04x}",c as u32)),
        c=>r.push(c),
    }}
    r
}

fn ser(j:&J)->String{
    match j{
        J::Null=>"null".into(),
        J::Bool(true)=>"true".into(),
        J::Bool(false)=>"false".into(),
        J::Num(n)=>{if*n==n.round()&&n.abs()<1e15{format!("{}",*n as i64)}else{format!("{}",n)}}
        J::Str(s)=>format!("\"{}\"",ej(s)),
        J::Arr(a)=>format!("[{}]",a.iter().map(ser).collect::<Vec<_>>().join(",")),
        J::Obj(e)=>format!("{{{}}}",e.iter().map(|(k,v)|format!("\"{}\":{}",ej(k),ser(v))).collect::<Vec<_>>().join(",")),
    }
}

fn esc(s:&str)->String{
    let mut r=String::new();
    for c in s.chars(){match c{
        '\\' =>r.push_str("\\\\"),
        '\n'=>r.push_str("\\n"),
        '\r'=>r.push_str("\\r"),
        '\t'=>r.push_str("\\t"),
        c=>r.push(c),
    }}
    r
}

fn parse_url(url:&str)->(String,u16,String){
    let rest=if url.starts_with("http://"){&url[7..]}else if url.starts_with("https://"){&url[8..]}else{url};
    let sl=rest.find('/').unwrap_or(rest.len());
    let hp=&rest[..sl];let path=&rest[sl..];
    if let Some(ci)=hp.rfind(':'){(hp[..ci].to_string(),hp[ci+1..].parse().unwrap(),path.to_string())}
    else{(hp.to_string(),80,path.to_string())}
}

fn http_post(host:&str,port:u16,path:&str,body:&str,api_key:&str)->(u16,HashMap<String,String>,Vec<u8>){
    let mut stream=TcpStream::connect((host,port)).unwrap();
    let req=format!("POST {} HTTP/1.1\r\nHost: {}:{}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n{}",path,host,port,body.len(),api_key,body);
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();
    let mut rd=BufReader::new(stream);
    let mut line=String::new();rd.read_line(&mut line).unwrap();
    let status:u16=line.split_whitespace().nth(1).unwrap().parse().unwrap();
    let mut hdrs=HashMap::new();
    loop{
        let mut l=String::new();rd.read_line(&mut l).unwrap();
        let t=l.trim_end_matches(|c|c=='\r'||c=='\n');
        if t.is_empty(){break;}
        let ci=t.find(':').unwrap();
        hdrs.insert(t[..ci].trim().to_lowercase(),t[ci+1..].trim().to_string());
    }
    let mut body_bytes=Vec::new();
    let te=hdrs.get("transfer-encoding").map(|s|s.to_lowercase());
    if te.as_deref()==Some("chunked"){
        loop{
            let mut sl=String::new();rd.read_line(&mut sl).unwrap();
            let sz=sl.trim_end_matches(|c|c=='\r'||c=='\n');
            let sz=sz.split(';').next().unwrap().trim();
            let size=usize::from_str_radix(sz,16).unwrap();
            if size==0{
                // read trailing CRLF (or trailer headers + CRLF)
                loop{
                    let mut tl=String::new();
                    let n=rd.read_line(&mut tl).unwrap();
                    if n==0||tl.trim_end_matches(|c|c=='\r'||c=='\n').is_empty(){break;}
                }
                break;
            }
            let mut buf=vec![0u8;size];
            rd.read_exact(&mut buf).unwrap();
            body_bytes.extend_from_slice(&buf);
            let mut crlf=[0u8;2];rd.read_exact(&mut crlf).unwrap();
        }
    }else if let Some(cl)=hdrs.get("content-length"){
        let len:usize=cl.parse().unwrap();
        body_bytes.resize(len,0);
        rd.read_exact(&mut body_bytes).unwrap();
    }
    (status,hdrs,body_bytes)
}

struct SseEv{event:String,data:String}

fn parse_sse(body:&[u8])->Vec<SseEv>{
    let text=String::from_utf8_lossy(body);
    let mut evts=Vec::new();
    let mut et=String::new();
    let mut dl:Vec<String>=Vec::new();
    for line in text.lines(){
        if line.is_empty(){
            if !et.is_empty()||!dl.is_empty(){
                evts.push(SseEv{event:et.clone(),data:dl.join("\n")});
                et.clear();dl.clear();
            }
        }else if line.starts_with(':'){}
        else if line.starts_with("event:"){
            let v=&line[6..];
            et=if v.starts_with(' '){v[1..].to_string()}else{v.to_string()};
        }else if line.starts_with("data:"){
            let v=&line[5..];
            dl.push(if v.starts_with(' '){v[1..].to_string()}else{v.to_string()});
        }
    }
    evts
}

struct BB{btype:String,thinking:String,signature:String,text:String,id:String,name:String,input_json:String}
impl BB{fn new()->Self{BB{btype:String::new(),thinking:String::new(),signature:String::new(),text:String::new(),id:String::new(),name:String::new(),input_json:String::new()}}}

struct Reply{blocks:Vec<BB>,stop_reason:String,input_tokens:u64,output_tokens:u64,cache_read:u64}

fn process_reply(events:&[SseEv])->Reply{
    let mut blocks:Vec<BB>=Vec::new();
    let mut stop_reason=String::new();
    let mut input_tokens=0u64;let mut output_tokens=0u64;let mut cache_read=0u64;
    for ev in events{
        match ev.event.as_str(){
            "message_start"=>{
                let d=pj(&ev.data);
                if let Some(msg)=d.get("message"){
                    if let Some(u)=msg.get("usage"){
                        input_tokens+=u.get("input_tokens").map(|v|v.gn() as u64).unwrap_or(0);
                        cache_read+=u.get("cache_read_input_tokens").map(|v|v.gn() as u64).unwrap_or(0);
                    }
                }
            }
            "content_block_start"=>{
                let d=pj(&ev.data);
                let idx=d.get("index").map(|v|v.gn() as usize).unwrap_or(0);
                let cb=d.get("content_block").unwrap();
                let bt=cb.get("type").map(|v|v.gs()).unwrap_or("").to_string();
                let mut b=BB::new();b.btype=bt;
                if let Some(id)=cb.get("id"){b.id=id.gs().to_string();}
                if let Some(nm)=cb.get("name"){b.name=nm.gs().to_string();}
                while blocks.len()<=idx{blocks.push(BB::new());}
                blocks[idx]=b;
            }
            "content_block_delta"=>{
                let d=pj(&ev.data);
                let idx=d.get("index").map(|v|v.gn() as usize).unwrap_or(0);
                let delta=d.get("delta").unwrap();
                let dt=delta.get("type").map(|v|v.gs()).unwrap_or("");
                match dt{
                    "thinking_delta"=>{blocks[idx].thinking.push_str(delta.get("thinking").map(|v|v.gs()).unwrap_or(""));}
                    "signature_delta"=>{blocks[idx].signature.push_str(delta.get("signature").map(|v|v.gs()).unwrap_or(""));}
                    "text_delta"=>{blocks[idx].text.push_str(delta.get("text").map(|v|v.gs()).unwrap_or(""));}
                    "input_json_delta"=>{blocks[idx].input_json.push_str(delta.get("partial_json").map(|v|v.gs()).unwrap_or(""));}
                    _=>{}
                }
            }
            "message_delta"=>{
                let d=pj(&ev.data);
                if let Some(dd)=d.get("delta"){
                    if let Some(sr)=dd.get("stop_reason"){stop_reason=sr.gs().to_string();}
                }
                if let Some(u)=d.get("usage"){
                    output_tokens+=u.get("output_tokens").map(|v|v.gn() as u64).unwrap_or(0);
                }
            }
            "message_stop"=>{}
            _=>{}
        }
    }
    Reply{blocks,stop_reason,input_tokens,output_tokens,cache_read}
}

fn run_tool(name:&str,input:&J)->(String,bool){
    match name{
        "measure"=>{
            let text=input.get("text").map(|v|v.gs()).unwrap_or("");
            let unit=input.get("unit").map(|v|v.gs()).unwrap_or("");
            match unit{
                "code_points"=>(text.chars().count().to_string(),false),
                "utf8_bytes"=>(text.len().to_string(),false),
                "utf16_units"=>(text.encode_utf16().count().to_string(),false),
                _=>(format!("unsupported unit: {}",unit),true),
            }
        }
        "reverse"=>{
            let text=input.get("text").map(|v|v.gs()).unwrap_or("");
            (text.chars().rev().collect::<String>(),false)
        }
        _=>(format!("unknown tool: {}",name),true),
    }
}

fn print_blocks(blocks:&[BB]){
    for b in blocks{
        match b.btype.as_str(){
            "thinking"=>{println!("thinking {}",esc(&b.thinking));println!("signature {}",esc(&b.signature));}
            "text"=>{println!("text {}",esc(&b.text));}
            "tool_use"=>{println!("tool_use {} {} {}",b.id,b.name,esc(&b.input_json));}
            _=>{}
        }
    }
}

