import Foundation

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let fm = FileManager.default
guard let entries = try? fm.contentsOfDirectory(atPath: dir) else { exit(1) }

let wavFiles = entries.filter { $0.hasSuffix(".wav") }.sorted { a, b in
    Array(a.utf8).lexicographicallyPrecedes(Array(b.utf8))
}

let lowFreqs: [Double] = [697, 770, 852, 941]
let highFreqs: [Double] = [1209, 1336, 1477, 1633]

let keypad: [[String]] = [
    ["1", "2", "3", "A"],
    ["4", "5", "6", "B"],
    ["7", "8", "9", "C"],
    ["*", "0", "#", "D"]
]

func readUInt16LE(_ data: [UInt8], _ offset: Int) -> Int {
    return Int(data[offset]) | (Int(data[offset + 1]) << 8)
}

func readUInt32LE(_ data: [UInt8], _ offset: Int) -> Int {
    return Int(data[offset]) | (Int(data[offset + 1]) << 8) | (Int(data[offset + 2]) << 16) | (Int(data[offset + 3]) << 24)
}

func readInt16LE(_ data: [UInt8], _ offset: Int) -> Int {
    let val = Int(data[offset]) | (Int(data[offset + 1]) << 8)
    if val >= 32768 { return val - 65536 }
    return val
}

var first = true

for name in wavFiles {
    if !first { print("") }
    first = false

    let path = dir + "/" + name
    guard let fileData = fm.contents(atPath: path) else {
        print("\(name): unsupported")
        continue
    }

    let bytes = [UInt8](fileData)

    guard bytes.count >= 12 else {
        print("\(name): unsupported")
        continue
    }
    guard bytes[0] == 0x52 && bytes[1] == 0x49 && bytes[2] == 0x46 && bytes[3] == 0x46 else {
        print("\(name): unsupported")
        continue
    }
    guard bytes[8] == 0x57 && bytes[9] == 0x41 && bytes[10] == 0x56 && bytes[11] == 0x45 else {
        print("\(name): unsupported")
        continue
    }

    // Parse chunks
    var pos = 12
    var fmtBody: [UInt8]? = nil
    var dataOffset = -1
    var dataSize = 0

    while pos + 8 <= bytes.count {
        let chunkId = String(bytes: bytes[pos..<pos+4], encoding: .ascii) ?? ""
        let chunkSize = readUInt32LE(bytes, pos + 4)
        let bodyStart = pos + 8
        let bodyEnd = bodyStart + chunkSize
        guard bodyEnd <= bytes.count else { break }

        if chunkId == "fmt " {
            fmtBody = Array(bytes[bodyStart..<bodyEnd])
        } else if chunkId == "data" {
            dataOffset = bodyStart
            dataSize = chunkSize
        }

        pos = bodyEnd
        if chunkSize % 2 == 1 { pos += 1 }
    }

    guard let fmt = fmtBody, fmt.count >= 16, dataOffset >= 0 else {
        print("\(name): unsupported")
        continue
    }

    let formatTag = readUInt16LE(fmt, 0)
    let channels = readUInt16LE(fmt, 2)
    let sampleRate = readUInt32LE(fmt, 4)
    let bitsPerSample = readUInt16LE(fmt, 14)

    var effectiveFormat = formatTag
    if formatTag == 0xFFFE {
        guard fmt.count >= 26 else {
            print("\(name): unsupported")
            continue
        }
        effectiveFormat = readUInt16LE(fmt, 24)
    }

    guard effectiveFormat == 1 && bitsPerSample == 16 &&
          (channels == 1 || channels == 2) &&
          (sampleRate == 8000 || sampleRate == 16000) else {
        print("\(name): unsupported")
        continue
    }

    let totalFrames = dataSize / (2 * channels)
    let N = sampleRate / 50
    let numBlocks = totalFrames / N

    // Extract left channel samples
    var samples = [Int](repeating: 0, count: totalFrames)
    for i in 0..<totalFrames {
        let offset = dataOffset + i * 2 * channels
        samples[i] = readInt16LE(bytes, offset)
    }

    // Process blocks
    var labels = [String?](repeating: nil, count: numBlocks)

    for block in 0..<numBlocks {
        let startIdx = block * N

        // Energy
        var E: Double = 0
        for n in 0..<N {
            let x = Double(samples[startIdx + n])
            E += x * x
        }

        if E < 1000000.0 * Double(N) {
            continue
        }

        // Goertzel
        func goertzel(_ f: Double) -> Double {
            let c = 2.0 * cos(2.0 * Double.pi * f / Double(sampleRate))
            var s1 = 0.0
            var s2 = 0.0
            for n in 0..<N {
                let s = Double(samples[startIdx + n]) + c * s1 - s2
                s2 = s1
                s1 = s
            }
            return s1 * s1 + s2 * s2 - c * s1 * s2
        }

        var maxLowR: Double = -1
        var maxLowIdx = 0
        var maxHighR: Double = -1
        var maxHighIdx = 0

        for i in 0..<4 {
            let P = goertzel(lowFreqs[i])
            let r = 2.0 * P / (Double(N) * E)
            if r > maxLowR {
                maxLowR = r
                maxLowIdx = i
            }
        }

        for i in 0..<4 {
            let P = goertzel(highFreqs[i])
            let r = 2.0 * P / (Double(N) * E)
            if r > maxHighR {
                maxHighR = r
                maxHighIdx = i
            }
        }

        if maxLowR >= 0.1 && maxHighR >= 0.1 && maxLowR + maxHighR >= 0.6 {
            labels[block] = keypad[maxLowIdx][maxHighIdx]
        }
    }

    // Bridging (use original labels for neighbor checks)
    var bridged = labels
    if numBlocks >= 3 {
        for i in 1..<numBlocks - 1 {
            if labels[i] == nil {
                if let prev = labels[i - 1], let next = labels[i + 1], prev == next {
                    bridged[i] = prev
                }
            }
        }
    }

    // Events
    var events: [(String, Int, Int)] = []
    var i = 0
    while i < numBlocks {
        guard let d = bridged[i] else { i += 1; continue }
        var j = i + 1
        while j < numBlocks && bridged[j] == d { j += 1 }
        if j - i >= 2 {
            events.append((d, 20 * i, 20 * j))
        }
        i = j
    }

    // Output
    print("\(name): \(sampleRate) Hz, \(channels) ch, \(numBlocks) blocks")
    for (digit, start, end) in events {
        print("\(digit) \(start) \(end)")
    }
    let allDigits = events.map { $0.0 }.joined()
    print("digits: \(allDigits)")
}

import sys
import struct
import zlib
import re
from decimal import Decimal


def read_file(path):
    with open(path, 'rb') as f:
        return f.read()


def read_uint16(data, offset):
    return struct.unpack_from('>H', data, offset)[0]


def read_uint32(data, offset):
    return struct.unpack_from('>I', data, offset)[0]


def read_varint(data, offset):
    """Read a SQLite varint (1-9 bytes). Returns (value, bytes_consumed)."""
    result = 0
    for i in range(9):
        b = data[offset + i]
        if i == 8:
            result = (result << 8) | b
            # Interpret as signed 64-bit integer
            if result >= (1 << 63):
                result -= (1 << 64)
            return result, 9
        result = (result << 7) | (b & 0x7F)
        if b < 0x80:
            return result, i + 1


def parse_page_header(data, page_num, page_size, reserved):
    """Parse the b-tree page header."""
    offset = 100 if page_num == 1 else 0
    page_type = data[offset]
    first_freeblock = read_uint16(data, offset + 1)
    num_cells = read_uint16(data, offset + 3)
    cell_content_start = read_uint16(data, offset + 5)
    fragmented_free = data[offset + 7]

    rightmost = None
    if page_type in (1, 2):  # interior pages (index or table)
        rightmost = read_uint32(data, offset + 8)

    return page_type, first_freeblock, num_cells, cell_content_start, fragmented_free, rightmost


def get_cell_offsets(data, page_num, page_size, reserved):
    """Get the cell pointer array."""
    offset = 100 if page_num == 1 else 0
    page_type, _, num_cells, _, _, _ = parse_page_header(data, page_num, page_size, reserved)

    cell_array_start = offset + 8
    if page_type in (1, 2):
        cell_array_start = offset + 12  # 8 bytes header + 4 bytes rightmost pointer

    offsets = []
    for i in range(num_cells):
        cell_off = read_uint16(data, cell_array_start + i * 2)
        offsets.append(cell_off)
    return offsets


def read_overflow(data, page_size, reserved, payload_size, embedded_size, overflow_page):
    """Read overflow payload, following overflow chain."""
    if overflow_page == 0:
        return b''

    payload = b''
    pg = overflow_page
    remaining = payload_size - embedded_size

    while pg != 0 and remaining > 0:
        page_start = (pg - 1) * page_size
        usable = page_size - reserved
        next_page = read_uint32(data, page_start)
        chunk_size = min(remaining, usable - 4)
        payload += data[page_start + 4: page_start + 4 + chunk_size]
        remaining -= chunk_size
        pg = next_page

    return payload


def parse_record(data, offset, payload_size):
    """Parse a record (payload) starting at offset. Returns list of (serial_type, value)."""
    # Read header size
    header_size, n = read_varint(data, offset)

    # Read serial types
    serial_types = []
    pos = offset + n
    header_end = offset + header_size

    while pos < header_end:
        st, n = read_varint(data, pos)
        serial_types.append(st)
        pos += n

    # Read values
    values = []
    val_offset = header_end

    for st in serial_types:
        if st == 0:
            values.append((st, None))
        elif st == 1:
            values.append((st, struct.unpack_from('>b', data, val_offset)[0]))
            val_offset += 1
        elif st == 2:
            values.append((st, struct.unpack_from('>h', data, val_offset)[0]))
            val_offset += 2
        elif st == 3:
            val = (data[val_offset] << 16) | (data[val_offset + 1] << 8) | data[val_offset + 2]
            if val >= 0x800000:
                val -= 0x1000000
            values.append((st, val))
            val_offset += 3
        elif st == 4:
            values.append((st, struct.unpack_from('>i', data, val_offset)[0]))
            val_offset += 4
        elif st == 5:
            val = struct.unpack_from('>q', b'\x00\x00' + data[val_offset:val_offset + 6])[0]
            values.append((st, val))
            val_offset += 6
        elif st == 6:
            values.append((st, struct.unpack_from('>q', data, val_offset)[0]))
            val_offset += 8
        elif st == 7:
            values.append((st, struct.unpack_from('>d', data, val_offset)[0]))
            val_offset += 8
        elif st == 8:
            values.append((st, 0))
        elif st == 9:
            values.append((st, 1))
        elif st >= 12 and st % 2 == 0:
            blob_len = (st - 12) // 2
            values.append((st, data[val_offset:val_offset + blob_len]))
            val_offset += blob_len
        elif st >= 13 and st % 2 == 1:
            text_len = (st - 13) // 2
            values.append((st, data[val_offset:val_offset + text_len]))
            val_offset += text_len
        else:
            values.append((st, None))

    return values


def read_leaf_table_page(data, page_num, page_size, reserved):
    """Read all rows from a leaf table b-tree page. Returns list of (rowid, payload_bytes)."""
    offsets = get_cell_offsets(data, page_num, page_size, reserved)
    rows = []

    U = page_size - reserved
    X = U - 35
    M = ((U - 12) * 32 // 255) - 23

    for cell_off in offsets:
        # Read payload size
        payload_size, n = read_varint(data, cell_off)
        pos = cell_off + n
        # Read rowid
        rowid, n = read_varint(data, pos)
        pos += n

        # Determine embedded size
        if payload_size <= X:
            embedded = payload_size
            overflow = 0
        else:
            K = M + ((payload_size - M) % (U - 4))
            if K > X:
                K = M
            embedded = K
            overflow = read_uint32(data, pos + embedded)

        # Read embedded payload
        embedded_data = data[pos:pos + embedded]

        # Read overflow if any
        if overflow != 0:
            overflow_data = read_overflow(data, page_size, reserved, payload_size, embedded, overflow)
            full_payload = embedded_data + overflow_data
        else:
            full_payload = embedded_data

        rows.append((rowid, full_payload))

    return rows


def read_table_btree(data, root_page, page_size, reserved, freelist_pages):
    """Walk a table b-tree and return all rows as (rowid, payload_bytes)."""
    rows = []
    stack = [root_page]

    while stack:
        pg = stack.pop()
        if pg in freelist_pages:
            continue

        page_type, _, num_cells, _, _, rightmost = parse_page_header(data, pg, page_size, reserved)

        if page_type == 2:  # Interior table b-tree
            offsets = get_cell_offsets(data, pg, page_size, reserved)
            # Add rightmost child
            if rightmost != 0 and rightmost not in freelist_pages:
                stack.append(rightmost)
            # Add children from cells
            for cell_off in offsets:
                child_page = read_uint32(data, cell_off)
                if child_page not in freelist_pages:
                    stack.append(child_page)
        elif page_type == 13:  # Leaf table b-tree
            page_rows = read_leaf_table_page(data, pg, page_size, reserved)
            rows.extend(page_rows)

    return rows


def get_freelist_pages(data, page_size, reserved):
    """Get set of all freelist page numbers."""
    freelist = set()

    trunk_page = read_uint32(data, 32)
    total_free = read_uint32(data, 36)

    while trunk_page != 0:
        if trunk_page in freelist:
            break
        freelist.add(trunk_page)

        page_start = (trunk_page - 1) * page_size
        next_trunk = read_uint32(data, page_start)
        num_leaves = read_uint32(data, page_start + 4)

        usable = page_size - reserved
        max_leaves = (usable - 8) // 4

        for i in range(min(num_leaves, max_leaves)):
            leaf_page = read_uint32(data, page_start + 8 + i * 4)
            if leaf_page != 0:
                freelist.add(leaf_page)

        trunk_page = next_trunk

    return freelist


def parse_create_table(sql):
    """Parse CREATE TABLE to get column names and INTEGER PRIMARY KEY info."""
    # Find the first '(' which starts column definitions
    i = 0
    while i < len(sql):
        if sql[i] == '(':
            break
        i += 1

    defs_start = i + 1
    # Find matching ')'
    depth = 1
    j = defs_start
    while j < len(sql) and depth > 0:
        if sql[j] == '(':
            depth += 1
        elif sql[j] == ')':
            depth -= 1
        j += 1

    defs_str = sql[defs_start:j - 1]

    # Split by commas not inside parentheses
    columns = []
    depth = 0
    current = ''
    for ch in defs_str:
        if ch == '(':
            depth += 1
            current += ch
        elif ch == ')':
            depth -= 1
            current += ch
        elif ch == ',' and depth == 0:
            columns.append(current.strip())
            current = ''
        else:
            current += ch
    if current.strip():
        columns.append(current.strip())

    result = []
    for col_def in columns:
        col_def = col_def.strip()
        if not col_def:
            continue

        # Extract column name (first token)
        if col_def.startswith('"'):
            end_quote = col_def.index('"', 1)
            name = col_def[1:end_quote]
            rest = col_def[end_quote + 1:].strip()
        else:
            name = ''
            idx = 0
            for ch in col_def:
                if ch.isalnum() or ch == '_':
                    name += ch
                    idx += 1
                else:
                    break
            rest = col_def[idx:].strip()

        # Check if type is exactly "INTEGER" (single word, case-insensitive) and PRIMARY KEY is present
        is_rowid_alias = False
        type_word = ''
        for ch in rest:
            if ch.isalpha():
                type_word += ch
            else:
                break

        if type_word.upper() == 'INTEGER':
            upper_rest = rest.upper()
            if re.search(r'\bPRIMARY\s+KEY\b', upper_rest):
                is_rowid_alias = True

        result.append((name, is_rowid_alias))

    return result


def format_real(f):
    """Format a REAL value as exact decimal."""
    d = Decimal(f)
    s = format(d, 'f')
    if '.' not in s:
        s += '.0'
    else:
        s = s.rstrip('0')
        if s.endswith('.'):
            s += '0'
    return s


def format_text(data):
    """Format TEXT bytes for output."""
    text = data.decode('utf-8')
    result = []
    for ch in text:
        cp = ord(ch)
        if cp == 0x5C:
            result.append('\\\\')
        elif cp == 0x22:
            result.append('\\"')
        elif cp == 0x0A:
            result.append('\\n')
        elif cp == 0x0D:
            result.append('\\r')
        elif cp == 0x09:
            result.append('\\t')
        elif cp < 0x20 or cp == 0x7F:
            result.append('\\x{:02X}'.format(cp))
        else:
            result.append(ch)
    return '"' + ''.join(result) + '"'


def format_value(serial_type, value):
    """Format a value for output based on its serial type."""
    if serial_type == 0:
        return 'NULL'
    elif serial_type in (1, 2, 3, 4, 5, 6, 8, 9):
        return str(value)
    elif serial_type == 7:
        return format_real(value)
    elif serial_type >= 12 and serial_type % 2 == 0:
        # BLOB
        data = value
        if len(data) <= 100:
            hex_str = data.hex().upper()
            return "X'" + hex_str + "'"
        else:
            crc = zlib.crc32(data) & 0xFFFFFFFF
            return "<BLOB len={} crc32={:08x}>".format(len(data), crc)
    elif serial_type >= 13 and serial_type % 2 == 1:
        # TEXT
        data = value
        if len(data) <= 100:
            return format_text(data)
        else:
            crc = zlib.crc32(data) & 0xFFFFFFFF
            return "<TEXT len={} crc32={:08x}>".format(len(data), crc)
    else:
        return 'NULL'


def main():
    db_path = sys.argv[1] + '/db.sqlite'
    data = read_file(db_path)

    # Read file header
    page_size = read_uint16(data, 16)
    if page_size == 1:
        page_size = 65536
    reserved = data[20]

    # Get freelist pages
    freelist_pages = get_freelist_pages(data, page_size, reserved)

    # Read schema (rooted at page 1)
    schema_rows = read_table_btree(data, 1, page_size, reserved, freelist_pages)

    # Parse schema rows to find tables
    tables = []
    for rowid, payload in schema_rows:
        values = parse_record(payload, 0, len(payload))
        # Schema columns: type, name, tbl_name, rootpage, sql
        row_type = values[0][1].decode('utf-8') if len(values) > 0 and values[0][0] >= 13 else ''
        row_name = values[1][1].decode('utf-8') if len(values) > 1 and values[1][0] >= 13 else ''
        row_rootpage = values[3][1] if len(values) > 3 else 0

        if row_type == 'table' and not row_name.startswith('sqlite_'):
            row_sql = values[4][1].decode('utf-8') if len(values) > 4 and values[4][0] >= 13 else ''
            tables.append((row_name, row_rootpage, row_sql))

    # Sort by name (byte-wise ascending)
    tables.sort(key=lambda x: x[0].encode('utf-8'))

    # Process each table
    first = True
    for name, rootpage, sql_text in tables:
        if not first:
            print()
        first = False

        # Parse columns from CREATE TABLE
        columns = parse_create_table(sql_text)

        # Read all rows from table b-tree
        rows = read_table_btree(data, rootpage, page_size, reserved, freelist_pages)

        # Sort by rowid
        rows.sort(key=lambda x: x[0])

        print("TABLE {} rows={}".format(name, len(rows)))
