#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <dirent.h>
#include <stdint.h>

static uint32_t read_u32(const unsigned char *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static uint16_t read_u16(const unsigned char *p) {
    return (uint16_t)p[0] | ((uint16_t)p[1] << 8);
}

static int16_t read_i16(const unsigned char *p) {
    return (int16_t)(p[0] | (p[1] << 8));
}

static const double low_freqs[4] = {697.0, 770.0, 852.0, 941.0};
static const double high_freqs[4] = {1209.0, 1336.0, 1477.0, 1633.0};

static const char keypad[4][4] = {
    {'1', '2', '3', 'A'},
    {'4', '5', '6', 'B'},
    {'7', '8', '9', 'C'},
    {'*', '0', '#', 'D'}
};

static double goertzel(const int16_t *x, int N, double rate, double freq) {
    double c = 2.0 * cos(2.0 * M_PI * freq / rate);
    double s1 = 0.0, s2 = 0.0;
    for (int n = 0; n < N; n++) {
        double s = (double)x[n] + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    return s1 * s1 + s2 * s2 - c * s1 * s2;
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

int main(int argc, char *argv[]) {
    if (argc < 2) return 1;

    const char *dir = argv[1];
    DIR *d = opendir(dir);
    if (!d) return 1;

    char **files = NULL;
    int nfiles = 0;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        const char *name = ent->d_name;
        size_t len = strlen(name);
        if (len >= 4 && strcmp(name + len - 4, ".wav") == 0) {
            files = realloc(files, (nfiles + 1) * sizeof(char *));
            files[nfiles++] = strdup(name);
        }
    }
    closedir(d);

    if (nfiles > 0)
        qsort(files, nfiles, sizeof(char *), cmp_str);

    for (int fi = 0; fi < nfiles; fi++) {
        if (fi > 0) printf("\n");

        const char *name = files[fi];

        char path[4096];
        snprintf(path, sizeof(path), "%s/%s", dir, name);
        FILE *fp = fopen(path, "rb");
        if (!fp) {
            printf("%s: unsupported\n", name);
            continue;
        }

        fseek(fp, 0, SEEK_END);
        long fsize = ftell(fp);
        fseek(fp, 0, SEEK_SET);

        unsigned char *buf = (unsigned char *)malloc(fsize);
        if (!buf) { fclose(fp); printf("%s: unsupported\n", name); continue; }
        fread(buf, 1, fsize, fp);
        fclose(fp);

        if (fsize < 12 || memcmp(buf, "RIFF", 4) != 0 || memcmp(buf + 8, "WAVE", 4) != 0) {
            printf("%s: unsupported\n", name);
            free(buf);
            continue;
        }

        int fmt_found = 0, data_found = 0;
        unsigned char *fmt_body = NULL;
        int fmt_size = 0;
        unsigned char *data_body = NULL;
        int data_size = 0;

        long pos = 12;
        while (pos + 8 <= fsize) {
            uint32_t chunk_size = read_u32(buf + pos + 4);
            long body_start = pos + 8;

            if (memcmp(buf + pos, "fmt ", 4) == 0) {
                fmt_body = buf + body_start;
                fmt_size = (int)chunk_size;
                fmt_found = 1;
            } else if (memcmp(buf + pos, "data", 4) == 0) {
                data_body = buf + body_start;
                data_size = (int)chunk_size;
                data_found = 1;
            }

            long next = body_start + (long)chunk_size;
            if (chunk_size % 2 != 0) next++;
            pos = next;
        }

        if (!fmt_found || !data_found || fmt_size < 16) {
            printf("%s: unsupported\n", name);
            free(buf);
            continue;
        }

        uint16_t format_tag = read_u16(fmt_body);
        uint16_t channels = read_u16(fmt_body + 2);
        uint32_t rate = read_u32(fmt_body + 4);
        uint16_t bits = read_u16(fmt_body + 14);

        uint16_t effective_format = format_tag;
        if (format_tag == 0xFFFE && fmt_size >= 26) {
            effective_format = read_u16(fmt_body + 24);
        }

        if (effective_format != 1 || bits != 16) {
            printf("%s: unsupported\n", name);
            free(buf);
            continue;
        }

        if (channels != 1 && channels != 2) {
            printf("%s: unsupported\n", name);
            free(buf);
            continue;
        }

        if (rate != 8000 && rate != 16000) {
            printf("%s: unsupported\n", name);
            free(buf);
            continue;
        }

        int N = (int)rate / 50;
        int total_frames = data_size / (2 * (int)channels);
        int blocks = total_frames / N;

        printf("%s: %u Hz, %u ch, %d blocks\n", name, rate, channels, blocks);

        /* Extract left channel */
        int16_t *left = (int16_t *)malloc(total_frames * sizeof(int16_t));
        int bytes_per_frame = 2 * (int)channels;
        for (int i = 0; i < total_frames; i++) {
            left[i] = read_i16(data_body + i * bytes_per_frame);
        }

        /* Step 3: detect digit per block */
        int *labels = (int *)malloc(blocks * sizeof(int));

        for (int b = 0; b < blocks; b++) {
            const int16_t *blk = left + b * N;

            double E = 0.0;
            for (int n = 0; n < N; n++) {
                double v = (double)blk[n];
                E += v * v;
            }

            if (E < 1000000.0 * (double)N) {
                labels[b] = -1;
                continue;
            }

            double r_low[4], r_high[4];
            for (int i = 0; i < 4; i++) {
                double P = goertzel(blk, N, (double)rate, low_freqs[i]);
                r_low[i] = 2.0 * P / ((double)N * E);
            }
            for (int i = 0; i < 4; i++) {
                double P = goertzel(blk, N, (double)rate, high_freqs[i]);
                r_high[i] = 2.0 * P / ((double)N * E);
            }

            int best_low = 0, best_high = 0;
            for (int i = 1; i < 4; i++) {
                if (r_low[i] > r_low[best_low]) best_low = i;
                if (r_high[i] > r_high[best_high]) best_high = i;
            }

            if (r_low[best_low] >= 0.1 && r_high[best_high] >= 0.1 &&
                r_low[best_low] + r_high[best_high] >= 0.6) {
                labels[b] = best_low * 4 + best_high;
            } else {
                labels[b] = -1;
            }
        }

        /* Step 4: bridging (use original labels for neighbor checks) */
        int *bridged = (int *)malloc(blocks * sizeof(int));
        memcpy(bridged, labels, blocks * sizeof(int));
        for (int b = 1; b < blocks - 1; b++) {
            if (labels[b] == -1 && labels[b - 1] != -1 && labels[b + 1] != -1 &&
                labels[b - 1] == labels[b + 1]) {
                bridged[b] = labels[b - 1];
            }
        }

        /* Step 5: events */
        char digits[65536];
        int dpos = 0;

        int b = 0;
        while (b < blocks) {
            if (bridged[b] == -1) { b++; continue; }
            int d = bridged[b];
            int start = b;
            while (b < blocks && bridged[b] == d) b++;
            int end = b; /* exclusive */
            if (end - start >= 2) {
                char ch = keypad[d / 4][d % 4];
                printf("%c %d %d\n", ch, 20 * start, 20 * end);
                digits[dpos++] = ch;
            }
        }
        digits[dpos] = '\0';
        printf("digits: %s\n", digits);

        free(left);
        free(labels);
        free(bridged);
        free(buf);
    }

    for (int i = 0; i < nfiles; i++) free(files[i]);
    free(files);

    return 0;
}

