import * as fs from 'fs';
import * as path from 'path';

const dir = process.argv[2];

// Find all .wav files, sort by byte-wise ascending order of filename
const entries = fs.readdirSync(dir);
const wavFiles = entries.filter(name => name.endsWith('.wav')).sort((a, b) => {
  const bufA = Buffer.from(a, 'utf-8');
  const bufB = Buffer.from(b, 'utf-8');
  return bufA.compare(bufB);
});

const LOW_FREQS = [697, 770, 852, 941];
const HIGH_FREQS = [1209, 1336, 1477, 1633];

const KEYPAD: string[][] = [
  ['1', '2', '3', 'A'],
  ['4', '5', '6', 'B'],
  ['7', '8', '9', 'C'],
  ['*', '0', '#', 'D'],
];

function parseWav(filePath: string): { rate: number; channels: number; samples: number[] } | null {
  const buf = fs.readFileSync(filePath);

  if (buf.length < 12) return null;
  if (buf.toString('ascii', 0, 4) !== 'RIFF') return null;
  if (buf.toString('ascii', 8, 12) !== 'WAVE') return null;

  let offset = 12;
  let fmtBody: Buffer | null = null;
  let dataBody: Buffer | null = null;

  while (offset + 8 <= buf.length) {
    const chunkId = buf.toString('ascii', offset, offset + 4);
    const chunkSize = buf.readUInt32LE(offset + 4);
    const bodyStart = offset + 8;

    if (chunkId === 'fmt ') {
      fmtBody = buf.subarray(bodyStart, bodyStart + chunkSize);
    } else if (chunkId === 'data') {
      dataBody = buf.subarray(bodyStart, bodyStart + chunkSize);
    }

    offset = bodyStart + chunkSize;
    if (chunkSize % 2 !== 0) offset++; // pad byte
  }

  if (!fmtBody || !dataBody) return null;

  const formatTag = fmtBody.readUInt16LE(0);
  const channels = fmtBody.readUInt16LE(2);
  const rate = fmtBody.readUInt32LE(4);
  const bitsPerSample = fmtBody.readUInt16LE(14);

  let effectiveFormat = formatTag;
  if (formatTag === 0xFFFE && fmtBody.length > 16) {
    effectiveFormat = fmtBody.readUInt16LE(24);
  }

  // Check support
  if (effectiveFormat !== 1) return null;
  if (bitsPerSample !== 16) return null;
  if (channels !== 1 && channels !== 2) return null;
  if (rate !== 8000 && rate !== 16000) return null;

  // Extract left channel samples
  const bytesPerFrame = 2 * channels;
  const numFrames = Math.floor(dataBody.length / bytesPerFrame);

  const samples: number[] = [];
  for (let i = 0; i < numFrames; i++) {
    samples.push(dataBody.readInt16LE(i * bytesPerFrame));
  }

  return { rate, channels, samples };
}

function goertzelPower(x: number[], f: number, rate: number, N: number): number {
  const c = 2 * Math.cos(2 * Math.PI * f / rate);
  let s1 = 0.0;
  let s2 = 0.0;
  for (let n = 0; n < N; n++) {
    const s = x[n] + c * s1 - s2;
    s2 = s1;
    s1 = s;
  }
  return s1 * s1 + s2 * s2 - c * s1 * s2;
}

function processFile(name: string, filePath: string): string {
  const result = parseWav(filePath);
  if (!result) {
    return `${name}: unsupported`;
  }

  const { rate, channels, samples } = result;
  const N = rate / 50; // 160 at 8000, 320 at 16000
  const numBlocks = Math.floor(samples.length / N);

  // Step 3: detect digit per block
  const labels: (string | null)[] = [];

  for (let i = 0; i < numBlocks; i++) {
    const blockStart = i * N;

    // Energy
    let E = 0;
    for (let n = 0; n < N; n++) {
      const v = samples[blockStart + n];
      E += v * v;
    }

    if (E < 1000000 * N) {
      labels.push(null);
      continue;
    }

    // Goertzel for all 8 frequencies
    const rLow: number[] = [];
    const rHigh: number[] = [];

    for (const f of LOW_FREQS) {
      const P = goertzelPower(samples, f, rate, N);
      // Need to pass the block starting at blockStart
      rLow.push(2 * P / (N * E));
    }
    for (const f of HIGH_FREQS) {
      const P = goertzelPower(samples, f, rate, N);
      rHigh.push(2 * P / (N * E));
    }

    // Find max in low and high groups
    let maxLowIdx = 0;
    let maxLowR = rLow[0];
    for (let j = 1; j < 4; j++) {
      if (rLow[j] > maxLowR) { maxLowR = rLow[j]; maxLowIdx = j; }
    }

    let maxHighIdx = 0;
    let maxHighR = rHigh[0];
    for (let j = 1; j < 4; j++) {
      if (rHigh[j] > maxHighR) { maxHighR = rHigh[j]; maxHighIdx = j; }
    }

    // Check thresholds
    if (maxLowR >= 0.1 && maxHighR >= 0.1 && maxLowR + maxHighR >= 0.6) {
      labels.push(KEYPAD[maxLowIdx][maxHighIdx]);
    } else {
      labels.push(null);
    }
  }

  // Step 4: Bridging - use original labels for decisions
  const bridged: (string | null)[] = [...labels];
  for (let i = 1; i < numBlocks - 1; i++) {
    if (labels[i] === null && labels[i - 1] !== null && labels[i + 1] !== null && labels[i - 1] === labels[i + 1]) {
      bridged[i] = labels[i - 1];
    }
  }

  // Step 5: Events - maximal runs of same digit, length >= 2
  const events: { digit: string; start: number; end: number }[] = [];
  let i = 0;
  while (i < numBlocks) {
    if (bridged[i] !== null) {
      let j = i;
      while (j < numBlocks && bridged[j] === bridged[i]) {
        j++;
      }
      const runLength = j - i;
      if (runLength >= 2) {
        events.push({
          digit: bridged[i]!,
          start: 20 * i,
          end: 20 * j,
        });
      }
      i = j;
    } else {
      i++;
    }
  }

  // Build output
  const lines: string[] = [];
  lines.push(`${name}: ${rate} Hz, ${channels} ch, ${numBlocks} blocks`);
  for (const ev of events) {
    lines.push(`${ev.digit} ${ev.start} ${ev.end}`);
  }
  lines.push(`digits: ${events.map(e => e.digit).join('')}`);

  return lines.join('\n');
}

// Process all files
const outputs: string[] = [];
for (const name of wavFiles) {
  const filePath = path.join(dir, name);
  outputs.push(processFile(name, filePath));
}

if (outputs.length > 0) {
  console.log(outputs.join('\n\n'));
}

