import Foundation
import Darwin

// ============ JSON Types ============

struct RS { let v: String; let raw: String }

enum JV {
    case nul
    case blb(Bool)
    case ino(Int)
    case flo(Double)
    case str(RS)
    case arr([JV])
    case obj([(String, JV)])
}

// ============ JSON Parser ============

final class JP {
    let c: [Character]
    var i: Int = 0
    init(_ s: String) { c = Array(s) }

    func ws() { while i < c.count && c[i].isWhitespace { i += 1 } }
    func pk() -> Character? { i < c.count ? c[i] : nil }
    func eat(_ x: Character) { guard i < c.count && c[i] == x else { fatalError("eat \(x)") }; i += 1 }

    func val() -> JV {
        ws()
        guard let x = pk() else { fatalError("EOF") }
        switch x {
        case "n": i += 4; return .nul
        case "t": i += 4; return .blb(true)
        case "f": i += 5; return .blb(false)
        case "\"": return .str(str())
        case "[": return arr()
        case "{": return obj()
        default:
            if x == "-" || x.isNumber { return num() }
            fatalError("bad \(x)")
        }
    }

    func str() -> RS {
        let s = i; eat("\"")
        var d = ""
        while i < c.count && c[i] != "\"" {
            if c[i] == "\\" {
                i += 1; guard i < c.count else { fatalError("EOFstr") }
                let e = c[i]
                switch e {
                case "\"": d.append("\""); i += 1
                case "\\": d.append("\\"); i += 1
                case "/": d.append("/"); i += 1
                case "b": d.append("\u{0008}"); i += 1
                case "f": d.append("\u{000C}"); i += 1
                case "n": d.append("\n"); i += 1
                case "r": d.append("\r"); i += 1
                case "t": d.append("\t"); i += 1
                case "u":
                    i += 1
                    let h = hex4()
                    if h >= 0xD800 && h <= 0xDBFF {
                        eat("\\"); eat("u")
                        let l = hex4()
                        let cp = 0x10000 + ((h - 0xD800) << 10) + (l - 0xDC00)
                        d.append(Character(UnicodeScalar(cp)!))
                    } else {
                        d.append(Character(UnicodeScalar(h)!))
                    }
                default: fatalError("esc \\(e)")
                }
            } else { d.append(c[i]); i += 1 }
        }
        eat("\"")
        return RS(v: d, raw: String(c[s..<i]))
    }

    func hex4() -> Int {
        var v = 0
        for _ in 0..<4 { guard i < c.count, let d = c[i].hexDigitValue else { fatalError("hex") }; v = v*16+d; i += 1 }
        return v
    }

    func num() -> JV {
        let s = i
        if i < c.count && c[i] == "-" { i += 1 }
        while i < c.count && c[i].isNumber { i += 1 }
        var f = false
        if i < c.count && c[i] == "." { f = true; i += 1; while i < c.count && c[i].isNumber { i += 1 } }
        if i < c.count && (c[i] == "e" || c[i] == "E") { f = true; i += 1; if i < c.count && (c[i] == "+" || c[i] == "-") { i += 1 }; while i < c.count && c[i].isNumber { i += 1 } }
        let t = String(c[s..<i])
        return f ? .flo(Double(t)!) : .ino(Int(t)!)
    }

    func arr() -> JV {
        eat("["); var a: [JV] = []; ws()
        if pk() == "]" { i += 1; return .arr(a) }
        while true { a.append(val()); ws(); if pk() == "," { i += 1; continue }; if pk() == "]" { i += 1; break }; fatalError("arr") }
        return .arr(a)
    }

    func obj() -> JV {
        eat("{"); var p: [(String, JV)] = []; ws()
        if pk() == "}" { i += 1; return .obj(p) }
        while true { ws(); let k = str().v; ws(); eat(":"); let v = val(); p.append((k,v)); ws(); if pk() == "," { i += 1; continue }; if pk() == "}" { i += 1; break }; fatalError("obj") }
        return .obj(p)
    }

    func objPos() -> [(String, JV, Int, Int)] {
        eat("{"); var p: [(String, JV, Int, Int)] = []; ws()
        if pk() == "}" { i += 1; return p }
        while true { ws(); let k = str().v; ws(); eat(":"); ws(); let vs = i; let v = val(); let ve = i; p.append((k,v,vs,ve)); ws(); if pk() == "," { i += 1; continue }; if pk() == "}" { i += 1; break }; fatalError("objPos") }
        return p
    }
}

func pj(_ s: String) -> JV { JP(s).val() }

func gv(_ v: JV, _ k: String) -> JV? {
    if case .obj(let ps) = v { for (kk,vv) in ps { if kk == k { return vv } } }
    return nil
}
func gs(_ v: JV) -> String { if case .str(let r) = v { return r.v }; fatalError("notstr") }
func gi(_ v: JV) -> Int { if case .ino(let n) = v { return n }; if case .flo(let d) = v { return Int(d) }; fatalError("notint") }

// ============ JSON String Escaping ============

func esc(_ s: String) -> String {
    var r = "\""
    for ch in s.unicodeScalars {
        switch ch {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\u{0008}": r += "\\b"
        case "\u{000C}": r += "\\f"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default:
            if ch.value < 0x20 { r += String(format: "\\u%04x", ch.value) }
            else { r.append(Character(ch)) }
        }
    }
    r += "\""
    return r
}

// ============ CSV Parser ============

func parseCSV(_ text: String) -> [[String]] {
    var s = text
    if s.hasPrefix("\u{FEFF}") { s = String(s.dropFirst()) }
    let ch = Array(s)
    var recs: [[String]] = []
    var i = 0
    while i < ch.count {
        var fields: [String] = []
        while true {
            var f = ""
            if i < ch.count && ch[i] == "\"" {
                i += 1
                while i < ch.count {
                    if ch[i] == "\"" {
                        if i+1 < ch.count && ch[i+1] == "\"" { f.append("\""); i += 2 }
                        else { i += 1; break }
                    } else { f.append(ch[i]); i += 1 }
                }
            } else {
                while i < ch.count && ch[i] != "," && ch[i] != "\r" && ch[i] != "\n" { f.append(ch[i]); i += 1 }
            }
            fields.append(f)
            if i < ch.count && ch[i] == "," { i += 1; continue }
            if i < ch.count && ch[i] == "\r" { i += 1; if i < ch.count && ch[i] == "\n" { i += 1 } }
            else if i < ch.count && ch[i] == "\n" { i += 1 }
            break
        }
        recs.append(fields)
    }
    return recs
}

// ============ HTTP Client ============

func writeAll(_ fd: Int32, _ data: Data) {
    var off = 0
    data.withUnsafeBytes { buf in
        while off < buf.count {
            let n = write(fd, buf.baseAddress! + off, buf.count - off)
            if n <= 0 { fatalError("write") }
            off += n
        }
    }
}

func httpPost(host: String, port: Int, path: String, body: String, apiKey: String) -> (Int, String) {
    let fd = socket(AF_INET, SOCK_STREAM, 0)
    guard fd >= 0 else { fatalError("socket") }
    defer { close(fd) }

    var tv = timeval(tv_sec: 60, tv_usec: 0)
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, socklen_t(MemoryLayout<timeval>.size))
    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, socklen_t(MemoryLayout<timeval>.size))

    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = in_port_t(port).bigEndian

    if inet_pton(AF_INET, host, &addr.sin_addr) != 1 {
        var hints = addrinfo(ai_flags: 0, ai_family: AF_INET, ai_socktype: SOCK_STREAM, ai_protocol: IPPROTO_TCP, ai_addrlen: 0, ai_canonname: nil, ai_addr: nil, ai_next: nil)
        var res: UnsafeMutablePointer<addrinfo>?
        guard getaddrinfo(host, String(port), &hints, &res) == 0, let r = res else { fatalError("resolve \(host)") }
        addr = r.pointee.ai_addr.withMemoryRebound(to: sockaddr_in.self, capacity: 1) { $0.pointee }
        freeaddrinfo(r)
    }

    let cr = withUnsafePointer(to: &addr) { ptr in
        ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) { sockPtr in
            connect(fd, sockPtr, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    guard cr == 0 else { fatalError("connect to \(host):\(port)") }

    let bodyData = body.data(using: .utf8)!
    var req = "POST \(path) HTTP/1.1\r\n"
    req += "Host: \(host):\(port)\r\n"
    req += "Authorization: Bearer \(apiKey)\r\n"
    req += "Content-Type: application/json\r\n"
    req += "Content-Length: \(bodyData.count)\r\n"
    req += "Connection: close\r\n"
    req += "\r\n"

    writeAll(fd, req.data(using: .utf8)!)
    writeAll(fd, bodyData)

    var resp = Data()
    let buf = UnsafeMutablePointer<UInt8>.allocate(capacity: 65536)
    defer { buf.deallocate() }
    while true {
        let n = read(fd, buf, 65536)
        if n <= 0 { break }
        resp.append(buf, count: n)
    }

    let respStr = String(data: resp, encoding: .utf8) ?? ""
    guard let nl = respStr.firstIndex(of: "\r") else { fatalError("no status line") }
    let statusLine = String(respStr[..<nl])
    let parts = statusLine.split(separator: " ", maxSplits: 2)
    let status = parts.count >= 2 ? Int(parts[1]) ?? 0 : 0

    guard let he = respStr.range(of: "\r\n\r\n") else { fatalError("no header/body sep") }
    let respBody = String(respStr[he.upperBound...])

    return (status, respBody)
}

