let args = CommandLine.arguments
guard args.count >= 3 else { fatalError("usage: \(args[0]) <data_dir> <base_url>") }
let dataDir = args[1]
let baseUrl = args[2]

let taskStr = try! String(contentsOfFile: "\(dataDir)/task.json", encoding: .utf8)
