// Parse task.json
let tp = JP(taskStr)
let taskPairs = tp.objPos()

var apiKey = ""
var model = ""
var systemMsg = ""
var userMsg = ""
var toolsRaw = ""

for (k, v, vs, ve) in taskPairs {
    switch k {
    case "api_key": apiKey = gs(v)
    case "model": model = gs(v)
    case "system": systemMsg = gs(v)
    case "user": userMsg = gs(v)
    case "tools": toolsRaw = String(tp.c[vs..<ve])
    default: break
    }
}

// Parse rates.json
let ratesJV = pj(ratesStr)
var ratesMap: [String: Int] = [:]
if let rv = gv(ratesJV, "rates"), case .obj(let rp) = rv {
    for (ck, cv) in rp { ratesMap[ck] = gi(cv) }
}

// Parse inventory.csv
let csvRecs = parseCSV(csvStr)
struct InvRow { let name: String; let priceCents: Int; let currency: String; let stock: Int }
var invDict: [String: InvRow] = [:]
if csvRecs.count > 1 {
    for rec in csvRecs.dropFirst() {
        guard rec.count >= 5 else { continue }
        invDict[rec[0]] = InvRow(name: rec[1], priceCents: Int(rec[2]) ?? 0, currency: rec[3], stock: Int(rec[4]) ?? 0)
    }
