    case sys(String)
    case usr(String)
    case asst(contentRaw: String?, tcs: [TCInfo])
    case tool(id: String, content: String)
}

func serMsg(_ m: Msg) -> String {
    switch m {
    case .sys(let c):
        return "{\"role\":\"system\",\"content\":\(esc(c))}"
    case .usr(let c):
        return "{\"role\":\"user\",\"content\":\(esc(c))}"
    case .asst(let cr, let tcs):
        var s = "{\"role\":\"assistant\",\"content\":"
        if let r = cr { s += r } else { s += "null" }
        s += ",\"tool_calls\":["
        for (idx, tc) in tcs.enumerated() {
            if idx > 0 { s += "," }
            s += "{\"id\":\(esc(tc.id)),\"type\":\"function\",\"function\":{\"name\":\(esc(tc.name)),\"arguments\":\(tc.argsRaw)}}"
        }
        s += "]}"
        return s
    case .tool(let id, let c):
        return "{\"role\":\"tool\",\"tool_call_id\":\(esc(id)),\"content\":\(esc(c))}"
    }
}

func buildBody(_ msgs: [Msg]) -> String {
    var ms = "["
    for (i, m) in msgs.enumerated() {
        if i > 0 { ms += "," }
        ms += serMsg(m)
    }
    ms += "]"
    return "{\"model\":\(esc(model)),\"messages\":\(ms),\"tools\":\(toolsRaw),\"tool_choice\":\"auto\"}"
}

