        let from = gs(gv(av, "from")!)
        let to = gs(gv(av, "to")!)
        let rFrom = Int64(ratesMap[from]!)
        let rTo = Int64(ratesMap[to]!)
        let converted = (2 * Int64(amount) * rTo + rFrom) / (2 * rFrom)
        return "{\"amount_cents\":\(converted),\"currency\":\(esc(to))}"
    } else {
        return "{\"error\":\(esc("unknown tool: \(name)"))}"
    }
