import Foundation

// ============ JSON Types ============

struct RS { let v: String; let raw: String }

enum JV {
    case nul
    case blb(Bool)
    case ino(Int)
    case flo(Double)
    case str(RS)
    case arr([JV])
    case obj([(String, JV)])
}

// ============ JSON Parser ============

final class JP {
    let c: [Character]
    var i: Int = 0
    init(_ s: String) { c = Array(s) }

    func ws() { while i < c.count && c[i].isWhitespace { i += 1 } }
    func pk() -> Character? { i < c.count ? c[i] : nil }
    func eat(_ x: Character) { guard i < c.count && c[i] == x else { fatalError("eat \(x)") }; i += 1 }

    func val() -> JV {
        ws()
        guard let x = pk() else { fatalError("EOF") }
        switch x {
        case "n": i += 4; return .nul
        case "t": i += 4; return .blb(true)
        case "f": i += 5; return .blb(false)
        case "\"": return .str(str())
        case "[": return arr()
        case "{": return obj()
        default:
            if x == "-" || x.isNumber { return num() }
            fatalError("bad \(x)")
        }
    }

    func str() -> RS {
        let s = i; eat("\"")
        var d = ""
        while i < c.count && c[i] != "\"" {
            if c[i] == "\\" {
                i += 1; guard i < c.count else { fatalError("EOFstr") }
                let e = c[i]
                switch e {
                case "\"": d.append("\""); i += 1
                case "\\": d.append("\\"); i += 1
                case "/": d.append("/"); i += 1
                case "b": d.append("\u{0008}"); i += 1
                case "f": d.append("\u{000C}"); i += 1
                case "n": d.append("\n"); i += 1
                case "r": d.append("\r"); i += 1
                case "t": d.append("\t"); i += 1
                case "u":
                    i += 1
                    let h = hex4()
                    if h >= 0xD800 && h <= 0xDBFF {
                        eat("\\"); eat("u")
                        let l = hex4()
                        let cp = 0x10000 + ((h - 0xD800) << 10) + (l - 0xDC00)
                        d.append(Character(UnicodeScalar(cp)!))
                    } else {
                        d.append(Character(UnicodeScalar(h)!))
                    }
                default: fatalError("esc \\(e)")
                }
            } else { d.append(c[i]); i += 1 }
        }
        eat("\"")
        return RS(v: d, raw: String(c[s..<i]))
    }

    func hex4() -> Int {
        var v = 0
        for _ in 0..<4 { guard i < c.count, let d = c[i].hexDigitValue else { fatalError("hex") }; v = v*16+d; i += 1 }
        return v
    }

    func num() -> JV {
        let s = i
        if i < c.count && c[i] == "-" { i += 1 }
        while i < c.count && c[i].isNumber { i += 1 }
        var f = false
        if i < c.count && c[i] == "." { f = true; i += 1; while i < c.count && c[i].isNumber { i += 1 } }
        if i < c.count && (c[i] == "e" || c[i] == "E") { f = true; i += 1; if i < c.count && (c[i] == "+" || c[i] == "-") { i += 1 }; while i < c.count && c[i].isNumber { i += 1 } }
        let t = String(c[s..<i])
        return f ? .flo(Double(t)!) : .ino(Int(t)!)
    }

    func arr() -> JV {
        eat("["); var a: [JV] = []; ws()
        if pk() == "]" { i += 1; return .arr(a) }
        while true { a.append(val()); ws(); if pk() == "," { i += 1; continue }; if pk() == "]" { i += 1; break }; fatalError("arr") }
        return .arr(a)
    }

    func obj() -> JV {
        eat("{"); var p: [(String, JV)] = []; ws()
        if pk() == "}" { i += 1; return .obj(p) }
        while true { ws(); let k = str().v; ws(); eat(":"); let v = val(); p.append((k,v)); ws(); if pk() == "," { i += 1; continue }; if pk() == "}" { i += 1; break }; fatalError("obj") }
        return .obj(p)
    }

    func objPos() -> [(String, JV, Int, Int)] {
        eat("{"); var p: [(String, JV, Int, Int)] = []; ws()
        if pk() == "}" { i += 1; return p }
        while true { ws(); let k = str().v; ws(); eat(":"); ws(); let vs = i; let v = val(); let ve = i; p.append((k,v,vs,ve)); ws(); if pk() == "," { i += 1; continue }; if pk() == "}" { i += 1; break }; fatalError("objPos") }
        return p
    }
}

func pj(_ s: String) -> JV { JP(s).val() }

func gv(_ v: JV, _ k: String) -> JV? {
    if case .obj(let ps) = v { for (kk,vv) in ps { if kk == k { return vv } } }
    return nil
}
func gs(_ v: JV) -> String { if case .str(let r) = v { return r.v }; fatalError("notstr") }
func gi(_ v: JV) -> Int { if case .ino(let n) = v { return n }; if case .flo(let d) = v { return Int(d) }; fatalError("notint") }

// ============ JSON String Escaping ============

func esc(_ s: String) -> String {
    var r = "\""
    for ch in s.unicodeScalars {
        switch ch {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\u{0008}": r += "\\b"
        case "\u{000C}": r += "\\f"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default:
            if ch.value < 0x20 { r += String(format: "\\u%04x", ch.value) }
            else { r.append(Character(ch)) }
        }
    }
    r += "\""
    return r
}

// ============ CSV Parser ============

func parseCSV(_ text: String) -> [[String]] {
    var s = text
    if s.hasPrefix("\u{FEFF}") { s = String(s.dropFirst()) }
    let ch = Array(s)
    var recs: [[String]] = []
    var i = 0
    while i < ch.count {
        var fields: [String] = []
        while true {
            var f = ""
            if i < ch.count && ch[i] == "\"" {
                i += 1
                while i < ch.count {
                    if ch[i] == "\"" {
                        if i+1 < ch.count && ch[i+1] == "\"" { f.append("\""); i += 2 }
                        else { i += 1; break }
                    } else { f.append(ch[i]); i += 1 }
                }
            } else {
                while i < ch.count && ch[i] != "," && ch[i] != "\r" && ch[i] != "\n" { f.append(ch[i]); i += 1 }
            }
            fields.append(f)
            if i < ch.count && ch[i] == "," { i += 1; continue }
            if i < ch.count && ch[i] == "\r" { i += 1; if i < ch.count && ch[i] == "\n" { i += 1 } }
            else if i < ch.count && ch[i] == "\n" { i += 1 }
            break
        }
        recs.append(fields)
    }
    return recs
}

// ============ HTTP Client (URLSession) ============

func httpPost(host: String, port: Int, path: String, body: String, apiKey: String) -> (Int, String) {
    let urlString = "http://\(host):\(port)\(path)"
    guard let url = URL(string: urlString) else { fatalError("bad url: \(urlString)") }

    var request = URLRequest(url: url)
    request.httpMethod = "POST"
    request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
    request.httpBody = body.data(using: .utf8)
    request.timeoutInterval = 120

    let semaphore = DispatchSemaphore(value: 0)
    var statusCode = 0
    var respBody = ""

    let session = URLSession(configuration: .ephemeral)
    let task = session.dataTask(with: request) { data, response, error in
        defer { semaphore.signal() }
        if let error = error {
            fatalError("HTTP request failed: \(error)")
        }
        statusCode = (response as? HTTPURLResponse)?.statusCode ?? 0
        if let data = data {
            respBody = String(data: data, encoding: .utf8) ?? ""
        }
    }
    task.resume()
    semaphore.wait()
    session.invalidateAndCancel()

    return (statusCode, respBody)
}

