const pageSize = pageSizeRaw === 1 ? 65536 : pageSizeRaw;
const reservedBytes = data[18];
const usableSize = pageSize - reservedBytes;

// CRC-32 lookup table
const crcTable: number[] = [];
for (let i = 0; i < 256; i++) {
  let c = i;
  for (let j = 0; j < 8; j++) {
    c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  }
  crcTable[i] = c;
}

function crc32(buf: Buffer): number {
  let c = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) {
    c = crcTable[(c ^ buf[i]) & 0xFF] ^ (c >>> 8);
  }
  return (c ^ 0xFFFFFFFF) >>> 0;
}

function getPage(pageNum: number): Buffer {
  return data.subarray((pageNum - 1) * pageSize, pageNum * pageSize);
}

function readVarint(buf: Buffer, offset: number): [bigint, number] {
  let result = 0n;
  for (let i = 0; i < 9; i++) {
    const byte = buf[offset + i];
    if (i === 8) {
      result = (result << 8n) | BigInt(byte);
      return [result, offset + 9];
    }
    result = (result << 7n) | BigInt(byte & 0x7F);
    if ((byte & 0x80) === 0) {
      return [result, offset + i + 1];
    }
  }
  return [result, offset + 9];
}

function readSignedBE(buf: Buffer, offset: number, length: number): bigint {
  let result = 0n;
  for (let i = 0; i < length; i++) {
    result = (result << 8n) | BigInt(buf[offset + i]);
  }
  if (result & (1n << BigInt(length * 8 - 1))) {
    result -= (1n << BigInt(length * 8));
  }
  return result;
}

type Value =
  | { type: 'null' }
  | { type: 'integer'; data: bigint }
  | { type: 'real'; data: number }
  | { type: 'text'; data: Buffer }
  | { type: 'blob'; data: Buffer };

function parseRecord(payload: Buffer): Value[] {
  let offset = 0;
  const [headerSize, off1] = readVarint(payload, offset);
  offset = off1;
  const headerEnd = Number(headerSize);

  const serialTypes: number[] = [];
  while (offset < headerEnd) {
    const [st, off2] = readVarint(payload, offset);
    offset = off2;
    serialTypes.push(Number(st));
  }

  const values: Value[] = [];
  for (const st of serialTypes) {
    if (st === 0) {
      values.push({ type: 'null' });
    } else if (st >= 1 && st <= 4) {
      values.push({ type: 'integer', data: readSignedBE(payload, offset, st) });
      offset += st;
    } else if (st === 5) {
      values.push({ type: 'integer', data: readSignedBE(payload, offset, 6) });
      offset += 6;
    } else if (st === 6) {
      values.push({ type: 'integer', data: readSignedBE(payload, offset, 8) });
      offset += 8;
    } else if (st === 7) {
      values.push({ type: 'real', data: payload.readDoubleBE(offset) });
      offset += 8;
    } else if (st === 8) {
      values.push({ type: 'integer', data: 0n });
    } else if (st === 9) {
      values.push({ type: 'integer', data: 1n });
    } else if (st >= 12 && st % 2 === 0) {
      const len = (st - 12) / 2;
      values.push({ type: 'blob', data: payload.subarray(offset, offset + len) });
      offset += len;
    } else if (st >= 13 && st % 2 === 1) {
      const len = (st - 13) / 2;
      values.push({ type: 'text', data: payload.subarray(offset, offset + len) });
      offset += len;
    } else {
      values.push({ type: 'null' });
    }
  }
  return values;
}

function readPayload(pageNum: number, cellOffset: number, payloadSize: number): Buffer {
  const page = getPage(pageNum);
  const X = usableSize - 35;

  if (payloadSize <= X) {
    return page.subarray(cellOffset, cellOffset + payloadSize);
  }

  const M = Math.floor(((usableSize - 12) * 32) / 255) - 23;
  const K = M + ((payloadSize - M) % (usableSize - 4));
  const localSize = K <= X ? K : M;

  const local = page.subarray(cellOffset, cellOffset + localSize);
  const overflowPageNum = page.readUInt32BE(cellOffset + localSize);

  const overflowSize = payloadSize - localSize;
  const overflow = Buffer.alloc(overflowSize);
  let cur = overflowPageNum;
  let written = 0;

  while (cur !== 0 && written < overflowSize) {
    const op = getPage(cur);
    const chunk = Math.min(usableSize - 4, overflowSize - written);
    op.copy(overflow, written, 4, 4 + chunk);
    written += chunk;
    cur = op.readUInt32BE(0);
  }

  return Buffer.concat([local, overflow]);
}

function walkTableBTree(pageNum: number): Array<[bigint, Buffer]> {
  if (pageNum === 0) return [];

  const page = getPage(pageNum);
  const hOff = pageNum === 1 ? 100 : 0;
  const pageType = page[hOff];
  const numCells = page.readUInt16BE(hOff + 3);
  const cellPtrStart = hOff + 12; // table b-tree header is 12 bytes

  const results: Array<[bigint, Buffer]> = [];

  if (pageType === 13) {
    // Leaf table page
    for (let i = 0; i < numCells; i++) {
      const cp = page.readUInt16BE(cellPtrStart + i * 2);
      let co = cp;
      const [pSize, o1] = readVarint(page, co);
      co = o1;
      const [rowid, o2] = readVarint(page, co);
      co = o2;
      const payload = readPayload(pageNum, co, Number(pSize));
      results.push([rowid, payload]);
    }
  } else if (pageType === 5) {
    // Interior table page
    for (let i = 0; i < numCells; i++) {
      const cp = page.readUInt16BE(cellPtrStart + i * 2);
      const leftChild = page.readUInt32BE(cp);
      const sub = walkTableBTree(leftChild);
      for (const r of sub) results.push(r);
    }
    const rightMost = page.readUInt32BE(hOff + 8);
    const sub = walkTableBTree(rightMost);
    for (const r of sub) results.push(r);
  }

  return results;
}

function formatReal(value: number): string {
  const buf = Buffer.alloc(8);
  buf.writeDoubleBE(value, 0);
  const bits = buf.readBigUInt64BE(0);

  const sign = (bits >> 63n) & 1n;
  const exp = Number((bits >> 52n) & 0x7FFn);
  const frac = bits & ((1n << 52n) - 1n);

  let m: bigint;
  let e: number;
  if (exp === 0) {
    m = frac;
    e = -1074;
  } else {
    m = frac | (1n << 52n);
    e = exp - 1075;
  }

  const five8 = 390625n; // 5^8
  let n: bigint;
  if (e + 8 >= 0) {
    n = m * (1n << BigInt(e + 8)) * five8;
  } else {
    const num = m * five8;
    const den = 1n << BigInt(-(e + 8));
    const q = num / den;
    const r = num % den;
    n = (r * 2n >= den) ? q + 1n : q;
  }

  let s = n.toString();
  while (s.length <= 8) s = '0' + s;
  const intPart = s.slice(0, s.length - 8);
  let fracPart = s.slice(s.length - 8);
  fracPart = fracPart.replace(/0+$/, '');
  if (fracPart === '') fracPart = '0';

  const signStr = sign ? '-' : '';
  return signStr + intPart + '.' + fracPart;
}

function escapeText(buf: Buffer): string {
  const str = buf.toString('utf-8');
  let result = '';
  for (const ch of str) {
    const code = ch.codePointAt(0)!;
    if (code === 0x5C) result += '\\\\';
    else if (code === 0x22) result += '\\"';
    else if (code === 0x0A) result += '\\n';
    else if (code === 0x0D) result += '\\r';
    else if (code === 0x09) result += '\\t';
    else if (code < 0x20 || code === 0x7F)
      result += '\\x' + code.toString(16).toUpperCase().padStart(2, '0');
    else result += ch;
  }
  return result;
}

function formatValue(v: Value): string {
  switch (v.type) {
    case 'null': return 'NULL';
    case 'integer': return v.data.toString();
    case 'real': return formatReal(v.data);
    case 'text': {
      const b = v.data;
      if (b.length <= 100) return '"' + escapeText(b) + '"';
      return `<TEXT len=${b.length} crc32=${crc32(b).toString(16).padStart(8, '0')}>`;
    }
    case 'blob': {
      const b = v.data;
      if (b.length <= 100) return "X'" + b.toString('hex').toUpperCase() + "'";
      return `<BLOB len=${b.length} crc32=${crc32(b).toString(16).padStart(8, '0')}>`;
    }
  }
}

function parseColumns(sql: string): { names: string[]; rowidAlias: boolean[] } {
  let i = 0;
  const len = sql.length;

  while (i < len && /\s/.test(sql[i])) i++;
  if (sql.slice(i, i + 6).toUpperCase() === 'CREATE') i += 6;
  while (i < len && /\s/.test(sql[i])) i++;
  if (sql.slice(i, i + 5).toUpperCase() === 'TABLE') i += 5;
  while (i < len && /\s/.test(sql[i])) i++;

  // optional IF NOT EXISTS
  if (i + 1 < len && sql.slice(i, i + 2).toUpperCase() === 'IF') {
    i += 2;
    while (i < len && /\s/.test(sql[i])) i++;
    if (sql.slice(i, i + 3).toUpperCase() === 'NOT') {
      i += 3;
      while (i < len && /\s/.test(sql[i])) i++;
      if (sql.slice(i, i + 6).toUpperCase() === 'EXISTS') {
        i += 6;
        while (i < len && /\s/.test(sql[i])) i++;
      }
    }
  }

  // skip table name
  if (i < len && sql[i] === '"') {
    i++;
    while (i < len && sql[i] !== '"') i++;
    i++;
  } else {
    while (i < len && /[a-zA-Z0-9_]/.test(sql[i])) i++;
  }
  while (i < len && /\s/.test(sql[i])) i++;

  // find opening paren
  while (i < len && sql[i] !== '(') i++;
  const defsStart = i + 1;
  let depth = 1;
  i++;
  while (i < len && depth > 0) {
    if (sql[i] === '(') depth++;
    else if (sql[i] === ')') depth--;
    i++;
  }
  const defsEnd = i - 1;

  // split by top-level commas
  const defs: string[] = [];
  let cur = '';
  depth = 0;
  for (let j = defsStart; j < defsEnd; j++) {
    if (sql[j] === '(') depth++;
    else if (sql[j] === ')') depth--;
    else if (sql[j] === ',' && depth === 0) {
      defs.push(cur);
      cur = '';
      continue;
    }
    cur += sql[j];
  }
  if (cur.trim().length > 0) defs.push(cur);

  const names: string[] = [];
  const rowidAlias: boolean[] = [];

  for (const def of defs) {
    let j = 0;
    while (j < def.length && /\s/.test(def[j])) j++;

    let name: string;
    if (j < def.length && def[j] === '"') {
      j++;
      const ns = j;
      while (j < def.length && def[j] !== '"') j++;
      name = def.slice(ns, j);
      j++;
    } else {
      const ns = j;
      while (j < def.length && /[a-zA-Z0-9_]/.test(def[j])) j++;
      name = def.slice(ns, j);
    }
    names.push(name);

    const rest = def.slice(j);
    const ru = rest.toUpperCase();
    const intWord = /^\s*INTEGER\b/.test(ru);
    const sizeSpec = /^\s*INTEGER\s*\(/.test(ru);
    const isInt = intWord && !sizeSpec;
    const hasPK = /\bPRIMARY\b/.test(ru) && /\bKEY\b/.test(ru);
    rowidAlias.push(isInt && hasPK);
  }

  return { names, rowidAlias };
}

// --- Main ---

const schemaRows = walkTableBTree(1);

interface TableInfo { name: string; rootPage: number; sql: string; }
const tables: TableInfo[] = [];

for (const [, payload] of schemaRows) {
  const vals = parseRecord(payload);
  if (vals.length < 5) continue;
  if (vals[0].type !== 'text') continue;
  if ((vals[0].data as Buffer).toString('utf-8') !== 'table') continue;
  if (vals[1].type !== 'text') continue;
  const tname = (vals[1].data as Buffer).toString('utf-8');
  if (tname.startsWith('sqlite_')) continue;
  if (vals[3].type !== 'integer') continue;
  const rp = Number(vals[3].data as bigint);
  const sqlText = vals[4].type === 'text' ? (vals[4].data as Buffer).toString('utf-8') : '';
  tables.push({ name: tname, rootPage: rp, sql: sqlText });
}

tables.sort((a, b) => Buffer.compare(Buffer.from(a.name, 'utf-8'), Buffer.from(b.name, 'utf-8')));

const outputs: string[] = [];
for (const table of tables) {
  const { names, rowidAlias } = parseColumns(table.sql);
  const rows = walkTableBTree(table.rootPage);

  const lines: string[] = [];
  lines.push(`TABLE ${table.name} rows=${rows.length}`);
  lines.push(`COLUMNS ${names.join(', ')}`);

  for (const [rowid, payload] of rows) {
    const vals = parseRecord(payload);
    const fmt: string[] = [];
    for (let i = 0; i < names.length; i++) {
      if (rowidAlias[i]) {
        fmt.push(rowid.toString());
      } else if (i < vals.length) {
        fmt.push(formatValue(vals[i]));
      } else {
        fmt.push('NULL');
      }
    }
    lines.push(`${rowid.toString()}: ${fmt.join(', ')}`);
  }

  outputs.push(lines.join('\n'));
}

if (outputs.length > 0) {
  console.log(outputs.join('\n\n'));
}

