  while (i < len && /\s/.test(sql[i])) i++;

  // find opening paren
  while (i < len && sql[i] !== '(') i++;
  const defsStart = i + 1;
  let depth = 1;
  i++;
  while (i < len && depth > 0) {
    if (sql[i] === '(') depth++;
    else if (sql[i] === ')') depth--;
    i++;
  }
  const defsEnd = i - 1;

  // split by top-level commas
  const defs: string[] = [];
  let cur = '';
  depth = 0;
  for (let j = defsStart; j < defsEnd; j++) {
    if (sql[j] === '(') depth++;
    else if (sql[j] === ')') depth--;
    else if (sql[j] === ',' && depth === 0) {
      defs.push(cur);
      cur = '';
      continue;
    }
    cur += sql[j];
  }
  if (cur.trim().length > 0) defs.push(cur);

  const names: string[] = [];
  const rowidAlias: boolean[] = [];

  for (const def of defs) {
    let j = 0;
    while (j < def.length && /\s/.test(def[j])) j++;

    let name: string;
    if (j < def.length && def[j] === '"') {
      j++;
      const ns = j;
      while (j < def.length && def[j] !== '"') j++;
      name = def.slice(ns, j);
      j++;
    } else {
      const ns = j;
      while (j < def.length && /[a-zA-Z0-9_]/.test(def[j])) j++;
      name = def.slice(ns, j);
    }
    names.push(name);

    const rest = def.slice(j);
    const ru = rest.toUpperCase();
    const intWord = /^\s*INTEGER\b/.test(ru);
    const sizeSpec = /^\s*INTEGER\s*\(/.test(ru);
    const isInt = intWord && !sizeSpec;
    const hasPK = /\bPRIMARY\b/.test(ru) && /\bKEY\b/.test(ru);
    rowidAlias.push(isInt && hasPK);
  }

  return { names, rowidAlias };
}

// --- Main ---

const schemaRows = walkTableBTree(1);

interface TableInfo { name: string; rootPage: number; sql: string; }
const tables: TableInfo[] = [];

for (const [, payload] of schemaRows) {
  const vals = parseRecord(payload);
  if (vals.length < 5) continue;
  if (vals[0].type !== 'text') continue;
  if ((vals[0].data as Buffer).toString('utf-8') !== 'table') continue;
  if (vals[1].type !== 'text') continue;
  const tname = (vals[1].data as Buffer).toString('utf-8');
  if (tname.startsWith('sqlite_')) continue;
  if (vals[3].type !== 'integer') continue;
  const rp = Number(vals[3].data as bigint);
  const sqlText = vals[4].type === 'text' ? (vals[4].data as Buffer).toString('utf-8') : '';
  tables.push({ name: tname, rootPage: rp, sql: sqlText });
}

tables.sort((a, b) => Buffer.compare(Buffer.from(a.name, 'utf-8'), Buffer.from(b.name, 'utf-8')));

const outputs: string[] = [];
for (const table of tables) {
  const { names, rowidAlias } = parseColumns(table.sql);
  const rows = walkTableBTree(table.rootPage);

  const lines: string[] = [];
  lines.push(`TABLE ${table.name} rows=${rows.length}`);
  lines.push(`COLUMNS ${names.join(', ')}`);

  for (const [rowid, payload] of rows) {
    const vals = parseRecord(payload);
    const fmt: string[] = [];
    for (let i = 0; i < names.length; i++) {
      if (rowidAlias[i]) {
        fmt.push(rowid.toString());
      } else if (i < vals.length) {
        fmt.push(formatValue(vals[i]));
      } else {
        fmt.push('NULL');
      }
    }
    lines.push(`${rowid.toString()}: ${fmt.join(', ')}`);
  }

  outputs.push(lines.join('\n'));
}

if (outputs.length > 0) {
  console.log(outputs.join('\n\n'));
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <ctype.h>

static uint8_t *db;
static size_t db_size;
static int page_size;
static int reserved_bytes;
static int usable_size;

// Read big-endian integers
static uint16_t read_be16(const uint8_t *p) {
    return (uint16_t)((p[0] << 8) | p[1]);
}

static uint32_t read_be32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3];
}

static uint64_t read_be64(const uint8_t *p) {
    return ((uint64_t)p[0] << 56) | ((uint64_t)p[1] << 48) | ((uint64_t)p[2] << 40) |
           ((uint64_t)p[3] << 32) | ((uint64_t)p[4] << 24) | ((uint64_t)p[5] << 16) |
           ((uint64_t)p[6] << 8) | p[7];
}

// Read SQLite varint, returns number of bytes consumed
static int read_varint(const uint8_t *p, uint64_t *val) {
    *val = 0;
    int i;
    for (i = 0; i < 8; i++) {
        *val = (*val << 7) | (p[i] & 0x7F);
        if (!(p[i] & 0x80)) {
            return i + 1;
        }
    }
    // 9th byte
    *val = (*val << 8) | p[8];
    return 9;
}

// Get page data pointer (page numbers are 1-based)
static const uint8_t* get_page(int page_num) {
    return db + (size_t)(page_num - 1) * page_size;
}

// Get page header offset (page 1 has 100-byte file header before page header)
static int page_header_offset(int page_num) {
    return page_num == 1 ? 100 : 0;
}

// CRC32 (zlib/PNG style)
static uint32_t crc32_table[256];
static void crc32_init(void) {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++) {
            if (c & 1) c = 0xEDB88320 ^ (c >> 1);
            else c >>= 1;
        }
        crc32_table[i] = c;
    }
}

static uint32_t crc32_compute(const uint8_t *data, size_t len) {
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < len; i++) {
        crc = crc32_table[(crc ^ data[i]) & 0xFF] ^ (crc >> 8);
    }
    return crc ^ 0xFFFFFFFF;
}

// Value representation
typedef enum { V_NULL, V_INT, V_REAL, V_TEXT, V_BLOB } ValType;

typedef struct {
    ValType type;
    int64_t ival;
    double dval;
    const uint8_t *data;
    size_t len;
} Value;

// Decode a record from payload
// Returns number of values decoded
static int decode_record(const uint8_t *payload, size_t payload_len, Value *values, int max_values) {
    int pos = 0;
    uint64_t header_size;
    int n = read_varint(payload + pos, &header_size);
    pos += n;

    // Read serial types
    uint64_t serial_types[256]; // assuming max 256 columns, should be enough
    int num_cols = 0;
    while (pos < (int)header_size && num_cols < max_values) {
        n = read_varint(payload + pos, &serial_types[num_cols]);
        pos += n;
        num_cols++;
    }

    // Decode each value
    int data_pos = (int)header_size; // data starts after header
    for (int i = 0; i < num_cols; i++) {
        uint64_t st = serial_types[i];
        if (st == 0) {
            values[i].type = V_NULL;
        } else if (st >= 1 && st <= 4) {
            int nbytes = (int)st;
            int64_t v = 0;
            for (int j = 0; j < nbytes; j++) {
                v = (v << 8) | payload[data_pos + j];
            }
            // Sign extend
            if (nbytes < 8 && (v & (1LL << (nbytes * 8 - 1)))) {
                v |= ~((1LL << (nbytes * 8)) - 1);
            }
            values[i].type = V_INT;
            values[i].ival = v;
            data_pos += nbytes;
        } else if (st == 5) {
            int64_t v = 0;
            for (int j = 0; j < 6; j++) {
                v = (v << 8) | payload[data_pos + j];
            }
            if (v & (1LL << 47)) {
                v |= ~((1LL << 48) - 1);
            }
            values[i].type = V_INT;
            values[i].ival = v;
            data_pos += 6;
        } else if (st == 6) {
            values[i].type = V_INT;
            values[i].ival = (int64_t)read_be64(payload + data_pos);
            data_pos += 8;
        } else if (st == 7) {
            values[i].type = V_REAL;
            uint64_t bits = read_be64(payload + data_pos);
            memcpy(&values[i].dval, &bits, 8);
            data_pos += 8;
        } else if (st == 8) {
            values[i].type = V_INT;
            values[i].ival = 0;
        } else if (st == 9) {
            values[i].type = V_INT;
            values[i].ival = 1;
        } else if (st >= 12 && st % 2 == 0) {
            size_t len = (size_t)((st - 12) / 2);
            values[i].type = V_BLOB;
            values[i].data = payload + data_pos;
            values[i].len = len;
            data_pos += len;
        } else if (st >= 13 && st % 2 == 1) {
            size_t len = (size_t)((st - 13) / 2);
            values[i].type = V_TEXT;
            values[i].data = payload + data_pos;
            values[i].len = len;
            data_pos += len;
        }
    }

    return num_cols;
}

// Read payload for a leaf table cell, handling overflow
static uint8_t* read_leaf_payload(const uint8_t *cell, size_t *out_len) {
    int pos = 0;
    uint64_t payload_size;
    pos += read_varint(cell + pos, &payload_size);
    pos += read_varint(cell + pos, NULL); // skip rowid

    int X = usable_size - 35;
    int M = ((usable_size - 12) * 64 / 255) - 23;

    size_t embedded;
    if ((int)payload_size <= X) {
        embedded = payload_size;
        *out_len = payload_size;
        // Return pointer directly into the cell
        return (uint8_t*)(cell + pos);
    } else {
        int K = M + ((int)(payload_size - M) % (usable_size - 4));
        if (K <= X) embedded = K;
        else embedded = M;

        // Read embedded portion + overflow
        uint8_t *full = malloc(payload_size);
        memcpy(full, cell + pos, embedded);

        // Follow overflow chain
        size_t remaining = payload_size - embedded;
        size_t written = embedded;
        uint32_t overflow_page = read_be32(cell + pos + embedded);

        while (remaining > 0 && overflow_page != 0) {
            const uint8_t *op = get_page(overflow_page);
            size_t chunk = usable_size - 4; // first 4 bytes are next page pointer
            if (chunk > remaining) chunk = remaining;
            memcpy(full + written, op + 4, chunk);
            written += chunk;
            remaining -= chunk;
            overflow_page = read_be32(op);
        }

        *out_len = payload_size;
        return full;
    }
}

// B-tree traversal for leaf table pages
// Collects all rows (rowid + payload) from a table b-tree rooted at page_num
typedef struct {
    int64_t rowid;
    const uint8_t *payload;
    size_t payload_len;
} Row;

// Dynamic array of rows
typedef struct {
    Row *rows;
    int count;
    int capacity;
} RowList;

static void rowlist_init(RowList *rl) {
    rl->rows = NULL;
    rl->count = 0;
    rl->capacity = 0;
}

static void rowlist_add(RowList *rl, int64_t rowid, const uint8_t *payload, size_t len) {
    if (rl->count >= rl->capacity) {
        rl->capacity = rl->capacity ? rl->capacity * 2 : 64;
        rl->rows = realloc(rl->rows, rl->capacity * sizeof(Row));
    }
    rl->rows[rl->count].rowid = rowid;
    rl->rows[rl->count].payload = payload;
    rl->rows[rl->count].payload_len = len;
    rl->count++;
}

static void walk_btree(int page_num, RowList *rl) {
    const uint8_t *page = get_page(page_num);
    int hdr_off = page_header_offset(page_num);
    uint8_t page_type = page[hdr_off];
    int num_cells = read_be16(page + hdr_off + 3);

    // Cell pointer array starts after the page header
    int cell_ptr_start = hdr_off + (page_type == 5 ? 12 : 8); // interior table has extra 4 bytes for right pointer

    for (int i = 0; i < num_cells; i++) {
        int cell_offset = read_be16(page + cell_ptr_start + i * 2);
        const uint8_t *cell = page + cell_offset;

        if (page_type == 5) {
            // Interior table b-tree page
            // Cell: 4-byte left child page, varint key (rowid)
            uint32_t child_page = read_be32(cell);
            int64_t key = (int64_t)0;
            read_varint(cell + 4, (uint64_t*)&key);
            // Recurse into left child
            walk_btree(child_page, rl);
        } else if (page_type == 13) {
            // Leaf table b-tree page
            int pos = 0;
            uint64_t payload_size;
            pos += read_varint(cell + pos, &payload_size);
            uint64_t rowid;
            pos += read_varint(cell + pos, &rowid);

            size_t pl_len;
            uint8_t *pl = read_leaf_payload(cell, &pl_len);
            rowlist_add(rl, (int64_t)rowid, pl, pl_len);
        }
    }

    // For interior pages, also recurse into rightmost child
    if (page_type == 5) {
        uint32_t rightmost = read_be32(page + hdr_off + 8);
        walk_btree(rightmost, rl);
    }
}

// Parse column names from CREATE TABLE SQL
// Returns number of columns, fills names array
static int parse_columns(const char *sql, char names[256][256], int is_rowid_alias[256]) {
    // Find the opening parenthesis after CREATE TABLE <name>
    // Skip whitespace between tokens
    const char *p = sql;

    // Skip "CREATE TABLE" (case-insensitive)
    // Actually, let me just find the first '(' that starts the column definitions
    // But I need to skip the table name which might be quoted

    // Find first '('
    while (*p && *p != '(') p++;
    if (!*p) return 0;
    p++; // skip '('

    // Now parse column definitions separated by commas not inside parentheses
    int depth = 0;
    int num_cols = 0;

    while (*p) {
        // Skip whitespace
        while (*p && isspace((unsigned char)*p)) p++;
        if (*p == ')') break;

        // Parse column name
        int name_start = 0;
        char col_name[256] = {0};

        if (*p == '"') {
            p++; // skip opening quote
            int j = 0;
            while (*p && *p != '"') {
                col_name[j++] = *p++;
            }
            col_name[j] = '\0';
            if (*p == '"') p++; // skip closing quote
        } else {
            // Bare identifier: starts with letter or underscore, followed by alnum or $
            int j = 0;
            while (*p && (isalnum((unsigned char)*p) || *p == '_' || *p == '$')) {
                col_name[j++] = *p++;
            }
            col_name[j] = '\0';
        }

        // Now we have the column name. Parse the rest of the definition to check for INTEGER PRIMARY KEY
        // Skip to next comma at depth 0 or closing paren at depth 0
        const char *def_start = p;
        int def_depth = 0;
        while (*p) {
            if (*p == '(') def_depth++;
            else if (*p == ')') {
                if (def_depth == 0) break;
                def_depth--;
            } else if (*p == ',' && def_depth == 0) {
                break;
            }
            p++;
        }

        // Extract the definition text (from after name to current position)
        size_t def_len = p - def_start;
        char def_text[1024];
        if (def_len >= sizeof(def_text)) def_len = sizeof(def_text) - 1;
        memcpy(def_text, def_start, def_len);
        def_text[def_len] = '\0';

        // Check for INTEGER PRIMARY KEY alias
        // The declared type is the first word after the column name
        const char *tp = def_start;
        while (*tp && isspace((unsigned char)*tp)) tp++;

        // Read type name (first word)
        char type_name[256] = {0};
        int ti = 0;
        while (*tp && (isalnum((unsigned char)*tp) || *tp == '_')) {
            type_name[ti++] = *tp++;
        }
        type_name[ti] = '\0';

        // Check if type is exactly "INTEGER" (case-insensitive)
        int is_integer_type = (strcasecmp(type_name, "INTEGER") == 0);

        // Check if definition contains "PRIMARY KEY" (case-insensitive)
        int has_primary_key = 0;
        // Convert def_text to uppercase for comparison
        char upper_def[1024];
        for (size_t i = 0; i < def_len; i++) {
            upper_def[i] = toupper((unsigned char)def_text[i]);
        }
        upper_def[def_len] = '\0';
        if (strstr(upper_def, "PRIMARY KEY")) {
            has_primary_key = 1;
        }

        is_rowid_alias[num_cols] = (is_integer_type && has_primary_key);

        strncpy(names[num_cols], col_name, 255);
        names[num_cols][255] = '\0';
        num_cols++;

        // Skip comma
        if (*p == ',') p++;
    }

    return num_cols;
}

// Format a REAL value
static void format_real(double d, char *buf, size_t bufsize) {
    if (signbit(d)) {
        // Negative
        snprintf(buf, bufsize, "-%.8f", -d);
        // Strip trailing zeros but keep at least one digit after decimal
        char *dot = strchr(buf, '.');
        if (dot) {
            char *end = buf + strlen(buf) - 1;
            while (end > dot + 1 && *end == '0') end--;
            *(end + 1) = '\0';
        }
    } else {
        snprintf(buf, bufsize, "%.8f", d);
        char *dot = strchr(buf, '.');
        if (dot) {
            char *end = buf + strlen(buf) - 1;
            while (end > dot + 1 && *end == '0') end--;
            *(end + 1) = '\0';
        }
    }
}

// Print a value
static void print_value(const Value *v) {
    switch (v->type) {
        case V_NULL:
            printf("NULL");
            break;
        case V_INT:
            printf("%lld", (long long)v->ival);
            break;
        case V_REAL: {
            char buf[64];
            format_real(v->dval, buf, sizeof(buf));
            printf("%s", buf);
            break;
        }
        case V_TEXT:
            if (v->len <= 100) {
                printf("\"");
                for (size_t i = 0; i < v->len; i++) {
                    uint8_t c = v->data[i];
                    if (c == '\\') printf("\\\\");
                    else if (c == '"') printf("\\\"");
                    else if (c == '\n') printf("\\n");
                    else if (c == '\r') printf("\\r");
                    else if (c == '\t') printf("\\t");
                    else if (c < 0x20 || c == 0x7F) printf("\\x%02X", c);
                    else putchar(c);
                }
                printf("\"");
            } else {
                printf("<TEXT len=%zu crc32=%08x>", v->len, crc32_compute(v->data, v->len));
            }
            break;
        case V_BLOB:
            if (v->len <= 100) {
                printf("X'");
                for (size_t i = 0; i < v->len; i++) {
                    printf("%02X", v->data[i]);
                }
                printf("'");
            } else {
                printf("<BLOB len=%zu crc32=%08x>", v->len, crc32_compute(v->data, v->len));
            }
            break;
    }
}

// Schema entry
typedef struct {
    char name[256];
    int rootpage;
    char sql[4096];
} SchemaEntry;

int main(int argc, char *argv[]) {
    if (argc < 2) return 1;

    crc32_init();

    // Read database file
    char path[1024];
    snprintf(path, sizeof(path), "%s/db.sqlite", argv[1]);

    FILE *f = fopen(path, "rb");
    if (!f) {
        perror(path);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    db_size = ftell(f);
    fseek(f, 0, SEEK_SET);
    db = malloc(db_size);
    fread(db, 1, db_size, f);
    fclose(f);

    // Parse header
    int ps = read_be16(db + 16);
    page_size = (ps == 1) ? 65536 : ps;
    reserved_bytes = db[20];
    usable_size = page_size - reserved_bytes;

    // Walk page 1 b-tree to get schema
    RowList schema_rows;
    rowlist_init(&schema_rows);
    walk_btree(1, &schema_rows);

    // Decode schema rows and collect table entries
    SchemaEntry tables[256];
    int num_tables = 0;

    for (int i = 0; i < schema_rows.count; i++) {
        Value vals[5];
        int ncols = decode_record(schema_rows.rows[i].payload, schema_rows.rows[i].payload_len, vals, 5);

        if (ncols < 5) continue;

        // Check type == "table"
        if (vals[0].type != V_TEXT || vals[0].len != 5) continue;
        if (memcmp(vals[0].data, "table", 5) != 0) continue;

        // Check name doesn't start with "sqlite_"
        if (vals[1].type != V_TEXT) continue;
        if (vals[1].len >= 7 && memcmp(vals[1].data, "sqlite_", 7) == 0) continue;

        // Get rootpage
        if (vals[3].type != V_INT) continue;

        SchemaEntry *se = &tables[num_tables];
        size_t nlen = vals[1].len;
        if (nlen >= sizeof(se->name)) nlen = sizeof(se->name) - 1;
        memcpy(se->name, vals[1].data, nlen);
        se->name[nlen] = '\0';
        se->rootpage = (int)vals[3].ival;

        // Get SQL
        if (vals[4].type == V_TEXT) {
            size_t slen = vals[4].len;
            if (slen >= sizeof(se->sql)) slen = sizeof(se->sql) - 1;
            memcpy(se->sql, vals[4].data, slen);
            se->sql[slen] = '\0';
        } else {
            se->sql[0] = '\0';
        }

        num_tables++;
    }

    // Sort tables by name (byte-wise ascending)
    for (int i = 0; i < num_tables - 1; i++) {
        for (int j = 0; j < num_tables - 1 - i; j++) {
            if (strcmp(tables[j].name, tables[j+1].name) > 0) {
                SchemaEntry tmp = tables[j];
                tables[j] = tables[j+1];
                tables[j+1] = tmp;
            }
        }
    }

    // Process each table
    for (int t = 0; t < num_tables; t++) {
        if (t > 0) printf("\n");

        // Parse columns
        char col_names[256][256];
        int rowid_alias[256];
        int num_cols = parse_columns(tables[t].sql, col_names, rowid_alias);

        // Walk b-tree to get rows
        RowList rows;
        rowlist_init(&rows);
        walk_btree(tables[t].rootpage, &rows);

        printf("TABLE %s rows=%d\n", tables[t].name, rows.count);

        // Print columns
        printf("COLUMNS ");
        for (int c = 0; c < num_cols; c++) {
            if (c > 0) printf(", ");
            printf("%s", col_names[c]);
        }
        printf("\n");

        // Print rows
        for (int r = 0; r < rows.count; r++) {
            printf("%lld: ", (long long)rows.rows[r].rowid);

            Value vals[256];
            int ncols = decode_record(rows.rows[r].payload, rows.rows[r].payload_len, vals, num_cols);

            for (int c = 0; c < num_cols; c++) {
                if (c > 0) printf(", ");

                if (rowid_alias[c]) {
                    // INTEGER PRIMARY KEY: value is rowid
                    Value v;
                    v.type = V_INT;
                    v.ival = rows.rows[r].rowid;
                    print_value(&v);
                } else if (c < ncols) {
                    print_value(&vals[c]);
                } else {
                    printf("NULL");
                }
            }
            printf("\n");
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <stdint.h>
#include <math.h>
#include <ctype.h>

static uint8_t *db;
static size_t db_size;
static int page_size;
static int reserved_bytes;
static int usable_size;

static uint16_t read_be16(const uint8_t *p) {
    return (uint16_t)((p[0] << 8) | p[1]);
}

static uint32_t read_be32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3];
}

static uint64_t read_be64(const uint8_t *p) {
    return ((uint64_t)p[0] << 56) | ((uint64_t)p[1] << 48) | ((uint64_t)p[2] << 40) |
           ((uint64_t)p[3] << 32) | ((uint64_t)p[4] << 24) | ((uint64_t)p[5] << 16) |
           ((uint64_t)p[6] << 8) | p[7];
}

static int read_varint(const uint8_t *p, uint64_t *val) {
    uint64_t v = 0;
    int i;
    for (i = 0; i < 8; i++) {
        v = (v << 7) | (p[i] & 0x7F);
        if (!(p[i] & 0x80)) {
            if (val) *val = v;
            return i + 1;
        }
    }
    v = (v << 8) | p[8];
    if (val) *val = v;
    return 9;
}

static const uint8_t* get_page(int page_num) {
    return db + (size_t)(page_num - 1) * page_size;
}

static int page_header_offset(int page_num) {
    return page_num == 1 ? 100 : 0;
}

static uint32_t crc32_table[256];
static void crc32_init(void) {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++) {
            if (c & 1) c = 0xEDB88320 ^ (c >> 1);
            else c >>= 1;
        }
        crc32_table[i] = c;
    }
}

static uint32_t crc32_compute(const uint8_t *data, size_t len) {
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < len; i++) {
        crc = crc32_table[(crc ^ data[i]) & 0xFF] ^ (crc >> 8);
    }
    return crc ^ 0xFFFFFFFF;
}

typedef enum { V_NULL, V_INT, V_REAL, V_TEXT, V_BLOB } ValType;

typedef struct {
    ValType type;
    int64_t ival;
    double dval;
    const uint8_t *data;
    size_t len;
} Value;

static int decode_record(const uint8_t *payload, size_t payload_len, Value *values, int max_values) {
    if (payload_len == 0) return 0;
    int pos = 0;
    uint64_t header_size;
    int n = read_varint(payload + pos, &header_size);
    pos += n;

    uint64_t serial_types[2048];
    int num_serial = 0;
    while (pos < (int)header_size && num_serial < 2048) {
        n = read_varint(payload + pos, &serial_types[num_serial]);
        pos += n;
        num_serial++;
    }

    int data_pos = (int)header_size;
    int count = num_serial < max_values ? num_serial : max_values;

    for (int i = 0; i < count; i++) {
        uint64_t st = serial_types[i];
        if (st == 0) {
            values[i].type = V_NULL;
        } else if (st >= 1 && st <= 4) {
            int nbytes = (int)st;
            int64_t v = 0;
            for (int j = 0; j < nbytes; j++) {
                v = (v << 8) | payload[data_pos + j];
            }
            if (nbytes < 8 && (v & (1LL << (nbytes * 8 - 1)))) {
                v |= ~((1LL << (nbytes * 8)) - 1);
            }
            values[i].type = V_INT;
            values[i].ival = v;
            data_pos += nbytes;
        } else if (st == 5) {
            int64_t v = 0;
            for (int j = 0; j < 6; j++) {
                v = (v << 8) | payload[data_pos + j];
            }
            if (v & (1LL << 47)) {
                v |= ~((1LL << 48) - 1);
            }
            values[i].type = V_INT;
            values[i].ival = v;
            data_pos += 6;
        } else if (st == 6) {
            values[i].type = V_INT;
            values[i].ival = (int64_t)read_be64(payload + data_pos);
            data_pos += 8;
        } else if (st == 7) {
            values[i].type = V_REAL;
            uint64_t bits = read_be64(payload + data_pos);
            memcpy(&values[i].dval, &bits, 8);
            data_pos += 8;
        } else if (st == 8) {
            values[i].type = V_INT;
            values[i].ival = 0;
        } else if (st == 9) {
            values[i].type = V_INT;
            values[i].ival = 1;
        } else if (st >= 12 && st % 2 == 0) {
            size_t len = (size_t)((st - 12) / 2);
            values[i].type = V_BLOB;
            values[i].data = payload + data_pos;
            values[i].len = len;
            data_pos += len;
        } else if (st >= 13 && st % 2 == 1) {
            size_t len = (size_t)((st - 13) / 2);
            values[i].type = V_TEXT;
            values[i].data = payload + data_pos;
            values[i].len = len;
            data_pos += len;
        }
    }

    return count;
}

static uint8_t* read_leaf_payload(const uint8_t *cell, size_t *out_len) {
    int pos = 0;
    uint64_t payload_size;
    pos += read_varint(cell + pos, &payload_size);
    pos += read_varint(cell + pos, NULL);

    int X = usable_size - 35;
    int M = ((usable_size - 12) * 64 / 255) - 23;

    size_t embedded;
    if ((int64_t)payload_size <= X) {
        embedded = (size_t)payload_size;
        *out_len = (size_t)payload_size;
        return (uint8_t*)(cell + pos);
    } else {
        int K = M + ((int)(payload_size - M) % (usable_size - 4));
        if (K <= X) embedded = (size_t)K;
        else embedded = (size_t)M;

        uint8_t *full = malloc((size_t)payload_size);
        memcpy(full, cell + pos, embedded);

        size_t remaining = (size_t)payload_size - embedded;
        size_t written = embedded;
        uint32_t overflow_page = read_be32(cell + pos + embedded);

        while (remaining > 0 && overflow_page != 0) {
            const uint8_t *op = get_page((int)overflow_page);
            size_t chunk = (size_t)(usable_size - 4);
            if (chunk > remaining) chunk = remaining;
            memcpy(full + written, op + 4, chunk);
            written += chunk;
            remaining -= chunk;
            overflow_page = read_be32(op);
        }

        *out_len = (size_t)payload_size;
        return full;
    }
}

typedef struct {
    int64_t rowid;
    const uint8_t *payload;
    size_t payload_len;
} Row;

typedef struct {
    Row *rows;
    int count;
    int capacity;
} RowList;

static void rowlist_init(RowList *rl) {
    rl->rows = NULL;
    rl->count = 0;
    rl->capacity = 0;
}

static void rowlist_add(RowList *rl, int64_t rowid, const uint8_t *payload, size_t len) {
    if (rl->count >= rl->capacity) {
        rl->capacity = rl->capacity ? rl->capacity * 2 : 64;
        rl->rows = realloc(rl->rows, (size_t)rl->capacity * sizeof(Row));
    }
    rl->rows[rl->count].rowid = rowid;
    rl->rows[rl->count].payload = payload;
    rl->rows[rl->count].payload_len = len;
    rl->count++;
}

static void walk_btree(int page_num, RowList *rl) {
    const uint8_t *page = get_page(page_num);
    int hdr_off = page_header_offset(page_num);
    uint8_t page_type = page[hdr_off];
    int num_cells = read_be16(page + hdr_off + 3);

    int cell_ptr_start = hdr_off + (page_type == 5 ? 12 : 8);

    for (int i = 0; i < num_cells; i++) {
        int cell_offset = read_be16(page + cell_ptr_start + i * 2);
        const uint8_t *cell = page + cell_offset;

        if (page_type == 5) {
            uint32_t child_page = read_be32(cell);
            walk_btree((int)child_page, rl);
        } else if (page_type == 13) {
            int pos = 0;
            uint64_t payload_size;
            pos += read_varint(cell + pos, &payload_size);
            uint64_t rowid;
            pos += read_varint(cell + pos, &rowid);

            size_t pl_len;
            uint8_t *pl = read_leaf_payload(cell, &pl_len);
            rowlist_add(rl, (int64_t)rowid, pl, pl_len);
        }
    }

    if (page_type == 5) {
        uint32_t rightmost = read_be32(page + hdr_off + 8);
        walk_btree((int)rightmost, rl);
    }
}

static int parse_columns(const char *sql, char names[][1024], int is_rowid_alias[], int max_cols) {
    const char *p = sql;

    while (*p && *p != '(') p++;
    if (!*p) return 0;
    p++;

    int num_cols = 0;

    while (*p && num_cols < max_cols) {
        while (*p && isspace((unsigned char)*p)) p++;
        if (*p == ')') break;

        char col_name[1024] = {0};

        if (*p == '"') {
            p++;
            int j = 0;
            while (*p && *p != '"') {
                col_name[j++] = *p++;
            }
            col_name[j] = '\0';
            if (*p == '"') p++;
        } else {
            int j = 0;
            while (*p && (isalnum((unsigned char)*p) || *p == '_' || *p == '$')) {
                col_name[j++] = *p++;
            }
            col_name[j] = '\0';
        }

        const char *def_start = p;
        int def_depth = 0;
        while (*p) {
            if (*p == '(') def_depth++;
            else if (*p == ')') {
                if (def_depth == 0) break;
                def_depth--;
            } else if (*p == ',' && def_depth == 0) {
                break;
            }
            p++;
        }

        const char *tp = def_start;
        while (*tp && isspace((unsigned char)*tp)) tp++;

        char type_name[256] = {0};
        int ti = 0;
        while (*tp && (isalnum((unsigned char)*tp) || *tp == '_')) {
            type_name[ti++] = *tp++;
        }
        type_name[ti] = '\0';

        int is_integer_type = (strcasecmp(type_name, "INTEGER") == 0);

        int has_primary_key = 0;
        {
            size_t def_len = (size_t)(p - def_start);
            char *upper = malloc(def_len + 1);
            for (size_t i = 0; i < def_len; i++) {
                upper[i] = toupper((unsigned char)def_start[i]);
            }
            upper[def_len] = '\0';
            if (strstr(upper, "PRIMARY KEY")) {
                has_primary_key = 1;
            }
            free(upper);
        }

        is_rowid_alias[num_cols] = (is_integer_type && has_primary_key);

        strncpy(names[num_cols], col_name, 1023);
        names[num_cols][1023] = '\0';
        num_cols++;

        if (*p == ',') p++;
    }

    return num_cols;
}

static void format_real(double d, char *buf, size_t bufsize) {
    if (d == 0.0) {
        snprintf(buf, bufsize, "0.0");
        return;
    }

    int neg = 0;
    if (d < 0) {
        neg = 1;
        d = -d;
    }

    char tmp[512];
    snprintf(tmp, sizeof(tmp), "%.8f", d);

    if (neg) {
        buf[0] = '-';
        strncpy(buf + 1, tmp, bufsize - 1);
        buf[bufsize - 1] = '\0';
    } else {
        strncpy(buf, tmp, bufsize);
        buf[bufsize - 1] = '\0';
    }

    char *dot = strchr(buf, '.');
    if (dot) {
        char *end = buf + strlen(buf) - 1;
        while (end > dot + 1 && *end == '0') end--;
        *(end + 1) = '\0';
    }
}

static void print_value(const Value *v) {
    switch (v->type) {
        case V_NULL:
            printf("NULL");
            break;
        case V_INT:
            printf("%lld", (long long)v->ival);
            break;
        case V_REAL: {
            char buf[512];
            format_real(v->dval, buf, sizeof(buf));
            printf("%s", buf);
            break;
        }
        case V_TEXT:
            if (v->len <= 100) {
                printf("\"");
                for (size_t i = 0; i < v->len; i++) {
                    uint8_t c = v->data[i];
                    if (c == '\\') printf("\\\\");
                    else if (c == '"') printf("\\\"");
                    else if (c == '\n') printf("\\n");
                    else if (c == '\r') printf("\\r");
                    else if (c == '\t') printf("\\t");
                    else if (c < 0x20 || c == 0x7F) printf("\\x%02X", c);
                    else putchar(c);
                }
                printf("\"");
            } else {
                printf("<TEXT len=%zu crc32=%08x>", v->len, crc32_compute(v->data, v->len));
            }
            break;
        case V_BLOB:
            if (v->len <= 100) {
                printf("X'");
                for (size_t i = 0; i < v->len; i++) {
                    printf("%02X", v->data[i]);
                }
                printf("'");
            } else {
                printf("<BLOB len=%zu crc32=%08x>", v->len, crc32_compute(v->data, v->len));
            }
            break;
    }
}

typedef struct {
    char *name;
    int rootpage;
    char *sql;
} SchemaEntry;

int main(int argc, char *argv[]) {
    if (argc < 2) return 1;

    crc32_init();

    char path[4096];
    snprintf(path, sizeof(path), "%s/db.sqlite", argv[1]);

    FILE *f = fopen(path, "rb");
    if (!f) {
        perror(path);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    db_size = (size_t)ftell(f);
    fseek(f, 0, SEEK_SET);
    db = malloc(db_size);
    fread(db, 1, db_size, f);
    fclose(f);

    int ps = read_be16(db + 16);
    page_size = (ps == 1) ? 65536 : ps;
    reserved_bytes = db[20];
    usable_size = page_size - reserved_bytes;

    RowList schema_rows;
    rowlist_init(&schema_rows);
    walk_btree(1, &schema_rows);

    SchemaEntry *tables = malloc(sizeof(SchemaEntry) * 4096);
    int num_tables = 0;

    for (int i = 0; i < schema_rows.count; i++) {
        Value vals[5];
        int ncols = decode_record(schema_rows.rows[i].payload, schema_rows.rows[i].payload_len, vals, 5);

        if (ncols < 5) continue;

        if (vals[0].type != V_TEXT || vals[0].len != 5) continue;
        if (memcmp(vals[0].data, "table", 5) != 0) continue;

        if (vals[1].type != V_TEXT) continue;
        if (vals[1].len >= 7 && memcmp(vals[1].data, "sqlite_", 7) == 0) continue;

        if (vals[3].type != V_INT) continue;

        tables[num_tables].name = malloc(vals[1].len + 1);
        memcpy(tables[num_tables].name, vals[1].data, vals[1].len);
        tables[num_tables].name[vals[1].len] = '\0';
        tables[num_tables].rootpage = (int)vals[3].ival;

        if (vals[4].type == V_TEXT) {
            tables[num_tables].sql = malloc(vals[4].len + 1);
            memcpy(tables[num_tables].sql, vals[4].data, vals[4].len);
            tables[num_tables].sql[vals[4].len] = '\0';
        } else {
            tables[num_tables].sql = calloc(1, 1);
        }

        num_tables++;
    }

    for (int i = 0; i < num_tables - 1; i++) {
        for (int j = 0; j < num_tables - 1 - i; j++) {
            if (strcmp(tables[j].name, tables[j+1].name) > 0) {
                SchemaEntry tmp = tables[j];
                tables[j] = tables[j+1];
                tables[j+1] = tmp;
            }
        }
    }

    for (int t = 0; t < num_tables; t++) {
        if (t > 0) printf("\n");

        char (*col_names)[1024] = malloc(2048 * 1024);
        int *rowid_alias = malloc(2048 * sizeof(int));
        int num_cols = parse_columns(tables[t].sql, col_names, rowid_alias, 2048);

        RowList rows;
        rowlist_init(&rows);
        walk_btree(tables[t].rootpage, &rows);

        printf("TABLE %s rows=%d\n", tables[t].name, rows.count);

        printf("COLUMNS ");
        for (int c = 0; c < num_cols; c++) {
            if (c > 0) printf(", ");
            printf("%s", col_names[c]);
        }
        printf("\n");

        for (int r = 0; r < rows.count; r++) {
            printf("%lld: ", (long long)rows.rows[r].rowid);

            Value *vals = malloc(sizeof(Value) * (num_cols > 0 ? num_cols : 1));
            int ncols = decode_record(rows.rows[r].payload, rows.rows[r].payload_len, vals, num_cols);

            for (int c = 0; c < num_cols; c++) {
                if (c > 0) printf(", ");

                if (rowid_alias[c]) {
                    printf("%lld", (long long)rows.rows[r].rowid);
                } else if (c < ncols) {
                    print_value(&vals[c]);
                } else {
                    printf("NULL");
                }
            }
            printf("\n");

            free(vals);
        }

        free(col_names);
        free(rowid_alias);
    }

    return 0;
}

import sys
import socket
import hashlib
import base64
import os
import struct


def parse_ws_url(url):
    prefix = "ws://"
    rest = url[len(prefix):]
    slash_idx = rest.index('/')
    hostport = rest[:slash_idx]
    path = rest[slash_idx:]
    if ':' in hostport:
        host, port_str = hostport.rsplit(':', 1)
        port = int(port_str)
    else:
        host = hostport
        port = 80
    return host, port, path


def generate_ws_key():
    return base64.b64encode(os.urandom(16)).decode('ascii')


def compute_accept(key):
    magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
    sha1_digest = hashlib.sha1((key + magic).encode('ascii')).digest()
    return base64.b64encode(sha1_digest).decode('ascii')


def encode_frame(opcode, payload, mask=True):
    frame = bytearray()
    frame.append(0x80 | opcode)
    mask_bit = 0x80 if mask else 0
    length = len(payload)
    if length <= 125:
        frame.append(mask_bit | length)
    elif length <= 65535:
        frame.append(mask_bit | 126)
        frame.extend(struct.pack('!H', length))
    else:
        frame.append(mask_bit | 127)
        frame.extend(struct.pack('!Q', length))
    if mask:
        while True:
            mask_key = os.urandom(4)
            if mask_key != b'\x00\x00\x00\x00':
                break
        frame.extend(mask_key)
        masked = bytearray(length)
        for i in range(length):
            masked[i] = payload[i] ^ mask_key[i % 4]
        frame.extend(masked)
    return bytes(frame)


class WebSocketClient:
    def __init__(self, sock):
        self.sock = sock
        self.buf = bytearray()
        self.sent_close = False

    def read_bytes(self, n):
        while len(self.buf) < n:
            data = self.sock.recv(65536)
            if not data:
                raise ConnectionError("Connection closed")
            self.buf.extend(data)
        result = bytes(self.buf[:n])
        self.buf = self.buf[n:]
        return result

    def read_line(self):
        while b'\r\n' not in self.buf:
            data = self.sock.recv(65536)
            if not data:
                raise ConnectionError("Connection closed")
            self.buf.extend(data)
        idx = self.buf.index(b'\r\n')
        line = bytes(self.buf[:idx])
        self.buf = self.buf[idx + 2:]
        return line

    def handshake(self, host, port, path):
        key = generate_ws_key()
        request = (
            f"GET {path} HTTP/1.1\r\n"
            f"Host: {host}:{port}\r\n"
            f"Upgrade: websocket\r\n"
            f"Connection: Upgrade\r\n"
            f"Sec-WebSocket-Version: 13\r\n"
            f"Sec-WebSocket-Key: {key}\r\n"
            f"\r\n"
        )
        self.sock.sendall(request.encode('ascii'))

        status_line = self.read_line().decode('ascii')
        parts = status_line.split(' ', 2)
        status_code = int(parts[1])
        reason = parts[2] if len(parts) > 2 else ''

        headers = {}
        while True:
            line = self.read_line()
            if line == b'':
                break
            decoded = line.decode('ascii')
            colon_idx = decoded.index(':')
            name = decoded[:colon_idx].strip().lower()
            value = decoded[colon_idx + 1:].strip()
            headers[name] = value

        if status_code != 101:
            return False, f"handshake failed: {status_code} {reason}"

        expected_accept = compute_accept(key)
        actual_accept = headers.get('sec-websocket-accept', '')
        if actual_accept != expected_accept:
            return False, "handshake failed: bad Sec-WebSocket-Accept"

        return True, key

    def read_frame(self):
        data = self.read_bytes(2)
        byte0 = data[0]
        byte1 = data[1]
        fin = (byte0 & 0x80) != 0
        opcode = byte0 & 0x0F
        masked = (byte1 & 0x80) != 0
        payload_len = byte1 & 0x7F

        if payload_len == 126:
            payload_len = struct.unpack('!H', self.read_bytes(2))[0]
        elif payload_len == 127:
            payload_len = struct.unpack('!Q', self.read_bytes(8))[0]

        mask_key = None
        if masked:
            mask_key = self.read_bytes(4)

        payload = self.read_bytes(payload_len)
        if masked:
            payload = bytes(payload[i] ^ mask_key[i % 4] for i in range(payload_len))

        return fin, opcode, payload

    def send_frame(self, opcode, payload=b''):
        frame = encode_frame(opcode, payload, mask=True)
        self.sock.sendall(frame)

    def read_message(self):
        """Read a complete message, handling fragmentation, pings, and pongs.
        Returns (opcode, payload) where opcode is 1 (text), 2 (binary), or 8 (close)."""
        while True:
            fin, opcode, payload = self.read_frame()

            if opcode == 9:  # Ping
                self.send_frame(10, payload)
                continue
            elif opcode == 10:  # Unsolicited pong
                continue
            elif opcode == 8:  # Close
                return (8, payload)

            # Data frame (text=1 or binary=2)
            if fin:
                return (opcode, payload)

            # Start of fragmented message
            accumulated = bytearray(payload)
            msg_opcode = opcode
            while not fin:
                fin, opcode, payload = self.read_frame()
                if opcode == 9:
                    self.send_frame(10, payload)
                    continue
                elif opcode == 10:
                    continue
                elif opcode == 8:
                    return (8, payload)
                accumulated.extend(payload)
            return (msg_opcode, bytes(accumulated))

    def handle_close(self, payload):
        code = struct.unpack('!H', payload[:2])[0] if len(payload) >= 2 else 1005
        reason = payload[2:].decode('utf-8') if len(payload) > 2 else ''
        if not self.sent_close:
            close_payload = struct.pack('!H', code)
            self.send_frame(8, close_payload)
            self.sent_close = True
        if reason:
            print(f"closed {code} {reason}")
        else:
            print(f"closed {code}")

    def process_session(self):
        while True:
            opcode, payload = self.read_message()

            if opcode == 8:
                self.handle_close(payload)
                return

            if opcode == 1:
                text = payload.decode('utf-8')
                result = self.handle_command(text)
                if result == 'close':
                    return
            # opcode == 2 unexpected here, ignore

    def handle_command(self, text):
        if text.startswith('ADD '):
            parts = text.split()
            a = int(parts[1])
            b = int(parts[2])
            result = str(a + b)
            self.send_frame(1, result.encode('utf-8'))
            print(f"{text} -> {result}")

        elif text.startswith('REV '):
            rev_text = text[4:]
            reversed_text = rev_text[::-1]
            self.send_frame(1, reversed_text.encode('utf-8'))
            print(f"{text} -> {reversed_text}")

        elif text == 'SHA1':
            opcode, payload = self.read_message()
            if opcode == 8:
                self.handle_close(payload)
                return 'close'
            hex_digest = hashlib.sha1(payload).hexdigest()
            self.send_frame(1, hex_digest.encode('utf-8'))
            print(f"SHA1 {len(payload)} -> {hex_digest}")

        elif text == 'BYE':
            close_payload = struct.pack('!H', 1000)
            self.send_frame(8, close_payload)
            self.sent_close = True
            while True:
                opcode, payload = self.read_message()
                if opcode == 8:
                    self.handle_close(payload)
                    return 'close'

        return None

    def close(self):
        try:
            self.sock.close()
        except Exception:
            pass


def main():
    urls = sys.argv[1:]
    for i, url in enumerate(urls, 1):
        print(f"session {i}")
        host, port, path = parse_ws_url(url)
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.connect((host, port))
        except Exception:
            print("handshake failed: connection refused")
            continue

        client = WebSocketClient(sock)
        try:
            success, msg = client.handshake(host, port, path)
            if not success:
                print(msg)
                client.close()
                continue
            client.process_session()
        except Exception:
            pass
        finally:
            client.close()


if __name__ == '__main__':
    main()

import sys
import socket
import hashlib
import base64
import os
import struct


def parse_ws_url(url):
    prefix = "ws://"
    rest = url[len(prefix):]
    slash_idx = rest.index('/')
    hostport = rest[:slash_idx]
    path = rest[slash_idx:]
    if ':' in hostport:
        host, port_str = hostport.rsplit(':', 1)
        port = int(port_str)
    else:
        host = hostport
        port = 80
    return host, port, path


def generate_ws_key():
    return base64.b64encode(os.urandom(16)).decode('ascii')


def compute_accept(key):
    magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
    sha1_digest = hashlib.sha1((key + magic).encode('ascii')).digest()
    return base64.b64encode(sha1_digest).decode('ascii')


def encode_frame(opcode, payload, mask=True):
    frame = bytearray()
    frame.append(0x80 | opcode)
    mask_bit = 0x80 if mask else 0
    length = len(payload)
    if length <= 125:
        frame.append(mask_bit | length)
    elif length <= 65535:
        frame.append(mask_bit | 126)
        frame.extend(struct.pack('!H', length))
    else:
        frame.append(mask_bit | 127)
        frame.extend(struct.pack('!Q', length))
    if mask:
        while True:
            mask_key = os.urandom(4)
            if mask_key != b'\x00\x00\x00\x00':
                break
        frame.extend(mask_key)
        masked = bytearray(length)
        for i in range(length):
            masked[i] = payload[i] ^ mask_key[i % 4]
        frame.extend(masked)
    return bytes(frame)


class WebSocketClient:
    def __init__(self, sock):
        self.sock = sock
        self.buf = bytearray()
        self.sent_close = False

    def read_bytes(self, n):
        while len(self.buf) < n:
            data = self.sock.recv(65536)
            if not data:
                raise ConnectionError("Connection closed")
            self.buf.extend(data)
        result = bytes(self.buf[:n])
        self.buf = self.buf[n:]
        return result

    def read_line(self):
        while b'\r\n' not in self.buf:
            data = self.sock.recv(65536)
            if not data:
                raise ConnectionError("Connection closed")
            self.buf.extend(data)
        idx = self.buf.index(b'\r\n')
        line = bytes(self.buf[:idx])
        self.buf = self.buf[idx + 2:]
        return line

    def handshake(self, host, port, path):
        key = generate_ws_key()
        request = (
            f"GET {path} HTTP/1.1\r\n"
            f"Host: {host}:{port}\r\n"
            f"Upgrade: websocket\r\n"
            f"Connection: Upgrade\r\n"
            f"Sec-WebSocket-Version: 13\r\n"
            f"Sec-WebSocket-Key: {key}\r\n"
            f"\r\n"
        )
        self.sock.sendall(request.encode('ascii'))

        status_line = self.read_line().decode('ascii')
        parts = status_line.split(' ', 2)
        status_code = int(parts[1])
        reason = parts[2] if len(parts) > 2 else ''

        headers = {}
        while True:
            line = self.read_line()
            if line == b'':
                break
            decoded = line.decode('ascii')
            colon_idx = decoded.index(':')
            name = decoded[:colon_idx].strip().lower()
            value = decoded[colon_idx + 1:].strip()
            headers[name] = value

        if status_code != 101:
            return False, f"handshake failed: {status_code} {reason}"

        expected_accept = compute_accept(key)
        actual_accept = headers.get('sec-websocket-accept', '')
        if actual_accept != expected_accept:
            return False, "handshake failed: bad Sec-WebSocket-Accept"

        return True, key

    def read_frame(self):
        data = self.read_bytes(2)
        byte0 = data[0]
        byte1 = data[1]
        fin = (byte0 & 0x80) != 0
        opcode = byte0 & 0x0F
        masked = (byte1 & 0x80) != 0
        payload_len = byte1 & 0x7F

        if payload_len == 126:
            payload_len = struct.unpack('!H', self.read_bytes(2))[0]
        elif payload_len == 127:
            payload_len = struct.unpack('!Q', self.read_bytes(8))[0]

        mask_key = None
        if masked:
            mask_key = self.read_bytes(4)

        payload = self.read_bytes(payload_len)
        if masked:
            payload = bytes(payload[i] ^ mask_key[i % 4] for i in range(payload_len))

        return fin, opcode, payload

    def send_frame(self, opcode, payload=b''):
        frame = encode_frame(opcode, payload, mask=True)
        self.sock.sendall(frame)

    def read_message(self):
        """Read a complete message, handling fragmentation, pings, and pongs.
        Returns (opcode, payload) where opcode is 1 (text), 2 (binary), or 8 (close)."""
        while True:
            fin, opcode, payload = self.read_frame()

            if opcode == 9:  # Ping
                self.send_frame(10, payload)
                continue
            elif opcode == 10:  # Unsolicited pong
                continue
            elif opcode == 8:  # Close
                return (8, payload)

            # Data frame (text=1 or binary=2)
            if fin:
                return (opcode, payload)

            # Start of fragmented message
            accumulated = bytearray(payload)
            msg_opcode = opcode
            while True:
                fin2, opcode2, payload2 = self.read_frame()
                if opcode2 == 9:
                    self.send_frame(10, payload2)
                    continue
                elif opcode2 == 10:
                    continue
                elif opcode2 == 8:
                    return (8, payload2)
                accumulated.extend(payload2)
                if fin2:
                    break
            return (msg_opcode, bytes(accumulated))

    def handle_close(self, payload):
        code = struct.unpack('!H', payload[:2])[0] if len(payload) >= 2 else 1005
        reason = payload[2:].decode('utf-8') if len(payload) > 2 else ''
        if not self.sent_close:
            close_payload = struct.pack('!H', code)
            self.send_frame(8, close_payload)
            self.sent_close = True
        if reason:
            print(f"closed {code} {reason}")
        else:
            print(f"closed {code}")

    def process_session(self):
        while True:
            opcode, payload = self.read_message()

            if opcode == 8:
                self.handle_close(payload)
                return

            if opcode == 1:
                text = payload.decode('utf-8')
                result = self.handle_command(text)
                if result == 'close':
                    return
            # opcode == 2 unexpected here, ignore

    def handle_command(self, text):
        if text.startswith('ADD '):
            parts = text.split()
            a = int(parts[1])
            b = int(parts[2])
            result = str(a + b)
            self.send_frame(1, result.encode('utf-8'))
            print(f"{text} -> {result}")

        elif text.startswith('REV '):
            rev_text = text[4:]
            reversed_text = rev_text[::-1]
            self.send_frame(1, reversed_text.encode('utf-8'))
            print(f"{text} -> {reversed_text}")

        elif text == 'SHA1':
            opcode, payload = self.read_message()
            if opcode == 8:
                self.handle_close(payload)
                return 'close'
            hex_digest = hashlib.sha1(payload).hexdigest()
            self.send_frame(1, hex_digest.encode('utf-8'))
            print(f"SHA1 {len(payload)} -> {hex_digest}")

        elif text == 'BYE':
            close_payload = struct.pack('!H', 1000)
            self.send_frame(8, close_payload)
            self.sent_close = True
            while True:
                opcode, payload = self.read_message()
                if opcode == 8:
                    self.handle_close(payload)
                    return 'close'

        return None

    def close(self):
        try:
            self.sock.close()
        except Exception:
            pass


def main():
    urls = sys.argv[1:]
    for i, url in enumerate(urls, 1):
        print(f"session {i}")
        host, port, path = parse_ws_url(url)
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.connect((host, port))
        except Exception:
            print("handshake failed: connection refused")
            continue

        client = WebSocketClient(sock)
        try:
            success, msg = client.handshake(host, port, path)
            if not success:
                print(msg)
                client.close()
                continue
            client.process_session()
        except Exception:
            pass
        finally:
            client.close()


