    main()

use std::env;
use std::fs;

#[derive(Clone, Debug)]
enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_varint(data: &[u8], offset: usize) -> (u64, usize) {
    let mut result: u64 = 0;
    let mut i = 0;
    while i < 8 {
        let byte = data[offset + i] as u64;
        result = (result << 7) | (byte & 0x7F);
        if byte < 0x80 {
            return (result, i + 1);
        }
        i += 1;
    }
    let byte = data[offset + 8] as u64;
    result = (result << 8) | byte;
    (result, 9)
}

fn read_u16be(data: &[u8], offset: usize) -> u16 {
    u16::from_be_bytes([data[offset], data[offset + 1]])
}

fn read_u32be(data: &[u8], offset: usize) -> u32 {
    u32::from_be_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn read_int_bytes(data: &[u8], offset: usize, len: usize) -> i64 {
    let mut val: u64 = 0;
    for i in 0..len {
        val = (val << 8) | data[offset + i] as u64;
    }
    if len < 8 && (val >> (len * 8 - 1)) != 0 {
        val |= !((1u64 << (len * 8)) - 1);
    }
    val as i64
}

struct Db<'a> {
    data: &'a [u8],
    page_size: usize,
    usable: usize,
}

impl<'a> Db<'a> {
    fn page(&self, num: usize) -> &'a [u8] {
        &self.data[(num - 1) * self.page_size..num * self.page_size]
    }

    fn walk_btree(&self, root_page: usize, rows: &mut Vec<(i64, Vec<u8>)>) {
        let pg = self.page(root_page);
        let hdr_off = if root_page == 1 { 100 } else { 0 };
        let flags = pg[hdr_off];
        let num_cells = read_u16be(pg, hdr_off + 3) as usize;

        if flags == 0x0D {
            let ptr_start = hdr_off + 8;
            let x = self.usable - 35;
            let m = ((self.usable - 12) * 64 / 255) - 23;
            let small_m = ((self.usable - 12) * 32 / 255) - 23;

            for i in 0..num_cells {
                let cell_off = read_u16be(pg, ptr_start + i * 2) as usize;
                let (payload_size_v, n1) = read_varint(pg, cell_off);
                let (rowid_v, n2) = read_varint(pg, cell_off + n1);
                let payload_size = payload_size_v as usize;
                let rowid = rowid_v as i64;

                let mut payload = Vec::with_capacity(payload_size);

                if payload_size <= x {
                    let start = cell_off + n1 + n2;
                    payload.extend_from_slice(&pg[start..start + payload_size]);
                } else {
                    let k = (payload_size - m) % (self.usable - 4);
                    let local = if k <= small_m { m + k } else { small_m };
                    let actual_local = local - 4;
                    let start = cell_off + n1 + n2;
                    payload.extend_from_slice(&pg[start..start + actual_local]);

                    let ovf_page = read_u32be(pg, start + actual_local);
                    let mut remaining = payload_size - actual_local;
                    let mut page = ovf_page as usize;
                    while page != 0 && remaining > 0 {
                        let ovf_pg = self.page(page);
                        let next = read_u32be(ovf_pg, 0);
                        let take = std::cmp::min(remaining, self.usable - 4);
                        payload.extend_from_slice(&ovf_pg[4..4 + take]);
                        remaining -= take;
                        page = next as usize;
                    }
                }

                rows.push((rowid, payload));
            }
        } else if flags == 0x05 {
            let ptr_start = hdr_off + 12;
            let rightmost = read_u32be(pg, hdr_off + 8) as usize;

            for i in 0..num_cells {
                let cell_off = read_u16be(pg, ptr_start + i * 2) as usize;
                let child_page = read_u32be(pg, cell_off) as usize;
                self.walk_btree(child_page, rows);
            }
            self.walk_btree(rightmost, rows);
        }
    }
}

fn parse_record(payload: &[u8]) -> Vec<Value> {
    if payload.is_empty() {
        return vec![];
    }
    let (header_size_v, n) = read_varint(payload, 0);
    let header_size = header_size_v as usize;

    let mut serial_types = Vec::new();
    let mut pos = n;
    while pos < header_size {
        let (st, br) = read_varint(payload, pos);
        serial_types.push(st);
        pos += br;
    }

    let mut values = Vec::new();
    let mut dp = header_size;

    for &st in &serial_types {
        let val = match st {
            0 => Value::Null,
            1 => { let v = read_int_bytes(payload, dp, 1); dp += 1; Value::Integer(v) }
            2 => { let v = read_int_bytes(payload, dp, 2); dp += 2; Value::Integer(v) }
            3 => { let v = read_int_bytes(payload, dp, 3); dp += 3; Value::Integer(v) }
            4 => { let v = read_int_bytes(payload, dp, 4); dp += 4; Value::Integer(v) }
            5 => { let v = read_int_bytes(payload, dp, 6); dp += 6; Value::Integer(v) }
            6 => { let v = read_int_bytes(payload, dp, 8); dp += 8; Value::Integer(v) }
            7 => {
                let bits = u64::from_be_bytes([
                    payload[dp], payload[dp+1], payload[dp+2], payload[dp+3],
                    payload[dp+4], payload[dp+5], payload[dp+6], payload[dp+7],
                ]);
                dp += 8;
                Value::Real(f64::from_bits(bits))
            }
            8 => Value::Integer(0),
            9 => Value::Integer(1),
            n if n >= 12 && n % 2 == 0 => {
                let len = ((n - 12) / 2) as usize;
                let v = payload[dp..dp + len].to_vec();
                dp += len;
                Value::Blob(v)
            }
            n if n >= 13 && n % 2 == 1 => {
                let len = ((n - 13) / 2) as usize;
                let v = payload[dp..dp + len].to_vec();
                dp += len;
                Value::Text(v)
            }
            _ => Value::Null,
        };
        values.push(val);
    }
    values
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn format_real(f: f64) -> String {
    let s = format!("{:.8}", f);
    let s = s.trim_end_matches('0');
    if s.ends_with('.') {
        format!("{}0", s)
    } else {
        s.to_string()
    }
}

fn format_text(bytes: &[u8]) -> String {
    let mut result: Vec<u8> = Vec::new();
    result.push(b'"');
    for &b in bytes {
        match b {
            b'\\' => result.extend_from_slice(b"\\\\"),
            b'"' => result.extend_from_slice(b"\\\""),
            b'\n' => result.extend_from_slice(b"\\n"),
            b'\r' => result.extend_from_slice(b"\\r"),
            b'\t' => result.extend_from_slice(b"\\t"),
            0x7f => result.extend_from_slice(b"\\x7F"),
            _ if b < 0x20 => {
                result.push(b'\\');
                result.push(b'x');
                let hex = b"0123456789ABCDEF";
                result.push(hex[(b >> 4) as usize]);
                result.push(hex[(b & 0xF) as usize]);
            }
            _ => result.push(b),
        }
    }
    result.push(b'"');
    String::from_utf8(result).unwrap()
}

fn format_blob(bytes: &[u8]) -> String {
    let mut result = String::from("X'");
    for &b in bytes {
        result.push_str(&format!("{:02X}", b));
    }
    result.push('\'');
    result
}

fn format_value(v: &Value) -> String {
    match v {
        Value::Null => "NULL".to_string(),
        Value::Integer(n) => n.to_string(),
        Value::Real(f) => format_real(*f),
        Value::Text(bytes) => {
            if bytes.len() <= 100 {
                format_text(bytes)
            } else {
                let crc = crc32(bytes);
                format!("<TEXT len={} crc32={:08x}>", bytes.len(), crc)
            }
        }
        Value::Blob(bytes) => {
            if bytes.len() <= 100 {
                format_blob(bytes)
            } else {
                let crc = crc32(bytes);
                format!("<BLOB len={} crc32={:08x}>", bytes.len(), crc)
            }
        }
    }
}

fn is_ident_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

fn skip_ws(data: &[u8], mut pos: usize) -> usize {
    while pos < data.len() && matches!(data[pos], b' ' | b'\t' | b'\n' | b'\r') {
        pos += 1;
    }
    pos
}

fn skip_keyword(data: &[u8], mut pos: usize, kw: &str) -> usize {
    pos = skip_ws(data, pos);
    if pos + kw.len() <= data.len() && data[pos..pos + kw.len()].eq_ignore_ascii_case(kw.as_bytes()) {
        pos += kw.len();
    }
    pos
}

struct ColumnDef {
    name: String,
    is_rowid_alias: bool,
}

fn parse_columns(sql: &str) -> Vec<ColumnDef> {
    let sb = sql.as_bytes();
    let mut pos = 0;

    pos = skip_keyword(sb, pos, "CREATE");
    pos = skip_keyword(sb, pos, "TABLE");

    // Try to skip IF NOT EXISTS
    let save = pos;
    let p1 = skip_keyword(sb, pos, "IF");
    if p1 > pos {
        let p2 = skip_keyword(sb, p1, "NOT");
        if p2 > p1 {
            let p3 = skip_keyword(sb, p2, "EXISTS");
            if p3 > p2 {
                pos = p3;
            } else {
                pos = save;
            }
        } else {
            pos = save;
        }
    }

    pos = skip_ws(sb, pos);

    // Skip table name
    if pos < sb.len() && sb[pos] == b'"' {
        pos += 1;
        while pos < sb.len() && sb[pos] != b'"' { pos += 1; }
        pos += 1;
    } else {
        while pos < sb.len() && is_ident_char(sb[pos]) { pos += 1; }
    }

    pos = skip_ws(sb, pos);

    if pos >= sb.len() || sb[pos] != b'(' {
        return vec![];
    }
    pos += 1;

    // Find matching close paren
    let defs_start = pos;
    let mut depth = 1;
    while pos < sb.len() && depth > 0 {
        if sb[pos] == b'(' { depth += 1; }
        else if sb[pos] == b')' { depth -= 1; }
        if depth > 0 { pos += 1; }
    }
    let defs_str = &sql[defs_start..pos];

    let defs = split_top_level_commas(defs_str);
    defs.iter().map(|d| parse_column_def(d)).collect()
}

fn split_top_level_commas(s: &str) -> Vec<&str> {
    let bytes = s.as_bytes();
    let mut parts = Vec::new();
    let mut depth = 0;
    let mut start = 0;
    for i in 0..bytes.len() {
        match bytes[i] {
            b'(' => depth += 1,
            b')' => depth -= 1,
            b',' if depth == 0 => {
                parts.push(&s[start..i]);
                start = i + 1;
            }
            _ => {}
        }
    }
    if start < s.len() {
        let trimmed = &s[start..];
        if !trimmed.trim().is_empty() {
            parts.push(trimmed);
        }
    }
    parts
}

fn parse_column_def(def: &str) -> ColumnDef {
    let sb = def.as_bytes();
    let mut pos = 0;
    pos = skip_ws(sb, pos);

    // Parse column name
    let name;
    if pos < sb.len() && sb[pos] == b'"' {
        pos += 1;
        let start = pos;
        while pos < sb.len() && sb[pos] != b'"' { pos += 1; }
        name = def[start..pos].to_string();
        pos += 1;
    } else {
        let start = pos;
        while pos < sb.len() && is_ident_char(sb[pos]) { pos += 1; }
        name = def[start..pos].to_string();
    }

    // Parse type word
    pos = skip_ws(sb, pos);
    let type_start = pos;
    while pos < sb.len() && is_ident_char(sb[pos]) { pos += 1; }
    let type_word = def[type_start..pos].to_uppercase();

    // Check if followed by ( meaning type has arguments
    let pos_after_word = pos;
    pos = skip_ws(sb, pos);
    let has_args = pos < sb.len() && sb[pos] == b'(';

    // Check if definition contains PRIMARY KEY
    let def_upper = def.to_uppercase();
    let has_pk = def_upper.contains("PRIMARY KEY");

    let is_rowid_alias = type_word == "INTEGER" && !has_args && has_pk;

    ColumnDef { name, is_rowid_alias }
}

fn value_to_string(v: &Value) -> String {
    match v {
        Value::Text(b) => String::from_utf8_lossy(b).to_string(),
        Value::Blob(b) => String::from_utf8_lossy(b).to_string(),
        Value::Integer(n) => n.to_string(),
        Value::Real(f) => format!("{}", f),
        Value::Null => String::new(),
    }
}

fn value_to_i64(v: &Value) -> i64 {
    match v {
        Value::Integer(n) => *n,
        _ => 0,
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/db.sqlite", dir);
    let data = fs::read(&path).unwrap();

    let page_size_raw = u16::from_be_bytes([data[16], data[17]]) as usize;
    let page_size = if page_size_raw == 1 { 65536 } else { page_size_raw };
    let reserved = data[20] as usize;
    let usable = page_size - reserved;

    let db = Db { data: &data, page_size, usable };

    // Read schema from page 1
    let mut schema_entries: Vec<(String, usize, String)> = Vec::new();
    let mut raw_rows = Vec::new();
    db.walk_btree(1, &mut raw_rows);

    for (_rowid, payload) in &raw_rows {
        let values = parse_record(payload);
        if values.len() < 4 { continue; }

        let typ = value_to_string(&values[0]);
        let name = value_to_string(&values[1]);
        let rootpage = value_to_i64(&values[3]) as usize;
        let sql = if values.len() > 4 { value_to_string(&values[4]) } else { String::new() };

        if typ == "table" && !name.starts_with("sqlite_") {
            schema_entries.push((name, rootpage, sql));
        }
    }

    // Sort by name byte-wise ascending
    schema_entries.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));

    let mut first_table = true;
    for (tname, rootpage, sql) in &schema_entries {
        if !first_table { println!(); }
        first_table = false;

        let columns = parse_columns(sql);

        let mut raw = Vec::new();
        db.walk_btree(*rootpage, &mut raw);

        let mut rows: Vec<(i64, Vec<Value>)> = Vec::new();
        for (rowid, payload) in &raw {
            let mut values = parse_record(payload);
            while values.len() < columns.len() {
                values.push(Value::Null);
            }
            rows.push((*rowid, values));
        }

        rows.sort_by_key(|(r, _)| *r);

        println!("TABLE {} rows={}", tname, rows.len());

        let col_names: Vec<&str> = columns.iter().map(|c| c.name.as_str()).collect();
        println!("COLUMNS {}", col_names.join(", "));

        for (rowid, values) in &rows {
            let parts: Vec<String> = columns.iter().enumerate().map(|(i, col)| {
                if col.is_rowid_alias {
                    format_value(&Value::Integer(*rowid))
                } else {
                    format_value(&values[i])
                }
            }).collect();
            println!("{}: {}", rowid, parts.join(", "));
        }
    }
}

use std::env;
use std::fs;

#[derive(Clone, Debug)]
enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_varint(data: &[u8], offset: usize) -> (u64, usize) {
    let mut result: u64 = 0;
    let mut i = 0;
    while i < 8 {
        let byte = data[offset + i] as u64;
        result = (result << 7) | (byte & 0x7F);
        if byte < 0x80 {
            return (result, i + 1);
        }
        i += 1;
    }
    let byte = data[offset + 8] as u64;
    result = (result << 8) | byte;
    (result, 9)
}

fn read_u16be(data: &[u8], offset: usize) -> u16 {
    u16::from_be_bytes([data[offset], data[offset + 1]])
}

fn read_u32be(data: &[u8], offset: usize) -> u32 {
    u32::from_be_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn read_int_bytes(data: &[u8], offset: usize, len: usize) -> i64 {
    let mut val: u64 = 0;
    for i in 0..len {
        val = (val << 8) | data[offset + i] as u64;
    }
    if len < 8 && (val >> (len * 8 - 1)) != 0 {
        val |= !((1u64 << (len * 8)) - 1);
    }
    val as i64
}

struct Db<'a> {
    data: &'a [u8],
    page_size: usize,
    usable: usize,
}

impl<'a> Db<'a> {
    fn page(&self, num: usize) -> &'a [u8] {
        &self.data[(num - 1) * self.page_size..num * self.page_size]
    }

    fn walk_btree(&self, root_page: usize, rows: &mut Vec<(i64, Vec<u8>)>) {
        let pg = self.page(root_page);
        let hdr_off = if root_page == 1 { 100 } else { 0 };
        let flags = pg[hdr_off];
        let num_cells = read_u16be(pg, hdr_off + 3) as usize;

        if flags == 0x0D {
            let ptr_start = hdr_off + 8;
            let x = self.usable - 35;
            let big_m = ((self.usable - 12) * 64 / 255) - 23;
            let small_m = ((self.usable - 12) * 32 / 255) - 23;

            for i in 0..num_cells {
                let cell_off = read_u16be(pg, ptr_start + i * 2) as usize;
                let (payload_size_v, n1) = read_varint(pg, cell_off);
                let (rowid_v, n2) = read_varint(pg, cell_off + n1);
                let payload_size = payload_size_v as usize;
                let rowid = rowid_v as i64;

                let mut payload = Vec::with_capacity(payload_size);

                if payload_size <= x {
                    let start = cell_off + n1 + n2;
                    payload.extend_from_slice(&pg[start..start + payload_size]);
                } else {
                    let k = (payload_size - big_m) % (self.usable - 4);
                    let local = if k <= small_m { big_m + k } else { small_m };
                    let start = cell_off + n1 + n2;
                    payload.extend_from_slice(&pg[start..start + local]);

                    let ovf_page = read_u32be(pg, start + local);
                    let mut remaining = payload_size - local;
                    let mut page = ovf_page as usize;
                    while page != 0 && remaining > 0 {
                        let ovf_pg = self.page(page);
                        let next = read_u32be(ovf_pg, 0);
                        let take = std::cmp::min(remaining, self.usable - 4);
                        payload.extend_from_slice(&ovf_pg[4..4 + take]);
                        remaining -= take;
                        page = next as usize;
                    }
                }

                rows.push((rowid, payload));
            }
        } else if flags == 0x05 {
            let ptr_start = hdr_off + 12;
            let rightmost = read_u32be(pg, hdr_off + 8) as usize;

            for i in 0..num_cells {
                let cell_off = read_u16be(pg, ptr_start + i * 2) as usize;
                let child_page = read_u32be(pg, cell_off) as usize;
                self.walk_btree(child_page, rows);
            }
            self.walk_btree(rightmost, rows);
        }
    }
}

fn parse_record(payload: &[u8]) -> Vec<Value> {
    if payload.is_empty() {
        return vec![];
    }
    let (header_size_v, n) = read_varint(payload, 0);
    let header_size = header_size_v as usize;

    let mut serial_types = Vec::new();
    let mut pos = n;
    while pos < header_size {
        let (st, br) = read_varint(payload, pos);
        serial_types.push(st);
        pos += br;
    }

    let mut values = Vec::new();
    let mut dp = header_size;

    for &st in &serial_types {
        let val = match st {
            0 => Value::Null,
            1 => { let v = read_int_bytes(payload, dp, 1); dp += 1; Value::Integer(v) }
            2 => { let v = read_int_bytes(payload, dp, 2); dp += 2; Value::Integer(v) }
            3 => { let v = read_int_bytes(payload, dp, 3); dp += 3; Value::Integer(v) }
            4 => { let v = read_int_bytes(payload, dp, 4); dp += 4; Value::Integer(v) }
            5 => { let v = read_int_bytes(payload, dp, 6); dp += 6; Value::Integer(v) }
            6 => { let v = read_int_bytes(payload, dp, 8); dp += 8; Value::Integer(v) }
            7 => {
                let bits = u64::from_be_bytes([
                    payload[dp], payload[dp+1], payload[dp+2], payload[dp+3],
                    payload[dp+4], payload[dp+5], payload[dp+6], payload[dp+7],
                ]);
                dp += 8;
                Value::Real(f64::from_bits(bits))
            }
            8 => Value::Integer(0),
            9 => Value::Integer(1),
            n if n >= 12 && n % 2 == 0 => {
                let len = ((n - 12) / 2) as usize;
                let v = payload[dp..dp + len].to_vec();
                dp += len;
                Value::Blob(v)
            }
            n if n >= 13 && n % 2 == 1 => {
                let len = ((n - 13) / 2) as usize;
                let v = payload[dp..dp + len].to_vec();
                dp += len;
                Value::Text(v)
            }
            _ => Value::Null,
        };
        values.push(val);
    }
    values
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn format_real(f: f64) -> String {
    let s = format!("{:.8}", f);
    let s = s.trim_end_matches('0');
    if s.ends_with('.') {
        format!("{}0", s)
    } else {
        s.to_string()
    }
}

fn format_text(bytes: &[u8]) -> String {
    let mut result: Vec<u8> = Vec::new();
    result.push(b'"');
    for &b in bytes {
        match b {
            b'\\' => result.extend_from_slice(b"\\\\"),
            b'"' => result.extend_from_slice(b"\\\""),
            b'\n' => result.extend_from_slice(b"\\n"),
            b'\r' => result.extend_from_slice(b"\\r"),
            b'\t' => result.extend_from_slice(b"\\t"),
            0x7f => result.extend_from_slice(b"\\x7F"),
            _ if b < 0x20 => {
                result.push(b'\\');
                result.push(b'x');
                let hex = b"0123456789ABCDEF";
                result.push(hex[(b >> 4) as usize]);
                result.push(hex[(b & 0xF) as usize]);
            }
            _ => result.push(b),
        }
    }
    result.push(b'"');
    String::from_utf8(result).unwrap()
}

fn format_blob(bytes: &[u8]) -> String {
    let mut result = String::from("X'");
    for &b in bytes {
        result.push_str(&format!("{:02X}", b));
    }
    result.push('\'');
    result
}

fn format_value(v: &Value) -> String {
    match v {
        Value::Null => "NULL".to_string(),
        Value::Integer(n) => n.to_string(),
        Value::Real(f) => format_real(*f),
        Value::Text(bytes) => {
            if bytes.len() <= 100 {
                format_text(bytes)
            } else {
                let crc = crc32(bytes);
                format!("<TEXT len={} crc32={:08x}>", bytes.len(), crc)
            }
        }
        Value::Blob(bytes) => {
            if bytes.len() <= 100 {
                format_blob(bytes)
            } else {
                let crc = crc32(bytes);
                format!("<BLOB len={} crc32={:08x}>", bytes.len(), crc)
            }
        }
    }
}

fn is_ident_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

fn skip_ws(data: &[u8], mut pos: usize) -> usize {
    while pos < data.len() && matches!(data[pos], b' ' | b'\t' | b'\n' | b'\r') {
        pos += 1;
    }
    pos
}

fn skip_keyword(data: &[u8], mut pos: usize, kw: &str) -> usize {
    pos = skip_ws(data, pos);
    if pos + kw.len() <= data.len() && data[pos..pos + kw.len()].eq_ignore_ascii_case(kw.as_bytes()) {
        pos += kw.len();
    }
    pos
}

struct ColumnDef {
    name: String,
    is_rowid_alias: bool,
}

fn parse_columns(sql: &str) -> Vec<ColumnDef> {
    let sb = sql.as_bytes();
    let mut pos = 0;

    pos = skip_keyword(sb, pos, "CREATE");
    pos = skip_keyword(sb, pos, "TABLE");

    // Try to skip IF NOT EXISTS
    let save = pos;
    let p1 = skip_keyword(sb, pos, "IF");
    if p1 > pos {
        let p2 = skip_keyword(sb, p1, "NOT");
        if p2 > p1 {
            let p3 = skip_keyword(sb, p2, "EXISTS");
            if p3 > p2 {
                pos = p3;
            } else {
                pos = save;
            }
        } else {
            pos = save;
        }
    }

    pos = skip_ws(sb, pos);

    // Skip table name
    if pos < sb.len() && sb[pos] == b'"' {
        pos += 1;
        while pos < sb.len() && sb[pos] != b'"' { pos += 1; }
        pos += 1;
    } else {
        while pos < sb.len() && is_ident_char(sb[pos]) { pos += 1; }
    }

    pos = skip_ws(sb, pos);

    if pos >= sb.len() || sb[pos] != b'(' {
        return vec![];
    }
    pos += 1;

    // Find matching close paren
    let defs_start = pos;
    let mut depth = 1;
    while pos < sb.len() && depth > 0 {
        if sb[pos] == b'(' { depth += 1; }
        else if sb[pos] == b')' { depth -= 1; }
        if depth > 0 { pos += 1; }
    }
    let defs_str = &sql[defs_start..pos];

    let defs = split_top_level_commas(defs_str);
    defs.iter().map(|d| parse_column_def(d)).collect()
}

fn split_top_level_commas(s: &str) -> Vec<&str> {
    let bytes = s.as_bytes();
    let mut parts = Vec::new();
    let mut depth = 0;
    let mut start = 0;
    for i in 0..bytes.len() {
        match bytes[i] {
            b'(' => depth += 1,
            b')' => depth -= 1,
            b',' if depth == 0 => {
                parts.push(&s[start..i]);
                start = i + 1;
            }
            _ => {}
        }
    }
    if start < s.len() {
        let trimmed = &s[start..];
        if !trimmed.trim().is_empty() {
            parts.push(trimmed);
        }
    }
    parts
}

fn parse_column_def(def: &str) -> ColumnDef {
    let sb = def.as_bytes();
    let mut pos = 0;
    pos = skip_ws(sb, pos);

    // Parse column name
    let name;
    if pos < sb.len() && sb[pos] == b'"' {
        pos += 1;
        let start = pos;
        while pos < sb.len() && sb[pos] != b'"' { pos += 1; }
        name = def[start..pos].to_string();
        pos += 1;
    } else {
        let start = pos;
        while pos < sb.len() && is_ident_char(sb[pos]) { pos += 1; }
        name = def[start..pos].to_string();
    }

    // Parse type word
    pos = skip_ws(sb, pos);
    let type_start = pos;
    while pos < sb.len() && is_ident_char(sb[pos]) { pos += 1; }
    let type_word = def[type_start..pos].to_uppercase();

    // Check if followed by ( meaning type has arguments
    let pos_after_word = pos;
    pos = skip_ws(sb, pos);
    let has_args = pos < sb.len() && sb[pos] == b'(';
    let _ = pos_after_word;

    // Check if definition contains PRIMARY KEY
    let def_upper = def.to_uppercase();
    let has_pk = def_upper.contains("PRIMARY KEY");

    let is_rowid_alias = type_word == "INTEGER" && !has_args && has_pk;

    ColumnDef { name, is_rowid_alias }
}

fn value_to_string(v: &Value) -> String {
    match v {
        Value::Text(b) => String::from_utf8_lossy(b).to_string(),
        Value::Blob(b) => String::from_utf8_lossy(b).to_string(),
        Value::Integer(n) => n.to_string(),
        Value::Real(f) => format!("{}", f),
        Value::Null => String::new(),
    }
}

fn value_to_i64(v: &Value) -> i64 {
    match v {
        Value::Integer(n) => *n,
        _ => 0,
    }
}

