            println!("{}: {}", rowid, parts.join(", "));
        }
    }
}

import * as net from 'net';
import * as crypto from 'crypto';

interface Frame {
    fin: boolean;
    opcode: number;
    payload: Buffer;
}

class Connection {
    socket: net.Socket;
    buffer: Buffer = Buffer.alloc(0);
    ended: boolean = false;
    private pendingResolve: (() => void) | null = null;

    constructor(socket: net.Socket) {
        this.socket = socket;
        socket.on('data', (data: Buffer) => {
            this.buffer = Buffer.concat([this.buffer, data]);
            if (this.pendingResolve) {
                const r = this.pendingResolve;
                this.pendingResolve = null;
                r();
            }
        });
        socket.on('end', () => {
            this.ended = true;
            if (this.pendingResolve) {
                const r = this.pendingResolve;
                this.pendingResolve = null;
                r();
            }
        });
        socket.on('error', () => {
            this.ended = true;
            if (this.pendingResolve) {
                const r = this.pendingResolve;
                this.pendingResolve = null;
                r();
            }
        });
    }

    async waitForData(): Promise<void> {
        if (this.ended) return;
        await new Promise<void>((resolve) => {
            this.pendingResolve = resolve;
        });
    }

    async ensureBytes(n: number): Promise<boolean> {
        while (this.buffer.length < n) {
            if (this.ended) return false;
            await this.waitForData();
        }
        return true;
    }

    consume(n: number): void {
        this.buffer = this.buffer.subarray(n);
    }

    write(data: Buffer): void {
        this.socket.write(data);
    }

    close(): void {
        this.socket.destroy();
    }
}

function randomMaskKey(): Buffer {
    let key: Buffer;
    do {
        key = crypto.randomBytes(4);
    } while (key[0] === 0 && key[1] === 0 && key[2] === 0 && key[3] === 0);
    return key;
}

function buildFrame(opcode: number, payload: Buffer): Buffer {
    const maskKey = randomMaskKey();
    let headerSize: number;

    if (payload.length <= 125) {
        headerSize = 2;
    } else if (payload.length <= 65535) {
        headerSize = 4;
    } else {
        headerSize = 10;
    }

    const frame = Buffer.alloc(headerSize + 4 + payload.length);
    frame[0] = 0x80 | opcode;

    if (payload.length <= 125) {
        frame[1] = 0x80 | payload.length;
    } else if (payload.length <= 65535) {
        frame[1] = 0x80 | 126;
        frame.writeUInt16BE(payload.length, 2);
    } else {
        frame[1] = 0x80 | 127;
        frame.writeBigUInt64BE(BigInt(payload.length), 2);
    }

    maskKey.copy(frame, headerSize);
    for (let i = 0; i < payload.length; i++) {
        frame[headerSize + 4 + i] = payload[i] ^ maskKey[i % 4];
    }

    return frame;
}

async function readFrame(conn: Connection): Promise<Frame | null> {
    if (!await conn.ensureBytes(2)) return null;

    const b0 = conn.buffer[0];
    const b1 = conn.buffer[1];

    const fin = (b0 & 0x80) !== 0;
    const opcode = b0 & 0x0F;
    let payloadLength = b1 & 0x7F;
    let headerSize = 2;

    if (payloadLength === 126) {
        if (!await conn.ensureBytes(4)) return null;
        payloadLength = conn.buffer.readUInt16BE(2);
        headerSize = 4;
    } else if (payloadLength === 127) {
        if (!await conn.ensureBytes(10)) return null;
        payloadLength = Number(conn.buffer.readBigUInt64BE(2));
        headerSize = 10;
    }

    if (!await conn.ensureBytes(headerSize + payloadLength)) return null;
    const payload = Buffer.from(conn.buffer.subarray(headerSize, headerSize + payloadLength));
    conn.consume(headerSize + payloadLength);

    return { fin, opcode, payload };
}

async function readHttpHeaders(conn: Connection): Promise<string | null> {
    while (true) {
        const idx = conn.buffer.indexOf('\r\n\r\n');
        if (idx !== -1) {
            const header = conn.buffer.subarray(0, idx + 4).toString('ascii');
            conn.consume(idx + 4);
            return header;
        }
        if (conn.ended) return null;
        await conn.waitForData();
    }
}

function handleTextCommand(text: string): { reply?: string; action?: 'sha1' | 'bye' } {
    if (text === 'BYE') {
        return { action: 'bye' };
    }
    if (text === 'SHA1') {
        return { action: 'sha1' };
    }
    if (text.startsWith('ADD ')) {
        const parts = text.substring(4).split(' ');
        const a = BigInt(parts[0]);
        const b = BigInt(parts[1]);
        const sum = (a + b).toString();
        return { reply: sum };
    }
    if (text.startsWith('REV ')) {
        const textToReverse = text.substring(4);
        const reversed = [...textToReverse].reverse().join('');
        return { reply: reversed };
    }
    return {};
}

async function processSession(urlStr: string, sessionNum: number): Promise<void> {
    console.log(`session ${sessionNum}`);

    const url = new URL(urlStr);
    const port = parseInt(url.port) || 80;
    const host = url.hostname;
    const requestTarget = url.pathname + url.search;

    const socket: net.Socket = await new Promise((resolve, reject) => {
        const s = net.createConnection({ host, port }, () => resolve(s));
        s.on('error', reject);
    });

    const conn = new Connection(socket);

    const wsKey = crypto.randomBytes(16).toString('base64');

    const handshake = `GET ${requestTarget} HTTP/1.1\r\n` +
        `Host: ${host}:${port}\r\n` +
        `Upgrade: websocket\r\n` +
        `Connection: Upgrade\r\n` +
        `Sec-WebSocket-Version: 13\r\n` +
        `Sec-WebSocket-Key: ${wsKey}\r\n` +
        `\r\n`;
    conn.write(Buffer.from(handshake, 'ascii'));

    const headerBlock = await readHttpHeaders(conn);
    if (headerBlock === null) {
        conn.close();
        return;
    }

    const lines = headerBlock.split('\r\n');
    const statusLine = lines[0];
    const statusMatch = statusLine.match(/^HTTP\/\d\.\d (\d{3}) (.*)$/);
    if (!statusMatch) {
        conn.close();
        return;
    }

    const statusCode = parseInt(statusMatch[1]);
    const reasonPhrase = statusMatch[2];

    if (statusCode !== 101) {
        console.log(`handshake failed: ${statusCode} ${reasonPhrase}`);
        conn.close();
        return;
    }

    let acceptValue: string | undefined;
    for (let i = 1; i < lines.length; i++) {
        const colonIdx = lines[i].indexOf(':');
        if (colonIdx === -1) continue;
        const name = lines[i].substring(0, colonIdx).trim().toLowerCase();
        const value = lines[i].substring(colonIdx + 1).trim();
        if (name === 'sec-websocket-accept') {
            acceptValue = value;
        }
    }

    const expectedAccept = crypto.createHash('sha1')
        .update(wsKey + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11')
        .digest('base64');

    if (acceptValue !== expectedAccept) {
        console.log('handshake failed: bad Sec-WebSocket-Accept');
        conn.close();
        return;
    }

    // WebSocket frame processing loop
    let hasSentClose = false;
    let waitingForSHA1 = false;
    let currentOpcode = -1;
    let fragments: Buffer[] = [];

    while (true) {
        const frame = await readFrame(conn);
        if (frame === null) break;

        if (frame.opcode === 9) {
            conn.write(buildFrame(10, frame.payload));
            continue;
        }

        if (frame.opcode === 10) {
            continue;
        }

        if (frame.opcode === 8) {
            let code: number;
            let reason: string;
            if (frame.payload.length >= 2) {
                code = frame.payload.readUInt16BE(0);
                reason = frame.payload.subarray(2).toString('utf8');
            } else {
                code = 1005;
                reason = '';
            }
            if (reason === '') {
                console.log(`closed ${code}`);
            } else {
                console.log(`closed ${code} ${reason}`);
            }
            if (!hasSentClose) {
                const closePayload = Buffer.alloc(2);
                closePayload.writeUInt16BE(code, 0);
                conn.write(buildFrame(8, closePayload));
                hasSentClose = true;
            }
            break;
        }

        if (frame.opcode === 1 || frame.opcode === 2) {
            if (frame.fin) {
                const data = frame.payload;
                if (waitingForSHA1 && frame.opcode === 2) {
                    const hash = crypto.createHash('sha1').update(data).digest('hex');
                    conn.write(buildFrame(1, Buffer.from(hash, 'utf8')));
                    console.log(`SHA1 ${data.length} -> ${hash}`);
                    waitingForSHA1 = false;
                } else if (frame.opcode === 1) {
                    const text = data.toString('utf8');
                    const result = handleTextCommand(text);
                    if (result.action === 'bye') {
                        conn.write(buildFrame(8, Buffer.from([0x03, 0xE8])));
                        hasSentClose = true;
                    } else if (result.action === 'sha1') {
                        waitingForSHA1 = true;
                    } else if (result.reply !== undefined) {
                        conn.write(buildFrame(1, Buffer.from(result.reply, 'utf8')));
                        console.log(`${text} -> ${result.reply}`);
                    }
                }
            } else {
                currentOpcode = frame.opcode;
                fragments = [frame.payload];
            }
            continue;
        }

        if (frame.opcode === 0) {
            fragments.push(frame.payload);
            if (frame.fin) {
                const data = Buffer.concat(fragments);
                if (waitingForSHA1 && currentOpcode === 2) {
                    const hash = crypto.createHash('sha1').update(data).digest('hex');
                    conn.write(buildFrame(1, Buffer.from(hash, 'utf8')));
                    console.log(`SHA1 ${data.length} -> ${hash}`);
                    waitingForSHA1 = false;
                } else if (currentOpcode === 1) {
                    const text = data.toString('utf8');
                    const result = handleTextCommand(text);
                    if (result.action === 'bye') {
                        conn.write(buildFrame(8, Buffer.from([0x03, 0xE8])));
                        hasSentClose = true;
                    } else if (result.action === 'sha1') {
                        waitingForSHA1 = true;
                    } else if (result.reply !== undefined) {
                        conn.write(buildFrame(1, Buffer.from(result.reply, 'utf8')));
                        console.log(`${text} -> ${result.reply}`);
                    }
                }
            }
            continue;
        }
    }

    conn.close();
}

async function main(): Promise<void> {
    const args = process.argv.slice(2);
    for (let i = 0; i < args.length; i++) {
        await processSession(args[i], i + 1);
    }
}

main().then(() => { process.exit(0); }).catch(() => { process.exit(0); });

use std::collections::HashMap;
use std::env;
use std::fs;

// ===== Date/time utilities =====

fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: i64, m: i64) -> i64 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => if is_leap(y) { 29 } else { 28 },
        _ => 30,
    }
}

fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as i64;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as i64;
    (y + if m <= 2 { 1 } else { 0 }, m, d)
}

fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = (y - era * 400) as u64;
    let mp = if m > 2 { m - 3 } else { m + 9 } as u64;
    let doy = (153 * mp + 2) / 5 + d as u64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe as i64 - 719468
}

fn fmt_datetime(secs: i64) -> String {
    let days = secs.div_euclid(86400);
    let tod = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    let h = tod / 3600;
    let mi = (tod % 3600) / 60;
    let s = tod % 60;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y, m, d, h, mi, s)
}

fn fmt_offset(offset: i32) -> String {
    let sign = if offset >= 0 { '+' } else { '-' };
    let abs = offset.abs();
    let h = abs / 3600;
    let m = (abs % 3600) / 60;
    let s = abs % 60;
    if s != 0 {
        format!("{}{:02}:{:02}:{:02}", sign, h, m, s)
    } else {
        format!("{}{:02}:{:02}", sign, h, m)
    }
}

fn parse_wall_time(s: &str) -> i64 {
    let year: i64 = s[0..4].parse().unwrap();
    let month: i64 = s[5..7].parse().unwrap();
    let day: i64 = s[8..10].parse().unwrap();
    let hour: i64 = s[11..13].parse().unwrap();
    let min: i64 = s[14..16].parse().unwrap();
    let sec: i64 = s[17..19].parse().unwrap();
    days_from_civil(year, month, day) * 86400 + hour * 3600 + min * 60 + sec
}

// ===== POSIX TZ string parsing =====

struct PosixRule {
    std_name: String,
    std_offset: i32,
    dst_name: Option<String>,
    dst_offset: Option<i32>,
    start_m: i32,
    start_w: i32,
    start_d: i32,
    start_time: i32,
    end_m: i32,
    end_w: i32,
    end_d: i32,
    end_time: i32,
}

impl PosixRule {
    fn utc_std(&self) -> i32 { -self.std_offset }
    fn utc_dst(&self) -> i32 { -self.dst_offset.unwrap() }
    fn has_dst(&self) -> bool { self.dst_name.is_some() }
}

fn parse_posix(s: &str) -> PosixRule {
    let b = s.as_bytes();
    let mut p = 0usize;

    let std_name = parse_name(b, &mut p);
    let std_offset = parse_offset_val(b, &mut p);

    let mut dst_name = None;
    let mut dst_offset = None;

    if p < b.len() && (b[p] == b'<' || b[p].is_ascii_alphabetic()) {
        let n = parse_name(b, &mut p);
        dst_name = Some(n);
        if p < b.len() && (b[p] == b'+' || b[p] == b'-' || b[p].is_ascii_digit()) {
            dst_offset = Some(parse_offset_val(b, &mut p));
        } else {
            dst_offset = Some(std_offset - 3600);
        }
    }

    let mut start_m = 3i32; let mut start_w = 5i32; let mut start_d = 0i32; let mut start_time = 7200i32;
    let mut end_m = 10i32; let mut end_w = 5i32; let mut end_d = 0i32; let mut end_time = 7200i32;

    if p < b.len() && b[p] == b',' {
        p += 1;
        (start_m, start_w, start_d) = parse_md(b, &mut p);
        if p < b.len() && b[p] == b'/' {
            p += 1;
            start_time = parse_offset_val(b, &mut p);
        }
        if p < b.len() && b[p] == b',' {
            p += 1;
            (end_m, end_w, end_d) = parse_md(b, &mut p);
            if p < b.len() && b[p] == b'/' {
                p += 1;
                end_time = parse_offset_val(b, &mut p);
            }
        }
    }

    PosixRule {
        std_name, std_offset, dst_name, dst_offset,
        start_m, start_w, start_d, start_time,
        end_m, end_w, end_d, end_time,
    }
}

fn parse_name(b: &[u8], p: &mut usize) -> String {
    if *p < b.len() && b[*p] == b'<' {
        *p += 1;
        let start = *p;
        while *p < b.len() && b[*p] != b'>' { *p += 1; }
        let s = String::from_utf8(b[start..*p].to_vec()).unwrap();
        *p += 1;
        s
    } else {
        let start = *p;
        while *p < b.len() && b[*p].is_ascii_alphabetic() { *p += 1; }
        String::from_utf8(b[start..*p].to_vec()).unwrap()
    }
}

fn parse_offset_val(b: &[u8], p: &mut usize) -> i32 {
    let mut sign = 1i32;
    if *p < b.len() && b[*p] == b'-' {
        sign = -1; *p += 1;
    } else if *p < b.len() && b[*p] == b'+' {
        *p += 1;
    }
    let mut h = 0i32;
    while *p < b.len() && b[*p].is_ascii_digit() {
        h = h * 10 + (b[*p] - b'0') as i32; *p += 1;
    }
    let mut m = 0i32;
    let mut s = 0i32;
    if *p < b.len() && b[*p] == b':' {
        *p += 1;
        while *p < b.len() && b[*p].is_ascii_digit() {
            m = m * 10 + (b[*p] - b'0') as i32; *p += 1;
        }
        if *p < b.len() && b[*p] == b':' {
            *p += 1;
            while *p < b.len() && b[*p].is_ascii_digit() {
                s = s * 10 + (b[*p] - b'0') as i32; *p += 1;
            }
        }
    }
    sign * (h * 3600 + m * 60 + s)
}

fn parse_md(b: &[u8], p: &mut usize) -> (i32, i32, i32) {
    assert_eq!(b[*p], b'M'); *p += 1;
    let m = parse_num(b, p);
    assert_eq!(b[*p], b'.'); *p += 1;
    let w = parse_num(b, p);
    assert_eq!(b[*p], b'.'); *p += 1;
    let d = parse_num(b, p);
    (m, w, d)
}

fn parse_num(b: &[u8], p: &mut usize) -> i32 {
    let mut n = 0i32;
    while *p < b.len() && b[*p].is_ascii_digit() {
        n = n * 10 + (b[*p] - b'0') as i32; *p += 1;
    }
    n
}

// ===== TZif data =====

struct TzData {
    transitions: Vec<(i64, u8)>,
    types: Vec<(i32, u8, u8)>,
    abbrs: Vec<u8>,
    posix: PosixRule,
}

impl TzData {
    fn load(path: &str) -> Self {
        let data = fs::read(path).unwrap();
        let mut pos = 0usize;

        // First header
        assert_eq!(&data[0..4], b"TZif");
        pos = 44;

        // Skip first data block
        let c1: [u32; 6] = read_counts(&data[pos..]);
        pos += 24;
        let block1_size = c1[3] as usize * 4 + c1[3] as usize
            + c1[4] as usize * 6 + c1[5] as usize
            + c1[2] as usize * 8 + c1[1] as usize + c1[0] as usize;
        pos += block1_size;

        // Second header
        assert_eq!(&data[pos..pos + 4], b"TZif");
        pos += 4 + 1 + 15;
        let c2: [u32; 6] = read_counts(&data[pos..]);
        pos += 24;

        let timecnt = c2[3] as usize;
        let typecnt = c2[4] as usize;
        let charcnt = c2[5] as usize;
        let leapcnt = c2[2] as usize;
        let isstdcnt = c2[1] as usize;
        let isutcnt = c2[0] as usize;

        // 64-bit transition times
        let mut times = Vec::with_capacity(timecnt);
        for _ in 0..timecnt {
            times.push(read_i64_be(&data[pos..]));
            pos += 8;
        }

        // Type indices
        let mut tidx = Vec::with_capacity(timecnt);
        for _ in 0..timecnt {
            tidx.push(data[pos]);
            pos += 1;
        }

        let transitions: Vec<(i64, u8)> = times.into_iter().zip(tidx).collect();

        // Type records
        let mut types = Vec::with_capacity(typecnt);
        for _ in 0..typecnt {
            let gmtoff = read_i32_be(&data[pos..]); pos += 4;
            let isdst = data[pos]; pos += 1;
            let abbridx = data[pos]; pos += 1;
            types.push((gmtoff, isdst, abbridx));
        }

        // Abbreviations
        let abbrs = data[pos..pos + charcnt].to_vec();
        pos += charcnt;

        // Skip leap seconds, isstd, isut
        pos += leapcnt * 12 + isstdcnt + isutcnt;

        // Footer
        assert_eq!(data[pos], b'\n');
        pos += 1;
        let fs = pos;
        let fe = data[pos..].iter().position(|&b| b == b'\n').unwrap() + pos;
        let posix_str = String::from_utf8(data[fs..fe].to_vec()).unwrap();

        let posix = parse_posix(&posix_str);

        TzData { transitions, types, abbrs, posix }
    }

    fn get_abbr(&self, idx: u8) -> String {
        let start = idx as usize;
        let end = self.abbrs[start..].iter().position(|&b| b == 0)
            .unwrap_or(self.abbrs.len() - start) + start;
        String::from_utf8_lossy(&self.abbrs[start..end]).to_string()
    }

    fn offset_at(&self, t: i64) -> (i32, String) {
        if self.transitions.is_empty() {
            return self.posix_at(t);
        }

        let last_t = self.transitions[self.transitions.len() - 1].0;

        if t < self.transitions[0].0 {
            let (gmtoff, _, abbridx) = self.types[0];
            return (gmtoff, self.get_abbr(abbridx));
        }

        if t > last_t {
            return self.posix_at(t);
        }

        // Binary search for latest transition <= t
        let mut lo = 0usize;
        let mut hi = self.transitions.len() - 1;
        while lo < hi {
            let mid = (lo + hi + 1) / 2;
            if self.transitions[mid].0 <= t {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        let ti = self.transitions[lo].1 as usize;
        let (gmtoff, _, abbridx) = self.types[ti];
        (gmtoff, self.get_abbr(abbridx))
    }

    fn posix_at(&self, t: i64) -> (i32, String) {
        if !self.posix.has_dst() {
            return (self.posix.utc_std(), self.posix.std_name.clone());
        }

        let utc_std = self.posix.utc_std();
        let utc_dst = self.posix.utc_dst();

        let local_std_secs = t + utc_std as i64;
        let days = local_std_secs.div_euclid(86400);
        let (year, _, _) = civil_from_days(days);

        let start_utc = self.compute_start_utc(year);
        let end_utc = self.compute_end_utc(year);

        let in_dst = if start_utc <= end_utc {
            t >= start_utc && t < end_utc
        } else {
            t >= start_utc || t < end_utc
        };

        if in_dst {
            (utc_dst, self.posix.dst_name.clone().unwrap())
        } else {
            (utc_std, self.posix.std_name.clone())
        }
    }

    fn compute_start_utc(&self, year: i64) -> i64 {
        let day = self.compute_md_date(year, self.posix.start_m, self.posix.start_w, self.posix.start_d);
        let day_secs = days_from_civil(year, self.posix.start_m as i64, day) * 86400
            + self.posix.start_time as i64;
        day_secs + self.posix.std_offset as i64
    }

    fn compute_end_utc(&self, year: i64) -> i64 {
        let day = self.compute_md_date(year, self.posix.end_m, self.posix.end_w, self.posix.end_d);
        let day_secs = days_from_civil(year, self.posix.end_m as i64, day) * 86400
            + self.posix.end_time as i64;
        day_secs + self.posix.dst_offset.unwrap() as i64
    }

    fn compute_md_date(&self, year: i64, m: i32, w: i32, d: i32) -> i64 {
        let dim = days_in_month(year, m as i64);
        let first_day = days_from_civil(year, m as i64, 1);
        let dow_first = ((first_day + 4) % 7 + 7) % 7; // 0=Sun
        let first_d = 1 + ((d as i64 - dow_first + 7) % 7);

        if w == 5 {
            let mut last_d = first_d + 28;
            if last_d > dim { last_d -= 7; }
            last_d
        } else {
            first_d + 7 * (w as i64 - 1)
        }
    }

    fn local_query(&self, wall_secs: i64) -> Vec<(i64, i32, String)> {
        let mut offsets: Vec<i32> = Vec::new();
        for &(gmtoff, _, _) in &self.types {
            if !offsets.contains(&gmtoff) { offsets.push(gmtoff); }
        }
        let utc_std = self.posix.utc_std();
        if !offsets.contains(&utc_std) { offsets.push(utc_std); }
        if self.posix.has_dst() {
            let utc_dst = self.posix.utc_dst();
            if !offsets.contains(&utc_dst) { offsets.push(utc_dst); }
        }

        let mut solutions = Vec::new();
        for &o in &offsets {
            let t = wall_secs - o as i64;
            let (actual, abbr) = self.offset_at(t);
            if actual == o {
                solutions.push((t, o, abbr));
            }
        }

        solutions.sort_by_key(|&(t, _, _)| t);
        solutions
    }

    fn gap_query(&self, wall_secs: i64) -> (i64, i32, String) {
        let mut all_trans: Vec<(i64, i32, i32)> = Vec::new();

        if !self.transitions.is_empty() {
            let o0 = self.types[0].0;
            all_trans.push((
                self.transitions[0].0,
                o0,
                self.types[self.transitions[0].1 as usize].0,
            ));
            for i in 1..self.transitions.len() {
                let o_old = self.types[self.transitions[i - 1].1 as usize].0;
                let o_new = self.types[self.transitions[i].1 as usize].0;
                all_trans.push((self.transitions[i].0, o_old, o_new));
            }
        }

        // Implicit transition at file/POSIX boundary
        if !self.transitions.is_empty() {
            let last_t = self.transitions[self.transitions.len() - 1].0;
            let o_last = self.types[self.transitions[self.transitions.len() - 1].1 as usize].0;
            let (o_posix, _) = self.posix_at(last_t + 1);
            if o_last != o_posix {
                all_trans.push((last_t + 1, o_last, o_posix));
            }
        }

        // Annual POSIX transitions
        if self.posix.has_dst() {
            let utc_std = self.posix.utc_std();
            let utc_dst = self.posix.utc_dst();
            let last_file_t = if self.transitions.is_empty() {
                i64::MIN
            } else {
                self.transitions[self.transitions.len() - 1].0
            };

            let approx_days = wall_secs.div_euclid(86400);
            let (approx_year, _, _) = civil_from_days(approx_days);

            for year in (approx_year - 1)..=(approx_year + 1) {
                let start_utc = self.compute_start_utc(year);
                let end_utc = self.compute_end_utc(year);

                if start_utc > last_file_t {
                    all_trans.push((start_utc, utc_std, utc_dst));
                }
                if end_utc > last_file_t {
                    all_trans.push((end_utc, utc_dst, utc_std));
                }
            }
        }

        for &(T, o_old, o_new) in &all_trans {
            if o_new > o_old {
                let gap_start = T + o_old as i64;
                let gap_end = T + o_new as i64;
                if wall_secs >= gap_start && wall_secs < gap_end {
                    let t_answer = wall_secs - o_old as i64;
                    let (offset, abbr) = self.offset_at(t_answer);
                    return (t_answer, offset, abbr);
                }
            }
        }

        panic!("No gap transition found");
    }
}

// ===== Binary reading helpers =====

fn read_counts(data: &[u8]) -> [u32; 6] {
    let mut c = [0u32; 6];
    for i in 0..6 {
        c[i] = read_u32_be(&data[i * 4..]);
    }
    c
}

fn read_u32_be(data: &[u8]) -> u32 {
    u32::from_be_bytes([data[0], data[1], data[2], data[3]])
}

fn read_i32_be(data: &[u8]) -> i32 {
    i32::from_be_bytes([data[0], data[1], data[2], data[3]])
}

fn read_i64_be(data: &[u8]) -> i64 {
    i64::from_be_bytes([data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7]])
}

// ===== Main =====

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let queries_content = fs::read_to_string(format!("{}/queries.txt", dir)).unwrap();

    let mut cache: HashMap<String, TzData> = HashMap::new();

    for line in queries_content.lines() {
        if line.trim().is_empty() { continue; }

        let fields: Vec<&str> = line.split(' ').collect();
        let query_type = fields[0];
        let filename = fields[1];

        if !cache.contains_key(filename) {
            let path = format!("{}/{}", dir, filename);
            cache.insert(filename.to_string(), TzData::load(&path));
        }

        let tz = &cache[filename];

        if query_type == "UTC" {
            let t: i64 = fields[2].parse().unwrap();
            let (offset, abbr) = tz.offset_at(t);
            let local_secs = t + offset as i64;
            println!("{} -> {}{} {}", line, fmt_datetime(local_secs), fmt_offset(offset), abbr);
        } else {
            let wall_secs = parse_wall_time(fields[2]);
            let solutions = tz.local_query(wall_secs);

            if solutions.len() == 1 {
                let (t, offset, abbr) = &solutions[0];
                println!("{} -> {} {} {}", line, t, fmt_offset(*offset), abbr);
            } else if solutions.len() >= 2 {
                let (t1, o1, a1) = &solutions[0];
                let (t2, o2, a2) = &solutions[1];
                println!("{} -> {} {} {} | {} {} {}", line, t1, fmt_offset(*o1), a1, t2, fmt_offset(*o2), a2);
            } else {
                let (t, offset, abbr) = tz.gap_query(wall_secs);
                let local_secs = t + offset as i64;
                println!("{} -> GAP {} {}{} {}", line, t, fmt_datetime(local_secs), fmt_offset(offset), abbr);
            }
        }
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;

// ===== Date/time utilities =====

fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: i64, m: i64) -> i64 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => if is_leap(y) { 29 } else { 28 },
        _ => 30,
    }
}

fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as i64;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as i64;
    (y + if m <= 2 { 1 } else { 0 }, m, d)
}

fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = (y - era * 400) as u64;
    let mp = if m > 2 { m - 3 } else { m + 9 } as u64;
    let doy = (153 * mp + 2) / 5 + d as u64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe as i64 - 719468
}

fn fmt_datetime(secs: i64) -> String {
    let days = secs.div_euclid(86400);
    let tod = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    let h = tod / 3600;
    let mi = (tod % 3600) / 60;
    let s = tod % 60;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y, m, d, h, mi, s)
}

fn fmt_offset(offset: i32) -> String {
    let sign = if offset >= 0 { '+' } else { '-' };
    let abs = offset.abs();
    let h = abs / 3600;
    let m = (abs % 3600) / 60;
    let s = abs % 60;
    if s != 0 {
        format!("{}{:02}:{:02}:{:02}", sign, h, m, s)
    } else {
        format!("{}{:02}:{:02}", sign, h, m)
    }
}

fn parse_wall_time(s: &str) -> i64 {
    let year: i64 = s[0..4].parse().unwrap();
    let month: i64 = s[5..7].parse().unwrap();
    let day: i64 = s[8..10].parse().unwrap();
    let hour: i64 = s[11..13].parse().unwrap();
    let min: i64 = s[14..16].parse().unwrap();
    let sec: i64 = s[17..19].parse().unwrap();
    days_from_civil(year, month, day) * 86400 + hour * 3600 + min * 60 + sec
}

// ===== POSIX TZ string parsing =====

struct PosixRule {
    std_name: String,
    std_offset: i32,
    dst_name: Option<String>,
    dst_offset: Option<i32>,
    start_m: i32,
    start_w: i32,
    start_d: i32,
    start_time: i32,
    end_m: i32,
    end_w: i32,
    end_d: i32,
    end_time: i32,
}

impl PosixRule {
    fn utc_std(&self) -> i32 { -self.std_offset }
    fn utc_dst(&self) -> i32 { -self.dst_offset.unwrap() }
    fn has_dst(&self) -> bool { self.dst_name.is_some() }
}

fn parse_posix(s: &str) -> PosixRule {
    let b = s.as_bytes();
    let mut p = 0usize;

    let std_name = parse_name(b, &mut p);
    let std_offset = parse_offset_val(b, &mut p);

    let mut dst_name = None;
    let mut dst_offset = None;

    if p < b.len() && (b[p] == b'<' || b[p].is_ascii_alphabetic()) {
        let n = parse_name(b, &mut p);
        dst_name = Some(n);
        if p < b.len() && (b[p] == b'+' || b[p] == b'-' || b[p].is_ascii_digit()) {
            dst_offset = Some(parse_offset_val(b, &mut p));
        } else {
            dst_offset = Some(std_offset - 3600);
        }
    }

    let mut start_m = 3i32; let mut start_w = 5i32; let mut start_d = 0i32; let mut start_time = 7200i32;
    let mut end_m = 10i32; let mut end_w = 5i32; let mut end_d = 0i32; let mut end_time = 7200i32;

    if p < b.len() && b[p] == b',' {
        p += 1;
        (start_m, start_w, start_d) = parse_md(b, &mut p);
        if p < b.len() && b[p] == b'/' {
            p += 1;
            start_time = parse_offset_val(b, &mut p);
        }
        if p < b.len() && b[p] == b',' {
            p += 1;
            (end_m, end_w, end_d) = parse_md(b, &mut p);
            if p < b.len() && b[p] == b'/' {
                p += 1;
                end_time = parse_offset_val(b, &mut p);
            }
        }
    }

    PosixRule {
        std_name, std_offset, dst_name, dst_offset,
        start_m, start_w, start_d, start_time,
        end_m, end_w, end_d, end_time,
    }
}

fn parse_name(b: &[u8], p: &mut usize) -> String {
    if *p < b.len() && b[*p] == b'<' {
        *p += 1;
        let start = *p;
        while *p < b.len() && b[*p] != b'>' { *p += 1; }
        let s = String::from_utf8(b[start..*p].to_vec()).unwrap();
        *p += 1;
        s
    } else {
        let start = *p;
        while *p < b.len() && b[*p].is_ascii_alphabetic() { *p += 1; }
        String::from_utf8(b[start..*p].to_vec()).unwrap()
    }
}

fn parse_offset_val(b: &[u8], p: &mut usize) -> i32 {
    let mut sign = 1i32;
    if *p < b.len() && b[*p] == b'-' {
        sign = -1; *p += 1;
    } else if *p < b.len() && b[*p] == b'+' {
        *p += 1;
    }
    let mut h = 0i32;
    while *p < b.len() && b[*p].is_ascii_digit() {
        h = h * 10 + (b[*p] - b'0') as i32; *p += 1;
    }
    let mut m = 0i32;
    let mut s = 0i32;
    if *p < b.len() && b[*p] == b':' {
        *p += 1;
        while *p < b.len() && b[*p].is_ascii_digit() {
            m = m * 10 + (b[*p] - b'0') as i32; *p += 1;
        }
        if *p < b.len() && b[*p] == b':' {
            *p += 1;
            while *p < b.len() && b[*p].is_ascii_digit() {
                s = s * 10 + (b[*p] - b'0') as i32; *p += 1;
            }
        }
    }
    sign * (h * 3600 + m * 60 + s)
}

fn parse_md(b: &[u8], p: &mut usize) -> (i32, i32, i32) {
    assert_eq!(b[*p], b'M'); *p += 1;
    let m = parse_num(b, p);
    assert_eq!(b[*p], b'.'); *p += 1;
    let w = parse_num(b, p);
    assert_eq!(b[*p], b'.'); *p += 1;
    let d = parse_num(b, p);
    (m, w, d)
}

fn parse_num(b: &[u8], p: &mut usize) -> i32 {
    let mut n = 0i32;
    while *p < b.len() && b[*p].is_ascii_digit() {
        n = n * 10 + (b[*p] - b'0') as i32; *p += 1;
    }
    n
}

// ===== TZif data =====

struct TzData {
    transitions: Vec<(i64, u8)>,
    types: Vec<(i32, u8, u8)>,
    abbrs: Vec<u8>,
    posix: PosixRule,
}

impl TzData {
    fn load(path: &str) -> Self {
        let data = fs::read(path).unwrap();

        // First header (44 bytes: magic(4) + version(1) + unused(15) + counts(24))
        assert_eq!(&data[0..4], b"TZif");
        let c1: [u32; 6] = read_counts(&data[20..]);

        // Skip first data block
        let mut pos = 44usize;
        let block1_size = c1[3] as usize * 4 + c1[3] as usize
            + c1[4] as usize * 6 + c1[5] as usize
            + c1[2] as usize * 8 + c1[1] as usize + c1[0] as usize;
        pos += block1_size;

        // Second header (44 bytes)
        assert_eq!(&data[pos..pos + 4], b"TZif");
        let c2: [u32; 6] = read_counts(&data[pos + 20..]);
        pos += 44;

        let timecnt = c2[3] as usize;
        let typecnt = c2[4] as usize;
        let charcnt = c2[5] as usize;
        let leapcnt = c2[2] as usize;
        let isstdcnt = c2[1] as usize;
        let isutcnt = c2[0] as usize;

        // 64-bit transition times
        let mut times = Vec::with_capacity(timecnt);
        for _ in 0..timecnt {
            times.push(read_i64_be(&data[pos..]));
            pos += 8;
        }

        // Type indices
        let mut tidx = Vec::with_capacity(timecnt);
        for _ in 0..timecnt {
            tidx.push(data[pos]);
            pos += 1;
        }

        let transitions: Vec<(i64, u8)> = times.into_iter().zip(tidx).collect();

        // Type records
        let mut types = Vec::with_capacity(typecnt);
        for _ in 0..typecnt {
            let gmtoff = read_i32_be(&data[pos..]); pos += 4;
            let isdst = data[pos]; pos += 1;
            let abbridx = data[pos]; pos += 1;
            types.push((gmtoff, isdst, abbridx));
        }

        // Abbreviations
        let abbrs = data[pos..pos + charcnt].to_vec();
        pos += charcnt;

        // Skip leap seconds, isstd, isut
        pos += leapcnt * 12 + isstdcnt + isutcnt;

        // Footer
        assert_eq!(data[pos], b'\n');
        pos += 1;
        let fs_start = pos;
        let fe = data[pos..].iter().position(|&b| b == b'\n').unwrap() + pos;
        let posix_str = String::from_utf8(data[fs_start..fe].to_vec()).unwrap();

        let posix = parse_posix(&posix_str);

        TzData { transitions, types, abbrs, posix }
    }

    fn get_abbr(&self, idx: u8) -> String {
        let start = idx as usize;
        let end = self.abbrs[start..].iter().position(|&b| b == 0)
            .unwrap_or(self.abbrs.len() - start) + start;
        String::from_utf8_lossy(&self.abbrs[start..end]).to_string()
    }

    fn offset_at(&self, t: i64) -> (i32, String) {
        if self.transitions.is_empty() {
            return self.posix_at(t);
        }

        let last_t = self.transitions[self.transitions.len() - 1].0;

        if t < self.transitions[0].0 {
            let (gmtoff, _, abbridx) = self.types[0];
            return (gmtoff, self.get_abbr(abbridx));
        }

        if t > last_t {
            return self.posix_at(t);
        }

        // Binary search for latest transition <= t
        let mut lo = 0usize;
        let mut hi = self.transitions.len() - 1;
        while lo < hi {
            let mid = (lo + hi + 1) / 2;
            if self.transitions[mid].0 <= t {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        let ti = self.transitions[lo].1 as usize;
        let (gmtoff, _, abbridx) = self.types[ti];
        (gmtoff, self.get_abbr(abbridx))
    }

    fn posix_at(&self, t: i64) -> (i32, String) {
        if !self.posix.has_dst() {
            return (self.posix.utc_std(), self.posix.std_name.clone());
        }

        let utc_std = self.posix.utc_std();
        let utc_dst = self.posix.utc_dst();

        let local_std_secs = t + utc_std as i64;
        let days = local_std_secs.div_euclid(86400);
        let (year, _, _) = civil_from_days(days);

        let start_utc = self.compute_start_utc(year);
        let end_utc = self.compute_end_utc(year);

        let in_dst = if start_utc <= end_utc {
            t >= start_utc && t < end_utc
        } else {
            t >= start_utc || t < end_utc
        };

        if in_dst {
            (utc_dst, self.posix.dst_name.clone().unwrap())
        } else {
            (utc_std, self.posix.std_name.clone())
        }
    }

    fn compute_start_utc(&self, year: i64) -> i64 {
        let day = self.compute_md_date(year, self.posix.start_m, self.posix.start_w, self.posix.start_d);
        let day_secs = days_from_civil(year, self.posix.start_m as i64, day) * 86400
            + self.posix.start_time as i64;
        day_secs + self.posix.std_offset as i64
    }

    fn compute_end_utc(&self, year: i64) -> i64 {
        let day = self.compute_md_date(year, self.posix.end_m, self.posix.end_w, self.posix.end_d);
        let day_secs = days_from_civil(year, self.posix.end_m as i64, day) * 86400
            + self.posix.end_time as i64;
        day_secs + self.posix.dst_offset.unwrap() as i64
    }

    fn compute_md_date(&self, year: i64, m: i32, w: i32, d: i32) -> i64 {
        let dim = days_in_month(year, m as i64);
        let first_day = days_from_civil(year, m as i64, 1);
        let dow_first = ((first_day + 4) % 7 + 7) % 7; // 0=Sun
        let first_d = 1 + ((d as i64 - dow_first + 7) % 7);

        if w == 5 {
            let mut last_d = first_d + 28;
            if last_d > dim { last_d -= 7; }
            last_d
        } else {
            first_d + 7 * (w as i64 - 1)
        }
    }

    fn local_query(&self, wall_secs: i64) -> Vec<(i64, i32, String)> {
        let mut offsets: Vec<i32> = Vec::new();
        for &(gmtoff, _, _) in &self.types {
            if !offsets.contains(&gmtoff) { offsets.push(gmtoff); }
        }
        let utc_std = self.posix.utc_std();
        if !offsets.contains(&utc_std) { offsets.push(utc_std); }
        if self.posix.has_dst() {
            let utc_dst = self.posix.utc_dst();
            if !offsets.contains(&utc_dst) { offsets.push(utc_dst); }
        }

        let mut solutions = Vec::new();
        for &o in &offsets {
            let t = wall_secs - o as i64;
            let (actual, abbr) = self.offset_at(t);
            if actual == o {
                solutions.push((t, o, abbr));
            }
        }

        solutions.sort_by_key(|&(t, _, _)| t);
        solutions
    }

    fn gap_query(&self, wall_secs: i64) -> (i64, i32, String) {
        let mut all_trans: Vec<(i64, i32, i32)> = Vec::new();

        if !self.transitions.is_empty() {
            let o0 = self.types[0].0;
            all_trans.push((
                self.transitions[0].0,
                o0,
                self.types[self.transitions[0].1 as usize].0,
            ));
            for i in 1..self.transitions.len() {
                let o_old = self.types[self.transitions[i - 1].1 as usize].0;
                let o_new = self.types[self.transitions[i].1 as usize].0;
                all_trans.push((self.transitions[i].0, o_old, o_new));
            }
        }

        // Implicit transition at file/POSIX boundary
        if !self.transitions.is_empty() {
            let last_t = self.transitions[self.transitions.len() - 1].0;
            let o_last = self.types[self.transitions[self.transitions.len() - 1].1 as usize].0;
            let (o_posix, _) = self.posix_at(last_t + 1);
            if o_last != o_posix {
                all_trans.push((last_t + 1, o_last, o_posix));
            }
        }

        // Annual POSIX transitions
        if self.posix.has_dst() {
            let utc_std = self.posix.utc_std();
            let utc_dst = self.posix.utc_dst();
            let last_file_t = if self.transitions.is_empty() {
                i64::MIN
            } else {
                self.transitions[self.transitions.len() - 1].0
            };

            let approx_days = wall_secs.div_euclid(86400);
            let (approx_year, _, _) = civil_from_days(approx_days);

            for year in (approx_year - 1)..=(approx_year + 1) {
                let start_utc = self.compute_start_utc(year);
                let end_utc = self.compute_end_utc(year);

                if start_utc > last_file_t {
                    all_trans.push((start_utc, utc_std, utc_dst));
                }
                if end_utc > last_file_t {
                    all_trans.push((end_utc, utc_dst, utc_std));
                }
            }
        }

        for &(T, o_old, o_new) in &all_trans {
            if o_new > o_old {
                let gap_start = T + o_old as i64;
                let gap_end = T + o_new as i64;
                if wall_secs >= gap_start && wall_secs < gap_end {
                    let t_answer = wall_secs - o_old as i64;
                    let (offset, abbr) = self.offset_at(t_answer);
                    return (t_answer, offset, abbr);
                }
            }
        }

        // Fallback: should not reach here for valid inputs
        panic!("No gap transition found");
    }
}

// ===== Binary reading helpers =====

fn read_counts(data: &[u8]) -> [u32; 6] {
    let mut c = [0u32; 6];
    for i in 0..6 {
        c[i] = read_u32_be(&data[i * 4..]);
    }
    c
}

fn read_u32_be(data: &[u8]) -> u32 {
    u32::from_be_bytes([data[0], data[1], data[2], data[3]])
}

fn read_i32_be(data: &[u8]) -> i32 {
    i32::from_be_bytes([data[0], data[1], data[2], data[3]])
}

fn read_i64_be(data: &[u8]) -> i64 {
    i64::from_be_bytes([data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7]])
}

// ===== Main =====

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let queries_content = fs::read_to_string(format!("{}/queries.txt", dir)).unwrap();

    let mut cache: HashMap<String, TzData> = HashMap::new();

    for line in queries_content.lines() {
        if line.trim().is_empty() { continue; }

        let fields: Vec<&str> = line.split(' ').collect();
        let query_type = fields[0];
        let filename = fields[1];

        if !cache.contains_key(filename) {
            let path = format!("{}/{}", dir, filename);
            cache.insert(filename.to_string(), TzData::load(&path));
        }

        let tz = &cache[filename];

        if query_type == "UTC" {
            let t: i64 = fields[2].parse().unwrap();
            let (offset, abbr) = tz.offset_at(t);
            let local_secs = t + offset as i64;
            println!("{} -> {}{} {}", line, fmt_datetime(local_secs), fmt_offset(offset), abbr);
        } else {
            let wall_secs = parse_wall_time(fields[2]);
            let solutions = tz.local_query(wall_secs);

            if solutions.len() == 1 {
                let (t, offset, abbr) = &solutions[0];
                println!("{} -> {} {} {}", line, t, fmt_offset(*offset), abbr);
            } else if solutions.len() >= 2 {
                let (t1, o1, a1) = &solutions[0];
                let (t2, o2, a2) = &solutions[1];
                println!("{} -> {} {} {} | {} {} {}", line, t1, fmt_offset(*o1), a1, t2, fmt_offset(*o2), a2);
            } else {
                let (t, offset, abbr) = tz.gap_query(wall_secs);
                let local_secs = t + offset as i64;
                println!("{} -> GAP {} {}{} {}", line, t, fmt_datetime(local_secs), fmt_offset(offset), abbr);
            }
        }
    }
}

import * as fs from 'fs';
import * as path from 'path';

// --- Date/time utilities ---

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  const dm = [31,28,31,30,31,30,31,31,30,31,30,31];
  if (m === 2 && isLeap(y)) return 29;
  return dm[m - 1];
}

function daysFromCivil(y: number, m: number, d: number): number {
  y = y - (m <= 2 ? 1 : 0);
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const mp = m + (m > 2 ? -3 : 9);
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

function civilFromDays(z: number): { y: number; m: number; d: number } {
  z += 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp + (mp < 10 ? 3 : -9);
  return { y: y + (m <= 2 ? 1 : 0), m, d };
}

function unixToComponents(t: number): { y: number; m: number; d: number; h: number; mi: number; s: number } {
  let days = Math.floor(t / 86400);
  let rem = t - days * 86400;
  const { y, m, d } = civilFromDays(days);
  const h = Math.floor(rem / 3600);
  const mi = Math.floor((rem % 3600) / 60);
  const s = rem % 60;
  return { y, m, d, h, mi, s };
}

function componentsToUnix(y: number, m: number, d: number, h: number, mi: number, s: number): number {
  return daysFromCivil(y, m, d) * 86400 + h * 3600 + mi * 60 + s;
}

function pad2(n: number): string {
  return n.toString().padStart(2, '0');
}

function formatLocal(y: number, m: number, d: number, h: number, mi: number, s: number): string {
  return `${y}-${pad2(m)}-${pad2(d)}T${pad2(h)}:${pad2(mi)}:${pad2(s)}`;
}

function formatOffset(offset: number): string {
  const sign = offset >= 0 ? '+' : '-';
  const abs = Math.abs(offset);
  const h = Math.floor(abs / 3600);
  const m = Math.floor((abs % 3600) / 60);
  const s = abs % 60;
  let result = `${sign}${pad2(h)}:${pad2(m)}`;
  if (s !== 0) result += `:${pad2(s)}`;
  return result;
}

function dayOfWeek(y: number, m: number, d: number): number {
  const t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
  if (m < 3) y = y - 1;
  return ((y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400) + t[m - 1] + d) % 7 + 7) % 7;
}

// --- TZif parsing ---

interface TypeRecord {
  gmtoff: number;
  isdst: number;
  abbrIndex: number;
}

interface TZifData {
  transitions: number[];
  typeIndices: number[];
  types: TypeRecord[];
  abbreviations: string[];
  footer: string;
}

function parseTZif(filePath: string): TZifData {
  const buf = fs.readFileSync(filePath);
  let pos = 0;

  // First header (44 bytes)
  pos += 4; // magic
  pos += 1; // version
  pos += 15; // unused
  const isutcnt1 = buf.readInt32BE(pos); pos += 4;
  const isstdcnt1 = buf.readInt32BE(pos); pos += 4;
  const leapcnt1 = buf.readInt32BE(pos); pos += 4;
  const timecnt1 = buf.readInt32BE(pos); pos += 4;
  const typecnt1 = buf.readInt32BE(pos); pos += 4;
  const charcnt1 = buf.readInt32BE(pos); pos += 4;

  // First data block
  pos += timecnt1 * 4;
  pos += timecnt1 * 1;
  pos += typecnt1 * 6;
  pos += charcnt1;
  pos += leapcnt1 * 8;
  pos += isstdcnt1;
  pos += isutcnt1;

  // Second header (44 bytes)
  pos += 4; // magic
  pos += 1; // version
  pos += 15; // unused
  const isutcnt2 = buf.readInt32BE(pos); pos += 4;
  const isstdcnt2 = buf.readInt32BE(pos); pos += 4;
  const leapcnt2 = buf.readInt32BE(pos); pos += 4;
  const timecnt2 = buf.readInt32BE(pos); pos += 4;
  const typecnt2 = buf.readInt32BE(pos); pos += 4;
  const charcnt2 = buf.readInt32BE(pos); pos += 4;

  // Second data block (64-bit)
  const transitions: number[] = [];
  for (let i = 0; i < timecnt2; i++) {
    transitions.push(Number(buf.readBigInt64BE(pos))); pos += 8;
  }

  const typeIndices: number[] = [];
  for (let i = 0; i < timecnt2; i++) {
    typeIndices.push(buf[pos]); pos += 1;
  }

  const types: TypeRecord[] = [];
  for (let i = 0; i < typecnt2; i++) {
    const gmtoff = buf.readInt32BE(pos); pos += 4;
    const isdst = buf[pos]; pos += 1;
    const abbrIndex = buf[pos]; pos += 1;
    types.push({ gmtoff, isdst, abbrIndex });
  }

  // Abbreviations
  const abbrBuf = buf.slice(pos, pos + charcnt2); pos += charcnt2;
  const abbreviations: string[] = [];
  let abbrStart = 0;
  for (let i = 0; i < charcnt2; i++) {
    if (abbrBuf[i] === 0) {
      abbreviations.push(abbrBuf.toString('ascii', abbrStart, i));
      abbrStart = i + 1;
    }
  }

  // Leap seconds
  pos += leapcnt2 * 12;
  pos += isstdcnt2;
  pos += isutcnt2;

  // Footer
  pos += 1; // leading \n
  const footerEnd = buf.indexOf(0x0A, pos);
  const footer = footerEnd >= 0 ? buf.toString('ascii', pos, footerEnd) : '';

  return { transitions, typeIndices, types, abbreviations, footer };
}

// --- POSIX TZ string parsing ---

interface PosixRule {
  month: number;
  week: number;
  day: number;
  time: number;
}

interface PosixTZ {
  stdName: string;
  stdOffset: number;
  dstName: string;
  dstOffset: number;
  start: PosixRule;
  end: PosixRule;
  hasDst: boolean;
  hasRules: boolean;
}

function parsePosixTZ(s: string): PosixTZ {
  let pos = 0;

  function readName(): string {
    if (pos < s.length && s[pos] === '<') {
      pos++;
      let name = '';
      while (pos < s.length && s[pos] !== '>') { name += s[pos]; pos++; }
      pos++;
      return name;
    } else {
      let name = '';
      while (pos < s.length && /[A-Za-z]/.test(s[pos])) { name += s[pos]; pos++; }
      return name;
    }
  }

  function readOffsetVal(): number {
    let sign = 1;
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-')) {
      if (s[pos] === '-') sign = -1;
      pos++;
    }
    let h = 0, m = 0, sec = 0;
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    h = parseInt(numStr) || 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStr = '';
      while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
      m = parseInt(numStr) || 0;
      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStr = '';
        while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
        sec = parseInt(numStr) || 0;
      }
    }
    return sign * (h * 3600 + m * 60 + sec);
  }

  function readTime(): number {
    let sign = 1;
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-')) {
      if (s[pos] === '-') sign = -1;
      pos++;
    }
    let h = 0, m = 0, sec = 0;
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    h = parseInt(numStr) || 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStr = '';
      while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
      m = parseInt(numStr) || 0;
      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStr = '';
        while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
        sec = parseInt(numStr) || 0;
      }
    }
    return sign * (h * 3600 + m * 60 + sec);
  }

  function readRule(): PosixRule {
    pos++; // skip 'M'
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const month = parseInt(numStr);
    pos++; // skip '.'
    numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const week = parseInt(numStr);
    pos++; // skip '.'
    numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const day = parseInt(numStr);
    let time = 2 * 3600;
    if (pos < s.length && s[pos] === '/') {
      pos++;
      time = readTime();
    }
    return { month, week, day, time };
  }

  const stdName = readName();
  const stdOffsetVal = readOffsetVal();
  const stdOffset = -stdOffsetVal;

  let hasDst = false;
  let dstName = '';
  let dstOffset = stdOffset;
  let start: PosixRule = { month: 0, week: 0, day: 0, time: 0 };
  let end: PosixRule = { month: 0, week: 0, day: 0, time: 0 };
  let hasRules = true;

  if (pos < s.length && (/[A-Za-z<]/.test(s[pos]))) {
    hasDst = true;
    dstName = readName();
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-' || /\d/.test(s[pos]))) {
      const dstOffsetVal = readOffsetVal();
      dstOffset = -dstOffsetVal;
    } else {
      dstOffset = stdOffset + 3600;
    }
    if (pos < s.length && s[pos] === ',') {
      pos++;
      start = readRule();
      pos++;
      end = readRule();
    } else {
      hasRules = false;
    }
  }

  return { stdName, stdOffset, dstName, dstOffset, start, end, hasDst, hasRules };
}

// --- Core logic ---

function computeDayOfMonth(y: number, rule: PosixRule): number {
  const { month, week, day } = rule;
  const dim = daysInMonth(y, month);
  const dowFirst = dayOfWeek(y, month, 1);
  let firstDay: number;
  if (dowFirst <= day) {
    firstDay = 1 + (day - dowFirst);
  } else {
    firstDay = 1 + (7 - dowFirst + day);
  }
  let d = firstDay + (week - 1) * 7;
  if (d > dim) d -= 7;
  return d;
}

function computeTransitionUtc(y: number, rule: PosixRule, utcOffset: number): number {
  const d = computeDayOfMonth(y, rule);
  const localUnix = componentsToUnix(y, rule.month, d, 0, 0, 0) + rule.time;
  return localUnix - utcOffset;
}

function isDstAt(t: number, posix: PosixTZ): boolean {
  if (!posix.hasDst) return false;
  if (!posix.hasRules) return true;

  const comp = unixToComponents(t);
  const year = comp.y;

  const trans: { time: number; toDst: boolean }[] = [];
  for (let y = year - 1; y <= year + 1; y++) {
    trans.push({ time: computeTransitionUtc(y, posix.start, posix.stdOffset), toDst: true });
    trans.push({ time: computeTransitionUtc(y, posix.end, posix.dstOffset), toDst: false });
  }
  trans.sort((a, b) => a.time - b.time);

  let isdst = false;
  for (const tr of trans) {
    if (tr.time <= t) {
      isdst = tr.toDst;
    } else {
      break;
    }
  }
  return isdst;
}

function getOffsetAtTime(tzif: TZifData, posix: PosixTZ | null, t: number): { offset: number; abbr: string; isdst: boolean } {
  const { transitions, typeIndices, types, abbreviations } = tzif;

  if (transitions.length === 0) {
    if (posix) {
      if (isDstAt(t, posix)) {
        return { offset: posix.dstOffset, abbr: posix.dstName, isdst: true };
      } else {
        return { offset: posix.stdOffset, abbr: posix.stdName, isdst: false };
      }
    }
    const type = types[0];
    return { offset: type.gmtoff, abbr: abbreviations[type.abbrIndex], isdst: type.isdst === 1 };
  }

  if (t < transitions[0]) {
    const type = types[0];
    return { offset: type.gmtoff, abbr: abbreviations[type.abbrIndex], isdst: type.isdst === 1 };
  }

  if (t > transitions[transitions.length - 1]) {
    if (posix) {
      if (isDstAt(t, posix)) {
        return { offset: posix.dstOffset, abbr: posix.dstName, isdst: true };
      } else {
        return { offset: posix.stdOffset, abbr: posix.stdName, isdst: false };
      }
    }
    const type = types[typeIndices[transitions.length - 1]];
    return { offset: type.gmtoff, abbr: abbreviations[type.abbrIndex], isdst: type.isdst === 1 };
  }

  // Binary search: find latest transition <= t
  let lo = 0, hi = transitions.length - 1;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (transitions[mid] <= t) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }
  const type = types[typeIndices[lo]];
  return { offset: type.gmtoff, abbr: abbreviations[type.abbrIndex], isdst: type.isdst === 1 };
}

// --- Main ---

const dir = process.argv[2];
const queryFile = path.join(dir, 'queries.txt');
const content = fs.readFileSync(queryFile, 'utf8');
const lines = content.split('\n');

const tzifCache: Map<string, { tzif: TZifData; posix: PosixTZ | null }> = new Map();

function getTZif(fileName: string): { tzif: TZifData; posix: PosixTZ | null } {
  if (tzifCache.has(fileName)) return tzifCache.get(fileName)!;
  const filePath = path.join(dir, fileName);
  const tzif = parseTZif(filePath);
  let posix: PosixTZ | null = null;
  if (tzif.footer.length > 0) {
    posix = parsePosixTZ(tzif.footer);
  }
  const result = { tzif, posix };
  tzifCache.set(fileName, result);
  return result;
}

const output: string[] = [];

for (const line of lines) {
  if (!line.trim()) continue;
  const parts = line.split(' ');

  if (parts[0] === 'UTC') {
    const fileName = parts[1];
    const t = parseInt(parts[2]);
    const { tzif, posix } = getTZif(fileName);
    const { offset, abbr } = getOffsetAtTime(tzif, posix, t);
    const localUnix = t + offset;
    const comp = unixToComponents(localUnix);
    const localStr = formatLocal(comp.y, comp.m, comp.d, comp.h, comp.mi, comp.s);
    const offsetStr = formatOffset(offset);
    output.push(`${line} -> ${localStr}${offsetStr} ${abbr}`);

  } else if (parts[0] === 'LOCAL') {
    const fileName = parts[1];
    const wallStr = parts[2];
    const { tzif, posix } = getTZif(fileName);

    const [datePart, timePart] = wallStr.split('T');
    const [wy, wm, wd] = datePart.split('-').map(Number);
    const [wh, wmi, ws] = timePart.split(':').map(Number);
    const wallAsNumber = componentsToUnix(wy, wm, wd, wh, wmi, ws);

    // Collect all possible UTC offsets
    const offsets = new Set<number>();
    for (const type of tzif.types) {
      offsets.add(type.gmtoff);
    }
    if (posix) {
      offsets.add(posix.stdOffset);
      if (posix.hasDst) offsets.add(posix.dstOffset);
    }

    // Compute candidates
    const validCandidates: { t: number; offset: number; abbr: string }[] = [];
    for (const off of offsets) {
      const t = wallAsNumber - off;
      const { offset: actualOffset, abbr } = getOffsetAtTime(tzif, posix, t);
      if (actualOffset === off) {
        const localUnix = t + actualOffset;
        if (localUnix === wallAsNumber) {
          validCandidates.push({ t, offset: off, abbr });
        }
      }
    }

    validCandidates.sort((a, b) => a.t - b.t);

    if (validCandidates.length === 1) {
      const c = validCandidates[0];
      const offsetStr = formatOffset(c.offset);
      output.push(`${line} -> ${c.t} ${offsetStr} ${c.abbr}`);
    } else if (validCandidates.length === 2) {
      const c1 = validCandidates[0];
      const c2 = validCandidates[1];
      const offsetStr1 = formatOffset(c1.offset);
      const offsetStr2 = formatOffset(c2.offset);
      output.push(`${line} -> ${c1.t} ${offsetStr1} ${c1.abbr} | ${c2.t} ${offsetStr2} ${c2.abbr}`);
    } else {
      // Gap: find the transition that caused it
      const allTransitions: { time: number; oldOffset: number; newOffset: number }[] = [];

      // Data block transitions
      for (let i = 0; i < tzif.transitions.length; i++) {
        const tr = tzif.transitions[i];
        const newType = tzif.types[tzif.typeIndices[i]];
        const oldType = i > 0 ? tzif.types[tzif.typeIndices[i - 1]] : tzif.types[0];
        allTransitions.push({ time: tr, oldOffset: oldType.gmtoff, newOffset: newType.gmtoff });
      }

      // Footer transitions
      if (posix && posix.hasDst && posix.hasRules) {
        const comp = unixToComponents(wallAsNumber);
        for (let y = comp.y - 2; y <= comp.y + 2; y++) {
          const startT = computeTransitionUtc(y, posix.start, posix.stdOffset);
          const endT = computeTransitionUtc(y, posix.end, posix.dstOffset);
          allTransitions.push({ time: startT, oldOffset: posix.stdOffset, newOffset: posix.dstOffset });
          allTransitions.push({ time: endT, oldOffset: posix.dstOffset, newOffset: posix.stdOffset });
        }
      }

      let gapTransition: { time: number; oldOffset: number; newOffset: number } | null = null;
      for (const tr of allTransitions) {
        if (tr.newOffset > tr.oldOffset) {
          if (wallAsNumber >= tr.time + tr.oldOffset && wallAsNumber < tr.time + tr.newOffset) {
            gapTransition = tr;
            break;
          }
        }
      }

      if (gapTransition) {
        const t = wallAsNumber - gapTransition.oldOffset;
        const { offset, abbr } = getOffsetAtTime(tzif, posix, t);
        const localUnix = t + offset;
        const comp = unixToComponents(localUnix);
        const localStr = formatLocal(comp.y, comp.m, comp.d, comp.h, comp.mi, comp.s);
        const offsetStr = formatOffset(offset);
        output.push(`${line} -> GAP ${t} ${localStr}${offsetStr} ${abbr}`);
      }
    }
  }
}

console.log(output.join('\n'));

import * as fs from 'fs';
import * as path from 'path';

// --- Date/time utilities ---

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  const dm = [31,28,31,30,31,30,31,31,30,31,30,31];
  if (m === 2 && isLeap(y)) return 29;
  return dm[m - 1];
}

function daysFromCivil(y: number, m: number, d: number): number {
  y = y - (m <= 2 ? 1 : 0);
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const mp = m + (m > 2 ? -3 : 9);
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

function civilFromDays(z: number): { y: number; m: number; d: number } {
  z += 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp + (mp < 10 ? 3 : -9);
  return { y: y + (m <= 2 ? 1 : 0), m, d };
}

function unixToComponents(t: number): { y: number; m: number; d: number; h: number; mi: number; s: number } {
  let days = Math.floor(t / 86400);
  let rem = t - days * 86400;
  const { y, m, d } = civilFromDays(days);
  const h = Math.floor(rem / 3600);
  const mi = Math.floor((rem % 3600) / 60);
  const s = rem % 60;
  return { y, m, d, h, mi, s };
}

function componentsToUnix(y: number, m: number, d: number, h: number, mi: number, s: number): number {
  return daysFromCivil(y, m, d) * 86400 + h * 3600 + mi * 60 + s;
}

function pad2(n: number): string {
  return n.toString().padStart(2, '0');
}

function formatLocal(y: number, m: number, d: number, h: number, mi: number, s: number): string {
  return `${y}-${pad2(m)}-${pad2(d)}T${pad2(h)}:${pad2(mi)}:${pad2(s)}`;
}

function formatOffset(offset: number): string {
  const sign = offset >= 0 ? '+' : '-';
  const abs = Math.abs(offset);
  const h = Math.floor(abs / 3600);
  const m = Math.floor((abs % 3600) / 60);
  const s = abs % 60;
  let result = `${sign}${pad2(h)}:${pad2(m)}`;
  if (s !== 0) result += `:${pad2(s)}`;
  return result;
}

function dayOfWeek(y: number, m: number, d: number): number {
  const t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
  if (m < 3) y = y - 1;
  return ((y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400) + t[m - 1] + d) % 7 + 7) % 7;
}

// --- TZif parsing ---

interface TypeRecord {
  gmtoff: number;
  isdst: number;
  abbrIndex: number;
}

interface TZifData {
  transitions: number[];
  typeIndices: number[];
  types: TypeRecord[];
  abbrBuf: Buffer;
  footer: string;
}

function getAbbr(abbrBuf: Buffer, abbrIndex: number): string {
  let end = abbrIndex;
  while (end < abbrBuf.length && abbrBuf[end] !== 0) end++;
  return abbrBuf.toString('ascii', abbrIndex, end);
}

function parseTZif(filePath: string): TZifData {
  const buf = fs.readFileSync(filePath);
  let pos = 0;

  // First header (44 bytes)
  pos += 4; // magic
  pos += 1; // version
  pos += 15; // unused
  const isutcnt1 = buf.readInt32BE(pos); pos += 4;
  const isstdcnt1 = buf.readInt32BE(pos); pos += 4;
  const leapcnt1 = buf.readInt32BE(pos); pos += 4;
  const timecnt1 = buf.readInt32BE(pos); pos += 4;
  const typecnt1 = buf.readInt32BE(pos); pos += 4;
  const charcnt1 = buf.readInt32BE(pos); pos += 4;

  // First data block
  pos += timecnt1 * 4;
  pos += timecnt1 * 1;
  pos += typecnt1 * 6;
  pos += charcnt1;
  pos += leapcnt1 * 8;
  pos += isstdcnt1;
  pos += isutcnt1;

  // Second header (44 bytes)
  pos += 4; // magic
  pos += 1; // version
  pos += 15; // unused
  const isutcnt2 = buf.readInt32BE(pos); pos += 4;
  const isstdcnt2 = buf.readInt32BE(pos); pos += 4;
  const leapcnt2 = buf.readInt32BE(pos); pos += 4;
  const timecnt2 = buf.readInt32BE(pos); pos += 4;
  const typecnt2 = buf.readInt32BE(pos); pos += 4;
  const charcnt2 = buf.readInt32BE(pos); pos += 4;

  // Second data block (64-bit)
  const transitions: number[] = [];
  for (let i = 0; i < timecnt2; i++) {
    transitions.push(Number(buf.readBigInt64BE(pos))); pos += 8;
  }

  const typeIndices: number[] = [];
  for (let i = 0; i < timecnt2; i++) {
    typeIndices.push(buf[pos]); pos += 1;
  }

  const types: TypeRecord[] = [];
  for (let i = 0; i < typecnt2; i++) {
    const gmtoff = buf.readInt32BE(pos); pos += 4;
    const isdst = buf[pos]; pos += 1;
    const abbrIndex = buf[pos]; pos += 1;
    types.push({ gmtoff, isdst, abbrIndex });
  }

  // Abbreviation buffer (raw)
  const abbrBuf = buf.slice(pos, pos + charcnt2); pos += charcnt2;

  // Leap seconds
  pos += leapcnt2 * 12;
  pos += isstdcnt2;
  pos += isutcnt2;

  // Footer
  pos += 1; // leading \n
  const footerEnd = buf.indexOf(0x0A, pos);
  const footer = footerEnd >= 0 ? buf.toString('ascii', pos, footerEnd) : '';

  return { transitions, typeIndices, types, abbrBuf, footer };
}

// --- POSIX TZ string parsing ---

interface PosixRule {
  month: number;
  week: number;
  day: number;
  time: number;
}

interface PosixTZ {
  stdName: string;
  stdOffset: number;
  dstName: string;
  dstOffset: number;
  start: PosixRule;
  end: PosixRule;
  hasDst: boolean;
  hasRules: boolean;
}

function parsePosixTZ(s: string): PosixTZ {
  let pos = 0;

  function readName(): string {
    if (pos < s.length && s[pos] === '<') {
      pos++;
      let name = '';
      while (pos < s.length && s[pos] !== '>') { name += s[pos]; pos++; }
      pos++;
      return name;
    } else {
      let name = '';
      while (pos < s.length && /[A-Za-z]/.test(s[pos])) { name += s[pos]; pos++; }
      return name;
    }
  }

  function readOffsetVal(): number {
    let sign = 1;
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-')) {
      if (s[pos] === '-') sign = -1;
      pos++;
    }
    let h = 0, m = 0, sec = 0;
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    h = parseInt(numStr) || 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStr = '';
      while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
      m = parseInt(numStr) || 0;
      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStr = '';
        while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
        sec = parseInt(numStr) || 0;
      }
    }
    return sign * (h * 3600 + m * 60 + sec);
  }

  function readTime(): number {
    let sign = 1;
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-')) {
      if (s[pos] === '-') sign = -1;
      pos++;
    }
    let h = 0, m = 0, sec = 0;
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    h = parseInt(numStr) || 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStr = '';
      while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
      m = parseInt(numStr) || 0;
      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStr = '';
        while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
        sec = parseInt(numStr) || 0;
      }
    }
    return sign * (h * 3600 + m * 60 + sec);
  }

  function readRule(): PosixRule {
    pos++; // skip 'M'
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const month = parseInt(numStr);
    pos++; // skip '.'
    numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const week = parseInt(numStr);
    pos++; // skip '.'
    numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const day = parseInt(numStr);
    let time = 2 * 3600;
    if (pos < s.length && s[pos] === '/') {
      pos++;
      time = readTime();
    }
    return { month, week, day, time };
  }

  const stdName = readName();
  const stdOffsetVal = readOffsetVal();
  const stdOffset = -stdOffsetVal;

  let hasDst = false;
  let dstName = '';
  let dstOffset = stdOffset;
  let start: PosixRule = { month: 0, week: 0, day: 0, time: 0 };
  let end: PosixRule = { month: 0, week: 0, day: 0, time: 0 };
  let hasRules = true;

  if (pos < s.length && (/[A-Za-z<]/.test(s[pos]))) {
    hasDst = true;
    dstName = readName();
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-' || /\d/.test(s[pos]))) {
      const dstOffsetVal = readOffsetVal();
      dstOffset = -dstOffsetVal;
    } else {
      dstOffset = stdOffset + 3600;
    }
    if (pos < s.length && s[pos] === ',') {
      pos++;
      start = readRule();
      pos++;
      end = readRule();
    } else {
      hasRules = false;
    }
  }

  return { stdName, stdOffset, dstName, dstOffset, start, end, hasDst, hasRules };
}

// --- Core logic ---

function computeDayOfMonth(y: number, rule: PosixRule): number {
  const { month, week, day } = rule;
  const dim = daysInMonth(y, month);
  const dowFirst = dayOfWeek(y, month, 1);
  let firstDay: number;
  if (dowFirst <= day) {
    firstDay = 1 + (day - dowFirst);
  } else {
    firstDay = 1 + (7 - dowFirst + day);
  }
  let d = firstDay + (week - 1) * 7;
  if (d > dim) d -= 7;
  return d;
}

function computeTransitionUtc(y: number, rule: PosixRule, utcOffset: number): number {
  const d = computeDayOfMonth(y, rule);
  const localUnix = componentsToUnix(y, rule.month, d, 0, 0, 0) + rule.time;
  return localUnix - utcOffset;
}

function isDstAt(t: number, posix: PosixTZ): boolean {
  if (!posix.hasDst) return false;
  if (!posix.hasRules) return true;

  const comp = unixToComponents(t);
  const year = comp.y;

  const trans: { time: number; toDst: boolean }[] = [];
  for (let y = year - 1; y <= year + 1; y++) {
    trans.push({ time: computeTransitionUtc(y, posix.start, posix.stdOffset), toDst: true });
    trans.push({ time: computeTransitionUtc(y, posix.end, posix.dstOffset), toDst: false });
  }
  trans.sort((a, b) => a.time - b.time);

  let isdst = false;
  for (const tr of trans) {
    if (tr.time <= t) {
      isdst = tr.toDst;
    } else {
      break;
    }
  }
  return isdst;
}

function getOffsetAtTime(tzif: TZifData, posix: PosixTZ | null, t: number): { offset: number; abbr: string; isdst: boolean } {
  const { transitions, typeIndices, types, abbrBuf } = tzif;

  if (transitions.length === 0) {
    if (posix) {
      if (isDstAt(t, posix)) {
        return { offset: posix.dstOffset, abbr: posix.dstName, isdst: true };
      } else {
        return { offset: posix.stdOffset, abbr: posix.stdName, isdst: false };
      }
    }
    const type = types[0];
    return { offset: type.gmtoff, abbr: getAbbr(abbrBuf, type.abbrIndex), isdst: type.isdst === 1 };
  }

  if (t < transitions[0]) {
    const type = types[0];
    return { offset: type.gmtoff, abbr: getAbbr(abbrBuf, type.abbrIndex), isdst: type.isdst === 1 };
  }

  if (t > transitions[transitions.length - 1]) {
    if (posix) {
      if (isDstAt(t, posix)) {
        return { offset: posix.dstOffset, abbr: posix.dstName, isdst: true };
      } else {
        return { offset: posix.stdOffset, abbr: posix.stdName, isdst: false };
      }
    }
    const type = types[typeIndices[transitions.length - 1]];
    return { offset: type.gmtoff, abbr: getAbbr(abbrBuf, type.abbrIndex), isdst: type.isdst === 1 };
  }

  // Binary search: find latest transition <= t
  let lo = 0, hi = transitions.length - 1;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (transitions[mid] <= t) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }
  const type = types[typeIndices[lo]];
  return { offset: type.gmtoff, abbr: getAbbr(abbrBuf, type.abbrIndex), isdst: type.isdst === 1 };
}

// --- Main ---

const dir = process.argv[2];
const queryFile = path.join(dir, 'queries.txt');
const content = fs.readFileSync(queryFile, 'utf8');
const lines = content.split('\n');

const tzifCache: Map<string, { tzif: TZifData; posix: PosixTZ | null }> = new Map();

function getTZif(fileName: string): { tzif: TZifData; posix: PosixTZ | null } {
  if (tzifCache.has(fileName)) return tzifCache.get(fileName)!;
  const filePath = path.join(dir, fileName);
  const tzif = parseTZif(filePath);
  let posix: PosixTZ | null = null;
  if (tzif.footer.length > 0) {
    posix = parsePosixTZ(tzif.footer);
  }
  const result = { tzif, posix };
  tzifCache.set(fileName, result);
  return result;
}

const output: string[] = [];

for (const line of lines) {
  if (!line.trim()) continue;
  const parts = line.split(' ');

  if (parts[0] === 'UTC') {
    const fileName = parts[1];
    const t = parseInt(parts[2]);
    const { tzif, posix } = getTZif(fileName);
    const { offset, abbr } = getOffsetAtTime(tzif, posix, t);
    const localUnix = t + offset;
    const comp = unixToComponents(localUnix);
    const localStr = formatLocal(comp.y, comp.m, comp.d, comp.h, comp.mi, comp.s);
    const offsetStr = formatOffset(offset);
    output.push(`${line} -> ${localStr}${offsetStr} ${abbr}`);

  } else if (parts[0] === 'LOCAL') {
    const fileName = parts[1];
    const wallStr = parts[2];
    const { tzif, posix } = getTZif(fileName);

    const [datePart, timePart] = wallStr.split('T');
    const [wy, wm, wd] = datePart.split('-').map(Number);
    const [wh, wmi, ws] = timePart.split(':').map(Number);
    const wallAsNumber = componentsToUnix(wy, wm, wd, wh, wmi, ws);

    // Collect all possible UTC offsets
    const offsets = new Set<number>();
    for (const type of tzif.types) {
      offsets.add(type.gmtoff);
    }
    if (posix) {
      offsets.add(posix.stdOffset);
      if (posix.hasDst) offsets.add(posix.dstOffset);
    }

    // Compute candidates
    const validCandidates: { t: number; offset: number; abbr: string }[] = [];
    for (const off of offsets) {
      const t = wallAsNumber - off;
      const { offset: actualOffset, abbr } = getOffsetAtTime(tzif, posix, t);
      if (actualOffset === off) {
        const localUnix = t + actualOffset;
        if (localUnix === wallAsNumber) {
          validCandidates.push({ t, offset: off, abbr });
        }
      }
    }

    validCandidates.sort((a, b) => a.t - b.t);

    if (validCandidates.length === 1) {
      const c = validCandidates[0];
      const offsetStr = formatOffset(c.offset);
      output.push(`${line} -> ${c.t} ${offsetStr} ${c.abbr}`);
    } else if (validCandidates.length === 2) {
      const c1 = validCandidates[0];
      const c2 = validCandidates[1];
      const offsetStr1 = formatOffset(c1.offset);
      const offsetStr2 = formatOffset(c2.offset);
      output.push(`${line} -> ${c1.t} ${offsetStr1} ${c1.abbr} | ${c2.t} ${offsetStr2} ${c2.abbr}`);
    } else {
      // Gap: find the transition that caused it
      const allTransitions: { time: number; oldOffset: number; newOffset: number }[] = [];

      // Data block transitions
      for (let i = 0; i < tzif.transitions.length; i++) {
        const tr = tzif.transitions[i];
        const newType = tzif.types[tzif.typeIndices[i]];
        const oldType = i > 0 ? tzif.types[tzif.typeIndices[i - 1]] : tzif.types[0];
        allTransitions.push({ time: tr, oldOffset: oldType.gmtoff, newOffset: newType.gmtoff });
      }

      // Footer transitions
      if (posix && posix.hasDst && posix.hasRules) {
        const comp = unixToComponents(wallAsNumber);
        for (let y = comp.y - 2; y <= comp.y + 2; y++) {
          const startT = computeTransitionUtc(y, posix.start, posix.stdOffset);
          const endT = computeTransitionUtc(y, posix.end, posix.dstOffset);
          allTransitions.push({ time: startT, oldOffset: posix.stdOffset, newOffset: posix.dstOffset });
          allTransitions.push({ time: endT, oldOffset: posix.dstOffset, newOffset: posix.stdOffset });
        }
      }

      let gapTransition: { time: number; oldOffset: number; newOffset: number } | null = null;
      for (const tr of allTransitions) {
        if (tr.newOffset > tr.oldOffset) {
          if (wallAsNumber >= tr.time + tr.oldOffset && wallAsNumber < tr.time + tr.newOffset) {
            gapTransition = tr;
            break;
          }
        }
      }

      if (gapTransition) {
        const t = wallAsNumber - gapTransition.oldOffset;
        const { offset, abbr } = getOffsetAtTime(tzif, posix, t);
        const localUnix = t + offset;
        const comp = unixToComponents(localUnix);
        const localStr = formatLocal(comp.y, comp.m, comp.d, comp.h, comp.mi, comp.s);
        const offsetStr = formatOffset(offset);
        output.push(`${line} -> GAP ${t} ${localStr}${offsetStr} ${abbr}`);
      }
    }
  }
}

