import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

public class Main {
    static final SecureRandom RNG = new SecureRandom();

    public static void main(String[] args) throws Exception {
        for (int i = 0; i < args.length; i++) {
            System.out.println("session " + (i + 1));
            processUrl(args[i]);
        }
    }

    static void processUrl(String url) throws Exception {
        String rest = url.substring(5); // strip "ws://"
        int slashIdx = rest.indexOf('/');
        String hostPort, path;
        if (slashIdx >= 0) {
            hostPort = rest.substring(0, slashIdx);
            path = rest.substring(slashIdx);
        } else {
            hostPort = rest;
            path = "/";
        }

        String host;
        int port;
        int colonIdx = hostPort.lastIndexOf(':');
        if (colonIdx >= 0) {
            host = hostPort.substring(0, colonIdx);
            port = Integer.parseInt(hostPort.substring(colonIdx + 1));
        } else {
            host = hostPort;
            port = 80;
        }

        Socket socket = new Socket(host, port);
        socket.setTcpNoDelay(true);
        BufferedInputStream in = new BufferedInputStream(socket.getInputStream());
        OutputStream out = socket.getOutputStream();

        byte[] keyBytes = new byte[16];
        RNG.nextBytes(keyBytes);
        String wsKey = Base64.getEncoder().encodeToString(keyBytes);

        StringBuilder req = new StringBuilder();
        req.append("GET ").append(path).append(" HTTP/1.1\r\n");
        req.append("Host: ").append(host).append(":").append(port).append("\r\n");
        req.append("Upgrade: websocket\r\n");
        req.append("Connection: Upgrade\r\n");
        req.append("Sec-WebSocket-Version: 13\r\n");
        req.append("Sec-WebSocket-Key: ").append(wsKey).append("\r\n");
        req.append("\r\n");
        out.write(req.toString().getBytes(StandardCharsets.US_ASCII));
        out.flush();

        String statusLine = readLine(in);
        int sp1 = statusLine.indexOf(' ');
        String afterVer = statusLine.substring(sp1 + 1);
        int sp2 = afterVer.indexOf(' ');
        int statusCode;
        String reasonPhrase;
        if (sp2 >= 0) {
            statusCode = Integer.parseInt(afterVer.substring(0, sp2));
            reasonPhrase = afterVer.substring(sp2 + 1);
        } else {
            statusCode = Integer.parseInt(afterVer);
            reasonPhrase = "";
        }

        if (statusCode != 101) {
            System.out.println("handshake failed: " + statusCode + " " + reasonPhrase);
            socket.close();
            return;
        }

        String acceptValue = null;
        while (true) {
            String line = readLine(in);
            if (line.isEmpty()) break;
            int colon = line.indexOf(':');
            if (colon >= 0) {
                String name = line.substring(0, colon).trim();
                String value = line.substring(colon + 1).trim();
                if (name.equalsIgnoreCase("Sec-WebSocket-Accept")) {
                    acceptValue = value;
                }
            }
        }

        String expectedAccept = computeAccept(wsKey);
        if (acceptValue == null || !acceptValue.equals(expectedAccept)) {
            System.out.println("handshake failed: bad Sec-WebSocket-Accept");
            socket.close();
            return;
        }

        processFrames(in, out, socket);
    }

    static String computeAccept(String key) throws Exception {
        MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
        sha1.update((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").getBytes(StandardCharsets.US_ASCII));
        return Base64.getEncoder().encodeToString(sha1.digest());
    }

    static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\r') {
                int next = in.read();
                if (next == '\n') break;
                sb.append((char) c);
                if (next != -1) sb.append((char) next);
            } else if (c == '\n') {
                break;
            } else {
                sb.append((char) c);
            }
        }
        return sb.toString();
    }

    static void processFrames(InputStream in, OutputStream out, Socket socket) throws Exception {
        boolean sentClose = false;
        boolean sha1Waiting = false;
        boolean assembling = false;
        int assembleOpcode = -1;
        ByteArrayOutputStream assembleBuf = null;

        while (true) {
            int b0 = in.read();
            if (b0 == -1) break;
            boolean fin = (b0 & 0x80) != 0;
            int opcode = b0 & 0x0F;

            int b1 = in.read();
            if (b1 == -1) break;
            long payloadLen = b1 & 0x7F;
            if (payloadLen == 126) payloadLen = readBE(in, 2);
            else if (payloadLen == 127) payloadLen = readBE(in, 8);

            byte[] payload = new byte[(int) payloadLen];
            if (payloadLen > 0) readFully(in, payload);

            // Control frames
            if (opcode == 8) { // Close
                int closeCode = 0;
                String closeReason = "";
                if (payload.length >= 2) {
                    closeCode = ((payload[0] & 0xFF) << 8) | (payload[1] & 0xFF);
                    if (payload.length > 2) {
                        closeReason = new String(payload, 2, payload.length - 2, StandardCharsets.UTF_8);
                    }
                }
                if (closeReason.isEmpty()) {
                    System.out.println("closed " + closeCode);
                } else {
                    System.out.println("closed " + closeCode + " " + closeReason);
                }
                if (!sentClose) {
                    sendFrame(out, 8, new byte[]{(byte) (closeCode >> 8), (byte) (closeCode & 0xFF)});
                    sentClose = true;
                }
                socket.close();
                return;
            } else if (opcode == 9) { // Ping
                sendFrame(out, 10, payload);
                continue;
            } else if (opcode == 10) { // Pong
                continue;
            }

            // Data frames
            if (opcode == 1 || opcode == 2) {
                assembling = true;
                assembleOpcode = opcode;
                assembleBuf = new ByteArrayOutputStream();
                assembleBuf.write(payload);
            } else if (opcode == 0) { // Continuation
                if (!assembling) continue;
                assembleBuf.write(payload);
            } else {
                continue;
            }

            if (!fin) continue;

            // Complete message assembled
            assembling = false;
            byte[] msgData = assembleBuf.toByteArray();
            int msgOp = assembleOpcode;

            if (sha1Waiting) {
                sha1Waiting = false;
                MessageDigest md = MessageDigest.getInstance("SHA-1");
                md.update(msgData);
                String hex = bytesToHex(md.digest());
                sendFrame(out, 1, hex.getBytes(StandardCharsets.UTF_8));
                System.out.println("SHA1 " + msgData.length + " -> " + hex);
                continue;
            }

            if (msgOp == 1) {
                String text = new String(msgData, StandardCharsets.UTF_8);

                if (text.equals("BYE")) {
                    sendFrame(out, 8, new byte[]{0x03, (byte) 0xE8});
                    sentClose = true;
                    continue;
                }

                if (text.equals("SHA1")) {
                    sha1Waiting = true;
                    continue;
                }

                if (text.startsWith("ADD ")) {
                    String[] parts = text.split(" ", 3);
                    long a = Long.parseLong(parts[1]);
                    long b = Long.parseLong(parts[2]);
                    long sum = a + b;
                    String reply = String.valueOf(sum);
                    sendFrame(out, 1, reply.getBytes(StandardCharsets.UTF_8));
                    System.out.println(text + " -> " + reply);
                } else if (text.startsWith("REV ")) {
                    String arg = text.substring(4);
                    String reversed = reverseCodePoints(arg);
                    sendFrame(out, 1, reversed.getBytes(StandardCharsets.UTF_8));
                    System.out.println(text + " -> " + reversed);
                }
            }
            // Binary message not for SHA1: ignore
        }

        if (!socket.isClosed()) socket.close();
    }

    static void sendFrame(OutputStream out, int opcode, byte[] payload) throws IOException {
        byte[] maskKey = new byte[4];
        do {
            RNG.nextBytes(maskKey);
        } while (maskKey[0] == 0 && maskKey[1] == 0 && maskKey[2] == 0 && maskKey[3] == 0);

        int len = payload.length;
        int headerSize = 2;
        if (len > 125 && len <= 65535) headerSize += 2;
        else if (len > 65535) headerSize += 8;
        headerSize += 4; // mask key

        byte[] frame = new byte[headerSize + len];
        int pos = 0;

        frame[pos++] = (byte) (0x80 | opcode); // FIN=1, RSV=0

        if (len <= 125) {
            frame[pos++] = (byte) (0x80 | len);
        } else if (len <= 65535) {
            frame[pos++] = (byte) (0x80 | 126);
            frame[pos++] = (byte) (len >> 8);
            frame[pos++] = (byte) (len & 0xFF);
        } else {
            frame[pos++] = (byte) (0x80 | 127);
            long len64 = len & 0xFFFFFFFFL;
            for (int i = 7; i >= 0; i--) {
                frame[pos++] = (byte) ((len64 >> (i * 8)) & 0xFF);
            }
        }

        frame[pos++] = maskKey[0];
        frame[pos++] = maskKey[1];
        frame[pos++] = maskKey[2];
        frame[pos++] = maskKey[3];

        for (int i = 0; i < len; i++) {
            frame[pos++] = (byte) (payload[i] ^ maskKey[i & 3]);
        }

        out.write(frame);
        out.flush();
    }

    static long readBE(InputStream in, int n) throws IOException {
        long val = 0;
        for (int i = 0; i < n; i++) {
            int b = in.read();
            if (b == -1) throw new IOException("EOF");
            val = (val << 8) | (b & 0xFF);
        }
        return val;
    }

    static void readFully(InputStream in, byte[] buf) throws IOException {
        int off = 0;
        while (off < buf.length) {
            int n = in.read(buf, off, buf.length - off);
            if (n == -1) throw new IOException("EOF");
            off += n;
        }
    }

    static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            sb.append(String.format("%02x", b & 0xFF));
        }
        return sb.toString();
    }

    static String reverseCodePoints(String s) {
        int[] cps = s.codePoints().toArray();
        StringBuilder sb = new StringBuilder(cps.length);
        for (int i = cps.length - 1; i >= 0; i--) {
            sb.appendCodePoint(cps[i]);
        }
        return sb.toString();
    }
}

import Foundation
import Darwin
import CommonCrypto

// Buffered socket reader
class SocketReader {
    var buffer: [UInt8] = []
    var pos: Int = 0
    let fd: Int32

    init(fd: Int32) {
        self.fd = fd
    }

    func ensure(_ n: Int) -> Bool {
        while buffer.count - pos < n {
            if pos > 4096 {
                buffer.removeFirst(pos)
                pos = 0
            }
            let needed = n - (buffer.count - pos)
            let toRead = max(needed, 65536)
            var tmp = [UInt8](repeating: 0, count: toRead)
            let bytesRead = tmp.withUnsafeMutableBytes { ptr -> Int in
                Darwin.read(fd, ptr.baseAddress, toRead)
            }
            if bytesRead < 0 {
                if errno == EINTR { continue }
                return false
            }
            if bytesRead == 0 { return false }
            buffer.append(contentsOf: tmp[0..<bytesRead])
        }
        return true
    }

    func readByte() -> UInt8? {
        guard ensure(1) else { return nil }
        let b = buffer[pos]
        pos += 1
        return b
    }

    func readBytes(_ n: Int) -> [UInt8]? {
