    }
}

func writeAll(fd: Int32, data: [UInt8]) {
    var offset = 0
    data.withUnsafeBytes { ptr in
        while offset < data.count {
            let n = Darwin.write(fd, ptr.baseAddress! + offset, data.count - offset)
            if n < 0 {
                if errno == EINTR { continue }
                break
            }
            offset += n
        }
    }
}

func randomMaskKey() -> [UInt8] {
    var key = [UInt8](repeating: 0, count: 4)
    repeat {
        arc4random_buf(&key, 4)
    } while key[0] == 0 && key[1] == 0 && key[2] == 0 && key[3] == 0
    return key
}

