}

func sendFrame(fd: Int32, opcode: UInt8, payload: [UInt8]) {
    var frame: [UInt8] = []
    frame.append(0x80 | opcode)

    let len = payload.count
    if len <= 125 {
        frame.append(0x80 | UInt8(len))
    } else if len <= 65535 {
        frame.append(0x80 | 126)
        frame.append(UInt8(len >> 8))
        frame.append(UInt8(len & 0xFF))
    } else {
        frame.append(0x80 | 127)
        for i in stride(from: 56, through: 0, by: -8) {
            frame.append(UInt8((len >> i) & 0xFF))
        }
    }

    let maskKey = randomMaskKey()
    frame.append(contentsOf: maskKey)

    for i in 0..<payload.count {
        frame.append(payload[i] ^ maskKey[i % 4])
    }

    writeAll(fd: fd, data: frame)
}

