func processSession(urlStr: String) {
    guard let (host, port, path) = parseURL(urlStr) else { return }

    let fd = socket(AF_INET, SOCK_STREAM, 0)
    if fd < 0 { return }
    defer { Darwin.close(fd) }

    var addr = sockaddr_in()
    memset(&addr, 0, MemoryLayout<sockaddr_in>.size)
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = in_port_t(port).bigEndian
    _ = host.withCString { cstr in
        inet_pton(AF_INET, cstr, &addr.sin_addr)
    }

    let connectResult = withUnsafePointer(to: &addr) { addrPtr in
        addrPtr.withMemoryRebound(to: sockaddr.self, capacity: 1) { sockPtr in
            Darwin.connect(fd, sockPtr, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    if connectResult != 0 { return }

    let wsKey = randomKey()

    var request = "GET \(path) HTTP/1.1\r\n"
    request += "Host: \(host):\(port)\r\n"
    request += "Upgrade: websocket\r\n"
    request += "Connection: Upgrade\r\n"
    request += "Sec-WebSocket-Version: 13\r\n"
    request += "Sec-WebSocket-Key: \(wsKey)\r\n"
    request += "\r\n"

    writeAll(fd: fd, data: Array(request.utf8))

    let reader = SocketReader(fd: fd)

    // Read HTTP response header block
    var headerBlock = ""
    while true {
        guard let b = reader.readByte() else { return }
        headerBlock.append(Character(UnicodeScalar(b)))
        if headerBlock.hasSuffix("\r\n\r\n") { break }
    }

    // Parse status line
    let lines = headerBlock.components(separatedBy: "\r\n")
    guard let statusLine = lines.first else { return }
    let statusParts = statusLine.components(separatedBy: " ")
    guard statusParts.count >= 2, let statusCode = Int(statusParts[1]) else { return }

    if statusCode != 101 {
        let reason = statusParts.count >= 3 ? statusParts[2...].joined(separator: " ") : ""
        print("handshake failed: \(statusCode) \(reason)")
        return
    }

    // Check Sec-WebSocket-Accept
    var acceptValue: String?
    for line in lines.dropFirst() {
        if let colonIdx = line.firstIndex(of: ":") {
            let name = String(line[line.startIndex..<colonIdx]).lowercased()
            if name == "sec-websocket-accept" {
                let value = String(line[line.index(after: colonIdx)...])
                acceptValue = value.trimmingCharacters(in: .whitespaces)
            }
        }
    }

    let expectedAccept = computeAccept(key: wsKey)
    if acceptValue != expectedAccept {
        print("handshake failed: bad Sec-WebSocket-Accept")
        return
    }

    var closeSent = false

    func readNextMessage() -> (opcode: UInt8, payload: [UInt8])? {
        var msgOpcode: UInt8 = 0
        var msgPayload: [UInt8] = []

        while true {
            guard let b0 = reader.readByte() else { return nil }
            guard let b1 = reader.readByte() else { return nil }

            let fin = (b0 & 0x80) != 0
            let opcode = b0 & 0x0F
            let masked = (b1 & 0x80) != 0
            var length = Int(b1 & 0x7F)

            if length == 126 {
                guard let bytes = reader.readBytes(2) else { return nil }
                length = (Int(bytes[0]) << 8) | Int(bytes[1])
            } else if length == 127 {
                guard let bytes = reader.readBytes(8) else { return nil }
                length = 0
                for b in bytes {
                    length = (length << 8) | Int(b)
                }
            }

            var maskKey: [UInt8] = []
            if masked {
                guard let key = reader.readBytes(4) else { return nil }
                maskKey = key
            }

            var framePayload = reader.readBytes(length) ?? []
            if masked && !maskKey.isEmpty {
                for i in 0..<framePayload.count {
                    framePayload[i] ^= maskKey[i % 4]
                }
            }

            if opcode == 9 { // Ping
                sendFrame(fd: fd, opcode: 10, payload: framePayload)
                continue
            } else if opcode == 10 { // Pong
                continue
            } else if opcode == 8 { // Close
                return (8, framePayload)
            }

            if opcode == 0 { // Continuation
                msgPayload.append(contentsOf: framePayload)
            } else {
                msgOpcode = opcode
                msgPayload = framePayload
            }

            if fin {
                return (msgOpcode, msgPayload)
            }
        }
    }

    func handleCloseFrame(payload: [UInt8]) {
        var code = 1005
        var reason = ""
        if payload.count >= 2 {
            code = (Int(payload[0]) << 8) | Int(payload[1])
            if payload.count > 2 {
                reason = String(decoding: Array(payload[2...]), as: UTF8.self)
            }
        }
        if reason.isEmpty {
            print("closed \(code)")
        } else {
            print("closed \(code) \(reason)")
        }
        if !closeSent {
            let closePayload: [UInt8] = [UInt8(code >> 8), UInt8(code & 0xFF)]
            sendFrame(fd: fd, opcode: 8, payload: closePayload)
            closeSent = true
        }
    }

    // Main message loop
    while let (opcode, payload) = readNextMessage() {
        if opcode == 8 {
            handleCloseFrame(payload: payload)
            return
        }

        if opcode == 1 {
            let text = String(decoding: payload, as: UTF8.self)

            if text.hasPrefix("ADD ") {
                let argsStr = String(text.dropFirst(4))
                let parts = argsStr.components(separatedBy: " ")
                guard parts.count == 2, let a = Int64(parts[0]), let b = Int64(parts[1]) else { continue }
                let sum = a + b
                print("\(text) -> \(sum)")
            } else if text.hasPrefix("REV ") {
                let revText = String(text.dropFirst(4))
                let reversed = String(revText.unicodeScalars.reversed())
                print("\(text) -> \(reversed)")
            } else if text == "SHA1" {
                guard let (binOp, binPayload) = readNextMessage() else { break }
                if binOp == 8 {
                    handleCloseFrame(payload: binPayload)
                    return
                }
                let hex = sha1Hex(binPayload)
                print("SHA1 \(binPayload.count) -> \(hex)")
            } else if text == "BYE" {
                let closePayload: [UInt8] = [0x03, 0xE8]
                sendFrame(fd: fd, opcode: 8, payload: closePayload)
                closeSent = true
                while let (op, pl) = readNextMessage() {
                    if op == 8 {
                        handleCloseFrame(payload: pl)
                        return
                    }
                }
                return
            }
        }
    }
}

