#[derive(Debug, Clone)]
enum JV { Null, Bool(bool), Num(String), Str(String), Arr(Vec<JV>), Obj(Vec<(String, JV)>) }

impl JV {
    fn get(&self, k: &str) -> Option<&JV> {
        if let JV::Obj(ps) = self { for (a,b) in ps { if a==k { return Some(b); } } }
        None
    }
    fn as_str(&self) -> Option<&str> { if let JV::Str(s)=self { Some(s) } else { None } }
    fn as_i64(&self) -> Option<i64> { if let JV::Num(s)=self { s.parse().ok() } else { None } }
    fn as_arr(&self) -> Option<&Vec<JV>> { if let JV::Arr(a)=self { Some(a) } else { None } }
}

struct JP<'a> { b: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(s: &'a str) -> Self { JP{b:s.as_bytes(),p:0} }
    fn ws(&mut self) { while self.p<self.b.len() && (self.b[self.p]==b' '||self.b[self.p]==b'\t'||self.b[self.p]==b'\n'||self.b[self.p]==b'\r') { self.p+=1; } }
    fn val(&mut self) -> JV {
        self.ws();
        if self.p>=self.b.len() { return JV::Null; }
        match self.b[self.p] {
            b'{' => self.obj(), b'[' => self.arr(), b'"' => JV::Str(self.sraw()),
            b't' => { self.p+=4; JV::Bool(true) }, b'f' => { self.p+=5; JV::Bool(false) },
            b'n' => { self.p+=4; JV::Null }, _ => self.num(),
        }
    }
    fn obj(&mut self) -> JV {
        self.p+=1; let mut ps=Vec::new(); self.ws();
        if self.p<self.b.len() && self.b[self.p]==b'}' { self.p+=1; return JV::Obj(ps); }
        loop { self.ws(); let k=self.sraw(); self.ws(); if self.p<self.b.len() && self.b[self.p]==b':' { self.p+=1; }
            let v=self.val(); ps.push((k,v)); self.ws();
            if self.p<self.b.len() && self.b[self.p]==b',' { self.p+=1; } else { break; } }
        self.ws(); if self.p<self.b.len() && self.b[self.p]==b'}' { self.p+=1; }
        JV::Obj(ps)
    }
    fn arr(&mut self) -> JV {
        self.p+=1; let mut a=Vec::new(); self.ws();
        if self.p<self.b.len() && self.b[self.p]==b']' { self.p+=1; return JV::Arr(a); }
        loop { a.push(self.val()); self.ws();
            if self.p<self.b.len() && self.b[self.p]==b',' { self.p+=1; } else { break; } }
        self.ws(); if self.p<self.b.len() && self.b[self.p]==b']' { self.p+=1; }
        JV::Arr(a)
    }
    fn sraw(&mut self) -> String {
        self.p+=1; let mut o:Vec<u8>=Vec::new();
        while self.p<self.b.len() {
            let c=self.b[self.p];
            if c==b'"' { self.p+=1; break; }
            if c==b'\\' { self.p+=1; if self.p>=self.b.len(){break;}
                let e=self.b[self.p]; self.p+=1;
                match e {
                    b'"'=>o.push(b'"'), b'\\'=>o.push(b'\\'), b'/'=>o.push(b'/'),
                    b'b'=>o.push(8), b'f'=>o.push(12), b'n'=>o.push(10), b'r'=>o.push(13), b't'=>o.push(9),
                    b'u'=>{ let cp=self.h4();
                        if cp>=0xD800&&cp<=0xDBFF {
                            if self.p+1<self.b.len()&&self.b[self.p]==b'\\'&&self.b[self.p+1]==b'u' {
                                self.p+=2; let cp2=self.h4();
                                if cp2>=0xDC00&&cp2<=0xDFFF {
                                    let f=0x10000u32+((cp-0xD800)<<10)+(cp2-0xDC00);
                                    if let Some(ch)=char::from_u32(f){let mut bu=[0u8;4];o.extend_from_slice(ch.encode_utf8(&mut bu).as_bytes());}
                                    else{o.extend_from_slice("\u{FFFD}".as_bytes());}
                                } else { o.extend_from_slice("\u{FFFD}".as_bytes()); o.extend_from_slice("\u{FFFD}".as_bytes()); }
                            } else { o.extend_from_slice("\u{FFFD}".as_bytes()); }
                        } else if cp>=0xDC00&&cp<=0xDFFF { o.extend_from_slice("\u{FFFD}".as_bytes()); }
                        else { if let Some(ch)=char::from_u32(cp){let mut bu=[0u8;4];o.extend_from_slice(ch.encode_utf8(&mut bu).as_bytes());} else {o.extend_from_slice("\u{FFFD}".as_bytes());} }
                    }
                    _=>{o.push(b'\\');o.push(e);}
                }
            } else { o.push(c); self.p+=1; }
        }
        String::from_utf8(o).unwrap_or_default()
    }
    fn h4(&mut self)->u32{let mut v=0u32;for _ in 0..4{let c=self.b[self.p];self.p+=1;v=v*16+match c{b'0'..=b'9'=>(c-b'0')as u32,b'a'..=b'f'=>(c-b'a'+10)as u32,b'A'..=b'F'=>(c-b'A'+10)as u32,_=>0};}v}
    fn num(&mut self)->JV{
        let s=self.p;
        if self.p<self.b.len()&&self.b[self.p]==b'-'{self.p+=1;}
        while self.p<self.b.len()&&self.b[self.p].is_ascii_digit(){self.p+=1;}
        if self.p<self.b.len()&&self.b[self.p]==b'.'{self.p+=1;while self.p<self.b.len()&&self.b[self.p].is_ascii_digit(){self.p+=1;}}
        if self.p<self.b.len()&&(self.b[self.p]==b'e'||self.b[self.p]==b'E'){self.p+=1;if self.p<self.b.len()&&(self.b[self.p]==b'+'||self.b[self.p]==b'-'){self.p+=1;}while self.p<self.b.len()&&self.b[self.p].is_ascii_digit(){self.p+=1;}}
        JV::Num(String::from_utf8_lossy(&self.b[s..self.p]).to_string())
    }
}

