    s
}

fn sha1(data: &[u8]) -> [u8; 20] {
    let mut h: [u32; 5] = [0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0];
    let msg_len = data.len();
    let bit_len = (msg_len as u64) * 8;
    let pad_len = if msg_len % 64 <= 55 {
        55 - msg_len % 64
    } else {
        119 - msg_len % 64
    };
    let mut padded = Vec::with_capacity(msg_len + 1 + pad_len + 8);
    padded.extend_from_slice(data);
    padded.push(0x80);
    for _ in 0..pad_len {
        padded.push(0);
    }
    padded.extend_from_slice(&bit_len.to_be_bytes());

    for block in padded.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([block[i * 4], block[i * 4 + 1], block[i * 4 + 2], block[i * 4 + 3]]);
        }
        for i in 16..80 {
            w[i] = (w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]).rotate_left(1);
        }
        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        for i in 0..80 {
            let (f, k) = if i < 20 {
                ((b & c) | ((!b) & d), 0x5A827999u32)
            } else if i < 40 {
                (b ^ c ^ d, 0x6ED9EBA1u32)
            } else if i < 60 {
                ((b & c) | (b & d) | (c & d), 0x8F1BBCDCu32)
            } else {
                (b ^ c ^ d, 0xCA62C1D6u32)
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
    }
    let mut result = [0u8; 20];
    for i in 0..5 {
        let bytes = h[i].to_be_bytes();
        result[i * 4] = bytes[0];
        result[i * 4 + 1] = bytes[1];
        result[i * 4 + 2] = bytes[2];
        result[i * 4 + 3] = bytes[3];
    }
    result
}

fn random_bytes(n: usize) -> Vec<u8> {
    let mut file = std::fs::File::open("/dev/urandom").expect("open urandom");
    let mut buf = vec![0u8; n];
    file.read_exact(&mut buf).expect("read urandom");
    buf
}

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("ws://").expect("bad url");
    let slash_pos = rest.find('/').unwrap_or(rest.len());
    let host_port = &rest[..slash_pos];
    let path = if slash_pos < rest.len() { &rest[slash_pos..] } else { "/" };
    let colon_pos = host_port.rfind(':').expect("no port");
    let host = host_port[..colon_pos].to_string();
    let port: u16 = host_port[colon_pos + 1..].parse().expect("bad port");
    (host, port, path.to_string())
}

fn compute_accept(key: &str) -> String {
    let input = format!("{}258EAFA5-E914-47DA-95CA-C5AB0DC85B11", key);
    let digest = sha1(input.as_bytes());
    b64_encode(&digest)
}

fn read_frame<R: Read>(reader: &mut R) -> Option<(bool, u8, Vec<u8>)> {
    let mut hdr = [0u8; 2];
    if reader.read_exact(&mut hdr).is_err() {
        return None;
    }
    let fin = (hdr[0] & 0x80) != 0;
    let opcode = hdr[0] & 0x0F;
    let masked = (hdr[1] & 0x80) != 0;
    let len7 = hdr[1] & 0x7F;
    let payload_len: u64 = if len7 == 126 {
        let mut b = [0u8; 2];
        if reader.read_exact(&mut b).is_err() { return None; }
        u16::from_be_bytes(b) as u64
    } else if len7 == 127 {
        let mut b = [0u8; 8];
        if reader.read_exact(&mut b).is_err() { return None; }
        u64::from_be_bytes(b)
    } else {
        len7 as u64
    };
    let mut mask_key = [0u8; 4];
    if masked {
        if reader.read_exact(&mut mask_key).is_err() { return None; }
    }
    let mut payload = vec![0u8; payload_len as usize];
    if payload_len > 0 {
        if reader.read_exact(&mut payload).is_err() { return None; }
    }
    if masked {
        for i in 0..payload.len() {
            payload[i] ^= mask_key[i & 3];
        }
    }
    Some((fin, opcode, payload))
}

fn send_frame<W: Write>(writer: &mut W, opcode: u8, payload: &[u8]) {
    let mut frame = Vec::new();
    frame.push(0x80 | opcode);
    let len = payload.len();
    if len <= 125 {
        frame.push(0x80 | len as u8);
    } else if len <= 65535 {
        frame.push(0x80 | 126);
        frame.extend_from_slice(&(len as u16).to_be_bytes());
    } else {
        frame.push(0x80 | 127);
        frame.extend_from_slice(&(len as u64).to_be_bytes());
    }
    let key = loop {
        let k = random_bytes(4);
        if k != [0u8; 4] { break k; }
    };
    frame.extend_from_slice(&key);
    for (i, &b) in payload.iter().enumerate() {
        frame.push(b ^ key[i & 3]);
    }
    writer.write_all(&frame).unwrap();
    writer.flush().unwrap();
}

fn handle_session(url: &str) {
    let (host, port, path) = parse_url(url);
    let stream = match TcpStream::connect(format!("{}:{}", host, port)) {
        Ok(s) => s,
        Err(_) => return,
    };
    let mut reader = BufReader::new(stream.try_clone().unwrap());
    let mut writer = stream;

    let key_bytes = random_bytes(16);
    let ws_key = b64_encode(&key_bytes);

    let request = format!(
        "GET {} HTTP/1.1\r\nHost: {}:{}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: {}\r\n\r\n",
        path, host, port, ws_key
    );
    writer.write_all(request.as_bytes()).unwrap();
    writer.flush().unwrap();

    let mut status_line = String::new();
    if reader.read_line(&mut status_line).unwrap() == 0 {
        return;
    }
    let status_line_t = status_line.trim_end_matches("\r\n");
    let parts: Vec<&str> = status_line_t.splitn(3, ' ').collect();
    let status_code: u16 = parts[1].parse().unwrap_or(0);
    let reason_phrase = if parts.len() >= 3 { parts[2] } else { "" };

    let mut headers: Vec<(String, String)> = Vec::new();
    loop {
        let mut line = String::new();
        let n = reader.read_line(&mut line).unwrap();
        if n == 0 { break; }
        if line == "\r\n" || line == "\n" { break; }
        if let Some(colon) = line.find(':') {
            let name = line[..colon].trim().to_lowercase();
            let value = line[colon + 1..].trim().to_string();
            headers.push((name, value));
        }
    }

    if status_code != 101 {
        println!("handshake failed: {} {}", status_code, reason_phrase);
        return;
    }

    let expected_accept = compute_accept(&ws_key);
    let accept_ok = headers.iter().any(|(name, value)| {
        name == "sec-websocket-accept" && *value == expected_accept
    });
    if !accept_ok {
        println!("handshake failed: bad Sec-WebSocket-Accept");
        return;
    }

    let mut sent_close = false;
    let mut expecting_sha1 = false;
    let mut frag_opcode: u8 = 0;
    let mut frag_payload: Vec<u8> = Vec::new();

    loop {
        let (fin, opcode, payload) = match read_frame(&mut reader) {
            Some(f) => f,
            None => break,
        };

        match opcode {
            0x9 => {
                send_frame(&mut writer, 0xA, &payload);
            }
            0xA => {}
            0x8 => {
                let code = if payload.len() >= 2 {
                    u16::from_be_bytes([payload[0], payload[1]])
                } else {
                    1005
                };
                let reason = if payload.len() > 2 {
                    String::from_utf8_lossy(&payload[2..]).to_string()
                } else {
                    String::new()
                };
                if reason.is_empty() {
                    println!("closed {}", code);
                } else {
                    println!("closed {} {}", code, reason);
                }
                if !sent_close {
                    let cp = code.to_be_bytes().to_vec();
                    send_frame(&mut writer, 0x8, &cp);
                }
                break;
            }
            0x0 => {
                frag_payload.extend_from_slice(&payload);
                if fin {
                    process_message(frag_opcode, &frag_payload, &mut writer, &mut sent_close, &mut expecting_sha1);
                }
            }
            0x1 | 0x2 => {
                if fin {
                    process_message(opcode, &payload, &mut writer, &mut sent_close, &mut expecting_sha1);
                } else {
                    frag_opcode = opcode;
                    frag_payload = payload;
                }
            }
            _ => {}
        }
    }
}

fn process_message(opcode: u8, payload: &[u8], writer: &mut TcpStream, sent_close: &mut bool, expecting_sha1: &mut bool) {
    if *expecting_sha1 {
        let digest = sha1(payload);
        let hex: String = digest.iter().map(|b| format!("{:02x}", b)).collect();
        println!("SHA1 {} -> {}", payload.len(), hex);
        send_frame(writer, 0x1, hex.as_bytes());
        *expecting_sha1 = false;
        return;
    }

    if opcode == 0x1 {
        let cmd = String::from_utf8_lossy(payload).to_string();

        if cmd == "BYE" {
            send_frame(writer, 0x8, &[0x03, 0xE8]);
            *sent_close = true;
        } else if cmd.starts_with("ADD ") {
            let params = &cmd[4..];
            let parts: Vec<&str> = params.split_whitespace().collect();
            let a: i64 = parts[0].parse().unwrap();
            let b: i64 = parts[1].parse().unwrap();
            let sum = a + b;
            println!("{} -> {}", cmd, sum);
            send_frame(writer, 0x1, sum.to_string().as_bytes());
        } else if cmd.starts_with("REV ") {
            let text = &cmd[4..];
            let reversed: String = text.chars().rev().collect();
            println!("{} -> {}", cmd, reversed);
            send_frame(writer, 0x1, reversed.as_bytes());
        } else if cmd == "SHA1" {
            *expecting_sha1 = true;
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    for (idx, url) in args.iter().enumerate() {
        println!("session {}", idx + 1);
        handle_session(url);
    }
    std::process::exit(0);
}

use std::fs;
use std::io::Read;
use std::path::Path;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];

    let mut entries: Vec<String> = Vec::new();
    if let Ok(rd) = fs::read_dir(dir) {
        for entry in rd.flatten() {
            let name = entry.file_name().to_string_lossy().to_string();
            if name.ends_with(".wav") {
                if entry.path().is_file() {
                    entries.push(name);
                }
            }
        }
    }
    entries.sort();

    let low_freqs: [f64; 4] = [697.0, 770.0, 852.0, 941.0];
    let high_freqs: [f64; 4] = [1209.0, 1336.0, 1477.0, 1633.0];

    let keypad: [[char; 4]; 4] = [
        ['1', '2', '3', 'A'],
        ['4', '5', '6', 'B'],
        ['7', '8', '9', 'C'],
        ['*', '0', '#', 'D'],
    ];

    let mut first_file = true;
    for name in &entries {
        if !first_file {
            println!();
        }
        first_file = false;

        let path = Path::new(dir).join(name);
        let mut buf = Vec::new();
        if let Ok(mut f) = fs::File::open(&path) {
            f.read_to_end(&mut buf).unwrap();
        }

        let (rate, channels, samples) = parse_wav(&buf);

        match samples {
            None => {
                println!("{}: unsupported", name);
            }
            Some(data) => {
                let frames = data.len();
                let n = (rate / 50) as usize;
                let blocks = frames / n;

                println!("{}: {} Hz, {} ch, {} blocks", name, rate, channels, blocks);

                let mut labels: Vec<Option<char>> = vec![None; blocks];

                for i in 0..blocks {
                    let start = i * n;
                    let end = start + n;
                    let block = &data[start..end];

                    let e: f64 = block.iter().map(|&x| (x as f64) * (x as f64)).sum();

                    if e < 1_000_000.0 * (n as f64) {
                        continue;
                    }

                    let mut max_r_low = 0.0f64;
                    let mut best_low = 0usize;
                    for fi in 0..4 {
                        let r = goertzel_relative(block, low_freqs[fi], rate as f64, n, e);
                        if r > max_r_low {
                            max_r_low = r;
                            best_low = fi;
                        }
                    }

                    let mut max_r_high = 0.0f64;
                    let mut best_high = 0usize;
                    for fi in 0..4 {
                        let r = goertzel_relative(block, high_freqs[fi], rate as f64, n, e);
                        if r > max_r_high {
                            max_r_high = r;
                            best_high = fi;
                        }
                    }

                    if max_r_low >= 0.1 && max_r_high >= 0.1 && max_r_low + max_r_high >= 0.6 {
                        labels[i] = Some(keypad[best_low][best_high]);
                    }
                }

                // Bridging: use original labels to decide
                let orig_labels = labels.clone();
                if blocks >= 3 {
                    for i in 1..blocks - 1 {
                        if orig_labels[i].is_none() {
                            if orig_labels[i - 1].is_some() && orig_labels[i - 1] == orig_labels[i + 1] {
                                labels[i] = orig_labels[i - 1];
                            }
                        }
                    }
                }

                // Find events (runs of >= 2 consecutive same-digit blocks)
                let mut events: Vec<(char, usize, usize)> = Vec::new();
                let mut i = 0;
                while i < blocks {
                    if labels[i].is_some() {
                        let digit = labels[i].unwrap();
                        let start = i;
                        while i < blocks && labels[i] == Some(digit) {
                            i += 1;
                        }
                        let end = i;
                        if end - start >= 2 {
                            events.push((digit, 20 * start, 20 * end));
                        }
                    } else {
                        i += 1;
                    }
                }

                for &(digit, start, end) in &events {
                    println!("{} {} {}", digit, start, end);
                }

                let digits: String = events.iter().map(|&(d, _, _)| d).collect();
                println!("digits: {}", digits);
            }
        }
    }
}

fn parse_wav(buf: &[u8]) -> (u32, u32, Option<Vec<i16>>) {
    if buf.len() < 12 {
        return (0, 0, None);
    }
    if &buf[0..4] != b"RIFF" || &buf[8..12] != b"WAVE" {
        return (0, 0, None);
    }

    let mut pos = 12usize;
    let mut fmt_body: Option<Vec<u8>> = None;
    let mut data_body: Option<Vec<u8>> = None;

    while pos + 8 <= buf.len() {
        let chunk_id = &buf[pos..pos + 4];
        let chunk_size =
            u32::from_le_bytes([buf[pos + 4], buf[pos + 5], buf[pos + 6], buf[pos + 7]]) as usize;
        pos += 8;

        let body_end = pos + chunk_size;
        if body_end > buf.len() {
            break;
        }

        if chunk_id == b"fmt " {
            fmt_body = Some(buf[pos..body_end].to_vec());
        } else if chunk_id == b"data" {
            data_body = Some(buf[pos..body_end].to_vec());
        }

        pos = body_end;
        if chunk_size % 2 != 0 {
            pos += 1;
        }
    }

    let fmt = match fmt_body {
        Some(f) => f,
        None => return (0, 0, None),
    };
    let data = match data_body {
        Some(d) => d,
        None => return (0, 0, None),
    };

    if fmt.len() < 16 {
        return (0, 0, None);
    }

    let format_tag = u16::from_le_bytes([fmt[0], fmt[1]]);
    let channels = u16::from_le_bytes([fmt[2], fmt[3]]) as u32;
    let rate = u32::from_le_bytes([fmt[4], fmt[5], fmt[6], fmt[7]]);
    let bits = u16::from_le_bytes([fmt[14], fmt[15]]) as u32;

    let effective_format = if format_tag == 0xFFFE {
        if fmt.len() >= 26 {
            u16::from_le_bytes([fmt[24], fmt[25]])
        } else {
            return (rate, channels, None);
        }
    } else {
        format_tag
    };

    if effective_format != 1 || bits != 16 {
        return (rate, channels, None);
    }

    if channels != 1 && channels != 2 {
        return (rate, channels, None);
    }

    if rate != 8000 && rate != 16000 {
        return (rate, channels, None);
    }

    let frames = data.len() / (2 * channels as usize);
    let mut samples: Vec<i16> = Vec::with_capacity(frames);
    for i in 0..frames {
        let offset = i * 2 * channels as usize;
        let sample = i16::from_le_bytes([data[offset], data[offset + 1]]);
        samples.push(sample);
    }

    (rate, channels, Some(samples))
}

fn goertzel_relative(block: &[i16], freq: f64, rate: f64, n: usize, energy: f64) -> f64 {
    let c = 2.0 * (2.0 * std::f64::consts::PI * freq / rate).cos();
    let mut s1 = 0.0f64;
    let mut s2 = 0.0f64;
    for &x in block {
        let s = x as f64 + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    let power = s1 * s1 + s2 * s2 - c * s1 * s2;
    2.0 * power / (n as f64 * energy)
}

#!/usr/bin/env python3
import sys
import struct
import os
from datetime import datetime, timedelta
from bisect import bisect_right

EPOCH = datetime(1970, 1, 1)


def parse_tzif(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()

    pos = 0
    # First header
    counts1 = struct.unpack('>6I', data[20:44])
    isutcnt1, isstdcnt1, leapcnt1, timecnt1, typecnt1, charcnt1 = counts1
    pos = 44
    block1_size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1
    pos += block1_size

    # Second header
    counts2 = struct.unpack('>6I', data[pos + 20:pos + 44])
    isutcnt2, isstdcnt2, leapcnt2, timecnt2, typecnt2, charcnt2 = counts2
    pos += 44

    # Transition times (64-bit signed big-endian)
    trans_times = list(struct.unpack('>{}q'.format(timecnt2), data[pos:pos + timecnt2 * 8]))
    pos += timecnt2 * 8

    # Transition type indices
    trans_types = list(data[pos:pos + timecnt2])
    pos += timecnt2

    # Local time type records
    ttinfos = []
    for i in range(typecnt2):
        gmtoff = struct.unpack('>i', data[pos:pos + 4])[0]
        isdst = data[pos + 4]
        abbridx = data[pos + 5]
        ttinfos.append((gmtoff, isdst, abbridx))
        pos += 6

    # Abbreviations
    abbrs = data[pos:pos + charcnt2]
    pos += charcnt2

    # Skip leap seconds, isstd, isut
    pos += leapcnt2 * 12 + isstdcnt2 + isutcnt2

    # Footer
    assert data[pos] == ord('\n')
    pos += 1
    end = data.index(b'\n', pos)
    posix_str = data[pos:end].decode('ascii')

    return trans_times, trans_types, ttinfos, abbrs, posix_str


def get_abbr(abbrs, idx):
    end = abbrs.index(0, idx)
    return abbrs[idx:end].decode('ascii')


def parse_posix_tz(s):
    if not s:
        return None
    pos = [0]

    def parse_name():
        if s[pos[0]] == '<':
            end = s.index('>', pos[0])
            name = s[pos[0] + 1:end]
            pos[0] = end + 1
            return name
        start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isalpha():
            pos[0] += 1
        return s[start:pos[0]]

    def parse_offset():
        sign = 1
        if pos[0] < len(s) and s[pos[0]] in '+-':
            if s[pos[0]] == '-':
                sign = -1
            pos[0] += 1
        h_start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        hours = int(s[h_start:pos[0]])
        minutes = 0
        seconds = 0
        if pos[0] < len(s) and s[pos[0]] == ':':
            pos[0] += 1
            m_start = pos[0]
            while pos[0] < len(s) and s[pos[0]].isdigit():
                pos[0] += 1
            minutes = int(s[m_start:pos[0]])
        if pos[0] < len(s) and s[pos[0]] == ':':
            pos[0] += 1
            s_start = pos[0]
            while pos[0] < len(s) and s[pos[0]].isdigit():
                pos[0] += 1
            seconds = int(s[s_start:pos[0]])
        return sign * (hours * 3600 + minutes * 60 + seconds)

    def parse_rule():
        assert s[pos[0]] == 'M'
        pos[0] += 1
        m_start = pos[0]
        while s[pos[0]].isdigit():
            pos[0] += 1
        month = int(s[m_start:pos[0]])
        assert s[pos[0]] == '.'
        pos[0] += 1
        w_start = pos[0]
        while s[pos[0]].isdigit():
            pos[0] += 1
        week = int(s[w_start:pos[0]])
        assert s[pos[0]] == '.'
        pos[0] += 1
        d_start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        day = int(s[d_start:pos[0]])
        time = 2 * 3600
        if pos[0] < len(s) and s[pos[0]] == '/':
            pos[0] += 1
            time = parse_offset()
        return (month, week, day, time)

    std_name = parse_name()
    std_posix_offset = parse_offset()

    dst_name = None
    dst_posix_offset = None
    start_rule = None
    end_rule = None

    if pos[0] < len(s) and s[pos[0]] != ',':
        dst_name = parse_name()
        if pos[0] < len(s) and s[pos[0]] in '+-0123456789':
            dst_posix_offset = parse_offset()
        else:
            dst_posix_offset = std_posix_offset - 3600

    if pos[0] < len(s) and s[pos[0]] == ',':
        pos[0] += 1
        start_rule = parse_rule()
        if pos[0] < len(s) and s[pos[0]] == ',':
            pos[0] += 1
            end_rule = parse_rule()

    return (std_name, std_posix_offset, dst_name, dst_posix_offset, start_rule, end_rule)


def compute_transition_local(year, rule):
    month, week, day, time = rule
    first_day = datetime(year, month, 1)
    first_dow = (first_day.weekday() + 1) % 7  # 0=Sun
    delta = (day - first_dow) % 7
    first_occurrence = 1 + delta
    if week == 5:
        if month == 12:
            next_month = datetime(year + 1, 1, 1)
        else:
            next_month = datetime(year, month + 1, 1)
        days_in_month = (next_month - first_day).days
        target_day = first_occurrence + 7 * ((days_in_month - first_occurrence) // 7)
    else:
        target_day = first_occurrence + 7 * (week - 1)
    dt = datetime(year, month, target_day)
    d = dt - EPOCH
    return d.days * 86400 + d.seconds + time


def get_utc_offset_at(t, trans_times, trans_types, ttinfos, abbrs, posix_info):
    """Return (utc_offset_seconds, abbreviation) for Unix time t."""
    # After last transition: use POSIX footer rule
    if trans_times and t > trans_times[-1]:
        if posix_info:
            std_name, std_posix_offset, dst_name, dst_posix_offset, start_rule, end_rule = posix_info
            std_utc_offset = -std_posix_offset
            if dst_name is None or start_rule is None or end_rule is None:
                return std_utc_offset, std_name
            dst_utc_offset = -dst_posix_offset
            approx_year = int(t // 31557600) + 1970
            for year in range(approx_year - 1, approx_year + 2):
                start_local = compute_transition_local(year, start_rule)
                end_local = compute_transition_local(year, end_rule)
                start_unix = start_local - std_utc_offset
                end_unix = end_local - dst_utc_offset
                if start_unix < end_unix:
                    # Northern hemisphere
                    if start_unix <= t < end_unix:
                        return dst_utc_offset, dst_name
                elif start_unix > end_unix:
                    # Southern hemisphere: DST from start to end of year, and from start of year to end
                    if t >= start_unix or t < end_unix:
                        return dst_utc_offset, dst_name
                # start_unix == end_unix: no DST
            return std_utc_offset, std_name
        else:
            # No footer rule; use last transition type
            type_idx = trans_types[-1]
            gmtoff, isdst, abbridx = ttinfos[type_idx]
            return gmtoff, get_abbr(abbrs, abbridx)

    # Before first transition or no transitions
    if not trans_times or t < trans_times[0]:
        gmtoff, isdst, abbridx = ttinfos[0]
        return gmtoff, get_abbr(abbrs, abbridx)

    # Between transitions (inclusive of last)
    idx = bisect_right(trans_times, t) - 1
    type_idx = trans_types[idx]
    gmtoff, isdst, abbridx = ttinfos[type_idx]
    return gmtoff, get_abbr(abbrs, abbridx)


def format_offset(utc_offset):
    if utc_offset < 0:
        sign = '-'
        utc_offset = -utc_offset
    else:
        sign = '+'
    hours = utc_offset // 3600
    minutes = (utc_offset % 3600) // 60
    seconds = utc_offset % 60
    if seconds != 0:
        return "{}{:02d}:{:02d}:{:02d}".format(sign, hours, minutes, seconds)
    else:
        return "{}{:02d}:{:02d}".format(sign, hours, minutes)


def sec_to_str(seconds):
    dt = EPOCH + timedelta(seconds=seconds)
    return "{:04d}-{:02d}-{:02d}T{:02d}:{:02d}:{:02d}".format(
        dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second)


def main():
    directory = sys.argv[1]
    tzif_cache = {}

    def load_tzif(filename):
        if filename not in tzif_cache:
            filepath = os.path.join(directory, filename)
            tzif_cache[filename] = parse_tzif(filepath)
        return tzif_cache[filename]

    queries_path = os.path.join(directory, 'queries.txt')
    with open(queries_path, 'r') as f:
        lines = f.readlines()

    results = []

    for line in lines:
        line = line.rstrip('\r\n')
        if not line.strip():
            continue

        parts = line.split(' ')
        query_type = parts[0]
        filename = parts[1]

        trans_times, trans_types, ttinfos, abbrs, posix_str = load_tzif(filename)
        posix_info = parse_posix_tz(posix_str)

        if query_type == 'UTC':
            t = int(parts[2])
            utc_offset, abbr = get_utc_offset_at(t, trans_times, trans_types, ttinfos, abbrs, posix_info)
            local_seconds = t + utc_offset
            local_str = sec_to_str(local_seconds)
            offset_str = format_offset(utc_offset)
            results.append("{} -> {}{} {}".format(line, local_str, offset_str, abbr))

        elif query_type == 'LOCAL':
            wall_str = parts[2]
            dt = datetime.strptime(wall_str, '%Y-%m-%dT%H:%M:%S')
            d = dt - EPOCH
            W = d.days * 86400 + d.seconds

            # Collect candidate UTC offsets
            offsets = set()
            for gmtoff, isdst, abbridx in ttinfos:
                offsets.add(gmtoff)
            if posix_info:
                std_name, std_posix_offset, dst_name, dst_posix_offset, start_rule, end_rule = posix_info
                offsets.add(-std_posix_offset)
                if dst_posix_offset is not None:
                    offsets.add(-dst_posix_offset)

            # Find all valid solutions
            solutions = []
            for o in offsets:
                t = W - o
                actual_offset, abbr = get_utc_offset_at(t, trans_times, trans_types, ttinfos, abbrs, posix_info)
                if actual_offset == o:
                    solutions.append((t, o, abbr))

            solutions.sort(key=lambda x: x[0])

            if len(solutions) == 1:
                t, o, abbr = solutions[0]
                results.append("{} -> {} {} {}".format(line, t, format_offset(o), abbr))
            elif len(solutions) >= 2:
                parts_out = []
                for t, o, abbr in solutions:
                    parts_out.append("{} {} {}".format(t, format_offset(o), abbr))
                results.append("{} -> {}".format(line, ' | '.join(parts_out)))
            else:
                # GAP: find the spring-forward transition that skipped W
                offset_before = None

                # Check file transitions
                for i in range(len(trans_times)):
                    T = trans_times[i]
                    if i == 0:
                        ob = ttinfos[0][0]
                    else:
                        ob = ttinfos[trans_types[i - 1]][0]
                    oa = ttinfos[trans_types[i]][0]
                    if oa > ob:
                        gap_start = T + ob
                        gap_end = T + oa
                        if gap_start <= W < gap_end:
                            offset_before = ob
                            break

                # Check POSIX rule transitions
                if offset_before is None and posix_info:
                    std_name, std_posix_offset, dst_name, dst_posix_offset, start_rule, end_rule = posix_info
                    if dst_name and start_rule and end_rule:
                        std_utc_offset = -std_posix_offset
                        dst_utc_offset = -dst_posix_offset
                        approx_year = int(W // 31557600) + 1970
                        last_file_trans = trans_times[-1] if trans_times else None

                        for year in range(approx_year - 1, approx_year + 2):
                            start_local = compute_transition_local(year, start_rule)
                            end_local = compute_transition_local(year, end_rule)
                            start_unix = start_local - std_utc_offset
                            end_unix = end_local - dst_utc_offset

                            # Spring forward: std -> dst
                            if dst_utc_offset > std_utc_offset:
                                if last_file_trans is None or start_unix > last_file_trans:
                                    gap_start = start_unix + std_utc_offset
                                    gap_end = start_unix + dst_utc_offset
                                    if gap_start <= W < gap_end:
                                        offset_before = std_utc_offset
                                        break

                            # Fall back creating gap (if std > dst, unusual)
                            if std_utc_offset > dst_utc_offset:
                                if last_file_trans is None or end_unix > last_file_trans:
                                    gap_start = end_unix + dst_utc_offset
                                    gap_end = end_unix + std_utc_offset
                                    if gap_start <= W < gap_end:
                                        offset_before = dst_utc_offset
                                        break

                if offset_before is None:
                    # Fallback (should not happen with valid input)
                    if posix_info:
                        offset_before = -posix_info[1]
                    elif trans_times:
                        offset_before = ttinfos[trans_types[-1]][0]
                    else:
                        offset_before = ttinfos[0][0]

                t = W - offset_before
                utc_offset, abbr = get_utc_offset_at(t, trans_times, trans_types, ttinfos, abbrs, posix_info)
                local_seconds = t + utc_offset
                local_str = sec_to_str(local_seconds)
                offset_str = format_offset(utc_offset)
                results.append("{} -> GAP {} {} {}".format(line, t, local_str, offset_str, abbr))

    for r in results:
        print(r)


if __name__ == '__main__':
    main()

import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;

public class Main {

    static class TzData {
        long[] transTimes;
        int[] transTypeIdx;
        int[] utOffsets;
        boolean[] isDsts;
        String[] abbrevs;

        String stdName;
        int stdOffset;
        String dstName;
        int dstOffset;
        boolean hasDst;

        int startMonth, startWeek, startDay;
        int startTime;
        int endMonth, endWeek, endDay;
        int endTime;

        long lastTransTime;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        List<String> lines = Files.readAllLines(Path.of(dir, "queries.txt"));
        Map<String, TzData> cache = new HashMap<>();

        StringBuilder output = new StringBuilder();
        for (String line : lines) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split(" ");
            String type = parts[0];
            String fileName = parts[1];

            TzData tz = cache.computeIfAbsent(fileName, f -> {
                try { return parseTzif(Path.of(dir, f)); }
                catch (Exception e) { throw new RuntimeException(e); }
            });

            if (type.equals("UTC")) {
                long t = Long.parseLong(parts[2]);
                output.append(handleUTC(line, tz, t)).append("\n");
            } else {
                String wallClock = parts[2];
                output.append(handleLocal(line, tz, wallClock)).append("\n");
            }
        }

        System.out.print(output);
    }

    static TzData parseTzif(Path path) throws Exception {
        byte[] data = Files.readAllBytes(path);
        ByteBuffer buf = ByteBuffer.wrap(data).order(ByteOrder.BIG_ENDIAN);

        // First header (44 bytes)
        buf.position(0);
        buf.position(4); // magic
        buf.get();       // version
        buf.position(buf.position() + 15);
        int isutcnt1 = buf.getInt();
        int isstdcnt1 = buf.getInt();
        int leapcnt1 = buf.getInt();
        int timecnt1 = buf.getInt();
        int typecnt1 = buf.getInt();
        int charcnt1 = buf.getInt();

        // Skip first data block
        int blockSize1 = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
        buf.position(buf.position() + blockSize1);

        // Second header (44 bytes)
        buf.position(buf.position() + 4); // magic
        buf.get(); // version
        buf.position(buf.position() + 15);
        int isutcnt = buf.getInt();
        int isstdcnt = buf.getInt();
        int leapcnt = buf.getInt();
        int timecnt = buf.getInt();
        int typecnt = buf.getInt();
        int charcnt = buf.getInt();

        // 64-bit transition times
        long[] transTimes = new long[timecnt];
        for (int i = 0; i < timecnt; i++) transTimes[i] = buf.getLong();

        // Type indices
        int[] transTypeIdx = new int[timecnt];
        for (int i = 0; i < timecnt; i++) transTypeIdx[i] = buf.get() & 0xFF;

        // Type records
        int[] utOffsets = new int[typecnt];
        boolean[] isDsts = new boolean[typecnt];
        int[] abbrIdxs = new int[typecnt];
        for (int i = 0; i < typecnt; i++) {
            utOffsets[i] = buf.getInt();
            isDsts[i] = buf.get() != 0;
            abbrIdxs[i] = buf.get() & 0xFF;
        }

        // Abbreviation characters
        byte[] abbrBytes = new byte[charcnt];
        buf.get(abbrBytes);
        String[] abbrevs = new String[typecnt];
        for (int i = 0; i < typecnt; i++) {
            int start = abbrIdxs[i];
            int end = start;
            while (end < charcnt && abbrBytes[end] != 0) end++;
            abbrevs[i] = new String(abbrBytes, start, end - start);
        }

        // Skip leap second records (8+4=12 bytes each)
        buf.position(buf.position() + leapcnt * 12);
        // Skip isstdcnt + isutcnt bytes
        buf.position(buf.position() + isstdcnt + isutcnt);

        // Footer: \n<posix>\n
        buf.get(); // leading newline
        int footerStart = buf.position();
        int footerEnd = data.length - 1; // trailing newline
        String posixStr = new String(data, footerStart, footerEnd - footerStart);

        TzData tz = new TzData();
        tz.transTimes = transTimes;
        tz.transTypeIdx = transTypeIdx;
        tz.utOffsets = utOffsets;
        tz.isDsts = isDsts;
        tz.abbrevs = abbrevs;
        parsePosix(posixStr, tz);
        tz.lastTransTime = timecnt > 0 ? transTimes[timecnt - 1] : Long.MIN_VALUE;

        return tz;
    }

    static void parsePosix(String s, TzData tz) {
        int pos = 0;

        // std name
        if (pos < s.length() && s.charAt(pos) == '<') {
            int close = s.indexOf('>', pos);
            tz.stdName = s.substring(pos + 1, close);
            pos = close + 1;
        } else {
            int start = pos;
            while (pos < s.length() && Character.isLetter(s.charAt(pos))) pos++;
            tz.stdName = s.substring(start, pos);
        }

        // std offset
        int[] r = parseOffset(s, pos);
        tz.stdOffset = -r[0];
        pos = r[1];

        // check for dst
        if (pos >= s.length()) {
            tz.hasDst = false;
            return;
        }
        char c = s.charAt(pos);
        if (c != '<' && !Character.isLetter(c)) {
            tz.hasDst = false;
            return;
        }

        // dst name
        if (c == '<') {
            int close = s.indexOf('>', pos);
            tz.dstName = s.substring(pos + 1, close);
            pos = close + 1;
        } else {
            int start = pos;
            while (pos < s.length() && Character.isLetter(s.charAt(pos))) pos++;
            tz.dstName = s.substring(start, pos);
        }

        // dst offset (optional)
        if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-' || Character.isDigit(s.charAt(pos)))) {
            r = parseOffset(s, pos);
            tz.dstOffset = -r[0];
            pos = r[1];
        } else {
            tz.dstOffset = tz.stdOffset + 3600;
        }

        tz.hasDst = true;

        // transitions
        if (pos < s.length() && s.charAt(pos) == ',') {
            pos++;
            r = parseRule(s, pos);
            tz.startMonth = r[0]; tz.startWeek = r[1]; tz.startDay = r[2]; tz.startTime = r[3];
            pos = r[4];
            pos++; // skip ','
            r = parseRule(s, pos);
            tz.endMonth = r[0]; tz.endWeek = r[1]; tz.endDay = r[2]; tz.endTime = r[3];
        } else {
            tz.startMonth = 3; tz.startWeek = 2; tz.startDay = 0; tz.startTime = 2 * 3600;
            tz.endMonth = 11; tz.endWeek = 1; tz.endDay = 0; tz.endTime = 2 * 3600;
        }
    }

    static int[] parseOffset(String s, int pos) {
        int sign = 1;
        if (pos < s.length() && s.charAt(pos) == '+') { pos++; }
        else if (pos < s.length() && s.charAt(pos) == '-') { sign = -1; pos++; }

        int hours = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { hours = hours * 10 + (s.charAt(pos) - '0'); pos++; }

        int minutes = 0, seconds = 0;
        if (pos < s.length() && s.charAt(pos) == ':') {
            pos++;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) { minutes = minutes * 10 + (s.charAt(pos) - '0'); pos++; }
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) { seconds = seconds * 10 + (s.charAt(pos) - '0'); pos++; }
            }
        }
        return new int[]{ sign * (hours * 3600 + minutes * 60 + seconds), pos };
    }

    static int[] parseRule(String s, int pos) {
        pos++; // skip 'M'
        int month = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { month = month * 10 + (s.charAt(pos) - '0'); pos++; }
        pos++; // '.'
        int week = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { week = week * 10 + (s.charAt(pos) - '0'); pos++; }
        pos++; // '.'
        int day = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { day = day * 10 + (s.charAt(pos) - '0'); pos++; }

        int time = 2 * 3600;
        if (pos < s.length() && s.charAt(pos) == '/') {
            pos++;
            int[] r = parseOffset(s, pos);
            time = r[0];
            pos = r[1];
        }
        return new int[]{ month, week, day, time, pos };
    }

    static LocalDate findDowInMonth(int year, int month, int week, int dow) {
        // dow: 0=Sun..6=Sat  → Java: 1=Mon..7=Sun
        int jdow = (dow == 0) ? 7 : dow;
        LocalDate first = LocalDate.of(year, month, 1);
        int fdow = first.getDayOfWeek().getValue();
        int diff = (jdow - fdow + 7) % 7;
        int firstOcc = 1 + diff;
        if (week == 5) {
            int lastDay = first.lengthOfMonth();
            int ldow = LocalDate.of(year, month, lastDay).getDayOfWeek().getValue();
            int diff2 = (ldow - jdow + 7) % 7;
            return LocalDate.of(year, month, lastDay - diff2);
        } else {
            return LocalDate.of(year, month, firstOcc + (week - 1) * 7);
        }
    }

    static long footerStartTs(TzData tz, int year) {
        LocalDate d = findDowInMonth(year, tz.startMonth, tz.startWeek, tz.startDay);
        long daySecs = d.toEpochDay() * 86400L;
        return daySecs + tz.startTime - tz.stdOffset;
    }

    static long footerEndTs(TzData tz, int year) {
        LocalDate d = findDowInMonth(year, tz.endMonth, tz.endWeek, tz.endDay);
        long daySecs = d.toEpochDay() * 86400L;
        return daySecs + tz.endTime - tz.dstOffset;
    }

    static boolean isDstFooter(TzData tz, long t) {
        if (!tz.hasDst) return false;
        int year = (int) Instant.ofEpochSecond(t).atZone(ZoneOffset.UTC).getYear();
        long s = footerStartTs(tz, year);
        long e = footerEndTs(tz, year);
        if (s < e) return t >= s && t < e;
        else return t >= s || t < e;
    }

    static int offsetAt(TzData tz, long t) {
        if (tz.transTimes.length == 0) return isDstFooter(tz, t) ? tz.dstOffset : tz.stdOffset;
        if (t < tz.transTimes[0]) return tz.utOffsets[0];
        if (t > tz.lastTransTime) return isDstFooter(tz, t) ? tz.dstOffset : tz.stdOffset;
        int idx = Arrays.binarySearch(tz.transTimes, t);
        if (idx >= 0) return tz.utOffsets[tz.transTypeIdx[idx]];
        idx = -idx - 2;
        return tz.utOffsets[tz.transTypeIdx[idx]];
    }

    static String abbrAt(TzData tz, long t) {
        if (tz.transTimes.length == 0) return isDstFooter(tz, t) ? tz.dstName : tz.stdName;
        if (t < tz.transTimes[0]) return tz.abbrevs[0];
        if (t > tz.lastTransTime) return isDstFooter(tz, t) ? tz.dstName : tz.stdName;
        int idx = Arrays.binarySearch(tz.transTimes, t);
        if (idx >= 0) return tz.abbrevs[tz.transTypeIdx[idx]];
        idx = -idx - 2;
        return tz.abbrevs[tz.transTypeIdx[idx]];
    }

    static String fmtOff(int off) {
        int a = Math.abs(off);
        int h = a / 3600, m = (a % 3600) / 60, s = a % 60;
        String sg = off >= 0 ? "+" : "-";
        if (s != 0) return String.format("%s%02d:%02d:%02d", sg, h, m, s);
        return String.format("%s%02d:%02d", sg, h, m);
    }

    static String fmtLocal(long t, int off) {
        long ls = t + off;
        long day = Math.floorDiv(ls, 86400L);
        long sod = Math.floorMod(ls, 86400L);
        LocalDate d = LocalDate.ofEpochDay(day);
        int h = (int)(sod / 3600), m = (int)((sod % 3600) / 60), s = (int)(sod % 60);
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d", d.getYear(), d.getMonthValue(), d.getDayOfMonth(), h, m, s);
    }

    static String handleUTC(String query, TzData tz, long t) {
        int off = offsetAt(tz, t);
        String ab = abbrAt(tz, t);
        return query + " -> " + fmtLocal(t, off) + fmtOff(off) + " " + ab;
    }

    static String handleLocal(String query, TzData tz, String wcStr) {
        LocalDateTime wall = LocalDateTime.parse(wcStr);
        long wallSecs = wall.toEpochSecond(ZoneOffset.UTC);

        // collect distinct offsets
        Set<Integer> offs = new LinkedHashSet<>();
        for (int o : tz.utOffsets) offs.add(o);
        if (tz.hasDst) { offs.add(tz.stdOffset); offs.add(tz.dstOffset); }

        List<Long> valid = new ArrayList<>();
        for (int o : offs) {
            long t = wallSecs - o;
            if (offsetAt(tz, t) == o) valid.add(t);
        }
        Collections.sort(valid);

        if (valid.size() == 1) {
            long t = valid.get(0);
            int o = offsetAt(tz, t);
            return query + " -> " + t + " " + fmtOff(o) + " " + abbrAt(tz, t);
        } else if (valid.size() >= 2) {
            StringBuilder sb = new StringBuilder();
            sb.append(query).append(" -> ");
            for (int i = 0; i < valid.size(); i++) {
                if (i > 0) sb.append(" | ");
                long t = valid.get(i);
                int o = offsetAt(tz, t);
                sb.append(t).append(" ").append(fmtOff(o)).append(" ").append(abbrAt(tz, t));
            }
            return sb.toString();
        } else {
            // GAP: find the spring-forward transition that skipped this wall time
            List<Long> allT = new ArrayList<>();
            for (long tt : tz.transTimes) allT.add(tt);
            if (tz.hasDst) {
                int wy = wall.getYear();
                for (int y = wy - 2; y <= wy + 2; y++) {
                    long fs = footerStartTs(tz, y);
                    long fe = footerEndTs(tz, y);
                    if (tz.transTimes.length == 0 || fs > tz.lastTransTime) allT.add(fs);
                    if (tz.transTimes.length == 0 || fe > tz.lastTransTime) allT.add(fe);
                }
            }
            Collections.sort(allT);

            long gapT = 0;
            for (long tr : allT) {
                int ob = offsetAt(tz, tr - 1);
                int oa = offsetAt(tz, tr);
                if (oa > ob) {
                    long gs = tr + ob;
                    long ge = tr + oa;
                    if (wallSecs >= gs && wallSecs < ge) {
                        gapT = wallSecs - ob;
                        break;
                    }
                }
            }

            int off = offsetAt(tz, gapT);
            String ab = abbrAt(tz, gapT);
            String loc = fmtLocal(gapT, off);
            return query + " -> GAP " + gapT + " " + loc + " " + ab;
        }
    }
}

import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;

public class Main {

    static class TzData {
        long[] transTimes;
        int[] transTypeIdx;
        int[] utOffsets;
        boolean[] isDsts;
        String[] abbrevs;

        String stdName;
        int stdOffset;
        String dstName;
        int dstOffset;
        boolean hasDst;

        int startMonth, startWeek, startDay;
        int startTime;
        int endMonth, endWeek, endDay;
        int endTime;

        long lastTransTime;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        List<String> lines = Files.readAllLines(Path.of(dir, "queries.txt"));
        Map<String, TzData> cache = new HashMap<>();

        StringBuilder output = new StringBuilder();
        for (String line : lines) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split(" ");
            String type = parts[0];
            String fileName = parts[1];

            TzData tz = cache.computeIfAbsent(fileName, f -> {
                try { return parseTzif(Path.of(dir, f)); }
                catch (Exception e) { throw new RuntimeException(e); }
            });

            if (type.equals("UTC")) {
                long t = Long.parseLong(parts[2]);
                output.append(handleUTC(line, tz, t)).append("\n");
            } else {
                String wallClock = parts[2];
                output.append(handleLocal(line, tz, wallClock)).append("\n");
            }
        }

        System.out.print(output);
    }

    static TzData parseTzif(Path path) throws Exception {
        byte[] data = Files.readAllBytes(path);
        ByteBuffer buf = ByteBuffer.wrap(data).order(ByteOrder.BIG_ENDIAN);

        // First header (44 bytes)
        buf.position(0);
        buf.position(4); // magic
        buf.get();       // version
        buf.position(buf.position() + 15);
        int isutcnt1 = buf.getInt();
        int isstdcnt1 = buf.getInt();
        int leapcnt1 = buf.getInt();
        int timecnt1 = buf.getInt();
        int typecnt1 = buf.getInt();
        int charcnt1 = buf.getInt();

        // Skip first data block
        int blockSize1 = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
        buf.position(buf.position() + blockSize1);

        // Second header (44 bytes)
        buf.position(buf.position() + 4); // magic
        buf.get(); // version
        buf.position(buf.position() + 15);
        int isutcnt = buf.getInt();
        int isstdcnt = buf.getInt();
        int leapcnt = buf.getInt();
        int timecnt = buf.getInt();
        int typecnt = buf.getInt();
        int charcnt = buf.getInt();

        // 64-bit transition times
        long[] transTimes = new long[timecnt];
        for (int i = 0; i < timecnt; i++) transTimes[i] = buf.getLong();

        // Type indices
        int[] transTypeIdx = new int[timecnt];
        for (int i = 0; i < timecnt; i++) transTypeIdx[i] = buf.get() & 0xFF;

        // Type records
        int[] utOffsets = new int[typecnt];
        boolean[] isDsts = new boolean[typecnt];
        int[] abbrIdxs = new int[typecnt];
        for (int i = 0; i < typecnt; i++) {
            utOffsets[i] = buf.getInt();
            isDsts[i] = buf.get() != 0;
            abbrIdxs[i] = buf.get() & 0xFF;
        }

        // Abbreviation characters
        byte[] abbrBytes = new byte[charcnt];
        buf.get(abbrBytes);
        String[] abbrevs = new String[typecnt];
        for (int i = 0; i < typecnt; i++) {
            int start = abbrIdxs[i];
            int end = start;
            while (end < charcnt && abbrBytes[end] != 0) end++;
            abbrevs[i] = new String(abbrBytes, start, end - start);
        }

        // Skip leap second records (8+4=12 bytes each)
        buf.position(buf.position() + leapcnt * 12);
        // Skip isstdcnt + isutcnt bytes
        buf.position(buf.position() + isstdcnt + isutcnt);

        // Footer: \n<posix>\n
        buf.get(); // leading newline
        int footerStart = buf.position();
        int footerEnd = data.length - 1; // trailing newline
        String posixStr = new String(data, footerStart, footerEnd - footerStart);

        TzData tz = new TzData();
        tz.transTimes = transTimes;
        tz.transTypeIdx = transTypeIdx;
        tz.utOffsets = utOffsets;
        tz.isDsts = isDsts;
        tz.abbrevs = abbrevs;
        parsePosix(posixStr, tz);
        tz.lastTransTime = timecnt > 0 ? transTimes[timecnt - 1] : Long.MIN_VALUE;

        return tz;
    }

    static void parsePosix(String s, TzData tz) {
        int pos = 0;

        // std name
        if (pos < s.length() && s.charAt(pos) == '<') {
            int close = s.indexOf('>', pos);
            tz.stdName = s.substring(pos + 1, close);
            pos = close + 1;
        } else {
            int start = pos;
            while (pos < s.length() && Character.isLetter(s.charAt(pos))) pos++;
            tz.stdName = s.substring(start, pos);
        }

        // std offset
        int[] r = parseOffset(s, pos);
        tz.stdOffset = -r[0];
        pos = r[1];

        // check for dst
        if (pos >= s.length()) {
            tz.hasDst = false;
            return;
        }
        char c = s.charAt(pos);
        if (c != '<' && !Character.isLetter(c)) {
            tz.hasDst = false;
            return;
        }

        // dst name
        if (c == '<') {
            int close = s.indexOf('>', pos);
            tz.dstName = s.substring(pos + 1, close);
            pos = close + 1;
        } else {
            int start = pos;
            while (pos < s.length() && Character.isLetter(s.charAt(pos))) pos++;
            tz.dstName = s.substring(start, pos);
        }

        // dst offset (optional)
        if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-' || Character.isDigit(s.charAt(pos)))) {
            r = parseOffset(s, pos);
            tz.dstOffset = -r[0];
            pos = r[1];
        } else {
            tz.dstOffset = tz.stdOffset + 3600;
        }

        tz.hasDst = true;

        // transitions
        if (pos < s.length() && s.charAt(pos) == ',') {
            pos++;
            r = parseRule(s, pos);
            tz.startMonth = r[0]; tz.startWeek = r[1]; tz.startDay = r[2]; tz.startTime = r[3];
            pos = r[4];
            pos++; // skip ','
            r = parseRule(s, pos);
            tz.endMonth = r[0]; tz.endWeek = r[1]; tz.endDay = r[2]; tz.endTime = r[3];
        } else {
            tz.startMonth = 3; tz.startWeek = 2; tz.startDay = 0; tz.startTime = 2 * 3600;
            tz.endMonth = 11; tz.endWeek = 1; tz.endDay = 0; tz.endTime = 2 * 3600;
        }
    }

    static int[] parseOffset(String s, int pos) {
        int sign = 1;
        if (pos < s.length() && s.charAt(pos) == '+') { pos++; }
        else if (pos < s.length() && s.charAt(pos) == '-') { sign = -1; pos++; }

        int hours = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { hours = hours * 10 + (s.charAt(pos) - '0'); pos++; }

        int minutes = 0, seconds = 0;
        if (pos < s.length() && s.charAt(pos) == ':') {
            pos++;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) { minutes = minutes * 10 + (s.charAt(pos) - '0'); pos++; }
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) { seconds = seconds * 10 + (s.charAt(pos) - '0'); pos++; }
            }
        }
        return new int[]{ sign * (hours * 3600 + minutes * 60 + seconds), pos };
    }

    static int[] parseRule(String s, int pos) {
        pos++; // skip 'M'
        int month = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { month = month * 10 + (s.charAt(pos) - '0'); pos++; }
        pos++; // '.'
        int week = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { week = week * 10 + (s.charAt(pos) - '0'); pos++; }
        pos++; // '.'
        int day = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { day = day * 10 + (s.charAt(pos) - '0'); pos++; }

        int time = 2 * 3600;
        if (pos < s.length() && s.charAt(pos) == '/') {
            pos++;
            int[] r = parseOffset(s, pos);
            time = r[0];
            pos = r[1];
        }
        return new int[]{ month, week, day, time, pos };
    }

    static LocalDate findDowInMonth(int year, int month, int week, int dow) {
        // dow: 0=Sun..6=Sat  → Java: 1=Mon..7=Sun
        int jdow = (dow == 0) ? 7 : dow;
        LocalDate first = LocalDate.of(year, month, 1);
        int fdow = first.getDayOfWeek().getValue();
        int diff = (jdow - fdow + 7) % 7;
        int firstOcc = 1 + diff;
        if (week == 5) {
            int lastDay = first.lengthOfMonth();
            int ldow = LocalDate.of(year, month, lastDay).getDayOfWeek().getValue();
            int diff2 = (ldow - jdow + 7) % 7;
            return LocalDate.of(year, month, lastDay - diff2);
        } else {
            return LocalDate.of(year, month, firstOcc + (week - 1) * 7);
        }
    }

    static long footerStartTs(TzData tz, int year) {
        LocalDate d = findDowInMonth(year, tz.startMonth, tz.startWeek, tz.startDay);
        long daySecs = d.toEpochDay() * 86400L;
        return daySecs + tz.startTime - tz.stdOffset;
    }

    static long footerEndTs(TzData tz, int year) {
        LocalDate d = findDowInMonth(year, tz.endMonth, tz.endWeek, tz.endDay);
        long daySecs = d.toEpochDay() * 86400L;
        return daySecs + tz.endTime - tz.dstOffset;
    }

    static boolean isDstFooter(TzData tz, long t) {
        if (!tz.hasDst) return false;
        int year = (int) Instant.ofEpochSecond(t).atZone(ZoneOffset.UTC).getYear();
        long s = footerStartTs(tz, year);
        long e = footerEndTs(tz, year);
        if (s < e) return t >= s && t < e;
        else return t >= s || t < e;
    }

    static int offsetAt(TzData tz, long t) {
        if (tz.transTimes.length == 0) return isDstFooter(tz, t) ? tz.dstOffset : tz.stdOffset;
        if (t < tz.transTimes[0]) return tz.utOffsets[0];
        if (t > tz.lastTransTime) return isDstFooter(tz, t) ? tz.dstOffset : tz.stdOffset;
        int idx = Arrays.binarySearch(tz.transTimes, t);
        if (idx >= 0) return tz.utOffsets[tz.transTypeIdx[idx]];
        idx = -idx - 2;
        return tz.utOffsets[tz.transTypeIdx[idx]];
    }

    static String abbrAt(TzData tz, long t) {
        if (tz.transTimes.length == 0) return isDstFooter(tz, t) ? tz.dstName : tz.stdName;
        if (t < tz.transTimes[0]) return tz.abbrevs[0];
        if (t > tz.lastTransTime) return isDstFooter(tz, t) ? tz.dstName : tz.stdName;
        int idx = Arrays.binarySearch(tz.transTimes, t);
        if (idx >= 0) return tz.abbrevs[tz.transTypeIdx[idx]];
        idx = -idx - 2;
        return tz.abbrevs[tz.transTypeIdx[idx]];
    }

    static String fmtOff(int off) {
        int a = Math.abs(off);
        int h = a / 3600, m = (a % 3600) / 60, s = a % 60;
        String sg = off >= 0 ? "+" : "-";
        if (s != 0) return String.format("%s%02d:%02d:%02d", sg, h, m, s);
        return String.format("%s%02d:%02d", sg, h, m);
    }

    static String fmtLocal(long t, int off) {
        long ls = t + off;
        long day = Math.floorDiv(ls, 86400L);
        long sod = Math.floorMod(ls, 86400L);
        LocalDate d = LocalDate.ofEpochDay(day);
        int h = (int)(sod / 3600), m = (int)((sod % 3600) / 60), s = (int)(sod % 60);
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d", d.getYear(), d.getMonthValue(), d.getDayOfMonth(), h, m, s);
    }

    static String handleUTC(String query, TzData tz, long t) {
        int off = offsetAt(tz, t);
        String ab = abbrAt(tz, t);
        return query + " -> " + fmtLocal(t, off) + fmtOff(off) + " " + ab;
    }

    static String handleLocal(String query, TzData tz, String wcStr) {
        LocalDateTime wall = LocalDateTime.parse(wcStr);
        long wallSecs = wall.toEpochSecond(ZoneOffset.UTC);

        // collect distinct offsets
        Set<Integer> offs = new LinkedHashSet<>();
        for (int o : tz.utOffsets) offs.add(o);
        if (tz.hasDst) { offs.add(tz.stdOffset); offs.add(tz.dstOffset); }

        List<Long> valid = new ArrayList<>();
        for (int o : offs) {
            long t = wallSecs - o;
            if (offsetAt(tz, t) == o) valid.add(t);
        }
        Collections.sort(valid);

        if (valid.size() == 1) {
            long t = valid.get(0);
            int o = offsetAt(tz, t);
            return query + " -> " + t + " " + fmtOff(o) + " " + abbrAt(tz, t);
        } else if (valid.size() >= 2) {
            StringBuilder sb = new StringBuilder();
            sb.append(query).append(" -> ");
            for (int i = 0; i < valid.size(); i++) {
                if (i > 0) sb.append(" | ");
                long t = valid.get(i);
                int o = offsetAt(tz, t);
                sb.append(t).append(" ").append(fmtOff(o)).append(" ").append(abbrAt(tz, t));
            }
            return sb.toString();
        } else {
            // GAP: find the spring-forward transition that skipped this wall time
            List<Long> allT = new ArrayList<>();
            for (long tt : tz.transTimes) allT.add(tt);
            if (tz.hasDst) {
                int wy = wall.getYear();
                for (int y = wy - 2; y <= wy + 2; y++) {
                    long fs = footerStartTs(tz, y);
                    long fe = footerEndTs(tz, y);
                    if (tz.transTimes.length == 0 || fs > tz.lastTransTime) allT.add(fs);
                    if (tz.transTimes.length == 0 || fe > tz.lastTransTime) allT.add(fe);
                }
            }
            Collections.sort(allT);

            long gapT = 0;
            for (long tr : allT) {
                int ob = offsetAt(tz, tr - 1);
                int oa = offsetAt(tz, tr);
                if (oa > ob) {
                    long gs = tr + ob;
                    long ge = tr + oa;
                    if (wallSecs >= gs && wallSecs < ge) {
                        gapT = wallSecs - ob;
                        break;
                    }
                }
            }

            int off = offsetAt(tz, gapT);
            String ab = abbrAt(tz, gapT);
            String loc = fmtLocal(gapT, off) + fmtOff(off);
            return query + " -> GAP " + gapT + " " + loc + " " + ab;
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>

static int32_t rb32(const uint8_t *p){
    return (int32_t)(((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|(uint32_t)p[3]);
}
static int64_t rb64(const uint8_t *p){
    return (int64_t)(((uint64_t)p[0]<<56)|((uint64_t)p[1]<<48)|((uint64_t)p[2]<<40)|((uint64_t)p[3]<<32)|
                     ((uint64_t)p[4]<<24)|((uint64_t)p[5]<<16)|((uint64_t)p[6]<<8)|(uint64_t)p[7]);
}

static int is_leap(int y){return (y%4==0&&y%100!=0)||y%400==0;}
static int dim(int y,int m){
    static const int d[]={0,31,28,31,30,31,30,31,31,30,31,30,31};
    return (m==2&&is_leap(y))?29:d[m];
}
static int64_t days_from_civil(int y,int m,int d){
    y-=m<=2;
    int64_t era=(y>=0?y:y-399)/400;
    unsigned yoe=(unsigned)(y-era*400);
    unsigned doy=(153u*(unsigned)(m+(m>2?-3:9))+2u)/5u+(unsigned)d-1u;
    unsigned doe=yoe*365u+yoe/4u-yoe/100u+doy;
    return era*146097+(int64_t)doe-719468;
}
static void civil_from_days(int64_t z,int *y,int *m,int *d){
    z+=719468;
    int64_t era=(z>=0?z:z-146096)/146097;
    unsigned doe=(unsigned)(z-era*146097);
    unsigned yoe=(doe-doe/1460u+doe/36524u-doe/146096u)/365u;
    int yy=(int)(yoe+era*400);
    unsigned doy=doe-(365u*yoe+yoe/4u-yoe/100u);
    unsigned mp=(5u*doy+2u)/153u;
    *d=(int)(doy-(153u*mp+2u)/5u+1u);
    *m=(int)mp+(mp<10?3:-9);
    *y=yy+(*m<=2?1:0);
}
static void unix_to_civil(int64_t t,int *y,int *m,int *d,int *h,int *mi,int *s){
    int64_t days=t>=0?t/86400:(t-86399)/86400;
    int secs=(int)(t-days*86400);
    civil_from_days(days,y,m,d);
    *h=secs/3600;*mi=(secs%3600)/60;*s=secs%60;
}
static int64_t civil_to_unix(int y,int m,int d,int h,int mi,int s){
    return days_from_civil(y,m,d)*86400+(int64_t)h*3600+(int64_t)mi*60+s;
}
static int dow_of(int y,int m,int d){
    int64_t z=days_from_civil(y,m,d);
    int dw=(int)((z+4)%7);
    if(dw<0)dw+=7;
    return dw;
}

typedef struct{int32_t off;uint8_t isdst;char abbr[64];}LTT;
typedef struct{int64_t time;uint8_t type_idx;}Trans;
typedef struct{
    char std_name[64],dst_name[64];
    int32_t std_off,dst_off;
    int has_dst,has_rules;
    int sm,sw,sd,sh,smi,ss;
    int em,ew,ed,eh,emi,es;
}PosixTZ;
typedef struct{
    int timecnt,typecnt;
    Trans *trans;
    LTT *types;
    PosixTZ posix;
    int has_posix;
}TZData;
typedef struct{int32_t off;char abbr[64];}TI;

static const char*p_name(const char*s,char*out,int max){
    int i=0;
    if(*s=='<'){s++;while(*s&&*s!='>'&&i<max-1)out[i++]=*s++;if(*s=='>')s++;}
    else{while(isalpha((unsigned char)*s)&&i<max-1)out[i++]=*s++;}
    out[i]='\0';return s;
}
static const char*p_off(const char*s,int32_t*out){
    int sg=1;if(*s=='+'||*s=='-'){if(*s=='-')sg=-1;s++;}
    int hh=0,mm=0,ss=0;
    while(isdigit((unsigned char)*s)){hh=hh*10+(*s++-'0');}
    if(*s==':'){s++;while(isdigit((unsigned char)*s)){mm=mm*10+(*s++-'0');}}
    if(*s==':'){s++;while(isdigit((unsigned char)*s)){ss=ss*10+(*s++-'0');}}
    *out=sg*(hh*3600+mm*60+ss);return s;
}
static const char*p_time(const char*s,int*h,int*m,int*sec){
    int sg=1;if(*s=='+'||*s=='-'){if(*s=='-')sg=-1;s++;}
    *h=0;*m=0;*sec=0;
    while(isdigit((unsigned char)*s)){*h=*h*10+(*s++-'0');}
    if(*s==':'){s++;while(isdigit((unsigned char)*s)){*m=*m*10+(*s++-'0');}}
    if(*s==':'){s++;while(isdigit((unsigned char)*s)){*sec=*sec*10+(*s++-'0');}}
    *h*=sg;*m*=sg;*sec*=sg;return s;
}
static const char*p_mwd(const char*s,int*mo,int*w,int*d){
    if(*s=='M')s++;
    *mo=0;while(isdigit((unsigned char)*s)){*mo=*mo*10+(*s++-'0');}
    if(*s=='.')s++;
    *w=0;while(isdigit((unsigned char)*s)){*w=*w*10+(*s++-'0');}
    if(*s=='.')s++;
    *d=0;while(isdigit((unsigned char)*s)){*d=*d*10+(*s++-'0');}
    return s;
}
static int parse_posix(const char*str,PosixTZ*p){
    memset(p,0,sizeof(*p));
    p->sh=2;p->smi=0;p->ss=0;p->eh=2;p->emi=0;p->es=0;
    const char*s=str;
    s=p_name(s,p->std_name,64);
    if(strlen(p->std_name)<3)return -1;
    int32_t raw;
    s=p_off(s,&raw);p->std_off=-raw;
    if(*s&&(*s=='<'||isalpha((unsigned char)*s))){
        p->has_dst=1;
        s=p_name(s,p->dst_name,64);
        if(*s=='+'||*s=='-'){s=p_off(s,&raw);p->dst_off=-raw;}
        else p->dst_off=p->std_off+3600;
    }
    if(*s==','){
        s++;p->has_rules=1;
        s=p_mwd(s,&p->sm,&p->sw,&p->sd);
        if(*s=='/'){s++;s=p_time(s,&p->sh,&p->smi,&p->ss);}
        if(*s==',')s++;
        s=p_mwd(s,&p->em,&p->ew,&p->ed);
        if(*s=='/'){s++;s=p_time(s,&p->eh,&p->emi,&p->es);}
    }
    return 0;
}

static int mwd_day(int y,int mo,int w,int d){
    int fd=dow_of(y,mo,1);
    int fo=1+(d-fd+7)%7;
    if(w==5){int day=fo+28;if(day>dim(y,mo))day-=7;return day;}
    return fo+7*(w-1);
}
static int64_t posix_start(int y,PosixTZ*p){
    int day=mwd_day(y,p->sm,p->sw,p->sd);
    return civil_to_unix(y,p->sm,day,p->sh,p->smi,p->ss)-p->std_off;
}
static int64_t posix_end(int y,PosixTZ*p){
    int day=mwd_day(y,p->em,p->ew,p->ed);
    return civil_to_unix(y,p->em,day,p->eh,p->emi,p->es)-p->dst_off;
}
static int posix_is_dst(int64_t t,PosixTZ*p){
    if(!p->has_dst||!p->has_rules)return 0;
    int64_t days=t>=0?t/86400:(t-86399)/86400;
    int y,m,d;civil_from_days(days,&y,&m,&d);
    int64_t ts=posix_start(y,p),te=posix_end(y,p);
    if(ts<=te)return(t>=ts&&t<te)?1:0;
    return(t>=ts||t<te)?1:0;
}

static TI type_at(int64_t t,TZData*tz){
    TI ti;
    if(tz->timecnt==0){
        if(tz->has_posix&&posix_is_dst(t,&tz->posix)){ti.off=tz->posix.dst_off;strcpy(ti.abbr,tz->posix.dst_name);}
        else if(tz->has_posix){ti.off=tz->posix.std_off;strcpy(ti.abbr,tz->posix.std_name);}
        else{ti.off=tz->types[0].off;strcpy(ti.abbr,tz->types[0].abbr);}
        return ti;
    }
    if(t<tz->trans[0].time){ti.off=tz->types[0].off;strcpy(ti.abbr,tz->types[0].abbr);return ti;}
    if(t>tz->trans[tz->timecnt-1].time){
        if(tz->has_posix&&posix_is_dst(t,&tz->posix)){ti.off=tz->posix.dst_off;strcpy(ti.abbr,tz->posix.dst_name);}
        else if(tz->has_posix){ti.off=tz->posix.std_off;strcpy(ti.abbr,tz->posix.std_name);}
        else{ti.off=tz->types[0].off;strcpy(ti.abbr,tz->types[0].abbr);}
        return ti;
    }
    int lo=0,hi=tz->timecnt-1;
    while(lo<hi){int mid=(lo+hi+1)/2;if(tz->trans[mid].time<=t)lo=mid;else hi=mid-1;}
    int idx=tz->trans[lo].type_idx;
    ti.off=tz->types[idx].off;strcpy(ti.abbr,tz->types[idx].abbr);
    return ti;
}

static int parse_tzif(const char*path,TZData*tz){
    FILE*f=fopen(path,"rb");if(!f)return -1;
    fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
    uint8_t*buf=malloc(sz);fread(buf,1,sz,f);fclose(f);
    if(sz<44||memcmp(buf,"TZif",4)!=0){free(buf);return -1;}
    int iu1=rb32(buf+20),is1=rb32(buf+24),lp1=rb32(buf+28),tc1=rb32(buf+32),ty1=rb32(buf+36),ch1=rb32(buf+40);
    int pos=44+tc1*4+tc1+ty1*6+ch1+lp1*8+is1+iu1;
    if(pos+44>sz||memcmp(buf+pos,"TZif",4)!=0){free(buf);return -1;}
    int iu2=rb32(buf+pos+20),is2=rb32(buf+pos+24),lp2=rb32(buf+pos+28),tc2=rb32(buf+pos+32),ty2=rb32(buf+pos+36),ch2=rb32(buf+pos+40);
    pos+=44;
    tz->timecnt=tc2;tz->typecnt=ty2;
    tz->trans=(Trans*)malloc((tc2?tc2:1)*sizeof(Trans));
    for(int i=0;i<tc2;i++){tz->trans[i].time=rb64(buf+pos);pos+=8;}
    for(int i=0;i<tc2;i++){tz->trans[i].type_idx=buf[pos++];}
    tz->types=(LTT*)malloc((ty2?ty2:1)*sizeof(LTT));
    int aidx[256];
    for(int i=0;i<ty2;i++){
        tz->types[i].off=rb32(buf+pos);pos+=4;
        tz->types[i].isdst=buf[pos++];
        aidx[i]=buf[pos++];
    }
    char*ab=(char*)malloc(ch2+1);memcpy(ab,buf+pos,ch2);ab[ch2]='\0';pos+=ch2;
    for(int i=0;i<ty2;i++){
        if(aidx[i]>=0&&aidx[i]<ch2)strcpy(tz->types[i].abbr,ab+aidx[i]);
        else tz->types[i].abbr[0]='\0';
    }
    free(ab);
    pos+=lp2*12+is2+iu2;
    if(pos<sz&&buf[pos]=='\n')pos++;
    int fs=pos;while(pos<sz&&buf[pos]!='\n')pos++;
    int fl=pos-fs;
    tz->has_posix=(fl>0);
    if(fl>0){char*ps=(char*)malloc(fl+1);memcpy(ps,buf+fs,fl);ps[fl]='\0';parse_posix(ps,&tz->posix);free(ps);}
    free(buf);
    return 0;
}

static void print_off(int32_t off){
    char sg=off>=0?'+':'-';int a=off<0?-off:off;
    int h=a/3600,m=(a%3600)/60,s=a%60;
    if(s)printf("%c%02d:%02d:%02d",sg,h,m,s);
    else printf("%c%02d:%02d",sg,h,m);
}

static int find_gap(int64_t W,TZData*tz,int32_t*res){
    for(int i=0;i<tz->timecnt;i++){
        int32_t bo,ao;
        if(i==0)bo=tz->types[0].off;else bo=tz->types[tz->trans[i-1].type_idx].off;
        ao=tz->types[tz->trans[i].type_idx].off;
        if(ao>bo){int64_t gs=tz->trans[i].time+bo,ge=tz->trans[i].time+ao;
            if(W>=gs&&W<ge){*res=bo;return 1;}}
    }
    if(tz->timecnt>0&&tz->has_posix){
        int64_t tl=tz->trans[tz->timecnt-1].time;
        int32_t ol=tz->types[tz->trans[tz->timecnt-1].type_idx].off;
        TI ti=type_at(tl+1,tz);
        if(ti.off>ol){int64_t gs=tl+ol,ge=tl+1+ti.off;
            if(W>=gs&&W<ge){*res=ol;return 1;}}
    }
    if(tz->has_posix&&tz->posix.has_dst&&tz->posix.has_rules&&tz->posix.dst_off>tz->posix.std_off){
        int64_t days=W>=0?W/86400:(W-86399)/86400;
        int y,m,d;civil_from_days(days,&y,&m,&d);
        for(int yr=y-1;yr<=y+1;yr++){
            int64_t ts=posix_start(yr,&tz->posix);
            if(tz->timecnt>0&&ts<=tz->trans[tz->timecnt-1].time)continue;
            int64_t gs=ts+tz->posix.std_off,ge=ts+tz->posix.dst_off;
            if(W>=gs&&W<ge){*res=tz->posix.std_off;return 1;}
        }
    }
    return 0;
}

#define MAXC 256
static struct{char fn[512];TZData tz;}cache[MAXC];
static int cn=0;
static TZData*get_tz(const char*fn){
    for(int i=0;i<cn;i++)if(strcmp(cache[i].fn,fn)==0)return &cache[i].tz;
    if(cn>=MAXC)return NULL;
    strcpy(cache[cn].fn,fn);
    if(parse_tzif(fn,&cache[cn].tz)!=0)return NULL;
    return &cache[cn++].tz;
}

int main(int argc,char*argv[]){
    if(argc<2)return 1;
    char qp[512];snprintf(qp,sizeof(qp),"%s/queries.txt",argv[1]);
    FILE*qf=fopen(qp,"r");if(!qf)return 1;
    char line[1024];
    while(fgets(line,sizeof(line),qf)){
        int len=strlen(line);
        while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r'))line[--len]='\0';
        if(len==0)continue;
        char cmd[16],fn[256],val[256];
        sscanf(line,"%s %s %s",cmd,fn,val);
        char fp[512];snprintf(fp,sizeof(fp),"%s/%s",argv[1],fn);
        TZData*tz=get_tz(fp);if(!tz)continue;
        if(strcmp(cmd,"UTC")==0){
            int64_t t=strtoll(val,NULL,10);
            TI ti=type_at(t,tz);
            int64_t loc=t+ti.off;
            int y,m,d,h,mi,s;unix_to_civil(loc,&y,&m,&d,&h,&mi,&s);
            printf("%s -> %04d-%02d-%02dT%02d:%02d:%02d",line,y,m,d,h,mi,s);
            print_off(ti.off);
            printf(" %s\n",ti.abbr);
        } else {
            int y,m,d,h,mi,s;
            sscanf(val,"%d-%d-%dT%d:%d:%d",&y,&m,&d,&h,&mi,&s);
            int64_t W=civil_to_unix(y,m,d,h,mi,s);
            int32_t offs[512];int no=0;
            for(int i=0;i<tz->typecnt&&no<512;i++)offs[no++]=tz->types[i].off;
            if(tz->has_posix){offs[no++]=tz->posix.std_off;if(tz->posix.has_dst)offs[no++]=tz->posix.dst_off;}
            int64_t rt[4];int32_t ro[4];char ra[4][64];int nr=0;
            for(int i=0;i<no;i++){
                int64_t tc=W-offs[i];
                TI ti=type_at(tc,tz);
                if(ti.off==offs[i]){
                    int dup=0;for(int j=0;j<nr;j++)if(rt[j]==tc){dup=1;break;}
                    if(!dup&&nr<4){rt[nr]=tc;ro[nr]=ti.off;strcpy(ra[nr],ti.abbr);nr++;}
                }
            }
            for(int i=0;i<nr-1;i++)for(int j=i+1;j<nr;j++)if(rt[j]<rt[i]){
                int64_t t0=rt[i];rt[i]=rt[j];rt[j]=t0;
                int32_t o0=ro[i];ro[i]=ro[j];ro[j]=o0;
                char a0[64];strcpy(a0,ra[i]);strcpy(ra[i],ra[j]);strcpy(ra[j],a0);
            }
            if(nr==1){
                printf("%s -> %lld ",line,(long long)rt[0]);print_off(ro[0]);printf(" %s\n",ra[0]);
            }else if(nr==2){
                printf("%s -> %lld ",line,(long long)rt[0]);print_off(ro[0]);printf(" %s | %lld ",ra[0],(long long)rt[1]);print_off(ro[1]);printf(" %s\n",ra[1]);
            }else{
                int32_t bo=0;find_gap(W,tz,&bo);
                int64_t tg=W-bo;
                TI ti=type_at(tg,tz);
                int64_t loc=tg+ti.off;
                int ly,lm,ld,lh,lmi,ls;unix_to_civil(loc,&ly,&lm,&ld,&lh,&lmi,&ls);
                printf("%s -> GAP %lld %04d-%02d-%02dT%02d:%02d:%02d",line,(long long)tg,ly,lm,ld,lh,lmi,ls);
                print_off(ti.off);printf(" %s\n",ti.abbr);
            }
        }
    }
    fclose(qf);
    return 0;
}

import Foundation

// === Big-endian reading ===
func readBE32(_ d: [UInt8], _ p: Int) -> Int {
    return Int(Int32(bitPattern: UInt32(d[p]) << 24 | UInt32(d[p+1]) << 16 | UInt32(d[p+2]) << 8 | UInt32(d[p+3])))
}

func readBE64(_ d: [UInt8], _ p: Int) -> Int {
    let hi = Int(Int32(bitPattern: UInt32(d[p]) << 24 | UInt32(d[p+1]) << 16 | UInt32(d[p+2]) << 8 | UInt32(d[p+3])))
    let lo = Int(UInt32(d[p+4]) << 24 | UInt32(d[p+5]) << 16 | UInt32(d[p+6]) << 8 | UInt32(d[p+7]))
    return hi << 32 | lo
}

// === Date utilities ===
func floorDiv(_ a: Int, _ b: Int) -> Int {
    let q = a / b
    let r = a % b
    if (r != 0) && ((r > 0) != (b > 0)) { return q - 1 }
    return q
}

func daysFromCivil(_ year: Int, _ month: Int, _ day: Int) -> Int {
    var y = year
    if month <= 2 { y -= 1 }
    let era = (y >= 0 ? y : y - 399) / 400
    let yoe = y - era * 400
    let mp = month + (month > 2 ? -3 : 9)
    let doy = (153 * mp + 2) / 5 + day - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    return era * 146097 + doe - 719468
}

func civilFromDays(_ z: Int) -> (year: Int, month: Int, day: Int) {
    var z2 = z + 719468
    let era = (z2 >= 0 ? z2 : z2 - 146096) / 146097
    let doe = z2 - era * 146097
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365
    let y = yoe + era * 400
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100)
    let mp = (5 * doy + 2) / 153
    let d = doy - (153 * mp + 2) / 5 + 1
    let m = mp + (mp < 10 ? 3 : -9)
    return (year: y + (m <= 2 ? 1 : 0), month: m, day: d)
}

func unixToUtc(_ t: Int) -> (Int, Int, Int, Int, Int, Int) {
    let days = floorDiv(t, 86400)
    let rem = t - days * 86400
    let c = civilFromDays(days)
    return (c.year, c.month, c.day, rem / 3600, (rem % 3600) / 60, rem % 60)
}

func utcToUnix(_ y: Int, _ m: Int, _ d: Int, _ h: Int, _ mi: Int, _ s: Int) -> Int {
    return daysFromCivil(y, m, d) * 86400 + h * 3600 + mi * 60 + s
}

func daysInMonth(_ year: Int, _ month: Int) -> Int {
    if month == 2 {
        if (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0) { return 29 }
        return 28
    }
    let table = [31,28,31,30,31,30,31,31,30,31,30,31]
    return table[month - 1]
}

func dayOfWeek(_ year: Int, _ month: Int, _ day: Int) -> Int {
    let d = daysFromCivil(year, month, day)
    var dow = (d + 4) % 7
    if dow < 0 { dow += 7 }
    return dow
}

func mwdToDay(_ year: Int, _ month: Int, _ week: Int, _ day: Int) -> Int {
    let firstDow = dayOfWeek(year, month, 1)
    let firstOcc = 1 + ((day - firstDow + 7) % 7)
    var result = firstOcc + (week - 1) * 7
    if week == 5 {
        let dim = daysInMonth(year, month)
        if result > dim { result -= 7 }
    }
    return result
}

// === Structures ===
struct LocalTimeType {
    var utcOffset: Int
    var isDst: Bool
    var abbr: String
}

struct Transition {
    var time: Int
    var typeIndex: Int
}

struct PosixRule {
    var stdAbbr: String
    var stdUtcOffset: Int
    var dstAbbr: String?
    var dstUtcOffset: Int?
    var startMonth: Int?
    var startWeek: Int?
    var startDay: Int?
    var startTime: Int
    var endMonth: Int?
    var endWeek: Int?
    var endDay: Int?
    var endTime: Int
}

struct TzFile {
    var transitions: [Transition]
    var types: [LocalTimeType]
    var posixRule: PosixRule?
}

// === POSIX TZ string parsing ===
func parsePosixRule(_ str: String) -> PosixRule? {
    let chars = Array(str)
    var pos = 0

    func isAlpha(_ c: Character) -> Bool { c.isLetter }
    func isDigit(_ c: Character) -> Bool { c.isNumber }

    func parseName() -> String? {
        if pos < chars.count && chars[pos] == "<" {
            let saved = pos
            pos += 1
            var name = ""
            while pos < chars.count && chars[pos] != ">" {
                name.append(chars[pos])
                pos += 1
            }
            if pos < chars.count { pos += 1 }
            return name
        } else if pos < chars.count && isAlpha(chars[pos]) {
            let saved = pos
            var name = ""
            while pos < chars.count && isAlpha(chars[pos]) {
                name.append(chars[pos])
                pos += 1
            }
            if name.count >= 3 { return name }
            pos = saved
            return nil
        }
        return nil
    }

    func parseOffset() -> Int? {
        let saved = pos
        var sign = 1
        if pos < chars.count && (chars[pos] == "+" || chars[pos] == "-") {
            if chars[pos] == "-" { sign = -1 }
            pos += 1
        }
        guard pos < chars.count && isDigit(chars[pos]) else { pos = saved; return nil }
        var h = 0
        while pos < chars.count && isDigit(chars[pos]) {
            h = h * 10 + Int(chars[pos].asciiValue! - 48)
            pos += 1
        }
        var m = 0, s = 0
        if pos < chars.count && chars[pos] == ":" {
            pos += 1
            while pos < chars.count && isDigit(chars[pos]) {
                m = m * 10 + Int(chars[pos].asciiValue! - 48)
                pos += 1
            }
            if pos < chars.count && chars[pos] == ":" {
                pos += 1
                while pos < chars.count && isDigit(chars[pos]) {
                    s = s * 10 + Int(chars[pos].asciiValue! - 48)
                    pos += 1
                }
            }
        }
        return sign * (h * 3600 + m * 60 + s)
    }

    func parseMWD() -> (Int, Int, Int)? {
        guard pos < chars.count && chars[pos] == "M" else { return nil }
        pos += 1
        guard pos < chars.count && isDigit(chars[pos]) else { return nil }
        var m = 0
        while pos < chars.count && isDigit(chars[pos]) {
            m = m * 10 + Int(chars[pos].asciiValue! - 48)
            pos += 1
        }
        guard pos < chars.count && chars[pos] == "." else { return nil }
        pos += 1
        var w = 0
        while pos < chars.count && isDigit(chars[pos]) {
            w = w * 10 + Int(chars[pos].asciiValue! - 48)
            pos += 1
        }
        guard pos < chars.count && chars[pos] == "." else { return nil }
        pos += 1
        var d = 0
        while pos < chars.count && isDigit(chars[pos]) {
            d = d * 10 + Int(chars[pos].asciiValue! - 48)
            pos += 1
        }
        return (m, w, d)
    }

    // Parse std name
    guard let stdName = parseName() else { return nil }
    // Parse std offset
    guard let stdPosixOff = parseOffset() else { return nil }
    let stdUtcOff = -stdPosixOff

    // Try DST name
    var dstAbbr: String? = nil
    var dstUtcOff: Int? = nil
    let savedPos = pos
    if let dn = parseName() {
        dstAbbr = dn
        if let dpo = parseOffset() {
            dstUtcOff = -dpo
        } else {
            dstUtcOff = stdUtcOff + 3600
        }
    } else {
        pos = savedPos
    }

    // Parse rules
    var startMonth: Int? = nil, startWeek: Int? = nil, startDay: Int? = nil
    var startTime = 2 * 3600
    var endMonth: Int? = nil, endWeek: Int? = nil, endDay: Int? = nil
    var endTime = 2 * 3600

    if pos < chars.count && chars[pos] == "," {
        pos += 1
        guard let (sm, sw, sd) = parseMWD() else { return nil }
        startMonth = sm; startWeek = sw; startDay = sd
        if pos < chars.count && chars[pos] == "/" {
            pos += 1
            if let t = parseOffset() { startTime = t }
        }
        if pos < chars.count && chars[pos] == "," {
            pos += 1
            guard let (em, ew, ed) = parseMWD() else { return nil }
            endMonth = em; endWeek = ew; endDay = ed
            if pos < chars.count && chars[pos] == "/" {
                pos += 1
                if let t = parseOffset() { endTime = t }
            }
        }
    }

    return PosixRule(stdAbbr: stdName, stdUtcOffset: stdUtcOff,
                     dstAbbr: dstAbbr, dstUtcOffset: dstUtcOff,
                     startMonth: startMonth, startWeek: startWeek, startDay: startDay,
                     startTime: startTime,
                     endMonth: endMonth, endWeek: endWeek, endDay: endDay,
                     endTime: endTime)
}

// === TZif parsing ===
func parseTzif(_ data: [UInt8]) -> TzFile {
    var p = 0
    // First header: magic(4) + version(1) + unused(15) + 6*int32 = 44
    p = 20
    let isutcnt1 = readBE32(data, p); p += 4
    let isstdcnt1 = readBE32(data, p); p += 4
    let leapcnt1 = readBE32(data, p); p += 4
    let timecnt1 = readBE32(data, p); p += 4
    let typecnt1 = readBE32(data, p); p += 4
    let charcnt1 = readBE32(data, p); p += 4

    // Skip data block 1
    let block1Size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1
    p += block1Size

    // Second header
    p += 20
    let isutcnt = readBE32(data, p); p += 4
    let isstdcnt = readBE32(data, p); p += 4
    let leapcnt = readBE32(data, p); p += 4
    let timecnt = readBE32(data, p); p += 4
    let typecnt = readBE32(data, p); p += 4
    let charcnt = readBE32(data, p); p += 4

    // Transition times (64-bit)
    var transTimes = [Int]()
    for _ in 0..<timecnt {
        transTimes.append(readBE64(data, p))
        p += 8
    }

    // Type indices
    var transTypeIdx = [Int]()
    for _ in 0..<timecnt {
        transTypeIdx.append(Int(data[p]))
        p += 1
    }

    // Type records
    var typeRecs: [(off: Int, isdst: Bool, abbrIdx: Int)] = []
    for _ in 0..<typecnt {
        let off = readBE32(data, p); p += 4
        let isdst = data[p] != 0; p += 1
        let abbrIdx = Int(data[p]); p += 1
        typeRecs.append((off, isdst, abbrIdx))
    }

    // Abbreviation characters
    let abbrChars = Array(data[p..<p+charcnt])
    p += charcnt

    // Skip leap seconds, isstd, isut
    p += leapcnt * 12 + isstdcnt + isutcnt

    // Footer
    if p < data.count && data[p] == 10 { p += 1 }
    var tzStrBytes = [UInt8]()
    while p < data.count && data[p] != 10 {
        tzStrBytes.append(data[p])
        p += 1
    }
    let tzStr = String(bytes: tzStrBytes, encoding: .ascii) ?? ""

    // Build types
    var types = [LocalTimeType]()
    for i in 0..<typecnt {
        var abbr = ""
        var j = typeRecs[i].abbrIdx
        while j < abbrChars.count && abbrChars[j] != 0 {
            abbr.append(Character(UnicodeScalar(abbrChars[j])))
            j += 1
        }
        types.append(LocalTimeType(utcOffset: typeRecs[i].off, isDst: typeRecs[i].isdst, abbr: abbr))
    }

    // Build transitions
    var transitions = [Transition]()
    for i in 0..<timecnt {
        transitions.append(Transition(time: transTimes[i], typeIndex: transTypeIdx[i]))
    }

    var posixRule: PosixRule? = nil
    if !tzStr.isEmpty {
        posixRule = parsePosixRule(tzStr)
    }

    return TzFile(transitions: transitions, types: types, posixRule: posixRule)
}

// === Time zone operations ===
func dstStartTime(year: Int, rule: PosixRule) -> Int {
    guard let m = rule.startMonth, let w = rule.startWeek, let d = rule.startDay else {
        return Int.max / 2
    }
    let day = mwdToDay(year, m, w, d)
    let localSec = utcToUnix(year, m, day, 0, 0, 0) + rule.startTime
    return localSec - rule.stdUtcOffset
}

func dstEndTime(year: Int, rule: PosixRule) -> Int {
    guard let m = rule.endMonth, let w = rule.endWeek, let d = rule.endDay else {
        return Int.max / 2
    }
    guard let dstOff = rule.dstUtcOffset else { return Int.max / 2 }
    let day = mwdToDay(year, m, w, d)
    let localSec = utcToUnix(year, m, day, 0, 0, 0) + rule.endTime
    return localSec - dstOff
}

func getTypeFromRule(t: Int, rule: PosixRule) -> LocalTimeType {
    guard let dstAbbr = rule.dstAbbr, let dstOff = rule.dstUtcOffset,
          rule.startMonth != nil else {
        return LocalTimeType(utcOffset: rule.stdUtcOffset, isDst: false, abbr: rule.stdAbbr)
    }

    let (year, _, _, _, _, _) = unixToUtc(t)

    for y in [year - 1, year, year + 1] {
        let startT = dstStartTime(year: y, rule: rule)
        let endT = dstEndTime(year: y, rule: rule)

        if startT < endT {
            if t >= startT && t < endT {
                return LocalTimeType(utcOffset: dstOff, isDst: true, abbr: dstAbbr)
            }
        } else if startT > endT {
            let endNext = dstEndTime(year: y + 1, rule: rule)
            if t >= startT && t < endNext {
                return LocalTimeType(utcOffset: dstOff, isDst: true, abbr: dstAbbr)
            }
        }
    }

    return LocalTimeType(utcOffset: rule.stdUtcOffset, isDst: false, abbr: rule.stdAbbr)
}

func getTypeAtTime(_ t: Int, tz: TzFile) -> LocalTimeType {
    if tz.transitions.isEmpty {
        if let rule = tz.posixRule {
            return getTypeFromRule(t: t, rule: rule)
        }
        if !tz.types.isEmpty { return tz.types[0] }
        return LocalTimeType(utcOffset: 0, isDst: false, abbr: "")
    }

    let firstTime = tz.transitions[0].time
    let lastTime = tz.transitions[tz.transitions.count - 1].time

    if t < firstTime {
        return tz.types[0]
    }

    if t > lastTime {
        if let rule = tz.posixRule {
            return getTypeFromRule(t: t, rule: rule)
        }
        return tz.types[tz.transitions[tz.transitions.count - 1].typeIndex]
    }

    // Binary search for latest transition <= t
    var lo = 0, hi = tz.transitions.count - 1
    while lo < hi {
        let mid = (lo + hi + 1) / 2
        if tz.transitions[mid].time <= t {
            lo = mid
        } else {
            hi = mid - 1
        }
    }
    return tz.types[tz.transitions[lo].typeIndex]
}

// === Output formatting ===
func formatOffset(_ offset: Int) -> String {
    let sign = offset >= 0 ? "+" : "-"
    let absOff = abs(offset)
    let h = absOff / 3600
    let m = (absOff % 3600) / 60
    let s = absOff % 60
    if s != 0 {
        return String(format: "%@%02d:%02d:%02d", sign, h, m, s)
    } else {
        return String(format: "%@%02d:%02d", sign, h, m)
    }
}

func formatLocalDateTime(t: Int, offset: Int) -> String {
    let localSec = t + offset
    let (y, m, d, h, mi, s) = unixToUtc(localSec)
    return String(format: "%04d-%02d-%02dT%02d:%02d:%02d", y, m, d, h, mi, s) + formatOffset(offset)
}

// === Main ===
let dir = CommandLine.arguments[1]
let queriesPath = dir + "/queries.txt"
let queriesContent = try! String(contentsOfFile: queriesPath, encoding: .ascii)

var tzCache = [String: TzFile]()

func getTz(_ name: String) -> TzFile? {
    if let cached = tzCache[name] { return cached }
    let path = dir + "/" + name
    guard let data = FileManager.default.contents(atPath: path) else { return nil }
    let tz = parseTzif(Array(data))
    tzCache[name] = tz
    return tz
}

for line in queriesContent.components(separatedBy: "\n") {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }

    let fields = trimmed.components(separatedBy: " ")
    let queryType = fields[0]
    let fileName = fields[1]

    guard let tz = getTz(fileName) else { continue }

    if queryType == "UTC" {
        let t = Int(fields[2])!
        let tp = getTypeAtTime(t, tz: tz)
        let localStr = formatLocalDateTime(t: t, offset: tp.utcOffset)
        print("\(trimmed) -> \(localStr) \(tp.abbr)")

    } else if queryType == "LOCAL" {
        let wallClock = fields[2]
        let wcParts = wallClock.components(separatedBy: "T")
        let dateParts = wcParts[0].components(separatedBy: "-")
        let timeParts = wcParts[1].components(separatedBy: ":")
        let wYear = Int(dateParts[0])!
        let wMonth = Int(dateParts[1])!
        let wDay = Int(dateParts[2])!
        let wHour = Int(timeParts[0])!
        let wMin = Int(timeParts[1])!
        let wSec = Int(timeParts[2])!
        let wSeconds = utcToUnix(wYear, wMonth, wDay, wHour, wMin, wSec)

        // Collect all unique UTC offsets
        var offsets = Set<Int>()
        for tp in tz.types { offsets.insert(tp.utcOffset) }
        if let rule = tz.posixRule {
            offsets.insert(rule.stdUtcOffset)
            if let doff = rule.dstUtcOffset { offsets.insert(doff) }
        }

        // For each offset, compute candidate t and check validity
        var solutions: [(t: Int, type: LocalTimeType)] = []
        for off in offsets {
            let t = wSeconds - off
            let actual = getTypeAtTime(t, tz: tz)
            if actual.utcOffset == off {
                solutions.append((t: t, type: actual))
            }
        }

        solutions.sort { $0.t < $1.t }

        if solutions.count == 1 {
            let sol = solutions[0]
            print("\(trimmed) -> \(sol.t) \(formatOffset(sol.type.utcOffset)) \(sol.type.abbr)")
        } else if solutions.count >= 2 {
            // Take first two (there should be exactly 2 for an overlap)
            let s1 = solutions[0], s2 = solutions[1]
            print("\(trimmed) -> \(s1.t) \(formatOffset(s1.type.utcOffset)) \(s1.type.abbr) | \(s2.t) \(formatOffset(s2.type.utcOffset)) \(s2.type.abbr)")
        } else {
            // GAP: find the spring-forward transition that skips this wall-clock time
            var gapFound = false
            var gapT = 0
            var gapType = LocalTimeType(utcOffset: 0, isDst: false, abbr: "")

            // Collect all transitions (file + footer) near wSeconds
            var allTrans: [(time: Int, oldType: LocalTimeType, newType: LocalTimeType)] = []

            // File transitions
            for i in 0..<tz.transitions.count {
                let tr = tz.transitions[i]
                let newType = tz.types[tr.typeIndex]
                let oldType: LocalTimeType
                if i == 0 {
                    oldType = tz.types[0]
                } else {
                    oldType = tz.types[tz.transitions[i - 1].typeIndex]
                }
                allTrans.append((time: tr.time, oldType: oldType, newType: newType))
            }

            // Footer transitions
            if let rule = tz.posixRule, rule.startMonth != nil, let dstOff = rule.dstUtcOffset {
                let (year, _, _, _, _, _) = unixToUtc(wSeconds)
                let stdType = LocalTimeType(utcOffset: rule.stdUtcOffset, isDst: false, abbr: rule.stdAbbr)
                let dstType = LocalTimeType(utcOffset: dstOff, isDst: true, abbr: rule.dstAbbr ?? "")
                for y in [year - 1, year, year + 1] {
                    let sT = dstStartTime(year: y, rule: rule)
                    let eT = dstEndTime(year: y, rule: rule)
                    allTrans.append((time: sT, oldType: stdType, newType: dstType))
                    allTrans.append((time: eT, oldType: dstType, newType: stdType))
                }
            }

            allTrans.sort { $0.time < $1.time }

            for tr in allTrans {
                if tr.newType.utcOffset > tr.oldType.utcOffset {
                    let gapStart = tr.time + tr.oldType.utcOffset
                    let gapEnd = tr.time + tr.newType.utcOffset
                    if wSeconds >= gapStart && wSeconds < gapEnd {
                        gapT = wSeconds - tr.oldType.utcOffset
                        gapType = getTypeAtTime(gapT, tz: tz)
                        gapFound = true
                        break
                    }
                }
            }

            if gapFound {
                let localStr = formatLocalDateTime(t: gapT, offset: gapType.utcOffset)
                print("\(trimmed) -> GAP \(gapT) \(localStr) \(gapType.abbr)")
            } else {
                // Fallback (shouldn't happen with valid input)
                let tp = getTypeAtTime(wSeconds, tz: tz)
                let localStr = formatLocalDateTime(t: wSeconds, offset: tp.utcOffset)
                print("\(trimmed) -> GAP \(wSeconds) \(localStr) \(tp.abbr)")
            }
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <CommonCrypto/CommonDigest.h>

/* ===== Base64 encode ===== */
static const char B64[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static void b64_encode(const uint8_t *data, size_t len, char *out) {
    size_t i = 0, j = 0;
    while (i + 2 < len) {
        uint32_t n = ((uint32_t)data[i] << 16) | ((uint32_t)data[i+1] << 8) | data[i+2];
        out[j++] = B64[(n >> 18) & 63];
        out[j++] = B64[(n >> 12) & 63];
        out[j++] = B64[(n >> 6) & 63];
        out[j++] = B64[n & 63];
        i += 3;
    }
    if (i < len) {
        uint32_t n = (uint32_t)data[i] << 16;
        if (i + 1 < len) n |= (uint32_t)data[i+1] << 8;
        out[j++] = B64[(n >> 18) & 63];
        out[j++] = B64[(n >> 12) & 63];
        out[j++] = (i + 1 < len) ? B64[(n >> 6) & 63] : '=';
        out[j++] = '=';
    }
    out[j] = '\0';
}

/* ===== SHA-1 ===== */
static void sha1_hash(const uint8_t *data, size_t len, uint8_t out[20]) {
    CC_SHA1(data, (CC_LONG)len, out);
}

/* ===== Buffered Reader ===== */
typedef struct {
    int fd;
    uint8_t *buf;
    size_t cap, start, end;
} Reader;

static void reader_init(Reader *r, int fd) {
    r->fd = fd;
    r->cap = 1 << 16;
    r->buf = malloc(r->cap);
    r->start = r->end = 0;
}

static void reader_free(Reader *r) { free(r->buf); }

static int reader_fill(Reader *r, size_t need) {
    while (r->end - r->start < need) {
        if (r->start > 0) {
            memmove(r->buf, r->buf + r->start, r->end - r->start);
            r->end -= r->start;
            r->start = 0;
        }
        if (r->end >= r->cap) {
            r->cap *= 2;
            r->buf = realloc(r->buf, r->cap);
        }
        ssize_t n = read(r->fd, r->buf + r->end, r->cap - r->end);
        if (n <= 0) return -1;
        r->end += (size_t)n;
    }
    return 0;
}

static int reader_read_exact(Reader *r, uint8_t *dst, size_t n) {
    if (n == 0) return 0;
    if (reader_fill(r, n) < 0) return -1;
    memcpy(dst, r->buf + r->start, n);
    r->start += n;
    return 0;
}

static int reader_read_line(Reader *r, uint8_t *dst, size_t max) {
    size_t i = 0;
    for (;;) {
        if (r->start >= r->end) {
            if (r->start > 0) {
                memmove(r->buf, r->buf + r->start, r->end - r->start);
                r->end -= r->start;
                r->start = 0;
            }
            if (r->end >= r->cap) {
                r->cap *= 2;
                r->buf = realloc(r->buf, r->cap);
            }
            ssize_t n = read(r->fd, r->buf + r->end, r->cap - r->end);
            if (n <= 0) return -1;
            r->end += (size_t)n;
        }
        while (r->start < r->end) {
            if (r->buf[r->start] == '\r') {
                if (r->start + 1 < r->end) {
                    if (r->buf[r->start + 1] == '\n') {
                        r->start += 2;
                        dst[i] = '\0';
                        return (int)i;
                    }
                    if (i < max) dst[i++] = r->buf[r->start];
                    r->start++;
                } else {
                    break; /* need more data to confirm \n */
                }
            } else {
                if (i < max) dst[i++] = r->buf[r->start];
                r->start++;
            }
        }
    }
}

/* ===== write all ===== */
static int write_all(int fd, const uint8_t *data, size_t len) {
    size_t off = 0;
    while (off < len) {
        ssize_t n = write(fd, data + off, len - off);
        if (n <= 0) return -1;
        off += (size_t)n;
    }
    return 0;
}

/* ===== Send WebSocket frame (masked, FIN=1) ===== */
static void send_frame(int fd, uint8_t opcode, const uint8_t *payload, size_t len) {
    uint8_t hdr[14];
    size_t hlen = 0;
    hdr[hlen++] = 0x80 | opcode;
    if (len < 126) {
        hdr[hlen++] = 0x80 | (uint8_t)len;
    } else if (len <= 65535) {
        hdr[hlen++] = 0x80 | 126;
        hdr[hlen++] = (uint8_t)(len >> 8);
        hdr[hlen++] = (uint8_t)(len & 0xFF);
    } else {
        hdr[hlen++] = 0x80 | 127;
        uint64_t v = (uint64_t)len;
        for (int i = 7; i >= 0; i--) hdr[hlen++] = (uint8_t)(v >> (i * 8));
    }
    uint8_t mask[4];
    do { arc4random_buf(mask, 4); } while (mask[0]==0&&mask[1]==0&&mask[2]==0&&mask[3]==0);
    memcpy(hdr + hlen, mask, 4);
    hlen += 4;

    uint8_t *frame = malloc(hlen + len);
    memcpy(frame, hdr, hlen);
    for (size_t i = 0; i < len; i++)
        frame[hlen + i] = payload[i] ^ mask[i & 3];
    write_all(fd, frame, hlen + len);
    free(frame);
}

/* ===== UTF-8 reverse by code point ===== */
static void reverse_utf8(const char *text, size_t len, char *out, size_t *out_len) {
    if (len == 0) { *out_len = 0; return; }
    /* count code points */
    size_t count = 0, i = 0;
    while (i < len) {
        uint8_t b = (uint8_t)text[i];
        if (b < 0x80) i += 1;
        else if ((b & 0xE0) == 0xC0) i += 2;
        else if ((b & 0xF0) == 0xE0) i += 3;
        else if ((b & 0xF8) == 0xF0) i += 4;
        else i += 1;
        count++;
    }
    uint32_t *cps = malloc((count + 1) * sizeof(uint32_t));
    size_t n = 0;
    i = 0;
    while (i < len) {
        uint8_t b = (uint8_t)text[i];
        uint32_t cp;
        int extra;
        if (b < 0x80) { cp = b; extra = 0; }
        else if ((b & 0xE0) == 0xC0) { cp = b & 0x1F; extra = 1; }
        else if ((b & 0xF0) == 0xE0) { cp = b & 0x0F; extra = 2; }
        else if ((b & 0xF8) == 0xF0) { cp = b & 0x07; extra = 3; }
        else { cp = b; extra = 0; }
        i++;
        for (int j = 0; j < extra && i < len; j++) {
            cp = (cp << 6) | ((uint8_t)text[i] & 0x3F);
            i++;
        }
        cps[n++] = cp;
    }
    for (size_t j = 0; j < n / 2; j++) {
        uint32_t tmp = cps[j]; cps[j] = cps[n-1-j]; cps[n-1-j] = tmp;
    }
    size_t pos = 0;
    for (size_t j = 0; j < n; j++) {
        uint32_t cp = cps[j];
        if (cp < 0x80) {
            out[pos++] = (char)cp;
        } else if (cp < 0x800) {
            out[pos++] = (char)(0xC0|(cp>>6));
            out[pos++] = (char)(0x80|(cp&0x3F));
        } else if (cp < 0x10000) {
            out[pos++] = (char)(0xE0|(cp>>12));
            out[pos++] = (char)(0x80|((cp>>6)&0x3F));
            out[pos++] = (char)(0x80|(cp&0x3F));
        } else {
            out[pos++] = (char)(0xF0|(cp>>18));
            out[pos++] = (char)(0x80|((cp>>12)&0x3F));
            out[pos++] = (char)(0x80|((cp>>6)&0x3F));
            out[pos++] = (char)(0x80|(cp&0x3F));
        }
    }
    *out_len = pos;
    free(cps);
}

/* ===== Parse ws:// URL ===== */
static void parse_url(const char *url, char *host, int *port, char *path, size_t pathsz) {
    const char *p = url + 5; /* skip "ws://" */
    const char *slash = strchr(p, '/');
    const char *colon = strchr(p, ':');
    if (colon && (!slash || colon < slash)) {
        size_t hl = (size_t)(colon - p);
        memcpy(host, p, hl);
        host[hl] = '\0';
        *port = atoi(colon + 1);
    } else {
        size_t hl = slash ? (size_t)(slash - p) : strlen(p);
        memcpy(host, p, hl);
        host[hl] = '\0';
        *port = 80;
    }
    if (slash) {
        strncpy(path, slash, pathsz - 1);
        path[pathsz - 1] = '\0';
    } else {
        path[0] = '/'; path[1] = '\0';
    }
}

/* ===== Main session handler ===== */
static void handle_session(const char *url, int sess_num) {
    printf("session %d\n", sess_num);
    fflush(stdout);

    char host[256], path[4096];
    int port;
    parse_url(url, host, &port, path, sizeof(path));

    /* TCP connect */
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons((uint16_t)port);
    inet_pton(AF_INET, host, &addr.sin_addr);
    if (connect(fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        close(fd);
        return;
    }

    Reader rdr;
    reader_init(&rdr, fd);

    /* Generate Sec-WebSocket-Key */
    uint8_t key_bytes[16];
    arc4random_buf(key_bytes, 16);
    char ws_key[32];
    b64_encode(key_bytes, 16, ws_key);

    /* Build and send handshake */
    char req[8192];
    int rlen = snprintf(req, sizeof(req),
        "GET %s HTTP/1.1\r\n"
        "Host: %s:%d\r\n"
        "Upgrade: websocket\r\n"
        "Connection: Upgrade\r\n"
        "Sec-WebSocket-Version: 13\r\n"
        "Sec-WebSocket-Key: %s\r\n"
        "\r\n",
        path, host, port, ws_key);
    if (write_all(fd, (uint8_t*)req, (size_t)rlen) < 0) {
        reader_free(&rdr);
        close(fd);
        return;
    }

    /* Read status line */
    uint8_t line[4096];
    int llen = reader_read_line(&rdr, line, sizeof(line) - 1);
    if (llen < 0) {
        printf("handshake failed: 0 \n");
        reader_free(&rdr);
        close(fd);
        return;
    }

    /* Parse status code and reason */
    int status = 0;
    char reason[512] = "";
    {
        const char *sp1 = strchr((const char*)line, ' ');
        if (sp1) {
            status = atoi(sp1 + 1);
            const char *sp2 = strchr(sp1 + 1, ' ');
            if (sp2) {
                strncpy(reason, sp2 + 1, sizeof(reason) - 1);
                reason[sizeof(reason)-1] = '\0';
            }
        }
    }

    /* Read headers */
    char accept_val[256] = "";
    for (;;) {
        llen = reader_read_line(&rdr, line, sizeof(line) - 1);
        if (llen <= 0) break; /* empty line or error */
        if (llen >= 21 && strncasecmp((const char*)line, "Sec-WebSocket-Accept:", 21) == 0) {
            char *v = (char*)line + 21;
            while (*v == ' ' || *v == '\t') v++;
            strncpy(accept_val, v, sizeof(accept_val) - 1);
            accept_val[sizeof(accept_val)-1] = '\0';
        }
    }

    if (status != 101) {
        printf("handshake failed: %d %s\n", status, reason);
        fflush(stdout);
        reader_free(&rdr);
        close(fd);
        return;
    }

    /* Verify Sec-WebSocket-Accept */
    {
        char concat[128];
        int clen = snprintf(concat, sizeof(concat), "%s258EAFA5-E914-47DA-95CA-C5AB0DC85B11", ws_key);
        uint8_t digest[20];
        sha1_hash((const uint8_t*)concat, (size_t)clen, digest);
        char expected[32];
        b64_encode(digest, 20, expected);
        if (strcmp(accept_val, expected) != 0) {
            printf("handshake failed: bad Sec-WebSocket-Accept\n");
            fflush(stdout);
            reader_free(&rdr);
            close(fd);
            return;
        }
    }

    /* ===== Frame loop ===== */
    int sent_close = 0;
    int expect_sha1 = 0;
    int bying = 0;

    /* Message accumulation */
    int msg_opcode = -1;
    uint8_t *msg_buf = NULL;
    size_t msg_len = 0, msg_cap = 0;

    for (;;) {
        /* Read 2-byte frame header */
        uint8_t fh[2];
        if (reader_read_exact(&rdr, fh, 2) < 0) break;

        int fin = (fh[0] >> 7) & 1;
        uint8_t opcode = fh[0] & 0x0F;
        int masked = (fh[1] >> 7) & 1;
        (void)masked; /* server frames are not masked */
        uint64_t payload_len = fh[1] & 0x7F;

        if (payload_len == 126) {
            uint8_t ext[2];
            if (reader_read_exact(&rdr, ext, 2) < 0) break;
            payload_len = ((uint64_t)ext[0] << 8) | ext[1];
        } else if (payload_len == 127) {
            uint8_t ext[8];
            if (reader_read_exact(&rdr, ext, 8) < 0) break;
            payload_len = 0;
            for (int i = 0; i < 8; i++) payload_len = (payload_len << 8) | ext[i];
        }

        /* Read payload */
        uint8_t *payload = NULL;
        if (payload_len > 0) {
            payload = malloc((size_t)payload_len);
            if (reader_read_exact(&rdr, payload, (size_t)payload_len) < 0) {
                free(payload);
                break;
            }
        }

        if (opcode == 8) {
            /* Close frame */
            uint16_t code = 1005;
            char close_reason[4096] = "";
            if (payload_len >= 2) {
                code = ((uint16_t)payload[0] << 8) | payload[1];
                size_t rlen2 = (size_t)payload_len - 2;
                if (rlen2 > 0 && rlen2 < sizeof(close_reason)) {
                    memcpy(close_reason, payload + 2, rlen2);
                    close_reason[rlen2] = '\0';
                }
            }
            if (strlen(close_reason) > 0)
                printf("closed %u %s\n", (unsigned)code, close_reason);
            else
                printf("closed %u\n", (unsigned)code);
            fflush(stdout);

            if (!sent_close) {
                uint8_t cp[2] = { (uint8_t)(code >> 8), (uint8_t)(code & 0xFF) };
                send_frame(fd, 8, cp, 2);
                sent_close = 1;
            }
            free(payload);
            break;
        }

        if (opcode == 9) {
            /* Ping -> reply pong */
            send_frame(fd, 10, payload, (size_t)payload_len);
            free(payload);
            continue;
        }

        if (opcode == 10) {
            /* Pong -> ignore */
            free(payload);
            continue;
        }

        /* Data frame: text(1), binary(2), continuation(0) */
        if (msg_opcode == -1) {
            msg_opcode = opcode;
            msg_len = 0;
        }
        /* Accumulate */
        if (msg_len + payload_len > msg_cap) {
            msg_cap = (msg_len + payload_len) * 2 + 1;
            msg_buf = realloc(msg_buf, msg_cap);
        }
        if (payload_len > 0) {
            memcpy(msg_buf + msg_len, payload, (size_t)payload_len);
            msg_len += (size_t)payload_len;
        }
        free(payload);

        if (!fin) continue; /* more fragments coming */

        /* Complete message */
        int done_type = msg_opcode;
        msg_opcode = -1;

        if (bying) {
            /* We already sent close; just wait for server close */
            continue;
        }

        if (expect_sha1 && done_type == 2) {
            /* SHA1 data message */
            uint8_t digest[20];
            sha1_hash(msg_buf, msg_len, digest);
            char hex[41];
            for (int i = 0; i < 20; i++)
                sprintf(hex + i * 2, "%02x", digest[i]);
            hex[40] = '\0';

            send_frame(fd, 1, (const uint8_t*)hex, 40);
            printf("SHA1 %zu -> %s\n", msg_len, hex);
            fflush(stdout);
            expect_sha1 = 0;
            continue;
        }

        if (done_type == 1) {
            /* Text message: command */
            char *cmd = (char*)malloc(msg_len + 1);
            memcpy(cmd, msg_buf, msg_len);
            cmd[msg_len] = '\0';

            if (strncmp(cmd, "ADD ", 4) == 0) {
                long long a, b;
                sscanf(cmd + 4, "%lld %lld", &a, &b);
                long long sum = a + b;
                char reply[64];
                snprintf(reply, sizeof(reply), "%lld", sum);
                send_frame(fd, 1, (const uint8_t*)reply, strlen(reply));
                printf("%s -> %s\n", cmd, reply);
                fflush(stdout);
            } else if (strncmp(cmd, "REV ", 4) == 0) {
                const char *text = cmd + 4;
                size_t textlen = msg_len - 4;
                char *rev = malloc(textlen + 1);
                size_t revlen;
                reverse_utf8(text, textlen, rev, &revlen);
                rev[revlen] = '\0';
                send_frame(fd, 1, (const uint8_t*)rev, revlen);
                printf("%s -> %s\n", cmd, rev);
                fflush(stdout);
                free(rev);
            } else if (strcmp(cmd, "SHA1") == 0) {
                expect_sha1 = 1;
            } else if (strcmp(cmd, "BYE") == 0) {
                uint8_t cp[2] = { 0x03, 0xE8 };
                send_frame(fd, 8, cp, 2);
                sent_close = 1;
                bying = 1;
            }
            free(cmd);
        }
        /* binary messages when not expecting SHA1: ignore */
    }

    free(msg_buf);
    reader_free(&rdr);
    close(fd);
}

/* ===== Main ===== */
int main(int argc, char **argv) {
    for (int i = 1; i < argc; i++) {
        handle_session(argv[i], i);
    }
    return 0;
}
